INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32393','清凉寺','溫庭筠','quantangshi','','卷33','黄花红树谢芳蹊，宫殿参差黛巘西。
诗合晓窗藏雪岭，画堂秋水接蓝溪。
松飘晚吹摐金铎，竹荫寒苔上石梯。
妙迹奇名竟何在，下方烟暝草萋萋。','',''),('quantangshi-32394','赠卢长史','溫庭筠','quantangshi','','卷33','移病欲成隐，扁舟归旧居。
地深新事少，官散故交疎。
道直更无侣，家贫唯有书。
东门烟水梦，非独为鲈鱼。','',''),('quantangshi-32395','秋日旅舍寄义山李侍御','溫庭筠','quantangshi','','卷33','一水悠悠隔渭城，渭城风物近柴荆。
寒蛩乍响催机杼，旅雁初来忆弟兄。
自为林泉牵晓梦，不关砧杵报秋声。
子虚何处堪消渴，试向文园问长卿。','',''),('quantangshi-32396','晚坐寄友人','溫庭筠','quantangshi','','卷33','九枝灯在琐窗空，希逸无聊恨不同。
晓梦未离金夹膝，早寒先到石屏风。
遗簪可惜三秋白，蜡烛犹残一寸红。
应卷鰕帘看皓齿，镜中惆怅见梧桐。','',''),('quantangshi-32397','送渤海王子归本国','溫庭筠','quantangshi','','卷33','疆理虽重海，车书本一家。
盛勋归旧国，佳句在中华。
定界分秋涨，开帆到曙霞。
九门风月好，回首是天涯。','',''),('quantangshi-32398','送北阳袁明府','溫庭筠','quantangshi','','卷33','楚乡千里路，君去及良晨。
苇浦迎船火，茶山候吏尘。
桑浓蚕卧晚，麦秀雉声春。
莫作东篱兴，青云有故人。','',''),('quantangshi-32399','送李生归旧居','溫庭筠','quantangshi','','卷33','一从征战后，故社几人归。
薄宦离山久，高谈与世稀。
夕阳当板槛，春日入柴扉。
莫却严滩意，西溪有钓矶。','',''),('quantangshi-32400','早春浐水送友人','溫庭筠','quantangshi','','卷33','青门烟野外，渡浐送行人。
鸭卧溪沙暖，鸠鸣社树春。
残波青有石，幽草绿无尘。
杨柳东风里，相看泪满巾。','',''),('quantangshi-32401','送襄州李中丞赴从事','溫庭筠','quantangshi','','卷33','汉庭文采有相如，天子通宵爱子虚。
把钓看棊高兴尽，焚香起草宦情疎。
楚山重叠当归路，溪月分明到直庐。
江雨潇潇帆一片，此行谁道为鲈鱼。','',''),('quantangshi-32402','江上别友人','溫庭筠','quantangshi','','卷33','秋色满葭菼，离人西复东。
几年方暂见，一笑又难同。
地势萧陵歇，江声禹庙空。
如何暮滩上，千里逐征鸿。','',''),('quantangshi-32403','与友人别','溫庭筠','quantangshi','','卷33','半醉别都门，含凄上古原。
晚风杨叶社，寒食杏花村。
薄暮牵离绪，伤春忆晤言。
年芳本无限，何况有兰孙。','',''),('quantangshi-32404','鸿胪寺有开元中锡宴堂楼台池沼雅为胜绝荒凉遗址仅有存者偶成四十韵','溫庭筠','quantangshi','','卷33','明皇昔御极，神圣垂耿光。
沈机发雷电，逸躅陵尧汤。
西覃积石山，北至穷发乡。
四凶有獬豸，一臂无螳螂。
婵娟得神艳，郁烈闻国香。
紫縧鸣羯鼓，玉管吹霓裳。
禄山未封侯，林甫才为郎。
昭融廓日月，妥帖安纪纲。
羣生到寿域，百辟趋明堂。
四海正夷宴，一尘不飞扬。
天子自犹豫，侍臣宜乐康。
轧然阊阖开，赤日生扶桑。
玉砌露盘纡，金壶漏丁当。
劒佩相击触，左右随趋跄。
玄珠十二旒，红粉三千行。
顾盻生羽翼，叱嗟廻雪霜。
神霞凌云阁，春水骊山阳。
盘鬬九子糭，瓯擎五云浆。
双琼京兆博，七鼓邯郸娼。
毰毸碧鸡鬬，茏葱翠雉场。
杖官绣蔽膝，宝马金镂锡。
椒涂隔鹦鹉，柘弹惊鸳鸯。
猗欤华国臣，鬓髪俱苍苍。
锡宴得幽致，车从真炜煌。
画鷁照鱼鼈，鸣驺乱鹙鸧。
颭滟荡碧波，炫煌迷横塘。
萦盈舞廻雪，宛转歌遶梁。
艳带画银络，宝梳金钿筐。
沈冥类汉相，醉倒疑楚狂。
一旦紫微东，胡星森耀芒。
凭陵逐鲸鲵，唐突驱犬羊。
纵火三月赤，战尘千里黄。
肴函与府寺，从此俱荒凉。
兹地乃蔓草，故基摧坏墙。
枯池接断岸，唧唧啼寒螿。
败荷塌作泥，死竹森如枪。
游人问老吏，相对聊感伤。
岂必见麋鹿，然后堪回肠。
幸今遇太平，令节称羽觞。
谁知曲江曲，岁岁栖鸾凰。','',''),('quantangshi-32405','访知玄上人遇暴经因有赠','溫庭筠','quantangshi','','卷33','缥帙无尘满画廊，钟山弟子静焚香。
惠能未肯传心法，张湛徒劳与眼方。
风扬檀烟销篆印，日移松影过禅牀。
客儿自有翻经处，江上秋来蕙草荒。','',''),('quantangshi-32406','寄崔先生','溫庭筠','quantangshi','','卷33','往年江海别元卿，家近山阳古郡城。
莲浦香中离席散，柳堤风里钓船横。
星霜荏苒无音信，烟水微茫变姓名。
菰黍正肥鱼正美，五侯门下负平生。','',''),('quantangshi-32407','敬答李先生','溫庭筠','quantangshi','','卷33','七里滩声舜庙前，杏花初盛草芊芊。
绿昏晴气春风岸，红漾轻纶野水天。
不为伤离成极望，更因行乐惜流年。
一瓢无事麛裘暖，手弄溪波坐钓船。','',''),('quantangshi-32408','宿沣曲僧舍','溫庭筠','quantangshi','','卷33','东郊和气新，芳霭远如尘。
客舍停疲马，僧墙画故人。
沃田桑景晚，平野菜花春。
更想严家濑，微风荡白苹。','',''),('quantangshi-32409','宿一公精舍','溫庭筠','quantangshi','','卷33','夜阑黄叶寺，瓶锡两俱能。
松下石桥路，雨中山殿灯。
茶炉天姥客，棊席剡溪僧。
还笑长门赋，高秋卧茂陵。','',''),('quantangshi-32410','月中宿云居寺上方','溫庭筠','quantangshi','','卷33','虚合披衣坐，寒堦踏叶行。
众星中夜少，圆月上方明。
霭尽无林色，喧余有涧声。
祗应愁恨事，还逐晓光生。','',''),('quantangshi-32411','登卢氏台','溫庭筠','quantangshi','','卷33','胜地当通邑，前山有故居。
台高秋尽出，林断野无余。
白露鸣蛩急，晴天度雁疎。
由来放怀地，非独在吾庐。','',''),('quantangshi-32412','牡丹二首 一','溫庭筠','quantangshi','','卷33','轻阴隔翠帏，宿雨泣晴晖。
醉后佳期在，歌余旧意非。
蝶繁经粉住，蜂重抱香归。
莫惜薰炉夜，因风到舞衣。','',''),('quantangshi-32413','牡丹二首 二','溫庭筠','quantangshi','','卷33','水漾晴红压叠波，晓来金粉覆庭莎。
裁成艳思偏应巧，分得春光最数多。
欲绽似含双靥笑，正繁疑有一声歌。
华堂客散帘垂地，想凭阑干歛翠蛾。','',''),('quantangshi-32414','反生桃花发因题','溫庭筠','quantangshi','','卷33','疾眼逢春四壁空，夜来山雪破东风。
未知王母千年熟，且共刘郎一笑同。
已落又开横晚翠，似无如有带朝红。
僧虔蜡炬高三尺，莫惜连宵照露丛。','',''),('quantangshi-32415','杏花','溫庭筠','quantangshi','','卷33','红花初绽雪花繁，重叠高低满小园。
正见盛时犹怅望，岂堪开处已缤翻。
情为世累诗千首，醉是吾乡酒一樽。
杳杳艳歌春日午，出墙何处隔朱门。','',''),('quantangshi-32416','和太常杜少卿东都修[行]里有嘉莲','溫庭筠','quantangshi','','卷33','春秋罢注直铜龙，旧宅嘉莲照水红。
两处龟巢清露里，一时鱼跃翠茎东。
同心表瑞荀池上，半面分妆乐镜中。
应为临川多丽句，故持重艳向西风。','',''),('quantangshi-32417','题磁岭海棠花','溫庭筠','quantangshi','','卷33','幽态竟谁赏，岁华空与期。
岛回香尽处，泉照艳浓时。
蜀彩淡摇曳，吴妆低怨思。
王孙又谁恨，惆怅下山迟。','',''),('quantangshi-32418','苦楝花','溫庭筠','quantangshi','','卷33','院里莺歌歇，墙头蝶舞孤。
天香薰羽葆，宫紫晕流苏。
暗暧迷青琐，氤氲向画图。
只应春惜别，留与博山炉。','',''),('quantangshi-32419','自有扈至京师已后朱樱之期','溫庭筠','quantangshi','','卷33','露圆霞赤数千枝，银笼谁家寄所思。
秦苑飞禽谙熟早，杜陵游客恨来迟。
空看翠幄成阴日，不见红珠满树时。
尽日徘徊浓影下，祗应重作钓鱼期。','',''),('quantangshi-32420','答段柯古见嘲','溫庭筠','quantangshi','','卷33','彩翰殊翁金缭绕，一千二百逃飞鸟。
尾薪桥下未为痴，暮雨朝云世间少。','',''),('quantangshi-32421','莲花','溫庭筠','quantangshi','','卷33','绿塘摇滟接星津，轧轧兰桡入白苹。
应为洛神波上韈，至今莲蘂有香尘。','',''),('quantangshi-32422','过吴景帝陵','溫庭筠','quantangshi','','卷33','王气销来水淼茫，岂能才与命相妨。
虚开直渎三千里，青盖何曾到洛阳。','',''),('quantangshi-32423','龙尾驿妇人图','溫庭筠','quantangshi','','卷33','慢笑开元有幸臣，直敎天子到蒙尘。
今来看画犹如此，何况亲逢绝世人。','',''),('quantangshi-32424','薛氏池垂钓','溫庭筠','quantangshi','','卷33','池塘经雨更苍苍，万点荷珠晓气凉。
朱瑀空偷御沟水，锦鳞红尾属严光。','',''),('quantangshi-32425','简同志','溫庭筠','quantangshi','','卷33','开济由来变盛衰，五车才得号镃基。
留侯功业何容易，一卷兵书作帝师。','',''),('quantangshi-32426','瑟瑟钗','溫庭筠','quantangshi','','卷33','翠染冰轻透露光，堕云孙寿有余香。
只因七夕回天浪，添作湘妃泪两行。','',''),('quantangshi-32427','元日','溫庭筠','quantangshi','','卷33','神耀破氛昏，新阳入晏温。
绪风调玉吹，端日应铜浑。
威凤跄瑶簴，升龙护璧门。
雨阳春令煦，裘冕晬容尊。','',''),('quantangshi-32428','二月十五日樱桃盛开自所居蹑履吟翫竞名王泽章洋才','溫庭筠','quantangshi','','卷33','晓觉笼烟重，春深染雪轻。
静应留得蝶，繁欲不胜莺。
影乱晨飙急，香多夜雨晴。
似将千万恨，西北为卿卿。','',''),('quantangshi-32429','寒食节日寄楚望二首 一','溫庭筠','quantangshi','','卷33','芳兰无意绿，弱柳何穷缕。
心断入淮山，梦长穿楚雨。
繁花如二八，好月当三五。
愁碧竟平臯，韶红换幽圃。
流莺隐员树，乳燕喧余哺。
旷望恋曾台，离忧集环堵。
当年不自遣，晚得终何补。
郑谷有樵苏，归来要腰斧。','',''),('quantangshi-32430','寒食节日寄楚望二首 二','溫庭筠','quantangshi','','卷33','家乏两千万，时当一百五。
飔飔杨柳风，穰穰樱桃雨。
年芳苦沈潦，心事如摧橹。
金犊近兰汀，铜龙接花坞。
青葱建杨宅，隐辚端门鼓。
彩素拂庭柯，轻球落邻圃。
三春谢游衍，一笑牵规矩。
独有恩泽侯，归来看楚舞。','',''),('quantangshi-32431','清明日','溫庭筠','quantangshi','','卷33','清娥画扇中，春树郁金红。
出犯繁花露，归穿弱柳风。
马骄偏避幰，鸡骇乍开笼。
柘弹何人发，黄鹂隔故宫。','',''),('quantangshi-32432','禁火日','溫庭筠','quantangshi','','卷33','骀荡清明日，储胥小苑东。
舞衫萱草绿，春鬓杏花红。
马辔轻衔雪，车衣弱向风。
□愁闻百舌，残睡正朦胧。','',''),('quantangshi-32433','嘲三月十八日雪','溫庭筠','quantangshi','','卷33','三月雪连夜，未应伤物华。
只缘春欲尽，留着伴梨花。','',''),('quantangshi-32434','杨柳八首 一','溫庭筠','quantangshi','','卷33','宜春苑外最长条。
闲褭春风伴舞腰，正是玉人肠断处。
一渠春水赤阑桥。','',''),('quantangshi-32435','杨柳八首 二','溫庭筠','quantangshi','','卷33','南内墙东御路旁，预知春色柳丝黄。
杏花未肯无情思，何是情人最断肠。','',''),('quantangshi-32436','杨柳八首 三','溫庭筠','quantangshi','','卷33','苏小门前柳万条，毶毶金线拂平桥。
黄莺不语东风起，深闭朱门伴细腰。','',''),('quantangshi-32437','杨柳八首 四','溫庭筠','quantangshi','','卷33','金缕毶毶碧瓦沟，六宫眉黛惹春愁。
晚来更带龙池雨，半拂阑干半入楼。','',''),('quantangshi-32438','杨柳八首 五','溫庭筠','quantangshi','','卷33','馆娃宫外邺城西，远映征帆近拂堤。
系得王孙归意切，不关春草绿萋萋。','',''),('quantangshi-32439','杨柳八首 六','溫庭筠','quantangshi','','卷33','两两黄鹂色似金，褭枝啼露动芳音。
春来幸自长如线，可惜牵缠荡子心。','',''),('quantangshi-32440','杨柳八首 七','溫庭筠','quantangshi','','卷33','御柳如丝映九重，凤皇窗柱绣芙蓉。
景阳楼畔千条露，一面新妆待晓钟。','',''),('quantangshi-32441','杨柳八首 八','溫庭筠','quantangshi','','卷33','织锦机边莺语频，停梭垂泪忆征人。
塞门三月犹萧索，纵有垂杨未觉春。','',''),('quantangshi-32442','客愁','溫庭筠','quantangshi','','卷33','客愁看柳色，日日逐春深。
荡漾春风里，谁知历乱心。','',''),('quantangshi-32443','和周繇','溫庭筠','quantangshi','','卷33','齐马驰千驷，卢姬逞十三。
玳筵方喜睐，金勒自䟃𧽼。
堕珥情初洽，鸣鞭战未酣。
神交花冉冉，眉语柳毶毶。
却略青鸾镜，翘翻翠凤篸。
专城有佳对，宁肯顾春蚕。','',''),('quantangshi-32444','光风亭夜宴妓有醉殴者','溫庭筠','quantangshi','','卷33','吴国初成阵，王家欲解围。
拂巾双雉呌，飘瓦两鸳飞。','',''),('quantangshi-32445','南歌子词二首 一','溫庭筠','quantangshi','','卷33','一尺深红胜麴尘，天生旧物不如新。
合欢桃核终堪恨，里许元来别有人。','',''),('quantangshi-32446','南歌子词二首 二','溫庭筠','quantangshi','','卷33','井底点灯深烛伊，共郎长行莫围棊。
玲珑骰子安红豆，入骨相思知不知。','',''),('quantangshi-32447','题李卫公诗二首 一','溫庭筠','quantangshi','','卷33','蒿棘深春卫国门，九年于此盗干坤。
两行密疏倾天下，一夜阴谋达至尊。
肉视具僚忘匕箸，气吞同列削寒温。
当时谁是承恩者，肯有余波达鬼邨。','',''),('quantangshi-32448','题李卫公诗二首 二','溫庭筠','quantangshi','','卷33','势欲凌云威触天，权倾诸夏力排山。
三年骥尾有人附，一日龙须无路攀。
画合不开梁燕去，朱门罢埽乳鸦还。
千岩万壑应惆怅，流水斜倾出武关。','',''),('quantangshi-32449','题谷隐兰若','溫庭筠','quantangshi','','卷33','风带巢熊拗树声，老僧相引入云行。
