穷愁读书者，应得假余光。','',''),('quantangshi-32455','和徐商贺卢员外赐绯','段成式','quantangshi','','卷33','云雨轩悬莺语新，一篇佳句占阳春。
银黄年少偏欺酒，金紫风流不让人。
连璧座中斜日满，贯珠歌里落花频。
莫辞倒载吟归去，看欲东山又吐茵。','',''),('quantangshi-32456','河出荣光','段成式','quantangshi','','卷33','符命自陶唐，吾君应会昌。
千年清德水，九折满荣花。
极岸浮佳气，微波照夕阳。
澄辉明贝阙，散彩入龙堂。
近带关云紫，遥连日道黄。
冯夷矜海若，汉武贵宣房。
