乱翠移林色，狂红照座殷。
防梭齿虽在，乞帽鬓慙斑。
傥恕相如瘦，应容累骑还。','',''),('quantangshi-32507','和张希复咏宣律和尚袈裟','段成式','quantangshi','','卷33','南山披时寒夜中，一角不动毗岚风。
何人见此生慙愧，断续犹应护得龙。','',''),('quantangshi-32508','句','段成式','quantangshi','','卷33','高谈敬风鉴，古貌怯冰棱。
虱暴妨归梦，虫喧彻曙更。
梦里思甘露，言中惜惠灯。
新破毗昙义，相期卜夜论。
随樵劫猨藏，隈石觑熊缘。
[捽]胡云彩落，疻面月痕消。
掷履仙凫起，扯衣蝴蝶飘。
羞中含薄怒，颦里带余娇。
醒后犹攘臂，归时更折腰。
狂夫自缨绝，眉势倩人描。
不愿石郎戴笠，难甘玉女披衣。','',''),('quantangshi-32509','皎皎词','劉駕','quantangshi','','卷33','皎皎复皎皎，逢时即为好。
高秋亦有花，不及当春草。
班姬入后宫，飞燕舞东风。
青娥中夜起，长叹月明里。','',''),('quantangshi-32510','长安旅舍纾情投先达','劉駕','quantangshi','','卷33','岐路不在地，马蹄徒苦辛。
上国闻姓名，不如山中人。
大宅满六街，此身入谁门。
愁心日散乱，有似空中尘。
白露下长安，百虫鸣草根。
方当秋赋日，却忆归山村。
静女头欲白，良媒况我邻。
无令苦长叹，长叹销人魂。','',''),('quantangshi-32511','送友下第游雁门','劉駕','quantangshi','','卷33','相别灞水湄，夹水柳依依。
我愿醉如死，不见君去时。
所诣星斗北，直行到犹迟。
况复挈空囊，求人悲路岐。
北门记室贤，爱我学古诗。
待君如待我，此事固不疑。
雁门春色外，四月雁未归。
主人拂金台，延客夜开扉。
舒君郁郁怀，饮彼白玉巵。
若不化女子，功名岂无期。','',''),('quantangshi-32512','读史','劉駕','quantangshi','','卷33','平地见天涯，登高天更远。
功名及所望，岐路又满眼。
万金买园林，千金修池馆。
他人厌游览，身独恋轩冕。
唯有汉二疎，应觉还家晚。','',''),('quantangshi-32513','反贾客乐','劉駕','quantangshi','','卷33','无言贾客乐，贾客多无墓。
行舟触风浪，尽入鱼腹去。
农夫更苦辛，所以羡尔身。','',''),('quantangshi-32514','送李垣先辈归嵩少旧居','劉駕','quantangshi','','卷33','高秋灞浐路，游子多惨戚。
君于此地行，独以寻春色。
文章满人口，高第非苟得。
要路在长安，归山却为客。
□□□□□，狂歌罢叹息。
我岂无故山，千里同外国。','',''),('quantangshi-32515','苦寒吟','劉駕','quantangshi','','卷33','百泉冻皆咽，我吟寒更切。
半夜倚乔松，不觉满衣雪。
竹竿有甘苦，我爱抱苦节。
鸟声有悲欢，我爱口流血。
潘生若解吟，更早生白发。','',''),('quantangshi-32516','上巳日','劉駕','quantangshi','','卷33','上巳曲江滨，喧于市朝路。
相寻不见者，此地皆相遇。
日光去此远，翠幕张如雾。
何事欢娱中，易觉春城暮。
物情重此节，不是爱芳树。
明日花更多，何人肯回顾。','',''),('quantangshi-32517','春台','劉駕','quantangshi','','卷33','台上树阴合，台前流水多。
青春不出门，坐见野田花。
谁能学公子，走马逐香车。
六街尘满衣，鼓绝方还家。','',''),('quantangshi-32518','钓台怀古','劉駕','quantangshi','','卷33','澄流可濯缨，严子但垂纶。
孤坐九层石，远笑清渭滨。
潜龙飞上天，四海岂无云。
清气不零雨，安使洗尘氛。
我来吟高风，仿髴见斯人。
江月尚皎皎，江石亦磷磷。
如何台下路，明日又迷津。','',''),('quantangshi-32519','励志','劉駕','quantangshi','','卷33','白发岂有情，贵贱同日生。
二轮不暂驻，似趂长安程。
前堂吹参差，不作缑山声。
后园植木槿，月照无余英。
及时立功德，身后犹光明。
仲尼亦为土，鲁人焉敢耕。','',''),('quantangshi-32520','桑妇','劉駕','quantangshi','','卷33','墙下桑叶尽，春蚕半未老。
城南路迢迢，今日起更早。
四邻无去伴，醉卧青楼晓。
妾颜不如谁，所贵守妇道。
一春常在树，自觉身如鸟。
归来见小姑，新妆弄百草。','',''),('quantangshi-32521','上马叹','劉駕','quantangshi','','卷33','羸马行迟迟，顽童去我远。
时时一回顾，不觉白日晚。
路傍豪家宅，楼上红妆满。
十月庭花开，花前吹玉管。
君当未贵日，岂不常屯蹇。
如何见布衣，忽若尘入眼。
布衣岂常贱，世事车轮转。','',''),('quantangshi-32522','唐乐府十首 送征夫','劉駕','quantangshi','','卷33','昔送征夫苦，今送征夫乐。
寒衣纵携去，应向归时着。
天子待功成，别造凌烟阁。','',''),('quantangshi-32523','唐乐府十首 轮者讴','劉駕','quantangshi','','卷33','挽粟上高山，高山若平地。
力尽心不怨，同我家私事。
去者不遑宁，归者唱歌行。
相逢古城下，立语天未明。
一身远出塞，十口无税征。','',''),('quantangshi-32524','唐乐府十首 吊西人','劉駕','quantangshi','','卷33','河湟父老地，尽知归明主。
将军入空城，城下吊黄土。
所愿边人耕，岁岁生禾黍。','',''),('quantangshi-32525','唐乐府十首 边军过','劉駕','quantangshi','','卷33','城前兵马过，城里人高卧。
官家自供给，畏我田产破。
健儿食肥肉，战马食新谷。
食饱物有余，所恨无两腹。
草青见军过，草白见军回。
军回人更多，尽系西戎来。','',''),('quantangshi-32526','唐乐府十首 望归马','劉駕','quantangshi','','卷33','东人望归马，马归莲峰下。
莲峰与地平，亦不更征兵。','',''),('quantangshi-32527','唐乐府十首 祝河水','劉駕','quantangshi','','卷33','河水清弥弥，照见远树枝。
征人不饮马，再拜祝冯夷。
从今亿万岁，不见河浊时。','',''),('quantangshi-32528','唐乐府十首 田西边','劉駕','quantangshi','','卷33','刀劒作锄犂，耕田古城下。
高秋禾黍多，无地放羊马。','',''),('quantangshi-32529','唐乐府十首 昆山','劉駕','quantangshi','','卷33','昔时玉为宝，昆山过不得。
今时玉为尘，昆山入中国。
白玉尚如尘，谁肯爱金银。','',''),('quantangshi-32530','唐乐府十首 乐边人','劉駕','quantangshi','','卷33','在乡身亦劳，在边腹亦饱。
父兄若一处，任向边头老。','',''),('quantangshi-32531','唐乐府十首 献贺觞','劉駕','quantangshi','','卷33','莫但取河湟，河湟非边疆。
愿今日入处，亦似天中央。
天子寿万岁，再拜献此觞。','',''),('quantangshi-32532','且可怜行','劉駕','quantangshi','','卷33','园中花自早，不信外无花。
良人未朝去，先出登香车。
□□五□轮，满城闻呕哑。
侍儿衣各别，头上金雀多。
祗是一家人，路人疑千家。
过后香满陌，直到春日斜。
今朝且可怜，莫问久如何。','',''),('quantangshi-32533','筑台词','劉駕','quantangshi','','卷33','前杵与后杵，筑城声不住。
我愿筑更高，得见秦皇墓。','',''),('quantangshi-32534','邻女','劉駕','quantangshi','','卷33','君嫌邻女丑，取妇他乡县。
料嫁与君人，亦为邻所贱。
菖蒲花可贵，只为人难见。','',''),('quantangshi-32535','山中夜坐','劉駕','quantangshi','','卷33','半夜山雨过，起来满山月。
落尽醉处花，荒沟水决决。
怆然惜春去，似与故人别。
谁遣我多情，壮年无鬓发。','',''),('quantangshi-32536','秦娥','劉駕','quantangshi','','卷33','秦娥十四五，面白于指爪。
羞人夜采桑，惊起戴胜鸟。','',''),('quantangshi-32537','牧童','劉駕','quantangshi','','卷33','牧童见客拜，山果怀中落。
昼日驱牛归，前溪风雨恶。','',''),('quantangshi-32538','古出塞','劉駕','quantangshi','','卷33','胡风不开花，四气多作雪。
北人尚冻死，况我本南越。
古来犬羊地，巡狩无遗辙。
九土耕不尽，武皇犹征伐。
中天有高阁，图画何时歇？
坐恐塞上山，低于沙中骨。','',''),('quantangshi-32539','寄远','劉駕','quantangshi','','卷33','雪花岂结子，徒满连理枝。
嫁作征人妻，不得长相随。
去年君点行，贱妾是新姬。
别早见未熟，入梦无定姿。
悄悄空闺中，蛩声遶罗帏。
得书喜犹甚，况复见君时。','',''),('quantangshi-32540','下第后屏居长安书怀寄太原从事','劉駕','quantangshi','','卷33','刖足岂更长，良工隔千里。
故山彭蠡上，归梦向汾水。
低摧神气尽，僮仆心亦耻。
未达谁不然，达者心思此。
行年忽已壮，去老年更几。
功名生不彰，身殁岂为鬼。
才看芳草歇，即叹凉风起。
匹马未来期，嘶声尚在耳。','',''),('quantangshi-32541','早行','劉駕','quantangshi','','卷33','马上续残梦，马嘶时复惊。
心孤多所虞，僮仆近我行。
栖禽未分散，落月照古城。
莫羡居者闲，冢边人已耕。','',''),('quantangshi-32542','青门路','劉駕','quantangshi','','卷33','青门有归路，坦坦高槐下。
贫贱自耻归，此地谁留我。
门开送客去，落日嬾回马。
旅食帝城中，不如远游者。
舟成于陆地，风水终相假。
吾道谅如斯，立身无苟且。','',''),('quantangshi-32543','效古','劉駕','quantangshi','','卷33','融融芳景和，杳杳春日斜。
娇娆不自持，清唱嚬双蛾。
终曲翻成泣，新人下香车。
新人且莫喜，故人曾如此。
燕赵犹生女，郎岂有终始。','',''),('quantangshi-32544','战城南','劉駕','quantangshi','','卷33','城南征战多，城北无饥鸦。
白骨马蹄下，谁言皆有家。
城前水声苦，倏忽流万古。
莫争城外城，城里终闲土。','',''),('quantangshi-32545','曲江春霁','劉駕','quantangshi','','卷33','宿雨洗秦树，旧花如新开。
池边草未干，日照人马来。
马蹄踏流水，渐渐成尘埃。
鸳鸯不敢下，飞绕岸东西。
此地喧仍旧，归人亦满街。','',''),('quantangshi-32546','赠先达','劉駕','quantangshi','','卷33','终南苍翠好，未必如故山。
心期在荣名，三载居长安。
昔蒙大雅匠，勉我工五言。
业成时不重，辛苦只自怜。
皎皎机上丝，尽作秦筝弦。
贫女皆罢织，富人岂不寒。
惊风起长波，浩浩何时还？
待君当要路，一指王化源。','',''),('quantangshi-32547','有感','劉駕','quantangshi','','卷33','弓劒不自行，难引河湟思。
将军半夜饮，十里闻歌饮。
高门几世宅，舞袖仍新赐。
谁遣一书来，灯前问边事。','',''),('quantangshi-32548','姑苏台','劉駕','quantangshi','','卷33','勾践饮胆日，吴酒正满杯。
笙歌入海云，声自姑苏来。
西施舞初罢，侍儿整金钗。
众女不敢妒，自比泉下泥。
越鼓声腾腾，吴天隔尘埃。
难将甬东地，更学会稽栖。
霸迹一朝尽，草中棠梨开。','',''),('quantangshi-32549','豪家','劉駕','quantangshi','','卷33','九陌槐叶尽，青春在豪家。
娇莺不出城，长宿庭上花。
高楼登夜半，已见南山多。
恩深势自然，不是爱骄奢。','',''),('quantangshi-32550','山中有招','劉駕','quantangshi','','卷33','朗朗山月出，尘中事由生。
人心虽不闲，九陌夜无行。
学古以求闻，有如石上耕。
齐姜早作妇，岂识闺中情。
何如此幽居，地僻人不争。
嘉树自昔有，茅屋因我成。
取薪不出门，采药于前庭。
春花虽无种，枕席芙蓉馨。
君来食葵藿，天爵岂不荣。','',''),('quantangshi-32551','空城雀','劉駕','quantangshi','','卷33','饥啄空城上，莫近太仓粟。
一粒未充肠，却入公子腹。
且吊城上骨，几曾害尔族。
不闻庄辛语，今日寒芜绿。','',''),('quantangshi-32552','冯叟居','劉駕','quantangshi','','卷33','天作冯叟居，山僧尚嫌僻。
开门因两树，结宇倚翠壁。
溪南有微径，时遇采芝客。
往往白云生，对面千里隔。
机忘若僮仆，常与猨鸟剧。
晒药上小峰，庭深无日色。
自忘归乡里，不见新旧戚。
累累子孙墓，秋风吹古柏。','',''),('quantangshi-32553','醒后','劉駕','quantangshi','','卷33','醉卧芳草间，酒醒日落后。
壶觞半倾覆，客去应已久。
不记折花时，何得花在手。','',''),('quantangshi-32554','弃妇','劉駕','quantangshi','','卷33','回车在门前，欲上心更悲。
路傍见花发，似妾初嫁时。
养蚕已成茧，织素犹在机。
新人应笑此，何如画蛾眉。
昨日惜红颜，今日畏老迟。
良媒去不远，此恨今告谁。','',''),('quantangshi-32555','送李殷游边','劉駕','quantangshi','','卷33','十年梦相识，一觏俄远别。
征驾在我傍，草草意难说。
君居洞庭日，诗句满魏阙。
如何万里来，青桂看人折。
行装不及备，西去偶然诀。
孟夏出都门，红尘客衣热。
荒城见羊马，野馆具薇蕨。
边境渐无虞，旅宿常待月。
西园置酒地，日夕簪裾列。
壮志安可留，槐花樽前发。','',''),('quantangshi-32556','江村','劉駕','quantangshi','','卷33','江水灌稻田，饥年稻亦熟。
舟中爱桑麻，日午因成宿。
相承几十代，居止连茅屋。
四邻不相离，安肯去骨肉。
书生说太苦，客路常在目。
纵使富贵还，交亲几坟绿。','',''),('quantangshi-32557','出门','劉駕','quantangshi','','卷33','出门羡他人，奔走如得涂。
翻思他人意，与我或不殊。
以兹聊自安，默默行九衢。
生计逐羸马，每出似移居。
客从我乡来，但得邻里书。
田园几换主，梦归犹荷锄。
进犹希万一，退复何所如。
况今辟公道，安得不踌躇。','',''),('quantangshi-32558','别道者','劉駕','quantangshi','','卷33','自君入城市，北邙无新坟。
始信壶中药，不落白杨根。
如何忽告归，蕣华还笑人。
玉笙无遗音，怅望缑岭云。','',''),('quantangshi-32559','兰昌宫','劉駕','quantangshi','','卷33','宫兰非瑶草，安得春长在。
回首春又归，翠华不能待。
悲风生辇路，山川寂已晦。
边恨在行人，行人无尽岁。','',''),('quantangshi-32560','送友人擢第东归','劉駕','quantangshi','','卷33','同家楚天南，相识秦云西。
古来悬弧义，岂顾子与妻。
携手践名场，正遇公道开。
君荣我虽黜，感恩同所怀。
有马不复羸，有奴不复饥。
灞岸秋草绿，却是还家时。
青门一瓢空，分手去迟迟。
期君辙未平，我车继东归。','',''),('quantangshi-32561','久客','劉駕','quantangshi','','卷33','久客心易足，主人有余力。
如何昨宵梦，到晓家山色。
南音入谁耳，曲尽头自白。','',''),('quantangshi-32562','秋夕','劉駕','quantangshi','','卷33','促织灯下吟，灯光冷于水。
乡魂坐中去，倚壁身如死。
求名为骨肉，骨肉万余里。
富贵在何时，离别今如此。
出门长叹息，月白西风起。','',''),('quantangshi-32563','效陶','劉駕','quantangshi','','卷33','两曜无停驭，蓬壶应有墓。
何况北邙山，只近市朝路。
大恢生死网，飞走无逃处。
白发忽已新，红颜岂如故。
我有杯中物，可以消万虑。
醉舞日婆娑，谁能记朝暮。
如求神仙药，阶下亦种黍。
但使长兀然，始见天地祖。','',''),('quantangshi-32564','长门怨','劉駕','quantangshi','','卷33','御泉长绕凤皇[楼]，只是恩波别处流。
闲揲舞衣归未得，夜来砧杵六宫秋。','',''),('quantangshi-32565','苦寒行','劉駕','quantangshi','','卷33','严寒动八荒，刺刺无休时。
阳乌不自暖，雪压扶桑枝。
岁暮寒益壮，青春安得归。
朔雁到南海，越禽何处飞。
谁言贫士叹，不为身无衣。','',''),('quantangshi-32566','琪树下因吟六韵呈先达者','劉駕','quantangshi','','卷33','举世爱嘉树，此树何人识。
清秋远山意，偶向亭际得。
奇柯交若鬬，珍叶密如织。
尘中尚青葱，更想尘外色。
所宜巢三鸟，影入瑶池碧。
移根岂无时，一问紫烟客。','',''),('quantangshi-32567','送人登第东归','劉駕','quantangshi','','卷33','学古既到古，反求鉴者难。
见诗未识君，疑生建安前。
海畔岂无家，终难成故山。
得失虽由命，世途多险艰。
我皇追古风，文柄付大贤。
此时如为君，果在甲科间。
晚达多早贵，举世咸为然。
一夕颜却少，虽病心且安。
所居似清明，冷竈起新烟。
高情懒行乐，花盛仆马前。
归程不淹留，指期到田园。
香醪四邻熟，霜橘千株繁。
肯忆长安夜，论诗风雪寒。','',''),('quantangshi-32568','贾客词','劉駕','quantangshi','','卷33','贾客灯下起，犹言发已迟。
高山有疾路，暗行终不疑。
寇盗伏其路，猛兽来相追。
金玉四散去，空囊委路岐。
扬州有大宅，白骨无地归。
少妇当此日，对镜弄花枝。','',''),('quantangshi-32569','塞下曲','劉駕','quantangshi','','卷33','勒兵辽水边，风急卷旌旃。
绝塞阴无草，平沙去尽天。
下营看斗建，传号信狼烟。
圣代书青史，当时破虏年。','',''),('quantangshi-32570','春夜二首 一','劉駕','quantangshi','','卷33','一别杜陵归未期，祗凭魂梦接亲知。
近来欲睡兼难睡，夜夜夜深闻子规。','',''),('quantangshi-32571','春夜二首 二','劉駕','quantangshi','','卷33','几岁干戈阻路岐，忆山心切与心违。
时难何处披衷抱，日日日斜空醉归。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32572','郪中感怀','劉駕','quantangshi','','卷33','顷年曾住此中来，今日重游事可哀。
忆得几家欢宴处，家家家业尽成灰。','',''),('quantangshi-32573','晓登迎春阁','劉駕','quantangshi','','卷33','未栉凭栏眺锦城，烟笼万井二江明。
香风满阁花满树，树树树梢啼晓莺。','',''),('quantangshi-32574','白髭','劉駕','quantangshi','','卷33','到处逢人求至药，几回染了又成丝。
素丝易染髭难染，墨翟当年合泣髭。','',''),('quantangshi-32575','送卢使君赴夔州','劉駕','quantangshi','','卷33','铙管随征斾，高秋上远巴。
白波连雾雨，青壁断蒹葭。
凭几双瞳静，登楼万井斜。
政成知俗变，当应画轮车。','',''),('quantangshi-32576','望月','劉駕','quantangshi','','卷33','清秋新霁与君同，江上高楼倚碧空。
酒尽露零宾客散，更更更漏月明中。','',''),('quantangshi-32577','古意','劉駕','quantangshi','','卷33','蒲帆出浦去，但见浦边树。
不如马行郎，马迹犹在路。
大舟不相载，买宅令委住。
莫道留金多，本非爱郎富。','',''),('quantangshi-32578','长洲怀古','劉滄','quantangshi','','卷33','野烧原空尽荻灰，吴王此地有楼台。
千年事往人何在，半夜月明潮自来。
白鸟影从江树没，清猨声入楚云哀。
停车日晚荐苹藻，风静寒塘花正开。','',''),('quantangshi-32579','经炀帝行宫','劉滄','quantangshi','','卷33','此地曾经翠辇过，浮云流水竟如何。
香销南国美人尽，怨入东风芳草多。
残柳宫前空露叶，夕阳川上浩烟波。
行人遥起广陵思，古渡月明闻棹歌。','',''),('quantangshi-32580','春日游嘉陵江','劉滄','quantangshi','','卷33','独泛扁舟映绿杨，嘉陵江水色苍苍。
行看芳草故乡远，坐对落花春日长。
曲岸危樯移渡影，暮天栖鸟入山光。
今来谁识东归意，把酒闲吟思洛阳。','',''),('quantangshi-32581','秋日山斋书怀','劉滄','quantangshi','','卷33','启户清风枕簟幽，虫丝吹落挂帘钩。
蝉吟高树雨初霁，人忆故乡山正秋。
浩渺蒹葭连夕照，萧疎杨柳隔沙洲。
空将方寸荷知己，身寄烟萝恩未酬。','',''),('quantangshi-32582','晚秋洛阳客舍','劉滄','quantangshi','','卷33','清洛平分两岸沙，沙边水色近人家。
隋朝古陌铜驼柳，石氏荒原金谷花。
庭叶霜浓悲远客，宫城日晚度寒鵶。
未成归计关河阻，空望白云乡路赊。','',''),('quantangshi-32583','深愁喜友人至','劉滄','quantangshi','','卷33','不避驱羸道路长，青山同喜惜年光。
灯前话旧堦草夜，月下醉吟溪树霜。
落叶已经寒烧尽，衡门犹对古城荒。
此身未遂归休计，一半生涯寄岳阳。','',''),('quantangshi-32584','秋日望西阳','劉滄','quantangshi','','卷33','古木苍苔坠几层，行人一望旅情增。
太行山下黄河水，铜雀台西武帝陵。
风入蒹葭秋色动，雨余杨柳暮烟凝。
野花似泣红妆泪，寒露满枝枝不胜。','',''),('quantangshi-32585','邺都怀古','劉滄','quantangshi','','卷33','昔时霸业何萧索，古木唯多鸟雀声。
芳草自生宫殿处，牧童谁识帝王城。
残春杨柳长川迥，落日蒹葭远水平。
一望青山便惆怅，西陵无主月空明。','',''),('quantangshi-32586','题龙门僧房','劉滄','quantangshi','','卷33','静室遥临伊水东，寂寥谁与此身同。
禹门山色度寒磬，萧寺竹声来晚风。
僧宿石龛残雪在，雁归沙渚夕阳空。
偶将心地问高士，坐指浮生一梦中。','',''),('quantangshi-32587','秋夕山斋即事','劉滄','quantangshi','','卷33','衡门无事闭苍苔，篱下萧疎野菊开。
半夜秋风江色动，满山寒叶雨声来。
雁飞关塞霜初落，书寄乡闾人未回。
独坐高窗此时节，一弹瑶瑟自成哀。','',''),('quantangshi-32588','江行书事','劉滄','quantangshi','','卷33','远渚蒹葭覆绿苔，姑苏南望思裴徊。
空江独树楚山背，暮雨一舟吴苑来。
人度深秋风叶落，鸟飞残照水烟开。
寒潮欲上泛萍藻，寄荐三闾情自哀。','',''),('quantangshi-32589','过铸鼎原','劉滄','quantangshi','','卷33','黄帝修真万国朝，鼎成龙驾上丹霄。
天风乍起鹤声远，海雾渐深龙节遥。
仙界日长青鸟度，御衣香散紫霞飘。
唯留古迹寒原在，碧水苍苍空寂寥。','',''),('quantangshi-32590','秋日寓怀','劉滄','quantangshi','','卷33','海上生涯一钓舟，偶因名利事淹留。
旅涂谁见客青眼，故国几多人白头。
霁色满川明水驿，蝉声落日隐城楼。
如何未尽此行役，西入潼关云木秋。','',''),('quantangshi-32591','江城晚望','劉滄','quantangshi','','卷33','一望江城思有余，遥分野迳入樵渔。
青山经雨菊花尽，白鸟下滩芦叶疎。
静听潮声寒木杪，远看风色暮帆舒。
秋期又涉潼关路，不得年年向此居。','',''),('quantangshi-32592','宿苍溪馆','劉滄','quantangshi','','卷33','孤馆门开对碧岑，竹窗灯下听猨吟。
巴山夜雨别离梦，秦塞旧山迢遰心。
满地莓苔生近水，几株杨柳自成阴。
空思知己隔云岭，乡路独归春草深。','',''),('quantangshi-32593','题王母庙','劉滄','quantangshi','','卷33','寂寥珠翠想遗声，门掩烟微水殿清。
拂曙紫霞生古壁，何年绛节下层城。
鹤归辽海春光晚，花落闲堦夕雨晴。
武帝无名在仙籍，玉坛星月夜空明。','',''),('quantangshi-32594','留别复本修古二上人','劉滄','quantangshi','','卷33','二远相知是昔年，此身长寄礼香烟。
绿芜风晚水边寺，清磬月高林下禅。
台殿虚窗山翠入，梧桐疎叶露光悬。
西峰话别又须去，终日关山在马前。','',''),('quantangshi-32595','边思','劉滄','quantangshi','','卷33','汉将边方背辘轳，受降城北是单于。
黄河晚冻雪风急，野火远烧山木枯。
偷号甲兵冲塞色，衔枚战马踏寒芜。
蛾眉一没空留怨，青冢月明啼夜乌。','',''),('quantangshi-32596','登龙门敬善寺阁','劉滄','quantangshi','','卷33','独步危梯入杳冥，天风潇洒拂檐楹。
禹门烟树正春色，少室云屏向晚晴。
花落院深清禁闭，水分川阔绿芜平。
琐窗朱槛同仙界，半夜缑山有鹤声。','',''),('quantangshi-32597','题王校书山斋','劉滄','quantangshi','','卷33','猨鸟无声昼掩扉，寒原隔水到人稀。
云晴古木月初上，雪满空庭鹤未归。
药囿地连山色近，樵家路入树烟微。
栖迟惯得沧浪思，云阁还应梦钓矶。','',''),('quantangshi-32598','浙江晚渡怀古','劉滄','quantangshi','','卷33','蝉噪秋风满古堤，荻花寒渡思萋萋。
潮声归海鸟初下，草色连江人自迷。
碧落晴分平楚外，青山晚出穆陵西。
此来一见垂纶者，却忆旧居明月溪。','',''),('quantangshi-32599','及第后宴曲江','劉滄','quantangshi','','卷33','及第新春选胜游，杏园初宴曲江头。
紫毫粉壁题仙籍，柳色箫声拂御楼。
霁景露光明远岸，晚空山翠坠芳洲。
归时不省花间醉，绮陌香车似水流。','',''),('quantangshi-32600','秋日山寺怀友人','劉滄','quantangshi','','卷33','萧寺楼台对夕阴，淡烟疎磬散空林。
风生寒渚白苹动，霜落秋山黄叶深。
云尽独看晴塞雁，月明遥听远村砧。
相思不见又经岁，坐向松窗弹玉琴。','',''),('quantangshi-32601','八月十五日夜玩月','劉滄','quantangshi','','卷33','中秋朗月静天河，乌鹊南飞客恨多。
寒色满窗明枕簟，清光凝露拂烟萝。
桂枝斜汉流灵魄，苹叶微风动细波。
此夜空亭闻木落，蒹葭霜碛雁初过。','',''),('quantangshi-32602','晚春宿僧院','劉滄','quantangshi','','卷33','萧寺春风正落花，淹留数宿惠休家。
碧空云尽磬声远，清夜月高窗影斜。
白日闲吟为道侣，青山遥指是生涯。
微微一点寒灯在，乡梦不成闻曙鵶。','',''),('quantangshi-32603','怀汶阳兄弟','劉滄','quantangshi','','卷33','回看云岭思茫茫，几处关河隔汶阳。
书信经年乡国远，弟兄无力海田荒。
天高霜月砧声苦，风满寒林木叶黄。
终日路岐归未得，秋来空羡雁成行。','',''),('quantangshi-32604','题天宫寺阁','劉滄','quantangshi','','卷33','丹阙侵霄壮复危，排空霞影动檐扉。
城连伊水禹门近，烟隔上阳宫树微。
天歛暮云残雨歇，路穿春草一僧归。
此来闲望更何有，无限清风生客衣。','',''),('quantangshi-32605','游上方石窟寺','劉滄','quantangshi','','卷33','苔径萦回景渐分，翛然空界静埃氛。
一声疎磬过寒水，半壁危楼隐白云。
雪下石龛僧在定，日西山木鸟成羣。
几来吟啸立朱槛，风起天香处处闻。','',''),('quantangshi-32606','怀江南友人','劉滄','quantangshi','','卷33','久绝音书隔塞尘，路岐谁与子相亲。
愁中独坐秦城夜，别后几经吴苑春。
湘岸风来吹绿绮，海门潮上没青苹。
空劳两地望明月，多感断蓬千里身。','',''),('quantangshi-32607','题敬亭山庙','劉滄','quantangshi','','卷33','森森古木列岩隈，迥压寒原霁色开。
云雨只从山上起，风雷多向庙中来。
三江入海声长在，双鹤啼天影未回。
花落空庭春昼晚，石牀松殿满青苔。','',''),('quantangshi-32608','经麻姑山','劉滄','quantangshi','','卷33','麻姑此地炼神丹，寂寞烟霞古竈残。
一自仙娥归碧落，几年春雨洗红兰。
帆飞震泽秋江远，雨过陵阳晚树寒。
山顶白云千万片，时闻鸾鹤下仙坛。','',''),('quantangshi-32609','对残春','劉滄','quantangshi','','卷33','杨花漠漠暗长堤，春尽人愁鸟又啼。
鬓髪近来生处白，家园几向梦中迷。
霏微远树荒郊外，牢落空城夕照西。
唯有年光堪自惜，不胜烟草日萋萋。','',''),('quantangshi-32610','过沧浪峡','劉滄','quantangshi','','卷33','山叠云重一径幽，苍苔古石濑清流。
出岩树色见来静，落涧泉声长自秋。
远入虚明思白帝，寒生浩景想沧洲。
如何地近东西路，马足车轮不暂留。','',''),('quantangshi-32611','经过建业','劉滄','quantangshi','','卷33','六代兴衰曾此地，西风露泣白苹花。
烟波浩渺空亡国，杨柳萧条有几家。
楚塞秋光晴入树，浙江残雨晚生霞。
凄凉处处渔樵路，鸟去人归山影斜。','',''),('quantangshi-32612','赠道者','劉滄','quantangshi','','卷33','真趣淡然居物外，忘机多是隐天台。
停灯深夜看仙箓，拂石高秋坐钓台。
卖药故人湘水别，入檐栖鸟旧山来。
无因朝市知名姓，地僻衡门对岳开。','',''),('quantangshi-32613','题马太尉华山庄','劉滄','quantangshi','','卷33','别开池馆背山阴，近得幽奇物外心。
竹色拂云连岳寺，泉声带雨出溪林。
一庭杨柳春光暖，三迳烟萝晚翠深。
自是功成闲劒履，西斋长卧对瑶琴。','',''),('quantangshi-32614','秋日夜怀','劉滄','quantangshi','','卷33','砧杵寥寥秋色长，遶枝寒鹊客情伤。
关山云尽九秋月，门柳叶凋三径霜。
近日每思归少室，故人遥忆隔潇湘。
如何节候变容髪，明镜一看愁异常。','',''),('quantangshi-32615','题巫山庙','劉滄','quantangshi','','卷33','十二岚峯挂夕晖，庙门深闭雾烟微。
天高木落楚人思，山迥月残神女归。
触石晴云凝翠鬓，度江寒雨湿罗衣。
婵娟似恨襄王梦，猨呌断岩秋藓稀。','',''),('quantangshi-32616','题吴宫苑','劉滄','quantangshi','','卷33','吴苑荒凉故国名，吴山月上照江明。
残春碧树自留影，半夜子规何处声。
芦叶长侵洲渚暗，苹花开尽水烟平。
经过此地千年恨，荏苒东风露色清。','',''),('quantangshi-32617','旅馆书怀','劉滄','quantangshi','','卷33','秋看庭树换风烟，兄弟飘零寄海边。
客计倦行分陕路，家贫休种汶阳田。
云低远塞鸣寒雁，雨歇空山噪暮蝉。
落叶虫丝满窗户，秋堂独坐思悠然。','',''),('quantangshi-32618','赠天台隐者','劉滄','quantangshi','','卷33','静者多依猨鸟丛，衡门野色四郊通。
天开宿雾海生日，水泛落花山有风。
回望一巢悬木末，独寻危石坐岩中。
看书饮酒余无事，自乐樵渔狎钓翁。','',''),('quantangshi-32619','洛阳月夜书怀','劉滄','quantangshi','','卷33','疎柳高槐古巷通，月明西照上阳宫。
一声边雁塞门雪，几处远砧河汉风。
独榻闲眠移岳影，寒窗幽思度烟空。
孤吟此夕惊秋晚，落叶残花树色中。','',''),('quantangshi-32620','江行夜泊','劉滄','quantangshi','','卷33','白浪连空极渺漫，孤舟此夜泊中滩。
岳阳秋霁寺钟远，渡口月明渔火残。
绿绮韵高湘女怨，青葭色映水禽寒。
乡遥楚国生归思，欲曙山光上木兰。','',''),('quantangshi-32621','赠颛顼山人','劉滄','quantangshi','','卷33','浩气含真玉片辉，着书精义入玄微。
洛阳紫陌几曾醉，少室白云时一归。
松雪月高唯鹤宿，烟岚秋霁到人稀。
知君济世有长策，莫问沧浪隐钓矶。','',''),('quantangshi-32622','长安冬夜书情','劉滄','quantangshi','','卷33','上国栖迟岁欲终，此情多寄寂寥中。
钟传半夜旅人馆，鵶呌一声疎树风。
古巷月高山色静，寒芜霜落灞原空。
今来唯问心期事，独望青云路未通。','',''),('quantangshi-32623','经古行宫','劉滄','quantangshi','','卷33','玉辇西归已至今，古原风景自沈沈。
御沟流水长芳草，宫树落花空夕阴。
胡蝶翅翻残露滴，子规声尽野烟深。
路人不记当年事，台殿寂寥山影侵。','',''),('quantangshi-32624','秋日登醴泉县楼','劉滄','quantangshi','','卷33','闲上高楼时一望，绿芜寒野静中分。
人行直路入秦树，雁截斜阳背塞云。
渭水自流汀岛色，汉陵空长石苔纹。
秋风高柳出危叶，独听蝉声日欲曛。','',''),('quantangshi-32625','春日旅游','劉滄','quantangshi','','卷33','玄髪辞家事远游，春风归雁一声愁。
花开忽忆故山树，月上自登临水楼。
浩浩晴原人独去，依依春草水分流。
秦川楚塞烟波隔，怨别路岐何日休。','',''),('quantangshi-32626','送友人下第归吴','劉滄','quantangshi','','卷33','共惜年华未立名，路岐终日轸羁情。
青春半是往来尽，白发多因离别生。
楚岸帆开云树映，吴门月上水烟清。
东归自有故山约，花落石牀苔藓平。','',''),('quantangshi-32627','访友人郊居','劉滄','quantangshi','','卷33','登原过水访相如，竹坞莎庭似故居。
空塞山当清昼晚，古槐人继绿阴余。
休弹瑟韵伤离思，已有蝉声报夏初。
醉唱劳歌翻自叹，钓船渔浦梦难疎。','',''),('quantangshi-32628','匡城寻薛闵秀才不遇','劉滄','quantangshi','','卷33','音容一别近三年，往事空思意浩然。
匹马东西何处客，孤城杨柳晚来蝉。
路长草色秋山绿，川阔晴光远水连。
不见故人劳梦寐，独吟风月过南燕。','',''),('quantangshi-32629','与僧话旧','劉滄','quantangshi','','卷33','巾舃同时下翠微，旧游因话事多违。
南朝古寺几僧在，西岭空林唯鸟归。
莎径晚烟凝竹坞，石池春色染苔衣。
此时相见又相别，即是关河朔雁飞。','',''),('quantangshi-32630','寄远','劉滄','quantangshi','','卷33','西园杨柳暗惊秋，宝瑟朱弦结远愁。
霜落雁声来紫塞，月明人梦在青楼。
蕙心迢遰湘云暮，兰思萦回楚水流。
锦字织成添别恨，关河万里路悠悠。','',''),('quantangshi-32631','长安逢友人','劉滄','quantangshi','','卷33','上国相逢尘满襟，倾杯一话昔年心。
荒台共望秋山立，古寺多同雪夜吟。
风度重城宫漏尽，月明高柳禁烟深。
终期白日青云路，休感鬓毛霜雪侵。','',''),('quantangshi-32632','下第东归途中书事','劉滄','quantangshi','','卷33','峡路谁知倦此情，往来多是半年程。
孤吟洛苑逢春尽，几向秦城见月明。
高柳断烟侵岳影，古堤斜日背滩声。
东归海上有余业，牢落田园荒草平。','',''),('quantangshi-32633','经龙门废寺','劉滄','quantangshi','','卷33','因思人事事无穷，几度经过感此中。
山色不移楼殿尽，石台依旧水云空。
唯余芳草滴春露，时有残花落晚风。
杨柳覆滩清濑响，暮天沙鸟自西东。','',''),('quantangshi-32634','下第后怀旧居','劉滄','quantangshi','','卷33','几到青门未立名，芳时多负故乡情。
雨余秦苑绿芜合，春尽灞原白发生。
每见山泉长属意，终期身事在归耕。
苹花覆水曲溪暮，独坐钓舟歌月明。','',''),('quantangshi-32635','经无可旧居兼伤贾岛','劉滄','quantangshi','','卷33','尘室寒窗我独看，别来人事几凋残。
昼空萧寺一僧去，雪满巴山孤客寒。
落叶堕巢禽自出，苍苔封砌竹成竿。
碧云迢遰长江远，向夕苦吟归思难。','',''),('quantangshi-32636','赠隐者','劉滄','quantangshi','','卷33','何时止此幽栖处，独掩衡门长绿苔。
临水静闻灵鹤语，隔原时有至人来。
五湖仙岛几年别，九转药炉深夜开。
谁识无机养真性，醉眠松石枕空杯。','',''),('quantangshi-32637','题书斋','劉滄','quantangshi','','卷33','一日不曾离此处，风吹疎牖夕云晴。
气凌霜色劒光动，吟对雪华诗韵清。
高木宿禽来远岳，古原残雨隔重城。
西斋瑶瑟自为侣，门掩半春苔藓生。','',''),('quantangshi-32638','题秦女楼','劉滄','quantangshi','','卷33','珠翠香销鸳瓦堕，神仙曾向此中游。
青楼月色桂花冷，碧落箫声云叶愁。
杳杳蓬莱人不见，苍苍苔藓路空留。
一从凤去千年后，迢遰岐山水石秋。','',''),('quantangshi-32639','题桃源处士山居留寄','劉滄','quantangshi','','卷33','白云深处葺茅庐，退隐衡门与俗疎。
一洞晓烟留水上，满庭春露落花初。
闲看竹屿吟新月，特酌山醪读古书。
穷达尽为身外事，浩然元气乐樵渔。','',''),('quantangshi-32640','宿题天坛观','劉滄','quantangshi','','卷33','沐髪清斋宿洞宫，桂花松韵满岩风。
紫霞晓色秋山霁，碧落寒光霜月空。
华表鹤声天外迥，蓬莱仙界海门通。
冥心一悟虚无理，寂寞玄珠象罔中。','',''),('quantangshi-32641','洛神怨','劉滄','quantangshi','','卷33','子建东归恨思长，飘颻神女步池塘。
云鬟高动水宫影，珠翠乍摇沙露光。
心寄碧沈空婉恋，梦残春色自悠扬。
停车绮陌傍杨柳，片月青楼落未央。','',''),('quantangshi-32642','龙门留别道友','劉滄','quantangshi','','卷33','一顾恩深荷道安，独垂双泪下层峦。
飞鸣北雁塞云暮，摇落西风关树寒。
春谷终期吹羽翼，萍身不定逐波澜。
裴徊偏起旧枝恋，半夜独吟孤烛残。','',''),('quantangshi-32643','题四皓庙','劉滄','quantangshi','','卷33','石壁苍苔翠霭浓，驱车商洛想遗踪。
天高猨呌向山月，露下鹤声来庙松。
叶堕阴岩疎薜荔，池经秋雨老芙蓉。
雪髯仙侣何深隐，千古寂寥云水重。','',''),('quantangshi-32644','望未央宫','劉滄','quantangshi','','卷33','西上秦原见未央，山岚川色晚苍苍。
云楼欲动入清渭，鸳瓦如飞出绿杨。
舞席歌尘空岁月，宫花春草满池塘。
香风吹落天人语，彩凤五云朝汉皇。','',''),('quantangshi-32645','秋日过昭陵','劉滄','quantangshi','','卷33','寝庙徒悲劒与冠，翠华龙驭杳漫漫。
原分山势入空塞，地匝松阴出晚寒。
上界鼎成云缥缈，西陵舞罢泪阑干。
那堪独立斜阳里，碧落秋光烟树残。','',''),('quantangshi-32646','夏日登慈恩寺','劉滄','quantangshi','','卷33','金界时来一访僧，天香飘翠琐窗凝。
碧池静照寒松影，清昼深悬古殿灯。
晚景风蝉催节候，高空云鸟度轩层。
尘机消尽话玄理，暮磬出林疎韵澄。','',''),('quantangshi-32647','宿题金山寺','劉滄','quantangshi','','卷33','一点青山翠色危，云岩不掩与星期。
海门烟树潮归后，江面山楼月照时。
独鹤唳空秋露下，高僧入定夜猨知。
萧疎水木清钟梵，颢气寒光动石池。','',''),('quantangshi-32648','送友人游蜀','劉滄','quantangshi','','卷33','北去西游春未半，蜀山云雪入诗情。
青萝拂水花流影，翠霭隔岩猨有声。
日出空江分远浪，鸟归高木认孤城。
心期万里无劳倦，古石苍苔峡路清。','',''),('quantangshi-32649','题郑中丞东溪','劉滄','quantangshi','','卷33','一境新开雉堞西，绿苔微径露凄凄。
高轩夜静竹声远，曲岸春深杨柳低。
山霁月明常此醉，草芳花暗省曾迷。
即随凤诏归清列，几忆风花梦小溪。','',''),('quantangshi-32650','代友人悼姬','劉滄','quantangshi','','卷33','罗帐香微冷锦裀，歌声永绝想梁尘。
萧郎独宿落花夜，谢女不归明月春。
青鸟罢传相寄字，碧江无复采莲人。
满庭芳草坐成恨，迢遰蓬莱入梦频。','',''),('quantangshi-32651','夏日登西林白上人楼','劉滄','quantangshi','','卷33','几到西林清净境，层台高视有无间。
寒光远动天边水，碧影出空烟外山。
苔点落花微萼在，叶藏幽鸟碎声闲。
旷然多慊登楼意，永日重门深掩关。','',''),('quantangshi-32652','江楼月夜闻笛','劉滄','quantangshi','','卷33','南浦蒹葭疎雨后，寂寥横笛怨江楼。
思飘明月浪花白，声入碧云枫叶秋。
河汉夜阑孤雁度，潇湘水阔二妃愁。
髪寒衣湿曲初罢，露色河光生钓舟。','',''),('quantangshi-32653','送友人下第东归','劉滄','quantangshi','','卷33','漠漠杨花灞岸飞，几回倾酒话东归。
九衢春尽生乡梦，千里尘多满客衣。
流水雨余芳草合，空山月晚白云微。
金门自有西来约，莫待萤光照竹扉。','',''),('quantangshi-32654','从郑郎中高州游东潭','劉滄','quantangshi','','卷33','烟岚晚入湿旌旗，高槛风清醉未归。
夹路野花迎马首，出林山鸟向人飞。
一溪寒水涵清浅，几处晴云度翠微。
自是谢公心近得，登楼望月思依依。','',''),('quantangshi-32655','罢华原尉上座主尚书','劉滄','quantangshi','','卷33','自怜生计事悠悠，浩渺沧浪一钓舟。
千里梦归清洛近，三年官罢杜陵秋。
山连绝塞浑无色，水到平沙几处流。
白露黄花岁时晚，不堪霜鬓镜前愁。','',''),('quantangshi-32656','雨后游南门寺','劉滄','quantangshi','','卷33','郭南山寺雨初晴，上界寻僧竹里行。
半壁楼台秋月过，一川烟水夕阳平。
苔封石室云含润，露滴松枝鹤有声。
木叶萧萧动归思，西风画角汉东城。','',''),('quantangshi-32657','题古寺','劉滄','quantangshi','','卷33','古寺萧条偶宿期，更深霜压竹枝低。
长天月影高窗过，疎树寒鵶半夜啼。
池水竭来龙已去，老松枯处鹤犹栖。
伤心可惜从前事，寥落朱廊堕粉泥。','',''),('quantangshi-32658','晚秋野望','劉滄','quantangshi','','卷33','秋尽郊原情自哀，菊花寂寞晚仍开。
高风疎叶带霜落，一雁寒声背水来。
荒垒几年经战后，故山终日望书回。
归途休问从前事，独唱劳歌醉数杯。','',''),('quantangshi-32659','秋月望上阳宫','劉滄','quantangshi','','卷33','苔色轻尘锁洞房，乱鸦羣鸽集残阳。
青山空出禁城日，黄叶自飞宫树霜。
御路几年香辇去，天津终日水声长。
此时独立意难尽，正值西风砧杵凉。','',''),('quantangshi-32660','入关留别主人','劉滄','quantangshi','','卷33','此来多愧食鱼心，东阁将辞强一吟。
羸马客程秋草合，晚蝉关树古槐深。
风生野渡河声急，雁过寒原岳势侵。
对酒相看自无语，几多离思入瑶琴。','',''),('quantangshi-32661','留别山中友人','劉滄','quantangshi','','卷33','欲辞松月恋知音，去住多同羁鸟心。
秋尽书窗惊白发，晚冲霜叶下青岑。
大河风急寒声远，高岭云开夕影深。
别后寂寥无限意，野花门路草虫吟。','',''),('quantangshi-32662','春晚旅次有怀','劉滄','quantangshi','','卷33','晚出关河绿野平，依依云树动乡情。
残春花尽黄莺语，远客愁多白发生。
野水乱流临古驿，断烟凝处近孤城。
东西未遂归田计，海上青山久废耕。','',''),('quantangshi-32663','与重幽上人话旧','劉滄','quantangshi','','卷33','云飞天末水空流，省与师同别异州。
庭树蝉声初入夏，石牀苔色几经秋。
灯微静室生乡思，月上严城话旅游。
自喜他年接巾舃，沧浪地近虎溪头。','',''),('quantangshi-32664','月夜闻鹤唳','劉滄','quantangshi','','卷33','碧落风微月正明，霜毛似怨有离情。
莓苔石冷想孤立，杨柳叶疎闻转清。
空夜露残惊堕羽，辽天秋晚忆归程。
凤凰楼阁知犹恋，终逐烟霞上玉京。','',''),('quantangshi-32665','过北邙山','劉滄','quantangshi','','卷33','散漫黄埃满北原，折碑横路碾苔痕。
空山夜月来松影，荒冢春风变木根。
漠漠兔丝罗古庙，翩翩丹旐过孤村。
白杨落日悲风起，萧索寒巢鸟独奔。','',''),('quantangshi-32666','咸阳怀古','劉滄','quantangshi','','卷33','经过此地无穷事，一望凄然感废兴。
渭水故都秦二世，咸原秋草汉诸陵。
天空绝塞闻边雁，叶尽孤村见夜灯。
风景苍苍多少恨，寒山半出白云层。','',''),('quantangshi-32667','送友人罢举赴蓟门从事','劉滄','quantangshi','','卷33','人生行止在知己，远佐诸侯重所依。
绿绶便当身是贵，青霄休怨志相违。
晚云辽水疎残雨，寒角边城怨落晖。
此去黄金台上客，相思应羡雁南归。','',''),('quantangshi-32668','看牓日','劉滄','quantangshi','','卷33','禁漏初停兰省开，列仙名目上清来。
飞鸣晓日莺声远，变化春风鹤影回。
广陌万人生喜色，曲江千树发寒梅。
青云已是酬恩处，莫惜芳时醉酒杯。','',''),('quantangshi-32669','送李休秀才归岭中','劉滄','quantangshi','','卷33','南泛孤舟景自饶，蒹葭汀浦晚萧萧。
秋风汉水旅愁起，寒木楚山归思遥。
独夜猨声和落叶，晴江月色带回潮。
故园新过重阳节，黄菊满篱应未凋。','',''),('quantangshi-32670','寓居寄友人','劉滄','quantangshi','','卷33','雨余虚馆竹阴清，独坐书窗轸旅情。
芳草衡门无马迹，古槐深巷有蝉声。
夕阳云尽嵩峰出，远岸烟消洛水平。
今夜南原赏佳景，月高风定苦吟生。','',''),('quantangshi-32671','经曲阜城','劉滄','quantangshi','','卷33','行经阙里自堪伤，曾叹东流逝水长。
萝蔓几凋荒陇树，莓苔多处古宫墙。
三千弟子标青史，万代先生号素王。
萧索风高洙泗上，秋山明月夜苍苍。','',''),('quantangshi-32672','汶阳客舍','劉滄','quantangshi','','卷33','年光自感益蹉跎，岐路东西竟若何。
窗外雨来山色近，海边秋至雁声多。
思乡每读登楼赋，对月空吟叩角歌。
迢遰旧山伊水畔，破斋荒径闭烟萝。','',''),('quantangshi-32673','留别崔澣秀才昆仲','劉滄','quantangshi','','卷33','汶阳离思水无穷，去住情深梦寐中。
岁晚虫鸣寒露草，日西蝉噪古槐风。
川分远岳秋光静，云尽遥天霁色空。
对酒不能伤此别，尺书凭雁往来通。','',''),('quantangshi-32674','和友人忆洞庭旧居','劉滄','quantangshi','','卷33','客舍经时益苦吟，洞庭犹忆在前林。
青山残月有归梦，碧落片云生远心。
溪路烟开江月出，草堂门掩海涛深。
因君话旧起愁思，隔水数声何处砧。','',''),('quantangshi-32675','晚归山居','劉滄','quantangshi','','卷33','寥落霜空木叶稀，初行郊野思依依。
秋深频忆故乡事，日暮独寻荒径归。
山影暗随云水动，钟声潜入远烟微。
娟娟唯有西林月，不惜清光照竹扉。','',''),('quantangshi-32676','送元叙上人归上党','劉滄','quantangshi','','卷33','太行关路战尘收，白日思乡别沃州。
薄暮焚香临野烧，清晨漱齿涉寒流。
溪边残垒空云木，山上孤城对驿楼。
此去寂寥寻旧迹，苍苔满径竹斋秋。','',''),('quantangshi-32677','秋日旅途即事','劉滄','quantangshi','','卷33','驱羸多自感，烟草远郊平。
乡路几时尽，旅人终日行。
渡边寒水驿，山下夕阳城。
萧索更何有，秋风两鬓生。','',''),('quantangshi-32678','早行','劉滄','quantangshi','','卷33','旅途乘早景，策马独凄凄。
残影郡楼月，一声关树鸡。
听钟烟柳外，问渡水云西。
当自勉行役，终期功业齐。','',''),('quantangshi-32679','句','劉滄','quantangshi','','卷33','海曙云浮日，江遥水合天。','',''),('quantangshi-32680','湘口送友人','李頻','quantangshi','','卷33','中流欲暮见湘烟，苇岸无穷接楚田。
去雁远冲云梦雪，离人独上洞庭船。
风波尽日依山转，星汉通霄向水连。
零落梅花过残腊，故园归醉及新年。','',''),('quantangshi-32681','鄂州头陀寺上方','李頻','quantangshi','','卷33','高寺上方无不见，天涯行客思迢迢。
西江帆挂东风急，夏口城衔楚塞遥。
沙渚渔归多湿网，桑林蚕后尽空条。
感时叹物寻僧话，惟向禅心得寂寥。','',''),('quantangshi-32682','寄远','李頻','quantangshi','','卷33','槐欲成阴分袂时，君期十日复金扉。
槐今落叶已将尽，君向远乡犹未归。
化石早曾闻节妇，沈湘何必独灵妃。
须知此意同生死，不学他人空寄衣。','',''),('quantangshi-32683','题张司马别墅','李頻','quantangshi','','卷33','庭前树尽手中栽，先后花分几番开。
巢鸟恋雏惊不起，野人思酒去还来。
自抛官与青山近，谁讶身为白发催。
门外寻常行乐处，重重履迹在莓苔。','',''),('quantangshi-32684','长安即事','李頻','quantangshi','','卷33','长遇豪家不敢过，此身谁与取高科。
故园久绝书来后，南国空看雁去多。
中夜永怀听叠漏，先秋归梦涉层波。
愁人白发自生早，我独少年能几何。','',''),('quantangshi-32685','汉上逢同年崔八','李頻','quantangshi','','卷33','去岁曾游帝里春，杏花开过各离秦。
偶先托质逢知己，独未还家作旅人。
世上路岐何缭绕，空中光景自逡巡。
一回相见一回别，能得几时年少身。','',''),('quantangshi-32686','五月一日蒙替本官不得随例入关感怀献送相公','李頻','quantangshi','','卷33','五月倾朝谒紫宸，一朝无分在清尘。
含香已去星郎位，衣锦惟思婺女隣。
折狱也曾为俗吏，劝农元本是耕人。
知将何事酬公道，只养生灵似养身。','',''),('quantangshi-32687','春闺怨','李頻','quantangshi','','卷33','红妆女儿灯下羞，画眉夫壻陇西头。
自怨愁容长照镜，悔教征戍觅封侯。','',''),('quantangshi-32688','送边将','李頻','quantangshi','','卷33','防秋戎马恐来奔，诏发将军出雁门。
遥领短兵登陇首，独横长劒向河源。
悠扬落日黄云动，苍莽阴风白草翻。
若纵干戈更深入，应闻收得到昆仑。','',''),('quantangshi-32689','太和公主还宫','李頻','quantangshi','','卷33','天骄发使犯边尘，汉将推功遂夺亲。
离乱应无初去貌，死生难有却回身。
禁花半老曾攀树，宫女多非旧识人。
重上凤楼追故事，几多愁思向青春。','',''),('quantangshi-32690','将赴黔州先寄本府中丞','李頻','quantangshi','','卷33','八月瞿塘到底翻，孤舟上得已销魂。
幕中职罢犹趋府，阙下官成未谢恩。
丹嶂耸空无过鸟，青林覆水有垂猿。
感知肺腑终难说，从此辞归便扫门。','',''),('quantangshi-32691','和友人下第北游感怀','李頻','quantangshi','','卷33','圣代为儒可致身，谁知又别五陵春。
青门独出空归鸟，紫陌相逢尽醉人。
江岛去寻垂钓远，塞山来见举头频。
且须共漉边城酒，何必陶家有白纶。','',''),('quantangshi-32692','乐游原春望','李頻','quantangshi','','卷33','五陵佳气晚氛氲，霸业雄图势自分。
秦地山河连楚塞，汉家宫殿入青云。
未央树色春中见，长乐钟声月下闻。
无那杨华起愁思，满天飘落雪纷纷。','',''),('quantangshi-32693','黄雀行','李頻','quantangshi','','卷33','欲窃高仓集御河，翩翩疑渡畏秋波。
朱宫晚树侵莺语，画阁香帘夺燕窠。
疎影暗栖寒露重，空城饥噪暮烟多。
谁令不解高飞去，破宅荒庭有网罗。','',''),('quantangshi-32694','长安寓居寄柏侍郎','李頻','quantangshi','','卷33','霜轻两鬓欲相侵，愁绪无端不可寻。
秦女红妆空觅伴，郢郎白雪少知音。
长亭古木春光老，太华青烟晚更深。
独向灞陵东北望，一封书寄万重心。','',''),('quantangshi-32695','春日思归','李頻','quantangshi','','卷33','春情不断若连环，一夕思归鬓欲斑。
壮志未酬三尺劒，故乡空隔万重山。
音书断绝干戈后，亲友相逢梦寐间。
却羡浮云与飞鸟，因风吹去又吹还。','',''),('quantangshi-32696','朔中即事','李頻','quantangshi','','卷33','关门南北杂戎夷，草木秋来即出师。
落日风沙长暝早，穷冬雨雪转春迟。
山头堠火孤明后，星外行人四绝时。
自古边功何不立，汉家中外自相疑。','',''),('quantangshi-32697','感怀献门下相公','李頻','quantangshi','','卷33','谁云郎选不由诗，上相怜才积有时。
却是龙钟到门晚，终非稽古致身迟。
谋将郡印归难遂，读着家书坐欲痴。
日望南宫看列宿，迢迢婺女与乡比。','',''),('quantangshi-32698','赠长城庾将军','李頻','quantangshi','','卷33','初年三十拜将军，近代英雄独未闻。
向国报恩心比石，辞天作镇气凌云。
逆风走马貂裘卷，望塞悬弧雁阵分。
定拥节麾从此去，安西大破犬戎羣。','',''),('quantangshi-32699','浙东献郑大夫','李頻','quantangshi','','卷33','圣主东忧涨海滨，思移副相倚陶钧。
楼台独坐江山月，舟楫先行泽国春。
遥想万家开户外，近闻羣盗窜诸邻。
几时入去调元化，天下同为尧舜人。','',''),('quantangshi-32700','镜湖夜泊有怀','李頻','quantangshi','','卷33','广水遥堤利物功，因思太守惠无穷。
自从版筑兴农隙，长与耕耘致岁丰。
涨接星津流荡漾，宽浮云岫动虚空。
想当战国开时有，范蠡扁舟祗此中。','',''),('quantangshi-32701','宣州献从叔大夫','李頻','quantangshi','','卷33','清时选地任贤明，从此观风辍尹京。
日月天中辞洛邑，云山江上领宣城。
万家闾井俱安寝，千里农桑竟起耕。
闻说圣朝同汉代，已愁征入拜公卿。','',''),('quantangshi-32702','贺同年翰林从叔舍人知制诰','李頻','quantangshi','','卷33','仙禁何人蹑近踪，孔门先选得真龙。
别居云路抛三省，专掌天书在九重。
五色毫挥成涣汗，百寮班下独从容。
芳年贵盛谁为比，郁郁青青岳顶松。','',''),('quantangshi-32703','吴门别主人','李頻','quantangshi','','卷33','早晚更看吴苑月，小斋长忆落西窗。
不知明夜谁家见，应照离人隔楚江。','',''),('quantangshi-32704','自黔中归新安','李頻','quantangshi','','卷33','朝过春关辞北阙，暮参戎幕向南巴。
却将仙桂东归去，江月相随直到家。','',''),('quantangshi-32705','奉和郑薰相公','李頻','quantangshi','','卷33','三四株松匝草亭，便成彭泽柳为名。
莲峰隐去难辞阙，浐水朝回与出城。','',''),('quantangshi-32706','及第后还家过岘岭','李頻','quantangshi','','卷33','魏驮山前一朵花，岭西更有几千家。
石斑鱼鲊香冲鼻，浅水沙田饭遶牙。','',''),('quantangshi-32707','春日旅舍','李頻','quantangshi','','卷33','未识东西南北路，青春白日坐销难。
如何一别故园后，五度花开五处看。','',''),('quantangshi-32708','过长江伤贾岛','李頻','quantangshi','','卷33','忽从一宦远流离，无罪无人子细知。
到得长江闻杜宇，想君魂魄也相随。','',''),('quantangshi-32709','自遣','李頻','quantangshi','','卷33','永拟东归把钓丝，将行忽起半心疑。
青云道是不平地，还有平人上得时。','',''),('quantangshi-32710','寄曹邺','李頻','quantangshi','','卷33','终南山是枕前云，禁鼓无因晓夜闻。
朝客秋来不朝日，曲江西岸去寻君。','',''),('quantangshi-32711','述怀','李頻','quantangshi','','卷33','望月疑无得桂缘，春天又待到秋天。
杏花开与槐花落，愁去愁来过几年。','',''),('quantangshi-32712','客洛酬刘驾','李頻','quantangshi','','卷33','浮世总应相送老，共君偏更远行多。
此回不似前回别，听尽离歌逐棹歌。','',''),('quantangshi-32713','题钓台障子','李頻','quantangshi','','卷33','君家尽是我家山，严子前台枕古湾。
却把钓竿终不可，几时入海得鱼还。','',''),('quantangshi-32714','题阳山顾炼师草堂','李頻','quantangshi','','卷33','若到当时上升处，长生何事后无人。
前峰自去种松子，坐见年来取茯神。','',''),('quantangshi-32715','闻金吾妓唱梁州','李頻','quantangshi','','卷33','闻君一曲古梁州，惊起黄云塞上愁。
秦女树前花正发，北风吹落满城秋。','',''),('quantangshi-32716','游蜀回简友人','李頻','quantangshi','','卷33','别来十二月，去到漏天边。
不是因逢闰，还应是隔年。','',''),('quantangshi-32717','赠泾州王侍御','李頻','quantangshi','','卷33','一旦天书下紫微，三年旌斾陇云飞。
塞门无事春空到，边草青青战马肥。','',''),('quantangshi-32718','夏日宿秘书姚监宅','李頻','quantangshi','','卷33','贵宅多嘉树，先秋有好风。
情闲离阙下，梦野在山中。
露色浮寒瓦，萤光堕暗丛。
听吟丽句尽，河汉任西东。','',''),('quantangshi-32719','过嵩阴隐者','李頻','quantangshi','','卷33','当门看少室，倚杖复披衣。
每日醒还醉，无人是与非。
架书抽读乱，庭果摘尝稀。
独有江南客，思家未得归。','',''),('quantangshi-32720','留别山家','李頻','quantangshi','','卷33','闲门不易求，半月在林丘。
已与山水别，难为花木留。
孤怀归静夜，远会隔高秋。
莫道无言去，冥心在重游。','',''),('quantangshi-32721','送人游吴','李頻','quantangshi','','卷33','楚田开雪后，草色与君看。
积水浮春气，深山滞雨寒。
毗陵孤月出，建业一钟残。
为把乡书去，因收别泪难。','',''),('quantangshi-32722','东渭桥晚眺','李頻','quantangshi','','卷33','秦地有吴洲，千樯渭曲头。
人当返照立，水彻故乡流。
落第春难过，穷途日易愁。
谁知桥上思，万里在江楼。','',''),('quantangshi-32723','送延陵韦少府','李頻','quantangshi','','卷33','延陵称贵邑，季子有高踪。
古迹传多代，仙山管几峰。
微泉声小雨，异木色深冬。
去毕三年秩，新诗箧不容。','',''),('quantangshi-32724','淮南送友人归沧州','李頻','quantangshi','','卷33','风色忽西转，坐为千里分。
高帆背楚落，寒日逆淮曛。
断烧缘乔木，盘雕隐片云。
乡关百战地，归去始休军。','',''),('quantangshi-32725','夏日题盩厔友人书斋','李頻','quantangshi','','卷33','修竹齐高树，书斋竹树中。
四时无夏气，三伏有秋风。
黑处巢幽鸟，阴来呌候虫。
牕西太白雪，万仞在遥空。','',''),('quantangshi-32726','寻山','李頻','quantangshi','','卷33','一迳入双崖，初疑有几家。
行穷人不见，坐久日空斜。
石上生灵草，泉中落异花。
终须结茅屋，向此学餐霞。','',''),('quantangshi-32727','送元遂上人归钱唐','李頻','quantangshi','','卷33','白衣游帝乡，已得事空王。
却返湖山寺，高禅水月房。
雨中过岳黑，秋后宿船凉。
回顾秦人语，他生会别方。','',''),('quantangshi-32728','贻友人喻坦之','李頻','quantangshi','','卷33','从容心自切，饮水胜衔杯。
共在山中长，相随阙下来。
修身空有道，取事各无媒。
不信升平代，终遗草泽才。','',''),('quantangshi-32729','送友人往振武','李頻','quantangshi','','卷33','风沙遥见说，道路替君愁。
碛夜星垂地，云明火上楼。
征鸿辞塞雪，战马识边秋。
不共将军语，何因有去留。','',''),('quantangshi-32730','赋得长城斑竹杖','李頻','quantangshi','','卷33','秦兴版筑时，翦伐不知谁。
异代余根在，幽人得手持。
细看生古意，闲倚动边思。
莫作鸠形并，空将鹤髪期。','',''),('quantangshi-32731','送德清喻明府','李頻','quantangshi','','卷33','棹返霅溪云，仍参旧使君。
州传多古迹，县记是新文。
水栅横舟闭，湖田立木分。
但如诗思苦，为政即超羣。','',''),('quantangshi-32732','送薛能少府任盩厔','李頻','quantangshi','','卷33','不才甘下第，君子蹇何重。
相送昆明岸，同看太白峰。
数瓢留顷刻，残照迫从容。
好去烟霞县，仙人有旧踪。','',''),('quantangshi-32733','送许寿下第归东山','李頻','quantangshi','','卷33','吾君设礼闱，谁合学忘机。
却是高人起，难为下第归。
出关心纵野，避世事终稀。
莫更今秋夕，相思望少微。','',''),('quantangshi-32734','冬夜酬范秘书','李頻','quantangshi','','卷33','九衢行一匝，不敢入他门。
累日无余事，通宵得至言。
命嗟清世蹇，春觉闰冬暄。
翻覆吟佳句，何酬国士恩。','',''),('quantangshi-32735','送陆肱尉江夏','李頻','quantangshi','','卷33','如何执简去，便作挂帆期。
泽国三春早，江天落日迟。
县人齐候处，洲鸟欲飞时。
免褐方三十，青云岂白髭。','',''),('quantangshi-32736','汉上送人西归','李頻','quantangshi','','卷33','几作西归梦，因为怆别心。
野衔天去尽，山夹汉来深。
叠浪翻残照，高帆引片阴。
空留相赠句，毕我白头吟。','',''),('quantangshi-32737','蜀中逢友人','李頻','quantangshi','','卷33','自古有行役，谁人免别家。
相欢犹陌上，一醉任天涯。
积叠山藏蜀，潺湲水遶巴。
他年复何处，共说海棠花。','',''),('quantangshi-32738','寄范评事','李頻','quantangshi','','卷33','行坐不相遗，辕门载笔时。
雅知难更遇，旧分合长思。
梦即重寻熟，书常转达迟。
山斋终拟到，何日遂心期。','',''),('quantangshi-32739','南游过湘汉即事寄友人','李頻','quantangshi','','卷33','南去远駈逐，三湘五月行。
巴山雪水下，楚泽火云生。
向野聊中饭，乘凉探暮程。
离怀不可说，已迫峡猿声。','',''),('quantangshi-32740','送许浑侍御赴润州','李頻','quantangshi','','卷33','家山近石头，遂意恣东游。
祖席离乌府，归帆转蜃楼。
阴氛出海散，落月向潮流。
别有为霖日，孤云未自由。','',''),('quantangshi-32741','喜友人厉图南及第','李頻','quantangshi','','卷33','相忧过己切，相贺似身荣。
心达无前后，神交共死生。
承家吾子事，登第世人情。
未有通儒术，明时道不行。','',''),('quantangshi-32742','送友人下第归越','李頻','quantangshi','','卷33','归意随流水，江湖共在东。
山阴何处去，草际片帆通。
雨色春愁里，潮声晓梦中。
虽为半年客，便是往来鸿。','',''),('quantangshi-32743','寄友人','李頻','quantangshi','','卷33','一别一相见，须臾老此生。
客衣寒后薄，山思夜深清。
诗近吟何句，髭新白几茎。
路岐如昨日，来往梦分明。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32744','送友人下第归宛陵','李頻','quantangshi','','卷33','天涯长恋亲，阙下独伤春。
拟住还求己，须归不为身。
临岐仍犯雪，挂席始离尘。
共泣东风别，同为沧海人。','',''),('quantangshi-32745','秋夜对月寄鳯翔范书记','李頻','quantangshi','','卷33','月过秋霖后，光应夜夜清。
一回相忆起，几度独吟行。
河汉东西直，山川远近明。
寸心遥往处，新有雁来声。','',''),('quantangshi-32746','送孙明秀才往潘州访韦卿','李頻','quantangshi','','卷33','北鸟飞不到，北人今去游。
天涯浮瘴水，岭外问潘州。
草木春冬茂，猿猱日夜愁。
定知迁客泪，应只对君流。','',''),('quantangshi-32747','八月十五夜对月','李頻','quantangshi','','卷33','阴盛此宵中，多为雨与风。
坐无云雨至，看与雪霜同。
抱湿离遥海，倾寒向逈空。
年年不可值，还似命难通。','',''),('quantangshi-32748','及第后归','李頻','quantangshi','','卷33','家临浙水傍，岸对买臣乡。
纵棹随归鸟，乘潮向夕阳。
苦吟身得雪，甘意鬓成霜。
况此年犹少，酬知足自强。','',''),('quantangshi-32749','过巫峡','李頻','quantangshi','','卷33','拥棹向惊湍，巫峰直上看。
削成从水底，耸出在云端。
暮雨晴时少，啼猿渴下难。
一闻神女去，风竹扫空坛。','',''),('quantangshi-32750','送友人往太原','李頻','quantangshi','','卷33','离亭聊把酒，此路彻边头。
草白雁来尽，时清人去游。
汾河流晋地，塞雪满并州。
别后相思夜，空看北斗愁。','',''),('quantangshi-32751','旅怀','李頻','quantangshi','','卷33','万里共心论，徒言吾道存。
奉亲无别业，谒帝有何门。
水宿惊涛浦，山行落叶村。
长安长梦去，欹枕即闻猿。','',''),('quantangshi-32752','送裴御史赴湖南','李頻','quantangshi','','卷33','关门鸟道中，飞传复乘骢。
暮雪离秦甸，春云入楚宫。
平芜天共阔，积水地多空。
使府悬帆去，能消几日风。','',''),('quantangshi-32753','送姚郜先辈赴汝州辟','李頻','quantangshi','','卷33','行李事寒天，东来聘礼全。
州当定鼎处，人去偃戈年。
雷雨依嵩岭，桑麻接楚田。
遥知清夜作，不是借戎篇。','',''),('quantangshi-32754','初离黔中泊江上','李頻','quantangshi','','卷33','去去把青桂，平生心不违。
更蒙莲府辟，兼脱布衣归。
霁岳明残雪，清波漾落晖。
无穷幽鸟戏，时向棹前飞。','',''),('quantangshi-32755','黔中酬同院韦判官','李頻','quantangshi','','卷33','平生同所为，相遇偶然迟。
各着青袍后，无归白社期。
江流来绝域，府地管诸夷。
圣代都无事，从公且赋诗。','',''),('quantangshi-32756','和范秘书襄阳旧游','李頻','quantangshi','','卷33','听话扬帆兴，初从岘首还。
高吟入白浪，遥坐看青山。
枯木猿啼爽，寒汀鹤步闲。
秋来关去梦，几夜度商颜。','',''),('quantangshi-32757','秋夜山中思归送友人','李頻','quantangshi','','卷33','萧条对秋色，相忆在云泉。
木落病身起，潮平归思悬。
凉钟山顶寺，暝火渡头船。
此地非吾土，淹留又一年。','',''),('quantangshi-32758','自黔中东归旅次淮上','李頻','quantangshi','','卷33','行旅本同愁，黔吴复阻修。
半年方中路，穷节到孤舟。
夕霭垂阴野，晨光动积流。
家山一夜梦，便是昔年游。','',''),('quantangshi-32759','江夏春感旧','李頻','quantangshi','','卷33','东风出海门，处处动林园。
泽国雪霜少，沙汀花木繁。
暖鱼依水浅，晴雁入空翻。
何处阳和力，生萍不驻根。','',''),('quantangshi-32760','眉州别李使君','李頻','quantangshi','','卷33','回首雪峰前，朱门心杳然。
离人自呜咽，流水莫潺湲。
毒草通蛮徼，秋林近漏天。
一生从此去，五字有谁怜。','',''),('quantangshi-32761','送许棠及第归宣州','李頻','quantangshi','','卷33','高科终自致，志业信如神。
待得逢公道，由来合贵身。
秋归方觉好，旧梦始知真。
更想青山宅，谁为后主人。','',''),('quantangshi-32762','黔中罢职将泛江东','李頻','quantangshi','','卷33','黔中初罢职，薄俸亦无残。
举目乡关远，携家旅食难。
野梅将雪竞，江月与沙寒。
两鬓愁应白，何劳把镜看。','',''),('quantangshi-32763','长安书事寄所知','李頻','quantangshi','','卷33','帝里本无名，端居有道情。
睡魂春梦断，书兴晚窗明。
老拟归何处，闲应过此生。
江湖终一日，拜别便东行。','',''),('quantangshi-32764','酬姚覃','李頻','quantangshi','','卷33','不见又相招，何曾诉寂寥。
醉眠春草长，吟坐夜灯销。
泪堕思山切，身归转路遥。
年年送别处，杨柳少垂条。','',''),('quantangshi-32765','春日鄜州赠裴居言','李頻','quantangshi','','卷33','虽将身佐幕，出入似闲居。
草色长相待，山情信不疎。
灯前春睡足，酒后夜寒余。
笔砚时时近，终非署簿书。','',''),('quantangshi-32766','送于生入蜀','李頻','quantangshi','','卷33','家吴闻入蜀，道路颇乖离。
一第何多难，都城可少知。
江山非久适，命数未终奇。
况又将冤抱，经春杜魄随。','',''),('quantangshi-32767','送许棠归泾县作尉','李頻','quantangshi','','卷33','青桂复青袍，一归荣一高。
县人齐下拜，邑宰共分曹。
遶郭看秧插，寻街听茧缫。
封侯万里者，燕颔乃徒劳。','',''),('quantangshi-32768','友人话别','李頻','quantangshi','','卷33','论交虽不蚤，话别且相亲。
除却栖禅客，谁非南陌人。
半生都返性，终老拟安贫。
愿入白云社，高眠自致身。','',''),('quantangshi-32769','山居','李頻','quantangshi','','卷33','欲出穷吾道，东西自未能。
卷书唯对鹤，开画独留僧。
落叶和云扫，秋山共月登。
何年石上水，夜夜滴高层。','',''),('quantangshi-32770','寄范郎中','李頻','quantangshi','','卷33','蔾杖山中出，吟诗对范家。
相知从海峤，寄食向京华。
名宦成何报，清眸未纵赊。
临邛梦来往，雨雪满襃斜。','',''),('quantangshi-32771','书怀','李頻','quantangshi','','卷33','宦途从不问，身事觉无差。
华髪初生女，沧洲未有家。
却闲思洞穴，终老旷桑麻。
别访栖禅侣，相期语劫沙。','',''),('quantangshi-32772','越中行','李頻','quantangshi','','卷33','越国临沧海，芳洲复暮晴。
湖通诸浦白，日隐乱峰明。
野宿多无定，闲游免有情。
天台闻不远，终到石桥行。','',''),('quantangshi-32773','春日南游寄浙东许同年','李頻','quantangshi','','卷33','孤帆处处宿，不问是谁家。
南国平芜远，东风细雨斜。
旅怀多寄酒，寒意欲留花。
更想前途去，茫茫沧海涯。','',''),('quantangshi-32774','明州江亭夜别段秀才','李頻','quantangshi','','卷33','离亭向水开，时候复蒸梅。
霹雳灯烛灭，蒹葭风雨来。
京关虽共语，海峤不同回。
莫为莼鲈美，天涯滞尔才。','',''),('quantangshi-32775','临岐留别相知','李頻','quantangshi','','卷33','百岁竟何事，一身长远游。
行行将近老，处处不离愁。
世路多相取，权门不自投。
难为此时别，欲别愿人留。','',''),('quantangshi-32776','鄂渚湖上即事','李頻','quantangshi','','卷33','杜门聊自适，湖水在窗间。
纵得沧洲去，无过白日闲。
多慵空好道，少贱早凋颜。
独有东山月，依依自往还。','',''),('quantangshi-32777','辞夏口崔尚书','李頻','quantangshi','','卷33','一饭仍难受，依仁况一年。
终期身可报，不拟骨空镌。
城晚风高角，江春浪起船。
同来栖止地，独去塞鸿前。','',''),('quantangshi-32778','秦原早望','李頻','quantangshi','','卷33','一忝乡书荐，长安未得回。
年光逐渭水，春色上秦台。
燕掠平芜去，人冲细雨来。
东风生故里，又过几花开。','',''),('quantangshi-32779','送友人之扬州','李頻','quantangshi','','卷33','一别长安后，晨征便信鸡。
河声入峡急，地势出关低。
绿树丛垓下，青芜阔楚西。
路长知不恶，随处得诗题。','',''),('quantangshi-32780','过四皓庙','李頻','quantangshi','','卷33','东西南北人，高迹自相亲。
天下已归汉，山中犹避秦。
龙楼曾作客，鹤氅不为臣。
独有千年后，青青庙木春。','',''),('quantangshi-32781','陕下怀归','李頻','quantangshi','','卷33','故园何处在，零落五湖东。
日暮无来客，天寒有去鸿。
大河冰彻塞，高岳雪连空。
独夜悬归思，迢迢永漏中。','',''),('quantangshi-32782','送徐处士归江南','李頻','quantangshi','','卷33','行行野雪薄，寒气日通春。
故国又芳草，沧江终白身。
游归花落满，睡起鸟啼新。
莫惜闲书札，西来问旅人。','',''),('quantangshi-32783','鄜州留别王从事','李頻','quantangshi','','卷33','相识未十日，相知如十年。
从来易离别，此去忽留连。
路险行冲雨，山高度隔天。
难终清夜坐，更听说安边。','',''),('quantangshi-32784','长安夜怀','李頻','quantangshi','','卷33','匹马西游日，从吴又转荆。
风雷几夜坐，山水半年行。
梦永秋灯灭，吟余晓露明。
良时不我与，白发向秦生。','',''),('quantangshi-32785','冬夜山中寻友','李頻','quantangshi','','卷33','何人山雪夜，相访不相思。
若得长闲日，应无暂到时。
叶寒凋欲尽，泉冻落还迟。
即此天明去，重来未有期。','',''),('quantangshi-32786','送刘山人归洞庭','李頻','quantangshi','','卷33','君逐云山去，人间又绝踪。
半湖乘早月，中路入疎钟。
秋尽草虫急，夜深山雨重。
平生心未已，岂得更相从。','',''),('quantangshi-32787','古意','李頻','quantangshi','','卷33','白马游何处，青楼日正长。
凤箫抛旧曲，鸾镜嬾新妆。
玄鸟深巢静，飞花入户香。
虽非窦滔妇，锦字已成章。','',''),('quantangshi-32788','避暑','李頻','quantangshi','','卷33','当暑忆归林，陶家借柳阴。
蝉从初伏噪，客向晚凉吟。
白日欺玄鬓，沧江负素心。
神仙倘有术，引我出幽岑。','',''),('quantangshi-32789','送吴秘书归杭州','李頻','quantangshi','','卷33','为客得从容，官清料复重。
海崖归有业，天目近何峰。
是处通春棹，无村不夜舂。
马卿夸贵达，还说返临邛。','',''),('quantangshi-32790','中秋对月','李頻','quantangshi','','卷33','秋分一夜停，阴魄最晶荧。
好是生沧海，徐看历杳冥。
层空疑洗色，万怪想潜形。
他夕无相类，晨鸡不可听。','',''),('quantangshi-32791','八月上峡','李頻','quantangshi','','卷33','万里巴江水，秋来满峡流。
乱山无陆路，行客在孤舟。
汹汹滩声急，冥冥树色愁。
免为三不吊，已白一生头。','',''),('quantangshi-32792','送狄明府赴九江','李頻','quantangshi','','卷33','字人修祖德，清白定闻传。
匹马从秦去，孤帆入楚悬。
关中寒食雨，湖上暑衣天。
四考兼重请，相知住几年。','',''),('quantangshi-32793','陕下投姚谏议','李頻','quantangshi','','卷33','旧业在东鄙，西游从楚荆。
风雷几夜坐，山水半年行。
梦永秋灯灭，吟孤晓露明。
前心若不遂，有耻却归耕。','',''),('quantangshi-32794','关东逢薛能','李頻','quantangshi','','卷33','何处不相思，相逢还有时。
交心如到老，会面未为迟。
苦学缘明代，劳生欲白髭。
唯君一度别，便似见无期。','',''),('quantangshi-32795','富春赠孙璐','李頻','quantangshi','','卷33','天柱与天目，曾栖绝顶房。
青云求禄晚，白日坐家长。
井气通潮信，牕风引海凉。
平生诗称在，老达亦何妨。','',''),('quantangshi-32796','送友人游蜀','李頻','quantangshi','','卷33','东堂虽不捷，西去复何愁。
蜀马知归路，巴山似旧游。
星临劒阁动，花落锦江流。
鼓吹青林下，时闻祭武侯。','',''),('quantangshi-32797','夏日盩厔郊居寄姚少府','李頻','quantangshi','','卷33','古木有清阴，寒泉有下深。
蝉从初伏噪，客向晚凉吟。
白日欺玄鬓，沧江负素心。
甚思中夜话，何路许相寻。','',''),('quantangshi-32798','送胡休处士归湘江','李頻','quantangshi','','卷33','见说湘江切，长愁有去时。
江湖秋涉远，雷雨夜眠迟。
旧业多归兴，空山尽老期。
天寒一瓢酒，落日醉留谁。','',''),('quantangshi-32799','峡州送清彻上人归浙西','李頻','quantangshi','','卷33','风涛几千里，归路半乘舟。
此地难相遇，何人更共游。
坐经嵩顶夏，行值洛阳秋。
到寺安禅夕，江云满石楼。','',''),('quantangshi-32800','送僧入天台','李頻','quantangshi','','卷33','一锡随缘赴，天台又去登。
长亭旧别路，落日独行僧。
夜烧山何处，秋帆浪几层。
他时授巾拂，莫为老无能。','',''),('quantangshi-32801','回山后寄范酇先辈','李頻','quantangshi','','卷33','高楼会月夜，北雁向南分。
留住经春雪，辞来见夏云。
遥空江不极，绝顶日难曛。
一与山僧坐，无因得议文。','',''),('quantangshi-32802','长安送友人东归','李頻','quantangshi','','卷33','白社思归处，青门见去人。
乡遥茂苑树，路入广陵尘。
海日潮浮晓，湖山雪露春。
犹期来帝里，未是得闲人。','',''),('quantangshi-32803','深秋过源宗上人房','李頻','quantangshi','','卷33','到日值摇落，相留山舍空。
微寒生夜半，积雨向秋终。
度讲多来雁，经禅少候虫。
方从听话后，不省在愁中。','',''),('quantangshi-32804','秋日登山阁','李頻','quantangshi','','卷33','苍苍山阁晚，杳杳隙尘秋。
偶上多时立，翻成尽日愁。
草平连邑动，河满逐江流。
下视穷边路，行人在陇头。','',''),('quantangshi-32805','秋宿慈恩寺遂上人院','李頻','quantangshi','','卷33','满阁终南色，清宵独倚栏。
风高斜汉动，叶下曲江寒。
帝里求名老，空门见性难。
吾师无一事，不似在长安。','',''),('quantangshi-32806','题栖霞寺庆上人院','李頻','quantangshi','','卷33','居与鸟巢邻，日将巢鸟亲。
多生从此性，久集得无身。
树老风终夜，山寒雪见春。
不知诸祖后，传印是何人。','',''),('quantangshi-32807','送友人入蜀','李頻','quantangshi','','卷33','天际蜀门开，西看举别杯。
何人不异礼，上客自怀才。
夜涧青林发，秋江渌水来。
临邛行乐处，莫到白头回。','',''),('quantangshi-32808','赠同官苏明府','李頻','quantangshi','','卷33','山中畿内邑，别觉大夫清。
簿领分王事，官资寄野情。
闲斋无狱讼，隐几向泉声。
从此朝天路，门前是去程。','',''),('quantangshi-32809','送厉图南往荆州觐伯','李頻','quantangshi','','卷33','云水入荆湘，古来鱼鸟乡。
故关重隔远，春日独行长。
山溜含清韵，江雷吐夜光。
郡中词客会，游子更升堂。','',''),('quantangshi-32810','山中夜坐','李頻','quantangshi','','卷33','归家来几夜，倏忽觉秋残。
月满方塘白，风依老树寒。
戏鱼重跃定，惊鸟却栖难。
为有门前路，吾生不得安。','',''),('quantangshi-32811','送台州唐兴陈明府','李頻','quantangshi','','卷33','见说海西隅，山川与俗殊。
宦游如不到，仙分即应无。
瀑布当公署，天台是县图。
遥知为吏去，有术字惸孤。','',''),('quantangshi-32812','夏日过友人檀溪别业','李頻','quantangshi','','卷33','暑天宜野宅，林籁爽泠泠。
沙月邀开户，岩风助扫庭。
鹭栖依绿筱，鱼跃出清萍。
客抱方如醉，因来得暂醒。','',''),('quantangshi-32813','自江上入关','李頻','quantangshi','','卷33','尽室寄沧洲，孤帆独溯流。
天涯心似梦，江上雨兼秋。
文字为人弃，田园被债收。','',''),('quantangshi-32814','冬夜和范秘书宿秘省中作','李頻','quantangshi','','卷33','每日得闲吟，清曹阙下深。
因知遥夜坐，别有远山心。
芸细书中气，松疎雪后阴。
归时高兴足，还复插朝簪。','',''),('quantangshi-32815','送友人游太原','李頻','quantangshi','','卷33','孤帆几日悬，楚客思飘然。
水宿南湖夜，山离旧国年。
秋风高送雁，寒雨入停蝉。
此去勤书札，时常中路传。','',''),('quantangshi-32816','江上居寄山中客','李頻','quantangshi','','卷33','山后与山前，相思隔呌猿。
残云收树末，返照落江源。
苦雨秋涛涨，狂风野火翻。
朝来卖药客，遇我达无言。','',''),('quantangshi-32817','送张郎中赴睦州','李頻','quantangshi','','卷33','青山复渌水，想入富春西。
夹岸清猿去，中流白日低。
美兼华省出，荣共故乡齐。
贱子遥攀送，归心逐马蹄。','',''),('quantangshi-32818','送鄂渚韦尚书赴镇','李頻','quantangshi','','卷33','夏口本吴头，重城据上游。
戈船转江汉，风月宿汀洲。
执宪倾民望，衔恩赴主忧。
谁知旧寮属，攀饯泪仍流。','',''),('quantangshi-32819','送崔侍御书记赴山北座主尚书招辟','李頻','quantangshi','','卷33','书记向丘门，旌幢夹谷尊。
从来游幕意，此去并酬恩。
雁呌嫌冰合，骢嘶喜雪繁。
同为入室士，不觉别销魂。','',''),('quantangshi-32820','入朝遇雪','李頻','quantangshi','','卷33','霜鬓持霜简，朝天向雪天。
玉阶初辨色，琼树乍相鲜。
密翳空难曙，盈徴瑞不愆。
谁为洛阳客，是日更高眠。','',''),('quantangshi-32821','勉力','李頻','quantangshi','','卷33','日月不并照，升沈俱有时。
自媒徒欲速，孤立却宜迟。
尽力唯求己，公心任遇谁。
人间不得意，半是鬓先衰。','',''),('quantangshi-32822','郊居寄友人','李頻','quantangshi','','卷33','林色树还曛，何时得见君。
独居度永日，相去远浮云。
故疾随秋至，离怀觉夜分。
蛩声非自苦，偏是旅人闻。','',''),('quantangshi-32823','送陆肱归吴兴','李頻','quantangshi','','卷33','雪后江上去，风光故国新。
清浑天气晓，绿动浪花春。
劝酒提壶鸟，乘舟震泽人。
谁知沧海月，取桂却来秦。','',''),('quantangshi-32824','暮秋重过山僧院','李頻','quantangshi','','卷33','却接良宵坐，明河几转流。
安禅逢小暑，抱疾入高秋。
静室闻玄理，深山可白头。
朝朝献林果，亦欲学猕猴。','',''),('quantangshi-32825','送新安少府','李頻','quantangshi','','卷33','南浮虽六月，风水已秋凉。
日乱看江树，身飞逐楚樯。
后期谁可定，临别语空长。
远宦须清苦，幽兰贵独芳。','',''),('quantangshi-32826','送人归吴','李頻','quantangshi','','卷33','何人不归去，君去是闲人。
帝里求相识，山家即近邻。
交情吾道可，离思柳条新。
未饮青门酒，先如醉梦身。','',''),('quantangshi-32827','送姚评事','李頻','quantangshi','','卷33','儒服从戎去，须知胜事全。
使君开幕日，天子偃戈年。
风雨依嵩岭，桑麻接楚田。
新诗随过客，旋满洛阳传。','',''),('quantangshi-32828','题栖云寺立上人院','李頻','quantangshi','','卷33','是法从生有，修持历劫尘。
独居岩下室，长似定中身。
树老风终夜，山寒雪见春。
不知诸祖后，传印是何人。','',''),('quantangshi-32829','黔中罢职过峡州题田使君北楼','李頻','quantangshi','','卷33','巴中初去日，已遇使君留。
及得寻东道，还陪上北楼。
江冲巫峡出，樯过洛宫收。
好是从戎罢，看山觉自由。','',''),('quantangshi-32830','江上送从兄羣玉校书东游','李頻','quantangshi','','卷33','逍遥蓬阁吏，才子复诗流。
坟籍因穷览，江湖却纵游。
眠波听戍鼓，饭浦约鱼舟。
处处迎高密，先应扫郡楼。','',''),('quantangshi-32831','宛陵东峰亭与友人话别','李頻','quantangshi','','卷33','坐举天涯目，停杯语日晡。
修篁齐逈槛，列岫限平芜。
乱水通三楚，归帆挂五湖。','',''),('quantangshi-32832','华山寻隐者','李頻','quantangshi','','卷33','自入华山居，关东相见疎。
瓢中谁寄酒，叶上我留书。
巢鸟寒栖尽，潭泉暮冻余。
长闻得药力，此说又何如。','',''),('quantangshi-32833','题荐福寺僧栖白上人院','李頻','quantangshi','','卷33','空门有才子，得道亦吟诗。
内殿频徴入，孤峰久作期。
高名何代比，密行几生持。
长爱乔松院，清凉坐夏时。','',''),('quantangshi-32834','游四明山刘樊二真人祠题山下孙氏居','李頻','quantangshi','','卷33','久在仙坛下，全家是地仙。
池塘来乳洞，禾黍接芝田。
起看青山足，还倾白酒眠。
不知尘世事，双鬓逐流年。','',''),('quantangshi-32835','和太学赵鸿博士归蔡中','李頻','quantangshi','','卷33','得禄从高第，还乡见后生。
田园休问主，词赋已垂名。
扫壁前题出，开窗旧景清。
遥知贤太守，致席日邀迎。','',''),('quantangshi-32836','送寿昌曹明府','李頻','quantangshi','','卷33','惠人须宰邑，为政贵通经。
却用清琴理，犹嫌薄俗听。
涨江晴渐渌，春峤烧还青。
若宿严陵濑，谁当是客星。','',''),('quantangshi-32837','哭贾岛','李頻','quantangshi','','卷33','秦楼吟苦夜，南望只悲君。
一宦终遐徼，千山隔旅坟。
恨声流蜀魄，冤气入湘云。
无限风骚句，时来日夜闻。','',''),('quantangshi-32838','送薛能赴镇徐方','李頻','quantangshi','','卷33','列土人间盛，彭门属九州。
山河天设险，礼乐牧分忧。
皎日为明信，清风占早秋。
虽同郤縠举，郤縠不封侯。','',''),('quantangshi-32839','送鳯翔范书记','李頻','quantangshi','','卷33','西京无暑气，夏景似清秋。
天府来相辟，高人去自由。
江山通蜀国，日月近神州。
若共将军语，河兰地未收。','',''),('quantangshi-32840','岐山逢陕下故人','李頻','quantangshi','','卷33','三秦一会面，二陕久分携。
共忆黄河北，相留白日西。
寄来书少达，别后梦多迷。
早晚期于此，看花听鸟啼。','',''),('quantangshi-32841','送友人陆肱往太原','李頻','quantangshi','','卷33','并州非故国，君去复寻谁。
猃狁方为寇，嫖姚正用师。
戍烟来自号，边雪下无时。
更想经绵上，应逢禁火期。','',''),('quantangshi-32842','赠李将军','李頻','quantangshi','','卷33','吾宗偏好武，汉代将家流。
走马辞中禁，屯军向渭州。
天心待破虏，阵面许封侯。
却得河源水，方应洗国讐。','',''),('quantangshi-32843','送友人喻坦之归睦州','李頻','quantangshi','','卷33','归心常共知，归路不相随。
彼此无依倚，东西又别离。
山花含雨湿，江树近潮欹。
莫恋渔樵兴，生涯各有为。','',''),('quantangshi-32844','寻华阳隐者','李頻','quantangshi','','卷33','闲却白云居，行踪出去初。
窗中聊取笔，架上独留书。
日背林光冷，潭澄岳影虚。
长闻得药力，此说复何如。','',''),('quantangshi-32845','长安即事','李頻','quantangshi','','卷33','岂得有书名，徒为老帝京。
关中秋气早，雨后夜凉生。
沧海身终泛，青门梦已行。
秦人纵相识，多少别离情。','',''),('quantangshi-32846','送友人游塞北','李頻','quantangshi','','卷33','朔野正秋风，前程见碛鸿。
日西身独远，山转路无穷。
树隔高关断，沙连大漠空。
君看河外将，早晚拟平戎。','',''),('quantangshi-32847','陕府上姚中丞','李頻','quantangshi','','卷33','关东领藩镇，[阙]下授旌旄。
觅句秋吟苦，酬恩夜坐劳。
天开吹角出，木落上楼高。
闲话钱塘郡，半年听海潮。','',''),('quantangshi-32848','送供奉喻炼师归天目山','李頻','quantangshi','','卷33','承恩虽内殿，得道本深山。
举世相看老，孤峰独自还。
溪来青壁里，路在白云间。
绝顶无人住，双峰是旧关。','',''),('quantangshi-32849','之任建安渌溪亭偶作二首 一','李頻','quantangshi','','卷33','入境当春务，农蚕事正殷。
逢溪难饮马，度岭更劳人。
想取烝黎泰，无过赋歛均。
不知成政后，谁是得为邻。','',''),('quantangshi-32850','之任建安渌溪亭偶作二首 二','李頻','quantangshi','','卷33','维舟绿溪岸，绕郡白云峰。
将幕连山起，人家向水重。
短才无独见，长策未相逢。
所幸分尧理，烝民悉可封。','',''),('quantangshi-32851','送侯郎中任新定二首 一','李頻','quantangshi','','卷33','为郎非白头，作牧授沧洲。
江界乘潮入，山川值胜游。
暑气随转扇，凉月傍开楼。
便欲归田里，抛官逐隐侯。','',''),('quantangshi-32852','送侯郎中任新定二首 二','李頻','quantangshi','','卷33','罢郎东出守，半路得浮舟。
大斾行当夏，桐江到未秋。
云闲分岛寺，涛静见沙鸥。
谁伴临清景，吟诗上郡楼。','',''),('quantangshi-32853','送太学吴康仁及第南归','李頻','quantangshi','','卷33','因为太学选，志业彻春闱。
首领诸生出，先登上第归。
一荣犹未已，具庆且应稀。
纵马行青草，临岐脱白衣。
家遥楚国寄，帆对汉山飞。
知己盈华省，看君再发机。','',''),('quantangshi-32854','陕州题河上亭','李頻','quantangshi','','卷33','岸拥洪流急，亭开清兴长。
当轩河草晚，入坐水风凉。
独鸟惊来客，孤云触去樯。
秋声和远雨，暮色带微阳。
浪静澄牕影，沙阴发簟光。
逍遥每尽日，谁识爱沧浪。','',''),('quantangshi-32855','留题姚氏山斋','李頻','quantangshi','','卷33','未厌栖林趣，犹怀济世才。
闲眠知道在，高步会时来。
露滴从添砚，蝉吟便送杯。
乱书离缥帙，迸笋出苔莓。
异果因僧摘，幽窗为燕开。
春游何处尽，欲别几迟回。','',''),('quantangshi-32856','长安书怀投知己','李頻','quantangshi','','卷33','所学近雕虫，知难谒至公。
徒随众人后，拟老一生中。
间岁家书到，经荒世业空。
心悬沧海断，梦与白云通。
玉漏声连北，银河气极东。
关门迢递月，禁苑寂寥鸿。
地广身难束，时平道独穷。
萧条苔长雨，淅沥叶危风。
久愧干朝客，多惭别钓翁。
因依非不忝，延荐况曾蒙。
与善应无替，垂恩本有终。
霜天摇落日，莫使逐孤蓬。','',''),('quantangshi-32857','送姚侍御充渭北掌书记','李頻','quantangshi','','卷33','北境烽烟急，南山战伐频。
抚绥初易帅，参画尽须人。
书记才偏称，朝廷意更亲。
绣衣行李日，绮陌别离尘。
报国将临虏，之藩不离秦。
豸冠严在首，雄笔健随身。
饮马河声暮，休兵塞色春。
败亡仍暴骨，冤哭可伤神。
上策何当用，边情此是真。
雕阴曾久客，拜送欲霑巾。','',''),('quantangshi-32858','长安书情投知己','李頻','quantangshi','','卷33','陕服因诗句，从容已半年。
一从归阙下，罕得到门前。
每候朝轩出，常看列宿悬。
重投期见奖，数首果蒙传。
转觉功宜倍，兼令住更坚。
都忘春暂醉，少省夜曾眠。
烦暑灯谁读，孤云业自专。
精华搜未竭，骚雅琢须全。
此事勤虽过，他谋拙莫先。
槐街劳白日，桂路在青天。
取第殊无序，还乡可有缘。
旅情长越鸟，秋思几秦蝉。
月色千楼满，砧声万井连。
江山阻迢递，时节暗推迁。
道即穷通守，才应始末怜。
书绅相戒语，藏箧赠行篇。
致主当齐圣，为郎本是仙。
人心期际会，凤翼许迁延。
毕竟良图在，何妨逸性便。
幽斋中寝觉，珍木正阴圆。
隐几闲瞻夜，临云兴渺然。
五陵供丽景，六义动花牋。
倘与潜生翼，宁非助化权。
免教垂素髪，归种海隅田。','',''),('quantangshi-32859','府试丹浦非乐战','李頻','quantangshi','','卷33','自古为君道，垂衣致理难。
怀仁须去杀，用武即胜残。
毒帜诛方及，兵临衅可观。
居来彭蠡固，战罢洞庭宽。
雪国知天远，霜林是血丹。
吾皇则尧典，薄伐至桑亁。','',''),('quantangshi-32860','府试风雨闻鸡','李頻','quantangshi','','卷33','不为风雨变，鸡德一何贞。
在暗长先觉，临晨即自鸣。
阴霾方见信，顷刻讵移声。
向晦如相警，知时似独清。
萧萧和断漏，喔喔报重城。
欲识诗人兴，中含君子情。','',''),('quantangshi-32861','府试观兰亭图','李頻','quantangshi','','卷33','往会人何处，遗踪事可观。
林亭今日在，草木古春残。
笔想吟中驻，杯疑饮后干。
向青穿峻岭，当白认回湍。
月影窗间夜，湖光枕上寒。
不知诗酒客，谁更慕前欢。','',''),('quantangshi-32862','府试老人星见','李頻','quantangshi','','卷33','良宵出户庭，极目向青冥。
海内逢康日，天边见寿星。
临空遥的的，竟晓独荧荧。
春后先依景，秋来忽近丁。
垂休临有道，作瑞掩前经。
岂比周王梦，徒言得九龄。','',''),('quantangshi-32863','省试振鹭','李頻','quantangshi','','卷33','有鸟生江浦，霜华作羽翰。
君臣将比洁，朝野共相欢。
月影林梢下，冰光水际残。
翻飞时共乐，饮啄道皆安。
逈翥宜高咏，羣栖入静看。
由来鸳鹭侣，济济列千官。','',''),('quantangshi-32864','寄辛明府','李頻','quantangshi','','卷33','何处无苛政，东南有子男。
细将朝客说，须是邑人谙。
别业空经稔，归田独未甘。
目凝烟积树，心贮月明潭。
晓鼓愁方乱，春山睡正酣。
不任啼鸟思，乡社欲桑蚕。','',''),('quantangshi-32865','苑中题友人林亭','李頻','quantangshi','','卷33','井邑藏嵓穴，幽栖趣若何。
春篁抽笋密，夏鸟杂雏多。
坐有清风至，林无暑气过。
乱书还就叶，真饮不听歌。
片影明红藓，斜阴映绿萝。
雄文终可惜，莫更弃高科。','',''),('quantangshi-32866','投京兆府试官任文学先辈','李頻','quantangshi','','卷33','高兴每论诗，非才独见推。
应当明试日，不比暗投时。
出口人皆信，操心自可知。
孤单虽有托，际会别无期。
取舍知由己，穷通断在兹。
贱身何足数，公道自难欺。
泽国违甘旨，渔舟积梦思。
长安未归去，为倚鉴妍媸。','',''),('quantangshi-32867','宋少府东溪泛舟','李頻','quantangshi','','卷33','登岸还入舟，水禽惊笑语。
晚叶低众色，湿云带繁暑。
落日乘醉归，溪流复几许。','',''),('quantangshi-32868','闻北虏入灵州二首 一','李頻','quantangshi','','卷33','河冰一夜合，虏骑入灵州。
岁岁徴兵去，难防塞草秋。','',''),('quantangshi-32869','闻北虏入灵州二首 二','李頻','quantangshi','','卷33','见说灵州战，沙中血未干。
将军日告急，走马向长安。','',''),('quantangshi-32870','送友人下第归感怀','李頻','quantangshi','','卷33','帝里春无意，归山对物华。
即应来日去，九陌踏槐花。','',''),('quantangshi-32871','赠桂林友人','李頻','quantangshi','','卷33','君家桂林住，日伐桂枝炊。
何事东堂树，年年待一枝。','',''),('quantangshi-32872','长安感怀','李頻','quantangshi','','卷33','一第知何日，全家待此身。
空将灞陵酒，酌送向东人。','',''),('quantangshi-32873','题长孙桐树','李頻','quantangshi','','卷33','一去龙门侧，千年凤影移。
空余剪圭处，无复在孙枝。','',''),('quantangshi-32874','渡汉江','李頻','quantangshi','','卷33','岭外音书绝，经年复历春。
近乡情更怯，不敢问来人。','',''),('quantangshi-32875','嵩山夜还','李頻','quantangshi','','卷33','家住东臯去，好采旧山薇。
自省游泉石，何曾不夜归。','',''),('quantangshi-32876','暮秋宿清源上人院','李頻','quantangshi','','卷33','野客愁来日，山房木落中。
微风生夜半，积雨向秋终。
证道方离法，安禅不住空。
迷途将觉路，语默见西东。','',''),('quantangshi-32877','秋夜宿重本上人院','李頻','quantangshi','','卷33','却忆凉堂坐，明河几度流。
安禅逢小暑，抱疾入高秋。
水国曾重讲，云林半旧游。
此来看月落，还似道相求。','',''),('quantangshi-32878','赠立规上人','李頻','quantangshi','','卷33','竹向空斋合，无僧在四邻。
去云离坐石，斜月到禅身。
树老风终夜，山寒雪见春。
不知诸祖后，传印是何人。','',''),('quantangshi-32879','苏州寒食日送人归觐','李頻','quantangshi','','卷33','江城寒食下，花木惨离魂。
几宿投山寺，孤帆过海门。
□声泼火雨，柳色禁烟村。
定看堂高后，斑衣灭泪痕。','',''),('quantangshi-32880','即席送许□之曹南省兄','李頻','quantangshi','','卷33','梅烂荷圆六月天，归帆高背虎丘烟。
到时自见成行雁，别处休听满树蝉。
卖劒为赊吴市酒，携家犹借洞庭船。
待看春榜来江外，名占蓬莱第几仙。','',''),('quantangshi-32881','送罗着作两浙按狱','李頻','quantangshi','','卷33','使印星车适旧游，陶潜今日在瀛洲。
科条尽晓三千罪，囹圄应空十二州。
旧绶有香笼驿马，皇华无暇狎沙鸥。
归来重过姑苏郡，莫忘题名在虎丘。','',''),('quantangshi-32882','下第后屏居书怀寄张侍御','李頻','quantangshi','','卷33','刖足岂一生，良工隔千里。
故山彭泽上，归梦向汾水。
低催神气尽，僮仆心亦耻。
未达谁不知，达者多忘此。
行年忽已壮，去老年更几。
功名如不彰，身殁岂为鬼。
才看芳草歇，即叹凉风起。
骢马未来朝，嘶声尚在耳。','',''),('quantangshi-32883','答韩中丞容不饮酒','李頻','quantangshi','','卷33','老大成名仍足病，强听丝竹亦无欢。
高情太守容闲坐，借与青山尽日看。','',''),('quantangshi-32884','句','李頻','quantangshi','','卷33','只将五字句，用破一生心。
楚里八千里，盘盘此都会。
巍峩数里城，远水相映带。','',''),('quantangshi-32885','冬至后西湖泛舟看断冰偶成长句','李郢','quantangshi','','卷33','一阳生后阴飙竭，湖上层冰看折时。
云母扇摇当殿色，珊瑚树碎满盘枝。
斜汀藻动鱼应觉，极浦波生雁未知。
山影浅中留瓦砾，日光寒外送涟漪。
崖崩苇岸纵横散，篙蹙兰舟片段随。
曾向黄河望冲激，大鹏飞起雪风吹。','',''),('quantangshi-32886','阳羡春歌','李郢','quantangshi','','卷33','石亭梅花落如积，玉藓斓班竹姑赤。
祝陵有酒清若空，煮稬蒸鱼作寒食。
长桥新晴好天气，两市儿郎[棹]船戏。
溪头铙鼓狂杀侬，青盖红裙偶相值。
风光何处最可怜，邵家高楼白日边。
楼下游人颜色喜，溪南黄帽应羞死。
三月未有二月残，灵龟可信渰水干。
葑草青青促归去，短箫横笛说明年。','',''),('quantangshi-32887','茶山贡焙歌','李郢','quantangshi','','卷33','使君爱客情无已，客在金台价无比。
春风三月贡茶时，尽逐红旌到山里。
焙中清晓朱门开，筐箱渐见新芽来。
陵烟触露不停探，官家赤印连帖催。
朝饥暮匐谁兴哀，喧阗竞纳不盈掬。
一时一饷还成堆，蒸之馥之香胜梅，研膏架动轰如雷。
茶成拜表贡天子，万人争噉春山摧。
驿骑鞭声砉流电，半夜驱夫谁复见。
十日王程路四千，到时须及清明宴。
吾君可谓纳谏君，谏官不谏何由闻。
九重城里虽玉食，天涯吏役长纷纷。
使君忧民惨容色，就焙尝茶坐诸客。
几回到口重咨嗟，嫩绿鲜芳出何力。
山中有酒亦有歌，乐营房户皆仙家。
仙家十队酒百斛，金丝宴馔随经过。
使君是日忧思多，客亦无言征绮罗。
殷勤绕焙复长叹，官府例成期如何。
吴民吴民莫憔悴，使君作相期苏尔。','',''),('quantangshi-32888','夏日登信州北楼','李郢','quantangshi','','卷33','高楼上长望，百里见灵山。
雨歇河珠定，云开谷鸟还。
田苗映林合，牛犊傍村闲。
始得消忧处，蝉声催入关。','',''),('quantangshi-32889','游天柱观','李郢','quantangshi','','卷33','听钟到灵观，仙子喜相寻。
茅洞几千载，水声寒至今。
读碑丹井上，坐石涧亭阴。
清兴未云尽，烟霞生夕林。','',''),('quantangshi-32890','酬刘谷除夜见寄','李郢','quantangshi','','卷33','坐恐三更至，流年此夜分。
客心无限事，愁雨不堪闻。
灞上家殊远，炉前酒暂醺。
刘郎亦多恨，诗忆故山云。','',''),('quantangshi-32891','元日作','李郢','quantangshi','','卷33','锵锵华驷客，门馆贺新正。
野雪江山霁，微风竹树清。
芜庭春意晓，残枿烬烟生。
忽忆王孙草，前年在帝京。','',''),('quantangshi-32892','酬刘谷立春日吏隐亭见寄','李郢','quantangshi','','卷33','孤亭遥带寺，静者独登临。
楚霁江流慢，春归泽气阴。
野田青牧马，幽竹暖鸣禽。
日日年光尽，何堪故国心。','',''),('quantangshi-32893','宿怜上人房','李郢','quantangshi','','卷33','重公旧相识，一夕话劳生。
药裹关身病，经函寄道情。
岳寒当寺色，滩夜入楼声。
不待移文诮，三年别赤城。','',''),('quantangshi-32894','园居','李郢','quantangshi','','卷33','暮雨杨雄宅，秋风向秀园。
不闻砧杵动，时看桔槔翻。
钓下鱼初食，船移鸭蹔喧。
橘寒才弄色，须带早霜繁。','',''),('quantangshi-32895','中元夜','李郢','quantangshi','','卷33','江南水寺中元夜，金粟栏边见月娥。
红烛影回仙态近，翠鬟光动看人多。
香飘彩殿凝兰麝，露绕轻衣杂绮罗。
湘水夜空巫峡远，不知归路欲如何。','',''),('quantangshi-32896','赠羽林将军','李郢','quantangshi','','卷33','虬须憔悴羽林郎，曾入甘泉侍武皇。
雕没夜云知御苑，马随仙仗识天香。
五湖归去孤舟月，六国平来两鬓霜。
唯有桓伊江上笛，卧吹三弄送残阳。','',''),('quantangshi-32897','送人之岭南','李郢','quantangshi','','卷33','关山迢遰古交州，岁[晏]怜君走马游。
谢氏海边逢素女，越王潭上见青牛。
嵩台月照啼猨曙，石室烟含古桂秋。
回望长安五千里，刺桐花下莫淹留。','',''),('quantangshi-32898','晚泊松江驿','李郢','quantangshi','','卷33','片帆孤客晚夷犹，红蓼花前水驿秋。
岁月方惊离别尽，烟波仍驻古今愁。
云阴故国山川暮，潮落空江网罟收。
还有吴娃旧歌曲，棹声遥散采菱舟。','',''),('quantangshi-32899','江亭春霁','李郢','quantangshi','','卷33','江蓠漠漠荇田田，江上云亭霁景鲜。
蜀客帆樯背归燕，楚山花木怨啼鹃。
春风掩映千门柳，晓色凄凉万井烟。
金磬泠泠水南寺，上方僧室翠微连。','',''),('quantangshi-32900','早秋书怀','李郢','quantangshi','','卷33','高梧一叶坠凉天，宋玉悲秋泪洒然。
霜拂楚山频见菊，雨零溪树忽无蝉。
虚村暮角催残日，近寺归僧寄野泉。
青鬓已缘多病镊，可堪风景促流年。','',''),('quantangshi-32901','为妻作生日寄意','李郢','quantangshi','','卷33','谢家生日好风烟，柳暖花春二月天。
金凤对翘双翡翠，蜀琴初上七丝弦。
鸳鸯交颈期千岁，琴瑟谐和愿百年。
应恨客程归未得，绿窗江泪冷涓涓。','',''),('quantangshi-32902','重阳日寄浙东诸从事','李郢','quantangshi','','卷33','野人多病门长掩，荒圃重阳菊自开。
愁里又闻清笛怨，望中难见白衣来。
元瑜正及从军乐，甯戚谁怜叩角哀。
红斾纷纷碧江暮，知君醉下望乡台。','',''),('quantangshi-32903','和湖州杜员外冬至日白苹洲见忆','李郢','quantangshi','','卷33','白苹亭上一阳生，谢朓新裁锦绣成。
千嶂雪消溪影渌，几家梅绽海波清。
已知鸥鸟长来狎，可许汀洲独有名。
多愧龙门重招引，即抛田舍棹舟行。','',''),('quantangshi-32904','上裴晋公','李郢','quantangshi','','卷33','四朝忧国鬓如丝，龙马精神海鹤姿。
天上玉书传诏夜，阵前金甲受降时。
曾经庾亮三秋月，下尽羊昙两路碁。
惆怅旧堂扃绿野，夕阳无限鸟飞迟。','',''),('quantangshi-32905','钱塘青山题李隐居西斋','李郢','quantangshi','','卷33','小隐西斋为客开，翠萝深处遍青苔。
林间扫石安碁局，岩下分泉遰酒杯。
兰叶露光秋月上，芦花风起夜潮来。
湖山遶屋犹嫌浅，欲棹渔舟近钓台。','',''),('quantangshi-32906','友人适越路过桐庐寄题江驿','李郢','quantangshi','','卷33','桐庐县前洲渚平，桐庐江上晚潮生。
莫言独有山川秀，过日仍闻官长清。
麦陇虚凉当水店，鲈鱼鲜美称莼羹。
王孙客棹残春去，相送河桥羡此行。','',''),('quantangshi-32907','送刘谷','李郢','quantangshi','','卷33','村桥西路雪初晴，云暖沙干马足轻。
寒涧渡头芳草色，新梅岭外鹧鸪声。
邮亭已送轻车发，山馆谁将候火迎。
落日千峰转迢遰，知君回首望高城。','',''),('quantangshi-32908','七夕','李郢','quantangshi','','卷33','乌鹊桥头双扇开，年年一度过河来。
莫嫌天上稀相见，犹胜人间去不回。
欲减烟花饶俗世，暂烦烟月掩妆台。
别时旧路长清浅，岂肯离情似死灰。','',''),('quantangshi-32909','秦处士移家富春发樟亭怀寄','李郢','quantangshi','','卷33','潮落空江洲渚生，知君已上富春亭。
尝闻郭邑山多秀，更说官僚眼尽青。
离别几宵魂耿耿，相思一座髪星星。
仙翁白石高歌调，无复松斋半夜听。','',''),('quantangshi-32910','故洛阳城','李郢','quantangshi','','卷33','胡兵一动朔方尘，不使銮舆此重巡。
清洛但流呜咽水，上阳深锁寂寥春。
云收少室初晴雨，柳拂中桥晚渡津。
欲问升平无故老，凤楼回首落花频。','',''),('quantangshi-32911','紫极宫上元斋次呈诸道流','李郢','quantangshi','','卷33','碧简朝天章奏频，清宫仿髴降灵真。
五龙金角向星斗，三洞玉音愁鬼神。
风拂乱灯山磬□，露霑仙杏石坛春。
明朝醮罢羽客散，尘土满城空世人。','',''),('quantangshi-32912','立春一日江村偶兴','李郢','quantangshi','','卷33','旧历年光看卷尽，立春何用更相催。
江边野店寒无色，竹外孤村坐见梅。
山雪乍晴岚翠起，渔家向晚笛声哀。
南州近有秦中使，闻道胡兵索战来。','',''),('quantangshi-32913','立秋后自京归家','李郢','quantangshi','','卷33','篱落秋归见豆花，竹门当水岸横槎。
松斋一雨宜清簟，佛室孤灯对绛纱。
尽日抱愁跧似鼠，移时不动嬾于虵。
西江近有鲈鱼否，张翰扁舟始到家。','',''),('quantangshi-32914','奉陪裴相公重阳日游安乐池亭','李郢','quantangshi','','卷33','绛霄轻霭翊三台，稽阮襟怀管乐才。
莲沼昔为王俭府，菊篱今作孟嘉杯。
宁知北阙元勋在，却引东山旧客来。
自笑吐茵还酩酊，日斜空从绛衣回。','',''),('quantangshi-32915','淛河馆','李郢','quantangshi','','卷33','雨湿菰蒲斜日明，茅厨煮茧掉车声。
青蛇上竹一种色，黄蝶隔溪无限情。
何处樵渔将远饷，故园田土忆春耕。
千峰万濑水潏潏，羸马此中愁独行。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32916','春日题山家','李郢','quantangshi','','卷33','偶与樵人熟，春残日日来。
依岗寻紫蕨，挽树得青梅。
燕静衔泥起，蜂喧抱蘂回。
嫩茶重搅绿，新酒畧炊醅。
漠漠蚕生纸，涓涓水弄苔。
丁香政堪结，留步小庭隈。','',''),('quantangshi-32917','江亭晚望','李郢','quantangshi','','卷33','碧天凉冷雁来疎，闲望江云思有余。
秋馆池亭荷叶后，野人篱落豆花初。
无愁自得仙人术，多病能忘太史书。
闻说故园香稻熟，片帆归去就鲈鱼。','',''),('quantangshi-32918','长安夜访澈上人','李郢','quantangshi','','卷33','关西木落夜霜凝，乌帽闲寻紫阁僧。
松迥月光先照鹤，寺寒沟水忽生冰。
琤琤晓漏喧秦禁，漠漠秋烟起汉陵。
闻说天台旧禅处，石房独有一龛灯。','',''),('quantangshi-32919','送圆鉴上人游天台','李郢','quantangshi','','卷33','西岭草堂留不住，独携瓶锡向天台。
霜清海寺闻潮至，日宴江船乞食回。
华顶夜寒孤月落，石桥秋尽一僧来。
灵溪道者相逢处，阴洞泠泠竹室开。','',''),('quantangshi-32920','送僧之台州','李郢','quantangshi','','卷33','独寻台岭闲游去，岂觉灵溪道里赊。
三井应潮通海浪，五峰攒寺落天花。
寒潭盥漱铜瓶洁，野店安禅锡杖斜。
到日初寻石桥路，莫教云雨湿袈裟。','',''),('quantangshi-32921','伤贾岛无可','李郢','quantangshi','','卷33','却到京师事事伤，惠休归寂贾生亡。
何人收得文章箧，独我来经苔藓房。
一命未霑为逐客，万缘初尽别空王。
萧萧竹坞斜阳在，叶覆闲堦雪拥墙。','',''),('quantangshi-32922','孔雀','李郢','quantangshi','','卷33','越鸟青春好颜色，晴轩入户看呫衣。
一身金翠画不得，万里山川来者稀。
丝竹惯听时独舞，楼台初上欲孤飞。
刺桐花谢芳草歇，南国同巢应望归。','',''),('quantangshi-32923','秋晚寄题陆勋校书义兴禅居时淮南从事','李郢','quantangshi','','卷33','禅居秋草晚，萧索异前时。
莲幕青云贵，翱翔绝后期。
藓房柽架掩，山砌石盆欹。
劒戟晨趋静，笙歌夜散迟。
谷寒霜狖静，林晚磬虫悲。
惠远烟霞在，方平杖履随。
骨清须贵达，神重有威仪。
万卒千蹄马，横鞭从信骑。','',''),('quantangshi-32924','酬王舍人雪中见寄','李郢','quantangshi','','卷33','三日柴门拥不开，堦庭平满白皑皑。
今朝踏作琼瑶迹，为有诗从凤沼来。','',''),('quantangshi-32925','蝉','李郢','quantangshi','','卷33','饮蝉惊雨落高槐，山蚁移将入石阶。
若使秦楼美人见，还应一为拔金钗。','',''),('quantangshi-32926','自水口入茶山','李郢','quantangshi','','卷33','蒨蒨红裙好女儿，相偎相倚看人时。
使君马上应含笑，横把金鞭为咏诗。','',''),('quantangshi-32927','重游天台','李郢','quantangshi','','卷33','南国天台山水奇，石桥危险古来知。
龙潭直下一百丈，谁见生公独坐时。','',''),('quantangshi-32928','山行','李郢','quantangshi','','卷33','小田微雨稻苗香，田畔清溪潏潏凉。
自忆东吴榜舟日，蓼花沟水半篙强。','',''),('quantangshi-32929','上元日寄湖杭二从事','李郢','quantangshi','','卷33','恋别山灯忆水灯，山光水焰百千层。
谢公留赏山公唤，知入笙歌阿那朋。','',''),('quantangshi-32930','寒食野望','李郢','quantangshi','','卷33','旧坟新陇哭多时，流世都堪几度悲。
乌鸟乱啼人未远，野风吹散白棠梨。','',''),('quantangshi-32931','清明日题一公禅室','李郢','quantangshi','','卷33','山头兰若石楠春，山下清明烟火新。
此日何穷礼禅客，归心谁是恋禅人。','',''),('quantangshi-32932','七夕寄张氏兄弟','李郢','quantangshi','','卷33','新秋牛女会佳期，红粉筵开玉馔时。
好与檀郎寄花朵，莫教清晓羡蛛丝。','',''),('quantangshi-32933','春晚与诸同舍出城迎座主侍郎','李郢','quantangshi','','卷33','三十骅骝一哄尘，来时不锁杏园春。
东风柳絮轻如雪，应有偷游曲水人。','',''),('quantangshi-32934','张郎中宅戏赠二首 一','李郢','quantangshi','','卷33','薄雪燕蓊紫燕钗，钗垂簏簌抱香怀。
一声歌罢刘郎醉，脱取明金压绣鞋。','',''),('quantangshi-32935','张郎中宅戏赠二首 二','李郢','quantangshi','','卷33','谢家青妓邃重关，谁省春风见玉颜。
闻道彩鸾三十六，一双双对碧池莲。','',''),('quantangshi-32936','醉送','李郢','quantangshi','','卷33','江梅冷艳酒清光，急拍繁弦醉画堂。
无限柳条多少雪，一将春恨付刘郎。','',''),('quantangshi-32937','晓井','李郢','quantangshi','','卷33','桐阴覆井月斜明，百尺寒泉古甃清。
越女携瓶下金索，晓天初放辘轳声。','',''),('quantangshi-32938','南池','李郢','quantangshi','','卷33','小男供饵妇搓丝，溢榼香醪倒接䍦。
日出两竿鱼正食，一家欢笑在南池。','',''),('quantangshi-32939','偶作','李郢','quantangshi','','卷33','一杯正发吟哦兴，两盏还生去住愁。
何似全家上船去，酒旗多处即淹留。','',''),('quantangshi-32940','画鼓','李郢','quantangshi','','卷33','尝闻画鼓动欢情，及送离人恨鼓声。
两杖一挥行缆解，暮天空使别魂惊。','',''),('quantangshi-32941','燕蓊花','李郢','quantangshi','','卷33','十二街中何限草，燕蓊尽欲占残春。
黄花扑地无穷极，愁杀江南去住人。','',''),('quantangshi-32942','邵博士溪亭','李郢','quantangshi','','卷33','野茶无限春风叶，溪水千重返照波。
只去长桥三十里，谁人一解枉帆过。','',''),('quantangshi-32943','小石上见亡友题处','李郢','quantangshi','','卷33','笋石清琤入紫烟，陆云题处是前年。
苔侵雨打依稀在，惆怅凉风树树蝉。','',''),('quantangshi-32944','洞灵观流泉','李郢','quantangshi','','卷33','石上苔芜水上烟，潺湲声在观门前。
千岩万壑分流去，更引飞花入洞天。','',''),('quantangshi-32945','送李判官','李郢','quantangshi','','卷33','津市停桡送别难，荧荧蜡炬照更阑。
东风万叠吹江月，谁伴袁襃宿夜滩。','',''),('quantangshi-32946','宿杭州虚白堂','李郢','quantangshi','','卷33','秋月斜明虚白堂，寒蛩唧唧树苍苍。
江风彻晓不得睡，二十五声秋点长。','',''),('quantangshi-32947','道林寺','崔珏','quantangshi','','卷33','临湘之滨麓之隅，西有松寺东岸无。
松风千里摆不断，竹泉泻入于僧厨。
宏梁大栋何足贵，山寺难有山泉俱。
四时唯夏不敢入，烛龙安敢停斯须。
远公池上种何物，碧罗扇底红鳞鱼。
香阁朝鸣大法鼓，天宫夜转三乘书。
野花市井栽不着，山鸡饮啄声相呼。
金槛僧回步步影，石盆水溅联联珠。
北临高处日正午，举手欲摸黄金乌。
遥江大船小于叶，远村杂树齐如蔬。
潭州城郭在何处，东边一片青模糊。
今来古往人满地，劳生未了归丘墟。
长卿之门久寂寞，五言七字夸规模。
我吟杜诗清入骨，灌顶何必须醍醐。
白日不照耒阳县，皇天厄死饥寒躯。
明珠大贝采欲尽，蚌蛤空满赤沙湖。
今我题诗亦无味，怀贤览古成长吁。
不如兴罢过江去，已有好月明归途。','',''),('quantangshi-32948','美人尝茶行','崔珏','quantangshi','','卷33','云鬟枕落困春泥，玉郎为碾瑟瑟尘。
闲教鹦鹉啄窗响，和娇扶起浓睡人。
银瓶贮泉水一掬，松雨声来乳花熟。
朱唇啜破绿云时，咽入香喉爽红玉。
明眸渐开横秋水，手拨丝簧醉心起。
台时却坐推金筝，不语思量梦中事。','',''),('quantangshi-32949','门前柳','崔珏','quantangshi','','卷33','门前蜀柳□知春，风澹暖烟愁杀人。
将谓只栽郡楼下，不知迤逦连南津。
南津柳色连南市，南市戎州三百里。
夷陬蛮落相连接，故乡莫道心先死。
我今帝里尚有家，门前嫩柳插仙霞。
晨霑太一坛边雨，暮宿凤皇城里鵶。
别来三载当谁道，门前年年绿阴好。
春来定解飞雪花，雨后还应庇烟草。
忆昔当年栽柳时，新芽茁茁嫌生迟。
如今宛转稊着地，常向绿阴劳梦思。
不道彼树好，不道此树恶。
试将此意问野人，野人尽道生处乐。
为报门前杨柳栽，我应来岁当归来。
纵令树下能攀折，白发如丝心似灰。','',''),('quantangshi-32950','岳阳楼晚望','崔珏','quantangshi','','卷33','干坤千里水云间，钓艇如萍去复还。
楼上北风斜卷席，湖中西日倒衔山。
怀沙有恨骚人往，鼓瑟无声帝子闲。
何事黄昏尚凝睇，数行烟树接荆蛮。','',''),('quantangshi-32951','哭李商隐 一','崔珏','quantangshi','','卷33','成纪星郎字义山，适归高壤抱长叹。
词林枝叶三春尽，学海波澜一夜干。
风雨已吹灯烛灭，姓名长在齿牙寒。
只应物外攀琪树，便着霓裳上绛坛。','',''),('quantangshi-32952','哭李商隐 二','崔珏','quantangshi','','卷33','虚负凌云万丈才，一生襟抱未曾开。
鸟啼花落人何在，竹死桐枯凤不来。
良马足因无主踠，旧交心为绝弦哀。
九泉莫叹三光隔，又送文星入夜台。','',''),('quantangshi-32953','和友人鸳鸯之什 一','崔珏','quantangshi','','卷33','翠鬣红衣舞夕晖，水禽情似此禽稀。
暂分烟岛犹回首，只渡寒塘亦共飞。
映雾乍迷珠殿瓦，逐梭齐上玉人机。
采莲无限兰桡女，笑指中流羡尔归。','',''),('quantangshi-32954','和友人鸳鸯之什 二','崔珏','quantangshi','','卷33','寂寂春塘烟晚时，两心和影共依依。
溪头日暖眠沙稳，渡口风寒浴浪稀。
翡翠莫夸饶彩饰，䴙鹈须羡好毛衣。','',''),('quantangshi-32955','和友人鸳鸯之什 三','崔珏','quantangshi','','卷33','舞鹤翔鸾俱别离，可怜生死两相随。
红丝毳落眠汀处，白雪花成蹙浪时。
琴上只闻交颈语，窗前空展共飞诗。
何如相见长相对，肯羡人间多所思。','',''),('quantangshi-32956','有赠 一','崔珏','quantangshi','','卷33','莫道妆成断客肠，粉胸绵手白莲香。
烟分顶上三层绿，劒截眸中一寸光。
舞胜柳枝腰更软，歌嫌珠贯曲犹长。
虽然不似王孙女，解爱临邛卖赋郎。','',''),('quantangshi-32957','有赠 二','崔珏','quantangshi','','卷33','锦里芬芳少佩兰，风流全占似君难。
心迷晓梦窗犹暗，粉落香肌汗未干。
两脸夭桃从镜发，一眸春水照人寒。
自嗟此地非吾土，不得如花岁岁看。','',''),('quantangshi-32958','和人听歌 一','崔珏','quantangshi','','卷33','气吐幽兰出洞房，乐人先问调宫商。
声和细管珠才转，曲度沈烟雪更香。
公子不随肠万结，离人须落泪千行。
巫山唱罢行云过，犹自微尘舞画梁。','',''),('quantangshi-32959','和人听歌 二','崔珏','quantangshi','','卷33','红脸初分翠黛愁，锦筵歌板拍清秋。
一楼春雪和尘落，午夜寒泉带雨流。
座上美人心尽死，尊前旅客泪难收。
莫辞更送刘郎酒，百斛明珠异日酬。','',''),('quantangshi-32960','水晶枕','崔珏','quantangshi','','卷33','千年积雪万年冰，掌上初擎力不胜。
南国旧知何处得，北方寒气此中凝。
黄昏转烛萤飞沼，白日褰帘水在簪。
蕲簟蜀琴相对好，裁诗乞与涤烦襟。','',''),('quantangshi-32961','席间咏琴客','崔珏','quantangshi','','卷33','七条弦上五音寒，此艺知音自古难。
唯有河南房次律，始终怜得董庭兰。','',''),('quantangshi-32962','句','崔珏','quantangshi','','卷33','楚王宫地罗含宅，赖许时时听法来。','',''),('quantangshi-32963','徒相逢','曹鄴','quantangshi','','卷33','江边野花不须采，梁头野燕不用亲。
西施本是越溪女，承恩不荐越溪人。','',''),('quantangshi-32964','杂诫','曹鄴','quantangshi','','卷33','带香入鲍肆，香气同鲍鱼。
未入犹可悟，已入当何如。','',''),('quantangshi-32965','捕渔谣','曹鄴','quantangshi','','卷33','天子好征战，百姓不种桑。
天子好年少，无人荐冯唐。
天子好美女，夫妇不成双。','',''),('quantangshi-32966','四怨三愁五情诗十二首 其一怨','曹鄴','quantangshi','','卷33','美人如新花，许嫁还独守。
岂无青铜镜，终日自疑丑。','',''),('quantangshi-32967','四怨三愁五情诗十二首 其二怨','曹鄴','quantangshi','','卷33','庭花已结子，岩花犹弄色。
谁令生处远，用尽春风力。','',''),('quantangshi-32968','四怨三愁五情诗十二首 其三怨','曹鄴','quantangshi','','卷33','短鬟一如螓，长眉一如蛾。
相共棹莲舟，得花不如他。','',''),('quantangshi-32969','四怨三愁五情诗十二首 其四怨','曹鄴','quantangshi','','卷33','手推呕哑车，朝朝暮暮耕。
未曾分得谷，空得老农名。','',''),('quantangshi-32970','四怨三愁五情诗十二首 其一愁','曹鄴','quantangshi','','卷33','远梦如水急，白发如草新。
归期待春至，春至还送人。','',''),('quantangshi-32971','四怨三愁五情诗十二首 其二愁','曹鄴','quantangshi','','卷33','涧草短短青，山月朗朗明。
此夜目不掩，屋头乌啼声。','',''),('quantangshi-32972','四怨三愁五情诗十二首 其三愁','曹鄴','quantangshi','','卷33','别家鬓未生，到城鬓似髪。
朝朝临川望，灞水不入越。','',''),('quantangshi-32973','四怨三愁五情诗十二首 其一情','曹鄴','quantangshi','','卷33','东西是长江，南北是官道。
牛羊不恋山，只恋山中草。','',''),('quantangshi-32974','四怨三愁五情诗十二首 其二情','曹鄴','quantangshi','','卷33','阿娇生汉宫，西施住南国。
专房莫相妒，各自有颜色。','',''),('quantangshi-32975','四怨三愁五情诗十二首 其三情','曹鄴','quantangshi','','卷33','蛱蝶空中飞，夭桃庭中春。
见他夫妇好，有女初嫁人。','',''),('quantangshi-32976','四怨三愁五情诗十二首 其四情','曹鄴','quantangshi','','卷33','槟榔自无柯，椰叶自无阴。
常羡庭边竹，生笋高于林。','',''),('quantangshi-32977','四怨三愁五情诗十二首 其五情','曹鄴','quantangshi','','卷33','野雀空城饥，交交复飞飞。
勿怪官仓粟，官仓无空时。','',''),('quantangshi-32978','寄刘驾','曹鄴','quantangshi','','卷33','一川草色青褭褭，遶屋水声如在家。
怅望美人不携手，墙东又发数枝花。','',''),('quantangshi-32979','风人体','曹鄴','quantangshi','','卷33','出门行一步，形影便相失。
何况大堤上，骢马如箭疾。
夜夜如织妇，寻思待成匹。
郎只不在家，在家亦如出。
将金与卜人，谲道远行吉。
念郎缘底事，不具天与日。','',''),('quantangshi-32980','杏园即席上同年','曹鄴','quantangshi','','卷33','岐路不在天，十年行不至。
一旦公道开，青云在平地。
枕上数声鼓，衡门已如市。
白日探得珠，不待骊龙睡。
怱怱出九衢，僮仆颜色异。
故衣未及换，尚有去年泪。
晴阳照花影，落絮浮野翠。
对酒时忽惊，犹疑梦中事。
自怜孤飞鸟，得接鸾凤翅。
永怀共济心，莫起胡越意。','',''),('quantangshi-32981','恃宠','曹鄴','quantangshi','','卷33','二月树色好，昭仪正骄奢。
恐君爱阳艳，斫却园中花。
三十六宫女，髻鬟各如鸦。
君王心所怜，独自不见瑕。
台上红灯尽，未肯下金车。
一笑不得所，尘中悉无家。
飞燕身更轻，何必恃容华。','',''),('quantangshi-32982','题女郎庙','曹鄴','quantangshi','','卷33','数点烟香出庙门，女娥飞去影中存。
年年岭上春无主，露泣花愁断客魂。','',''),('quantangshi-32983','四望楼','曹鄴','quantangshi','','卷33','背山见楼影，应合与山齐。
座上日已出，城中未鸣鸡。
无限燕赵女，吹笙上金梯。
风起洛阳东，香过洛阳西。
公子长夜醉，不闻子规啼。','',''),('quantangshi-32984','筑城三首 一','曹鄴','quantangshi','','卷33','郎有蘼芜心，妾有芙蓉质。
不辞嫁与郎，筑城无休日。','',''),('quantangshi-32985','筑城三首 二','曹鄴','quantangshi','','卷33','呜呜啄人鸦，轧轧上城车。
力尽土不尽，得归亦无家。','',''),('quantangshi-32986','筑城三首 三','曹鄴','quantangshi','','卷33','筑人非筑城，围秦岂围我。
不知城上土，化作宫中火。','',''),('quantangshi-32987','奉命齐州推事毕寄本府尚书','曹鄴','quantangshi','','卷33','越鸟栖不定，孤飞入齐乡。
日暮天欲雨，那兼羽翎伤。
州民言刺史，蠹物甚于蝗。
受命大执法，草草是行装。
仆隶皆分散，单车驿路长。
四顾无相识，奔驰若投荒。
重门下长锁，树影空过墙。
驱囚遶廊屋，𧥄𧥄如牛羊。
狱吏相对语，簿书堆满牀。
敲枷打锁声，终日在目旁。
既舍三山侣，来余五斗粮。
忍学空城雀，潜身入官仓。
国中天子令，头上白日光。
曲木用处多，不如直为梁。
恐孤食恩地，昼夜心不遑。
仲夏天气热，鬓须忽成霜。
社鼠不可灌，城狐不易防。
偶于擒纵间，尽得见否臧。
截断奸吏舌，擘开冤人肠。
明朝向西望，走马归汶阳。','',''),('quantangshi-32988','北郭闲思','曹鄴','quantangshi','','卷33','山前山后是青草，尽日出门还掩门。
每思骨肉在天畔，来看野翁怜子孙。','',''),('quantangshi-32989','战城南','曹鄴','quantangshi','','卷33','千金画阵图，自为弓剑苦。
杀尽田野人，将军犹爱武。
性命换他恩，功成谁作主。
凤皇楼上人，夜夜长歌舞。','',''),('quantangshi-32990','自退','曹鄴','quantangshi','','卷33','寒女面如花，空寂常对影。
况我不嫁容，甘为瓶堕井。','',''),('quantangshi-32991','早起','曹鄴','quantangshi','','卷33','月堕沧浪西，门开树无影。
此时归梦阑，立在梧桐井。','',''),('quantangshi-32992','古相送','曹鄴','quantangshi','','卷33','行人卜去期，白发根已出。
执君青松枝，空数别来日。
心如七夕女，生死难再匹。
且愿车声迫，莫使马行疾。
巫山千丈高，亦恐梦相失。','',''),('quantangshi-32993','甲第','曹鄴','quantangshi','','卷33','游人未入门，花影出门前。
将军来此住，十里无荒田。','',''),('quantangshi-32994','望不来','曹鄴','quantangshi','','卷33','见花忆郎面，常愿花色新。
为郎容貌好，难有相似人。','',''),('quantangshi-32995','官仓鼠','曹鄴','quantangshi','','卷33','官仓老鼠大如斗，见人开仓亦不走。
健儿无粮百姓饥，谁遣朝朝入君口。','',''),('quantangshi-32996','题濮庙','曹鄴','quantangshi','','卷33','晓祭瑶斋夜扣钟，鳌头风起浪重重。
人间直有仙桃种，海上应无肉马踪。
赤水梦沈迷象罔，翠华恩断泣芙蓉。
不知皇帝三宫驻，始向人间着衮龙。','',''),('quantangshi-32997','偶题','曹鄴','quantangshi','','卷33','白玉先生多在市，青牛道士不居山。
但能共得丹田语，正是忙时身亦闲。','',''),('quantangshi-32998','登岳阳楼有怀寄座主相公','曹鄴','quantangshi','','卷33','南登岳阳楼，北眺长安道。
不见升平里，千山树如草。
骨肉在南楚，沈忧起常早。
白社愁成空，秋芜待谁扫。
常闻诗人语，西子不宜老。
赖识丹元君，时来语蓬岛。','',''),('quantangshi-32999','出关','曹鄴','quantangshi','','卷33','山上黄犊走避人，山下女郎歌满野。
我独南征恨此身，更有无成出关者。','',''),('quantangshi-33000','将赴天平职书怀寄翰林从兄','曹鄴','quantangshi','','卷33','居处绝人事，门前雀罗施。
谁遣辟书至，仆隶皆展眉。
匹马渡河洛，西风飘路岐。
手执王粲笔，闲吟向旌旗。
香晚翠莲动，吟余红烛移。
开口啖酒肉，将何报相知。
况我魏公子，相愿不相疑。
岂学官仓鼠，饱食无所为。
白露霑碧草，芙蓉落清池。
自小不到处，全家忽如归。
吾宗处清切，立在白玉墀。
方得一侍座，单车又星飞。
愿将门底水，永托万顷陂。','',''),('quantangshi-33001','贺雪寄本府尚书','曹鄴','quantangshi','','卷33','雨雪不顺时，阴阳失明晦。
麦根半成土，农夫泣相对。
我公诚诉天，天地忽已泰。
长飙卷白云，散落羣峰外。
拂砌花影明，交宫鹤翎碎。
宿鸟晨不飞，犹疑月光在。
碧树香尽发，蠹虫声渐退。
有客怀兔园，吟诗遶城内。','',''),('quantangshi-33002','寄嵩阳道人','曹鄴','quantangshi','','卷33','三山浮海倚蓬瀛，路入真元险尽平。
华表千年孤鹤语，人间一梦晚蝉鸣。
将龙逐虎神初王，积火焚心气渐清。
见说嵩阳有仙客，欲持金简问长生。','',''),('quantangshi-33003','去不返','曹鄴','quantangshi','','卷33','寒女不自知，嫁为公子妻。
亲情未识面，明日便东西。
但得上马了，一去头不回。
双轮如鸟飞，影尽东南街。
九重十二门，一门四扇开。
君从此路去，妾向此路啼。
但得见君面，不辞插荆钗。','',''),('quantangshi-33004','送进士下第归南海','曹鄴','quantangshi','','卷33','数片红霞映夕阳，揽君衣袂更移觞。
行人莫叹碧云晚，上国每年春草芳。
雪过蓝关寒气薄，雁回湘浦怨声长。
应无惆怅沧波远，十二玉楼非我乡。','',''),('quantangshi-33005','送厉图南下第归澧州','曹鄴','quantangshi','','卷33','当春人尽归，我独无归计。
送君自多感，不是缘下第。
君看山上草，尽有干云势。
结根既不然，何必更掩袂。
澧水鲈鱼贱，荆门杨柳细。
勿为阳艳留，此处有月桂。
言毕尊未干，十二门欲闭。
伫立望不见，登高更流涕。
吟君别我诗，怅望水烟际。','',''),('quantangshi-33006','思不见','曹鄴','quantangshi','','卷33','但见出门踪，不见入门迹。
却笑山头女，无端化为石。','',''),('quantangshi-33007','贵宅','曹鄴','quantangshi','','卷33','入门又到门，到门戟相对。
玉箫声尚远，疑似人不在。
公子厌花繁，买药栽庭内。
望远不上楼，牕中见天外。
此地日烹羊，无异我食菜。
自是愁人眼，见之若奢泰。','',''),('quantangshi-33008','下第寄知己','曹鄴','quantangshi','','卷33','长安孟春至，枯树花亦发。
忧人此时心，冷若松上雪。
自知才不堪，岂敢频泣血。
所痛无罪者，明时屡遭刖。
故山秋草多，一卷成古辙。
夜来远心起，梦见潇湘月。
大贤冠盖高，何事怜屑屑。
不令伤弓鸟，日暮飞向越。
闻知感激语，胸中如有物。
举头望青天，白日头上没。
归来通济里，开户山鼠出。
中庭广寂寥，但见薇与蕨。
无虑数尺躯，委作泉下骨。
唯愁揽清镜，不见昨日髪。
愿怜闺中女，晚嫁唯守节。
勿惜四座言，女巧难自说。','',''),('quantangshi-33009','吴宫宴','曹鄴','quantangshi','','卷33','吴宫城阙高，龙凤遥相倚。
四面铿鼓钟，中央列罗绮。
春风时一来，兰麝闻数里。
三度明月落，青娥醉不起。
江头銕剑鸣，玉座成荒垒。
适来歌舞处，未知身是鬼。','',''),('quantangshi-33010','长相思','曹鄴','quantangshi','','卷33','翦妾身上巾，赠郎伤妾神。
郎车不暂停，妾貌宁长春。
青天无停雪，沧海无停津。
遣妾空牀梦，夜夜随车轮。','',''),('quantangshi-33011','长城下','曹鄴','quantangshi','','卷33','远水犹归壑，征人合忆乡。
泣多盈袖血，吟苦满头霜。
楚国连天浪，衡门到海荒。
何当生燕羽，时得近雕梁。','',''),('quantangshi-33012','成名后献恩门','曹鄴','quantangshi','','卷33','为物稍有香，心遭蠹虫啮。
平人登太行，万万车轮折。
一辞桂岭猨，九泣东门月。
年年孟春时，看花不如雪。
僻居城南隅，颜子须泣血。
沈埋若九泉，谁肯开口说。
辛勤学机杼，坐对秋灯灭。
织锦花不常，见之尽云拙。
自怜孤生竹，出土便有节。
每听浮竞言，喉中似无舌。
忽然风雷至，惊起池中物。
拔上青云巅，轻如一毫髪。
珑珑金锁甲，稍稍城乌绝。
名字如鸟飞，数日便到越。
幽兰生虽晚，幽香亦难歇。
何以保此身，终身事无缺。','',''),('quantangshi-33013','赠道师','曹鄴','quantangshi','','卷33','举世皆问人，唯师独求己。
一马无四蹄，顷刻行千里。
应笑北原上，丘坟乱如蚁。','',''),('quantangshi-33014','入关','曹鄴','quantangshi','','卷33','衡门亦无路，何况入西秦。
灸病不得穴，徒为采艾人。','',''),('quantangshi-33015','听刘尊师弹琴','曹鄴','quantangshi','','卷33','曾于清海独闻蝉，又向空庭夜听泉。
不似斋堂人静处，秋声长在七条弦。','',''),('quantangshi-33016','题山居','曹鄴','quantangshi','','卷33','扫叶煎茶摘叶书，心闲无梦夜窗虚。
只应光武恩波晚，岂是严君恋钓鱼。','',''),('quantangshi-33017','关试前送进士姚潜下第归南阳','曹鄴','quantangshi','','卷34','马嘶残日没残霞，二月东风便到家。
莫羡长安占春者，明年始见故园花。','',''),('quantangshi-33018','浐川寄进士刘驾','曹鄴','quantangshi','','卷34','我家不背水，君身不向越。
自是相忆苦，忽如经年别。
山家草木寒，石上有残雪。
美人望不见，迢迢云中月。','',''),('quantangshi-33019','翠孤至渚宫寄座主相公','曹鄴','quantangshi','','卷34','万里一孤舟，春行夏方到。
骨肉尽单羸，沈忧满怀抱。
羁孤相对泣，性命不相保。
开户山鼠惊，虫声乱秋草。
白菌缘屋生，黄蒿拥篱倒。
对此起长嗟，芳年亦须老。
恩门为宰相，出入用天道。
忽于摧落间，收得青松操。
全家到江陵，屋虚风浩浩。
中肠自相伐，日夕如寇盗。
其下有孤侄，其上有孀嫂。
黄粮贱于土，一饭常不饱。
天斜日光薄，地湿虫呌噪。
惟恐道忽消，形容益枯槁。
古人于黄雀，岂望白环报。
奉答恩地恩，何慙以诚告。','',''),('quantangshi-33020','早秋宿田舍','曹鄴','quantangshi','','卷34','涧草疎疎萤火光，山月朗朗枫树长。
南村犊子夜声急，应是栏边新有霜。','',''),('quantangshi-33021','旅次岳阳寄京中亲故','曹鄴','quantangshi','','卷34','君山南面浪连天，一客愁心两处悬。
身逐片帆归楚泽，魂随流水向秦川。
月回浦北千寻雪，树出湖东几点烟。
更欲登楼向西望，北风催上洞庭船。','',''),('quantangshi-33022','题舒乡','曹鄴','quantangshi','','卷34','功名若及鸱夷子，必拟将舟泛洞庭。
柳色湖光好相待，我心非醉亦非醒。','',''),('quantangshi-33023','碧寻宴上有怀知己','曹鄴','quantangshi','','卷34','荻花芦叶满溪流，一簇笙歌在水楼。
金管曲长人尽醉，玉簪恩重独生愁。
女萝力弱难逢地，桐树心孤易感秋。
莫怪当欢却惆怅，全家欲上五湖舟。','',''),('quantangshi-33024','从天平节度使游平流园','曹鄴','quantangshi','','卷34','池塘静于寺，俗事不到眼。
下马如在山，令人忽疎散。
明公有高思，到此遂长返。
乘兴挈一壶，折荷以为盏。
入竹藤似虵，侵墙水成藓。
幽鸟不识人，时来拂冠冕。
沿流路若穷，及行路犹远。
洞中已云夕，洞口天未晚。
自怜不羁者，写物心常简。
飜愁此兴多，引得嵇康嬾。','',''),('quantangshi-33025','故人寄茶','曹鄴','quantangshi','','卷34','剑外九华英，缄题下玉京。
开时微月上，碾处乱泉声。
半夜招僧至，孤吟对月烹。
碧沈霞脚碎，香泛乳花轻。
六腑睡神去，数朝诗思清。
月余不敢费，留伴肘书行。','',''),('quantangshi-33026','东武吟','曹鄴','quantangshi','','卷34','心如山上虎，身若仓中鼠。
惆怅倚市门，无人与之语。
夜宴李将军，欲望心相许。
何曾听我言，贪谑邯郸女。
独上黄金台，凄凉泪如雨。','',''),('quantangshi-33027','蓟北门行','曹鄴','quantangshi','','卷34','长河冻如石，征人夜中戍。
但恐筋力尽，敢惮将军遇。
古来死未歇，白骨碍官路。
岂无一有功，可以高其墓。
亲戚牵衣泣，悲号自相顾。
死者虽无言，那堪生者悟。
不如无手足，得见齿髪暮。
乃知七尺躯，却是速死具。','',''),('quantangshi-33028','金井怨','曹鄴','quantangshi','','卷34','西风吹急景，美人照金井。
不见面上花，却恨井中影。','',''),('quantangshi-33029','姑苏台','曹鄴','quantangshi','','卷34','南宫酒未销，又宴姑苏台。
美人和泪去，半夜阊门开。
相对正歌舞，笑中闻鼓鼙。
星散九重门，血流十二街。
一去成万古，台尽人不回。
时闻野田中，拾得黄金钗。','',''),('quantangshi-33030','夜坐有怀','曹鄴','quantangshi','','卷34','悄悄月出树，东南若微霜。
愁人不成寐，五月夜亦长。
佳期杳天末，骨肉不在旁。
年华且有恨，厥体难久康。
人言力耕者，岁旱亦有粮。
吾道固如此，安得苦伥伥。','',''),('quantangshi-33031','寄监察从兄','曹鄴','quantangshi','','卷34','我祖居邺地，邺人识文星。
此地星已落，兼无古时城。
古风既无根，千载难重生。
空留建安书，传说七子名。
贱子生桂州，桂州山水清。
自觉心貌古，兼合古人情。
因为二雅诗，出语有性灵。
持来向长安，时得长者惊。
芝草不为瑞，还共木叶零。
恨如辙中土，终岁填不平。
吾宗戴豸冠，忽然入西京。
怜其羽翼单，抚若亲弟兄。
松根已坚牢，松叶岂不荣。
言罢眼无泪，心中如酒酲。','',''),('quantangshi-33032','乐府体','曹鄴','quantangshi','','卷34','莲子房房嫩，菖蒲叶叶齐。
共结池中根，不厌池中泥。','',''),('quantangshi-33033','弃妇','曹鄴','quantangshi','','卷34','嫁来未曾出，此去长别离。
父母亦有家，羞言何以归。
此日年且少，事姑常有仪。
见多自成丑，不待颜色衰。
何人不识宠，所嗟无自非。
将欲告此意，四邻已相疑。','',''),('quantangshi-33034','读李斯传','曹鄴','quantangshi','','卷34','一车致三毂，本图行地速。
不知驾驭难，举足成颠覆。
欺暗尚不然，欺明当自戮。
难将一人手，掩得天下目。
不见三尺坟，云阳草空绿。','',''),('quantangshi-33035','文宗陵','曹鄴','quantangshi','','卷34','千年尧舜心，心成身已殁。
始随苍梧云，不返苍龙阙。
宫女衣不香，黄金赐白发。
留此奉天下，所以无征伐。
至今汨罗水，不葬大夫骨。','',''),('quantangshi-33036','偶怀','曹鄴','quantangshi','','卷34','开目不见路，常如夜中行。
最贱不自勉，中涂与谁争。
蓬为沙所危，还向沙上生。
一年秋不熟，安得便废耕。
颜子命未达，亦遇时人轻。','',''),('quantangshi-33037','代罗敷诮使君','曹鄴','quantangshi','','卷34','常言爱嵩山，别妾向东京。
朝来见人说，却知在石城。
未必菖蒲花，只向石城生。
自是使君眼，见物皆有情。
麋鹿同上山，莲藕同在泥。
莫学天上日，朝东暮还西。','',''),('quantangshi-33038','怨歌行','曹鄴','quantangshi','','卷34','丈夫好弓剑，行坐说金吾。
喜闻有行役，结束不待车。
官田赠倡妇，留妾待舅姑。
舅姑皆已死，庭花半是芜。
中妹寻适人，生女亦嫁夫。
何曾寄消息，他处却有书。
严风厉中野，女子心易孤。
贫贱又相负，封侯意何如。','',''),('quantangshi-33039','南征怨','曹鄴','quantangshi','','卷34','万浪东不回，昭王南征早。
龙舟没何处，独树江上老。
吾欲问水滨，宫殿已生草。','',''),('quantangshi-33040','和潘安仁金谷集','曹鄴','quantangshi','','卷34','太守龙为马，将军金作车。
香飘十里风，风下绿珠歌。
莫怪坐上客，叹君庭前花。
明朝此池馆，不是石崇家。','',''),('quantangshi-33041','不可见','曹鄴','quantangshi','','卷34','常闻贫贱夫，头白终相待。
自从嫁黔娄，终岁长不在。
君梦有双影，妾梦空四邻。
常思劲北风，吹折双车轮。','',''),('quantangshi-33042','秦后作','曹鄴','quantangshi','','卷34','大道不居谦，八荒安苟得。
木中不生火，高殿祸顷刻。
谁将白帝子，践我礼义域。
空持拔山志，欲夺天地德。
轵道人不回，壮士断消息。
父母骨成薪，虫蛇自相食。
鼎乱阴阳疑，战尽鬼神力。
东郊龙见血，九土玄黄色。
鼙鼓裂二景，妖星动中国。
圆丘无日月，旷野失南北。
徒流杀人血，神器终不忒。
一马渡空江，始知贤者贼。','',''),('quantangshi-33043','薄命妾','曹鄴','quantangshi','','卷34','薄命常恻恻，出门见南北。
刘郎马蹄疾，何处去不得？
泪珠不可收，虫丝不可织。
知君绿桑下，更有新相识。','',''),('quantangshi-33044','放歌行','曹鄴','quantangshi','','卷34','莫唱放歌行，此歌临楚水。
人皆恶此声，唱者终不已。
三闾有何罪，不向枕上死。','',''),('quantangshi-33045','江西送人','曹鄴','quantangshi','','卷34','八月江上楼，西风令人愁。
携酒楼上别，尽见四山秋。
但愁今日知，莫作他时疑。
郎本不住此，无人泣望归。
何水不生波，何木不改柯。
遥知明日恨，不如今日多。
将心速投人，路远人如何。','',''),('quantangshi-33046','始皇陵下作','曹鄴','quantangshi','','卷34','千金买鱼灯，泉下照狐兔。
行人上陵过，却吊扶苏墓。
累累圹中物，多于养生具。
若使山可移，应将秦国去。
舜殁虽在前，今犹未封树。','',''),('quantangshi-33047','洛原西望','曹鄴','quantangshi','','卷34','筑城畏不坚，城坚心自毁。
秦树满平原，秦人不居此。
犹为泣路者，无力报天子。','',''),('quantangshi-33048','赵城怀古','曹鄴','quantangshi','','卷34','邯郸旧公子，骑马又鸣珂。
手挥白玉鞭，不避五侯车。
闲愁春日短，沽酒入倡家。
一笑千万金，醉中赠秦娥。
如今高原上，树树白杨花。','',''),('quantangshi-33049','代班姬','曹鄴','quantangshi','','卷34','宠极多妒容，乘车上金阶。
歘然赵飞燕，不语到日西。
手把菖蒲花，君王唤不来。
常嫌鬓蝉重，乞人白玉钗。
君心无定波，咫尺流不回。
后宫门不掩，每夜黄鸟啼。
买得千金赋，花颜已如灰。','',''),('quantangshi-33050','庭草','曹鄴','quantangshi','','卷34','庭草根自浅，造化无遗功。
低回一寸心，不敢怨春风。','',''),('quantangshi-33051','过白起墓','曹鄴','quantangshi','','卷34','[夷]陵火焰灭，长平生气低。
将军临老病，赐剑咸阳西。','',''),('quantangshi-33052','对酒','曹鄴','quantangshi','','卷34','爱酒知是僻，难与性相舍。
未必独醒人，便是不饮者。
晚岁无此物，何由住田野。','',''),('quantangshi-33053','续幽愤','曹鄴','quantangshi','','卷34','繁霜作阴起，朱火乘夕发。
清昼冷无光，兰膏坐销歇。
惟公执天宪，身是台中杰。
一逐楚大夫，何人为君雪。
怱怱鬼方路，不许辞双阙。
过门似他乡，举趾如遗辙。
八月黄草生，洪涛入云热。
危魂没太行，客吊空骨节。
千年瘴江水，恨声流不绝。','',''),('quantangshi-33054','古词','曹鄴','quantangshi','','卷34','高阙碍飞鸟，人言是君家。
经年不归去，爱妾面上花。
妾面虽有花，妾心非女萝。
郎妻自不重，于妾欲如何。','',''),('quantangshi-33055','和谢豫章从宋公戏马台送孔令谢病','曹鄴','quantangshi','','卷34','碧树杳云暮，朔风自西来。
佳人忆山水，置酒在高台。
不必问流水，坐来日已西。
劝君速归去，正及鹧鸪啼。','',''),('quantangshi-33056','送进士李殷下第游汾河','曹鄴','quantangshi','','卷34','上国花照地，遣君向西征。
旁人亦有恨，况复故人情。
单车欲云去，别酒忽然醒。
如何今夜梦，半作道路程。
边士不好礼，全家住军城。
城中鼓角严，旅客常夜惊。
中有左记室，逢人眼光明。
西门未归者，下马如到京。
还应一开卷，为子心不平。
殷勤说忠抱，壮志勿自轻。','',''),('quantangshi-33057','相思极','曹鄴','quantangshi','','卷34','妾颜与日空，君心与日新。
三年得一书，犹在湘之滨。
料君相轻意，知妾无至亲。
况当受明礼，不令再嫁人。
愿君从此日，化质为妾身。','',''),('quantangshi-33058','代谢玄晖新亭送范零陵','曹鄴','quantangshi','','卷34','楚水洪无际，沧茫接天涯。
相看不能语，独鸟下江蓠。
蓬子悉有恋，蓬根却无期。
车轮自不住，何必怨路岐。
孟冬衣食薄，梦寐亦未遗。','',''),('quantangshi-33059','山中效陶','曹鄴','quantangshi','','卷34','落第非有罪，兹山聊归止。
山猨隔云住，共饮山中水。
读书时有兴，坐石忘却起。
西山忽然暮，往往遗巾履。
经时一出门，兼候僮仆喜。
常被山翁笑，求名岂如此。
齿髪老未衰，何如且求己。','',''),('quantangshi-33060','城南野居寄知己','曹鄴','quantangshi','','卷34','奔走未到我，在城如在村。
出门既无意，岂如常闭门。
作诗二十载，阙下名不闻。
无人为开口，君子独有言。
身为苦寒士，一笑亦感恩。
殷勤中途上，勿使车无轮。','',''),('quantangshi-33061','古莫买妾行','曹鄴','quantangshi','','卷34','千扉不当路，未似开一门。
若遣绿珠丑，石家应尚存。','',''),('quantangshi-33062','霁后作','曹鄴','quantangshi','','卷34','新霁辨草木，晚塘明衣衿。
乳燕不归宿，双双飞向林。
微照露花影，轻云浮麦阴。
无人可招隐，尽日登山吟。','',''),('quantangshi-33063','田家効陶','曹鄴','quantangshi','','卷34','黑黍舂来酿酒饮，青禾刈了驱牛载。
大姑小叔常在眼，却笑长安在天外。','',''),('quantangshi-33064','寄贾驰先辈','曹鄴','quantangshi','','卷34','游子想万里，何必登高台。
闻君燕女吟，如自蓟北来。
长安高盖多，健马东西街。
尽说蒿簪古，将钱买金钗。
我祖西园事，言之独伤怀。
如今数君子，如鸟无树栖。
济水一入河，便与清流乖。
闻君欲自持，勿使吾道低。','',''),('quantangshi-33065','送友人入塞','曹鄴','quantangshi','','卷34','乱蓬无根日，送子入青塞。
苍茫万里秋，如见原野大。
鸟雀寒不下，山川迥相对。
一马没黄云，登高望犹在。
惊风忽然起，白日黯已晦。
如何怨路长，出门天涯外。','',''),('quantangshi-33066','寄阳朔友人','曹鄴','quantangshi','','卷34','桂林须产千株桂，未解当天影日开。
我到月中收得种，为君移向故园栽。','',''),('quantangshi-33067','题广福岩','曹鄴','quantangshi','','卷34','未有天地先融结，方广高深无丈尺。
书言不尽画难成，留与人间作奇特。','',''),('quantangshi-33068','送曾德迈归宁宜春','曹鄴','quantangshi','','卷34','湘东山水有清辉，袁水词人得意归。
几府争驰毛义檄，一乡看侍老莱衣。
筵开灞岸临清浅，路去蓝关入翠微。
想到宜阳更无事，并将欢庆奉庭闱。','',''),('quantangshi-33069','送郑谷归宜春','曹鄴','quantangshi','','卷34','无成归故国，上马亦高歌。
况是飞鸣后，殊为喜庆多。
暑销嵩岳雨，凉吹洞庭波。
莫便闲吟去，须期接盛科。','',''),('quantangshi-33070','老圃堂','曹鄴','quantangshi','','卷34','邵平瓜地接吾庐，谷雨干时手自锄。
昨日春风欺不在，就牀吹落读残书。','',''),('quantangshi-33071','登芜城','儲嗣宗','quantangshi','','卷34','昔人登此地，丘壠已前悲。
今日又非昔，春风能几时。','',''),('quantangshi-33072','沧浪峡','儲嗣宗','quantangshi','','卷34','沧浪临古道，道上石成尘。
自有沧浪峡，谁为无事人。','',''),('quantangshi-33073','垓城','儲嗣宗','quantangshi','','卷34','百战未言非，孤军惊夜围。
山河意气尽，泪湿美人衣。','',''),('quantangshi-33074','南陂远望','儲嗣宗','quantangshi','','卷34','闲门横古塘，红树已惊霜。
独立望秋草，野人耕夕阳。
孤烟起蜗舍，飞鹭下渔梁。
唯有田家事，依依似故乡。','',''),('quantangshi-33075','宿玉箫宫','儲嗣宗','quantangshi','','卷34','尘飞不到空，露湿翠微宫。
鹤影石桥月，箫声松殿风。
绿毛辞世女，白发入壶翁。
借问烧丹处，桃花几遍红。','',''),('quantangshi-33076','晚眺徐州延福寺','儲嗣宗','quantangshi','','卷34','杉风振旅尘，晚景籍芳茵。
片水明在野，万花深见人。
静依归鹤思，远惜旧山春。
今日惜携手，寄怀吟白苹。','',''),('quantangshi-33077','宿甘棠馆','儲嗣宗','quantangshi','','卷34','尘迹入门尽，悄然江海心。
水声巫峡远，山色洞庭深。
风桂落寒子，岚烟凝夕阴。
前轩鹤归处，萝月思沈沈。','',''),('quantangshi-33078','和茅山高拾遗忆山中杂题五首 山泉','儲嗣宗','quantangshi','','卷34','香味清机仙府回，萦纡乱石便流杯。
春风莫泛桃花去，恐引凡人入洞来。','',''),('quantangshi-33079','和茅山高拾遗忆山中杂题五首 巢鹤','儲嗣宗','quantangshi','','卷34','千万云间丁令威，殷勤仙骨莫先飞。
若逢茅氏传消息，贞白先生不久归。','',''),('quantangshi-33080','和茅山高拾遗忆山中杂题五首 胡山','儲嗣宗','quantangshi','','卷34','犬入五云音信绝，凤楼凝碧悄无声。
焚香古洞步虚夜，露湿松花空月明。','',''),('quantangshi-33081','和茅山高拾遗忆山中杂题五首 小楼','儲嗣宗','quantangshi','','卷34','松杉风外乱山青，曲几焚香对石屏。
空忆去年春雨后，燕泥时污太玄经。','',''),('quantangshi-33082','和茅山高拾遗忆山中杂题五首 山邻','儲嗣宗','quantangshi','','卷34','石桥春涧已归迟，梦入仙山山不知。
柱史从来非俗吏，青牛道士莫相疑。','',''),('quantangshi-33083','送道士','儲嗣宗','quantangshi','','卷34','泠然御风客，与道自浮沈。
黄鹤有归语，白云无忌心。
药炉经月净，天路入壶深。','',''),('quantangshi-33084','宿山馆','儲嗣宗','quantangshi','','卷34','寂寞对衰草，地凉凝露华。
蝉鸣月中树，风落客前花。
山馆无宿伴，秋琴初别家。
自怜千万里，笔砚寄生涯。','',''),('quantangshi-33085','入浮石山','儲嗣宗','quantangshi','','卷34','斜日出门去，残花已过春。
鸟声穿叶远，虎迹渡溪新。
入洞几时路，耕田何代人。
自慙非避俗，不敢问迷津。','',''),('quantangshi-33086','送人归故园','儲嗣宗','quantangshi','','卷34','远节惨言别，况予心久违。
从来忆家泪，今日送君归。
野路正风雪，还乡犹布衣。
里中耕稼者，应笑读书非。','',''),('quantangshi-33087','得越中书','儲嗣宗','quantangshi','','卷34','芳草离离思，悠悠春梦余。
池亭千里月，烟水一封书。
诗想怀康乐，文应吊子胥。
扁舟恋南越，岂独为鲈鱼。','',''),('quantangshi-33088','秋墅','儲嗣宗','quantangshi','','卷34','欲暮候樵者，望山空翠微。
虹随余雨散，鵶带夕阳归。
穷巷长秋草，孤村时捣衣。
谁知多病客，寂寞掩柴扉。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33089','哭彭先生','儲嗣宗','quantangshi','','卷34','谷口溪声客自伤，那堪呜咽吊残阳。
空阶鹤恋丹青影，秋雨苔封白石牀。
主祭孤儿初学语，无媒旅榇未还乡。
门人远赴心丧夜，月满千山旧草堂。','',''),('quantangshi-33090','和顾非熊先生题茅山处士闲居','儲嗣宗','quantangshi','','卷34','归耕地肺绝尘喧，匣里青萍未报恩。
浊酒自怜终日醉，古风时得野人言。
鸟啼碧树闲临水，花满青山静掩门。
唯有阶前芳草色，年年惆怅忆王孙。','',''),('quantangshi-33091','长安怀古','儲嗣宗','quantangshi','','卷34','祸稔萧墙终不知，生人力屈尽边陲。
赤龙已赴东方暗，黄犬徒怀上蔡悲。
面缺崩城山寂寂，土埋冤骨草离离。
秋风解怨扶苏死，露泣烟愁红树枝。','',''),('quantangshi-33092','过王右丞书堂二首 一','儲嗣宗','quantangshi','','卷34','澄潭昔卧龙，章句世为宗。
独步声名在，千岩水石空。
野禽悲灌木，落日吊清风。
后学攀遗址，秋山闻草虫。','',''),('quantangshi-33093','过王右丞书堂二首 二','儲嗣宗','quantangshi','','卷34','万树影参差，石牀藤半垂。
萤光虽散草，鸟迹尚临池。
风雅传今日，云山想昔时。
感深苏属国，千载五言诗。','',''),('quantangshi-33094','孤雁','儲嗣宗','quantangshi','','卷34','孤雁暮飞急，萧萧天地秋。
关河正黄叶，消息断青楼。
湘渚烟波远，骊山风雨愁。
此时万里道，魂梦遶沧洲。','',''),('quantangshi-33095','赠隐者','儲嗣宗','quantangshi','','卷34','尽室居幽谷，乱山为四邻。
雾深知有术，窗静似无人。
鹤语松上月，花明云里春。
生涯更何许，尊酒与垂纶。','',''),('quantangshi-33096','早春怀薛公裕','儲嗣宗','quantangshi','','卷34','幽独自成愚，柴门日渐芜。
陆机初入洛，孙楚又游吴。
失意怨杨柳，异乡闻鹧鸪。
相思复相望，春草满南湖。','',''),('quantangshi-33097','村月','儲嗣宗','quantangshi','','卷34','月午篱南道，前村半隐林。
田翁独归处，荞麦露花深。','',''),('quantangshi-33098','早春','儲嗣宗','quantangshi','','卷34','野树花初发，空山独见时。
踟蹰历阳道，乡思满南枝。','',''),('quantangshi-33099','送友人游吴','儲嗣宗','quantangshi','','卷34','吴山青楚吟，草色异乡心。
一酌水边酒，数声花下琴。
登楼旧国远，探穴九疑深。
更想逢秋节，那堪闻夜砧。','',''),('quantangshi-33100','赠别','儲嗣宗','quantangshi','','卷34','兰泽伤秋色，临风远别期。
东城草虽绿，南浦柳无枝。
直道岂易枉，暗投谁不疑。
因君问行役，有泪湿江蓠。','',''),('quantangshi-33101','经故人旧居','儲嗣宗','quantangshi','','卷34','万里访遗尘，莺声泪湿巾。
古书无主散，废宅与山邻。
宿草风悲夜，荒村月吊人。
凄凉问残柳，今日为谁春。','',''),('quantangshi-33102','随边使过五原','儲嗣宗','quantangshi','','卷34','偶逐星车犯虏尘，故乡常恐到无因。
五原西去阳关废，日漫平沙不见人。','',''),('quantangshi-33103','春怀寄秣陵知友','儲嗣宗','quantangshi','','卷34','庐江城外柳堪攀，万里行人尚未还。
借问景阳台下客，谢家谁更卧东山。','',''),('quantangshi-33104','宋州月夜感怀','儲嗣宗','quantangshi','','卷34','雁池衰草露霑衣，河水东流万事微。
寂寞青陵台上月，秋风满树鹊南飞。','',''),('quantangshi-33105','吴宫','儲嗣宗','quantangshi','','卷34','荒台荆棘多，忠谏竟如何。
细草迷宫巷，闲花悞绮罗。
前溪徒自绿，子夜不闻歌。
怅望清江暮，悠悠东去波。','',''),('quantangshi-33106','春游望仙谷','儲嗣宗','quantangshi','','卷34','清无车马尘，深洞百花春。
鸡犬疑霑药，耕桑似避秦。
登山采樵路，临水浣纱人。
若得心无事，移家便卜邻。','',''),('quantangshi-33107','圣女祠','儲嗣宗','quantangshi','','卷34','石屏苔色凉，流水遶祠堂。
巢鹊疑天汉，潭花似镜妆。
神来云雨合，神去蕙兰香。
不复闻双佩，山门空夕阳。','',''),('quantangshi-33108','宿范水','儲嗣宗','quantangshi','','卷34','行人倦游宦，秋草宿湖边。
露湿芙蓉渡，月明渔网船。
寒机深竹里，远浪到门前。
何处思乡甚，歌声闻采莲。','',''),('quantangshi-33109','送顾陶校书归钱塘','儲嗣宗','quantangshi','','卷34','清苦月偏知，南归瘦马迟。
橐轻缘换酒，髪白为吟诗。
水色西陵渡，松声伍相祠。
圣朝思直谏，不是挂冠时。','',''),('quantangshi-33110','题云阳高少府衙斋','儲嗣宗','quantangshi','','卷34','大隐能兼济，轩窗逐胜开。
远含云水思，深得栋梁材。
吏散山逾静，庭闲鸟自来。
更怜幽砌色，秋雨长莓苔。','',''),('quantangshi-33111','早春山行','于武陵','quantangshi','','卷34','江草暖初绿，雁行皆北飞。
异乡那久客，野鸟尚思归。
十载过如梦，素心应已违。
行行家渐远，更苦得书稀。','',''),('quantangshi-33112','宿友生林居因怀贾区','于武陵','quantangshi','','卷34','绕屋树森森，多栖紫阁禽。
暂过当永夜，微得话前心。
入楚行应远，经湘恨必深。
那堪对寒烛，更赋别离吟。','',''),('quantangshi-33113','赠卖松人','于武陵','quantangshi','','卷34','入市虽求利，怜君意独真。
劚将寒涧树，卖与翠楼人。
瘦叶几经雪，淡花应少春。
长安重桃李，徒染六街尘。','',''),('quantangshi-33114','友人南游不回因而有寄','于武陵','quantangshi','','卷34','相思春树绿，千里亦依依。
鄠杜月频满，潇湘人未归。
桂花风半落，烟草蝶双飞。
一别无消息，水南车迹稀。','',''),('quantangshi-33115','送酇县董明府之任','于武陵','quantangshi','','卷34','南北行已久，怜君知苦辛。
万家同草木，三载得阳春。
东道听游子，夷门歌主人。
空持语相送，应怪不沾巾。','',''),('quantangshi-33116','山上树','于武陵','quantangshi','','卷34','日暖上山路，鸟啼知已春。
忽逢幽隐处，如见独醒人。
石冷开常晚，风多落亦频。
樵夫应不识，岁久伐为薪。','',''),('quantangshi-33117','长信宫二首 一','于武陵','quantangshi','','卷34','簟凉秋气初，长信恨何如。
拂黛月生指，解鬟云满梳。
一从悲画扇，几度泣前鱼。
坐听南宫乐，凉风摇翠裾。','',''),('quantangshi-33118','长信宫二首 二','于武陵','quantangshi','','卷34','一失辇前恩，绮罗生暗尘。
惟应深夜月，独伴向隅人。
长信翠蛾老，昭阳红粉新。
君心似秋节，不使草长春。','',''),('quantangshi-33119','洛阳道','于武陵','quantangshi','','卷34','浮世若浮云，千回故复新。
旋添青草冢，更有白头人。
岁暮容将老，雪晴山欲春。
行行车与马，不尽洛阳[尘]。','',''),('quantangshi-33120','东门路','于武陵','quantangshi','','卷34','东门车马路，此路在浮沈。
白日若不落，红尘应更深。
从来名利地，皆起是非心。
所以青青草，年年生汉阴。','',''),('quantangshi-33121','江楼春望','于武陵','quantangshi','','卷34','楼下长江路，舟车昼不闲。
鸟声非故国，春色是他山。
一望云复水，几重河与关。
愁心随落日，万里各西还。','',''),('quantangshi-33122','洛中晴望','于武陵','quantangshi','','卷34','九陌尽风尘，嚣嚣昼复昏。
古今人不断，南北路长存。
叶落上阳树，草衰金谷园。
乱鸦归未已，残日半前轩。','',''),('quantangshi-33123','西归','于武陵','quantangshi','','卷34','不系与舟闲，悠悠吴楚间。
羞将新白发，却到旧青山。
一叶忽离树，几人同入关。
长安家尚在，秋至又西还。','',''),('quantangshi-33124','南游','于武陵','quantangshi','','卷34','穷秋几日雨，处处生苍苔。
旧国寄书后，凉天方雁来。
露繁山草湿，洲暖水花开。
去尽同行客，一帆犹未回。','',''),('quantangshi-33125','南游有感','于武陵','quantangshi','','卷34','杜陵无厚业，不得驻车轮。
重到曾游处，多非旧主人。
东风千岭树，西日一洲苹。
又渡湘江去，湘江水复春。','',''),('quantangshi-33126','夜泊湘江','于武陵','quantangshi','','卷34','北风吹楚树，此地独先秋。
何事屈原恨，不随湘水流。
凉天生片月，竟夕伴孤舟。
一作南行客，无成空白头。','',''),('quantangshi-33127','客中','于武陵','quantangshi','','卷34','楚人歌竹枝，游子泪沾衣。
异国久为客，寒宵频梦归。
一封书未返，千树叶皆飞。
南过洞庭水，更应消息稀。','',''),('quantangshi-33128','夜寻僧不遇','于武陵','quantangshi','','卷34','数歇度烟水，渐非尘俗间。
泉声入秋寺，月色遍寒山。
石路几回雪，竹房犹闭关。','',''),('quantangshi-33129','访道者不遇','于武陵','quantangshi','','卷34','人间惟此路，长得绿苔衣。
及户无行迹，游方应未归。
平生无限事，到此尽知非。
独倚松门久，阴云昏翠微。','',''),('quantangshi-33130','赠王隐者山居','于武陵','quantangshi','','卷34','石室扫无尘，人寰与此分。
飞来南浦树，半是华山云。
浮世几多事，先生应不闻。
寒山满西日，空照雁成羣。','',''),('quantangshi-33131','寄北客','于武陵','quantangshi','','卷34','穷边足风惨，何处醉楼台？
家去几千里，月圆十二回。
寒阡随日远，雪路向城开。
游子久无信，年年空雁来。','',''),('quantangshi-33132','寄友人','于武陵','quantangshi','','卷34','长安清渭东，游子迹重重。
此去红尘路，难寻君马踪。
昔时轻一别，渐老贵相逢。
应恋嵩阳住，嵩阳饶古松。','',''),('quantangshi-33133','夜与故人别','于武陵','quantangshi','','卷34','白日去难驻，故人非旧容。
今宵一别后，何处更相逢？
过楚水千里，到秦山几重。
语来天又晓，月落满城钟。','',''),('quantangshi-33134','别故人','于武陵','quantangshi','','卷34','行子与秋叶，各随南北风。
虽非千里别，还阻一宵同。
过尽少年日，尚如长转蓬。
犹为布衣客，羞入故关中。','',''),('quantangshi-33135','送客东归','于武陵','quantangshi','','卷34','一听游子歌，秋计觉蹉跎。
四海少平地，百川无定波。
共惊年已暮，俱向客中多。
又驾征轮去，东归事若何。','',''),('quantangshi-33136','过侯王故第','于武陵','quantangshi','','卷34','过此一酸辛，行人泪有痕。
独残新碧树，犹拥旧朱门。
歌歇云初散，檐空燕尚存。','',''),('quantangshi-33137','孤云','于武陵','quantangshi','','卷34','南北各万里，有云心更闲。
因风离海上，伴月到人间。
洛浦少高树，长安无旧山。
裴回不可驻，漠漠又空还。','',''),('quantangshi-33138','远水','于武陵','quantangshi','','卷34','悔作望南浦，望中生远愁。
因知人易老，为有水东流。
欲附故乡信，不逢归客舟。
萋萋两岸草，又度一年秋。','',''),('quantangshi-33139','咏蝉','于武陵','quantangshi','','卷34','江头一声起，芳岁已难留。
听此高林上，遥知故国秋。
应催风落叶，似劝客回舟。
不是新蝉苦，年年自有愁。','',''),('quantangshi-33140','感情','于武陵','quantangshi','','卷34','青山长寂寞，南望独高歌。
四海故人尽，九原新壠多。
西沈浮世日，东注逝川波。
不使年华驻，此生能几何。','',''),('quantangshi-33141','早春日山居寄城郭知己','于武陵','quantangshi','','卷34','阳和潜发荡寒阴，便使川原景象新。
入户风泉声沥沥，当轩云岫色沈沈。
残云带雨轻飘雪，嫩柳含烟小绽金。
虽有眼前诗酒兴，遨游争得称闲心。','',''),('quantangshi-33142','劝酒','于武陵','quantangshi','','卷34','劝君金屈巵，满酌不须辞。
花发多风雨，人生足别离。','',''),('quantangshi-33143','感怀','于武陵','quantangshi','','卷34','东风吹草色，空使客蹉跎。
不设太平险，更应游子多。
几伤行处泪，一曲醉中歌。
尽向青门外，东随渭水波。','',''),('quantangshi-33144','友人亭松','于武陵','quantangshi','','卷34','俛仰不能去，如逢旧友同。
曾因春雪散，见在华山中。
何处有明月，访君听远风。
相将归未得，各占石岩东。','',''),('quantangshi-33145','游中梁山','于武陵','quantangshi','','卷34','僻地好泉石，何人曾陆沈。
不知青嶂外，更有白云深。
因此见乔木，几回思旧林。
殷勤猨与鸟，惟我独何心。','',''),('quantangshi-33146','寻山','于武陵','quantangshi','','卷34','到此绝车轮，萋萋草树春。
青山如有利，白石亦成尘。
水阔应无路，松深不见人。
如知巢与许，千载迹犹新。','',''),('quantangshi-33147','宿江口','于武陵','quantangshi','','卷34','南渡人来绝，喧喧雁满沙。
自生江上月，长有客思家。
半夜下霜岸，北风吹荻花。
自惊归梦断，不得到天涯。','',''),('quantangshi-33148','秋夜达萧关','于武陵','quantangshi','','卷34','扰扰浮梁路，人忙月自闲。
去年为塞客，今夜宿萧关。
辞国几经岁，望乡空见山。
不知江叶下，又作布衣还。','',''),('quantangshi-33149','斜谷道','于武陵','quantangshi','','卷34','乱峰连叠嶂，千里绿峨峨。
蜀国路如此，游人车亦过。
远烟当叶歛，骤雨逐风多。
独忆紫芝叟，临风歌旧歌。','',''),('quantangshi-33150','过百牢关贻舟中者','于武陵','quantangshi','','卷34','蜀国少平地，方思京洛间。
远为千里客，来度百牢关。
帆影清江水，铃声碧草山。
不因名与利，尔我各应闲。','',''),('quantangshi-33151','客中览镜','于武陵','quantangshi','','卷34','何当开此镜，即见髪如丝。
白日急于水，一年能几时。
每逢芳草处，长返故园迟。
所以多为客，蹉跎欲怨谁。','',''),('quantangshi-33152','长安逢隐者','于武陵','quantangshi','','卷34','征车千里至，碾遍六街尘。
向此有营地，忽逢无事人。
昔时颜未改，浮世路多新。
且脱衣沽酒，终南山欲春。','',''),('quantangshi-33153','与僧话旧','于武陵','quantangshi','','卷34','草堂前有山，一见一相宽。
处世贵僧静，青松因岁寒。
他山逢旧侣，尽日话长安。
所以闲行迹，千回遶药栏。','',''),('quantangshi-33154','赠王道士','于武陵','quantangshi','','卷34','日日市朝路，何时无苦辛。
不随丹竈客，终作白头人。
浮世度千载，桃源方一春。
归来华表上，应笑北邙尘。','',''),('quantangshi-33155','匣中琴','于武陵','quantangshi','','卷34','世人无正心，虫网匣中琴。
何以经时废，非为娱耳音。
独令高韵在，谁感隙尘深。
应是南风曲，声声不合今。','',''),('quantangshi-33156','过洛阳城','于武陵','quantangshi','','卷34','古来利与名，俱在洛阳城。
九陌鼓初起，万车轮已行。
周秦时几变，伊洛水犹清。
二月中桥路，鸟啼春草生。','',''),('quantangshi-33157','望月','于武陵','quantangshi','','卷34','离家凡几宵，一望一寥寥。
新魄又将满，故乡应渐遥。
独临彭蠡水，远忆洛阳桥。
更有乘舟客，凄然亦驻桡。','',''),('quantangshi-33158','王将军宅夜听歌','于武陵','quantangshi','','卷34','朱槛满明月，美人歌落梅。
忽惊尘起处，疑有凤飞来。
一曲听初彻，几年愁暂开。
东南正云雨，不得见阳台。','',''),('quantangshi-33159','长信宫','于武陵','quantangshi','','卷34','莫问古宫名，古宫空有城。
惟应东去水，不改旧时声。','',''),('quantangshi-33160','高楼','于武陵','quantangshi','','卷34','远天明月出，照此谁家楼。
上有罗衣裳，凉风吹不休。','',''),('quantangshi-33161','感古','司馬扎','quantangshi','','卷34','九折无停波，三光如转烛。
玄珠人不识，徒爱燕赵玉。
祖龙已深惑，汉氏远狥欲。
骊山与茂陵，相对秋草绿。','',''),('quantangshi-33162','赠王道士','司馬扎','quantangshi','','卷34','玉洞秋有花，蓬山夜无鬼。
岂知浮云世，生死逐流水。
瑶台歌一曲，曲尽五烟起。
悠然望虚路，玉京在海里。
青箓秘不闻，黄鹤去不止。
愿随执轻策，往结周太子。','',''),('quantangshi-33163','古思','司馬扎','quantangshi','','卷34','春华惜妾态，秋草念妾心。
始知井边桐，不如堂上琴。
月落却羡镜，花飞犹委苔。
门前长江水，一去终不回。','',''),('quantangshi-33164','猎客','司馬扎','quantangshi','','卷34','五陵射雕客，走马占春光。
下马青楼前，华裾独煌煌。
自言家咸京，世族如金张。
击钟传鼎食，尔来八十强。
朱门争先开，车轮满路傍。
娥娥燕赵人，珠箔闭高堂。
清歌杂妙舞，临欢度曲长。
朝游园花新，夜宴池月凉。
更以驰骤多，意气事[彊]梁。
君王正年少，终日在长杨。','',''),('quantangshi-33165','送进士苗纵归紫逻山居','司馬扎','quantangshi','','卷34','汝上多奇山，高怀惬清境。
强来干名地，冠带不能整。
常言梦归处，泉石寒更静。
鹤声夜无人，空月随松影。
今朝抛我去，春物伤明景。
怅望相送还，微阳在东岭。','',''),('quantangshi-33166','卖花者','司馬扎','quantangshi','','卷34','少壮彼何人，种花荒苑外。
不知力田苦，却笑耕耘辈。
当春卖春色，来往经几代。
长安甲第多，处处花堪爱。
良金不惜费，竞取园中最。
一蕊才占烟，歌声已高会。
自言种花地，终日拥轩盖。
农夫官役时，独与花相对。
那令卖花者，久为生人害。
贵粟不贵花，生人自应泰。','',''),('quantangshi-33167','弹琴','司馬扎','quantangshi','','卷34','凉室无外响，空桑七弦分。
所弹非新声，俗耳安肯闻。
月落未终曲，暗中泣湘君。
如传我心苦，千里苍梧云。','',''),('quantangshi-33168','古边卒思归','司馬扎','quantangshi','','卷34','有田不得耕，身卧辽阳城。
梦中稻花香，觉后战血腥。
汉武在深殿，唯思廓寰瀛。
中原半烽火，此屋皆点行。
边土无膏腴，闲地何必争。
徒令执耒者，刀下死纵横。','',''),('quantangshi-33169','美刘太保','司馬扎','quantangshi','','卷34','常爱鲁仲连，退身得其趣。
不知鸱夷子，更入五湖去。
云霞恣摇曳，鸿鹄无低翥。
万里天地空，清飙在平楚。
藏名向宠节，辞疾去公务。
夜尽醉弦歌，日高卧烟树。
岂嗤生前乐，千载自垂裕。
论道复论功，皆可黄金铸。','',''),('quantangshi-33170','蚕女','司馬扎','quantangshi','','卷34','养蚕先养桑，蚕老人亦衰。
苟无园中叶，安得机上丝。
妾家非豪门，官赋日相追。
鸣梭夜达晓，犹恐不及时。
但忧蚕与桑，敢问结发期。
东邻女新嫁，照镜弄蛾眉。','',''),('quantangshi-33171','效陶彭泽','司馬扎','quantangshi','','卷34','一梦倏已尽，百年如露草。
独有南山高，不与人共老。
尊中贮灵味，无事即醉倒。
何必鸣鼓钟，然后乐怀抱。
轻波向海疾，浮云归谷早。
形役良可嗟，唯能狥天道。','',''),('quantangshi-33172','锄草怨','司馬扎','quantangshi','','卷34','种田望雨多，雨多长蓬蒿。
亦念官赋急，宁知荷锄劳。
亭午霁日明，邻翁醉陶陶。
乡吏不到门，禾黍苗自高。
独有辛苦者，屡为州县徭。
罢锄田又废，恋乡不忍逃。
出门吏相促，邻家满仓谷。
邻翁不可告，尽日向田哭。','',''),('quantangshi-33173','山中晚兴寄裴侍御','司馬扎','quantangshi','','卷34','雷息疎雨散，空山夏云晴。
南轩对林晚，篱落新蛩鸣。
白酒一樽满，坐歌天地清。
十年身未闲，心在人间名。
永怀君亲恩，久贱难退情。
安得蓬丘侣，提携采瑶英。','',''),('quantangshi-33174','筑台','司馬扎','quantangshi','','卷34','魏国昔强盛，宫中金玉多。
征丁筑层台，唯恐不巍峩。
结构切星汉，跻攀横绮罗。
朝观细腰舞，夜听皓齿歌。
讵念人力劳，安问黍与禾。
一朝国既倾，千仞堂亦平。
舞模衰柳影，歌留草虫声。
月照白露寒，苍苍故邺城。
汉文有遗美，对此清飙生。','',''),('quantangshi-33175','道中早发','司馬扎','quantangshi','','卷34','野店鸡一声，萧萧客车动。
西峯带晓月，十里犹相送。
繁弦满长道，羸马四蹄重。
遥羡青楼人，锦衾方远梦。
功名不我与，孤剑何所用。
行役难自休，家山忆秋洞。','',''),('quantangshi-33176','沧浪峡','司馬扎','quantangshi','','卷34','山下水声深，水边山色聚。
月照秋自清，花名春不去。
似非人间境，又近红尘路。
乍入洞中天，更移云外步。
我殊惺惺者，犹得沧浪趣。
可以濯吾缨，斯言诚所慕。','',''),('quantangshi-33177','感萤','司馬扎','quantangshi','','卷34','爱尔持照书，临书叹吾道。
青荧一点光，曾误几人老。
夜久独此心，环垣闭秋草。','',''),('quantangshi-33178','自渭南晚次华州','司馬扎','quantangshi','','卷34','前楼仙鼎原，西经赤水渡。
火云入村巷，余雨依驿树。
我行伤去国，疲马屡回顾。
有如无窠鸟，触热不得住。
峨峨华峰近，城郭生夕雾。
逆旅何人寻，行客暗中住。
却思林丘卧，自惬平生素。
劳役今若兹，羞吟招隐句。','',''),('quantangshi-33179','近别','司馬扎','quantangshi','','卷34','咫尺不相见，便同天一涯。
何必隔关山，乃言伤别离。
君心与我心，脉脉无由知。
谁堪近别苦，远别犹有期。','',''),('quantangshi-33180','江上秋夕','司馬扎','quantangshi','','卷34','茂陵归路绝，谁念此淹留。
极目月沈浦，苦吟霜满舟。
孤猨啼后夜，久客病高秋。
欲寄乡关恨，寒江无北流。','',''),('quantangshi-33181','送归客','司馬扎','quantangshi','','卷34','多才与命违，末路隐柴扉。
白发何人问，青山一剑归。
晴烟独鸟没，野渡乱花飞。
寂寞长亭外，依然空落晖。','',''),('quantangshi-33182','东门晚望','司馬扎','quantangshi','','卷34','青门聊极望，何事久离羣。
芳草失归路，故乡空暮云。
信回陵树老，梦断灞流分。
兄弟正南北，鸿声堪独闻。','',''),('quantangshi-33183','上巳日曲江有感','司馬扎','quantangshi','','卷34','万花明曲水，车马动秦川。
此日不得意，青春徒少年。
晴沙下鸥鹭，幽沚生兰荃。
向晚积归念，江湖心渺然。','',''),('quantangshi-33184','宿寿安甘棠馆','司馬扎','quantangshi','','卷34','行人方倦役，到此似还乡。
流水来关外，青山近洛阳。
溪云归洞鹤，松月半轩霜。
坐恐晨钟动，天涯道路长。','',''),('quantangshi-33185','送友人下第东游','司馬扎','quantangshi','','卷34','出门皆有托，君去独何亲。
阙下新交少，天涯旧业贫。
烟寒岳树暝，雪后岭梅春。
圣代留昆玉，那令愧郄诜。','',''),('quantangshi-33186','山斋会别','司馬扎','quantangshi','','卷34','春草平陵路，荷衣醉别离。
将寻洛阳友，共结洞庭期。
星月半山尽，天鸡出海迟。
无轻此分手，他日重相思。','',''),('quantangshi-33187','晓过伊水寄龙门僧','司馬扎','quantangshi','','卷34','龙门树色暗苍苍，伊水东流客恨长。
病马独嘶残夜月，行人欲渡满船霜。
几家烟火依村步，何处渔歌似故乡？
山下禅庵老师在，愿将形役问空王。','',''),('quantangshi-33188','送孔恂入洛','司馬扎','quantangshi','','卷34','洛阳古城秋色多，送君此去心如何。
青山欲暮惜别酒，碧草未尽伤离歌。
前朝冠带掩金谷，旧游花月经铜驼。
行人正苦奈分手，日落远水生微波。','',''),('quantangshi-33189','观郊礼','司馬扎','quantangshi','','卷34','钟鼓旌旗引六飞，玉皇初着画龙衣。
泰坛烟尽星河晓，万国心随彩仗归。','',''),('quantangshi-33190','宫怨','司馬扎','quantangshi','','卷34','柳色参差掩画楼，晓莺啼送满宫愁。
年年花落无人见，空逐春泉出御沟。','',''),('quantangshi-33191','南徐夕眺','司馬扎','quantangshi','','卷34','行吟向暮天，何处不凄然？
岸影几家柳，笛声何处船。
楼分瓜步月，鸟入秣陵烟。
故里无人到，乡书谁为传。','',''),('quantangshi-33192','题清上人','司馬扎','quantangshi','','卷34','古院闭松色，入门人自闲。
罢经来宿鸟，支策对秋山。
客念蓬梗外，禅心烟雾间。
空怜濯缨处，阶下水潺潺。','',''),('quantangshi-33193','涂中寄薛中裕','司馬扎','quantangshi','','卷34','贫交千里外，失路更伤离。
晓泪芳草尽，夜魂明月知。
空山连野外，寒鸟下霜枝。
此景正寥落，为君玄髪衰。','',''),('quantangshi-33194','白马津阻雨','司馬扎','quantangshi','','卷34','津树萧萧旅馆空，坐看疎叶绕堦红。
故乡千里楚云外，归雁一声烟雨中。
漳浦病多愁易老，茂陵书在信难通。
功名傥遂身无事，终向溪头伴钓翁。','',''),('quantangshi-33195','秋日怀储嗣宗','司馬扎','quantangshi','','卷34','故人北游久不回，塞雁南渡声何哀。
相思闻雁更惆怅，却向单于台下来。','',''),('quantangshi-33196','夜听李山人弹琴','司馬扎','quantangshi','','卷34','瑶琴夜久弦秋清，楚客一奏湘烟生。
曲中声尽意不尽，月照竹轩红叶明。','',''),('quantangshi-33197','隐者','司馬扎','quantangshi','','卷34','松间开一径，秋草自相依。
终日不冠带，空山无是非。
投纶溪鸟伴，曝药谷云飞。
时向邻家去，狂歌夜醉归。','',''),('quantangshi-33198','登河中鹳[雀]楼','司馬扎','quantangshi','','卷34','楼中见千里，楼影入通津。
烟树遥分陕，山河曲向秦。
兴亡留白日，今古共红尘。
鹳雀飞何处，城隅草自春。','',''),('quantangshi-33199','漾陂晚望','司馬扎','quantangshi','','卷34','远客家水国，此来如到乡。
何人垂白发，一叶钓残阳。
柳暗鸟乍起，渚深兰自芳。
因知帝城下，有路向沧浪。','',''),('quantangshi-33200','贺襄阳副使节判同加章绶','徐商','quantangshi','','卷34','朱紫花前贺故人，兼荣此会颇关身。
同年坐上联宾榻，宗姓亭中布锦裀。
晴日照旗红灼烁，韶光入队影玢璘。
芳菲解助今朝喜，嫩蘂青条满眼新。','',''),('quantangshi-33201','句','徐商','quantangshi','','卷34','萍聚只因今日浪，荻斜都为夜来风。','',''),('quantangshi-33202','和薛逢赠别','高璩','quantangshi','','卷34','劒外绵州第一州，尊前偏喜接君留。
歌声婉转添长恨，管色凄凉似到秋。
但务欢娱思晓角，独耽云水上高楼。
莫言此去难相见，怨别征黄是顺流。','',''),('quantangshi-33203','句','高璩','quantangshi','','卷34','公斋一到人非旧，诗板重寻墨尚新。','',''),('quantangshi-33204','和李尚书命妓饯崔侍御','高湘','quantangshi','','卷34','谢安春渚饯袁宏，千里仁风一扇清。
歌黛惨时方酩酊，不知公子重飞觥。','',''),('quantangshi-33205','句','高湘','quantangshi','','卷34','惟有高州是当家。','',''),('quantangshi-33206','报何泽','崔安潛','quantangshi','','卷34','四十九年前及第，同年唯有老夫存。
今日殷勤访吾子，稳将鬐鬣上龙门。','',''),('quantangshi-33207','题文翁石室','裴鉶','quantangshi','','卷34','文翁石室有仪形，庠序千秋播德馨。
古柏尚留今日翠，高岷犹蔼旧时青。
人心未肯抛膻蚁，弟子依前学聚萤。
更叹沱江无限水，争流祗愿到沧溟。','',''),('quantangshi-33208','愤惋诗三首 一','劉損','quantangshi','','卷34','宝钗分股合无缘，鱼在深渊日在天。
得意紫鸾休舞镜，断踪青鸟罢衔笺。
金杯倒覆难收水，玉轸倾攲嬾续弦。
从此蘼芜山下过，祗应将泪比黄泉。','',''),('quantangshi-33209','愤惋诗三首 二','劉損','quantangshi','','卷34','鸾辞旧伴知何止，凤得新梧想称心。
红粉尚存香幕幕，白云将散信沈沈。
已休磨琢投泥玉，嬾更经营买笑金。
愿作山头似人石，丈夫衣上泪痕深。','',''),('quantangshi-33210','愤惋诗三首 三','劉損','quantangshi','','卷34','旧尝游处徧寻看，覩物伤情死一般。
买笑楼前花已谢，画眉窗下月空残。
云归巫峡音容断，路隔星河去住难。
莫道诗成无泪下，泪如泉滴亦须干。','',''),('quantangshi-33211','幼作','鄭愚','quantangshi','','卷34','台山初罢雾，岐海正分流。
渔浦扬来笛，鸿逵翼去舟。','',''),('quantangshi-33212','茶诗','鄭愚','quantangshi','','卷34','嫩芽香且灵，吾谓草中英。
夜臼和烟捣，寒炉对雪烹。
惟忧碧粉散，尝见绿花生。','',''),('quantangshi-33213','郡楼望九华歌','霍總','quantangshi','','卷34','楼上坐见九子峰，翠云赤日光溶溶。
有时朝昏变疎密，八峰和烟一峰出。
有时风卷天雨晴，聚立连连如弟兄。
阳乌生子偶成数，丹凤养雏同此名。
日日遥看机已静，未离尘躅思真境。
子明龙驾腾九垓，陵阳相对空崔嵬。
玉浆瑶草不可见，自有神仙风马来。','',''),('quantangshi-33214','塞下曲','霍總','quantangshi','','卷34','曾当一面战，频出九重围。
但见争锋处，长须得胜归。
雪沾旗尾落，风断节毛稀。
岂要铭燕石，平生重武威。','',''),('quantangshi-33215','关山月','霍總','quantangshi','','卷34','珠珑翡翠牀，白皙侍中郎。
五日来花下，双童问道傍。
到门车马狭，连夜管弦长。
每笑东家子，窥他宋玉墙。','',''),('quantangshi-33216','骢马','霍總','quantangshi','','卷34','青骊八尺高，侠客倚雄豪。
踏雪生珠汗，障泥护锦袍。
路傍看骤影，鞍底卷旋毛。
岂独连钱贵，酬恩更代劳。','',''),('quantangshi-33217','雉朝飞','霍總','quantangshi','','卷34','五色有名翚，清晨挟两雌。
羣羣飞自乐，步步饮相随。
觇叶逢人处，惊媒妬宠时。
绿毛春鬬尽，强敌愿君知。','',''),('quantangshi-33218','木芙蓉','霍總','quantangshi','','卷34','本自江湖远，常开霜露余。
争春候穠李，得水异红蕖。
孤秀曾无偶，当门幸不锄。
谁能政摇落，繁彩照堦除。','',''),('quantangshi-33219','采莲女','霍總','quantangshi','','卷34','舟中采莲女，两两催妆梳。
闻早渡江去，日高来起居。','',''),('quantangshi-33220','别僧','陳琡','quantangshi','','卷34','行若独轮车，常畏大道覆。
止若员底器，常恐他物触。
行止既如此，安得不离俗。','',''),('quantangshi-33221','早春残雪','裴虔餘','quantangshi','','卷34','霁日雕琼彩，幽庭减夜寒。
梅飘余片积，日堕晚光残。
零落偏依桂，霏微不掩兰。
阴林披雾縠，小沼破冰盘。
曲槛霜凝砌，疎篁玉碎竿。
已闻三径好，犹可访袁安。','',''),('quantangshi-33222','柳枝词咏篙水溅妓衣','裴虔餘','quantangshi','','卷34','半额微黄金缕衣，玉搔头褭凤双飞。
从教水溅罗裙湿，还道朝来行雨归。','',''),('quantangshi-33223','献淮南师','李嶸','quantangshi','','卷34','鸡树烟含瑞气凝，凤池波待玉山澄。
国人久倚东关望，拟筑沙堤到广陵。','',''),('quantangshi-33224','月','袁郊','quantangshi','','卷34','嫦娥窃药出人间，藏在蟾宫不放还。
后羿遍寻无觅处，谁知天上却容奸。','',''),('quantangshi-33225','霜','袁郊','quantangshi','','卷34','古今何事不思量，尽信邹生感彼苍。
但想燕山吹暖律，炎天岂不解飞霜。','',''),('quantangshi-33226','露','袁郊','quantangshi','','卷34','湛湛腾空下碧霄，地卑湿处更偏饶。
菅茅丰草皆霑润，不道良田有旱苗。','',''),('quantangshi-33227','云','袁郊','quantangshi','','卷34','楚甸尝闻旱魃侵，从龙应合解为霖。
荒淫却入阳台梦，惑乱怀襄父子心。','',''),('quantangshi-33228','游东观山','張叢','quantangshi','','卷34','岩岫碧孱颜，灵踪若可攀。
楼台烟霭外，松竹翠微间。
玉液寒深洞，秋光秀远山。','',''),('quantangshi-33229','掷卢作','馮衮','quantangshi','','卷34','八尺台盘照面新，千金一掷鬬精神。
合是赌时须赌取，不妨回首乞闲人。','',''),('quantangshi-33230','戏酒妓','馮衮','quantangshi','','卷34','醉眼从伊百度斜，是他家属是他家。
低声向道人知也，隔坐刚抛豆蔻花。','',''),('quantangshi-33231','老僧','鄭綮','quantangshi','','卷34','日照四山雪，老僧门未开。
冻瓶黏柱础，宿火陷炉灰。
童子病归去，鹿麑寒入来。
斋钟知渐近，枝鸟下生台。','',''),('quantangshi-33232','题卢州郡斋','鄭綮','quantangshi','','卷34','九衢尘里一书生，多达逢时拥斾旌。
醉里眼开金使字，紫旗风动耀天明。','',''),('quantangshi-33233','别郡后寄席中三兰','鄭綮','quantangshi','','卷34','淮淝两水不相通，隔岸临流望向东。
千颗泪珠无寄处，一时弹与渡前风。','',''),('quantangshi-33234','观山灯献徐尚书 一','溫庭皓','quantangshi','','卷34','一峰当胜地，万点照严城。
势异昆冈发，光疑玄圃生。
焚书翻见字，举燧不招兵。
况遇新春夜，何劳秉烛行。','',''),('quantangshi-33235','观山灯献徐尚书 二','溫庭皓','quantangshi','','卷34','九枝应并耀，午夜忽潜然。
景集青山外，萤分碧草前。
辉华侵月影，历乱写星躔。
望极高楼上，摇光满绮筵。','',''),('quantangshi-33236','观山灯献徐尚书 三','溫庭皓','quantangshi','','卷34','春山收暝色，爝火集余辉。
丽景饶红焰，祥光出翠微。
白榆行自比，青桂影相依。
唯有偷光客，追游欲忘归。','',''),('quantangshi-33237','梅','溫庭皓','quantangshi','','卷34','一树寒林外，何人此地栽。
春光先自暖，阳艳暗相催。
晓觉霜添白，寒迷月借开。
余香低惹袖，堕蘂逐流杯。
零落移新暖，飘扬上故台。
雪繁莺不识，风袅蝶空回。
羌吹应愁起，征徒异渴来。
莫贪题咏兴，商鼎待盐梅。','',''),('quantangshi-33238','言怀','高駢','quantangshi','','卷34','恨乏平戎策，慙登拜将坛。
手持金钺冷，身挂铁衣寒。
主圣扶持易，恩深报效难。
三边犹未静，何敢便休官。','',''),('quantangshi-33239','寄鄠杜李遂良处士','高駢','quantangshi','','卷34','小隐堪忘世上情，可能休梦入重城。
池边写字师前辈，座右题铭律后生。
吟社客归秦渡晚，醉乡渔去渼陂晴。
春来不得山中信，尽日无人傍水行。','',''),('quantangshi-33240','和王昭符进士赠洞庭赵先生','高駢','quantangshi','','卷34','为爱君山景最灵，角冠秋礼一坛星。
药将鸡犬云间试，琴许鱼龙月下听。
自要乘风随羽客，谁同种玉验仙经。
烟霞澹泊无人到，唯有渔翁过洞庭。','',''),('quantangshi-33241','依韵奉酬李迪','高駢','quantangshi','','卷34','柳下官资颜子居，闲情入骨若为除。
诗成斩将奇难敌，酒熟封侯快未如。
只见丝纶终日降，不知功业是谁书。
而今共饮醇滋味，消得揶揄势利疎。','',''),('quantangshi-33242','留别彰德军从事范校书','高駢','quantangshi','','卷34','无金寄与白头亲，节概犹夸似古人。
未出尘埃真落魄，不趋权势正因循。
桂攀明月曾观国，蓬转西风却问津。
匹马东归羡知己，燕王台上结交新。','',''),('quantangshi-33243','途次内黄马病寄僧舍呈诸友人','高駢','quantangshi','','卷34','官闲马病客深秋，肯学张衡咏四愁。
红叶寺多诗景致，白衣人尽酒交游。
依违讽刺因行得，澹泊供需不在求。
好与高阳结吟社，况无名迹达珠旒。','',''),('quantangshi-33244','遣兴','高駢','quantangshi','','卷34','浮世忙忙蚁子羣，莫嗔头上雪纷纷。
沈忧万种与千种，行乐十分无一分。
越外险巇防俗事，就中拘检信人文。
醉乡日月终须觅，去作先生号白云。','',''),('quantangshi-33245','南海神祠','高駢','quantangshi','','卷34','沧溟八千里，今古畏波涛。
此日征南将，安然渡万艘。','',''),('quantangshi-33246','送春','高駢','quantangshi','','卷34','水浅鱼争跃，花深鸟竞啼。
春光看欲尽，判却醉如泥。','',''),('quantangshi-33247','海翻','高駢','quantangshi','','卷34','几经人事变，又见海涛翻。
徒起如山浪，何曾洗至冤。','',''),('quantangshi-33248','筇竹杖寄僧','高駢','quantangshi','','卷34','坚轻筇竹杖，一枝有九节。
寄与沃洲人，闲步青山月。','',''),('quantangshi-33249','遣兴','高駢','quantangshi','','卷34','把盏非怜酒，持竿不为鱼。
唯应嵇叔夜，似我性慵疎。','',''),('quantangshi-33250','叹征人','高駢','quantangshi','','卷34','心坚胆壮箭头亲，十载沙场受苦辛。
力尽路傍行不得，广张红斾是何人。','',''),('quantangshi-33251','湘妃庙','高駢','quantangshi','','卷34','帝舜南巡去不还，二妃幽怨水云间。
当时珠泪垂多少，直到如今竹尚斑。','',''),('quantangshi-33252','赴安南却寄台司','高駢','quantangshi','','卷34','曾驱万马上天山，风去云回顷刻间。
今日海门南面事，莫教还似凤林关。','',''),('quantangshi-33253','闺怨','高駢','quantangshi','','卷34','人世悲欢不可知，夫君初破黑山归。
如今又献征南策，早晚催缝带号衣。','',''),('quantangshi-33254','马嵬驿','高駢','quantangshi','','卷34','玉颜虽掩马嵬尘，冤气和烟锁渭津。
蝉鬓不随銮驾去，至今空感往来人。','',''),('quantangshi-33255','宴犒蕃军有感','高駢','quantangshi','','卷34','蜀地恩留马嵬哭，烟雨蒙蒙春草绿。
满眼由来是旧人，那堪更奏梁州曲。','',''),('quantangshi-33256','寓怀','高駢','quantangshi','','卷34','关山万里恨难销，铁马金鞭出塞遥。
为问昔时青海畔，几人归到凤林桥。','',''),('quantangshi-33257','步虚词','高駢','quantangshi','','卷34','青溪道士人不识，上天下天鹤一只。
洞门深锁碧窗寒，滴露研朱点周易。','',''),('quantangshi-33258','赠歌者二首 一','高駢','quantangshi','','卷34','酒满金船花满枝，佳人立唱惨愁眉。
一声直入青云去，多少悲欢起此时。','',''),('quantangshi-33259','赠歌者二首 二','高駢','quantangshi','','卷34','公子邀欢月满楼，双成揭调唱伊州。
便从席上风沙起，直到阳关水尽头。','',''),('quantangshi-33260','入蜀','高駢','quantangshi','','卷34','万水千山音信希，空劳魂梦到京畿。
漫天岭上频回首，不见虞封泪满衣。','',''),('quantangshi-33261','边城听角','高駢','quantangshi','','卷34','席箕风起雁声秋，陇水边沙满目愁。
三会五更欲吹尽，不知凡白几人头。','',''),('quantangshi-33262','渭川秋望寄右军王特进','高駢','quantangshi','','卷34','长川终日碧潺湲，知道天河与地连。
凭寄两行朝阙泪，愿随流入御沟泉。','',''),('quantangshi-33263','山亭夏日','高駢','quantangshi','','卷34','绿树阴浓夏日长，楼台倒影入池塘。
水精帘动微风起，满架蔷薇一院香。','',''),('quantangshi-33264','蜀路感怀','高駢','quantangshi','','卷34','蜀山苍翠陇云愁，銮驾西巡陷几州。
唯有萦回深涧水，潺湲不改旧时流。','',''),('quantangshi-33265','残春遣兴','高駢','quantangshi','','卷34','画舸轻桡柳色新，摩诃池上醉青春。
不辞不为青春醉，只恐莺花也怪人。','',''),('quantangshi-33266','春日招宾','高駢','quantangshi','','卷34','花枝如火酒如饧，正好狂歌醉复醒。
对酒看花何处好，延和阁下碧筠亭。','',''),('quantangshi-33267','过天威径','高駢','quantangshi','','卷34','豺狼坑尽却朝天，战马休嘶瘴岭烟。
归路嶮巇今坦荡，一条千里直如弦。','',''),('quantangshi-33268','对花呈幕中','高駢','quantangshi','','卷34','海棠初发去春枝，首唱曾题七字诗。
今日能来花下饮，不辞频把使头旗。','',''),('quantangshi-33269','寄题罗浮别业','高駢','quantangshi','','卷34','不将真性染埃尘，为有烟霞伴此身。
带日长江好归信，博罗山下碧桃春。','',''),('quantangshi-33270','塞上曲二首 一','高駢','quantangshi','','卷34','二年边戍绝烟尘，一曲河湾万恨新。
从此凤林关外事，不知谁是苦心人。','',''),('quantangshi-33271','塞上曲二首 二','高駢','quantangshi','','卷34','陇上征夫陇下魂，死生同恨汉将军。
不知万里沙场苦，空举平安火入云。','',''),('quantangshi-33272','广陵宴次戏简幕宾','高駢','quantangshi','','卷34','一曲狂歌酒百分，蛾眉画出月争新。
将军醉罢无余事，乱把花枝折赠人。','',''),('quantangshi-33273','安南送曹别勑归朝','高駢','quantangshi','','卷34','云水苍茫日欲收，野烟深处鹧鸪愁。
知君万里朝天去，为说征南已五秋。','',''),('quantangshi-33274','对雪','高駢','quantangshi','','卷34','六出飞花入户时，坐看青竹变琼枝。
如今好上高楼望，盖尽人间恶路岐。','',''),('quantangshi-33275','访隐者不遇','高駢','quantangshi','','卷34','落花流水认天台，半醉闲吟独自来。
惆怅仙翁何处去，满庭红杏碧桃开。','',''),('quantangshi-33276','赴西川途经虢县作','高駢','quantangshi','','卷34','亚夫重过柳营门，路指岷峨隔暮云。
红额少年遮道拜，殷勤认得旧将军。','',''),('quantangshi-33277','锦城冩望','高駢','quantangshi','','卷34','蜀江波影碧悠悠，四望烟花匝郡楼。
不会人家多少锦，春来尽挂树梢头。','',''),('quantangshi-33278','太公庙','高駢','quantangshi','','卷34','青山长在境长新，寂寞持竿一水滨。
及得王师身已老，不知辛苦为何人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33279','边方春兴','高駢','quantangshi','','卷34','草色青青柳色浓，玉壶顷酒满金钟。
笙歌嘹亮随风去，知尽关山第几重。','',''),('quantangshi-33280','塞上寄家兄','高駢','quantangshi','','卷34','棣萼分张信使希，几多乡泪湿征衣。
笳声未断肠先断，万里胡天鸟不飞。','',''),('quantangshi-33281','写怀二首 一','高駢','quantangshi','','卷34','渔竿消日酒消愁，一醉忘情万事休。
却恨韩彭兴汉室，功成不向五湖游。','',''),('quantangshi-33282','写怀二首 二','高駢','quantangshi','','卷34','花满西园月满池，笙歌摇曳画船移。
如今暗与心相约，不动征旗动酒旗。','',''),('quantangshi-33283','池上送春','高駢','quantangshi','','卷34','持竿闲坐思沈吟，钓得江鳞出碧浔。
回首看花花欲尽，可怜寥落送春心。','',''),('quantangshi-33284','南征叙怀','高駢','quantangshi','','卷34','万里驱兵过海门，此生今日报君恩。
回期直待烽烟静，不遣征衣有泪痕。','',''),('quantangshi-33285','风筝','高駢','quantangshi','','卷34','夜静弦声响碧空，宫商信任往来风。
依稀似曲才堪听，又被移将别调中。','',''),('quantangshi-33286','平流园席上','高駢','quantangshi','','卷34','画舸摇烟水满塘，柳丝轻软小桃香。
却缘龙节为萦绊，好是狂时不得狂。','',''),('quantangshi-33287','闻河中王铎加都统','高駢','quantangshi','','卷34','炼汞烧铅四十年，至今犹在药炉前。
不知子晋缘何事，只学吹箫便得仙。','',''),('quantangshi-33288','句','高駢','quantangshi','','卷34','人间无限伤心事，不得尊前折一枝。
满宫多少承恩者，似有容华妾也无。
满身珠翠将何用，唯与豪家拂象牀。
何人种得西施花，千古春风开不尽。','',''),('quantangshi-33289','青楼曲','于濆','quantangshi','','卷34','青楼临大道，一上一回老。
所思终不来，极目伤春草。','',''),('quantangshi-33290','塞下曲','于濆','quantangshi','','卷34','紫塞晓屯兵，黄沙披甲卧。
战鼓声未齐，乌鸢已相贺。
燕然山上云，半是离乡魂。
卫霍待富贵，岂能无干坤。','',''),('quantangshi-33291','山村晓思','于濆','quantangshi','','卷34','开门省禾黍，邻翁水头住。
今朝南涧波，昨夜西川雨。
牧童披短蓑，腰笛期烟渚。
不问水边人，骑牛傍山去。','',''),('quantangshi-33292','马嵬驿','于濆','quantangshi','','卷34','常经马嵬驿，见说坡前客。
一从屠贵妃，生女愁倾国。
是日芙蓉花，不如秋草色。
当时嫁匹夫，不妨得头白。','',''),('quantangshi-33293','苦辛吟','于濆','quantangshi','','卷34','壠上扶犂儿，手种腹长饥。
窗下抛梭女，手织身无衣。
我愿燕赵姝，化为嫫母姿。
一笑不值钱，自然家国肥。','',''),('quantangshi-33294','野蚕','于濆','quantangshi','','卷34','野蚕食青桑，吐丝亦成茧。
无功及生人，何异偷饱暖。
我愿均尔丝，化为寒者衣。','',''),('quantangshi-33295','秦原览古','于濆','quantangshi','','卷34','耕者戮力地，龙虎曾角逐。
火德道将亨，夜逢虵母哭。
昔日望夷宫，是处寻桑谷。
汉祖竟为龙，赵高徒指鹿。
当时行路人，已合伤心目。
汉祚又千年，秦原草还绿。','',''),('quantangshi-33296','古宴曲','于濆','quantangshi','','卷34','雉扇合蓬莱，朝车回紫陌。
重门集嘶马，言宴金张宅。
燕娥奉巵酒，低鬟若无力。
十户手胼胝，凤凰钗一只。
高楼齐下视，日照罗衣色。
笑指负薪人，不信生中国。','',''),('quantangshi-33297','南越谣','于濆','quantangshi','','卷34','迢迢东南天，巨浸无津壖。
雄风卷昏雾，干戈满楼船。
此时尉佗心，儿童待幽燕。
三寸陆贾舌，万里汉山川。
若令交趾货，尽生虞芮田。
天意苟如此，遐人谁肯怜。','',''),('quantangshi-33298','述己叹','于濆','quantangshi','','卷34','不长不成人，及长老逼身。
履善本求乐，及善尤苦辛。
如何幽并儿，一箭取功勋。','',''),('quantangshi-33299','辽阳行','于濆','quantangshi','','卷34','辽阳在何处，妾欲随君去。
义合齐死生，本不夸机杼。
谁能守空闺，虚问辽阳路。','',''),('quantangshi-33300','旅馆秋思','于濆','quantangshi','','卷34','旅馆坐孤寂，出门成苦吟。
何事觉归晚，黄花秋意深。
寒蝶恋衰草，轸我离乡心。
更见庭前树，南枝巢宿禽。','',''),('quantangshi-33301','长城','于濆','quantangshi','','卷34','秦皇岂无德，蒙氏非不武。
岂将版筑功，万里遮胡虏。
团沙世所难，作垒明知苦。
死者倍堪伤，僵尸犹抱杵。
十年居上郡，四海谁为主。
纵使骨为尘，冤名不入土。','',''),('quantangshi-33302','田翁叹','于濆','quantangshi','','卷34','手植千树桑，文杏作中梁。
频年徭役重，尽属富家郎。
富家田业广，用此买金章。
昨日门前过，轩车满垂杨。
归来说向家，儿孙竟咨嗟。
不见千树桑，一浦芙蓉花。','',''),('quantangshi-33303','沙场夜','于濆','quantangshi','','卷34','城上更声发，城下杵声歇。
征人烧断蓬，对泣沙中月。
耕牛朝挽甲，战马夜衔铁。
士卒浣戎衣，交河水为血。
轻裘两都客，洞房愁宿别。
何况远辞家，生死犹未决。','',''),('quantangshi-33304','里中女','于濆','quantangshi','','卷34','吾闻池中鱼，不识海水深。
吾闻桑下女，不识华堂阴。
贫窗苦机杼，富家鸣杵砧。
天与双明眸，只教识蒿簪。
徒惜越娃貌，亦蕴韩娥音。
珠玉不到眼，遂无奢侈心。
岂知赵飞燕，满髻钗黄金。','',''),('quantangshi-33305','寒食','于濆','quantangshi','','卷34','二月野中芳，凡花亦能香。
素娥哭新冢，樵柯鸣柔桑。
田父引黄犬，寻狐上高冈。
坟前呼犬归，不知头似霜。','',''),('quantangshi-33306','边游录戍卒言','于濆','quantangshi','','卷34','二十属卢龙，三十防沙漠。
平生爱功业，不觉从军恶。
今来客鬓改，知学弯弓错。
赤肉痛金疮，他人成卫霍。
目断望君门，君门苦寥廓。','',''),('quantangshi-33307','古征战','于濆','quantangshi','','卷34','高峰凌青冥，深穴万丈坑。
皇天自山谷，焉得人心平。
齐鲁足兵甲，燕赵多娉婷。
仍闻丽水中，日日黄金生。
苟非夷齐心，岂得无战争。','',''),('quantangshi-33308','山村叟','于濆','quantangshi','','卷34','古凿岩居人，一廛称有产。
虽霑巾覆形，不及贵门犬。
驱牛耕白石，课女经黄茧。
岁暮霜霰浓，画楼人饱暖。','',''),('quantangshi-33309','戍客南归','于濆','quantangshi','','卷34','北别黄榆塞，南归白云乡。
孤舟下彭蠡，楚月沈沧浪。
为子惜功业，满身刀箭疮。
莫渡汨罗水，回君忠孝肠。','',''),('quantangshi-33310','经馆娃宫','于濆','quantangshi','','卷34','馆娃宫畔顾，国变生娇妒。
句践胆未尝，夫差心已误。
吴亡甘已矣，越胜今何处？
当时二国君，一种江边墓。','',''),('quantangshi-33311','村居晏起','于濆','quantangshi','','卷34','村舍少闻事，日高犹闭关。
起来花满地，戴胜鸣桑间。
居安即永业，何者为故山。
朱门与蓬户，六十头尽斑。','',''),('quantangshi-33312','感怀','于濆','quantangshi','','卷34','采薇易为山，何必登首阳。
濯缨易为水，何必泛沧浪。
贵崇已难慕，谄笑何所长。
东堂桂欲空，犹有收萤光。','',''),('quantangshi-33313','金谷感怀','于濆','quantangshi','','卷34','黄金骄石崇，与晋争国力。
更欲住人间，一日买不得。
行为忠信主，身是文章宅。
四者俱不闻，空传堕楼客。','',''),('quantangshi-33314','恨从军','于濆','quantangshi','','卷34','不嫁白衫儿，爱君新紫衣。
早知遽相别，何用假光辉。
已闻都万骑，又道出重围。
一轴金装字，致君终不归。','',''),('quantangshi-33315','烧金曲','于濆','quantangshi','','卷34','天寿畏不永，烧金希长年。
积土培枯根，自谓松柏坚。
南陌试腰褭，西楼歌婵娟。
岂知蔓草中，日日开夜泉。','',''),('quantangshi-33316','子从军','于濆','quantangshi','','卷34','男作乡中丁，女作乡男妇。
南村与北里，日日见父母。
岂似从军儿，一去便白首。
何当铸剑戟，尽得丁男力。','',''),('quantangshi-33317','越溪女','于濆','quantangshi','','卷34','会稽山上云，化作越溪人。
枉破吴王国，徒为西子身。
江边浣纱伴，黄金扼双腕。
倏忽不相期，思倾赵飞燕。
妾家基业薄，空有如花面。
嫁尽绿窗人，独自盘金线。','',''),('quantangshi-33318','巫山高','于濆','quantangshi','','卷34','何山无朝云，彼云亦悠扬。
何山无暮雨，彼雨亦苍茫。
宋玉恃才者，凭虚构高唐。
自垂文赋名，荒淫归楚襄。
峨峨十二峰，永作妖鬼乡。','',''),('quantangshi-33319','织素谣','于濆','quantangshi','','卷34','贫女苦筋力，缲丝夜夜织。
万梭为一素，世重韩娥色。
五侯初买笑，建章方落籍。
一曲古凉州，六亲长血食。
劝尔画长眉，学歌饱亲戚。','',''),('quantangshi-33320','拟古讽','于濆','quantangshi','','卷34','洛阳大道傍，甲第何深邃。
南亩无一廛，东园有余地。
春溪化桃李，秋沼生荷芰。
草木本无情，此时如有为。
旱苗当垄死，流水资嘉致。
余心甘至愚，不会皇天意。','',''),('quantangshi-33321','赠太行开路者','于濆','quantangshi','','卷34','手斸太行山，心齐太行巅。
斸尽太行险，君心更摩天。
何如回苦辛，自凿东臯田。','',''),('quantangshi-33322','戍卒伤春','于濆','quantangshi','','卷34','连年戍边塞，过却芳菲节。
东风气力尽，不减阴山雪。
萧条柳一株，南枝叶微发。
为带故乡情，依依籍攀折。
晚风吹碛沙，夜泪啼乡月。
凌烟阁上人，未必皆忠烈。','',''),('quantangshi-33324','早发','于濆','quantangshi','','卷34','绿野含曙光，东北云如茜。
栖鸦林际起，落月水中见。
此身何自苦，日日凌霜霰。
流苏帐里人，犹在阳台畔。','',''),('quantangshi-33325','季夏逢朝客','于濆','quantangshi','','卷34','浐水桃李熟，杜曲芙蓉老。
九天休沐归，腰玉垂杨道。
避路回绮罗，迎风嘶騕褭。
岂知山谷中，日日吹瑶草。','',''),('quantangshi-33326','陇头水','于濆','quantangshi','','卷34','行人何旁徨，陇头水呜咽。
寒沙战鬼愁，白骨风霜切。
薄日朦胧秋，怨气阴云结。
杀成边将名，名着生灵灭。','',''),('quantangshi-33327','古别离 一','于濆','quantangshi','','卷34','入室少情意，出门多路岐。
黄鹤有归日，荡子无还时。
人谁无分命，妾身何太奇。
君为东南风，妾作西北枝。
青楼邻里妇，终年画长眉。
自倚对良匹，笑妾空罗帏。','',''),('quantangshi-33328','古别离 二','于濆','quantangshi','','卷34','郎本东家儿，妾本西家女。
对门中道间，终谓无离阻。
岂知中道间，遣作空闺主。
自是爱封侯，非关备胡虏。','',''),('quantangshi-33329','拟古意','于濆','quantangshi','','卷34','白玉若无玷，花颜须及时。
国色久在室，良媒亦生疑。
鸦鬟未成髻，鸾镜徒相知。
翻慙效颦者，却笑从人迟。','',''),('quantangshi-33330','陇头吟','于濆','quantangshi','','卷34','借问陇头水，终年恨何事。
深疑呜咽声，中有征人泪。
自古蕴长策，况我非才智。
无计谢潺湲，一宵空不寐。','',''),('quantangshi-33331','思归引','于濆','quantangshi','','卷34','不耕南亩田，为爱东堂桂。
身同树上花，一落又经岁。
交亲日相薄，知己恩潜替。
日开十二门，自是无归计。','',''),('quantangshi-33332','秦富人','于濆','quantangshi','','卷34','高高起华堂，远远引流水。
粪土视金珍，犹嫌未奢侈。
陋巷满蓬蒿，谁怜有颜子。','',''),('quantangshi-33333','对花','于濆','quantangshi','','卷34','花开蝶满枝，花落蝶还稀。
惟有旧巢燕，主人贫亦归。','',''),('quantangshi-33334','宫怨','于濆','quantangshi','','卷34','妾家望江口，少年家财厚。
临江起珠楼，不卖文君酒。
当年乐贞独，巢燕时为友。
父兄未许人，畏妾事姑舅。
西墙邻宋玉，窥见妾眉宇。
一旦及天聪，恩光生户牖。
谓言入汉宫，富贵可长久。
君王纵有情，不奈陈皇后。
谁怜颊似桃，孰知腰胜柳。
今日在长门，从来不如丑。','',''),('quantangshi-33335','登越王楼即事','牛徵','quantangshi','','卷34','危楼送远目，信美奈乡情。
转岸孤舟疾，衔山落照明。
萧条看草色，惆怅认江声。
谁会登临恨，从军白发生。','',''),('quantangshi-33336','及第后寄梁烛处士','伊璠','quantangshi','','卷34','绣毂寻芳许史家，独将羁事达江沙。
十年辛苦一枝桂，二月艳阳千树花。
鹏化四溟归碧落，鹤栖三岛接青霞。
同袍不得同游翫，今对春风日又斜。','',''),('quantangshi-33337','春诗','蕭遘','quantangshi','','卷34','南国韶光早，春风送腊来。
水堤烟报柳，山寺雪惊梅。
练色铺江晚，潮声逐渚回。','',''),('quantangshi-33338','和王侍中谒张恶子庙','蕭遘','quantangshi','','卷34','青骨祀吴谁让德，紫华居越亦知名。
未闻一劒传唐主，长拥千山护蜀城。
斩马威棱应扫荡，截蛟锋刃俟升平。
酇侯为国亲箫鼓，堂上神筹更布兵。','',''),('quantangshi-33339','成都','蕭遘','quantangshi','','卷34','月晓已开花市合，江平偏见竹簰多。
好教载取芳菲树，剩照岷天瑟瑟波。','',''),('quantangshi-33340','句','蕭遘','quantangshi','','卷34','吾家九叶相，尽继明时出。','',''),('quantangshi-33341','策试夜潜纪长句于都堂西南隅 一','韋承貽','quantangshi','','卷34','褒衣博带满尘埃，独自都堂纳卷回。
蓬巷几时闻吉语，棘篱何日免重来。
三条烛尽钟初动，九转丹成鼎未开。
残月渐低人扰扰，不知谁是谪仙才。','',''),('quantangshi-33342','策试夜潜纪长句于都堂西南隅 二','韋承貽','quantangshi','','卷34','白莲千朵照廊明，一片升平雅颂声。
才唱第三条烛尽，南宫风月画难成。','',''),('quantangshi-33343','诏放云南子弟还国','鄭洪業','quantangshi','','卷34','德被陪臣子，仁垂圣主恩。
雕题辞凤阙，丹服出金门。
有泽沾殊俗，无征及犷𤟤。
铜梁分汉土，玉垒驾鸾轩。
瘴岭蚕丛盛，巴江越嶲垠。
万方同感化，岂独自南蕃。','',''),('quantangshi-33344','中秋夜思郑延美有作','孫緯','quantangshi','','卷34','中秋中夜月，世说慴妖精。
顾兔云初蔽，长虵谁与勍。
未追良友翫，安用玉轮盈。
此意人谁喻，裁时穿禁城。','',''),('quantangshi-33345','清晓卷帘','歐陽玭','quantangshi','','卷34','清晓意未惬，卷帘时一吟。
槛虚花气密，地暖竹声深。
秀色还朝暮，浮云自古今。
石泉惊已跃，会可洗幽心。','',''),('quantangshi-33346','巴陵','歐陽玭','quantangshi','','卷34','孤城向夕原，春入景初暄。
绿树低官舍，青山在县门。
楼台疑结蜃，枕席更闻猨。
客路何曾定，栖迟欲断魂。','',''),('quantangshi-33347','榆溪道上','歐陽玭','quantangshi','','卷34','初日在斜溪，山云片片低。
乡愁梦里失，马色望中迷。
涧底凄泉气，岩前遍绿荑。
非关秦塞去，无事候晨鸡。','',''),('quantangshi-33348','新岭临眺寄连总进士','歐陽玭','quantangshi','','卷34','关势遥临海，峰峦半入云。
烟中独鸟下，潭上杂花熏。
寄远悲春草，登临忆使君。
此时还极目，离思更纷纷。','',''),('quantangshi-33349','幽轩','歐陽玭','quantangshi','','卷34','幽轩斜映山，空涧复潺潺。
重叠岩峦趣，遥来窗户间。
桃花飘岫幌，燕子语松关。
衣桁侵池翠，阶痕露藓斑。
临风清瑟奏，对客白云闲。
眷恋青春色，含毫俯碧湾。','',''),('quantangshi-33350','社日村居','張演','quantangshi','','卷34','鹅湖山下稻粱肥，豚穽鸡栖对掩扉。
桑拓影斜春社散，家家扶得醉人归。','',''),('quantangshi-33351','吊孟昌图','裴澈','quantangshi','','卷34','一章何罪死何名，投水惟君与屈平。
从此蜀江烟月夜，杜鹃应作两般声。','',''),('quantangshi-33352','婕妤怨','翁綬','quantangshi','','卷34','谗谤潜来起百忧，朝承恩宠暮仇雠。
火烧白玉非因玷，霜剪红兰不待秋。
花落昭阳谁共辇，月明长信独登楼。
繁华事逐东流水，团扇悲歌万古愁。','',''),('quantangshi-33353','陇头吟','翁綬','quantangshi','','卷34','陇水潺湲陇树黄，征人陇上尽思乡。
马嘶斜[日]朔风急，雁过寒云边思长。
残月出林明劒戟，平沙隔水见牛羊。
横行俱是封侯者，谁斩楼兰献未央。','',''),('quantangshi-33354','关山月','翁綬','quantangshi','','卷34','裴回汉月满边州，照尽天涯到陇头。
影转银河寰海静，光分玉塞古今愁。
笳吹远戍孤烽灭，雁下平沙万里秋。
况是故园摇落夜，那堪少妇独登楼。','',''),('quantangshi-33355','雨雪曲','翁綬','quantangshi','','卷34','边声四合殷河流，雨雪飞来遍陇头。
铁岭探人迷鸟道，阴山飞将湿貂裘。
斜飘旌斾过戎帐，半杂风沙入戍楼。
一自塞垣无李蔡，何人为解北门忧。','',''),('quantangshi-33356','行路难','翁綬','quantangshi','','卷34','行路艰难不复歌，故人荣达我蹉跎。
双轮晚上铜台雪，一叶春浮瘴海波。
自古要津皆若此，方今失路欲如何。
君看西汉翟丞相，凤沼朝辞暮雀罗。','',''),('quantangshi-33357','折杨柳','翁綬','quantangshi','','卷34','紫陌金堤映绮罗，游人处处动离歌。
阴移古戍迷芳草，花带残阳落远波。
台上少年吹白雪，楼中思妇歛青蛾。
殷勤攀折赠行客，此去关山雨雪多。','',''),('quantangshi-33358','咏酒','翁綬','quantangshi','','卷34','逃暑迎春复送秋，无非绿蚁满杯浮。
百年莫惜千回醉，一盏能消万古愁。
几为芳菲眠细草，曾因雨雪上高楼。
平生名利关身者，不识狂歌到白头。','',''),('quantangshi-33359','白马','翁綬','quantangshi','','卷34','渥洼龙种雪霜同，毛骨天生胆气雄。
金埒乍调光照地，玉关初别远嘶风。
花明锦襜垂杨下，露湿朱缨细草中。
一夜羽书催转战，紫髯骑出佩騂弓。','',''),('quantangshi-33360','句','翁綬','quantangshi','','卷34','海国欧乡浙水东，暂烦良守此凭熊。','',''),('quantangshi-33361','中秋月','潘緯','quantangshi','','卷34','古今逢此夜，共冀泬㵳明。
岂是月华别，祗应秋气清。
影当中土正，轮对八荒平。
寻客徒留望，璇玑自有程。','',''),('quantangshi-33362','琴','潘緯','quantangshi','','卷34','客来鸣素琴，惆怅对遗音。
一曲起于古，几人听到今。
尽含风霭远，自泛月烟深。
风续水山操，坐生方外心。','',''),('quantangshi-33363','句','潘緯','quantangshi','','卷34','篆经千古涩，影泻一堂寒。','',''),('quantangshi-33364','九日卫使君筵上作','武瓘','quantangshi','','卷34','佳晨登赏喜还乡，谢宇开筵晚兴长。
满眼黄花初泛酒，隔烟红树欲迎霜。
千家门户笙歌发，十里江山白鸟翔。
共贺安人丰乐岁，幸陪珠履侍银章。','',''),('quantangshi-33365','劝酒','武瓘','quantangshi','','卷34','劝君金屈巵，满酌不须辞。
花发多风雨，人生足别离。','',''),('quantangshi-33366','感事','武瓘','quantangshi','','卷34','花开蝶满枝，花谢蝶还稀。
惟有旧巢燕，主人贫亦归。','',''),('quantangshi-33367','重归宜春偶成十六韵寄朝中知己','袁皓','quantangshi','','卷34','水香甘似醴，知是入袁溪。
黄竹成丛密，青萝夹岸低。
暖流鸂鶒戏，深树鹧鸪啼。
黄犬惊迎客，青牛困卧泥。
有村皆绩纺，无地不耕犂。
乡曲多耆旧，逢迎尽杖藜。
殷勤倾白酒，相劝有黄鸡。
归老官知忝，还乡路不迷。
直言干忌讳，权路耻依栖。
拙学趋时态，闲思与牧齐。
稻粮饶燕雀，江海溢凫鹥。
昔共逢离乱，今来息鼓鼙。
恩仁霑品物，教化及雕题。
上贡贞元禄，曾叨宠记批。
何须归紫禁，便是到丹梯。
珍重长安道，从今息马嘶。','',''),('quantangshi-33368','及第后作','袁皓','quantangshi','','卷34','金榜高悬姓字真，分明折得一枝春。
蓬瀛乍接神仙侣，江海回思耕钓人。
九万抟扶排羽翼，十年辛苦涉风尘。
升平时节逢公道，不觉龙门是嶮津。','',''),('quantangshi-33369','重归宜春经过萍川题梵林寺','袁皓','quantangshi','','卷34','梵林遗址在松萝，四十年来两度过。
滤水东奔彭蠡浪，萍川西注洞庭波。
村烟不改居人换，官路无穷行客多。
拖紫腰金成底事，凭阑惆怅欲如何。','',''),('quantangshi-33370','寄岳阳严使君','袁皓','quantangshi','','卷34','得意东归过岳阳，桂枝香惹蘂珠香。
也知暮雨生巫峡，争奈朝云属楚王。
万恨只凭期尅手，寸心唯系别离肠。
南亭宴罢笙歌散，回首烟波路渺茫。','',''),('quantangshi-33371','赋得郎官上应列宿','公乘億','quantangshi','','卷34','北极伫文昌，南宫晓拜郎。
紫泥乘帝泽，银印佩天光。
纬结三台侧，钩连四辅傍。
佐商依傅说，仕汉笑冯唐。
委佩摇秋色，峨冠带晚霜。
自然符列象，千古耀岩廊。','',''),('quantangshi-33372','春风扇微和','公乘億','quantangshi','','卷34','丽日催迟景，和风扇早春。
暖浮丹凤阙，韶媚黑龙津。
澹荡迎仙仗，霏微送画轮。
绿摇宫柳散，红待禁花新。
舞席潜回雪，歌筵暗起尘。
幸当阳候律，一顾及佳晨。','',''),('quantangshi-33373','赋得秋菊有佳色','公乘億','quantangshi','','卷34','陶令篱边菊，秋来色转佳。
翠攒千片叶，金剪一枝花。
蘂逐蜂须乱，英随蝶翅斜。
带香飘绿绮，和酒上乌纱。
散漫摇霜彩，娇妍漏日华。
芳菲彭泽见，更称在谁家。','',''),('quantangshi-33374','赋得临江迟来客','公乘億','quantangshi','','卷34','江上晚沈沈，烟波一望深。
向来殊未至，何处拟相寻。
柳结重重眼，萍翻寸寸心。
暮山期共眺，寒渚待同临。
北去鱼无信，南飞雁绝音。
思君不可见，使我独愁吟。','',''),('quantangshi-33375','句','公乘億','quantangshi','','卷34','十上十年皆落第，一家一半已成尘。','',''),('quantangshi-33376','九华山谣','王季文','quantangshi','','卷34','九华峥嵘占南陆，莲花擢本山半腹。
翠屏横截万里天，瀑水落深千丈玉。
云梯石磴入杳冥，俯看四极如中庭。
丹崖压下庐霍势，白日隐出牛斗星。
杉松一岁抽数尺，琼草夤缘秀层壁。
南风拂晓烟雾开，满山葱蒨铺鲜碧。
雷霆往往从地发，龙卧豹藏安可别。
峻极遥看戛昊苍，挺生岂得无才杰。
神仙惮险莫敢登，驭风驾鹤循丘陵。
阳乌不见峰顶树，大火尚结岩中冰。
灵光爽气曛复旭，晴天倒影西江渌。
具区彭蠡夹两傍，正可别作一岳当少阳。','',''),('quantangshi-33377','青出蓝','王季文','quantangshi','','卷34','芳蓝滋匹帛，人力半天经。
浸润加新气，光辉胜本青。
还同冰出水，不共草为萤。
翻覆依襟上，偏知造化灵。','',''),('quantangshi-33378','题青龙精舍','盧駢','quantangshi','','卷34','寿夭虽云命，荣枯亦大偏。
不知雷氏劒，何处更冲天。','',''),('quantangshi-33379','感事','王鐐','quantangshi','','卷34','击石易得火，扣人难动心。
今日朱门者，曾恨朱门深。','',''),('quantangshi-33380','退朝望终南山','李拯','quantangshi','','卷34','紫宸朝罢缀鸳鸾，丹凤楼前驻马看。
惟有终南山色在，晴明依旧满长安。','',''),('quantangshi-33381','月中桂树','顧封人','quantangshi','','卷34','芬馥天边桂，扶疎在月中。
能齐大椿长，不与小山同。
皎皎舒华色，亭亭丽碧空。
亏盈宁委露，摇落不关风。
岁晚花应发，春余质讵丰。
无因遂攀赏，徒欲望青葱。','',''),('quantangshi-33382','和陆鲁望白菊','司馬都','quantangshi','','卷34','耻共金英一例开，素芳须待早霜催。
绕篱看见成瑶圃，泛酒须迷傍玉杯。
映水好将苹作伴，犯寒疑与雪为媒。
夫君每尚风流事，应为徐妃致此栽。','',''),('quantangshi-33383','送羊振文先辈往桂阳归觐','司馬都','quantangshi','','卷34','此去欢荣冠士林，离筵休恨酒杯深。
云梯万仞初高步，月桂余香尚满襟。
鸣棹晓冲苍霭发，落帆寒动白华吟。
君家祖德惟清苦，却笑当时问绢心。','',''),('quantangshi-33384','书边事','李昌符','quantangshi','','卷34','朔野烟尘起，天军又举戈。
阴风向晚急，杀气入秋多。
树尽禽栖草，冰坚路在河。
汾阳无继者，羌虏肯先和。','',''),('quantangshi-33385','远归别墅','李昌符','quantangshi','','卷34','马省曾行处，连嘶渡晚河。
忽惊乡树出，渐识路人多。
细径穿禾黍，颓垣压薜萝。
乍归犹似客，邻叟亦相过。','',''),('quantangshi-33386','题友人屋','李昌符','quantangshi','','卷34','松底诗人宅，闲门远岫孤。
数家分小径，一水截平芜。
竹节偶相对，鸟名多自呼。
爱君真静者，欲去又踟蹰。','',''),('quantangshi-33387','赠同游','李昌符','quantangshi','','卷34','此来风雨后，已觉减年华。
若待皆无事，应难更有花。
管弦临夜急，榆柳向江斜。
且莫看归路，同须醉酒家。','',''),('quantangshi-33388','送人出塞','李昌符','quantangshi','','卷34','北风吹雨雪，举目已凄凄。
战鬼秋频哭，征鸿夜不栖。
沙平关路直，碛广郡楼低。
此去非东鲁，人多事鼓鼙。','',''),('quantangshi-33389','寻僧元皎因赠','李昌符','quantangshi','','卷34','此生迷有着，因病得寻师。
话尽山中事，归当月上时。
高松连寺影，亚竹入窗枝。
闲忆草堂路，相逢非素期。','',''),('quantangshi-33390','下第后蒙侍郎示意指于新先辈宣恩感谢','李昌符','quantangshi','','卷34','才薄命如此，自嗟兼自疑。
遭逢好文日，黜落至公时。
倚玉甘无路，穿杨却未期。
更慙君侍坐，问许可言诗。','',''),('quantangshi-33391','夜泊渭津','李昌符','quantangshi','','卷34','漂漂东去客，一宿渭城边。
远处星垂岸，中流月满船。
凉归夜深簟，秋入雨余天。
渐觉家山小，残程尚几年。','',''),('quantangshi-33392','晚夏逢友人','李昌符','quantangshi','','卷34','一别同袍友，相思已十年。
长安多在客，久病忽闻蝉。
骤雨才沾地，阴云不徧天。
微凉堪话旧，移榻晚风前。','',''),('quantangshi-33393','秋中夜坐','李昌符','quantangshi','','卷34','空庭吟坐久，爽气入荷衣。
病叶先秋落，惊禽背月飞。
瘴云晴未散，戍客老将依。
为应金门策，多应说战机。','',''),('quantangshi-33394','旅游伤春','李昌符','quantangshi','','卷34','酒醒乡关远，迢迢听漏终。
曙分林影外，春尽雨声中。
鸟思江村路，花残野岸风。
十年成底事，羸马倦西东。','',''),('quantangshi-33395','得远书','李昌符','quantangshi','','卷34','故人居谪宦，今日一书来。
良久惊兼喜，殷勤卷更开。
瘴云沉去雁，江雨促新梅。
满纸殊乡泪，非冤不可哀。','',''),('quantangshi-33396','赠同席','李昌符','quantangshi','','卷34','四座列吾友，满园花照衣。
一生知几度，后到拟先归。
急管侵诸乐，严城送落晖。
当欢莫离席，离席却欢稀。','',''),('quantangshi-33397','赠供奉僧玄观','李昌符','quantangshi','','卷34','自得曹溪法，诸经更不看。
已降禅侣久，兼作帝师难。
夜木侵檐黑，秋灯照雨寒。
如何嫌有着，一念在林峦。','',''),('quantangshi-33398','送琴客','李昌符','quantangshi','','卷34','楚客抱离思，蜀琴留恨声。
坐来新月上，听久觉秋生。
夜静骚人语，天高别鹤鸣。
因君兴一叹，竟夕意难平。','',''),('quantangshi-33399','别谪者','李昌符','quantangshi','','卷34','此地闻犹恶，人言是所之。
一家书绝久，孤驿梦成迟。
八月三湘道，闻猿冒雨时。
不须祠楚相，臣节转堪疑。','',''),('quantangshi-33400','行思','李昌符','quantangshi','','卷34','千里岂云去，欲归如路穷。
人间无暇日，马上又秋风。
破月衔高岳，流星拂晓空。
此时皆在梦，行色独怱怱。','',''),('quantangshi-33401','感怀题从舅宅','李昌符','quantangshi','','卷34','郗家庭树下，几度醉春风。
今日花还发，当时事不同。
流言应未息，直道竟难通。
徒遣相思者，悲歌向暮空。','',''),('quantangshi-33402','与友人会','李昌符','quantangshi','','卷34','蝉吟槐蘂落，的的是愁端。
病觉离家远，贫知处事难。
真交无所隐，深语有余欢。
未必闻歌吹，羁心得暂宽。','',''),('quantangshi-33403','赠春游侣','李昌符','quantangshi','','卷34','密林多暗香，轻吹送余芳。
啼鸟愁春尽，游人喜日长。
浮云横暮色，新雨洗韶光。
欲散垂□恨，应须入醉乡。','',''),('quantangshi-33404','送人游边','李昌符','quantangshi','','卷34','愁指萧关外，风沙入远程。
马行初有迹，雨落竟无声。
地理全归汉，天威不在兵。
西京逢故老，暗喜复时平。','',''),('quantangshi-33405','寄栖白上人','李昌符','quantangshi','','卷34','剪髪兼成隐，将心更属文。
无憀对豪客，不拜谒吾君。
画壁惟泉石，经窗半典坟。
归林幽鸟狎，乞食病僧分。
默坐终清夜，凝思念碧云。
相逢应未卜，余正走嚣氛。','',''),('quantangshi-33406','送人入新罗使','李昌符','quantangshi','','卷34','鸡林君欲去，立册付星轺。
越海程难计，征帆影自飘。
望乡当落日，怀阙羡回潮。
宿雾蒙青嶂，惊波荡碧霄。
春生阳气早，天接祖州遥。
愁约三年外，相迎上石桥。','',''),('quantangshi-33407','咏铁马鞭','李昌符','quantangshi','','卷34','汉将临流得铁鞭，鄂侯名字旧雕镌。
须为圣代无双物，肯逐将军卧九泉。
汗马不侵诛虏血，神功今见补亡篇。
时来终荐明君用，莫叹沉埋二百年。','',''),('quantangshi-33408','送友人','李昌符','quantangshi','','卷34','举世谁能与事期，解携多是正欢时。
人间不遣有名利，陌上始应无别离。
晚渡待船愁立久，乱山投店独行迟。
我今漂泊还如此，江劒相逢亦未知。','',''),('quantangshi-33409','南潭','李昌符','quantangshi','','卷34','匝岸青芜掩古苔，面山亭树枕潭开。
有时弦管收筵促，无数凫鹥逆浪来。
路入龙祠羣木老，风惊渔艇一声回。
人传郭恽多游此，谁见当初泛玉杯。','',''),('quantangshi-33410','秋夜作','李昌符','quantangshi','','卷34','数亩池塘近杜陵，秋天寂寞夜云凝。
芙蓉叶上三更雨，蟋蟀声中一点灯。
迹避险巇翻失路，心归闲澹不因僧。
既逢上国陈诗日，长守林泉亦未能。','',''),('quantangshi-33411','客恨','李昌符','quantangshi','','卷34','古原南北旧萧疎，高木风多小雪余。
半夜病吟人寝后，百年闲事酒醒初。
频招兄弟同佳节，已有兵戈隔远书。
肥马王孙定相笑，不知岐路厌樵渔。','',''),('quantangshi-33412','三月尽日','李昌符','quantangshi','','卷34','江头从此管弦稀，散尽游人独未归。
落日已将春色去，残花应逐夜风飞。','',''),('quantangshi-33413','绿珠咏','李昌符','quantangshi','','卷34','洛阳佳丽与芳华，金谷园中见百花。
谁遣当年坠楼死，无人巧笑破孙家。','',''),('quantangshi-33414','赠别','李昌符','quantangshi','','卷34','又将书劒出孤舟，尽日停桡结远愁。
莫道江波话离别，江波一去不回流。','',''),('quantangshi-33415','闷书','李昌符','quantangshi','','卷34','病来难处早秋天，一径无人树有蝉。
归计未成书半卷，中宵多梦昼多眠。','',''),('quantangshi-33416','伤春','李昌符','quantangshi','','卷34','即是春风尽，仍霑夜雨归。
明朝更来此，兼恐落花稀。','',''),('quantangshi-33417','登临洮望萧关','李昌符','quantangshi','','卷34','渐觉风沙暗，萧关欲到时。
儿童能探火，妇女解缝旗。
川少衔鱼鹭，林多带箭麋。
暂来戎马地，不敢苦吟诗。','',''),('quantangshi-33418','彭泽','汪遵','quantangshi','','卷34','鹤爱孤松云爱山，宦情微禄免相关。
栽成五柳吟归去，漉酒巾边伴菊闲。','',''),('quantangshi-33419','杜邮馆','汪遵','quantangshi','','卷34','杀尽降兵热血流，一心犹自逞戈矛。
功成若解求身退，岂得将军死杜邮。','',''),('quantangshi-33420','细腰宫','汪遵','quantangshi','','卷34','鼓声连日烛连宵，贪向春风舞细腰。
争奈君王正沈醉，秦兵江上促征桡。','',''),('quantangshi-33421','瑶台','汪遵','quantangshi','','卷34','仙梦香魂不久留，满川云雨满宫愁。
直须待得荆王死，始向瑶台一处游。','',''),('quantangshi-33422','吴坂','汪遵','quantangshi','','卷34','蜷局盐车万里蹄，忽逢良鉴始能嘶。
不缘伯乐称奇骨，几与驽骀价一齐。','',''),('quantangshi-33423','箕山','汪遵','quantangshi','','卷34','薄世临流洗耳尘，便归云洞任天真。
一瓢风入犹嫌闹，何况人间万种人。','',''),('quantangshi-33424','息国','汪遵','quantangshi','','卷34','家国兴亡身独存，玉容还受楚王恩。
衔冤只合甘先死，何待花间不肯言。','',''),('quantangshi-33425','梁寺','汪遵','quantangshi','','卷34','立国从来为战功，一朝何事却谈空。
台城兵匝无人敌，闲卧高僧满梵宫。','',''),('quantangshi-33426','南阳','汪遵','quantangshi','','卷34','陆困泥蟠未适从，岂妨耕嫁隐高踪。
若非先主垂三顾，谁识茅庐一卧龙。','',''),('quantangshi-33427','杞梁墓','汪遵','quantangshi','','卷34','一呌长城万仞摧，杞梁遗骨逐妻回。
南邻北里皆孀妇，谁解坚心继此来。','',''),('quantangshi-33428','夷门','汪遵','quantangshi','','卷34','晋鄙兵回为重难，秦师收斾亦西还。
今来不是无朱亥，谁降轩车问抱关。','',''),('quantangshi-33429','汴河','汪遵','quantangshi','','卷34','隋皇意欲泛龙舟，千里昆仑水别流。
还待春风锦帆暖，柳阴相送到迷楼。','',''),('quantangshi-33430','燕台','汪遵','quantangshi','','卷34','礼士招贤万古名，高台依旧对燕城。
如今寂寞无人上，春去秋来草自生。','',''),('quantangshi-33431','聊城','汪遵','quantangshi','','卷34','刃血攻聊已越年，竟凭儒术罢戈鋋。
田单漫逞烧牛计，一箭终输鲁仲连。','',''),('quantangshi-33432','西河','汪遵','quantangshi','','卷34','花貌年年溺水滨，俗传河伯娶生人。
自从明宰投巫后，直至如今鬼不神。','',''),('quantangshi-33433','密县','汪遵','quantangshi','','卷34','百里能将济猛宽，飞蝗不到邑人安。
至今闾里逢灾沴，犹祝当时卓长官。','',''),('quantangshi-33434','升仙桥','汪遵','quantangshi','','卷34','题桥贵欲露先诚，此日人皆笑率情。
应讶临邛沽酒客，逢时还作汉公卿。','',''),('quantangshi-33435','破陈','汪遵','quantangshi','','卷34','猎猎朱旗映彩霞，纷纷白刃入陈家。
看看打破东平苑，犹舞庭前玉树花。','',''),('quantangshi-33436','白头吟','汪遵','quantangshi','','卷34','失却青丝素髪生，合欢罗带意全轻。
古今人事皆如此，不独文君与马卿。','',''),('quantangshi-33437','短歌吟','汪遵','quantangshi','','卷34','箭飞乌兔竞东西，贵贱贤愚不梦齐。
匣里有琴樽有酒，人间便是武陵溪。','',''),('quantangshi-33438','晋河','汪遵','quantangshi','','卷34','风引征帆管吹高，晋君张[宴]俟雄豪。
舟人笑指千余客，谁是烟霄六翮毛。','',''),('quantangshi-33439','干将墓','汪遵','quantangshi','','卷34','橐龠冰霜万古闻，拍灰松地见余坟。
应缘神劒飞扬久，水水山山尽是云。','',''),('quantangshi-33440','金谷','汪遵','quantangshi','','卷34','晋臣荣盛更谁过，常向阶前舞翠娥。
香散艳消如一梦，但留风月伴烟萝。','',''),('quantangshi-33441','三闾庙','汪遵','quantangshi','','卷34','为嫌朝野尽陶陶，不觉官高怨亦高。
憔悴莫酬渔父笑，浪交千载咏离骚。','',''),('quantangshi-33442','易水','汪遵','quantangshi','','卷34','[匕]首空磨事不成，误留龙袂待琴声。
斯须却作秦中鬼，青史徒标烈士名。','',''),('quantangshi-33443','严陵台','汪遵','quantangshi','','卷34','一钓凄凉在杳冥，故人飞诏入山扃。
终将宠辱轻轩冕，高卧五云为客星。','',''),('quantangshi-33444','淮阴','汪遵','quantangshi','','卷34','秦季贤愚混不分，只应漂母识王孙。
归荣便累千金赠，为报当时一饭恩。','',''),('quantangshi-33445','鸡鸣曲','汪遵','quantangshi','','卷34','金距花冠傍舍栖，清晨相呌一声齐。
开关自有冯生计，不必天明待汝啼。','',''),('quantangshi-33446','采桑妇','汪遵','quantangshi','','卷34','为报踌躇陌上郎，蚕饥日晚妾心忙。
本来若爱黄金好，不肯携笼更采桑。','',''),('quantangshi-33447','渔父','汪遵','quantangshi','','卷34','棹月眠流处处通，绿蓑苇带混元风。
灵均说尽孤高事，全与逍遥意不同。','',''),('quantangshi-33448','越女','汪遵','quantangshi','','卷34','玉貌何曾为浣沙，只图句践献夫差。
苏台日夜唯歌舞，不觉干戈犯翠华。','',''),('quantangshi-33449','望思台','汪遵','quantangshi','','卷34','不忧家国任奸臣，骨肉翻为蓦路人。
巫蛊事行冤莫雪，九层徒筑见无因。','',''),('quantangshi-33450','比干墓','汪遵','quantangshi','','卷34','国乱时危道不行，忠贤谏死胜谋生。
一沈冤骨千年后，壠水虽平恨未平。','',''),('quantangshi-33451','郢中','汪遵','quantangshi','','卷34','莫言白雪少人听，高调都难称俗情。
不是楚词询宋玉，巴歌犹掩绕梁声。','',''),('quantangshi-33452','北海','汪遵','quantangshi','','卷34','汉臣曾此作缧囚，茹血衣毛十九秋。
鹤髪半垂龙节在，不闻青史说封侯。','',''),('quantangshi-33453','招屈亭','汪遵','quantangshi','','卷34','三闾溺处杀怀王，感得荆人尽缟裳。
招屈亭边两重恨，远天秋色暮苍苍。','',''),('quantangshi-33454','屈祠','汪遵','quantangshi','','卷34','不肯迂回入醉乡，乍吞忠梗没沧浪。
至今祠畔猨啼月，了了犹疑恨楚王。','',''),('quantangshi-33455','铜雀台','汪遵','quantangshi','','卷34','铜雀台成玉座空，短歌长袖尽悲风。
不知仙驾归何处，徒遣颦眉望汉宫。','',''),('quantangshi-33456','斑竹祠','汪遵','quantangshi','','卷34','九处烟霞九处昏，一回延首一销魂。
因凭直节流红泪，图得千秋见血痕。','',''),('quantangshi-33457','题李太尉平泉庄','汪遵','quantangshi','','卷34','水泉花木好高眠，嵩少纵横满目前。
惆怅人间不平事，今朝身在海南边。','',''),('quantangshi-33458','战城南','汪遵','quantangshi','','卷34','风沙刮地塞云愁，平旦交锋晚未休。
白骨又霑新战血，青天犹列旧旄头。','',''),('quantangshi-33459','延平津','汪遵','quantangshi','','卷34','三尺晶荧射斗牛，岂随凡手报冤雠。
延平一旦为龙处，看取风云布九州。','',''),('quantangshi-33460','项亭','汪遵','quantangshi','','卷34','不修仁德合文明，天道如何拟力争。
隔岸故乡归不得，十年空负拔山名。','',''),('quantangshi-33461','乌江','汪遵','quantangshi','','卷34','兵散弓残挫虎威，单枪匹马突重围。
英雄去尽羞容在，看却江东不得归。','',''),('quantangshi-33462','绿珠','汪遵','quantangshi','','卷34','大抵花颜最怕秋，南家歌歇北家愁。
从来几许如君貌，不肯如君坠玉楼。','',''),('quantangshi-33463','升仙桥','汪遵','quantangshi','','卷34','汉朝卿相尽风云，司马题桥众又闻。
何事不如杨得意，解搜贤哲荐明君。','',''),('quantangshi-33464','隋柳','汪遵','quantangshi','','卷34','夹浪分堤万树余，为迎龙舸到江都。
君看靖节高眠处，只向衡门种五株。','',''),('quantangshi-33465','杨柳','汪遵','quantangshi','','卷34','亚夫营畔柳蒙蒙，隋主堤边四路通。
攀折赠君还有意，翠眉轻嫩怕春风。','',''),('quantangshi-33466','桐江','汪遵','quantangshi','','卷34','光武重兴四海宁，汉臣无不受浮荣。
严陵何事轻轩冕，独向桐江钓月明。','',''),('quantangshi-33467','招隐','汪遵','quantangshi','','卷34','罢听泉声看鹿羣，丈夫才策合匡君。
早携书劒离岩谷，莫待蒲轮辗白云。','',''),('quantangshi-33468','陈宫','汪遵','quantangshi','','卷34','椒宫荒宴竟无疑，倏忽山河尽入隋。
留得后庭亡国曲，至今犹与酒家吹。','',''),('quantangshi-33469','樊将军庙','汪遵','quantangshi','','卷34','玉辇曾经陷楚营，汉皇心怯拟休兵。
当时不得将军力，日月须分一半明。','',''),('quantangshi-33470','东海','汪遵','quantangshi','','卷34','漾舟雪浪映花颜，徐福携将竟不还。
同作危时避秦客，此行何似武陵滩。','',''),('quantangshi-33471','昭君','汪遵','quantangshi','','卷34','汉家天子镇寰瀛，塞北羌胡未罢兵。
猛将谋臣徒自贵，蛾眉一笑塞尘清。','',''),('quantangshi-33472','五湖','汪遵','quantangshi','','卷34','已立平吴霸越功，片帆高扬五湖风。
不知战国官荣者，谁似陶朱得始终。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33473','渑池','汪遵','quantangshi','','卷34','西秦北赵各称高，池上张筵列我曹。
何事君王亲击缶，相如有劒可吹毛。','',''),('quantangshi-33474','函谷关','汪遵','quantangshi','','卷34','脱祸东奔壮气摧，马如飞电毂如雷。
当时若不听弹铗，那得关门半夜开。','',''),('quantangshi-33475','咏酒二首 一','汪遵','quantangshi','','卷34','九酝松醪一曲歌，本图闲放养天和。
后人不识前贤意，破国亡家事甚多。','',''),('quantangshi-33476','咏酒二首 二','汪遵','quantangshi','','卷34','万事销沈向一杯，竹门哑轧为风开。
秋宵睡足芭蕉雨，又是江湖入梦来。','',''),('quantangshi-33477','苍颉台','汪遵','quantangshi','','卷34','观迹成文代结绳，皇风儒教浩然兴。
几人从此休耕钓，吟对长安雪夜灯。','',''),('quantangshi-33478','长城','汪遵','quantangshi','','卷34','秦筑长城比铁牢，蕃戎不敢过临洮。
虽然万里连云际，争及尧阶三尺高。','',''),('quantangshi-33479','过洞庭湖','許棠','quantangshi','','卷34','惊波常不定，半日鬓堪斑。
四顾疑无地，中流忽有山。
鸟高恒畏坠，帆远却如闲。
渔父闲相引，时歌浩渺间。','',''),('quantangshi-33480','登渭南县楼','許棠','quantangshi','','卷34','近甸名偏着，登城景又宽。
半空分太华，极目是长安。
雪助河流涨，人耕烧色残。
闲来时甚少，欲下重凭栏。','',''),('quantangshi-33481','送李频之南陵主簿','許棠','quantangshi','','卷34','赴县是还乡，途程岂觉长。
听莺离灞岸，荡桨入陵阳。
野蕨生公署，闲云拂印牀。
晴天调膳外，垂钓有池塘。','',''),('quantangshi-33482','写怀','許棠','quantangshi','','卷34','汩没与辛勤，全钟在此身。
半生为下客，终老托何人。
两鬓关中改，千岩海上春。
青云知有路，自是致无因。','',''),('quantangshi-33483','过中条山','許棠','quantangshi','','卷34','徒为经异岳，不得访灵踪。
日尽行难尽，千重复万重。
云垂多作雨，雷动半和钟。
孤竹人藏处，无因认本峰。','',''),('quantangshi-33484','早发洛中','許棠','quantangshi','','卷34','半夜发清洛，不知过石桥。
云增中岳大，树隐上阳遥。
堑黑初沉月，河明欲认潮。
孤村人尚梦，无处暂停桡。','',''),('quantangshi-33485','汝州郡楼望嵩山','許棠','quantangshi','','卷34','不共众山同，岧嶤出迥空。
几层高鸟外，万仞一楼中。
水落难归地，云离便逐风。
唯应霄汉客，绝顶路方通。','',''),('quantangshi-33486','将归江南留别友人','許棠','quantangshi','','卷34','连春不得意，所业已疑非。
旧国乱离后，新年惆怅归。
雪开还楚地，花惹别秦衣。
江徼多留滞，高秋会恐违。','',''),('quantangshi-33487','塞外书事','許棠','quantangshi','','卷34','征路出穷边，孤吟傍戍烟。
河光深荡塞，碛色迥连天。
残日沉雕外，惊蓬到马前。
空怀钓鱼所，未定卜归年。','',''),('quantangshi-33488','日暮江上','許棠','quantangshi','','卷34','孤帆收广岸，落照在遥峰。
南北渡人少，高低归鸟重。
潮回沙出树，雨过浦沉钟。
渔父虽相问，那能话所从。','',''),('quantangshi-33489','客行','許棠','quantangshi','','卷34','旅食唯草草，此生谁我同。
故园魂梦外，长路别离中。
人事萍随水，年光鸟过空。
欲吟先落泪，多是怨途穷。','',''),('quantangshi-33490','送李员外知扬子州留务','許棠','quantangshi','','卷34','帝命分留务，东南向楚天。
几程回送骑，中路见迎船。
冶例开山铸，民多酌海煎。
青云名素重，此去岂经年。','',''),('quantangshi-33491','春暮途次华山下','許棠','quantangshi','','卷34','他皆宴牡丹，独又出长安。
远道行非易，无图住自难。
离城风已暖，近岳雨翻寒。
此去知谁顾，闲吟祗自宽。','',''),('quantangshi-33492','旅次滑台投献陆侍御','許棠','quantangshi','','卷34','已是鸿来日，堪惊却背秦。
天遥三楚树，路远两河人。
旅梦难归隐，吟魂不在身。
霜台欹冠豸，赖许往来频。','',''),('quantangshi-33493','重归江南','許棠','quantangshi','','卷34','无成归故里，不似在他乡。
岁月逐流水，山川空夕阳。
回潮迷古渡，迸竹过邻墙。
耆旧休存省，胡为止泪行。','',''),('quantangshi-33494','寄黔南李校书','許棠','quantangshi','','卷34','从戎巫峡外，吟兴更应多。
郡响蛮江涨，山昏蜀雨过。
公筵饶越味，俗土尚巴歌。
中夜怀吴梦，知经滟滪波。','',''),('quantangshi-33495','东归留辞沈侍郎','許棠','quantangshi','','卷34','一第久乖期，深心已自疑。
沧江归恨远，紫阁别愁迟。
稽古成何事，龙钟负已知。
依门非近日，不虑旧恩移。','',''),('quantangshi-33496','题开明里友人居','許棠','quantangshi','','卷34','城中尘外住，入望是田家。
井出深山水，阑藏异国花。
风巢和鸟动，雪竹向人斜。
来往唯君熟，乡园共海涯。','',''),('quantangshi-33497','遣怀','許棠','quantangshi','','卷34','此生何处遂，屑屑复悠悠。
旧国归无计，他乡梦亦愁。
飞尘长满眼，衰髪暗添头。
章句非经济，终难动五侯。','',''),('quantangshi-33498','送龙州樊使君','許棠','quantangshi','','卷34','曾见邛人说，龙州地未深。
碧溪飞白鸟，红斾映青林。
土产唯宜药，王租只贡金。
政成开宴日，谁伴使君吟。','',''),('quantangshi-33499','寄盩厔薛能少府','許棠','quantangshi','','卷34','满县唯云水，何曾似近畿。
晓庭猿集惯，寒署吏衙稀。
冰色封深涧，樵声出紫微。
时闻迎隐者，依旧着山衣。','',''),('quantangshi-33500','送李左丞巡边','許棠','quantangshi','','卷34','狂戎侵内地，左辖去萧关。
走马冲边雪，鸣鞞动塞山。
风收枯草定，月满广沙闲。
西绕河兰匝，应多隔岁还。','',''),('quantangshi-33501','题青山馆','許棠','quantangshi','','卷34','境概殊诸处，依然是谢家。
遗文齐日月，旧井照烟霞。
水隔平芜远，山横度鸟斜。
无人能此隐，来往谩兴嗟。','',''),('quantangshi-33502','雁门关野望','許棠','quantangshi','','卷34','高关闲独望，望久转愁人。
紫塞唯多雪，胡山不尽春。
河遥分断野，树乱起飞尘。
时见东来骑，心知近别秦。','',''),('quantangshi-33503','五原书事','許棠','quantangshi','','卷34','西出黄云外，东怀白浪遥。
星河愁立夜，雷电独行朝。
碛迥人防寇，天空雁避雕。
如何非战卒，弓劒不离腰。','',''),('quantangshi-33504','送从弟归泉州','許棠','quantangshi','','卷34','问省归南服，悬帆任北风。
何山犹见雪，半路已无鸿。
瘴杂春云重，星垂夜海空。
往来如不住，亦是一年中。','',''),('quantangshi-33505','留别故人','許棠','quantangshi','','卷34','殊立本不偶，非唯今所难。
无门闲共老，尽日泣相看。
鸟畏闻鶗鴂，花惭背牡丹。
何人知此计，复议出长安。','',''),('quantangshi-33506','塞下二首 一','許棠','quantangshi','','卷34','胡虏偏狂悍，边兵不敢闲。
防秋朝伏弩，纵火夜搜山。
雁逆风鼙振，沙飞猎骑还。
安西虽有路，难更出阳关。','',''),('quantangshi-33507','塞下二首 二','許棠','quantangshi','','卷34','征役已不定，又缘无定河。
塞深烽砦密，山乱犬羊多。
汉卒闻笳泣，胡儿击劒歌。
番情终未测，今昔谩言和。','',''),('quantangshi-33508','题张乔升平里居','許棠','quantangshi','','卷34','下马似无人，开门只一身。
心同孤鹤静，行过老僧真。
乱水藏幽径，高原隔远津。
匡庐曾共隐，相见自相亲。','',''),('quantangshi-33509','题郑拾遗南斋','許棠','quantangshi','','卷34','明时无事谏，岂事隐明君。
每值离丹陛，多陪宴白云。
门连萧洞僻，地与曲江分。
满院皆柽竹，期栖鸾鹤羣。','',''),('quantangshi-33510','渭上送人南归','許棠','quantangshi','','卷34','远役与归愁，同来渭水头。
南浮应到海，北去阻无州。
楚雨天连地，胡风夏甚秋。
江人如见问，为话复贫游。','',''),('quantangshi-33511','寄睦州陆郎中','許棠','quantangshi','','卷34','下国多高趣，终年半是吟。
海涛通越分，部伍杂闽音。
晓郭云藏市，春山鸟护林。
东浮虽未遂，日日至中心。','',''),('quantangshi-33512','投徐端公','許棠','quantangshi','','卷34','无谋寻旧友，强喜亦如愁。
丹桂阻丹恳，白衣成白头。
穷吴迷钓业，大漠事贫游。
霄汉期提引，龙钟未拟休。','',''),('quantangshi-33513','出塞门','許棠','quantangshi','','卷34','步步经戎虏，防兵不离身。
山多曾战处，路断野行人。
暴雨声同瀑，奔沙势异尘。
片时怀万虑，白发数茎新。','',''),('quantangshi-33514','新年呈友','許棠','quantangshi','','卷34','一月月相似，一年年不同。
清晨窥古镜，旅貌近衰翁。
处世闲难得，关身事半空。
浮生能几许，莫惜醉春风。','',''),('quantangshi-33515','银州北书事','許棠','quantangshi','','卷34','南辞采石远，北背乞银深。
碛路虽多险，江人不废吟。
雕依孤堠立，鸥向迥沙沈。
因共边人熟，行行起战心。','',''),('quantangshi-33516','寄赵能卿','許棠','quantangshi','','卷34','我命同君命，君诗似我诗。
俱无中道计，各失半生期。
素业沧江远，清时白发垂。
蹉跎一如此，何处卜栖迟。','',''),('quantangshi-33517','夏州道中','許棠','quantangshi','','卷34','茫茫沙漠广，渐远赫连城。
堡迥烽相见，河移浪旋生。
无蝉嘶折柳，有寇似防兵。
不耐饥寒迫，终谁至此行。','',''),('quantangshi-33518','经故杨太尉旧居','許棠','quantangshi','','卷34','在汉信垂功，于唐道更隆。
一川留古迹，多代仰高风。
树折巢堕鸟，阶荒草覆虫。
行人过岂少，独驻夕阳中。','',''),('quantangshi-33519','东归次采石江','許棠','quantangshi','','卷34','东下经牛渚，依然是故关。
客程临岸尽，乡思入鸥闲。
雨涨巴来浪，云增楚际山。
渔翁知未达，相顾不开颜。','',''),('quantangshi-33520','陇上书事','許棠','quantangshi','','卷34','城叠连云壑，人家似隐居。
树飞鹦鹉众，川下鹡鸰疎。
滴梦关山雨，资餐陇水鱼。
谁知江徼客，此景倍相于。','',''),('quantangshi-33521','陈情献江西李常侍五首 一','許棠','quantangshi','','卷34','二十二三年，游秦复滞燕。
徒陪羣彦后，自苦此生前。
径折啼猿树，岩荒喷月泉。
东堂曾受荐，垂白志犹坚。','',''),('quantangshi-33522','陈情献江西李常侍五首 二','許棠','quantangshi','','卷34','淅淅复栖栖，人间只自迷。
终年愁远道，到老去何蹊。
始见红叶落，又闻黄鸟啼。
不因趋大斾，谁肯暂提携。','',''),('quantangshi-33523','陈情献江西李常侍五首 三','許棠','quantangshi','','卷34','童蒙即苦辛，未识杏园春。
谩倚无为日，还成不偶人。
乡程长恨远，旅梦亦愁贫。
天地虽云广，殊难寄此身。','',''),('quantangshi-33524','陈情献江西李常侍五首 四','許棠','quantangshi','','卷34','春闱久已滞，秋赋又逢停。
选士疑长阻，伤时自不宁。
秦城还逐梦，楚徼影随形。
此去吟虽苦，何人更肯听。','',''),('quantangshi-33525','陈情献江西李常侍五首 五','許棠','quantangshi','','卷34','孤立时全塞，求名势转难。
身多离下国，分合阻长安。
越鸟啼春早，蛮花送雨寒。
丘门沾顾重，未别欲阑干。','',''),('quantangshi-33526','经八合坂','許棠','quantangshi','','卷34','蹑险入高空，初疑势不穷。
又缘千嶂尽，还共七盘同。
下辨东流水，平随北去鸿。
天然无此道，应免患穷通。','',''),('quantangshi-33527','送友人北游','許棠','quantangshi','','卷34','北出阴关去，何人肯待君。
无青山拥晋，半浊水通汾。
雁塞虽多雁，云州却少云。
兹游殊不恶，莫恨暂离羣。','',''),('quantangshi-33528','登凌歊台','許棠','quantangshi','','卷34','平芜望已极，况复倚凌歊。
江截吴山断，天临楚泽遥。
云帆高出树，水市迥分桥。
立久斜阳尽，无言似寂寥。','',''),('quantangshi-33529','曲江三月三日','許棠','quantangshi','','卷34','满国赏芳辰，飞蹄复走轮。
好花皆折尽，明日恐无春。
鸟避连云幄，鱼惊远浪尘。
如何当此节，独自作愁人。','',''),('quantangshi-33530','赠栖白上人','許棠','quantangshi','','卷34','闲身却不闲，日日对天颜。
已住城中寺，难归海上山。
诗传华夏外，偈布市朝间。
欲问空门事，空门岂有关。','',''),('quantangshi-33531','野步','許棠','quantangshi','','卷34','闲赏步易远，野吟声自高。
路无人到迹，林有鹤遗毛。
物外趣都别，尘中心枉劳。
沿溪收堕果，坐石唤饥猱。','',''),('quantangshi-33532','过湍沟谷','許棠','quantangshi','','卷34','西去穷胡处，嵓崖境不常。
石形相对耸，天势一条长。
栈底鸣流水，林端歛夕阳。
虽随兵马至，未免畏豺狼。','',''),('quantangshi-33533','送友人游蜀','許棠','quantangshi','','卷34','巴兴千万寻，此去若为心。
蟋蟀既将定，猕猴应正吟。
劒门秋断雁，褒谷夜多砧。
自古西南路，艰难直至今。','',''),('quantangshi-33534','题秦州城','許棠','quantangshi','','卷34','圣泽滋遐徼，河堤四向通。
大荒收虏帐，遗土复秦风。
乱烧迷归路，遥山似梦中。
此时怀感切，极目思无穷。','',''),('quantangshi-33535','寄敬亭山清越上人','許棠','quantangshi','','卷34','南朝山半寺，谢朓故乡邻。
岭上非无主，秋诗复有人。
高禅星月近，野火虎狼驯。
旧许陪闲社，终应待此身。','',''),('quantangshi-33536','秋江霁望','許棠','quantangshi','','卷34','高秋偏入望，霁景倍关情。
落木满江水，离人怀渭城。
山高孤戍断，野极暮天平。
渔父时相问，羞真道姓名。','',''),('quantangshi-33537','陇州旅中书事寄李中丞','許棠','quantangshi','','卷34','三伏客吟过，长安未拟还。
蛩声秋不动，燕别思仍闲。
乱叶随寒雨，孤蟾起暮关。
经时高岭外，来往斾旌间。','',''),('quantangshi-33538','秋日归旧山','許棠','quantangshi','','卷34','山云蝉满树，欲住更何安。
上国回将晚，孤峰别自难。
碛遥鸿未到，江近夜先寒。
泉石虽堪恋，行人不愿看。','',''),('quantangshi-33539','下黄耳盘','許棠','quantangshi','','卷34','独下黄盘路，多虞部落连。
云晴仍着地，树古自参天。
乱鸟飞人上，惊麋起马前。
行行无郡邑，唯见虎狼烟。','',''),('quantangshi-33540','旅怀','許棠','quantangshi','','卷34','终年唯旅舍，只似已无家。
白发除还出，丹霄去转赊。
夏游穷塞路，春醉负秦花。
应是穹苍意，空教老若耶。','',''),('quantangshi-33541','题金山寺','許棠','quantangshi','','卷34','四面波涛匝，中楼日月邻。
上穷如出世，下瞷忽惊神。
刹碍长空鸟，船通外国人。
房房皆叠石，风扫永无尘。','',''),('quantangshi-33542','送王侍御赴宣城','許棠','quantangshi','','卷34','朝回离九陌，岛外赏残春。
经宿留闲客，看云作主人。
时清难议隐，位重亦甘贫。
岩洞真仙境，应休别卧邻。','',''),('quantangshi-33543','题汧湖二首 一','許棠','quantangshi','','卷34','偶得湖中趣，都忘陇坻愁。
边声风下雁，楚思浪移舟。
静极亭连寺，凉多岛近楼。
吟游终不厌，还似曲江头。','',''),('quantangshi-33544','题汧湖二首 二','許棠','quantangshi','','卷34','陇首时无事，湖边日纵吟。
游鱼来复去，浴鸟出还沈。
蜃气藏孤屿，波光到远林。
无人见垂钓，暗起洞庭心。','',''),('quantangshi-33545','宿青山馆','許棠','quantangshi','','卷34','下马青山下，无言有所思。
云藏李白墓，苔暗谢公诗。
烈烧飞荒野，栖凫宿广陂。
东来与西去，皆是不闲时。','',''),('quantangshi-33546','宿同州厉评事旧业寄华下','許棠','quantangshi','','卷34','从戎依远地，无日见家山。
地近风沙处，城当甸服间。
阻河通渭水，曲苑带秦关。
待月登楼夜，何人相伴闲。','',''),('quantangshi-33547','闻蝉十二韵','許棠','quantangshi','','卷34','造化生微物，常能应候鸣。
初离何处树，又发去年声。
未蜕唯愁动，才飞似解惊。
闻来邻海徼，恨起过边城。
骚屑随风远，悠扬类雪轻。
报秋凉渐至，嘶月思偏清。
互默疑相答，微摇似欲行。
繁音人已厌，朽壳蚁犹争。
朝士严冠饰，宫嫔逞鬓名。
乱依西日噪，多引北归情。
筱露凝潜吸，蛛丝忽迸萦。
此时吟立者，不觉万愁生。','',''),('quantangshi-33548','冬杪归陵阳别业五首 一','許棠','quantangshi','','卷34','无媒归别业，所向自乖心。
闾里故人少，田园荒草深。
浪翻全失岸，竹迸别成林。
鸥鸟犹相识，时来听苦吟。','',''),('quantangshi-33549','冬杪归陵阳别业五首 二','許棠','quantangshi','','卷34','眠云终未遂，策马暂休期。
上国劳魂梦，中心甚别离。
冰封岩溜断，雪压砌松欹。
骨肉嗟名晚，看归却泪垂。','',''),('quantangshi-33550','冬杪归陵阳别业五首 三','許棠','quantangshi','','卷34','学劒虽无术，吟诗似有魔。
已贫甘事晚，临老爱闲多。
鸡犬唯随鹿，儿童只衣蓑。
时因寻野叟，狂醉复狂歌。','',''),('quantangshi-33551','冬杪归陵阳别业五首 四','許棠','quantangshi','','卷34','乡国乱离后，交亲半旅游。
远闻诚可念，归见岂无愁。
败苇迷荒径，寒蓑没坏舟。
衡门终不掩，倚杖看波流。','',''),('quantangshi-33552','冬杪归陵阳别业五首 五','許棠','quantangshi','','卷34','游秦复滞燕，不觉近衰年。
旅貌同柴毁，行衣对骨穿。
篱寒多啄雀，木落断浮烟。
楚夜闻鸣雁，犹疑在塞天。','',''),('quantangshi-33553','送王侍御赴宣城','許棠','quantangshi','','卷34','戴豸却驱鸡，东南上句溪。
路过金谷口，帆转石城西。
水树连天暗，山禽绕郡啼。
江人谙旧化，那复俟招携。','',''),('quantangshi-33554','春日乌延道中','許棠','quantangshi','','卷34','边穷厄未穷，复此逐归鸿。
去路多相似，行人半不同。
山川藏北狄，草木背东风。
虚负男儿志，无因立战功。','',''),('quantangshi-33555','寄华阴刘拾遗','許棠','quantangshi','','卷34','坚心持谏诤，自古亦艰难。
寄邑虽行化，眠云似去官。
河分中野断，岳入半天寒。
瀑布冰成日，谁陪吟复看。','',''),('quantangshi-33556','忆江南','許棠','quantangshi','','卷34','南楚西秦远，名迟别岁深。
欲归难遂去，闲忆自成吟。
雷电闲倾雨，猿猱鬬堕林。
眠云机尚在，未忍负初心。','',''),('quantangshi-33557','送前汝州李侍御罢归宣城','許棠','quantangshi','','卷34','吟诗早得名，戴豸又加荣。
下国闲归去，他人少此情。
云移寒峤出，烧夹夜江明。
重引池塘思，还登谢朓城。','',''),('quantangshi-33558','失题','許棠','quantangshi','','卷34','独夜长城下，孤吟近北辰。
半天初去雁，穷碛远来人。
月黯氛埃积，风膻帐幕邻。
惟闻防虏寇，不语暗伤神。','',''),('quantangshi-33559','送裴拾遗宰下邽','許棠','quantangshi','','卷34','受谪因延谏，兹行不出关。
直庐辞玉陛，上马向仙山。
地古桑麻广，城偏仆御闲。
县斋高枕卧，犹梦犯天颜。','',''),('quantangshi-33560','隗嚣宫晚望','許棠','quantangshi','','卷34','西顾伊兰近，方惊滞极边。
水随空谷转，山向夕阳偏。
碛鸟多依地，胡云不满天。
秋风动衰草，只觉犬羊膻。','',''),('quantangshi-33561','江上行','許棠','quantangshi','','卷34','片席随高鸟，连天积浪间。
苇宽云不匝，风广雨无闲。
戍影临孤浦，潮痕在半山。
东原归未得，荏苒滞江关。','',''),('quantangshi-33562','登山','許棠','quantangshi','','卷34','信步上鸟道，不知身忽高。
近空无世界，当楚见波涛。
顶峭松多瘦，崖悬石尽牢。
猕猴呼独散，隔水向人号。','',''),('quantangshi-33563','哭宣城元征君','許棠','quantangshi','','卷34','高眠终不起，远趣固难知。
琴劒今无主，园林旧许谁。
苔封僧坐石，苇涨鹤翘池。
后代传青史，方钦道德垂。','',''),('quantangshi-33564','寄建州姚员外','許棠','quantangshi','','卷34','诬谮遭遐谪，明君即自知。
乡遥辞劒外，身独向天涯。
岭堠蛮云积，闽空瘴雨垂。
南来终不遂，日探北归期。','',''),('quantangshi-33565','送厉校书从事鳯翔','許棠','quantangshi','','卷34','赴辟依丞相，超荣事岂同。
城池当陇右，山水是关中。
日有来巴使，秋高出塞鸿。
旬休随大斾，应到九成宫。','',''),('quantangshi-33566','春夜同厉文学先辈会宿','許棠','quantangshi','','卷34','江汉久分路，京关重聚吟。
更为他夜约，方尽昔年心。
月隔明河远，花藏宿鸟深。
无眠将及曙，多是说山阴。','',''),('quantangshi-33567','长安书情','許棠','quantangshi','','卷34','疎散过闲人，同人不在秦。
近来惊白发，方解惜青春。
僻寺居将遍，权门到绝因。
行藏如此辈，何以谓谋身。','',''),('quantangshi-33568','过故洛城','許棠','quantangshi','','卷34','七百数还穷，城池一旦空。
夕阳唯照草，危堞不胜风。
岸断河声别，田荒野色同。','',''),('quantangshi-33569','寄庐山贾处士','許棠','quantangshi','','卷34','时泰亦高眠，人皆谓不然。
穷经休望辟，饵术止期仙。
彭蠡波涵月，炉峰雪照天。
常闻风雨夜，到晓在渔船。','',''),('quantangshi-33570','下第东归留别郑侍郎','許棠','quantangshi','','卷34','无才副至公，岂是命难通。
分合吟诗老，家宜逐浪空。
别心悬阙下，归念极吴东。
唯畏重回日，初情恐不同。','',''),('quantangshi-33571','泗上早发','許棠','quantangshi','','卷34','独起无人见，长河夜泛时。
平芜疑自动，落月似相随。
楚外离空早，关西去已迟。
渔歌闻不绝，却轸洞庭思。','',''),('quantangshi-33572','赠天台僧','許棠','quantangshi','','卷34','赤城霞外寺，不忘旧登年。
石上吟分海，楼中语近天。
重游空有梦，再隐定无缘。
独夜休行道，星辰静照禅。','',''),('quantangshi-33573','冬夜与友人会宿','許棠','quantangshi','','卷34','君初离雁塞，我久滞雕阴。
隔闰俱劳梦，通宵各话心。
禁风吹漏出，原树映星沉。
白昼常多事，无妨到晓吟。','',''),('quantangshi-33574','送元遂上人归吴中','許棠','quantangshi','','卷34','落髪在王畿，承恩着紫衣。
印心谁受请，讲疏自携归。
泛浦龙惊锡，禅云虎绕扉。
吴中知久别，庵树想成围。','',''),('quantangshi-33575','赠志空上人','許棠','quantangshi','','卷34','了了在心中，南宗与北宗。
行高无外染，骨瘦是真容。
饭野盂埋雪，禅云杖倚松。
常修不住性，必拟老何峰。','',''),('quantangshi-33576','边城晚望','許棠','quantangshi','','卷34','广漠杳无穷，孤城四面空。
马行高碛上，日堕迥沙中。
逼晓人移帐，当川树列风。
迢迢河外路，知直去崆峒。','',''),('quantangshi-33577','汴上暮秋','許棠','quantangshi','','卷34','独立长堤上，西风满客衣。
日临秋草广，山接远天微。
岸叶随波尽，沙云与鸟飞。
秦人宁有素，去意自知归。','',''),('quantangshi-33578','春日言怀','許棠','quantangshi','','卷34','东风万物新，独未到幽人。
赋命自多蹇，阳和非不均。
五陵三月暮，百越一家贫。
早悞闲眠处，无愁异此身。','',''),('quantangshi-33579','奉天寒食书事','許棠','quantangshi','','卷34','处处无烟火，人家似暂空。
晓林花落雨，寒谷鸟啼风。
故里芳洲外，残春甸服中。
谁知独西去，步步泣途穷。','',''),('quantangshi-33580','长安寓居','許棠','quantangshi','','卷34','贫寄帝城居，交朋日自疎。
愁迎离碛雁，梦逐出关书。
经雨蝉声尽，兼风杵韵余。
谁知江徼塞，所忆在樵渔。','',''),('quantangshi-33581','写怀','許棠','quantangshi','','卷34','此生居此世，堪笑复堪悲。
在处有岐路，何人无别离。
长当多难日，愁过少年时。
穷达都判了，休闲镊白髭。','',''),('quantangshi-33582','白菊','許棠','quantangshi','','卷34','所尚雪霜姿，非关落帽期。
香飘风外别，影到月中疑。
发在林雕后，繁当露冷时。
人间稀有此，自古乃无诗。','',''),('quantangshi-33583','中秋夜对月','許棠','quantangshi','','卷34','月月势皆圆，中秋朗最偏。
万方期一夕，到晓是经年。
影蔽星芒尽，光分物状全。
惟应苦吟者，目断向遥天。','',''),('quantangshi-33584','陪郢州张员外宴白雪楼','許棠','quantangshi','','卷34','高情日日闲，多宴雪楼间。
洒槛江干雨，当筵天际山。
带帆分浪色，驻乐话朝班。
岂料羁浮者，樽前得解颜。','',''),('quantangshi-33585','和薛侍御题兴善寺松','許棠','quantangshi','','卷34','何年斸到城，满国响高名。
半寺阴常匝，邻坊景亦清。
代多无朽势，风定有余声。
自得天然状，非同涧底生。','',''),('quantangshi-33586','题郑侍郎岩隐十韵','許棠','quantangshi','','卷34','朝退常归隐，真修大隐情。
园林应得趣，岩谷自为名。
野步难寻寺，闲吟少在城。
树藏幽洞黑，花照远村明。
海石分湖路，风泉遰雨声。
性高怜散逸，官达厌公卿。
架引藤重长，阶延笋迸生。
青门无到客，紫阁有来莺。
物外身虽隐，区中望本清。
终难依此境，坐卧避钧衡。','',''),('quantangshi-33587','宿灵山兰若','許棠','quantangshi','','卷34','江心天半寺，一夕万缘空。
地出浮云上，星摇积浪中。
滴沤垂阁雨，吹桧送帆风。
旦夕闻清磬，唯应是钓翁。','',''),('quantangshi-33588','亲仁里双鹭','許棠','quantangshi','','卷34','双去双来日已频，只应知我是江人。
对欹雪顶思寻水，更振霜翎恐染尘。
三楚几时初失侣，五陵何树又栖身。
天然不与凡禽类，傍砌听吟性自驯。','',''),('quantangshi-33589','成纪书事二首 一','許棠','quantangshi','','卷34','东吴远别客西秦，怀旧伤时暗洒巾。
满野多成无主冢，防边半是异乡人。
山河再阔千余里，城市曾经一百春。
闲与将军议戎事，伊兰犹未绝胡尘。','',''),('quantangshi-33590','成纪书事二首 二','許棠','quantangshi','','卷34','蹉跎远入犬羊中，荏苒将成白首翁。
三楚田园归未得，五原岐路去无穷。
天垂大野雕盘草，月落孤城角啸风。
难问开元向前事，依稀犹认隗嚣宫。','',''),('quantangshi-33591','秦中遇友人','許棠','quantangshi','','卷34','半生南走复西驰，愁过杨朱罢泣岐。
远梦亦羞归海徼，贫游多是滞边陲。
胡云不聚风无定，陇路难行栈更危。
旦暮唯闻语征战，看看已欲废吟诗。','',''),('quantangshi-33592','过分水岭','許棠','quantangshi','','卷34','陇山高共鸟行齐，瞰险盘空甚蹑梯。
云势崩腾时向背，水声呜咽若东西。
风兼雨气吹人面，石带冰棱碍马蹄。
此去秦川无别路，隔崖穷谷却难迷。','',''),('quantangshi-33593','讲德陈情上淮南李仆射八首 一','許棠','quantangshi','','卷34','天降贤人佐圣时，自然声教满华夷。
英明不独中朝仰，清重兼闻外国知。
凉夜酒醒多对月，晓庭公退半吟诗。
梁城东下虽经战，风俗犹传守旧规。','',''),('quantangshi-33594','讲德陈情上淮南李仆射八首 二','許棠','quantangshi','','卷34','多朝轩冕冠干坤，四海皆推圣最尊。
楚玉已曾分卞玉，膺门依旧是龙门。
筵开乐振高云动，城掩鼙收落日昏。
尝念苍生如赤子，九州无处不沾恩。','',''),('quantangshi-33595','讲德陈情上淮南李仆射八首 三','許棠','quantangshi','','卷34','未领春闱望早清，况联戎阃控强兵。
风威遍布江山静，教化高同日月明。
九郡竟歌兼煮海，四方皆得共和羹。
东南自此全无事，只为期年政已成。','',''),('quantangshi-33596','讲德陈情上淮南李仆射八首 四','許棠','quantangshi','','卷34','帝念淮堧疫疹频，牢笼山海委名臣。
古来比德由无侣，当代同途岂有人。
夜宴独吟梁苑月，朝游重见广陵春。
多年疲瘵全苏息，须到讴谣日满秦。','',''),('quantangshi-33597','讲德陈情上淮南李仆射八首 五','許棠','quantangshi','','卷34','三纪吟诗望一名，丹霄待得白头成。
已期到老还沾禄，无复偷闲却养生。
当宴每垂听乐泪，望云长起忆山情。
朱门旧是登龙客，初脱鱼鳞胆尚惊。','',''),('quantangshi-33598','讲德陈情上淮南李仆射八首 六','許棠','quantangshi','','卷34','东来淮海拜旌旟，不把公卿一字书。
曾侍晚斋吟对雪，又容华馆食兼鱼。
孤微自省恩非次，际会谁知分有余。
唯耻旧桥题处在，荣归无计似相如。','',''),('quantangshi-33599','讲德陈情上淮南李仆射八首 七','許棠','quantangshi','','卷34','平生南北逐蓬飘，待得名成鬓已雕。
寒浦一从抛钓艇，旧林无处认风飙。
程途虽喜关河尽，时节犹惊骨肉遥。
愁策羸蹄更归去，乱山流水满翻潮。','',''),('quantangshi-33600','讲德陈情上淮南李仆射八首 八','許棠','quantangshi','','卷34','丹霄空把桂枝归，白首依前着布衣。
当路公卿谁见待，故乡亲爱自疑非。
东风乍喜还沧海，栖旅终愁出翠微。
应念无媒居选限，二年须更守渔矶。','',''),('quantangshi-33601','献独孤尚书','許棠','quantangshi','','卷34','虚抛南楚滞西秦，白首依前衣白身。
退鷁已经三十载，登龙曾见一千人。
魂离为役诗篇苦，泪竭缘嗟骨相贫。
今日鞠躬高斾下，欲倾肝胆杳无因。','',''),('quantangshi-33602','将过单于','許棠','quantangshi','','卷34','荒碛连天堡戍稀，日忧蕃寇却忘机。
江山不到处皆到，陇雁已归时未归。
行李亦须携战器，趋迎当便着戎衣。
并州去路殊迢遰，风雨何当达近畿。','',''),('quantangshi-33603','贞女祠','許棠','quantangshi','','卷34','何穴藏贞骨，荒祠见旧颜。
精灵应自在，云雨不相关。
落石泉多咽，无风树尽闲。
唯疑千古后，为瑞向人间。','',''),('quantangshi-33604','宿华山','許棠','quantangshi','','卷34','异境良难测，非仙岂合游。
星辰方满岳，风雨忽移舟。
喷月泉垂壁，栖松鹤在楼。
因知休养处，不必在嵩丘。','',''),('quantangshi-33605','送张员外西川从事','許棠','quantangshi','','卷34','为郎不入朝，自是赴嘉招。
豸角初离首，金章已在腰。
劒横阴绿野，栈响近丹霄。
迎驿应相续，悬愁去路遥。','',''),('quantangshi-33606','题慈恩寺元遂上人院','許棠','quantangshi','','卷34','竹槛匝回廊，城中似外方。
月云开作片，枝鸟立成行。
径接河源润，庭容塔影凉。
天台频去说，谁占最高房。','',''),('quantangshi-33607','送杜仓曹往沧洲觐叔常侍','許棠','quantangshi','','卷34','浮阳横巨浸，南巷拥旌旃。
别带秦城雨，行闻魏国蝉。
碛鸿来每后，朝日见常先。
东鄙云霞广，高林间水天。','',''),('quantangshi-33608','雕阴道中作','許棠','quantangshi','','卷34','五月绥州北，途程少郁蒸。
马依膻草聚，人抱浊河澄。
迹固长城垒，冤深太子陵。
往来经此地，悲苦有谁能。','',''),('quantangshi-33609','留别从弟郴','許棠','quantangshi','','卷34','同承太岳胤，俱值太平时。
丹陛怀趋计，沧洲负去期。
久贫成蹭蹬，多病惜支离。
宗分兼交分，吾知汝亦知。','',''),('quantangshi-33610','寻山','許棠','quantangshi','','卷34','蹑履复支筇，深山草木中。
隔溪遥避虎，当坞忽闻钟。
落叶多相似，幽禽半不同。
羣猱呼却散，如此异林翁。','',''),('quantangshi-33611','送徐侍御充南诏判官','許棠','quantangshi','','卷34','西去安夷落，乘轺从节行。
彤庭传圣旨，异城化戎情。
瘴路穷巴徼，蛮川过峤城。
地偏风自杂，天漏月稀明。
危栈连空动，长江到底清。
笑宜防狒狒，言好听猩猩。
抚论如敦行，归情自合盟。
回期佩印绶，何更见新正。','',''),('quantangshi-33612','送省玄上人归江东','許棠','quantangshi','','卷34','释律周儒礼，严持用戒身。
安禅思剡石，留偈别都人。
雨合吴江黑，潮移海路新。
瓶盂自此去，应不更还秦。','',''),('quantangshi-33613','送刘校书游东鲁','許棠','quantangshi','','卷34','内阁劳雠校，东邦忽纵游。
才编精二雅，分合遇诸侯。
暗海龟蒙雨，连空赵魏秋。
如经麟见处，驻马瞰荒丘。','',''),('quantangshi-33614','送金吾侍御奉使日东','許棠','quantangshi','','卷34','还乡兼作使，到日倍荣亲。
向化虽多国，如公有几人。
孤山无返照，积水合苍旻。
膝下知难住，金章已系身。','',''),('quantangshi-33615','题甘露寺','許棠','quantangshi','','卷34','丹槛拂丹霄，人寰下瞰遥。
何年增造化，万古出尘嚣。
地势盘三楚，江声换几朝。
满栏皆异药，到顶尽飞桥。
泽广方云梦，山孤数沃焦。
中[宵]霞始散，经腊木稀凋。
铎动天风度，窗明海气消。
带鼙分迥堞，当日辨翻潮。
鸟去沉葭菼，帆来映泬㵳。
浮生自多事，无计免回镳。','',''),('quantangshi-33616','冬夜怀真里友人会宿','許棠','quantangshi','','卷34','静语与高吟，搜神又爽心。
各来依帝里，相对似山阴。
漏永星河没，堂寒月彩深。
从容不易到，莫惜曙钟侵。','',''),('quantangshi-33617','陪友人夏夜对月','許棠','quantangshi','','卷34','后伏中宵月，高秋满魄齐。
轮移仙掌外，影下玉绳西。
蝉雀飞多悞，星萤出自迷。
烦蒸惊顿绝，吟翫畏闻鸡。','',''),('quantangshi-33618','送从弟筹任告成尉','許棠','quantangshi','','卷34','海上从戎罢，嵩阳佐县初。
故人皆羡去，吾祖旧曾居。
地古多生药，溪灵不聚鱼。
唯应寻隐者，闲寺讲仙书。','',''),('quantangshi-33619','秋日陪陆校书游玉泉','許棠','quantangshi','','卷34','共爱泉源异，频来不觉劳。
散光垂草细，繁响出风高。
沫滞潭花片，沙遗浴鸟毛。
尘间喧与闷，须向此中逃。','',''),('quantangshi-33620','送防州邬员外','許棠','quantangshi','','卷34','千溪与万嶂，缭绕复峥嵘。
太守劳车马，何从驻斾旌。
椒香近满郭，漆货远通京。
唯涤双尘耳，东南听政声。','',''),('quantangshi-33621','过穆陵关','許棠','quantangshi','','卷34','荒关无守吏，亦耻白衣过。
地广人耕绝，天寒雁下多。
东西方自感，雨雪更相和。
日暮聊摅思，摇鞭一放歌。','',''),('quantangshi-33622','江上遇友人','許棠','quantangshi','','卷34','阙下分离日，杏园花半开。
江边相值夜，榆塞雁初来。
坐久河沉斗，吟长月浸杯。
鲈鱼非不恋，共有客程催。','',''),('quantangshi-33623','忆宛陵旧居','許棠','quantangshi','','卷34','旧忆陵阳北，林园近板桥。
江晴帆影满，野迥鹤声遥。
鸟径通山市，汀扉上海潮。
秦城归去梦，夜夜到渔樵。','',''),('quantangshi-33624','题闻琴馆','許棠','quantangshi','','卷34','城非宓贱邑，馆亦号闻琴。
乃是前贤意，常留化俗心。
代公存绿绮，谁更寄清音。
此迹应无改，寥寥毕古今。','',''),('quantangshi-33625','寄江上弟妹','許棠','quantangshi','','卷34','无成归未得，不是不谋归。
垂老登云路，犹胜守钓矶。
大荒身去数，穷海信来稀。
孤立皆难进，非关命独违。','',''),('quantangshi-33626','题李昌符丰乐幽居','許棠','quantangshi','','卷34','诗家依阙下，野景似山中。
兰菊俱含露，杉梧为奏风。
破门韦曲对，浅岸御沟通。
莫叹连年屈，君须遇至公。','',''),('quantangshi-33627','青山晚望','許棠','quantangshi','','卷34','昔人怀感处，此地倍魂消。
四海经摇落，三吴正寂寥。
风移残烧远，帆带夕阳遥。
欲继前贤迹，谁能似隐招。','',''),('quantangshi-33628','宣城送进士郑徽赴举','許棠','quantangshi','','卷34','长安去是归，上马肯沾衣。
水国车通少，秦人楚荐稀。
鸿方离北鄙，叶下已西畿。
好整丹霄步，知音在紫微。','',''),('quantangshi-33629','言怀','許棠','quantangshi','','卷34','万事不关心，终朝但苦吟。
久贫慙负债，渐老爱山深。
日月销天外，帆樯弃海阴。
荣枯应已定，无复系浮沉。','',''),('quantangshi-33630','汴河十二韵','許棠','quantangshi','','卷34','昔年开汴水，元应别有由。
或兼通楚塞，宁独为扬州。
直断平芜色，横分积石流。
所思千里便，岂计万方忧。
首甚资功济，终难弭宴游。
空怀龙舸下，不见锦帆收。
浪倒长汀柳，风欹远岸楼。
奔逾怀许竭，澄彻泗滨休。
路要多行客，鱼稀少钓舟。
日开天际晚，雁合碛西秋。
一派注沧海，几人生白头。
常期身事毕，于此泳东浮。','',''),('quantangshi-33631','旅中送人归九华','許棠','quantangshi','','卷34','分与仙山背，多年负翠微。
无因随鹿去，只是送人归。
顶木晴摩日，根岚晓润衣。
会于猨鸟外，相对掩高扉。','',''),('quantangshi-33632','送友人归江南','許棠','quantangshi','','卷34','皇州五更鼓，月落西南维。
此时有行客，别我孤舟归。
上国身无主，下第诚可悲。','',''),('quantangshi-33633','洞庭湖','許棠','quantangshi','','卷34','空江浩荡景萧然，尽日菰蒲泊钓船。
青草浪高三月渡，绿杨花扑一溪烟。
情多莫举伤春目，愁极兼无买酒钱。
犹有渔人数家住，不成村落夕阳边。','',''),('quantangshi-33634','句','許棠','quantangshi','','卷34','晓嶂猨开户，寒湫鹿舐冰。
当空吟待月，到晚坐看山。
一年三领郡，领郡管仙山。','',''),('quantangshi-33635','放歌行','邵謁','quantangshi','','卷34','龟为秉灵亡，鱼为弄珠死。
心中自有贼，莫怨任公子。
屈原若不贤，焉得沈湘水。','',''),('quantangshi-33636','长安寒食','邵謁','quantangshi','','卷34','春日照九衢，春风媚罗绮。
万骑出都门，拥在香尘里。
莫辞吊枯骨，千载长如此。
安知今日身，不是昔时鬼。
但看平地游，亦见摧輈死。','',''),('quantangshi-33637','贞女墓','邵謁','quantangshi','','卷34','生持节操心，死作坚贞鬼。
至今坟上春，草木无花卉。','',''),('quantangshi-33638','自叹','邵謁','quantangshi','','卷34','春蚕未成茧，已贺箱笼实。
蟢子徒有丝，终年不成匹。
每念古人言，有得则有失。
我命独如何，憔悴长如一。
白日九衢中，幽独暗如漆。
流泉有枯时，穷贱无尽日。
惆怅复惆怅，几回新月出。','',''),('quantangshi-33639','送徐羣宰望江','邵謁','quantangshi','','卷34','古人力文学，所务安疲甿。
今人力文学，所务惟公卿。
大贤重邦本，屈迹官武城。
劝民勤机杼，自然国用并。
但见富贵者，知食不知耕。
忽尔秋不熟，储廪焉得盈。
贡艺既精苦，用心必公平。
吾道不遗贤，霄汉期芳馨。
一夫若有德，千古称其英。
陶潜虽理邑，崔烈徒台衡。
浊者必恶清，瞽者必恶明。
孤松自有色，岂夺众草荣。
为刀若不利，焉得宰牛名。
为丝若不直，焉得琴上声。
好去立高节，重来振羽翎。','',''),('quantangshi-33640','秋夕','邵謁','quantangshi','','卷34','万里凭梦归，骨肉皆在眼。
觉来益惆怅，不信长安远。
人人但为农，我独常逢旱。
恶命如漏巵，滴滴添不满。
天末雁来时，一呌一肠断。','',''),('quantangshi-33641','览孟东野集','邵謁','quantangshi','','卷34','蚌死留夜光，剑折留锋铓。
哲人归大夜，千古传圭璋。
圭璋徧四海，人伦多变改。
题花花已无，翫月月犹在。
不知天地间，白日几时昧。','',''),('quantangshi-33642','送友人江行','邵謁','quantangshi','','卷34','送君若浪水，叠叠愁思起。
梦魂如月明，相送秋江里。','',''),('quantangshi-33643','下第有感','邵謁','quantangshi','','卷34','古人有遗言，天地如掌阔。
我行三十载，青云路未达。
尝闻读书者，所贵免征伐。
谁知失意时，痛于刃伤骨。
身如石上草，根蔕浅难活。
人人皆爱春，我独愁花发。
如何归故山，相携采薇蕨。','',''),('quantangshi-33644','论政','邵謁','quantangshi','','卷34','贤哉三握髪，为有天下忧。
孙弘不开阁，丙吉宁问牛。
内政由股肱，外政由诸侯。
股肱政若行，诸侯政自修。
一物不得所，蚁穴满山丘。
莫言万木死，不因一叶秋。
朱云若不直，汉帝终自由。
子婴一失国，渭水东悠悠。','',''),('quantangshi-33645','战城南','邵謁','quantangshi','','卷34','武皇重征伐，战士轻生死。
朝争刃上功，暮作泉下鬼。
悲风吊枯骨，明日照荒垒。
千载留长声，呜咽城南水。','',''),('quantangshi-33646','赠郑殷处士','邵謁','quantangshi','','卷34','善琴不得听，嘉玉不得名。
知音既已死，良匠亦未生。
退居一河湄，山中物景清。
鱼沈池水碧，鹤去松枝轻。
长材靡入用，大厦失巨楹。
颜子不得禄，谁谓天道平。','',''),('quantangshi-33647','古乐府','邵謁','quantangshi','','卷34','对酒弹古琴，弦中发新音。
新音不可辨，十指幽怨深。
妾颜不自保，四时如车轮。
不知今夜月，曾照几时人。
露滴芙蓉香，香销心亦死。
良时无可留，残红谢池水。','',''),('quantangshi-33648','经安容先生旧居','邵謁','quantangshi','','卷34','羽化留遗踪，千载踪难没。
一泉岩下水，几度换明月。
松老不改柯，龙久皆变骨。
云雨有归时，鸡犬无还日。
至今青山中，寂寞桃花发。','',''),('quantangshi-33649','望行人','邵謁','quantangshi','','卷34','登楼恐不高，及高君已远。
云行郎即行，云归郎不返。
嗟为楼上人，望望不相近。
若作辙中泥，不放郎车转。
白日下西山，望尽妾肠断。','',''),('quantangshi-33650','岁丰','邵謁','quantangshi','','卷34','皇天降丰年，本忧贫士食。
贫士无良畴，安能得稼穑。
工佣输富家，日落长叹息。
为供豪者粮，役尽匹夫力。
天地莫施恩，施恩强者得。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33651','金谷园怀古','邵謁','quantangshi','','卷34','在富莫骄奢，骄奢多自亡。
为女莫骋容，骋容多自伤。
如何金谷园，郁郁椒兰房。
昨夜绮罗列，今日池馆荒。
竹死不变节，花落有余香。
美人抱义死，千载名犹彰。
娇歌无遗音，明月留清光。
浮云易改色，衰草难重芳。
不学韩侯妇，衔冤报宋王。','',''),('quantangshi-33652','春日有感','邵謁','quantangshi','','卷34','我心如蘖苦，他见如荠甘。
火未到身者，痛楚难共谙。
但言贫者拙，不言富者贫。
谁知苦寒女，力尽为桑蚕。','',''),('quantangshi-33653','学仙词','邵謁','quantangshi','','卷34','上仙传祕诀，澹薄与无营。
炼药□□□，变姓不变形。
三尸既无累，百虑自不生。
是知寸心中，有路通上清。
祖龙好仙术，烧却黄金精。','',''),('quantangshi-33654','妓女','邵謁','quantangshi','','卷34','天若许人登，青山高不止。
地若许人穷，黄泉深无水。
量诸造化情，物成皆有以。
如何上青冥，视之平若砥。
日下骋琅玕，空中无罗绮。
但见势腾凌，将为长如此。
炫耀一时间，逡巡九泉里。
一种为埃尘，不学堕楼死。','',''),('quantangshi-33655','寒女行','邵謁','quantangshi','','卷34','寒女命自薄，生来多贱微。
家贫人不聘，一身无所归。
养蚕多苦心，茧熟他人丝。
织素徒苦力，素成他人衣。
青楼富家女，才生便有主。
终日着罗绮，何曾识机杼。
清夜闻歌声，听之泪如雨。
他人如何欢，我意又何苦。
所以问皇天，皇天竟无语。','',''),('quantangshi-33656','览镜','邵謁','quantangshi','','卷34','一照一回悲，再照颜色衰。
日月自流水，不知身老时。
昨日照红颜，今朝照白丝。
白丝与红颜，相去咫尺间。','',''),('quantangshi-33657','轻薄行','邵謁','quantangshi','','卷34','薄薄身上衣，轻轻浮云质。
长安一花开，九陌马蹄疾。
谁言公子车，不是天上力。','',''),('quantangshi-33658','苦别离','邵謁','quantangshi','','卷34','十五为君婚，二十入君门。
自从入户后，见君长出门。
朝看相送人，暮看相送人。
若遣折杨柳，此地树无根。
愿为陌上土，得作马蹄尘。
愿为曲木枝，得作双车轮。
安得太行山，移来君马前。','',''),('quantangshi-33659','览张骞传','邵謁','quantangshi','','卷34','采药不得根，寻河不得源。
此时虚白首，徒感武皇恩。
桑田未闻改，日月曾几昏。
仙骨若求得，垄头无新坟。
不见杜陵草，至今空自繁。','',''),('quantangshi-33660','白头吟','邵謁','quantangshi','','卷34','汉家天宇阔，日月不暂闲。
常将古今骨，裨作北邙山。
山高势已极，犹自凋朱颜。','',''),('quantangshi-33661','瞽者叹','邵謁','quantangshi','','卷34','我心岂不平，我目自不明。
徒云备双足，天下何由行。','',''),('quantangshi-33662','送从弟长安下第南归觐亲','邵謁','quantangshi','','卷34','白日不得照，戴天如戴盆。
青云未见路，丹车劳出门。
采薇秦山镇，养亲湘水源。
心中岂不切，其如行路难。
为文清益峻，为心直且安。
芝兰未入用，馨香志独存。
他门种桃李，犹能荫子孙。
我家有棠阴，枝叶竟不繁。
心醉岂因酒，愁多徒见萱。
征徒忽告归，执袂殷勤论。
在鸟终为凤，为鱼须化鲲。
富贵岂长守，贫贱宁有根。
丈夫志不大，何以佐干坤。
昼短疾于箭，早来献天言。
莫恋苍梧畔，野烟横破村。','',''),('quantangshi-33663','少年行','邵謁','quantangshi','','卷34','丈夫十八九，胆气欺韩彭。
报雠不用剑，辅国不用兵。
以目为水鉴，以心作权衡。
愿君似尧舜，能使天下平。
何必走马夸弓矢，然后致得人心争。','',''),('quantangshi-33664','汉宫井','邵謁','quantangshi','','卷34','辘轳声绝离宫静，班姬几度照金井。
梧桐老去残花开，犹似当时美人影。','',''),('quantangshi-33665','显茂楼','邵謁','quantangshi','','卷34','秦山渭水尚悠悠，如何草树迷宫阙。
繁华朱翠尽东流，唯有望楼对明月。','',''),('quantangshi-33666','紫阁峯','邵謁','quantangshi','','卷34','壮国山河倚空碧，迥拔烟霞侵太白。
绿崖下视千万寻，青天只据百余尺。','',''),('quantangshi-33667','送李员外频之建州','林寬','quantangshi','','卷34','句践江头月，客星台畔松。
为郎久不见，出守暂相逢。
鸟泊牵滩索，花空押号钟。
远人思化切，休上武夷峰。','',''),('quantangshi-33668','送许棠先辈归宣州','林寬','quantangshi','','卷34','髪枯穷律韵，字字合埙篪。
日月所到处，姓名无不知。
莺啼谢守垒，苔老谪仙碑。
诗道丧来久，东归为吊之。','',''),('quantangshi-33669','穷冬太学','林寬','quantangshi','','卷34','投迹依槐馆，荒亭草合时。
雪深鸢啸急，薪湿鼎吟迟。
默坐同谁话，非僧不我知。
匡庐瀑布畔，何日副心期。','',''),('quantangshi-33670','陪郑諴郎中假日省中寓直','林寬','quantangshi','','卷34','宪厅名最重，假日许从容。
牀满诸司印，庭高五粒松。
井寻芸吏汲，茶拆岳僧封。
鸟度帘旌暮，犹吟隔苑钟。','',''),('quantangshi-33671','送谢石先辈归宣州','林寬','quantangshi','','卷34','名随春色远，湖外已先知。
花尽方辞醉，莺残是放时。
天寒千尺岳，颔白半联诗。
笋蕨犹堪采，荣归及养期。','',''),('quantangshi-33672','下第寄欧阳瓒','林寬','quantangshi','','卷34','诗人道僻命多奇，更值干戈乱起时。
莫作江宁王少府，一生吟苦竟谁知。','',''),('quantangshi-33673','寄何绍余','林寬','quantangshi','','卷34','雁过君犹未入城，清贤门下旧知名。
风波冻马遥逢见，革橐饥僮尚挈行。
住在闲坊无辙迹，别来何寺有泉声。
芙蓉苑北曲江岸，期看终南新雪晴。','',''),('quantangshi-33674','送人宰浦城','林寬','quantangshi','','卷34','东南犹阻寇，梨岭更谁登。
作宰应无俸，归船必有僧。
滩平眠獭石，烧断饮猨藤。
岁尽校殊最，方当见异能。','',''),('quantangshi-33675','省试腊后望春宫','林寬','quantangshi','','卷34','皇都初度腊，凤辇出深宫。
高凭楼台上，遥瞻灞浐中。
仗凝霜彩白，袍映日华红。
柳眼方开冻，莺声渐转风。
御沟穿断霭，骊岫照斜空。
时见宸游兴，因观稼穑功。','',''),('quantangshi-33676','寄省中知己','林寬','quantangshi','','卷34','门掩清曹晚，静将乌府邻。
花开封印早，雪下典衣频。
怪木风吹阁，废巢时落薪。
每怜吾道苦，长说向同人。','',''),('quantangshi-33677','朱坡','林寬','quantangshi','','卷34','朱坡坡上望，不似在秦京。
渐觉溪山秀，更高鱼鸟情。
夜吟禅子室，晓爨猎人铛。
恃此偷佳赏，九衢蜩未鸣。','',''),('quantangshi-33678','酬陈樵见寄','林寬','quantangshi','','卷34','失意闲眠起更迟，又将羁薄谢深知。
囊书旋入酒家尽，纱帽长依僧壁垂。
待月句新遭鬼哭，寻山貌古被猨窥。
元和才子多如此，除却清吟何所为。','',''),('quantangshi-33679','华清宫','林寬','quantangshi','','卷34','殿角钟残立宿鸦，朝元归驾望无涯。
香泉空浸宫前草，未到春时争发花。','',''),('quantangshi-33680','终南山','林寬','quantangshi','','卷34','标奇耸峻壮长安，影入千门万户寒。
徒自倚天生气色，尘中谁为举头看。','',''),('quantangshi-33681','歌风台','林寬','quantangshi','','卷34','蒿棘空存百尺基，酒酣曾唱大风词。
莫言马上得天下，自古英雄尽解诗。','',''),('quantangshi-33682','送人归日东','林寬','quantangshi','','卷34','沧溟西畔望，一望一心摧。
地即同正朔，天教阻往来。
波翻夜作电，鲸吼昼为雷。
门外人葠径，到时花几开。','',''),('quantangshi-33683','寓兴','林寬','quantangshi','','卷34','西母一杯酒，空言浩劫春。
英雄归厚土，日月照闲人。
衰草珠玑冢，冷灰龙凤身。
茂陵骊岫晚，过者暗伤神。','',''),('quantangshi-33684','少年行','林寬','quantangshi','','卷34','柳烟侵御道，门映夹城开。
白日莫空过，青春不再来。
报雠冲雪去，乘醉臂鹰回。
看取歌钟地，残阳满坏台。','',''),('quantangshi-33685','塞上还答友人','林寬','quantangshi','','卷34','无端游绝塞，归鬓已苍然。
戎羯围中过，风沙马上眠。
草衰频过烧，耳冷不闻蝉。
从此甘贫坐，休言更到边。','',''),('quantangshi-33686','哭栖白供奉','林寬','quantangshi','','卷34','侍辇才难得，三朝有上人。
琢诗方到骨，至死不离贫。
风帐孤萤入，霜堦积叶频。
夕阳门半掩，过此亦无因。','',''),('quantangshi-33687','送升道靖恭相公分司','林寬','quantangshi','','卷34','东风时不遇，果见致君难。
海岳影犹动，鵾鹏势未安。
星沈关锁冷，鸡唱驿灯残。
谁似二宾客，门闲嵩洛寒。','',''),('quantangshi-33688','关下早行','林寬','quantangshi','','卷34','轧轧推危辙，听鸡独早行。
风吹宿霭散，月照华山明。
白首东西客，黄河昼夜清。
相逢皆有事，唯我是闲情。','',''),('quantangshi-33689','曲江','林寬','quantangshi','','卷34','曲江初碧草初青，万毂千蹄匝岸行。
倾国妖姬云鬓重，薄徒公子雪衫轻。
琼镌狒𤝞遶觥舞，金蹙辟邪拏拨鸣。
柳絮杏花留不得，随风处处逐歌声。','',''),('quantangshi-33690','长安遣怀','林寬','quantangshi','','卷34','醉下高楼醒复登，任从浮薄笑才能。
青龙寺里三门上，立为南山不为僧。','',''),('quantangshi-33691','送僧游太白峰','林寬','quantangshi','','卷34','云深游太白，莫惜遍探奇。
顶上多灵迹，尘中少客知。
悬崖倚冻瀑，飞狖过孤枝。
出定更何事，相逢必有诗。','',''),('quantangshi-33692','哭造微禅师','林寬','quantangshi','','卷34','神迁不火葬，新塔露疎柽。
是物皆磨灭，唯师出死生。
虚堂散钓叟，怪木哭山精。
林下路长在，无因更此行。','',''),('quantangshi-33693','献同年孔郎中','林寬','quantangshi','','卷34','炊琼爇桂帝关居，卖尽寒衣典尽书。
驱马每寻霜影里，到门常在鼓声初。
蟾枝交彩清兰署，鸾佩排光映玉除。
一顾深恩身未杀，争期皎日负吹嘘。','',''),('quantangshi-33694','闻雁','林寬','quantangshi','','卷34','接影横空背雪飞，声声寒出玉关迟。
上阳宫里三千梦，月冷风清闻过时。','',''),('quantangshi-33695','送惠补阙','林寬','quantangshi','','卷34','诏下搜岩野，高人入竹林。
长因抗疏日，便作去官心。
清俸供僧尽，沧洲寄迹深。
东门有归路，徒自弃华簪。','',''),('quantangshi-33696','和友人贼后','林寬','quantangshi','','卷34','带号乞兵急，英雄陷贼围。
江山犹未静，鱼鸟欲何归。
城露桑榆尽，时平老幼稀。
书从战后得，读彻血盈衣。','',''),('quantangshi-33697','长安即事','林寬','quantangshi','','卷34','暝鼓才终复晓鸡，九门何计出沈迷。
樵童乱打金吾鼓，豪马争奔丞相堤。
翡翠鬟欹钗上燕，麒麟衫束海中犀。
须知不是诗人事，空忆泉声菊畔畦。','',''),('quantangshi-33698','和周繇校书先辈省中寓直','林寬','quantangshi','','卷34','古木重门掩，幽深秖欠溪。
此中真吏隐，何必更岩栖。
名姓镌幢记，经书逐库题。
字随飞蠹缺，堦与落星齐。
伴直僧谈静，侵霜蛩韵低。
粘尘贺草没，剥粉薛禽迷。
衰藓墙千堵，微阳菊半畦。
鼓残鸦去北，漏在月沈西。
每忆终南雪，几登云阁梯。
时因搜句次，那惜一招携。','',''),('quantangshi-33699','苦雨','林寬','quantangshi','','卷34','霪霖翳日月，穷巷变沟坑。
骤洒纤枝折，奔倾坏堵平。
蒙[簦]来客绝，跃甃噪蛙狞。
败屐阴苔积，摧檐湿菌生。
斜飞穿裂瓦，迸落打空铛。
叶底迟归蝶，林中滞出莺。
润侵书缝黑，冷浸鬓丝明。
牖暗参差影，堦寒断续声。
尺薪功比桂，寸粒价高琼。
遥想管弦里，无因识此情。','',''),('quantangshi-33700','翰林作','劉鄴','quantangshi','','卷34','曾是江波垂钓人，自怜深厌九衢尘。
浮生渐老年随水，往事曾闻泪满巾。
已觉远天秋色动，不堪闲夜雨声频。
多惭不是相如笔，虚直金銮接侍臣。','',''),('quantangshi-33701','待漏院吟','劉鄴','quantangshi','','卷34','玉堂帘外独迟迟，明月初沈勘契时。
闲听景阳钟尽后，两莺飞上万年枝。','',''),('quantangshi-33702','慧山寺肄业送怀坦上人','李騭','quantangshi','','卷34','流水何山分，浮云空中遇。
我生无根株，聚散亦难固。
忆昨鬬龙春，岩栖侣高步。
清怀去羁束，幽境无滓污。
日落九峰明，烟生万华暮。
兹欢未云隔，前笑倏已故。
四时难信留，百草换霜露。
离襟一成解，怅抱将何谕。
惊泉有余哀，永日谁与度。
缅思孤帆影，再往重江路。
去去忽凄悲，因风暂回顾。','',''),('quantangshi-33703','读惠山若冰师集因题故院三首 一','李騭','quantangshi','','卷34','五天何处望，心念起皆知。
化塔留今日，泉鸣自昔时。
古苔生石静，秋草满山悲。
莫道声容远，长歌白雪词。','',''),('quantangshi-33704','读惠山若冰师集因题故院三首 二','李騭','quantangshi','','卷34','高怀逢异境，佳句想吟频。
月冷松溪夜，烟浓草寺春。
浮云将世远，清听与名新。
不见开岩日，空为拜影人。','',''),('quantangshi-33705','读惠山若冰师集因题故院三首 三','李騭','quantangshi','','卷34','景物搜求歇，山云放纵飞。
树寒烟鹤去，池静水龙归。
暗榻尘飘满，阴檐月到稀。
何年灯焰尽，风动影堂扉。','',''),('quantangshi-33706','自惠山至吴下寄酬南徐从事','李騭','quantangshi','','卷34','不接芳晨游，独此长洲苑。
风颜一成阻，翰墨劳空返。
悠悠汀渚长，杳杳苹花晚。
如何西府欢，尚念东吴远。
瑶音动清韵，兰思芬盈畹。
犹及九峰春，归吟白云巘。','',''),('quantangshi-33707','中秋夜戏酬顾道流','孫蜀','quantangshi','','卷34','不那此身偏爱月，等闲看月即更深。
仙翁每被嫦娥使，一度逢圆一度吟。','',''),('quantangshi-33708','咏燕上主司郑愚','歐陽澥','quantangshi','','卷34','翩翩双燕画堂开，送古迎今几万回。
长向春秋社前后，为谁归去为谁来。','',''),('quantangshi-33709','句','歐陽澥','quantangshi','','卷34','黄菊离家十四年，离家已是梦松年。
落日望乡处，何人知客情。','',''),('quantangshi-33710','自咏豆花','陳黯','quantangshi','','卷34','玳瑁应难比，斑犀定不加。
天嫌未端正，满面与妆花。','',''),('quantangshi-33711','雪诗','張孜','quantangshi','','卷34','长安大雪天，鸟雀难相觅。
其中豪贵家，捣椒泥四壁。
到处爇红炉，周回下罗幂。
暖手调金丝，蘸甲斟琼液。
醉唱玉尘飞，困融香汗滴。
岂知饥寒人，手脚生皴劈。','',''),('quantangshi-33712','句','張孜','quantangshi','','卷34','着牙卖朱紫，断钱赊举选。
华山秀作英雄骨，黄河泻出纵横才。
梦破青霄春，烟霞无去尘。
若夸郭璞五色笔，江淹却是寻常人。','',''),('quantangshi-33713','赠妓仙哥','鄭仁表','quantangshi','','卷34','严吹如何下太清，玉肌无疹六铢轻。
自知不是流霞酌，愿听云和瑟一声。','',''),('quantangshi-33714','赠妓命洛真','鄭仁表','quantangshi','','卷34','巧制新章拍拍新，金罍巡举助精神。
时时欲得横波眄，又怕回筹错指人。','',''),('quantangshi-33715','句','鄭仁表','quantangshi','','卷34','文章世上争开路，阀阅山东拄破天。','',''),('quantangshi-33716','杜甫同谷茅茨','趙鴻','quantangshi','','卷34','工部栖迟后，邻家大半无。
青羌迷道路，白社寄杯盂。
大雅何人继，全生此地孤。
孤云飞鸟什，空勒旧山隅。','',''),('quantangshi-33717','栗亭','趙鴻','quantangshi','','卷34','杜甫栗亭诗，诗人多在口。
悠悠二甲子，题纪今何有。','',''),('quantangshi-33718','泥功山','趙鴻','quantangshi','','卷34','立石泥功状，天然诡怪形。
未尝私祸福，终不费丹青。','',''),('quantangshi-33719','昆明池织女石','童翰卿','quantangshi','','卷34','一片昆明石，千秋织女名。
见人虚脉脉，临水更盈盈。
苔作轻衣色，波为促杼声。
岸云连鬓湿，沙月对眉生。
有脸莲同笑，无心鸟不惊。
还如朝镜里，形影两分明。','',''),('quantangshi-33720','绝句','童翰卿','quantangshi','','卷34','大朴逐物尽，哀我天地功。
争得荣辱心，洒然归西风。','',''),('quantangshi-33721','补周礼九夏系文 一','皮日休','quantangshi','','卷34','爣爣皎日，歘丽于天。
厥明御舒，如王出焉。','',''),('quantangshi-33722','补周礼九夏系文 二','皮日休','quantangshi','','卷34','爣爣皎日，歘入于地。
厥晦厥贞，如王入焉。','',''),('quantangshi-33723','补周礼九夏系文 三','皮日休','quantangshi','','卷34','出有龙旗，入有珩佩。
勿驱勿驰，惟慎惟戒。','',''),('quantangshi-33724','补周礼九夏系文 四','皮日休','quantangshi','','卷34','出有嘉谋，入有内则。
繄彼臣庶，钦王之式。','',''),('quantangshi-33725','补周礼九夏系文 一','皮日休','quantangshi','','卷34','愔愔清庙，仪仪象服。
我尸出矣，迎神之谷。','',''),('quantangshi-33726','补周礼九夏系文 二','皮日休','quantangshi','','卷34','杳杳阴竹，坎坎路鼓。
我尸入矣，得神之祜。','',''),('quantangshi-33727','补周礼九夏系文 一','皮日休','quantangshi','','卷34','有郁其鬯，有俨其彝。
九变未作，全乘来之。','',''),('quantangshi-33728','补周礼九夏系文 二','皮日休','quantangshi','','卷34','既醑既酢，爰朄爰舞。
象物既降，全乘之去。','',''),('quantangshi-33729','补周礼九夏系文 一','皮日休','quantangshi','','卷34','麟之仪仪，不絷不维。
乐德而至，如宾之嬉。','',''),('quantangshi-33730','补周礼九夏系文 二','皮日休','quantangshi','','卷34','凤之愉愉，不篝不笯。
乐德而至，如宾之娱。','',''),('quantangshi-33731','补周礼九夏系文 三','皮日休','quantangshi','','卷34','自筐及筥，我有牢醑。
自筐及篚，我有货币。','',''),('quantangshi-33732','补周礼九夏系文 四','皮日休','quantangshi','','卷34','我牢不愆，我货不匮。
硕硕其才，有乐而止。','',''),('quantangshi-33733','补周礼九夏系文 一','皮日休','quantangshi','','卷34','王有虎臣，锡之鈇钺。
征彼不憓，一扑而灭。','',''),('quantangshi-33734','补周礼九夏系文 二','皮日休','quantangshi','','卷34','王有虎臣，锡之圭瓒。
征彼不享，一烘而泮。','',''),('quantangshi-33735','补周礼九夏系文 三','皮日休','quantangshi','','卷34','王有掌讶，遉尔疆理。
王有掌客，馈尔饔饩。','',''),('quantangshi-33736','补周礼九夏系文 四','皮日休','quantangshi','','卷34','何以乐之，金石九奏。
何以锡之，龙旗九旒。','',''),('quantangshi-33737','补周礼九夏系文','皮日休','quantangshi','','卷34','𤫩𤫩衡笄，翚衣褕翟。
自内而祭，为君之则。','',''),('quantangshi-33738','补周礼九夏系文 一','皮日休','quantangshi','','卷34','洪源谁孕，疏为江河。
大块孰埏，播为山阿。','',''),('quantangshi-33739','补周礼九夏系文 二','皮日休','quantangshi','','卷34','厥流浩漾，厥势嵯峨。
今君之酌，慰我实多。','',''),('quantangshi-33740','补周礼九夏系文 一','皮日休','quantangshi','','卷34','礼酒既酌，嘉宾既厚，牍为之奏。','',''),('quantangshi-33741','补周礼九夏系文 二','皮日休','quantangshi','','卷34','礼酒既竭，嘉宾既悦，应为之节。','',''),('quantangshi-33742','补周礼九夏系文 三','皮日休','quantangshi','','卷34','礼酒既罄，嘉宾既醒，雅为之行。','',''),('quantangshi-33743','补周礼九夏系文 一','皮日休','quantangshi','','卷34','桓桓其圭，衮衮其衣。
出作二伯，天子是毗。','',''),('quantangshi-33744','补周礼九夏系文 二','皮日休','quantangshi','','卷34','桓桓其圭，衮衮其服。
入作三孤，国人是福。','',''),('quantangshi-33745','三羞诗三首','皮日休','quantangshi','','卷34','吾闻古君子，介介励其节。
入门疑储宫，抚己思鈇钺。
志者若不退，佞者何由达。
君臣一肴膳，家国共残杀。
此道见于今，永思心若裂。
王臣方謇謇，佐我无玷缺。
如何以谋计，中道生芽蘖。
宪司遵故典，分道播南越。
苍惶出班行，家室不容别。
玄鬓行为霜，清泪立成血。
乘遽剧飞鸟，就传过风发。
嗟吾何为者，叨在造士列。
献文不上第，归于淮之汭。
蹇蹄可再犇，退羽可后歇。
利则侣轩裳，塞则友松月。
而于方寸内，未有是愁结。
未为禄食仕，俯不愧粱粝。
未为冠冕人，死不慙忠烈。
如何有是心，不能叩丹阙。
赫赫负君归，南山采芝蕨。','',''),('quantangshi-33746','三羞诗三首','皮日休','quantangshi','','卷34','南荒不择吏，致我交址覆。
緜联三四年，流为中夏辱。
懦者鬬即退，武者兵则黩。
军庸满天下，战将多金玉。
刮则齐民癕，分为猛士禄。
雄健许昌师，忠武冠其族。
去为万骑风，住作一川肉。
昨朝残卒回，千门万户哭。
哀声动闾里，怨气成山谷。
谁能听昼鼙，不忍看金镞。
吾有制胜术，不奈贱碌碌。
贮之胸臆间，慙见许师属。
自嗟胡为者，得蹑前修躅。
家不出军租，身不识部曲。
亦衣许师衣，亦食许师粟。
方知古人道，荫我已为足。
念此向谁羞，悠悠颍川绿。','',''),('quantangshi-33747','三羞诗三首','皮日休','quantangshi','','卷34','天子丙戌年，淮右民多饥。
就中颍之汭，转徙何累累。
夫妇相顾亡，弃却抱中儿。
兄弟各自散，出门如大痴。
一金易芦卜，一缣换凫茈。
荒村墓鸟树，空屋野花篱。
儿童啮草根，倚桑空羸羸。
斑白死路傍，枕土皆离离。
方知圣人教，于民良在斯。
厉能去人爱，荒能夺人慈。
如何司牧者，有术皆在兹。
粤吾何为人，数亩清溪湄。
一写落第文，一家欢复嬉。
朝食有麦饘，晨起有布衣。
一身既饱暖，一家无怨咨。
家虽有畎亩，手不秉镃基。
岁虽有札瘥，庖不废晨炊。
何道以致是，我有明公知。
食之以侯食，衣之以侯衣。
归时恤金帛，使我奉庭闱。
抚己愧颍民，奚不进德为。
因兹感知己，尽日空涕涕。','',''),('quantangshi-33748','七爱诗 房杜二相国','皮日休','quantangshi','','卷34','吾爱房与杜，贫贱共联步。
脱身抛乱世，策杖归真主。
纵横握中算，左右天下务。
肮脏无敌才，磊落不世遇。
美矣名公卿，魁然真宰辅。
黄阁三十年，清风一万古。
巨业照国史，大勋镇王府。
遂使后世民，至今受陶铸。
粤吾少有志，敢蹑前贤路。
苟得同其时，愿为执鞭竖。','',''),('quantangshi-33749','七爱诗 李太尉','皮日休','quantangshi','','卷34','吾爱李太尉，崛起定中原。
骁雄十万兵，四面围国门。
一战取王畿，一叱散妖氛。
乘舆既反正，凶竖争亡魂。
巍巍柱天功，荡荡盖世勋。
仁于曹孟德，勇过霍将军。
丹券入帑藏，青史传子孙。
所谓大丈夫，动合惊干坤。
所谓圣天子，难得忠贞臣。
下以契鱼水，上以合风云。
百世必一乱，千年方一人。
吾虽翰墨子，气概敢不羣。
愿以太平颂，题向甘泉春。','',''),('quantangshi-33750','七爱诗 卢征君','皮日休','quantangshi','','卷34','吾爱卢征君，高卧嵩山里。
百辟未一顾，三征方暂起。
坦腹对宰相，岸帻揖天子。
建礼门前吟，金銮殿里醉。
天下皆哺糟，真君独洁己。
天下皆乐闻，征君独洗耳。
天下皆怀羞，征君独多耻。
银黄不妨悬，赤绂不妨被。
而于心抱中，独作羲皇地。
篮舆一云返，泥诏褒不已。
再看缑山云，重酌嵩阳水。
放旷书里终，逍遥醉中死。
吾谓伊与周，不若征君贵。
吾谓巢与许，不若征君义。
高名无阶级，逸迹绝涯涘。
万世唐书中，逸名不可比。
粤吾慕真隐，强以骨肉累。
如教不为名，敢有征君志。','',''),('quantangshi-33751','七爱诗 元鲁山','皮日休','quantangshi','','卷34','吾爱元紫芝，清介如伯夷。
辇母远之官，宰邑无玷疵。
三年鲁山民，丰稔不暂饥。
三年鲁山吏，清慎各自持。
只饮鲁山泉，只采鲁山薇。
一室冰檗苦，四远声光飞。
退归旧隐来，斗酒入茅茨。
鸡黍匪家畜，琴尊常自怡。
尽日一菜食，穷年一布衣。
清似匣中镜，直如琴上丝。
世无用贤人，青山生白髭。
既卧黔娄衾，空立陈寔碑。
吾无鲁山道，空有鲁山辞。
所恨不相识，援毫空涕垂。','',''),('quantangshi-33752','七爱诗 李翰林','皮日休','quantangshi','','卷34','吾爱李太白，身是酒星魄。
口吐天上文，迹作人间客。
磥砢千丈林，澄澈万寻碧。
醉中草乐府，十幅笔一息。
召见承明庐，天子亲赐食。
醉曾吐御牀，傲几触天泽。
权臣妬逸才，心如斗筲窄。
失恩出内署，海岳甘自适。
刺谒戴接㒿，赴宴着縠屐。
诸侯百步迎，明君九天忆。
竟遭腐胁疾，醉魄归八极。
大鹏不可笼，大椿不可植。
蓬壶不可见，姑射不可识。
五岳为辞锋，四溟作胸臆。
惜哉千万年，此俊不可得。','',''),('quantangshi-33753','七爱诗 白太傅','皮日休','quantangshi','','卷34','吾爱白乐天，逸才生自然。
谁谓辞翰器，乃是经纶贤。
歘从浮艳诗，作得典诰篇。
立身百行足，为文六艺全。
清望逸内署，直声惊谏垣。
所刺必有思，所临必可传。
忘形任诗酒，寄傲徧林泉。
所望标文柄，所希持化权。
何期遇訾毁，中道多左迁。
天下皆汲汲，乐天独怡然。
天下皆闷闷，乐天独舍旃。
高吟辞两掖，清啸罢三川。
处世似孤鹤，遗荣同脱蝉。
仕若不得志，可为龟镜焉。','',''),('quantangshi-33754','正乐府十篇 卒妻怨','皮日休','quantangshi','','卷34','河湟戍卒去，一半多不回。
家有半菽食，身为一囊灰。
官吏按其籍，伍中斥其妻。
处处鲁人髽，家家杞妇哀。
少者任所归，老者无所携。
况当札瘥年，米粒如琼瑰。
累累作饿殍，见之心若摧。
其夫死锋刃，其室委尘埃。
其命即用矣，其赏安在哉。
岂无黔敖恩，救此穷饿骸。
谁知白屋士，念此飜唉唉。','',''),('quantangshi-33755','正乐府十篇 橡媪叹','皮日休','quantangshi','','卷34','秋深橡子熟，散落榛芜冈。
伛伛黄髪媪，拾之践晨霜。
移时始盈掬，尽日方满筐。
几曝复几蒸，用作三冬粮。
山前有熟稻，紫穗袭人香。
细获又精舂，粒粒如玉璫。
持之纳于官，私室无仓箱。
如何一石余，只作五斗量。
狡吏不畏刑，贪官不避赃。
农时作私债，农毕归官仓。
自冬及于春，橡实诳饥肠。
吾闻田成子，诈仁犹自王。
吁嗟逢橡媪，不觉泪霑裳。','',''),('quantangshi-33756','正乐府十篇 贪官怨','皮日休','quantangshi','','卷34','国家省闼吏，赏之皆与位。
素来不知书，岂能精吏理。
大者或宰邑，小者皆尉史。
愚者皆混沌，毒者如雄虺。
伤哉尧舜民，肉袒受鞭棰。
吾闻古圣王，天下无遗士。
朝庭及下邑，治者皆仁义。
国家选贤良，定制兼拘忌。
所以用此徒，令之充禄仕。
何不广取人，何不广历试？
下位既贤哉，上位何如矣。
胥徒赏以财，俊造悉为吏。
天下若不平，吾当甘弃市。','',''),('quantangshi-33757','正乐府十篇 农父谣','皮日休','quantangshi','','卷34','农父冤辛苦，向我述其情。
难将一人农，可备十人征。
如何江淮粟，挽漕输咸京。
黄河水如电，一半沈与倾。
均输利其事，职司安敢评。
三川岂不农，三辅岂不耕。
奚不车其粟，用以供天兵。
美哉农父言，何计达王程。','',''),('quantangshi-33758','正乐府十篇 路臣恨','皮日休','quantangshi','','卷34','路臣何方来，去马真如龙。
行骄不动尘，满辔金珑璁。
有人自天来，将避荆棘丛。
狞呼不觉止，推下苍黄中。
十夫掣鞭策，御之如惊鸿。
日行六七邮，瞥若鹰无踪。
路臣慎勿愬，愬则刑尔躬。
军期方似雨，天命正如风。
七雄战争时，宾旅犹自通。
如何太平世，动步却途穷。','',''),('quantangshi-33759','正乐府十篇 贱贡士','皮日休','quantangshi','','卷34','南越贡珠玑，西蜀进罗绮。
到京未晨旦，一一见天子。
如何贤与俊，为贡贱如此。
所知不可求，敢望前席事。
吾闻古圣人，射宫亲选士。
不肖尽屏迹，贤能皆得位。
所以谓得人，所以称多士。
叹息几编书，时哉又何异。','',''),('quantangshi-33760','正乐府十篇 颂夷臣','皮日休','quantangshi','','卷34','夷师本学外，仍善唐文字。
吾人本尚舍，何况夷臣事。
所以不学者，反为夷臣戏。
所以尸禄人，反为夷臣忌。
吁嗟华风衰，何尝不由是。','',''),('quantangshi-33761','正乐府十篇 惜义鸟','皮日休','quantangshi','','卷34','商颜多义鸟，义鸟实可嗟。
危巢末累累，隐在栲木花。
他巢若有雏，乳之如一家。
他巢若遭捕，投之同一罗。
商人每秋贡，所贵复如何。
饱以稻粱滋，饰以组绣华。
惜哉仁义禽，委戏于宫娥。
吾闻凤之贵，仁义亦足夸。
所以不遭捕，盖缘生不多。','',''),('quantangshi-33762','正乐府十篇 诮虚器','皮日休','quantangshi','','卷34','襄阳作髹器，中有库露真。
持以遗北虏，绐云生有神。
每岁走其使，所费如云屯。
吾闻古圣王，修德来远人。
未闻作巧诈，用欺禽兽君。
吾道尚如此，戎心安足云。
如何汉宣帝，却得呼韩臣。','',''),('quantangshi-33763','正乐府十篇 哀陇民','皮日休','quantangshi','','卷34','陇山千万仞，鹦鹉巢其巅。
穷危又极嶮，其山犹不全。
蚩蚩陇之民，悬度如登天。
空中觇其巢，堕者争纷然。
百禽不得一，十人九死焉。
陇川有戍卒，戍卒亦不闲。
将命提雕笼，直到金台前。
彼毛不自珍，彼舌不自言。
胡为轻人命，奉此玩好端。
吾闻古圣王，珍兽皆舍旃。
今此陇民属，每岁啼涟涟。','',''),('quantangshi-33764','奉献致政裴祕监','皮日休','quantangshi','','卷34','何胤本征士，高情动天地。
既无阀阅门，常嫌冠冕累。
宰邑着嘉政，为郡留高致。
移官在书府，方乐鸳池贵。
玉季牧江西，泣之不忍离。
舍杖随之去，天下钦高义。
乌帽白絺裘，篮舆竹如意。
黄菊陶潜酒，青山谢公妓。
月槛咏诗情，花溪钓鱼戏。
钟陵既方舟，魏阙将结驷。
甘求白首闲，不为苍生起。
优诏加大监，所以符公议。
既为逍遥公，又作鸱夷子。
安车悬不出，驷马闲无事。
微雨汉陂舟，残日终南骑。
富贵尽凌云，何人能至此。
猜祸皆及身，何复至如是。
贤哉此丈夫，百世一人矣。','',''),('quantangshi-33765','秋夜有怀','皮日休','quantangshi','','卷34','梦里忧身泣，觉来衣尚湿。
骨肉煎我心，不是谋生急。
如何欲佐主，功名未成立。
处世既孤特，传家无承袭。
明朝走梁楚，步步出门涩。
如何一寸心，千愁万愁入。','',''),('quantangshi-33766','喜鹊','皮日休','quantangshi','','卷34','弃膻在庭际，双鹊来摇尾。
欲啄怕人惊，喜语晴光里。
何况佞幸人，微禽解如此。','',''),('quantangshi-33767','蚊子','皮日休','quantangshi','','卷34','隐隐聚若雷，噆肤不知足。
皇天若不平，微物教食肉。
贫士无绛纱，忍苦卧茅屋。
何事觅膏腴，腹无太仓粟。','',''),('quantangshi-33768','鹿门夏日','皮日休','quantangshi','','卷34','满院松桂阴，日午却不知。
山人睡一觉，庭鹊立未移。
出檐趁云去，忘戴白接㒿。
书眼若薄雾，酒肠如漏巵。
身外所劳者，饮食须自持。
何如便绝粒，直使身无为。','',''),('quantangshi-33769','偶书','皮日休','quantangshi','','卷34','女娲掉绳索，絙泥成下人。
至今顽愚者，生如土偶身。
云物养吾道，天爵高我贫。
大笑猗氏辈，为富皆不仁。','',''),('quantangshi-33770','读书','皮日休','quantangshi','','卷34','家资是何物，积帙列梁梠。
高斋晓开卷，独共圣人语。
英贤虽异世，自古心相许。
案头见蠹鱼，犹胜凡俦侣。','',''),('quantangshi-33771','贫居秋日','皮日休','quantangshi','','卷34','亭午头未冠，端坐独愁予。
贫家烟爨稀，竈底阴虫语。
门小愧车马，廪空慙雀鼠。
尽室未寒衣，机声羡邻女。','',''),('quantangshi-33772','鲁望读襄阳耆旧传见赠五百言过褒庸材靡有称是然襄阳曩事历历在目夫耆旧传所未载者汉阳王则宗社元勋孟浩然则文章大匠予次而赞之因而寄答亦诗人无言不酬之义也次韵','皮日休','quantangshi','','卷34','汉水碧于天，南荆廓然秀。
庐罗遵古俗，鄢郢迷昔囿。
幽奇无得状，巉绝不能究。
兴替忽矣新，山川悄然旧。
斑斑生造士，一一应玄宿。
巴庸乃嶮岨，屈景实豪右。
是非既自分，泾渭不相就。
粤自灵均来，清才若天漱。
伟哉洞上隐，卓尔隆中耨。
始将麋鹿狎，遂与麒麟鬬。
万乘不可谒，千钟固非茂。
爰从景升死，境上多兵候。
檀溪试戈船，岘岭屯贝胄。
寂莫数百年，质唯包砾琇。
上玄赏唐德，生贤命之授。
是为汉阳王，帝曰俞尔奏。
巨德耸神鬼，宏才轹前后。
势端唯金茎，质古乃玉豆。
行叶荫大椿，词源吐洪溜。
六成清庙音，一柱明堂构。
在昔房陵迁，圆穹正中漏。
繄王揭然出，上下拓宇宙。
俯视三事者，呆呆若童幼。
低摧护中兴，若凤视其鷇。
遇险必伸足，逢诛将引脰。
既正北极尊，遂治众星谬。
重闻章陵幸，再见岐阳狩。
日似新刮膜，天如重熨绉。
易政疾似欬，求贤甚于购。
化之未朞年，民安而国富。
翼卫两舜趋，钩陈十尧骤。
忽然遗相印，如羿卸其彀。
奸幸却乘衅，播迁遂终寿。
遗庙屹峰崿，功名纷组绣。
开元文物盛，孟子生荆岫。
斯文纵奇巧，秦玺新雕镂。
甘穷卧牛衣，受辱对狗窦。
思变如易爻，才通似玄首。
祕于龙宫室，怪于天篆籀。
知者竞欲戴，嫉者或将诟。
任达且百觚，遂为当时陋。
既作才鬼终，恐为仙籍售。
予生二贤末，得作升木狖。
兼济与独善，俱敢怀其臭。
江汉称炳灵，克明嗣清昼。
继彼欲为三，如醨如醇酎。
既见陆夫子，驽心却伏厩。
结彼世外交，遇之于邂逅。
两鹤思竞闲，双松格争瘦。
唯恐别仙才，涟涟涕襟袖。','',''),('quantangshi-33773','鲁望昨以五百言见贻过有褒美内揣庸陋弥增愧悚因成一千言上述吾唐文物之盛次叙相得之欢亦迭和之微旨也','皮日休','quantangshi','','卷34','三辰至精气，生自苍颉前。
粤从有文字，精气铢于緜。
所以杨墨后，文词纵横颠。
元狩富材术，建安俨英贤。
厥祀四百余，作者如排穿。
五马渡江日，羣鱼食蒲年。
大风荡天地，万阵黄须膻。
纵有命世才，不如一空弮。
后至陈隋世，得之拘且緛。
太浮如潋滟，太细如蚳蝝。
太乱如靡靡，太轻如芊芊。
流之为䣱醟，变之为游畋。
百足虽云众，不救杀马蚿。
君臣作降虏，北走如㺦猭。
所以文字妖，致其国朝迁。
吾唐革其弊，取士将科县。
文星下为人，洪秀密于缏。
大开紫宸扉，来者皆详延。
日晏朝不罢，龙姿欢𨌈𨌈。
于焉周道反，由是秦法悛。
射洪陈子昂，其声亦喧阗。
惜哉不得时，将奋犹拘挛。
玉垒李太白，铜堤孟浩然。
李宽包堪舆，孟澹拟漪涟。
埋骨采石圹，留神鹿门埏。
俾其羇旅死，实觉天地孱。
猗与子美思，不尽如转辁。
纵为三十车，一字不可捐。
既作风雅主，遂司歌咏权。
谁知耒阳土，埋却真神仙。
当于李杜际，名辈或溯沿。
良御非异马，由弓非他弦。
其物无同异，其人有媸妍。
自开元至今，宗社纷如烟。
爽若沆瀣英，高如昆仑巅。
百家嚣浮说，诸子率寓篇。
筑之为京观，解之为牲牷。
各持天地维，率意东西牵。
竞抵元化首，争扼真宰咽。
或作制诰薮，或为宫体渊。
或堪被金石，或可投花钿。
或为舆隶唱，或被儿童怜。
乌垒虏亦写，鸡林夷争传。
披揭覆载枢，捭阖神异键。
力抛尾闾立，思轧大块旋。
降气或若虹，耀影或如{艹/冖/残}。
万象疮复痏，百灵瘠且{疒}。
谓乎数十公，笔若明堂椽。
其中有拟者，不绝当如綖。
齐驱不让策，竝驾或争骈。
所以吾唐风，直将三代甄。
被此文物盛，由乎声诗宣。
采彼风人谣，輶轩轻似鹯。
丽者固不舍，鄙者亦为铨。
其中有銮戒，一一堪雕镌。
乙夜以观之，吾君无释焉。
遂命大司乐，度之如星躔。
播于乐府中，俾为万代蠲。
吹彼圆丘竹，诵兹清庙弦。
不惟娱列祖，兼可格上玄。
粤予何为者，生自江海壖。
呆呆自总角，不甘耕一壥。
诸昆指仓库，谓我死道边。
何为不力农，稽古真可嘕。
遂与襏襫着，兼之籉笠全。
风吹蔓草花，飒飒盈荒田。
老牛瞪不行，力弱谁能鞭。
乃将耒与耜，竝换椠与铅。
阅彼图籍肆，致之千百编。
携将入苏岭，不就无出缘。
堆书塞低屋，添砚涸小泉。
对灯任髻爇，冯案从肘研。
苟无切玉刀，难除指上胼。
尔来五寒暑，试艺称精专。
昌黎道未着，文教如欲骞。
其中有声病，于我如𦧝𦧴。
是敢驱颓波，归之于大川。
其文如可用，不敢佞与便。
明水在稾秸，太羹临豆笾。
将来示时人，䝟貐垂馋涎。
亦或尚华缛，亦曾为便嬛。
亦能制灏灏，亦解攻翩翩。
唯思逢阵敌，与彼争后先。
避兵入句吴，穷悴祗自跧。
平原陆夫子，投刺来翩跹。
开卷读数行，为之加敬虔。
忽穷一两首，反顾唯曲拳。
始来遗巾帼，乃敢排戈鋋。
或为拔帜走，或遭劘垒还。
不能收乱辙，岂暇重为篿。
虽然未三北，亦可输千铣。
向来说文字，尔汝名可联。
圣人病殁世，不患穷而蹎。
我未九品位，君无一囊钱。
相逢得何事，两笼酬戏牋。
无颜解偷合，底事居冗员。
方知万钟禄，不博五湖船。
夷[险]但明月，死生应白莲。
吟余凭几饮，钓罢偎蓑眠。
终抛岘山业，相共此留连。','',''),('quantangshi-33774','吴中苦雨因书一百韵寄鲁望','皮日休','quantangshi','','卷34','全吴临巨溟，百里到沪渎。
海物竞骈罗，水怪争渗漉。
狂蜃吐其气，千寻勃然蹙。
一刷半天墨，架为欹危屋。
怒鲸瞪相向，吹浪山毂毂。
倏忽腥杳冥，须臾坼崖谷。
帝命有严程，慈物有潜伏。
嘘之为玄云，弥亘千万幅。
直拔倚天劒，又建横海纛。
化之为暴雨，潨潨射平陆。
如将月窟写，似把天河扑。
着树胜戟支，中人过箭镞。
龙光倏闪照，虬角搊琤触。
此时一千里，平下天台瀑。
雷公恣其志，䃸磹裂电目。
蹋破霹雳车，折却三四辐。
雨工避罪者，必在蚊睫宿。
狂发铿訇音，不得懈怠僇。
顷刻势稍止，尚自倾蔌蔌。
不敢履洿处，恐蹋烂地轴。
自尔凡十日，茫然晦林麓。
只是遇滂沱，少曾逢霢霂。
伊余之廨宇，古制拙卜筑。
颓檐倒菌黄，破砌顽莎绿。
只有方丈居，其中蹐且局。
朽处或似醉，漏时又如沃。
阶前平泛滥，墙下起趢趚。
唯堪着籉笠，复可乘𦨧宿。
鸡犬竝淋漓，儿童但咿噢。
勃勃生湿气，人人牢于锔。
须眉渍将断，肝膈蒸欲熟。
当庭死兰芷，四垣盛薋菉。
解帙展断书，拂牀安坏椟。
跳梁老蛙黾，直向牀前浴。
蹲前但相聒，似把白丁辱。
空厨方欲炊，渍米未离䉛。
薪蒸湿不着，白昼须然烛。
污莱既已泞，买鱼不获䱙。
竟未成麦饘，安能得粱肉。
更有陆先生，荒林抱穷蹙。
坏宅四五舍，病筱三两束。
盖檐低碍首，藓地滑㳠足。
注欲透承尘，湿难庇厨簏。
低摧在圭窦，索漠抛偏裻。
手指既已胼，肌肤亦将瘯。
一苞势欲陊，将撑乏寸木。
尽日欠束薪，经时无寸粟。
[螔]蝓将入甑，蟚蜞已临鍑。
娇儿未十岁，枵然自啼哭。
一钱买粔籹，数里走病仆。
破碎旧鹤笼，狼籍晚蚕蔟。
千卷素书外，此外无余蓄。
着处紵衣裂，戴次纱帽醭。
恶阴潜过午，未及烹葵菽。
吴中铜臭户，七万沸如臛。
啬止甘蟹䱬，侈唯僭车服。
皆希尉吏旨，尽怕里胥录。
低眉事庸奴，开颜纳金玉。
唯到陆先生，不能分一斛。
先生之志气，薄汉如鸿鹄。
遇善必擎跽，见才辄驰逐。
廉不受一芥，其余安可黩。
如何乡里辈，见之乃猬缩。
粤予苦心者，师仰但踖踧。
受易既可注，请玄又堪卜。
百家皆搜荡，六艺尽飜覆。
似馁见太牢，如迷遇华烛。
半年得酬唱，一日屡往复。
三秀间稂莠，九成杂巴濮。
奔命既不暇，乞降但相续。
吟诗口吻噅，把笔指节瘃。
君才既不穷，吾道由是笃。
所益谅弘多，厥交过亲族。
相逢似丹漆，相望如朓肭。
论业敢并驱，量分合继躅。
相违始两日，忡忡想华缛。
出门泥漫漶，恨无直辕辇。
十钱赁一轮，逢上鸣斛觫。
赤脚枕书帙，访予穿诘曲。
入门且抵掌，大噱时碌碌。
兹淋既浃旬，无乃害九谷。
予惟饿不死，得非道之福。
手中捉诗卷，语快还共读。
解带似归来，脱巾若沐浴。
疎如松间篁，野甚麋对鹿。
行谭弄书签，卧话枕棊局。
呼童具盘餐，擫衣换鸡鹜。
或蒸一升麻，或煠两把菊。
用以阅幽奇，岂能资口腹。
十分煎臯卢，半榼挽醽醁。
高谈繄无尽，昼漏何太促。
我公大司谏，一切从民欲。
梅润侵束杖，和气生空狱。
而民当斯时，不觉有烦溽。
念涝为之灾，拜神再三告。
太阴霍然收，天地一澄肃。
燔炙既芬芬，威仪乃毣毣。
须权元化柄，用拯中夏酷。
我愿荐先生，左右辅司牧。
兹雨何足云，唯思举颜歜。','',''),('quantangshi-33775','初夏即事寄鲁望','皮日休','quantangshi','','卷34','夏景恬且旷，远人疾初平。
黄鸟语方熟，紫桐阴正清。
廨宇有幽处，私游无定程。
归来闭双关，亦忘枯与荣。
土室作深谷，藓垣为干城。
𢼮杉突杝架，迸笋支檐楹。
片石共坐稳，病鹤同喜晴。
瘿木四五器，筇杖一两茎。
泉为葛天味，松作羲皇声。
或看名画彻，或吟闲诗成。
忽枕素琴睡，时把仙书行。
自然寡俦侣，莫说更纷争。
具区包地髓，震泽含天英。
粤从三让来，俊造纷然生。
顾予客兹地，薄我皆为伧。
唯有陆夫子，尽力提客卿。
各负出俗才，俱怀超世情。
驻我一栈车，啜君数藜羹。
敲门若我访，倒屣欣逢迎。
胡饼蒸甚熟，貊盘举尤轻。
茗脆不禁炙，酒肥或难倾。
扫除就藤下，移榻寻虚明。
唯共陆夫子，醉与天壤并。','',''),('quantangshi-33776','二游诗 徐诗','皮日休','quantangshi','','卷34','东莞为着姓，奕代皆隽喆。
强学取科第，名声尽孤揭。
自为方州来，清操称凛冽。
唯写坟籍多，必云清俸绝。
宣毫利若风，剡纸光于月。
札吏指欲胼，万通排未阕。
楼船若夏屋，欲载如垤㙞。
转徙入吴都，纵横碍门闑。
缥囊轻似雾，缃帙殷于血。
以此为基构，将斯用贻厥。
重于通侯印，贵却全师节。
我爱参卿道，承家能介洁。
潮田五万步，草屋十余楶。
微宦不能去，归来坐如刖。
保兹万卷书，守慎如羁绁。
念我曾苦心，相逢无间别。
引之看祕宝，任得穷披阅。
轴闲翠钿剥，签古红牙折。
帙解带芸香，卷开和桂屑。
枕兼石锋刃，榻共松疮疖。
一卧寂无喧，数编看尽彻。
或携归廨宇，或把穿林樾。
挈过太湖风，抱宿支硎雪。
如斯未星纪，悉得分毫末。
翦除幽僻薮，涤荡玄微窟。
学海正狂波，予头向中𭮷。
圣人患不学，垂诫尤为切。
苟昧古与今，何殊瘖共{目阕}。
昔之慕经史，有以佣笔札。
何况遇斯文，借之不曾辍。
吾衣任縠纑，吾食甘糠核。
其道苟可光，斯文那自伐。
何竹青堪杀，何蒲重好截。
如能盈兼两，便足酬饥渴。
有此竞苟荣，闻之兼可哕。
东臯耨烟雨，南岭提薇蕨。
何以谢徐君，公车不闻设。','',''),('quantangshi-33777','二游诗 任诗','皮日休','quantangshi','','卷34','任君恣高放，斯道能寡合。
一宅闲林泉，终身远嚣杂。
尝闻佐浩穰，散性多儑𠉤。
歘尔解其绶，遗之如弃靸。
归来乡党内，却与亲朋洽。
开溪未让丁，列第方称甲。
入门约百步，古木声霎霎。
广槛小山欹，斜廊怪石夹。
白莲倚阑楯，翠鸟缘帘押。
地势似五泻，岩形若三峡。
猿眠但腽肭，凫食时啑唼。
拨荇下文竿，结藤萦桂檝。
门留医树客，壁倚栽花锸。
度岁止褐衣，经旬唯白㡊。
多君方闭户，顾我能倒屧。
请题在茅栋，留坐于石榻。
魂从清景遛，衣任烟霞裛。
阶墀龟任上，枕席鸥方狎。
沼[似]颇黎[镜]，当中见鱼眨。
杯杓悉杉瘤，盘筵尽荷叶。
闲斟不置罚，闲弈无争劫。
闲日不整冠，闲风不用箑。
以斯为思虑，吾道宁疲薾。
衮衣竞璀璨，鼓吹争鞺鞳。
欲者解挤排，诟者能詀讘。
权豪暂飜覆，刑祸相填压。
此时一圭窦，不肯饶阊阖。
有第可栖息，有书可渔猎。
吾欲与任君，终身以斯惬。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33778','追和虎丘寺清远道士诗','皮日休','quantangshi','','卷34','成道自衰周，避世穷炎汉。
荆杞虽云梗，烟霞尚容窜。
兹岑信灵异，吾怀惬流玩。
石涩古铁鉎，岚重轻埃漫。
松膏腻幽径，苹沫着孤岸。
诸萝幄幕暗，众鸟陶匏乱。
岩罅地中心，海光天一半。
玄猨行列归，白云次第散。
蟾蜍生夕景，沆瀣余清旦。
风日采幽什，墨客学灵翰。
嗟予慕斯文，一咏复三叹。
显晦虽不同，兹吟粗堪赞。','',''),('quantangshi-33779','追和幽独君诗次韵 一','皮日休','quantangshi','','卷34','念尔风雅魄，幽咽犹能文。
空令伤魂鸟，啼破山边坟。','',''),('quantangshi-33780','追和幽独君诗次韵 二','皮日休','quantangshi','','卷34','恨剧但埋土，声幽难放哀。
坟古春自晚，愁绪空崔嵬。
白杨老无花，枯根侵夜台。
天高有时裂，川去何时回？
双睫不能濡，六藏无可摧。
不闻搴蓬事，何必深悲哉。','',''),('quantangshi-33781','奉和鲁望读阴符经见寄','皮日休','quantangshi','','卷34','三百八十言，出自伊[祁]氏。
上以生神仙，次云立仁义。
玄机一以发，五贼纷然起。
结为日月精，融作天地髓。
不测似阴阳，难名若鬼神。
得之升高天，失之沈厚地。
具茨云木老，大块烟霞委。
自颛顼以降，贼为圣人轨。
尧乃一庶人，得之贼帝挚。
挚见其德尊，脱身授其位。
舜唯一鳏民，冗冗作什器。
得之贼帝尧，白丁作天子。
禹本刑人后，以功继其嗣。
得之贼帝舜，用以平洚水。
自禹及文武，天机𢟉然弛。
姬公树其纲，贼之为圣智。
声诗川竞大，礼乐山争峙。
爰从幽厉余，宸极若孩穉。
九伯真犬彘，诸侯实虎兕。
五星合其耀，白日下阙里。
由是圣人生，于焉当乱纪。
黄帝之五贼，拾之若青紫。
高挥春秋笔，不可刊一字。
贼子虐甚斨，奸臣痛于棰。
至今千余年，蚩蚩受其赐。
时代更复改，刑政崩且陊。
予将贼其道，所动多訾毁。
叔孙与臧仓，贤圣多如此。
如何黄帝机，吾得多坎踬。
纵失生前禄，亦多身后利。
我欲贼其名，垂之千万祀。','',''),('quantangshi-33782','初夏游楞伽精舍','皮日休','quantangshi','','卷34','越舼轻似萍，漾漾出烟郭。
人声渐疎旷，天气忽寥廓。
伊予惬斯志，有似劀{疒}瘼。
遇胜即夷犹，逢幽且淹泊。
俄然棹深处，虚无倚岩崿。
霜毫一道人，引我登龙阁。
当中见寿象，欲礼光纷箔。
珠幡时相铿，恐是诸天乐。
树杪见觚棱，林端逢赭垩。
千寻井犹在，万祀灵不涸。
下通蛟人道，水色黮而恶。
欲照六藏惊，将窥百骸愕。
朅去山南岭，其险如邛笮。
悠然放吾兴，欲把青天摸。
紫藤垂罽珥，红荔悬缨络。
藓厚滑似漦，峰尖利如锷。
斯须到绝顶，似愈渐离㸌。
一片太湖光，只惊天汉落。
梅风脱纶帽，乳水透芒屩。
岚姿与波彩，不动浑相着。
既不暇供应，将何以酬酢。
却来穿竹径，似入青油幕。
穴恐水君开，龛如鬼工凿。
穷幽入兹院，前楯临巨壑。
遗画龙奴狞，残香虫篆薄。
褫魂窥玉镜，澄虑闻金铎。
云态共萦留，鸟言相许诺。
古木势如虺，近之恐相蠚。
怒泉声似激，闻之意争博。
时禽倏已嘿，众籁萧然作。
遂令不羁性，恋此如缠缚。
念彼上人者，将生付寂寞。
曾无肤挠事，肯把心源度。
胡为儒家流，没齿勤且恪。
沐猴本不冠，未是谋生错。
言行既异调，栖迟亦同托。
愿力傥不遗，请作华林鹤。','',''),('quantangshi-33783','公斋四咏 小松','皮日休','quantangshi','','卷34','婆娑只三尺，移来白云径。
亭亭向空意，已解凌辽敻。
叶健似虬须，枝脆如鹤胫。
清音犹未成，绀彩空不定。
阴圆小芝盖，鳞涩修荷柄。
先愁被鷃抢，预恐遭蜗病。
结根幸得地，且免离离映。
磥砢不难遇，在保晚成性。
一日造明堂，为君当毕命。','',''),('quantangshi-33784','公斋四咏 小桂','皮日休','quantangshi','','卷34','一子落天上，生此青璧枝。
歘从山之幽，斸断云根移。
劲挺隐圭质，盘珊缇油姿。
叶彩碧髓融，花状白毫蕤。
棱层立翠节，偃蹇樛青螭。
影澹雪霁后，香泛风和时。
吾祖在月竁，孤贞能见怡。
愿老君子地，不敢辞喧卑。','',''),('quantangshi-33785','公斋四咏 新竹','皮日休','quantangshi','','卷34','笠泽多异竹，移之植后楹。
一架三百本，绿沈森冥冥。
圆紧珊瑚节，钐利翡翠翎。
俨若青帝仗，矗如紫姑屏。
槭槭微风度，漠漠轻霭生。
如神语钧天，似乐奏洞庭。
一玩九藏冷，再闻百骸醒。
有根可以执，有𥳇可以馨。
愿禀君子操，不敢先凋零。','',''),('quantangshi-33786','公斋四咏 鹤屏','皮日休','quantangshi','','卷34','三幅吹空縠，孰写仙禽状。
䯔耳侧以听，赤精旷如望。
引吭看云势，翘足临池样。
颇似近蓐席，还如入方丈。
尽日空不鸣，穷年但相向。
未许子晋乘，难教道林放。
貌既合羽仪，骨亦符法相。
愿升君子堂，不必思昆阆。','',''),('quantangshi-33787','奉酬崔璐进士见寄次韵','皮日休','quantangshi','','卷34','伊余幼且贱，所禀自以殊。
弱岁谬知道，有心匡皇符。
意超海上鹰，运局辕下驹。
纵性作古文，所谓皆自如。
但恐才格劣，敢夸词彩敷。
句句考事实，篇篇穷玄虚。
谁能变羊质，竞不获骊珠。
粤有造化手，曾开天地炉。
文章邺下秀，气貌淹中儒。
展我此志业，期君持中枢。
苍生眼穿望，勿作磻溪谟。','',''),('quantangshi-33788','太湖诗 初入太湖','皮日休','quantangshi','','卷34','闻有太湖名，十年未曾识。
今朝得游泛，大笑称平昔。
一舍行胥塘，尽日到震泽。
三万六千顷，千顷颇黎色。
连空澹无纇，照野平绝隟。
好放青翰舟，堪弄白玉笛。
疎岑七十二，𡾼𡾼露矛戟。
悠然啸傲去，天上摇画艗。
西风乍猎猎，惊波罨涵碧。
倏忽雷阵吼，须臾玉崖坼。
树动为蜃尾，山浮似鳌脊。
落照射鸿溶，清辉荡抛𢶉。
云轻似可染，霞烂如堪摘。
渐暝无处泊，挽帆从所适。
枕下闻澎湃，肌上生瘮𤶬。
讨异足邅回，寻幽多阻隔。
愿风与良便，吹入神仙宅。
甘将一蕴书，永事嵩山伯。','',''),('quantangshi-33789','太湖诗 晓次神景宫','皮日休','quantangshi','','卷34','夜半幽梦中，扁舟似凫跃。
晓来到何许，俄倚包山脚。
三百六十丈，攒空利如削。
遐瞻但徙倚，欲上先矍铄。
浓露湿莎裳，浅泉渐草屩。
行行未一里，节境转寂寞。
静径侵泬寥，仙扉傍岩崿。
松声正清绝，海日方照灼。
歘临幽虚天，万想皆摆落。
坛灵有芝菌，殿圣无鸟雀。
琼帏自回旋，锦旌空粲错。
鼎气为龙虎，香烟混丹雘。
凝看出次云，默听语时鹤。
绿书不可注，云笈应无钥。
晴来鸟思喜，崦里花光弱。
天籁如击琴，泉声似摐铎。
清斋洞前院，敢负玄科约。
空中悉羽章，地上皆灵药。
金醴可酣畅，玉豉堪咀嚼。
存心服燕胎，叩齿读龙蹻。
福地七十二，兹焉永堪托。
在兽乏虎貙，于虫不毒蠚。
尝闻择骨录，仙志非可作。
绿肠既朱髓，青肝复紫络。
伊余乏此相，天与形貌恶。
每嗟原宪瘇，常苦齐侯疟。
终然合委顿，刚亦慕寥廓。
三茅亦常住，竟与圭组薄。
欲问包山神，来赊少岩壑。','',''),('quantangshi-33790','太湖诗 入林屋洞','皮日休','quantangshi','','卷34','斋心已三日，筋骨如烟轻。
腰下佩金兽，手中持火铃。
幽塘四百里，中有日月精。
连亘三十六，各各为玉京。
自非心至诚，必被神物烹。
顾余慕大道，不能惜微生。
遂招放旷侣，同作幽忧行。
其门才函丈，初若盘薄硎。
洞气黑昳𥄴，苔发红鬇鬡。
试足值坎窞，低头避峥嵘。
攀缘不知倦，怪异焉敢惊。
匍匐一百步，稍稍策可横。
忽然白蝙蝠，来扑松炬明。
人语散澒洞，石响高玲玎。
脚底龙蛇气，头上波涛声。
有时若服匿，逼仄如见绷。
俄尔造平澹，豁然逢光晶。
金堂似镌出，玉座如琢成。
前有方丈沼，凝碧融人[睛]。
云浆湛不动，璚露涵而馨。
漱之恐减算，酌之必延龄。
愁为三官责，不敢携一{賏/缶|瓦}。
昔云夏后氏，于此藏真经。
刻之以紫琳，祕之以丹琼。
期之以万祀，守之以百灵。
焉得彼丈人，窃之不加刑。
石匮一以出，左神俄不扃。
禹书既云得，吴国由是倾。
藓缝才半尺，中有怪物腥。
欲去既嚄唶，将回又伶俜。
却遵旧时道，半日出杳冥。
屦泥惹石髓，衣湿霑云英。
玄箓乏仙骨，青文无绛名。
虽然入阴宫，不得朝上清。
对彼神仙窟，自厌浊俗形。
却憎造物者，遣我骑文星。','',''),('quantangshi-33791','太湖诗 雨中游包山精舍','皮日休','quantangshi','','卷34','松门亘五里，彩碧高下绚。
幽人共跻攀，胜事颇清便。
翣翣林上雨，隐隐湖中电。
薜带轻束腰，荷笠低遮面。
湿屦黏烟雾，穿衣落霜霰。
笑次度岩壑，困中遇台殿。
老僧三四人，梵字十数卷。
施稀无夏屋，境僻乏朝膳。
散髪抵泉流，支颐数云片。
坐石忽忘起，扪萝不知倦。
异蝶时似锦，幽禽或如钿。
篥簩还戛刃，栟榈自摇扇。
俗态既斗薮，野情空眷恋。
道人摘芝菌，为予备午馔。
渴兴石榴羹，饥惬胡麻饭。
如何事于役，兹游急于传。
却将尘土衣，一任瀑丝溅。','',''),('quantangshi-33792','太湖诗 游毛公坛','皮日休','quantangshi','','卷34','却上南山路，松行俨如庑。
松根碍幽径，孱颜不能斧。
摆履跨乱云，倾巾蹲怪树。
三休且半日，始到毛公坞。
两水合一涧，潨崖却为浦。
相敌百千戟，共攂十万鼓。
喷散日月精，射破神仙府。
唯愁绝地脉，又恐折天柱。
一窥耳目眩，耳听云髪竖。
次到炼丹井，井干翳宿莽。
下有蘂刚丹，勺之百疾愈。
凝于白獭髓，湛似桐马乳。
黄露醒齿牙，碧黏甘胏腑。
桧异松复怪，枯疎互撑拄。
干蛟一百丈，髐然半天舞。
下有毛公坛，坛方不盈亩。
当时云龙篆，一片苔藓古。
时时仙禽来，忽忽祥烟聚。
我爱周息元，忽起应明主。
三谏却归来，回头唾圭组。
伊余何不幸，斯人不复覩。
如何大开口，与世争枯腐。
将山待夸娥，以肉投䝟貐。
歘坐侵桂阴，不知已与午。
兹地足灵境，他年终结宇。
敢道万石君，轻于一丝缕。','',''),('quantangshi-33793','太湖诗 三宿神景宫','皮日休','quantangshi','','卷34','古观岑且寂，幽人情自怡。
一来包天下，三宿湖之湄。
况此深夏夕，不逢清月姿。
玉泉浣衣后，金殿添香时。
客省高且敞，客牀蟠复奇。
石枕冷入脑，笋席寒侵肌。
气清寐不着，起坐临阶墀。
松阴忽微照，独见萤火芝。
素鹤警微露，白莲明暗池。
窗棂带乳藓，壁缝含云蕤。
闻磬走魍魉，见烛奔羁雌。
沆瀣欲滴沥，芭蕉未离披。
五更山蝉响，醒发如吹篪。
杉风忽然起，飘破步虚词。
道客巾屦样，上清朝礼仪。
明发作此事，岂复甘趋驰。','',''),('quantangshi-33794','太湖诗 以毛公泉一瓶献上谏议因寄','皮日休','quantangshi','','卷34','刘根昔成道，兹坞四百年。
毵毵被其体，号为绿毛仙。
因思清[泠]汲，凿彼岝𡿃巅。
五色既炼矣，一勺方铿然。
既用文武火，俄穷雌雄篇。
赤盐扑红雾，白华飞素烟。
服之生羽翼，倏尔冲玄天。
真隐尚有迹，厥祀将近千。
我来讨灵胜，到此期终焉。
滴苦破窦净，藓深余甃圆。
澄如玉髓洁，泛如金精鲜。
颜色半带乳，气味全和铅。
饮之融痞蹇，濯之伸拘挛。
有时玩者触，倏忽风雷颠。
素绠丝不短，越罂腹甚便。
汲时月液动，担处玉浆旋。
敢献大司谏，置之铃阁前。
清如介洁性，涤比埽荡权。
炙背野人兴，亦思侯伯怜。
也知饮冰苦，愿受一瓶泉。','',''),('quantangshi-33795','太湖诗 缥缈峰','皮日休','quantangshi','','卷34','头戴华阳帽，手拄大夏筇。
清晨陪道侣，来上缥缈峰。
带露齅药蔓，和云寻鹿踪。
时惊𪕍𪕌鼠，飞上千丈松。
翠壁内有室，叩之虚䃔䃧。
古穴下彻海，视之寒鸿蒙。
遇歇有佳思，缘危无倦容。
须臾到绝顶，似鸟穿樊笼。
恐足蹈海日，疑身凌天风。
众岫点巨浸，四方接圆穹。
似将青螺髻，撒在明月中。
片白作越分，孤岚为吴宫。
一阵叆叇气，隐隐生湖东。
激雷与波起，狂电将日红。
礊礊雨点大，金髇轰下空。
暴光隔云闪，仿髴亘天龙。
连拳百丈尾，下拔湖之洪。
捽为一雪山，欲与昭回通。
移时却𢷈下，细碎衡与嵩。
神物谅不测，绝境尤难穷。
杖策下返照，渐闻仙观钟。
烟波濆肌骨，云壑阗心胸。
竟死爱未足，当生且欢逢。
不然把天爵，自拜太湖公。','',''),('quantangshi-33796','太湖诗 桃花坞','皮日休','quantangshi','','卷34','夤缘度南岭，尽日穿林樾。
穷深到兹坞，逸兴转超忽。
坞名虽然在，不见桃花发。
恐是武陵溪，自闭仙日月。
倚峰小精舍，当岭残耕垡。
将洞任回环，把云恣披拂。
闲禽啼叫窱，险狖眠硉矹。
微风吹重岚，碧埃轻勃勃。
清阴减鹤睡，秀色治人渴。
敲竹鬬铮摐，弄泉争咽嗢。
空斋蒸柏叶，野饭调石髪。
空羡坞中人，终身无履韤。','',''),('quantangshi-33797','太湖诗 明月湾','皮日休','quantangshi','','卷34','晓景澹无际，孤舟恣回环。
试问最幽处，号为明月湾。
半岩翡翠巢，望见不可攀。
柳弱下丝网，藤深垂花鬘。
松瘿忽似狖，石文或如虥。
钓坛两三处，苔老腥斒斑。
沙雨几处霁，水禽相向闲。
野人波涛上，白屋幽深间。
晓培橘栽去，暮作鱼梁还。
清泉出石砌，好树临柴关。
对此老且死，不知忧与患。
好境无处住，好处无境删。
赧然不自适，脉脉当湖山。','',''),('quantangshi-33798','太湖诗 练渎','皮日休','quantangshi','','卷34','吴王厌得国，所玩终不足。
一上姑苏台，犹自嫌局促。
艅艎六宫闹，艨冲后军肃。
一阵水麝风，空中荡平渌。
鸟困避锦帆，龙跧防铁轴。
流苏惹烟浪，羽葆飘岩谷。
灵境太蹂践，因兹塞林屋。
空阔嫌太湖，崎岖开练渎。
三寻齾石齿，数里穿山腹。
底静似金膏，砾碎如丹粟。
波殿郑妲醉，蟾阁西施宿。
几转含烟舟，一唱来云曲。
不知阑楯上，夜有越人镞。
君王掩面死，嫔御不敢哭。
艳魄逐波涛，荒宫养麋鹿。
国破沟亦浅，代变草空绿。
白鸟都不知，朝眠还暮浴。','',''),('quantangshi-33799','太湖诗 投龙潭','皮日休','quantangshi','','卷34','龟山下最深，恶气何洋溢。
涎水瀑龙巢，腥风卷蛟室。
晓来林岑静，狞色如怒日。
气涌扑炱煤，波澄埽纯漆。
下有水君府，贝阙光比栉。
左右列介臣，纵横守鳞卒。
月中珠母见，烟际枫人出。
生犀不敢烧，水怪恐摧捽。
时有慕道者，作彼投龙术。
端岩持碧简，斋戒挥紫笔。
兼以金蜿蜒，投之光焌律。
琴高坐赤鲤，何许纵仙逸。
我愿与之游，兹焉托灵质。','',''),('quantangshi-33800','太湖诗 孤园寺','皮日休','quantangshi','','卷34','艇子小且兀，缘湖荡白芷。
萦纡泊一崎，宛到孤园寺。
萝岛凝清阴，松门湛虚翠。
寒泉飞碧螭，古木鬬苍兕。
钟梵在水魄，楼台入云肆。
岩边足鸣𧔢，树杪多飞鸓。
香莎满院落，风泛金靃靡。
静鹤啄柏蠹，闲猱弄榅䗁。
小殿熏陆香，古经贝多纸。
老僧方瞑坐，见客还强起。
指兹正险绝，何以来到此。
先言洞壑数，次话真如理。
磬韵醒闲心，茶香凝皓齿。
巾之劫贝布，馔以栴檀饵。
数刻得清净，终身欲依止。
可怜陶侍读，身列丹台位。
雅号曰胜力，亦闻师佛氏。
今日到孤园，何妨称弟子。','',''),('quantangshi-33801','太湖诗 上真观','皮日休','quantangshi','','卷34','径盘在山肋，缭绕穷云端。
摘菌杖头紫，缘崖屐齿刓。
半日到上真，洞宫知造难。
双户启真景，斋心方可观。
天钧鸣响亮，天禄行蹒跚。
琪树夹一径，万条青琅玕。
两松峙庭际，怪状吁可叹。
大螾腾共结，修蛇飞相盘。
皮肤坼甲胄，枝节擒貙犴。
罅处似天裂，朽中如井眢。
襹褷风声㾌，跁跒地力痑。
根上露钳釱，空中狂波澜。
合时若莽苍，辟处如轘辕。
俨对无霸阵，静问严陵滩。
灵飞一以护，山都焉敢干。
两廊洁寂历，中殿高巑岏。
静架九色节，闲悬十绝幡。
微风时一吹，百宝清阑珊。
昔有叶道士，位当升灵官。
欲笺紫微志，唯食虹影丹。
既逐隐龙去，道风由此残。
犹闻绛目草，往往生空坛。
羽客两三人，石上谭泥丸。
谓我或龙胄，粲然与之欢。
衣巾紫华冷，食次白芝寒。
自觉有真气，恐随风力抟。
明朝若更往，必拟隳儒冠。','',''),('quantangshi-33802','太湖诗 销夏湾','皮日休','quantangshi','','卷34','太湖有曲处，其门为两崖。
当中数十顷，别如一天池。
号为销夏湾，此名无所私。
赤日莫斜照，清风多遥吹。
沙屿埽粉墨，松竹调埙篪。
山果红靺鞨，水苔青髬髵。
木阴厚若瓦，严磴滑如饴。
我来此游息，夏景方赫曦。
一坐盘石上，肃肃寒生肌。
小艖或可泛，短策或可支。
行惊翠羽起，坐见白莲披。
敛袖弄轻浪，解巾敌凉飔。
但有水云见，更余沙禽知。
京洛往来客，暍死缘奔驰。
此中便可老，焉用名利为。','',''),('quantangshi-33803','太湖诗 包山祠','皮日休','quantangshi','','卷34','白云最深处，像设盈岩堂。
村祭足茗粣，水奠多桃桨。
䇹䉦突古砌，薜荔绷颓墙。
炉灰寂不然，风送杉桂香。
积雨晦州里，流波漂稻粱。
恭惟大司谏，悯此如发狂。
命予传明祷，祗事实不遑。
一奠若肸蠁，再祝如激扬。
出庙未半日，隔云逢澹光。
𡾼𡾼雨点少，渐收羽林枪。
忽然山家犬，起吠白日傍。
公心与神志，相向如玄黄。
我愿作一疏，奏之于穹苍。
留神千万祀，永福吴封疆。','',''),('quantangshi-33804','太湖诗 圣姑庙','皮日休','quantangshi','','卷34','洛神有灵逸，古庙临空渚。
暴雨驳丹青，荒萝绕梁梠。
野风旋芝盖，饥乌衔椒糈。
寂寂落枫花，时时鬬鼯鼠。
常云三五夕，尽会妍神侣。
月下留紫姑，霜中召青女。
俄然响环佩，倏尔鸣机杼。
乐至有闻时，香来无定处。
目瞪如有待，魂断空无语。','',''),('quantangshi-33805','太湖诗 太湖石','皮日休','quantangshi','','卷34','兹山有石岸，抵浪如受屠。
雪阵千万战，藓岩高下刳。
乃是天诡怪，信非人功夫。
白丁一云取，难甚网珊瑚。
厥状复若何，鬼工不可图。
或拳若虺蜴，或蹲如虎貙。
连络若钩鏁，重叠如萼跗。
或若巨人骼，或如太帝符。
胮肛篔簹笋，格磔琅玕株。
断处露海眼，移来和沙须。
求之烦耄倪，载之劳舳舻。
通侯一以眄，贵却骊龙珠。
厚赐以賝賮，远去穷京都。
五侯土山下，要尔添岩龉。
赏玩若称意，爵禄行斯须。
苟有王佐士，崛起于太湖。
试问欲西笑，得如兹石无。','',''),('quantangshi-33806','太湖诗 崦里','皮日休','quantangshi','','卷34','崦里何幽奇，膏腴二十顷。
风吹稻花香，直过龟山顶。
青苗细腻卧，白羽悠溶静。
塍畔起䴙鹈，田中通舴艋。
几家傍潭洞，孤戍当林岭。
罢钓时煑菱，停缲或焙茗。
峭然八十翁，生计于此永。
苦力供征赋，怡颜过朝暝。
洞庭取异事，包山极幽景。
念尔饱得知，亦是遗民幸。','',''),('quantangshi-33807','太湖诗 石板','皮日休','quantangshi','','卷34','翠石数百步，如板漂不流。
空疑水妃意，浮出青玉洲。
中若莹龙劒，外唯叠蛇矛。
狂波忽然死，浩气清且浮。
似将翠黛色，抹破太湖秋。
安得三五夕，携酒棹扁舟。
召取月夫人，啸歌于上头。
又恐霄景阔，虚皇拜仙侯。
欲建九锡碑，当立十二楼。
琼文忽然下，石板谁能留。
此事少知者，唯应波上鸥。','',''),('quantangshi-33808','奉和鲁望渔具十五咏 网','皮日休','quantangshi','','卷34','晚挂溪上网，暎空如雾縠。
闲来发其机，旋旋沈平绿。
下处若烟雨，牵时似崖谷。
必若遇鲲鲕，从教通一目。','',''),('quantangshi-33809','奉和鲁望渔具十五咏 罩','皮日休','quantangshi','','卷34','芒鞋下葑中，步步沈轻罩。
既为菱浪颭，亦为莲泥胶。
人立独无声，鱼烦似相抄。
满手搦霜鳞，思归举轻棹。','',''),('quantangshi-33810','奉和鲁望渔具十五咏 𦊔','皮日休','quantangshi','','卷34','烟雨晚来好，东塘下𦊔去。
网小正星𣞷，舟轻欲腾翥。
谁知荇深后，恰值鱼多处。
浦口更有人，停桡一延竚。','',''),('quantangshi-33811','奉和鲁望渔具十五咏 钓筒','皮日休','quantangshi','','卷34','笼籦截数尺，标置能幽绝。
从浮笠泽烟，任卧桐江月。
丝随碧波漫，饵逐清滩发。
好是趁筒时，秋声正清越。','',''),('quantangshi-33812','奉和鲁望渔具十五咏 钓车','皮日休','quantangshi','','卷34','得乐湖海志，不厌华輈小。
月中抛一声，惊起滩上鸟。
心将潭底测，手把波文褭。
何处觅奔车，平波今渺渺。','',''),('quantangshi-33813','奉和鲁望渔具十五咏 渔梁','皮日休','quantangshi','','卷34','波际插翠筠，离离似清籞。
游鳞到溪口，入此无逃所。
斜临杨柳津，静下鸬鷀侣。
编此欲何之，终焉富春渚。','',''),('quantangshi-33814','奉和鲁望渔具十五咏 叉鱼','皮日休','quantangshi','','卷34','列炬春溪口，平潭如不流。
照见游泳鱼，一一如清昼。
中目碎琼碧，毁鳞殷组绣。
乐此何太荒，居然愧川后。','',''),('quantangshi-33815','奉和鲁望渔具十五咏 射鱼','皮日休','quantangshi','','卷34','注矢寂不动，澄潭晴转烘。
下窥见鱼乐，怳若翔在空。
惊羽决凝碧，伤鳞浮殷红。
堪将指杯术，授与太湖公。','',''),('quantangshi-33816','奉和鲁望渔具十五咏 鸣桹','皮日休','quantangshi','','卷34','尽日平湖上，鸣桹仍动桨。
丁丁入波心，澄澈和清响。
鹭听独寂寞，鱼惊昧来往。
尽水无所逃，川中有钩党。','',''),('quantangshi-33817','奉和鲁望渔具十五咏 沪','皮日休','quantangshi','','卷34','波中植甚固，磔磔如鰕须。
涛头倏尔过，数顷跳鯆䱐。
不是细罗密，自为朝夕驱。
空怜指鱼命，遣出海边租。','',''),('quantangshi-33818','奉和鲁望渔具十五咏 {𥫗/䅟}','皮日休','quantangshi','','卷34','伐彼槎蘖枝，放于冰雪浦。
游鱼趁暖处，忽尔来相聚。
徒为栖托心，不问庇庥主。
一旦悬鼎镬，祸机真自取。','',''),('quantangshi-33819','奉和鲁望渔具十五咏 种鱼','皮日休','quantangshi','','卷34','移土湖岸边，一半和鱼子。
池中得春雨，点点活如蚁。
一月便翠鳞，终年必頳尾。
借问两绶人，谁知种鱼利。','',''),('quantangshi-33820','奉和鲁望渔具十五咏 药鱼','皮日休','quantangshi','','卷34','吾无竭泽心，何用药鱼药。
见说放溪上，点点波光恶。
食时竞夷犹，死者争纷泊。
何必重伤鱼，毒泾犹可作。','',''),('quantangshi-33821','奉和鲁望渔具十五咏 舴艋','皮日休','quantangshi','','卷34','阔处只三尺，翛然足吾事。
低篷挂钓车，枯蚌盛鱼饵。
只好携桡坐，唯堪盖蓑睡。
若遣遂平生，艅艎不如是。','',''),('quantangshi-33822','奉和鲁望渔具十五咏 笭箵','皮日休','quantangshi','','卷34','朝空笭箵去，暮实笭箵归。
归来倒却鱼，挂在幽窗扉。
但闻鰕蚬气，欲生苹藻衣。
十年佩此处，烟雨苦霏霏。','',''),('quantangshi-33823','添鱼具诗 鱼庵','皮日休','quantangshi','','卷34','庵中只方丈，恰称幽人住。
枕上悉渔经，门前空钓具。
束竿时倚壁，晒网还侵户。
上浻有杨颙，须留往来路。','',''),('quantangshi-33824','添鱼具诗 钓矶','皮日休','quantangshi','','卷34','盘滩一片石，置我山居足。
洼处着筣笓，窍中维[𦨧]䑿。
多逢沙鸟污，爱彼潭云触。
狂奴卧此多，所以蹋帝腹。','',''),('quantangshi-33825','添鱼具诗 蓑衣','皮日休','quantangshi','','卷34','一领蓑正新，着来沙坞中。
隔溪遥望见，疑是绿毛翁。
襟色裛䐑霭，袖香䙰褷风。
前头不施衮，何以为三公。','',''),('quantangshi-33826','添鱼具诗 箬笠','皮日休','quantangshi','','卷34','圆似写月魂，轻如织烟翠。
涔涔向上雨，不乱窥鱼思。
携来沙日微，挂处江风起。
纵带二梁冠，终身不忘尔。','',''),('quantangshi-33827','添鱼具诗 背篷','皮日休','quantangshi','','卷34','侬家背篷样，似个大龟甲。
雨中局蹐时，一向听霎霎。
甘从鱼不见，亦任鸥相狎。
深拥竟无言，空成睡齁䶎。','',''),('quantangshi-33828','奉和鲁望樵人十咏 樵溪','皮日休','quantangshi','','卷34','何时有此溪，应便生幽木。
橡实养山禽，藤花蒙涧鹿。
不止产蒸薪，愿当歌棫朴。
君知天意无，以此安吾族。','',''),('quantangshi-33829','奉和鲁望樵人十咏 樵家','皮日休','quantangshi','','卷34','空山最深处，太古两三家。
云萝共夙世，猨鸟同生涯。
衣服濯春泉，盘餐烹野花。
居兹老复老，不解叹年华。','',''),('quantangshi-33830','奉和鲁望樵人十咏 樵叟','皮日休','quantangshi','','卷34','不曾照青镜，岂解伤华髪。
至老未息肩，至今无病骨。
家风是林岭，世禄为薇蕨。
所以两大夫，天年自为伐。','',''),('quantangshi-33831','奉和鲁望樵人十咏 樵子','皮日休','quantangshi','','卷34','相约晚樵去，跳踉上山路。
将花饵鹿麛，以果投猨父。
束薪白云湿，负担春日暮。
何不寿童乌，果为玄所误。','',''),('quantangshi-33832','奉和鲁望樵人十咏 樵径','皮日休','quantangshi','','卷34','蒙茏中一径，绕在千峰里。
歇处遇松根，危中值石齿。
花穿枲衣落，云拂芒鞋起。
自古行此途，不闻颠与坠。','',''),('quantangshi-33833','奉和鲁望樵人十咏 樵斧','皮日休','quantangshi','','卷34','腰间插大柯，直入深溪里。
空林伐一声，幽鸟相呼起。
倒树去李父，倾巢啼木魅。
不知仗钺者，除害谁如此。','',''),('quantangshi-33834','奉和鲁望樵人十咏 樵担','皮日休','quantangshi','','卷34','不敢量樵重，唯知益薪束。
轧轧下山时，弯弯向身曲。
清泉洗得洁，翠霭侵来绿。
看取荷戈人，谁能似吾属。','',''),('quantangshi-33835','奉和鲁望樵人十咏 樵风','皮日休','quantangshi','','卷34','野船渡樵客，来往平波中。
纵横清飙吹，旦暮归期同。
苹光惹衣白，莲影涵薪红。
吾当请封尔，直作镜湖公。','',''),('quantangshi-33836','奉和鲁望樵人十咏 樵火','皮日休','quantangshi','','卷34','山客地炉里，然薪如阳辉。
松膏作𣺫瀡，杉子为珠玑。
响误击刺闹，焰疑彗孛飞。
傍边暖白酒，不觉瀑冰垂。','',''),('quantangshi-33837','奉和鲁望樵人十咏 樵歌','皮日休','quantangshi','','卷34','此曲太古音，由来无管奏。
多云采樵乐，或说林泉候。
一唱凝闲云，再谣悲顾兽。
若遇采诗人，诬辞收鄙陋。','',''),('quantangshi-33838','酒中十咏 酒星','皮日休','quantangshi','','卷34','谁遣酒旗耀，天文列其位。
彩微尝似酣，芒弱偏如醉。
唯忧犯帝座，只恐骑天驷。
若遇卷舌星，谗君应堕地。','',''),('quantangshi-33839','酒中十咏 酒泉','皮日休','quantangshi','','卷34','羲皇有玄酒，滋味何太薄。
玉液是浇漓，金沙乃糟粕。
春从野鸟沽，昼仍闲猨酌。
我愿葬兹泉，醉魂似凫跃。','',''),('quantangshi-33840','酒中十咏 酒篘','皮日休','quantangshi','','卷34','翠{𥫗/筏}初织来，或如古鱼器。
新从山下买，静向甔中试。
轻可网金醅，疎能容玉蚁。
自此好成功，无贻我罍耻。','',''),('quantangshi-33841','酒中十咏 酒牀','皮日休','quantangshi','','卷34','糟牀带松节，酒腻肥如羜。
滴滴连有声，空疑杜康语。
开眉既压后，染指偷尝处。
自此得公田，不过浑种黍。','',''),('quantangshi-33842','酒中十咏 酒垆','皮日休','quantangshi','','卷34','红垆高几尺，颇称幽人意。
火作缥醪香，灰为冬醷气。
有枪尽龙头，有主皆犊鼻。
倘得作杜根，佣保何足愧。','',''),('quantangshi-33843','酒中十咏 酒楼','皮日休','quantangshi','','卷34','钩楯跨通衢，喧闹当九市。
金罍潋滟后，玉斝纷纶起。
舞蝶傍应酣，啼莺闻亦醉。
野客莫登临，相雠多失意。','',''),('quantangshi-33844','酒中十咏 酒旗','皮日休','quantangshi','','卷34','青帜阔数尺，悬于往来道。
多为风所扬，时见酒名号。
拂拂野桥幽，翻翻江市好。
双眸复何事，终竟望君老。','',''),('quantangshi-33845','酒中十咏 酒樽','皮日休','quantangshi','','卷34','牺樽一何古，我抱期幽客。
少恐消醍醐，满拟烘琥珀。
猨窥曾扑泻，鸟蹋经攲仄。
度度醒来看，皆如死生隔。','',''),('quantangshi-33846','酒中十咏 酒城','皮日休','quantangshi','','卷34','万仞峻为城，沈酣浸其俗。
香侵井干过，味染濠波渌。
朝倾逾百榼，暮压几千斛。
吾将隶此中，但为阍者足。','',''),('quantangshi-33847','酒中十咏 酒乡','皮日休','quantangshi','','卷34','何人置此乡，杳在天皇外。
有事忘哀乐，有时忘显晦。
如寻罔象归，似与希夷会。
从此共君游，无烦用冠带。','',''),('quantangshi-33848','奉和添酒中六咏 酒池','皮日休','quantangshi','','卷34','八齐竞奔注，不知深几丈。
竹叶岛纡徐，凫花波荡漾。
醺应烂地轴，浸可柔天壤。
以此献吾君，愿铭于[几]杖。','',''),('quantangshi-33849','奉和添酒中六咏 酒龙','皮日休','quantangshi','','卷34','铜为蚴蟉鳞，铸作鱙𬵩角。
吐处百里雷，泻时千丈壑。
初疑潜苑囿，忽似拏寥廓。
遂使铜雀台，香消野花落。','',''),('quantangshi-33850','奉和添酒中六咏 酒瓮','皮日休','quantangshi','','卷34','坚净不苦窳，陶于醉封疆。
临溪刷旧痕，隔屋闻新香。
移来近麴室，倒处临糟牀。
所嗟无比邻，余亦能偷尝。','',''),('quantangshi-33851','奉和添酒中六咏 酒船','皮日休','quantangshi','','卷34','剡桂复刳兰，陶陶任行乐。
但知涵泳好，不计风涛恶。
尝行麴封内，稍系糟丘泊。
东海如可倾，乘之就斟酌。','',''),('quantangshi-33852','奉和添酒中六咏 酒枪','皮日休','quantangshi','','卷34','象鼎格仍高，其中不烹餁。
唯将煮浊醪，用以资酣饮。
偏宜旋樵火，稍近余酲枕。
若得伴琴书，吾将着闲品。','',''),('quantangshi-33853','奉和添酒中六咏 酒杯','皮日休','quantangshi','','卷34','昔有嵇氏子，龙章而凤姿。
手挥五弦罢，聊复一樽持。
但取性澹泊，不知味醇醨。
兹器不复见，家家唯玉巵。','',''),('quantangshi-33854','茶中杂咏 茶坞','皮日休','quantangshi','','卷34','闲寻尧氏山，遂入深深坞。
种荈已成园，栽葭宁记亩。
石洼泉似掬，岩罅云如缕。
好是夏初时，白花满烟雨。','',''),('quantangshi-33855','茶中杂咏 茶人','皮日休','quantangshi','','卷34','生于顾渚山，老在漫石坞。
语气为茶荈，衣香是烟雾。
庭从𣟤子遮，果任獳师虏。
日晚相笑归，腰间佩轻蒌。','',''),('quantangshi-33856','茶中杂咏 茶笋','皮日休','quantangshi','','卷34','袖然三五寸，生必依岩洞。
寒恐结红铅，暖疑销紫汞。
圆如玉轴光，脆似琼英冻。
每为遇之疎，南山挂幽梦。','',''),('quantangshi-33857','茶中杂咏 茶籯','皮日休','quantangshi','','卷34','筤篣晓携去，蓦个山桑坞。
开时送紫茗，负处沾清露。
歇把傍云泉，归将挂烟树。
满此是生涯，黄金何足数。','',''),('quantangshi-33858','茶中杂咏 茶舍','皮日休','quantangshi','','卷34','阳崖枕白屋，几口嬉嬉活。
棚上汲红泉，焙前蒸紫蕨。
乃翁研茗后，中妇拍茶歇。
相向掩柴扉，清香满山月。','',''),('quantangshi-33859','茶中杂咏 茶竈','皮日休','quantangshi','','卷34','南山茶事动，竈起岩根傍。
水煮石髪气，薪然杉脂香。
青琼蒸后凝，绿髓炊来光。
如何重辛苦，一一输膏粱。','',''),('quantangshi-33860','茶中杂咏 茶焙','皮日休','quantangshi','','卷34','凿彼碧岩下，恰应深二尺。
泥易带云根，烧难碍石脉。
初能燥金饼，渐见干琼液。
九里共杉林，相望在山侧。','',''),('quantangshi-33861','茶中杂咏 茶鼎','皮日休','quantangshi','','卷34','龙舒有良匠，铸此佳样成。
立作菌蠢势，煎为潺湲声。
草堂暮云阴，松窗残雪明。
此时勺复茗，野语知逾清。','',''),('quantangshi-33862','茶中杂咏 茶瓯','皮日休','quantangshi','','卷34','邢客与越人，皆能造兹器。
圆似月魂堕，轻如云魄起。
枣花势旋眼，苹沫香沾齿。
松下时一看，支公亦如此。','',''),('quantangshi-33863','茶中杂咏 煑茶','皮日休','quantangshi','','卷34','香泉一合乳，煎作连珠沸。
时看蟹目溅，乍见鱼鳞起。
声疑松带雨，饽恐生烟翠。
尚把沥中山，必无千日醉。','',''),('quantangshi-33864','石榴歌','皮日休','quantangshi','','卷34','蝉噪秋枝槐叶黄，石榴香老愁寒霜。
流霞包染紫鹦粟，黄蜡纸裹红瓠房。
玉刻冰壶含露湿，斓斑似带湘娥泣。
萧娘初嫁嗜甘酸，嚼破水精千万粒。','',''),('quantangshi-33865','奉和鲁望四明山九题 石窗','皮日休','quantangshi','','卷34','窗开自真宰，四达见苍涯。
苔染浑成绮，云漫便当纱。
棂中空吐月，扉际不扃霞。
未会通何处，应怜玉女家。','',''),('quantangshi-33866','奉和鲁望四明山九题 过云','皮日休','quantangshi','','卷34','粉洞二十里，当中幽客行。
片时迷鹿迹，寸步隔人声。
以杖探虚翠，将襟惹薄明。
经时未过得，恐是入层城。','',''),('quantangshi-33867','奉和鲁望四明山九题 云南','皮日休','quantangshi','','卷34','云南背一川，无雁到峰前。
墟里生红药，人家发白泉。
儿童皆似古，婚嫁尽如仙。
共作真官户，无由税石田。','',''),('quantangshi-33868','奉和鲁望四明山九题 云北','皮日休','quantangshi','','卷34','云北昼冥冥，空疑背寿星。
犬能谙药气，人解写芝形。
野歇遇松盖，醉书逢石屏。
焚香住此地，应得入金庭。','',''),('quantangshi-33869','奉和鲁望四明山九题 鹿亭','皮日休','quantangshi','','卷34','鹿羣多此住，因构白云楣。
待侣傍花久，引麛穿竹迟。
经时掊玉涧，尽日嗅金芝。
为在石窗下，成仙自不知。','',''),('quantangshi-33870','奉和鲁望四明山九题 樊榭','皮日休','quantangshi','','卷34','主人成列仙，故榭独依然。
石洞哄人笑，松声惊鹿眠。
井香为大药，和语是灵篇。
欲买重栖隐，云峰不售钱。','',''),('quantangshi-33871','奉和鲁望四明山九题 潺湲洞','皮日休','quantangshi','','卷34','阴宫何处渊，到此洞潺湲。
敲碎一轮月，镕销半段天。
响高吹谷动，势急歕云旋。
料得深秋夜，临流尽古仙。','',''),('quantangshi-33872','奉和鲁望四明山九题 青棂子','皮日休','quantangshi','','卷34','山风熟异果，应是供真仙。
味似云腴美，形如玉脑圆。
衔来多野鹤，落处半灵泉。
必共玄都柰，花开不记年。','',''),('quantangshi-33873','奉和鲁望四明山九题 鞠侯','皮日休','quantangshi','','卷34','堪羡鞠侯国，碧岩千万重。
烟萝为印绶，云壑是堤封。
泉遣狙公护，果教𤟤子供。
尔徒如不死，应得蹑玄踪。','',''),('quantangshi-33874','五贶诗 五泻舟','皮日休','quantangshi','','卷34','何事有青钱，因人买钓船。
阔容兼饵坐，深许共蓑眠。
短好随朱鹭，轻堪倚白莲。
自知无用处，却寄五湖仙。','',''),('quantangshi-33875','五贶诗 华顶杖','皮日休','quantangshi','','卷34','金庭仙树枝，道客自携持。
探洞求丹粟，挑云觅白芝。
量泉将濯足，阑鹤把支颐。
以此将为赠，惟君尽得知。','',''),('quantangshi-33876','五贶诗 太湖砚','皮日休','quantangshi','','卷34','求于花石间，怪状乃天然。
中莹五寸劒，外[差]千叠莲。
月融还似洗，云湿便堪研。
寄与先生后，应添内外篇。','',''),('quantangshi-33877','五贶诗 乌龙养和','皮日休','quantangshi','','卷34','寿木拳数尺，天生形状幽。
把疑伤虺节，用恐破蛇瘤。
置合月观内，买须云肆头。
料君携去处，烟雨太湖舟。','',''),('quantangshi-33878','五贶诗 诃陵樽','皮日休','quantangshi','','卷34','一片鲎鱼壳，其中生翠波。
买须能紫贝，用合对红螺。
尽泻判狂药，禁敲任浩歌。
明朝与君后，争那玉山何。','',''),('quantangshi-33879','早春病中书事寄鲁望','皮日休','quantangshi','','卷34','眼晕见云母，耳虚闻海涛。
惜春狂似蝶，养病躁于猱。
案静方书古，堂空药气高。
可怜真宰意，偏解困吾曹。','',''),('quantangshi-33880','又寄次前韵','皮日休','quantangshi','','卷34','病根冬养得，春到一时生。
眼暗怜晨惨，心寒怯夜清。
妻仍嫌酒癖，医只禁诗情。
应被高人笑，忧身不似名。','',''),('quantangshi-33881','秋晚留题鲁望郊居二首 一','皮日休','quantangshi','','卷34','竹树冷濩落，入门神已清。
寒蛩傍枕响，秋菜上墙生。
黄犬病仍吠，白驴饥不鸣。
唯将一杯酒，尽日慰刘桢。','',''),('quantangshi-33882','秋晚留题鲁望郊居二首 二','皮日休','quantangshi','','卷34','冷卧空斋内，余酲夕未消。
秋花如有恨，寒蝶似无憀。
檐上落鬬雀，篱根生晚潮。
若轮羁旅事，犹自胜臯桥。','',''),('quantangshi-33883','初冬章上人院','皮日休','quantangshi','','卷34','寒到无妨睡，僧吟不废禅。
尚关经病鹤，犹滤欲枯泉。
静案贝多纸，闲炉波律烟。
清谭两三句，相向自翛然。','',''),('quantangshi-33884','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 一','皮日休','quantangshi','','卷34','一方萧洒地，之子独深居。
绕屋亲栽竹，堆牀手写书。
高风翔砌鸟，暴雨失池鱼。
暗识归山计，村边买鹿车。','',''),('quantangshi-33885','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 二','皮日休','quantangshi','','卷34','篱疎从绿槿，檐乱任黄茅。
压酒移溪石，煎茶拾野巢。
静窗悬雨笠，闲壁挂烟匏。
支遁今无骨，谁为世外交。','',''),('quantangshi-33886','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 三','皮日休','quantangshi','','卷34','茧稀初上簇，醅尽未干牀。
尽日留蚕母，移时祭麴王。
趁泉浇竹急，候雨种莲忙。
更葺园中景，应为顾辟疆。','',''),('quantangshi-33887','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 四','皮日休','quantangshi','','卷34','静僻无人到，幽深每自知。
鹤来添口数，琴到益家资。
坏堑生鱼沫，颓檐落燕儿。
空将绿蕉叶，来往寄闲诗。','',''),('quantangshi-33888','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 五','皮日休','quantangshi','','卷34','夏过无担石，日高开板扉。
僧虽与筒簟，人不典蕉衣。
鹤静共眠觉，鹭驯同钓归。
生公石上月，何夕约谭微。','',''),('quantangshi-33889','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 六','皮日休','quantangshi','','卷34','经岁岸乌纱，读书三十车。
水痕侵病竹，蛛网上衰花。
诗任传渔客，衣从递酒家。
知君秋晚事，白帻刈胡麻。','',''),('quantangshi-33890','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 七','皮日休','quantangshi','','卷34','寂历秋怀动，萧条夏思残。
久贫空酒库，多病束鱼竿。
玄想凝鹤扇，清斋拂鹿冠。
梦魂无俗事，夜夜到金坛。','',''),('quantangshi-33891','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 八','皮日休','quantangshi','','卷34','闭门无一事，安稳卧凉天。
砌下翘饥鹤，庭阴落病蝉。
倚杉闲把易，烧术静论玄。
赖有包山客，时时寄紫泉。','',''),('quantangshi-33892','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 九','皮日休','quantangshi','','卷34','病起扶灵寿，翛然强到门。
与杉除败叶，为石整危根。
薜蔓任遮壁，莲茎卧枕盆。
明朝有忙事，召客斵桐孙。','',''),('quantangshi-33893','临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访欵然惜去因成五言十首奉题屋壁 十','皮日休','quantangshi','','卷34','缓颊称无利，低眉号不能。
世情都太薄，俗意就中憎。
云态不知骤，鹤情非会征。
画臣谁奉诏，来此写姜肱。','',''),('quantangshi-33894','游栖霞寺','皮日休','quantangshi','','卷34','不见明居士，空山但寂寥。
白莲吟次缺，青霭坐来销。
泉冷无三伏，松枯有六朝。
何时石上月，相对论逍遥。','',''),('quantangshi-33895','旅舍除夜','皮日休','quantangshi','','卷34','永夜谁能守，羁心不放眠。
挑灯犹故岁，听角已新年。
出谷空嗟晚，衔杯尚愧先。
晚来辞逆旅，雪涕野槐天。','',''),('quantangshi-33896','鲁望示广文先生吴门二章情格高散可醒俗态因追想山中风度次韵属和存于诗编鲁望之命也 一','皮日休','quantangshi','','卷34','我见先生道，休思郑广文。
鹤翻希作伴，鸥却觅为羣。
逸好冠清月，高宜着白云。
朝廷未无事，争任醉醺醺。','',''),('quantangshi-33897','鲁望示广文先生吴门二章情格高散可醒俗态因追想山中风度次韵属和存于诗编鲁望之命也 二','皮日休','quantangshi','','卷34','能谙肉芝样，解讲隐书文。
终古神仙窟，穷年麋鹿羣。
行厨煮白石，卧具拂青云。
应在雷平上，支颐复半醺。','',''),('quantangshi-33898','虎丘寺殿前有古杉一本形状丑怪图之不尽况百卉竞媚若妬若媢娼唯此杉死抱奇节髐然闯然不知雨露之可生也风霜之可瘁也乃造化者方外之材乎遂赋三百言以见志','皮日休','quantangshi','','卷34','种日应逢晋，枯来必自隋。
鰐狂将立处，螭鬬未开时。
卓荦掷枪干，叉牙束戟枝。
初惊蟉篆活，复讶獝狂痴。
劲质如尧瘦，贞容学舜霉。
势能擒土伯，丑可骇山只。
虎爪拏岩稳，虬身脱浪欹。
槎头秃似刷，枿觜利于锥。
突兀方相胫，鳞皴夏氏胝。
根应藏鬼血，柯欲漏龙漦。
抝似神荼怒，呀如猰貐饥。
朽痈难可吮，枯瘇不堪治。
一炷玄云拔，三寻黑矟奇。
狼头㪍窣竖，虿尾掘挛垂。
目燥那逢爟，心开岂中铍。
任苔为疥癣，从蠹作疮痍。
品格齐辽鹤，年龄等宝龟。
将怀缩地力，欲负拔山姿。
未倒防风骨，初僵负贰尸。
漆书明古本，铁室抗全师。
碨礧还无极，伶俜又莫持。
坚应敌骏骨，文定写甝皮。
蟠屈愁凌刹，腾骧恐攫池。
抢烟寒嶱𡾲，披茑静䙰褷。
威仰诚难识，句芒恐不知。
好烧胡律看，堪共达多期。
寡色诸芳笑，无声众籁疑。
终添八柱位，未要一绳维。
尽日来唯我，当春翫更谁。
他年如入用，直构太平基。','',''),('quantangshi-33899','新秋言怀寄鲁望三十韵','皮日休','quantangshi','','卷34','新秋入破宅，疎澹若平郊。
户牖深如窟，诗书乱似巢。
移牀惊蟋蟀，拂匣动蟏蛸。
静把泉华掬，闲拈乳管敲。
桧身浑个矮，石面得能䫜。
小桂如拳叶，新松似手梢。
鹤鸣转清角，鹘下扑金𩩉。
合药还慵服，为文亦嬾抄。
烦心入夜醒，疾首带凉抓。
杉叶尖如镞，藤丝靭似鞘。
偾田含紫芋，低蔓隐青匏。
老柏浑如疥，阴苔忽似胶。
王余落败堑，胡孟入空庖。
度日忘冠带，经时忆酒肴。
有心同木偶，无舌并金铙。
兴欲添玄测，狂将换易爻。
达人唯落落，俗士自譊譊。
底力将排难，何颜用解嘲。
欲销毁后骨，空转坐来胞。
犹豫应难抱，狐疑不易包。
等闲逢毒蠚，容易遇咆哮。
时事方千蝎，公途正二崤。
名微甘世弃，性拙任时抛。
白日须投分，青云合定交。
仕应同五柳，归莫舍三茅。
涧鹿从来去，烟萝任溷肴。
狙公闹后戏，云母病来𦾱。
从此居方丈，终非竞斗筲。
道穷应鬼遣，性拙必天教。
无限疎慵事，凭君解一瓟。','',''),('quantangshi-33900','奉和鲁望秋日遣怀次韵','皮日休','quantangshi','','卷34','高蹈为时背，幽怀是事兼。
神仙君可致，江海我能淹。
共守庚申夜，同看乙巳占。
药囊除紫蠹，丹竈拂红盐。
与物深无竞，于生亦太廉。
鸿灾因足警，鱼祸为稀潜。
笔砚秋光洗，衣巾夏藓霑。
酒甔香竹院，鱼笼挂茅檐。
琴忘因抛谱，诗存为致签。
茶旗经雨展，石笋带云尖。
鹤共心情慢，乌同面色黔。
向阳裁白帢，终岁忆貂襜。
取岭为山障，将泉作水帘。
溪晴多晚鹭，池废足秋蟾。
破衲虽云补，闲斋未办苫。
共君还有役，竟夕得厌厌。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-33901','江南书情二十韵寄秘阁韦校书贻之商洛宋先辈垂文二同年','皮日休','quantangshi','','卷34','四载加前字，今来未改衔。
君批凤尾诏，我住虎头岩。
季氏唯谋逐，臧仓只拟谗。
时讹轻五羖，俗浅重三缄。
瘦去形如鹤，忧来态似獑。
才非师赵壹，直欲效陈咸。
孤竹宁收笛，黄琮未作瑊。
作羊宁免狠，为兔即须毚。
枕户槐从亚，侵堦草嬾芟。
壅泉教咽咽，垒石放巉巉。
掣钓随心动，抽书任意杴。
茶教弩父摘，酒遣僰童监。
默坐看山困，清斋饮水严。
藓生天竺屐，烟外洞庭帆。
病久新乌帽，闲多着白衫。
药苞陈[雨]匼，诗草蠹云函。
遣客呼林狖，辞人寄海𧍧。
室唯搜古器，钱只买秋杉。
寡合无深契，相期有至諴。
他年如访问，烟茑暗髟髟。','',''),('quantangshi-33902','忆洞庭观步十韵','皮日休','quantangshi','','卷34','前时登观步，暑雨正铮摐。
上戍看绵蕝，登村度石矼。
崦花时有蔟，溪鸟不成双。
远树点黑矟，遥峰露碧幢。
岩根瘦似壳，杉破腹如腔。
䘨𧘈渔人服，筕篖野店窗。
多携白木锸，爱买紫泉缸。
仙犬声音古，遗民意绪厖。
何文堪纬地，底策可经邦。
自此将妻子，归山不姓庞。','',''),('quantangshi-33903','谏议以罢郡将归以六韵赐示因伫酬献','皮日休','quantangshi','','卷34','欲下持衡诏，先容解印归。
露浓春后泽，霜薄霁来威。
旧化堪治疾，余恩可疗饥。
隔花攀去棹，穿柳挽行衣。
佐理能无取，酬知力甚微。
空将千感泪，异日拜黄扉。','',''),('quantangshi-33904','过云居院玄福上人旧居','皮日休','quantangshi','','卷34','重到云居独悄然，隔窗窥影尚疑禅。
不逢野老来听法，犹见邻僧为引泉。
龛上已生新石耳，壁间空带旧茶烟。
南宗弟子时时到，泣把山花奠几筵。','',''),('quantangshi-33905','陪江西裴公游襄州延庆寺','皮日休','quantangshi','','卷34','丹霄路上歇征轮，胜地偷闲一日身。
不署前驱惊野鸟，唯将后乘载诗人。
岩边候吏云遮却，竹下朝衣露滴新。
更向碧山深处问，不妨犹有草茅臣。','',''),('quantangshi-33906','西塞山泊渔家','皮日休','quantangshi','','卷34','白纶巾下髪如丝，静倚枫根坐钓矶。
中妇桑村挑叶去，小儿沙市买蓑归。
雨来莼菜流船滑，春后鲈鱼坠钓肥。
西塞山前终日客，隔波相羡尽依依。','',''),('quantangshi-33907','襄州春游','皮日休','quantangshi','','卷34','信马腾腾触处行，春风相引与诗情。
等闲遇事成歌咏，取次冲筵隐姓名。
映柳认人多错误，透花窥鸟最分明。
岑牟单绞何曾着，莫道猖狂似禰衡。','',''),('quantangshi-33908','送从弟皮崇归复州','皮日休','quantangshi','','卷34','羡尔优游正少年，竟陵烟月似吴天。
车螯近岸无妨取，舴艋随风不费牵。
处处路傍千顷稻，家家门外一渠莲。
殷勤莫笑襄阳住，为爱南溪缩项鳊。','',''),('quantangshi-33909','题潼关兰若','皮日休','quantangshi','','卷34','潼津罢惊有招提，近百年无战马嘶。
壮士不言三尺劒，谋臣休道一丸泥。
昔时驰道洪波上，今日宸居紫气西。
关吏不劳重借问，弃繻生拟入耶溪。','',''),('quantangshi-33910','襄阳闲居与友生夜会','皮日休','quantangshi','','卷34','习隐悠悠世不知，林园幽事递相期。
旧丝再上琴调晚，坏叶重烧酒暖迟。
三径引时寒步月，四邻偷得夜吟诗。
草玄寂淡无人爱，不遇刘歆更语谁。','',''),('quantangshi-33911','习池晨起','皮日休','quantangshi','','卷34','清曙萧森载酒来，凉风相引绕亭台。
数声翡翠背人去，一番芙蓉含日开。
茭叶深深埋钓艇，鱼儿漾漾逐流杯。
竹屏风下登山屐，十宿高阳忘却回。','',''),('quantangshi-33912','秋晚自洞庭湖别业寄穆秀才','皮日休','quantangshi','','卷34','破村寥落过重阳，独自撄宁葺草房。
风扯红蕉仍换叶，雨淋黄菊不成香。
野猨偷栗重窥户，落雁疑人更绕塘。
他日若修耆旧传，为予添取此书堂。','',''),('quantangshi-33913','华山李炼师所居','皮日休','quantangshi','','卷34','麻姑古貌上仙才，谪向莲峰管玉台。
瑞气染衣金液启，香烟映面紫文开。
孤云尽日方离洞，双鹤移时只有苔。
深夜寂寥存想歇，月天时下草堂来。','',''),('quantangshi-33914','宏词下第感恩献兵部侍郎','皮日休','quantangshi','','卷34','分明仙籍列清虚，自是还丹九转疎。
画虎已成翻类狗，登龙才变即为鱼。
空慙季布千金诺，但负刘弘一纸书。
犹有报恩方寸在，不知通塞竟何如。','',''),('quantangshi-33915','襄州汉阳王故宅','皮日休','quantangshi','','卷34','碑字依稀庙已荒，犹闻耆旧忆贤王。
园林一半为他主，山水虚言是故乡。
戟户野蒿生翠瓦，舞楼栖鸽污雕梁。
柱天功业缘何事，不得终身似霍光。','',''),('quantangshi-33916','伤卢献秀才','皮日休','quantangshi','','卷34','愍征新价欲凌空，一首堪欺左太冲。
只为白衣声过重，且非青汉路难通。
贵侯待写过门下，词客偷名入卷中。
手弄桂枝嫌不折，直教身殁负春风。','',''),('quantangshi-33917','南阳','皮日休','quantangshi','','卷34','昆阳王气已萧疎，依旧山河捧帝居。
废路塌平残瓦砾，破坟耕出烂图书。
绿莎满县年荒后，白鸟盈溪雨霁初。
二百年来霸王业，可知今日是丘墟。','',''),('quantangshi-33918','秋晚访李处士所居','皮日休','quantangshi','','卷34','门前襄水碧潺潺，静钓归来不掩关。
书阁鼠穿厨簏破，竹园霜后桔橰闲。
儿童不许惊幽鸟，药草须教上假山。
莫为爱诗偏念我，访君多得醉中还。','',''),('quantangshi-33919','李处士郊居','皮日休','quantangshi','','卷34','石衣如髪小溪清，溪上柴门架树成。
园里水流浇竹响，窗中人静下棋声。
几多狎鸟皆谙性，无限幽花未得名。
满引红螺诗一首，刘桢失却病心情。','',''),('quantangshi-33920','送令狐补阙归朝','皮日休','quantangshi','','卷34','文如日月气如虹，举国重生正始风。
且愿仲山居左掖，只忧徐邈入南宫。
朝衣正在天香里，谏草应焚禁漏中。
为说明年今日事，晋廷新拜黑头公。','',''),('quantangshi-33921','洛中寒食二首 一','皮日休','quantangshi','','卷34','千门万户掩斜晖，绣幰金衔晚未归。
击鞠王孙如锦地，鬬鸡公子似花衣。
嵩云静对行台起，洛鸟闲穿上苑飞。
唯有路傍无意者，献书未纳问淮肥。','',''),('quantangshi-33922','洛中寒食二首 二','皮日休','quantangshi','','卷34','远近垂杨映钿车，天津桥影压神霞。
弄春公子正回首，趁节行人不到家。
洛水万年云母竹，汉陵千载野棠花。
欲知豪贵堪愁处，请看邙山晚照斜。','',''),('quantangshi-33923','登第后寒食杏园有宴因寄录事宋垂文同年','皮日休','quantangshi','','卷34','雨洗清明万象鲜，满城车马簇红筵。
恩荣虽得陪高会，科禁惟忧犯列仙。
当醉不知开火日，正贫那似看花年。
纵来恐被青娥笑，未纳春风一宴钱。','',''),('quantangshi-33924','陈先辈故居','皮日休','quantangshi','','卷34','杉桂交阴一里余，逢人浑似洞天居。
千株橘树唯沽酒，十顷莲塘不买鱼。
藜杖闲来侵径竹，角巾端坐满楼书。
襄阳无限烟霞地，难觅幽奇似此殊。','',''),('quantangshi-33925','奉和鲁望寒夜访寂上人次韵','皮日休','quantangshi','','卷34','院寒青霭正沈沈，霜栈干鸣入古林。
数叶贝书松火暗，一声金磬桧烟深。
陶潜见社无妨醉，殷浩谭经不废吟。
何事欲攀尘外契，除君皆有利名心。','',''),('quantangshi-33926','江南道中怀茅山广文南阳博士三首 一','皮日休','quantangshi','','卷34','寒岚依约认华阳，遥想高人卧草堂。
半日始斋青䭀饭，移时空印白檀香。
鹤雏入夜归云屋，乳管逢春落石牀。
谁道夫君无伴侣，不离窗下见羲皇。','',''),('quantangshi-33927','江南道中怀茅山广文南阳博士三首 二','皮日休','quantangshi','','卷34','住在华阳第八天，望君唯欲结良缘。
堂扃洞里千秋燕，厨盖岩根数斗泉。
坛上古松疑度世，观中幽鸟恐成仙。
不知何事迎新岁，乌纳裘中一觉眠。','',''),('quantangshi-33928','江南道中怀茅山广文南阳博士三首 三','皮日休','quantangshi','','卷34','五色香烟惹内文，石饴初熟酒初醺。
将开丹竈那防鹤，欲算棋图却望云。
海气平生当洞见，瀑冰初坼隔山闻。
如何世外无交者，一卧金坛只有君。','',''),('quantangshi-33929','奉和鲁望早春雪中作吴体见寄','皮日休','quantangshi','','卷34','威仰噤死不敢语，琼花云魄清珊珊。
溪光冷射触𪈺瑦，柳带冻脆攒栏杆。
竹根乍烧玉节快，酒面新泼金膏寒。
全吴缥瓦十万户，惟君与我如袁安。','',''),('quantangshi-33930','吴中言情寄鲁望','皮日休','quantangshi','','卷34','古来伧父爱吴乡，一上胥台不可忘。
爱酒有情如手足，除诗无计似膏肓。
宴时不辍琅书味，斋日难判玉鲙香。
为说松江堪老处，满船烟月湿莎裳。','',''),('quantangshi-33931','行次野梅','皮日休','quantangshi','','卷34','茑拂萝捎一树梅，玉妃无侣独裴回。
好临王母瑶池发，合傍萧家粉水开。
共月已为迷眼伴，与春先作断肠媒。
不堪便向多情道，万片霜华雨损来。','',''),('quantangshi-33932','扬州看辛夷花','皮日休','quantangshi','','卷34','腊前千朵亚芳丛，细腻偏胜素柰功。
螓首不言披晓雪，麝脐无主任春风。
一枝拂地成瑶圃，数树参庭是蘂宫。
应为当时天女服，至今犹未放全红。','',''),('quantangshi-33933','暇日独处寄鲁望','皮日休','quantangshi','','卷34','幽慵不觉耗年光，犀柄金徽乱一牀。
野客共为赊酒计，家人同作借书忙。
园蔬预遣分僧料，廪粟先教算鹤粮。
无限高情好风月，不妨犹得事吾王。','',''),('quantangshi-33934','屣步访鲁望不遇','皮日休','quantangshi','','卷34','雪晴墟里竹欹斜，蜡屐徐吟到陆家。
荒径埽稀堆柏子，破扉开涩染苔花。
壁闲定欲图双桧，厨静空如饭一麻。
拟受太玄今不遇，可怜遗恨似侯芭。','',''),('quantangshi-33935','开元寺客省早景即事','皮日休','quantangshi','','卷34','客省萧条柿叶红，楼台如画倚霜空。
铜池数滴桂上雨，金铎一声松杪风。
鹤静时来珠像侧，鸽驯多在宝幡中。
如何尘外虚为契，不得支公此会同。','',''),('quantangshi-33936','奉和鲁望独夜有怀吴体见寄','皮日休','quantangshi','','卷34','病鹤带雾傍独屋，破巢含雪倾孤梧。
濯足将加汉光腹，抵掌欲捋梁武须。
隐几清吟谁敢敌，枕琴高卧真堪图。
此时枉欠高散物，楠瘤作樽石作垆。','',''),('quantangshi-33937','病中有人惠海蟹转寄鲁望','皮日休','quantangshi','','卷34','绀甲青筐染菭衣，岛夷初寄北人时。
离居定有石帆觉，失伴唯应海月知。
族类分明连璅𤥐形容好个似蟛蜞。
病中无用霜螯处，寄与夫君左手持。','',''),('quantangshi-33938','病中美景颇阻追游因寄鲁望','皮日休','quantangshi','','卷34','瘿牀闲卧昼迢迢，唯把真如慰寂寥。
南国不须收薏苡，百年终竟是芭蕉。
药前美禄应难断，枕上芳辰岂易销。
看取病来多少日，早梅零落玉华焦。','',''),('quantangshi-33939','鲁望以花翁之什见招因次韵酬之','皮日休','quantangshi','','卷34','九十携锄伛偻翁，小园幽事尽能通。
斸烟栽药为身计，负水浇花是世功。
婚嫁定期杉叶紫，盖藏应待桂枝红。
不知家道能多少，只在句芒一夜风。','',''),('quantangshi-33940','病中庭际海石榴花盛发感而有寄','皮日休','quantangshi','','卷34','一夜春光绽绛囊，碧油枝上昼煌煌。
风匀秖似调红露，日暖唯忧化赤霜。
火齐满枝烧夜月，金津含蘂滴朝阳。
不知桂树知情否，无限同游阻陆郎。','',''),('quantangshi-33941','早春以橘子寄鲁望','皮日休','quantangshi','','卷34','个个和枝叶捧鲜，彩凝犹带洞庭烟。
不为韩嫣金丸重，直是周王玉果圆。
剖似日魂初破后，弄如星髓未销前。
知君多病仍中圣，尽送寒苞向枕边。','',''),('quantangshi-33942','病中书情寄上崔谏议','皮日休','quantangshi','','卷34','十日来来旷奉公，闭门无事忌春风。
虫丝度日萦琴荐，蛀粉经时落酒筒。
马足歇从残漏外，鱼须抛在乱书中。
殷勤莫怪求医切，只为山樱欲放红。','',''),('quantangshi-33943','病孔雀','皮日休','quantangshi','','卷34','烟花虽媚思沈冥，犹自抬头护翠翎。
强听紫箫如欲舞，困眠红树似依屏。
因思桂蠹伤肌骨，为忆松鹅损性灵。
尽日春风吹不起，钿毫金缕一星星。','',''),('quantangshi-33944','奉和鲁望上元日道室焚修','皮日休','quantangshi','','卷34','明真台上下仙官，玄藻初吟万籁寒。
飙御有声时杳杳，宝衣无影自珊珊。
蘂书乞见斋心易，玉籍求添拜首难。
端简不知清景暮，灵芜香烬落金坛。','',''),('quantangshi-33945','奉酬鲁望惜春见寄','皮日休','quantangshi','','卷34','十五日中春日好，可怜沈痼冷如灰。
以前虽被愁将去，向后须教醉领来。
梅片尽飘轻粉靥，柳芽初吐烂金醅。
病中无限花番次，为约东风且住开。','',''),('quantangshi-33946','闻鲁望游颜家林园病中有寄','皮日休','quantangshi','','卷34','一夜韶姿着水光，谢家春草满池塘。
细挑泉眼寻新脉，轻把花枝嗅宿香。
蝶欲试飞犹护粉，莺初学啭尚羞簧。
分明不得同君赏，尽日倾心羡索郎。','',''),('quantangshi-33947','奉和鲁望春雨即事次韵','皮日休','quantangshi','','卷34','织恨凝愁映鸟飞，半旬飘洒掩韶晖。
山容洗得如烟瘦，地脉流来似乳肥。
野客正闲移竹远，幽人多病探花稀。
何年细湿华阳道，两乘巾车相并归。','',''),('quantangshi-33948','鲁望春日多寻野景日休抱疾杜门因有是寄','皮日休','quantangshi','','卷34','野侣相逢不待期，半缘幽事半缘诗。
乌纱任岸穿筋竹，白袷从披趁肉芝。
数卷蠹书棊处展，几升菰米钓前炊。
病中不用君相忆，折取山樱寄一枝。','',''),('quantangshi-33949','鲁望以躬掇野蔬兼示雅什用以酬谢','皮日休','quantangshi','','卷34','杖擿春烟暖向阳，烦君为我致盈筐。
深挑乍见牛唇液，细掐徐闻鼠耳香。
紫甲采从泉脉畔，翠牙搜自石根傍。
雕胡饭熟𩝊糊软，不是高人不合尝。','',''),('quantangshi-33950','卧病感春寄鲁望','皮日休','quantangshi','','卷34','乌皮几上困腾腾，玉柄清羸愧不能。
昨夜眠时稀似鹤，今朝餐数减于僧。
药销美禄应夭折，医过芳辰定鬼憎。
任是雨多游未得，也须收在探花朋。','',''),('quantangshi-33951','奉和鲁望徐方平后闻赦次韵','皮日休','quantangshi','','卷34','金鸡烟外上临轩，紫诰新垂作解恩。
涿鹿未销初败血，新安顿雪已坑魂。
空林叶尽蝗来郡，腐骨花生战后村。
未遣蒲车问幽隐，共君应老抱桐孙。','',''),('quantangshi-33952','奉酬鲁望见答鱼牋之什','皮日休','quantangshi','','卷34','轻如隐起腻如饴，除却鲛工解制稀。
欲写恐成河伯诏，试裁疑是水仙衣。
毫端白獭脂犹湿，指下冰蚕子欲飞。
若用莫将闲处去，好题春思赠江妃。','',''),('quantangshi-33953','病后春思','皮日休','quantangshi','','卷34','连钱锦暗麝氛氲，荆思多才咏鄂君。
孔雀钿寒窥沼见，石榴红重堕堦闻。
牢愁有度应如月，春梦无心秖似云。
应笑病来慙满愿，花牋好作断肠文。','',''),('quantangshi-33954','偶成小酌招鲁望不至以诗为解因次韵酬之','皮日休','quantangshi','','卷34','醉侣相邀爱早阳，小筵催办不胜忙。
冲深柳驻吴娃幰，倚短花排羯鼓牀。
金凤欲为莺引去，钿蝉疑被蝶勾将。
如何共是忘形者，不见渔阳掺一场。','',''),('quantangshi-33955','以纱巾寄鲁望因而有作','皮日休','quantangshi','','卷34','周家新样替三梁，裹髪偏宜白面郎。
掩歛乍疑裁黑雾，轻明浑似戴玄霜。
今朝定见看花昃，明日应闻漉酒香。
更有一般君未识，虎文巾在绛霄房。','',''),('quantangshi-33956','临顿宅将有归于之日鲁望以诗见贶因抒怀酬之','皮日休','quantangshi','','卷34','共老林泉忍暂分，此生应不识回文。
几枚竹笥送德曜，一乘柴车迎少君。
举案品多缘涧药，承家事少为溪云。
居然自是幽人事，辄莫教他孙寿闻。','',''),('quantangshi-33957','奉和鲁望谢惠巨鱼之半','皮日休','quantangshi','','卷34','钓公来信自松江，三尺春鱼拨刺霜。
腹内旧钩苔染涩，腮中新饵藻和香。
冷鳞中断榆钱破，寒骨平分玉筯光。
何事贶君偏得所，秖缘同是越航郎。','',''),('quantangshi-33958','馆娃宫怀古','皮日休','quantangshi','','卷34','艳骨已成兰麝土，宫墙依旧压层崖。
弩台雨坏逢金镞，香径泥销露玉钗。
砚沼只留溪鸟浴，屧廊空信野花埋。
姑苏麋鹿真闲事，须为当时一怆怀。','',''),('quantangshi-33959','以紫石砚寄鲁望兼酬见赠','皮日休','quantangshi','','卷34','样如金蹙小能轻，微润将融紫玉英。
石墨一研为凤尾，寒泉半勺是龙睛。
骚人白芷伤心暗，狎客红筵夺眼明。
两地有期皆好用，不须空把洗溪声。','',''),('quantangshi-33960','奉和鲁望同游北禅院','皮日休','quantangshi','','卷34','戚历杉阴入草堂，老僧相见似相忘。
吟多几转莲花漏，坐久重焚柏子香。
鱼惯斋时分净食，鸽能闲处傍禅牀。
云林满眼空羁滞，欲对弥天却自伤。','',''),('quantangshi-33961','孙发百篇将游天台请诗赠行因以送之','皮日休','quantangshi','','卷34','孙子荆家思有余，元戎曾荐入公车。
百篇宫体喧金屋，一日官衔下玉除。
紫府近通斋后梦，赤城新有寄来书。
因逢二老如相问，正滞江南为𩸃鱼。','',''),('quantangshi-33962','奉和鲁望蔷薇次韵','皮日休','quantangshi','','卷34','谁绣连延满户陈，暂应遮得陆郎贫。
红芳掩歛将迷蝶，翠蔓飘颻欲挂人。
低拂地时如堕马，高临墙处似窥邻。
秖应是董双成戏，剪得神霞寸寸新。','',''),('quantangshi-33963','闻开元寺开笋园寄章上人','皮日休','quantangshi','','卷34','园鏁开声骇鹿羣，满林鲜箨水犀文。
森森竞泫林梢雨，𡾼𡾼争穿石上云。
并出亦如鹅管合，各生还似犬牙分。
折烟束露如相遗，何胤明朝不茹荤。','',''),('quantangshi-33964','开元寺佛钵诗','皮日休','quantangshi','','卷34','帝青石作绿冰姿，曾得金人手自持。
拘律树边斋散后，提罗花下洗来时。
乳麋味断中天觉，麦麨香消大劫知。
从此共君亲顶戴，斜风应不等闲吹。','',''),('quantangshi-33965','夏首病愈因招鲁望','皮日休','quantangshi','','卷34','晓入清和尚袷衣，夏阴初合掩双扉。
一声拨谷桑柘晚，数点舂锄烟雨微。
贫养山禽能个瘦，病关芳草就中肥。
明朝早起非无事，买得莼丝待陆机。','',''),('quantangshi-33966','奉和鲁望新夏东郊闲泛','皮日休','quantangshi','','卷34','水物轻明淡似秋，多情才子倚兰舟。
碧莎裳下携诗草，黄{𥫗/罒/伐}楼中挂酒篘。
莲叶蘸波初转棹，鱼儿簇饵未谙钩。
共君莫问当时事，一点沙禽胜五侯。','',''),('quantangshi-33967','奉和鲁望四月十五日道室书事','皮日休','quantangshi','','卷34','忘朝斋戒是寻常，静启金根第几章。
竹叶饮为甘露色，莲花鲊作肉芝香。
松膏背日凝云磴，丹粉经年染石牀。
剩欲与君终此志，顽仙唯恐鬓成霜。','',''),('quantangshi-33968','奉和鲁望看压新醅','皮日休','quantangshi','','卷34','一箦松花细有声，旋将渠椀撇寒清。
秦吴只恐篘来近，刘项真能酿得平。
酒德有神多客颂，醉乡无货没人争。
五湖烟水郎山月，合向樽前问底名。','',''),('quantangshi-33969','登初阳楼寄怀北平郎中','皮日休','quantangshi','','卷34','危楼新制号初阳，白粉青葌射沼光。
避酒几浮轻舴艋，下棊曾觉睡鸳鸯。
投钩列坐围华烛，格簺分朋占靓妆。
莫怪重登频有恨，二年曾侍旧吴王。','',''),('quantangshi-33970','夏初访鲁望偶题小斋','皮日休','quantangshi','','卷34','半里芳阴到陆家，藜牀相劝饭胡麻。
林间度宿抛棊局，壁上经旬挂钓车。
野客病时分竹米，邻翁斋日乞藤花。
踟蹰为放闲人去，半[岸]纱帩待月华。','',''),('quantangshi-33971','所居首夏水木尤清适然有作','皮日休','quantangshi','','卷34','病来无事草堂空，昼水休闻十二筒。
桂静似逢青眼客，松闲如见绿毛翁。
潮期暗动庭泉碧，梅信微侵地障红。
尽日枕书慵起得，被君犹自笑从公。','',''),('quantangshi-33972','重玄寺元达年逾八十好种名药凡所植者多至自天台四明包山句曲丛翠纷糅各可指名余奇而访之因题二章 一','皮日休','quantangshi','','卷34','雨涤烟锄伛偻賷，绀牙红甲两三畦。
药名却笑桐君少，年纪翻嫌竹祖低。
白石静敲蒸术火，清泉闲洗种花泥。
怪来昨日休持钵，一尺雕胡似掌齐。','',''),('quantangshi-33973','重玄寺元达年逾八十好种名药凡所植者多至自天台四明包山句曲丛翠纷糅各可指名余奇而访之因题二章 二','皮日休','quantangshi','','卷34','香蔓蒙茏覆昔邪，桂烟杉露湿袈裟。
石盆换水捞松叶，竹径穿牀避笋芽。
藜杖移时挑细药，铜瓶尽日灌幽花。
支公谩道怜神骏，不及今朝种一麻。','',''),('quantangshi-33974','怀华阳润卿博士三首 一','皮日休','quantangshi','','卷34','先生一向事虚皇，天市坛西与世忘。
环堵养龟看气诀，刀圭饵犬试仙方。
静探石脑衣裾润，闲炼松脂院落香。
闻道征贤须有诏，不知何日到良常。','',''),('quantangshi-33975','怀华阳润卿博士三首 二','皮日休','quantangshi','','卷34','冥心唯事白英君，不问人间爵与勋。
林下醉眠仙鹿见，洞中闲话隐芝闻。
石牀卧苦浑无藓，藤箧开稀恐有云。
料得虚皇新诏样，青琼板上绿为文。','',''),('quantangshi-33976','怀华阳润卿博士三首 三','皮日休','quantangshi','','卷34','凤骨轻来称瘦容，华阳馆主未成翁。
数行玉札存心久，一掬云浆漱齿空。
白石煮多熏屋黑，丹砂埋久染泉红。
他年欲事先生去，十赉须加陆逸冲。','',''),('quantangshi-33977','鲁望以竹夹膝见寄因次韵酬谢','皮日休','quantangshi','','卷34','圆于玉柱滑于龙，来自衡阳彩翠中。
拂润恐飞清夏雨，叩虚疑贮碧湘风。
大胜书客裁成柬，颇赛溪翁截[作]筒。
从此角巾因尔戴，俗人相访若为通。','',''),('quantangshi-33978','夏景无事因怀章来二上人二首 一','皮日休','quantangshi','','卷34','澹景微阴正送梅，幽人逃暑瘿柟杯。
水花移得和鱼子，山蕨收时带竹胎。
啸馆大都偏见月，醉乡终竟不闻雷。
更无一事唯留客，却被高僧怕不来。','',''),('quantangshi-33979','夏景无事因怀章来二上人二首 二','皮日休','quantangshi','','卷34','佳树盘珊枕草堂，此中随分亦闲忙。
平铺风簟寻琴谱，静扫烟窗着药方。
幽鸟见贫留好语，白莲知卧送清香。
从今有计消闲日，更为支公置一牀。','',''),('quantangshi-33980','寄琼州杨舍人','皮日休','quantangshi','','卷34','德星芒彩瘴天涯，酒树堪消谪宦嗟。
行遇竹王因设奠，居逢木客又迁家。
清斋净溲桄榔麪，远信闲封豆蔻花。
清切会须归有日，莫贪句漏足丹砂。','',''),('quantangshi-33981','鲁望以轮钩相示缅怀高致因作三篇 一','皮日休','quantangshi','','卷34','角柄孤轮细腻轻，翠篷十载伴君行。
拈时解转蟾蜍魄，抛处能啼络纬声。
七里滩波喧一舍，五云溪月静三更。
牛衣鲋足和蓑睡，谁信人间有利名。','',''),('quantangshi-33982','鲁望以轮钩相示缅怀高致因作三篇 二','皮日休','quantangshi','','卷34','一线飘然下碧塘，溪翁无语远相望。
蓑衣旧去烟披重，箬笠新来雨打香。
白鸟白莲为梦寐，清风清月是家乡。
明朝有物充君信，㰂酒三瓶寄夜航。','',''),('quantangshi-33983','鲁望以轮钩相示缅怀高致因作三篇 三','皮日休','quantangshi','','卷34','尽日悠然舴艋轻，小轮声细雨溟溟。
三寻丝带桐江烂，一寸钩含笠泽腥。
用近詹何传钓法，收和范蠡养鱼经。
孤篷半夜无余事，应被严滩聒酒醒。','',''),('quantangshi-33984','吴中书事寄汉南裴尚书','皮日休','quantangshi','','卷34','万家无事鏁兰桡，乡味腥多厌紫虈。
水似棊文交度郭，柳如行障俨遮桥。
青梅蔕重初迎雨，白鸟羣高欲避潮。
唯望旧知怜此意，得为伧鬼也逍遥。','',''),('quantangshi-33985','夏景冲澹偶然作二首 一','皮日休','quantangshi','','卷34','秖隈蒲褥岸乌纱，味道澄怀景便斜。
红印寄泉慙郡守，青筐与笋愧僧家。
茗炉尽日烧松子，书案经时剥瓦花。
园吏暂栖君莫笑，不妨犹更着南华。','',''),('quantangshi-33986','夏景冲澹偶然作二首 二','皮日休','quantangshi','','卷34','一室无喧事事幽，还如贞白在高楼。
天台画得千回看，湖目芳来百度游。
无限世机吟处息，几多身计钓前休。
他年谒帝言何事，请赠刘伶作醉侯。','',''),('quantangshi-33987','送李明府之任海南','皮日休','quantangshi','','卷34','五羊城在蜃楼边，墨绶垂腰正少年。
山静不应闻屈鸟，草深从使翳贪泉。
蟹奴晴上临潮槛，燕婢秋随过海船。
一事与君消远宦，乳蕉花发讼庭前。','',''),('quantangshi-33988','寄题罗浮轩辕先生所居','皮日休','quantangshi','','卷34','乱峰四百三十二，欲问征君何处寻。
红翠数声瑶室响，真檀一炷石楼深。
山都遣负沽来酒，樵客容看化后金。
从此谒师知不远，求官先有葛洪心。','',''),('quantangshi-33989','宿报恩寺水阁','皮日休','quantangshi','','卷34','寺鏁双峰寂不开，幽人中夜独裴回。
池文带月铺金簟，莲朵含风动玉杯。
往往竹梢摇翡翠，时时杉子掷莓苔。
可怜此际谁曾见，唯有支公尽看来。','',''),('quantangshi-33990','醉中偶作呈鲁望','皮日休','quantangshi','','卷34','溪云涧鸟本吾侪，刚为浮名事事乖。
十里寻山为思役，五更看月是情差。
分将吟咏华双鬓，力以壶觞固百骸。
争得草堂归卧去，共君同作太常斋。','',''),('quantangshi-33991','寄滑州李副使员外','皮日休','quantangshi','','卷34','兵绕临淮数十重，铁衣才子正从公。
军前草奏旄头下，城上封书箭𦼮中。
围合只应闻晓雁，血腥何处避春风。
故人勋重金章贵，犹在江湖积劒功。','',''),('quantangshi-33992','伤史拱山人','皮日休','quantangshi','','卷34','一缄幽信自襄阳，上报先生去岁亡。
山客为医翻贳药，野僧因吊却焚香。
峰头孤冢为云穴，松下灵筵是石牀。
宗炳死来君又去，终身不复到柴桑。','',''),('quantangshi-33993','吴中言怀寄南海二同年','皮日休','quantangshi','','卷34','曲水分飞岁已赊，东南为客各天涯。
退公秖傍苏劳竹，移宴多随末利花。
铜鼓夜敲溪上月，布帆晴照海边霞。
三年谩被鲈鱼累，不得横经侍绛纱。','',''),('quantangshi-33994','奉和鲁望白鸥诗','皮日休','quantangshi','','卷34','雪羽䙰褷半惹泥，海云深处旧巢迷。
池无飞浪争教舞，洲少轻沙若遣栖。
烟外失羣慙雁鹜，波中得志羡凫鹥。
主人恩重真难遇，莫为心孤忆旧溪。','',''),('quantangshi-33995','奉和鲁望怀杨台文杨鼎文二秀才','皮日休','quantangshi','','卷34','羊昙留我昔经春，各以篇章鬬五云。
宾草每容闲处见，击琴多任醉中闻。
钓前青翰交加倚，醉后红鱼取次分。
为说风标曾入梦，上仙初着翠霞帬。','',''),('quantangshi-33996','友人以人参见惠因以诗谢之','皮日休','quantangshi','','卷34','神草延年出道家，是谁披露记三桠。
开时的定涵云液，斸后还应带石花。
名士寄来消酒渴，野人煎处撇泉华。
从今汤剂如相续，不用金山焙上茶。','',''),('quantangshi-33997','伤进士严子重诗','皮日休','quantangshi','','卷34','十哭都门牓上尘，盖棺终是五湖人。
生前有敌唯丹桂，没后无家秖白苹。
箬下斩新醒处月，江南依旧咏来春。
知君精爽应无尽，必在酆都颂帝晨。','',''),('quantangshi-33998','奉和鲁望早秋吴体次韵','皮日休','quantangshi','','卷34','书淫传癖穷欲死，譊譊何必频相仍。
日干阴藓厚堪剥，藤把欹松牢似绳。
捣药香侵白袷袖，穿云润破乌纱棱。
安得瑶池饮残酒，半醉骑下垂天鹏。','',''),('quantangshi-33999','奉和鲁望秋赋有期次韵','皮日休','quantangshi','','卷34','十载江湖尽是闲，客儿诗句满人间。
郡侯闻誉亲邀得，乡老知名不放还。
应带瓦花经汴水，更携云实出包山。
太微宫里环冈树，无限瑶枝待尔攀。','',''),('quantangshi-34000','奉和鲁望病中秋怀次韵','皮日休','quantangshi','','卷34','贫病于君亦太兼，才高应亦被天嫌。
因分鹤料家资减，为置僧餐口数添。
静里改诗空凭几，寒中注易不开帘。
清词一一侵真宰，甘取穷愁不用占。','',''),('quantangshi-34001','新秋即事三首 一','皮日休','quantangshi','','卷34','痴号多于顾恺之，更无余事可从知。
酒坊吏到常先见，鹤料符来每探支。
凉后每谋清月社，晚来专赴白莲期。
共君无事堪相贺，又到金虀玉鲙时。','',''),('quantangshi-34002','新秋即事三首 二','皮日休','quantangshi','','卷34','堪笑高阳病酒徒，幅巾潇洒在东吴。
秋期净扫云根瘦，山信回缄乳管粗。
白月半窗抄术序，清泉一器授芝图。
乞求待得西风起，尽挽烟帆入太湖。','',''),('quantangshi-34003','新秋即事三首 三','皮日休','quantangshi','','卷34','露槿风杉满曲除，高秋无事似云庐。
醉多已任家人厌，病久还甘吏道疎。
青桂巾箱时寄药，白纶卧具半抛书。
君卿唇舌非吾事，且向江南问鳆鱼。','',''),('quantangshi-34004','南阳润卿将归雷平因而有赠','皮日休','quantangshi','','卷34','借问山中许道士，此回归去复何如。
竹屏风扇抄遗事，柘步舆竿系隐书。
绛树实多分紫鹿，丹沙泉浅种红鱼。
东卿旄节看看至，静启茅斋慎扫除。','',''),('quantangshi-34005','访寂上人不遇','皮日休','quantangshi','','卷34','何处寻云暂废禅，客来还寄草堂眠。
桂寒自落翻经案，石冷空消洗钵泉。
炉里尚飘残玉篆，龛中仍鏁小金仙。
须将二百签回去，得得支公恐隔年。','',''),('quantangshi-34006','顾道士亡弟子以束帛乞铭于余鲁望因赋戏赠日休奉和','皮日休','quantangshi','','卷34','师去东华却炼形，门人求我志金庭。
大椿枯后新为记，仙鹤亡来始有铭。
琼板欲刊知不朽，冰纨将受恐通灵。
君才莫叹无兹分，合注神玄劒解经。','',''),('quantangshi-34007','秋夕文宴得遥字','皮日休','quantangshi','','卷34','啼螿衰叶共萧萧，文宴无喧夜转遥。
高韵最宜题雪赞，逸才偏称和云谣。
风吹翠蜡应难刻，月照清香太易消。
无限玄言一杯酒，可能容得盖宽饶。','',''),('quantangshi-34008','南阳广文欲于荆襄卜居因而有赠','皮日休','quantangshi','','卷34','地脉从来是福乡，广文高致更无双。
青精饭熟云侵竈，白{衤劫}裘成雪溅窗。
度日竹书千万字，经冬术煎两三缸。
鲈鱼自是君家味，莫背松江忆汉江。','',''),('quantangshi-34009','寄毗陵魏处士朴','皮日休','quantangshi','','卷34','文籍先生不肯官，絮巾冲雪把鱼竿。
一堆方册为侯印，三级幽岩是将[坛]。
醉少最因吟月冷，瘦多偏为卧云寒。
兔皮衾暖篷舟稳，欲共谁游七里滩。','',''),('quantangshi-34010','初冬偶作寄南阳润卿','皮日休','quantangshi','','卷34','寓居无事入清冬，虽设樽罍酒半空。
白菊为霜翻带紫，苍苔因雨却成红。
迎潮预遣收鱼笱，防雪先教盖鹤笼。
唯待支硎最寒夜，共君披氅访林公。','',''),('quantangshi-34011','冬晓章上人院','皮日休','quantangshi','','卷34','山堂冬晓寂无闻，一句清言忆领军。
琥珀珠黏行处雪，椶榈箒扫卧来云。
松扉欲启如鸣鹤，石鼎初煎若聚蚊。
不是恋师终去晚，陆机茸内足毛羣。','',''),('quantangshi-34012','寄题镜岩周尊师所居','皮日休','quantangshi','','卷34','八十余年住镜岩，鹿皮巾下雪髟髟。
牀寒不奈云萦枕，经润何妨雨滴函。
饮涧猨回窥绝洞，缘梯人歇倚危杉。
如何计吏穷于鸟，欲望仙都举一帆。','',''),('quantangshi-34013','寒夜文宴得泉字','皮日休','quantangshi','','卷34','分明竞襞七香牋，王郎风姿尽列仙。
盈箧共开华顶药，满瓶同坼惠山泉。
蟹因霜重金膏溢，橘为风多玉脑鲜。
吟罢不知诗首数，隔林明月过中天。','',''),('quantangshi-34014','庚寅岁十一月新罗弘惠上人与本国同书请日休为灵鹫山周禅师碑将还以诗送之','皮日休','quantangshi','','卷34','三十麻衣弄渚禽，岂知名字彻鸡林。
勒铭虽即多遗草，越海还能抵万金。
鲸鬣晓掀峰正烧，鳌睛夜没岛还阴。
二千余字终天别，东望辰韩泪洒襟。','',''),('quantangshi-34015','送润卿博士还华阳','皮日休','quantangshi','','卷34','雪打篷舟离酒旗，华阳居士半酣归。
逍遥只恐逢云将，恬澹真应降月妃。
仙市鹿胎如锦嫩，阴宫燕肉似酥肥。
公车草合蒲轮坏，争不教他白日飞。','',''),('quantangshi-34016','寒日书斋即事三首 一','皮日休','quantangshi','','卷34','参佐三间似草堂，恬然无事可成忙。
移时寂历烧松子，尽日殷勤拂乳牀。
将近道斋先衣褐，欲清诗思更焚香。
空庭好待中宵月，独礼星辰学步罡。','',''),('quantangshi-34017','寒日书斋即事三首 二','皮日休','quantangshi','','卷35','不知何事有生涯，皮褐亲裁学道家。
深夜数瓯唯柏叶，清晨一器是云华。
盆池有鹭窥苹沫，石版无人扫桂花。
江汉欲归应未得，夜来频梦赤城霞。','',''),('quantangshi-34018','寒日书斋即事三首 三','皮日休','quantangshi','','卷35','方朔家贫未有车，肯从荣利舍樵渔。
从公未怪多侵酒，见客唯求转借书。
暂听松风生意足，偶看溪月世情疎。
如钩得贵非吾事，合向烟波为五鱼。','',''),('quantangshi-34019','腊后送内大德从勖游天台','皮日休','quantangshi','','卷35','讲散重云下九天，大君恩赐许随缘。
霜中一钵无辞乞，湖上孤舟不废禅。
梦入琼楼寒有月，行过石树冻无烟他时瓜镜知何用，吴越风光满御筵。','',''),('quantangshi-34020','寄题玉霄峰叶涵象尊师所居','皮日休','quantangshi','','卷35','青冥向上玉霄峰，元始先生戴紫蓉。
晓案琼文光洞壑，夜坛香气惹杉松。
闲迎仙客来为鹤，静噀灵符去是龙。
子细扪心无偃骨，欲随师去肯相容。','',''),('quantangshi-34021','奉和鲁望寄南阳广文次韵','皮日休','quantangshi','','卷35','春彩融融释冻塘，日精闲咽坐岩房。
琼函静启从猨覰，金液初开与鹤尝。
八会旧文多搭写，七真遗语剩思量。
不知梦到为何处，红药满山烟月香。','',''),('quantangshi-34022','题支山南峰僧','皮日休','quantangshi','','卷35','云侵坏衲重隈肩，不下南峰不记年。
池里羣鱼曾受戒，林间孤鹤欲参禅。
鸡头竹上开危径，鸭脚花中擿废泉。
无限吴都堪赏事，何如来此看师眠。','',''),('quantangshi-34023','送董少卿游茅山','皮日休','quantangshi','','卷35','名卿风度足杓斜，一舸闲寻二许家。
天影晓通金井水，山灵深护玉门沙。
空坛礼后销香母，阴洞缘时触乳花。
尽待于公作廷尉，不须从此便餐霞。','',''),('quantangshi-34024','酬鲁望见迎绿罽次韵','皮日休','quantangshi','','卷35','轻裁鸭绿任金刀，不怕西风断野蒿。
酬赠既无青玉案，纤华犹欠赤霜袍。
烟披怪石难同逸，竹映仙禽未胜高。
成后料君无别事，只应酣饮咏离骚。','',''),('quantangshi-34025','寄怀南阳润卿','皮日休','quantangshi','','卷35','鹿门山下捕鱼郎，今向江南作渴羌。
无事只陪看藕样，有钱唯欲买湖光。
醉来浑忘移花处，病起空闻焙药香。
何事对君犹有愧，一篷冲雪返华阳。','',''),('quantangshi-34026','鲁望悯承吉之孤为诗序邀予属和欲用予道振其孤而利之噫承吉之困身后乎鲁望视予困与承吉生前孰若哉未有已困而能振人者抑为之辞用塞良友','皮日休','quantangshi','','卷35','先生清骨葬烟霞，业破孤存孰为嗟。
几箧诗编分贵位，一林石笋散豪家。
儿过旧宅啼枫影，姬绕荒田泣稗花。
唯我共君堪便戒，莫将文誉作生涯。','',''),('quantangshi-34027','寄润卿博士','皮日休','quantangshi','','卷35','高眠可为要玄纁，鹊尾金炉一世焚。
尘外乡人为许掾，山中地主是茅君。
将收芝菌唯防雪，欲晒图书不奈云。
若使华阳终卧去，汉家封禅用谁文。','',''),('quantangshi-34028','奉和鲁望白菊','皮日休','quantangshi','','卷35','已过重阳半月天，琅华千点照寒烟。
蘂香亦似浮金靥，花样还如镂玉钱。
玩影冯妃堪比艳，炼形萧史好争妍。
无由擿向牙箱里，飞上方诸赠列仙。','',''),('quantangshi-34029','华亭鹤闻之旧矣及来吴中以钱半千得一只养之殆经岁不幸为饮啄所误经夕而卒悼之不已遂继以诗南阳润卿博士浙东德师侍御毗陵魏不琢处士东吴陆鲁望秀才及厚于予者悉寄之请垂见和','皮日休','quantangshi','','卷35','池上低摧病不行，谁教仙魄反层城。
阴苔尚有前朝迹，皎月新无昨夜声。
菰米正残三日料，筠笼休碍九霄程。
不知此恨何时尽，遇着云泉即怆情。','',''),('quantangshi-34030','伤开元观顾道士','皮日休','quantangshi','','卷35','协晨宫上启金扉，诏使先生坐蜕归。
鹤有一声应是哭，丹无余粒恐潜飞。
烟凄玉笥封云篆，月惨琪花葬羽衣。
肠断雷平旧游处，五芝无影草微微。','',''),('quantangshi-34031','醉中即席赠润卿博士','皮日休','quantangshi','','卷35','适越游吴一散仙，银瓶玉柄两翛然。
茅山顶上携书簏，笠泽心中漾酒船。
桐木布温吟倦后，桃花饭熟醉醒前。
谢安四十余方起，犹自高闲得数年。','',''),('quantangshi-34032','偶留羊振文先辈及一二文友小饮日休以眼病初平不敢饮酒遣侍密欢因成四韵','皮日休','quantangshi','','卷35','谢庄初起恰花晴，强侍红筵不避觥。
久断杯盂华盖喜，忽闻歌吹谷神惊。
䙰褷正重新开柳，呫嗫难通乍啭莺。
犹有僧虔多蜜炬，不辞相伴到天明。','',''),('quantangshi-34033','奉送浙东德师侍御罢府西归','皮日休','quantangshi','','卷35','建安才子太微仙，暂上金台许二年。
形影欲归温室树，梦魂犹傍越溪莲。
空将海月为京信，尚使樵风送酒船。
从此受恩知有处，免为伧鬼恨吴天。','',''),('quantangshi-34034','送羊振文先辈往桂阳归觐','皮日休','quantangshi','','卷35','桂阳新命下彤墀，彩服行当欲雪时。
登第已闻传禰赋，问安犹听讲韩诗。
竹人临水迎符节，风母穿云避信旗。
无限湘中悼骚恨，凭君此去谢江蓠。','',''),('quantangshi-34035','褚家林亭','皮日休','quantangshi','','卷35','广亭遥对旧娃宫，竹岛萝溪委曲通。
茂苑楼台低槛外，太湖鱼鸟彻池中。
萧疎桂影移茶具，狼籍苹花上钓筒。
争得共君来此住，便披鹤氅对清风。','',''),('quantangshi-34036','送圆载上人归日本国','皮日休','quantangshi','','卷35','讲殿谈余着赐衣，椰帆却返旧禅扉。
贝多纸上经文动，如意瓶中佛爪飞。
飓母影边持戒宿，波神宫里受斋归。
家山到日将何入，白象新秋十二围。','',''),('quantangshi-34037','重送','皮日休','quantangshi','','卷35','云涛万里最东头，射马台深玉署秋。
无限属城为躶国，几多分界是亶州。
取经海底开龙藏，诵咒空中散蜃楼。
不奈此时贫且病，乘桴直欲伴师游。','',''),('quantangshi-34038','润卿遗青䭀饭兼之一绝聊用答谢','皮日休','quantangshi','','卷35','传得三元䭀饭名，大宛闻说有仙卿。
分泉过屋舂青稻，拂雾彯衣折紫茎。
蒸处不教双鹤见，服来唯怕五云生。
草堂空坐无饥色，时把金津漱一声。','',''),('quantangshi-34039','鸳鸯二首 一','皮日休','quantangshi','','卷35','双丝绢上为新样，连理枝头是故园。
翠浪万回同过影，玉沙千处共栖痕。
若非足恨佳人魄，即是多情年少魂。
应念孤飞争别宿，芦花萧瑟雨黄昏。','',''),('quantangshi-34040','鸳鸯二首 二','皮日休','quantangshi','','卷35','钿𨯥雕镂费深功，舞妓衣边绣莫穷。
无日不来湘渚上，有时还在镜湖中。
烟浓共拂芭蕉雨，浪细双游菡萏风。
应笑豪家鹦鹉伴，年年徒被锁金笼。','',''),('quantangshi-34041','伤小女','皮日休','quantangshi','','卷35','一岁犹未满，九泉何太深。
唯余卷书草，相对共伤心。','',''),('quantangshi-34042','秋江晓望','皮日休','quantangshi','','卷35','万顷湖天碧，一星飞鹭白。
此时放怀望，不厌为浮客。','',''),('quantangshi-34043','闲夜酒醒','皮日休','quantangshi','','卷35','醒来山月高，孤枕羣书里。
酒渴漫思茶，山童呼不起。','',''),('quantangshi-34044','和鲁望风人诗三首 一','皮日休','quantangshi','','卷35','刻石书离恨，因成别后悲。
莫言春茧薄，犹有万重思。','',''),('quantangshi-34045','和鲁望风人诗三首 二','皮日休','quantangshi','','卷35','镂出容刀饰，亲逢巧笑难。
日中骚客佩，争奈即阑干。','',''),('quantangshi-34046','和鲁望风人诗三首 三','皮日休','quantangshi','','卷35','江上秋声起，从来浪得名。
逆风犹挂席，若不会凡情。','',''),('quantangshi-34047','古函关','皮日休','quantangshi','','卷35','破落古关城，犹能扼帝京。
今朝行客过，不待晓鸡鸣。','',''),('quantangshi-34048','聪明泉','皮日休','quantangshi','','卷35','一勺如琼液，将愚拟望贤。
欲知心不变，还似饮贪泉。','',''),('quantangshi-34049','史处士','皮日休','quantangshi','','卷35','山期须早赴，世累莫迟留。
忽遇狂风起，闲心不自由。','',''),('quantangshi-34050','芳草渡','皮日休','quantangshi','','卷35','溪南越乡音，古柳渡江深。
日晚无来客，闲船系绿阴。','',''),('quantangshi-34051','古宫词三首 一','皮日休','quantangshi','','卷35','楼殿倚明月，参差如乱峰。
宫花半夜发，不待景阳钟。','',''),('quantangshi-34052','古宫词三首 二','皮日休','quantangshi','','卷35','闲骑小步马，独遶万年枝。
尽日看花足，君王自不知。','',''),('quantangshi-34053','古宫词三首 三','皮日休','quantangshi','','卷35','玉枕寐不足，宫花空触檐。
梁间燕不睡，应怪夜明帘。','',''),('quantangshi-34054','春日陪崔谏议樱桃园宴','皮日休','quantangshi','','卷35','万树香飘水麝风，蜡熏花雪尽成红。
夜深欢态状不得，醉客图开明月中。','',''),('quantangshi-34055','松江早春','皮日休','quantangshi','','卷35','松陵清净雪消初，见底新安恐未如。
稳凭船舷无一事，分明数得鲙残鱼。','',''),('quantangshi-34056','女坟湖','皮日休','quantangshi','','卷35','万贵千奢已寂寥，可怜幽愤为谁娇。
须知韩重相思骨，直在芙蓉向下消。','',''),('quantangshi-34057','泰伯庙','皮日休','quantangshi','','卷35','一庙争祠两让君，几千年后转清[芬]。
当时尽解称高义，谁敢教他莽卓闻。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34058','宿木兰院','皮日休','quantangshi','','卷35','木兰院里双栖鹤，长被金钲聒不眠。
今夜宿来还似尔，到明无计梦云泉。','',''),('quantangshi-34059','重题蔷薇','皮日休','quantangshi','','卷35','浓似猩猩初染素，轻如燕燕欲凌空。
可怜细丽难胜日，照得深红作浅红。','',''),('quantangshi-34060','春夕酒醒','皮日休','quantangshi','','卷35','四弦才罢醉蛮奴，酃醁余香在翠炉。
夜半醒来红蜡短，一枝寒泪作珊瑚。','',''),('quantangshi-34061','青门闲泛','皮日休','quantangshi','','卷35','青翰虚徐夏思清，愁烟漠漠荇花平。
醉来欲把田田叶，尽裹当时醒酒鲭。','',''),('quantangshi-34062','木兰后池三咏 重台莲花','皮日休','quantangshi','','卷35','欹红婑媠力难任，每叶头边半米金。
可得教他水妃见，两重元是一重心。','',''),('quantangshi-34063','木兰后池三咏 浮萍','皮日休','quantangshi','','卷35','嫩似金脂扬似烟，多情浑欲拥红莲。
明朝拟附南风信，寄与湘妃作翠钿。','',''),('quantangshi-34064','木兰后池三咏 白莲','皮日休','quantangshi','','卷35','但恐醍醐难并洁，秖应薝卜可齐香。
半垂金粉知何似，静婉临溪照额黄。','',''),('quantangshi-34065','重题后池','皮日休','quantangshi','','卷35','细雨阑珊眠鹭觉，钿波悠漾并鸳娇。
适来会得荆王意，秖为莲茎重细腰。','',''),('quantangshi-34066','庭中初植松桂鲁望偶题奉和次韵','皮日休','quantangshi','','卷35','毵毵绿髪垂轻露，猎猎丹华动细风。
恰似青童君欲会，俨然相向立庭中。','',''),('quantangshi-34067','鲁望戏题书印囊奉和次韵','皮日休','quantangshi','','卷35','金篆方圆一寸余，可怜银艾未思渠。
不知夫子将心印，印破人间万卷书。','',''),('quantangshi-34068','馆娃宫怀古五绝 一','皮日休','quantangshi','','卷35','绮合飘香下太湖，乱兵侵晓上姑苏。
越王大有堪羞处，秖把西施赚得吴。','',''),('quantangshi-34069','馆娃宫怀古五绝 二','皮日休','quantangshi','','卷35','郑妲无言下玉墀，夜来飞箭满罘罳。
越王定指高台笑，却见当时金镂楣。','',''),('quantangshi-34070','馆娃宫怀古五绝 三','皮日休','quantangshi','','卷35','半夜娃宫作战场，血腥犹杂宴时香。
西施不及烧残蜡，犹为君王泣数行。','',''),('quantangshi-34071','馆娃宫怀古五绝 四','皮日休','quantangshi','','卷35','素袜虽遮未掩羞，越[兵]犹怕伍员头。
吴王恨魄今如在，只合西施濑上游。','',''),('quantangshi-34072','馆娃宫怀古五绝 五','皮日休','quantangshi','','卷35','响屧廊中金玉步，采苹山上绮罗身。
不知水葬今何处，溪月弯弯欲效颦。','',''),('quantangshi-34073','虎丘寺西小溪闲泛三绝 一','皮日休','quantangshi','','卷35','鼓子花明白石岸，桃枝竹覆翠岚溪。
分明似对天台洞，应厌顽仙不肯迷。','',''),('quantangshi-34074','虎丘寺西小溪闲泛三绝 二','皮日休','quantangshi','','卷35','绝壑秖怜白羽傲，穷溪唯觉锦鳞痴。
