庞公乐幽隐，辟聘无所就。
祗爱鹿门泉，泠泠倚岩漱。
孔明卧龙者，潜伏躬耕耨。
忽遭玄德云，遂起鳞角鬬。
三胡节皆峻，二习名亦茂。
其余文武家，相望如斥堠。
缅思齐梁降，寂寞寡清胄。
凝融为漪澜，复结作莹琇。
不知粹和气，有得方大受。
将生皮夫子，上帝可其奏。
并包数公才，用以殿厥后。
尝闻儿童岁，嬉戏陈俎豆。
积渐开词源，一派分万溜。
先崇丘旦室，大惧隳结构。
次补荀孟垣，所贵亡罅漏。
仰瞻三皇道，虮虱在宇宙。
却视五霸图，股掌弄孩幼。
或能醢髋髀，或与翼雏鷇。
或喜掉直舌，或乐斩邪脰。
或耨锄翳荟，或整理错谬。
或如百千骑，合沓原野狩。
又如晓江平，风死波不皱。
幽埋力须掘，遗落赀必购。
乃于文学中，十倍猗顿富。
囊乏向咸镐，马重迟步骤。
专场射策时，缚虎当羿彀。
归来把通籍，且作高堂寿。
未足逞戈矛，谁云被文绣。
从知偶东下，帆影拂吴岫。
物象悉摧藏，精灵畏雕镂。
伊余抱沈疾，顦顇守圭窦。
方推洪范畴，更念大玄首。
陈诗采风俗，学古穷篆籀。
朝朝贳薪米，往往逢责诟。
既被邻里轻，亦为妻子陋。
持冠适瓯越，敢怨不得售。
窘若晒沙鱼，悲如哭霜狖。
唯君枉车辙，以逐海上臭。
披襟两相对，半夜忽白昼。
执热濯清风，忘忧饮醇酎。
驱为文翰侣，驽皂参骥廐。
有时谐宫商，自喜真邂逅。
道孤情易苦，语直诗还瘦。
藻匠如见酬，终身致怀袖。','',''),('quantangshi-34143','袭美先辈以龟蒙所献五百言既蒙见和复示荣唱至于千字提奖之重蔑有称实再抒鄙怀用伸酬谢','陸龜蒙','quantangshi','','卷35','洪范分九畴，转成天下规。
河图孕八卦，焕作玄中奇。
先开否臧源，次筑经纬基。
粤若鲁圣出，正当周德衰。
越疆必载质，历国将扶危。
诸侯恣崛强，王室方陵迟。
歌凤时不偶，获麟心益悲。
始嗟吾道穷，竟使空言垂。
首赞五十易，又删三百诗。
遂令篇籍光，可竝日月姿。
向非笔削功，未必无瑕疵。
迨至夫子没，微言散如枝。
所宗既不同，所得亦异宜。
名法在深刻，虚玄至希夷。
自从战伐来，一派纵横驰。
寒谷生艳木，沸潭结流澌。
惊奔失壮士，好恶随纤儿。
嬴氏并六合，势尊丞相斯。
加于挟书律，尽取坑焚之。
南勒会稽颂，北恢胡亥阺。
犹怀徧巡狩，不暇亲维持。
及汉文景后，鸿生方鎃摫。
簸扬尧舜风，反作三代吹。
飘颻四百载，左右为藩篱。
邺下曹父子，猎贤甚熊罴。
发论若霞驳，裁诗如锦摛。
徐王应刘辈，头角咸相衰。
或有妙绝赏，或为独步推。
或许润色美，或嫌诋诃痴。
倏以中利病，且非混醇醨。
雅当乎魏文，丽矣哉陈思。
不肯少选妄，恐贻后世嗤。
吾祖仗才力，革车蒙虎皮。
手持一白旄，直向文场麾。
轻若脱钳釱，豁如抽扊扅。
精钢不足利，騕褭何劳追。
大可罩山岳，微堪析毫厘。
十体免负赘，百家咸起痿。
争入鬼神奥，不容天地私。
一篇迈华藻，万古无孑遗。
刻鹄尚未已，雕龙奋而为。
刘生吐英辩，上下穷高卑。
下臻宋与齐，上指轩从羲。
岂但标八索，殆将包两仪。
人谣洞野老，骚怨明湘累。
立本以致诘，驱宏来抵隵。
清如朔雪严，缓若春烟羸。
或欲开户牖，或将饰缨緌。
虽非倚天劒，亦是囊中锥。
皆由内史意，致得东莞词。
梁元尽索虏，后主终亡隋。
哀音但浮脆，岂望分雄雌。
吾唐揖让初，陛列森咎夔。
作颂媲吉甫，直言过祖伊。
明皇践中日，墨客肩参差。
岳净秀擢削，海寒光陆离。
皆能取穴凤，尽拟乘云螭。
迩来二十祀，俊造相追随。
余生落其下，亦值文明时。
少小不好弄，逡巡奉弓箕。
虽然苦贫贱，未省亲嚅㖇。
秋倚抱风桂，晓烹承露葵。
穷年只败袍，积日无晨炊。
远访卖药客，闲寻捕鱼师。
归来蠹编上，得以含情窥。
抗韵吟比雅，覃思念棿攡。
因知昭明前，剖石呈清琪。
又嗟昭明后，败叶埋芳蕤。
纵有月旦评，未能天下知。
徒为强貔豹，不免参狐狸。
谁蹇行地足，谁抽刺天鬐。
谁作河畔草，谁为洞中芝。
谁若灵囿鹿，谁犹清庙牺。
谁轻如鸿毛，谁密如凝脂。
谁比蜀严静，谁方巴賨赀。
谁能钓拚鳌，谁能灼神龟。
谁背如水火，谁同若埙篪。
谁可作梁栋，谁敢驱谷蠡。
用此常不快，无人动交铍。
空消病里骨，枉白愁中髭。
鹿门先生才，大小无不怡。
就彼六籍内，说诗直解颐。
顾我迷未远，开怀溃其疑。
初开凿本源，渐乃疏旁支。
邃古派泛滥，皇朝光赫曦。
揣摩是非际，一一如襟期。
李杜气不易，孟陈节难移。
信知君子言，可竝神明蓍。
枯腐尚求律，膏肓犹谒医。
况将太牢味，见啖逋悬饥。
今来置家地，正枕吴江湄。
饵薄钩不曲，跫然守空坻。
嘿坐无影响，唯君欵茅茨。
抽书乱签帙，酌茗烦瓯㰕。
或伴补缺砌，或偕诣荒祠。
孤筇倚烟蔓，细木横风漪。
触雨妨扉屦，临流泥江蓠。
既狎野人调，甘为豪士訾。
不敢负建鼓，唯忧掉降旗。
希君念余勇，挽袖登文陴。','',''),('quantangshi-34144','奉酬袭美先辈吴中苦雨一百韵','陸龜蒙','quantangshi','','卷35','微生参最灵，天与意绪拙。
人皆机巧求，百迳无一达。
家为唐臣来，奕世唯稷卨。
只垂青白风，凛凛自贻厥。
犹残赐书在，编简苦断绝。
其间忠孝字，万古光不灭。
孱孙诚瞢昧，有志常搰搰。
敢云嗣良弓，但欲终守节。
喧哗不入耳，谗佞不挂舌。
仰咏尧舜言，俯遵周孔辙。
所贪既仁义，岂暇理生活。
纵有旧田园，抛来亦芜没。
因之成否塞，十载真契阔。
冻骭一襜褕，饥肠少糠籺。
甘心付天壤，委分任回斡。
笠泽卧孤云，桐江钓明月。
盈筐盛芡芰，满釜煮鲈鳜。
酒帜风外㩻，茶枪露中撷。
歌谣非大雅，捃摭为小说。
上可补熏茎，傍堪跐芽蘖。
方当卖罾罩，尽以易纸札。
踪迹尚吴门，梦魂先魏阙。
寻闻天子诏，赫怒诛叛卒。
宵旰悯烝黎，谟明问征伐。
王师虽继下，贼垒未即拔。
此时淮海波，半是生人血。
霜戈驱少壮，败屋叶羸耋。
践蹋比尘埃，焚烧同稿秸。
吾皇自神圣，执事皆间杰。
射策亦何为，春卿遂聊辍。
伊余将贡技，未有耻可刷。
却问渔樵津，重耕烟雨墢。
诸侯急兵食，冗剩方翦截。
不可抱词章，巡门事干谒。
归来阖蓬楗，壁立空竖褐。
暖手抱孤烟，披书向残雪。
幽忧和愤懑，忽愁自惊蹶。
文兮乏寸毫，武也无尺铁。
平生所韬蓄，到死不开豁。
念此令人悲，翕然生内热。
加之被皲瘃，况复久藜粝。
既为霜露侵，一卧增百疾。
筋骸将束缚，腠理如棰挞。
初谓抵狂貙，又如当毒蝎。
江南多事鬼，巫觋连瓯粤。
可口是妖讹，恣情专赏罚。
良医只备位，药肆或虚设。
而我正萎痿，安能致诃咄。
椒兰任芳苾，精粣从罗列。
盏斝既屡倾，钱刀亦随爇。
兼之凟财贿，不止行盗窃。
天地如有知，微妖岂逃杀。
其时心力愤，益使气息惙。
永夜更呻吟，空牀但皮骨。
君来赞贤牧，野鹤聊簪笏。
谓我同光尘，心中有溟渤。
轮蹄相压至，问遗无虚月。
首到春鸿蒙，犹残病根茇。
看花虽眼晕，见酒忘肺渴。
隐几还自怡，逢卢亦争喝。
抽毫更唱和，劒戟相磨戛。
何大不包罗，何微不挑刮。
今来值霖雨，昼夜无暂歇。
杂若碎渊沦，高如破轇轕。
何劳鼍吼岸，讵要鹳鸣垤。
祗意江海翻，更愁山岳裂。
初惊蚩尤阵，虎豹争搏啮。
又疑伍胥涛，蛟蜃相蹙拶。
千家蒙瀑练，忽似好披拂。
万瓦垂玉绳，如堪取萦结。
况余居低下，本是蛙蚓窟。
迩来增号呼，得以恣唐突。
先夸屋舍好，又恃头角凸。
厚地虽直方，身能徧穿穴。
常参庄辩里，亦造扬玄末。
偃仰纵无机，形容且相忽。
低头增叹诧，到口复嗢咽。
沮洳渍琴书，莓苔染巾袜。
解衣换仓粟，秕稗犹未脱。
饥鸟屡窥临，泥僮苦舂䑔。
或闻秋稼穑，大半沈澎汃。
耕父蠹齐民，农夫思旱魃。
吾观天之意，未必洪水割。
且要虐飞龙，又图滋跛鼈。
三吴明太守，左右皆儒哲。
有力即扶危，怀仁过救暍。
鹿门皮夫子，气调真俊逸。
截海上云鹰，横空下霜鹘。
文坛如命将，可以持玉钺。
不独扆羲轩，便当城老佛。
顾余为山者，所得才篑撮。
譬如饰箭材，尚欠镞与筈。
闲将歈儿唱，强倚帝子瑟。
幸得远潇湘，不然嗤贾屈。
开缄窥宝肆，玑贝光比栉。
朗咏冲乐悬，陶匏响铿擖。
古来愁霖赋，不是不清越。
非君顿挫才，沴气难摧折。
驰情扣虚寂，力尽无所掇。
不足谢徽音，祗令凋鬓髪。','',''),('quantangshi-34145','奉酬袭美先辈初夏见寄次韵','陸龜蒙','quantangshi','','卷35','积雨晦臯圃，门前烟水平。
苹蘅增遥吹，枕席分余清。
村斾诧酒美，赊来满鋞程。
未必减宣子，何羡谢公荣。
借宅去人远，败墙连古城。
愁鸱占枯枿，野鼠趋前楹。
昨日云破损，晚林先觉晴。
幽篁倚微照，碧粉含疎茎。
蠹简有遗字，㪇琴无泛声。
蚕寒茧尚薄，燕喜雏新成。
览物正摇思，得君初夏行。
诚明复散诞，化匠安能争。
海浪刷三岛，天风吹六英。
洪崖领玉节，坐使虚音生。
吾祖傲洛客，因言几为伧。
末裔实渔者，敢怀干墨卿。
唯思钓璜老，遂得持竿情。
何须乞鹅炙，岂在斟羊羹。
畦蔬与瓮醁，便可相携迎。
蟠木几甚曲，笋皮冠且轻。
闲心放羁靮，醉脚从欹倾。
一迳有余远，一窗有余明。
秦皇苦不达，天下何足并。','',''),('quantangshi-34146','奉和袭美二游诗 徐诗','陸龜蒙','quantangshi','','卷35','尝闻四书曰，经史子集焉。
苟非天禄中，此事无由全。
自从秦火来，历代逢迍邅。
汉祖入关日，萧何为政年。
尽力取图籍，遂持天下权。
中兴熹平时，教化还相宣。
立石刻五经，置于太学前。
贼卓乱王室，君臣如转圜。
洛阳且煨烬，载籍宜为烟。
逮晋武革命，生民才息肩。
惠怀亟寡昧，戎羯俄腥膻。
已觉天地闭，竞为东南迁。
日既不暇给，坟索何由专。
尔后国脆弱，人多尚虚玄。
任学者得谤，清言者为贤。
直至沈范辈，始家藏简编。
御府有不足，仍令就之传。
梁元渚宫日，尽取如蚳蝝。
兵威忽破碎，焚爇无遗篇。
近者隋后主，搜罗势骈阗。
宝函映玉轴，彩翠明霞鲜。
伊唐受命初，载史声连延。
砥柱不我助，惊波涌沦涟。
遂令因去书，半在余浮泉。
贞观购亡逸，蓬瀛渐周旋。
炅然东壁光，与月争流天。
伟矣开元中，王道真平平。
八万五千卷，一一皆涂铅。
人间盛传写，海内奔穷研。
目云西斋书，有过东臯田。
吾闻徐氏子，奕世皆才贤。
因知遗孙谋，不[在]黄金钱。
插架几万轴，森森若戈鋋。
风吹签牌声，满室铿锵然。
佳哉鹿门子，好问如除㾓。
倏来参卿处，遂得参卿怜。
开怀展橱簏，唯在性所便。
素业已千仞，今为峻云巅。
雄才旧百派，相近浮日川。
君抱王佐图，纵步凌陶甄。
他时若报德，谁在参卿先。','',''),('quantangshi-34147','奉和袭美二游诗 任诗','陸龜蒙','quantangshi','','卷35','吴之辟疆园，在昔胜概敌。
前闻富修竹，后说纷怪石。
风烟惨无主，载祀将六百。
草色与行人，谁能问遗迹。
不知清景在，尽付任君宅。
却是五湖光，偷来傍檐隙。
出门向城路，车马声躏跞。
入门望亭隈，水木气岑寂。
犨墙绕曲岸，势似行无极。
十步一危梁，乍疑当绝壁。
池容澹而古，树意苍然僻。
鱼惊尾半红，鸟下衣全碧。
斜来岛屿隐，恍若潇湘隔。
雨静挂残丝，烟消有余脉。
朅来任公子，摆落名利役。
虽将禄代耕，颇爱巾随策。
秋笼支遁鹤，夜榻戴颙客。
说史足为师，谭禅差作伯。
君多鹿门思，到此情便适。
偶荫桂堪帷，纵吟苔可席。
顾余真任诞，雅遂中心获。
但知醉还醒，岂知玄尚白。
甘闲在鸡口，不贵封龙额。
即此自怡神，何劳谢公屐。','',''),('quantangshi-34148','次追和清远道士诗韵','陸龜蒙','quantangshi','','卷35','一代先后贤，声容剧河汉。
况兹迈古士，复历苍崖窜。
辰经几十万，邈与灵寿翫。
海岳尚推移，都鄙固芜漫。
羸僧下高阁，独鸟没远岸。
啸初风雨来，吟余钟呗乱。
如何炼精魄，万祀忽欲半。
宁为断臂忧，肯作秋柏散。
吾闻酆宫内，日月自昏旦。
左右修文郎，纵横洒篇翰。
斯人久冥漠，得不垂慨叹。
庶或有神交，相从重兴赞。','',''),('quantangshi-34149','补沈恭子诗','陸龜蒙','quantangshi','','卷35','灵质贯轩昊，遐年越商周。
自然失远裔，安得怨寡俦。
我亦小国胤，易名慙见优。
虽非放旷怀，雅奉逍遥游。
携手桂枝下，属词山之幽。
风雨一以过，林麓飒然秋。
落日倚石壁，天寒登古丘。
荒泉已无夕，败叶翳不流。
乱翠缺月隐，衰红清露愁。
览物性未逸，反为情所囚。
异才偶绝境，佳藻穷冥搜。
虚倾寂寞音，敢作杂佩酬。','',''),('quantangshi-34150','读阴符经寄鹿门子','陸龜蒙','quantangshi','','卷35','清晨整冠坐，朗咏三百言。
备识天地意，献词犯干坤。
何事不隐德，降灵生轩辕。
口衔造化斧，凿破机关门。
五贼忽迸逸，万物争崩奔。
虚施神仙要，莫救华池源。
但学战胜术，相高甲兵屯。
龙蛇竞起陆，鬬血浮中原。
成汤与周武，反覆更为尊。
下及秦汉得，黩弄兵亦烦。
奸强自林据，仁弱无枝蹲。
狂喉恣吞噬，逆翼争飞翻。
家家伺天发，不肯匡淫昏。
生民坠涂炭，比屋为冤魂。
祗为读此书，大朴难久存。
微臣与轩辕，亦是万世孙。
未能穷意义，岂敢求瑕痕。
曾亦爱两句，可与贤达论。
生者死之根，死者生之根。
方寸了十字，万化皆胚腪。
身外更何事，眼前徒自喧。
黄河但东注，不见归昆仑。
昼短苦夜永，劝君倾一尊。','',''),('quantangshi-34151','奉和袭美初夏游楞伽精舍次韵','陸龜蒙','quantangshi','','卷35','吴都涵汀洲，碧液浸郡郭。
微雨荡春醉，上下一清廓。
奇踪欲探讨，灵物先瘵瘼。
飘然兰叶舟，旋倚烟霞泊。
吟谭乱篙橹，梦寐杂巘崿。
纤情不可逃，洪笔难暂阁。
岂知楞伽会，乃在山水箔。
金仙着书日，世界名极乐。
薝卜冠诸香，琉璃代华垩。
禽言经不辍，象口川宁涸。
万善峻为城，巉巉捍羣恶。
清晨欲登造，安得无自愕。
险穴骇坤牢，高萝挂天笮。
池容澹相向，蛟怪如可摸。
苔蔽石髓根，蒲差水心锷。
岚侵答摩髻，日照狻猊络。
仰首乍眩旋，回眸更辉㸌。
檐端凝飞羽，磴外浮碧落。
到回解风襟，临幽濯云屩。
尘机性非便，静境心所着。
自取海鸥知，何烦尸祝酢。
峯围震泽岸，翠浪舞绡幕。
潋滟岂尧遭，㟞嵃非禹凿。
潜听钟梵处，别有松桂壑。
霭重灯不光，泉寒网犹薄。
僮能蹑孤刹，鸟惯亲摐铎。
服道身可遗，乞闲心已诺。
人间亦何事，万态相毒蠚。
战垒竞高深，儒衣谩褒博。
宣尼名位达，未必春秋作。
管氏包霸图，须人解其缚。
伊余采樵者，蓬藋方索寞。
近得风雅情，聊将圣贤度。
多君富遒采，识度两清恪。
讵宠生灭词，肯教夷夏错。
未为尧舜用，且向烟霞托。
我亦摆尘埃，他年附鸿鹤。','',''),('quantangshi-34152','奉和袭美公斋四咏次韵 小松','陸龜蒙','quantangshi','','卷35','擢秀逋客岩，遗根飞鸟迳。
因求饰清閟，遂得辞危敻。
贞同柏有心，立若珠无胫。
枝形短未怪，鬣数差难定。
况密三天风，方遵四时柄。
那兴培塿叹，免答邻里病。
微霜静可分，片月疎堪映。
奇当虎头笔，韵叶通明性。
会拂阳乌胸，抡才膺帝命。','',''),('quantangshi-34153','奉和袭美公斋四咏次韵 小桂','陸龜蒙','quantangshi','','卷35','讽赋轻八植，擅名方一枝。
才高不满意，更自寒山移。
宛宛别云态，苍苍出尘姿。
烟归助华杪，雪点迎芳蕤。
青条坐可结，白日如奔螭。
谅无𠠜翦忧，即是萧森时。
洛浦虽有荫，骚人聊自怡。
终为济川檝，岂在论高卑。','',''),('quantangshi-34154','奉和袭美公斋四咏次韵 新竹','陸龜蒙','quantangshi','','卷35','别坞破苔藓，严城树轩楹。
恭闻禀璇玑，化质离青冥。
色可定鸡颈，实堪招凤翎。
立窥五岭秀，坐对三都屏。
晴月窈窕入，曙烟霏微生。
昔者尚借宅，况来处宾庭。
金罍纵倾倒，碧露还鲜醒。
若非抱苦节，何以偶惟馨。
徐观穉龙出，更赋锦苞零。','',''),('quantangshi-34155','奉和袭美公斋四咏次韵 鹤屏','陸龜蒙','quantangshi','','卷35','时人重花屏，独即胎化状。
丛毛练分彩，疎节筇相望。
曾无氃氋态，颇得连轩样。
势拟抢高寻，身犹在函丈。
如忧鸡鹜鬬，似忆烟霞向。
尘世任纵横，霜襟自闲放。
空资明远思，不待浮丘相。
何由振玉衣，一举栖瀛阆。','',''),('quantangshi-34156','奉和袭美酬前进士崔潞盛制见寄因赠至一百四十言','陸龜蒙','quantangshi','','卷35','孔圣铸颜事，垂之千载余。
其间王道乖，化作荆榛墟。
天必授贤哲，为时攻翦除。
轲雄骨已朽，百代徒趦趄。
近者韩文公，首为闲辟锄。
夫子又继起，阴霾终廓如。
搜得万古遗，裁成十编书。
南山盛云雨，东序堆琼琚。
偶此真籍客，悠扬两情摅。
清词忽窈窕，雅韵何虚徐。
唱既野芳坼，酬还天籁疎。
轻波掠翡翠，晓露披芙渠。
俪曲信寡合，末流难嗣初。
空持一竿饵，有意鲸鱼。','',''),('quantangshi-34157','奉和袭美太湖诗二十首 初入太湖','陸龜蒙','quantangshi','','卷35','东南具区雄，天水合为一。
高帆大弓满，羿射争箭疾。
时当暑雨后，气象仍郁密。
乍如开雕笯，耸翅忽飞出。
行将十洲近，坐觉八极溢。
耳目骇鸿蒙，精神寒佶栗。
坑来斗呀豁，涌处惊嵳崒。
嶮异拔龙湫，喧如破蛟室。
斯须风妥帖，若受命平秩。
微茫诚端倪，远峤疑格笔。
巉巉见铜阙，左右皆辅弼。
盘空俨相趋，去势犹横逸。
尝闻咸池气，下注作清质。
至今涵赤霄，尚且浴白日。
又云构浮玉，宛与昆阆匹。
肃为灵官家，此事难致诘。
才迎沙屿好，指顾俄已失。
山川互蔽亏，鱼鸟空聱耴。
何当授真检，得召天吴术。
一一问朝宗，方应可谭悉。','',''),('quantangshi-34158','奉和袭美太湖诗二十首 晓次神景宫','陸龜蒙','quantangshi','','卷35','晓帆逗崎岸，高步入神景。
洒洒襟袖清，如临蘂珠屏。
虽然羣动息，此地常寂静。
翠镊有寒锵，碧花无定影。
凭轩羽人傲，夹户天兽猛。
稽首朝元君，褰衣就虚省。
呀空雪牙利，嗽水石齿冷。
香母未垂婴，芝田不论顷。
遥通河汉口，近抚松桂顶。
饭荐七白蔬，杯酾九光杏。
人间附尘躅，固陋真钳颈。
肯信拚鳌倾，犹疑夏虫永。
玄津荡琼垄，紫汞啼金鼎。
尽出冰霜书，期君一披省。','',''),('quantangshi-34159','奉和袭美太湖诗二十首 入林屋洞','陸龜蒙','quantangshi','','卷35','知名十小天，林屋当第九。
题之为左神，理之以天后。
魁堆辟邪辈，左右专备守。
自非方瞳人，不敢窥洞口。
唯君好奇士，复啸忘情友。
致伞在风林，低冠入云窦。
中深剧苔井，傍坎才药臼。
石角忽支颐，藤根时束肘。
初为大幽怖，渐见微明诱。
屹若造灵封，森如达仙薮。
尝闻白芝秀，状与琅花偶。
又坐紫泉光，甘如酌天酒。
何人能挹嚼，饵以代浆糗。
却笑探五符，徒劳步双斗。
真君不可见，焚盥空迟久。
眷恋玉碣文，行行但回首。','',''),('quantangshi-34160','奉和袭美太湖诗二十首 雨中游包山精舍','陸龜蒙','quantangshi','','卷35','包山信神仙，主者上真职。
及栖钟梵侣，又是清凉域。
乃知烟霞地，绝俗无不得。
岩开一迳分，柏拥深殿黑。
僧闲若图画，像古非雕刻。
海客施明珠，湘蕤料净食。
有鱼皆玉尾，有乌尽金臆。
手携鞞铎佉，若在中印国。
千峰残雨过，万籁清且极。
此时空寂心，可以遗智识。
知君战未胜，尚倚功名力。
却下听经徒，孤帆有行色。','',''),('quantangshi-34161','奉和袭美太湖诗二十首 毛公坛','陸龜蒙','quantangshi','','卷35','古有韩终道，授之刘先生。
身如碧凤皇，羽翼披轻轻。
先生盛驱役，臣伏甲与丁。
势可倒五岳，不唯鞭羣灵。
飘颻驾翔螭，白日朝太清。
空遗古坛在，稠叠烟萝屏。
远怀步罡夕，列宿森然明。
四角镇露兽，三层差羽婴。
回眸盼七炁，运足驰疎星。
象外真既感，区中道俄成。
迩来向千祀，云峤空峥嵘。
石上橘花落，石根瑶草青。
时时白鹿下，此外无人行。
我访岑寂境，自言斋戒精。
如今君安死，魂魄犹膻腥。
有芨皆绿字，有芝皆紫茎。
相将望瀛岛，浩荡凌沧溟。','',''),('quantangshi-34162','奉和袭美太湖诗二十首 三宿神景宫','陸龜蒙','quantangshi','','卷35','灵踪未徧寻，不觉溪色瞑。
回头问栖所，稍下杉萝迳。
岩居更幽绝，涧户相隐映。
过此即神宫，虚堂惬云性。
四轩尽疎达，一榻何清零。
仿髴闻玉笙，鼓铿动凉磬。
风凝古松粒，露压修荷柄。
万籁既无声，澄明但心听。
希微辨真语，若授虚皇命。
尺宅按来平，华池漱余净。
频窥宿羽丽，三吸晨霞盛。
岂独冷衣襟，便堪遗造请。
徒深物外趣，未脱尘中病。
举首谢灵峰，徜徉事归榜。','',''),('quantangshi-34163','奉和袭美太湖诗二十首 以毛公泉献大谏清河公','陸龜蒙','quantangshi','','卷35','先生炼飞精，羽化成翩翻。
荒坛与古甃，隐轸清泠存。
四面蹙山骨，中心含月魂。
除非紫水脉，即是金沙源。
香实洒桂蘂，甘惟渍云根。
向来探幽人，酌罢祛蒙昏。
况公圭璋质，近处谏诤垣。
又闻虚静姿，早挂冰雪痕。
君对瑶华味，重献兰薰言。
当应涤烦暑，朗咏翚飞轩。
我愿得一掬，攀天呌重阍。
霏霏散为雨，用以移焦原。','',''),('quantangshi-34164','奉和袭美太湖诗二十首 缥缈峰','陸龜蒙','quantangshi','','卷35','左右皆跳岑，孤峰挺然起。
因思缥缈称，乃在虚无里。
清晨跻磴道，便是孱颜始。
据石即更歌，遇泉还徙倚。
花奇忽如荐，树曲浑成几。
乐静烟霭知，忘机猨狖喜。
频攀峻过斗，末造平如砥。
举首阂青冥，回眸聊下视。
高帆大于鸟，广墠才类蚁。
就此微茫中，争先未尝已。
葛洪话刚气，去地四千里。
苟能乘之游，止若道路耳。
吾将自峰顶，便可朝帝扆。
尽欲活羣生，不唯私一己。
超骑明月蜍，复弄华星蘂。
却下蓬莱巅，重窥清浅水。
身为大块客，自号天随子。
他日向华阳，敲云问名氏。','',''),('quantangshi-34165','奉和袭美太湖诗二十首 桃花坞','陸龜蒙','quantangshi','','卷35','行行问绝境，贵与名相亲。
空经桃花坞，不见秦时人。
愿此为东风，吹起枝上春。
愿此作流水，潜浮蘂中尘。
愿此为好鸟，得栖花际邻。
愿此作幽蝶，得随花下宾。
朝为照花日，暮作涵花津。
试为探花士，作此偷桃臣。
桃源不我弃，庶可全天真。','',''),('quantangshi-34166','奉和袭美太湖诗二十首 明月湾','陸龜蒙','quantangshi','','卷35','昔闻明月观，祗伤荒野基。
今逢明月湾，不值三五时。
择此二明月，洞庭看最奇。
连山忽中断，远树分毫厘。
周回二十里，一片澄风漪。
见说秋半夜，净无云物欺。
兼之星斗藏，独有神仙期。
初闻锵镣跳，积渐调参差。
空中卓羽卫，波上停龙螭。
踪舞玉烟节，高歌碧霜词。
清光悄不动，万象寒咿咿。
此会非俗致，无由得旁窥。
但当乘扁舟，酒瓮仍相随。
或彻三弄笛，或成数联诗。
自然莹心骨，何用神仙为。','',''),('quantangshi-34167','奉和袭美太湖诗二十首 练渎','陸龜蒙','quantangshi','','卷35','越恃君子众，大将压全吴。
吴将派天泽，以练舟师徒。
一镜止千里，支流忽然迂。
苍匳朿洪波，坐似冯夷躯。
战舰百万辈，浮宫三十余。
平川盛丁宁，绝岛分储胥。
凤押半鹤膝，锦杠杂肥胡。
香烟与杀气，浩浩随风驱。
弹射尽高鸟，杯觥醉潜鱼。
山灵恐见鞭，水府愁为墟。
兵利德日削，反为雠国屠。
至今钩镞残，尚与泥沙俱。
照此月倍苦，来兹烟亦孤。
丁魂尚有泪，合洒青枫枯。','',''),('quantangshi-34168','奉和袭美太湖诗二十首 投龙潭','陸龜蒙','quantangshi','','卷35','名山潭洞中，自古多祕邃。
君将接神物，聊用申祀事。
镕金象牙角，尺木无不备。
亦既奉真官，因之徇前志。
持来展明诰，敬以投嘉瑞。
鳞光焕水容，目色烧山翠。
吾皇病秦汉，岂独探幽异。
所贵风雨时，民皆受其赐。
良田为巨浸，污泽成赤地。
掌职一不行，精灵又何寄。
唯贪血食饱，但据骊珠睡。
何必费黄金，年年授星使。','',''),('quantangshi-34169','奉和袭美太湖诗二十首 孤园寺','陸龜蒙','quantangshi','','卷35','浮屠从西来，事者极梁武。
岩幽与水曲，结构无遗土。
穷山林干尽，竭海珠玑聚。
况即侍从臣，敢爱烟波坞。
幡条玉龙扣，殿角金虬舞。
释子厌楼台，生人露风雨。
今来四百载，像设藏云浦。
轻鸽乱驯鸥，鸣钟和朝橹。
庭蕉裂旗斾，野蔓差缨组。
石上解空人，窗前听经虎。
林虚叶如织，水净沙堪数。
徧问得中天，归修释迦谱。','',''),('quantangshi-34170','奉和袭美太湖诗二十首 上真观','陸龜蒙','quantangshi','','卷35','尝闻升三清，真有上中下。
官居乘佩服，一一自相亚。
霄裙或霞粲，侍女忽玉姹。
坐进金碧腴，去驰飙歘驾。
今来上真观，恍若心灵讶。
祗恐暂神游，又疑新羽化。
风余撼朱草，云破生瑶榭。
望极觉波平，行虚信烟藉。
闲开飞龟帙，静倚宿凤架。
俗状既能遗，尘冠聊以卸。
人间方大火，此境无朱夏。
松盖荫日车，泉绅垂天罅。
穷幽不知倦，复息芝园舍。
锵佩引凉姿，焚香礼遥夜。
无情走声利，有志依闲暇。
何处好迎僧，希将石楼借。','',''),('quantangshi-34171','奉和袭美太湖诗二十首 销夏湾','陸龜蒙','quantangshi','','卷35','霞岛焰难泊，云峰奇未收。
萧条千里湾，独自清如秋。
古岸过新雨，高萝荫横流。
遥风吹蒹葭，折处鸣飕飕。
昔予守圭窦，过于回禄囚。
日为蘧筁徒，分作祗裯雠。
愿狎寒水怪，不封朱毂侯。
岂知烟浪涯，坐可思重裘。
健若数尺鲤，泛然双白鸥。
不识号火井，孰问名焦丘。
我真鱼鸟家，尽室营扁舟。
遗名复避世，消夏还消忧。','',''),('quantangshi-34172','奉和袭美太湖诗二十首 包山祠','陸龜蒙','quantangshi','','卷35','静境林麓好，古祠烟霭浓。
自非通灵才，敢陟羣仙峰。
百里波浪沓，中堂箫鼓重。
真君具琼舆，仿髴来相从。
清露濯巢鸟，阴云生昼龙。
风飘橘柚香，日动幡盖容。
将命礼且洁，所祈年不凶。
终当以疏闻，特用诸侯封。','',''),('quantangshi-34173','奉和袭美太湖诗二十首 圣姑庙','陸龜蒙','quantangshi','','卷35','渺渺洞庭水，盈盈芳屿神。
因知古佳丽，不独湘夫人。
流苏荡遥吹，斜领生轻尘。
蜀彩驳霞碎，吴绡盘雾匀。
可怜飞燕姿，合是乘鸾宾。
坐想烟雨夕，兼知花草春。
空登油壁车，窈窕谁相亲。
好赠玉条脱，堪携紫纶巾。
殷勤拨香池，重荐汀洲苹。
明朝动兰檝，不翅星河津。','',''),('quantangshi-34174','奉和袭美太湖诗二十首 太湖石','陸龜蒙','quantangshi','','卷35','他山岂无石，厥状皆可荐。
端然遇良工，坐使天质变。
或裁基栋宇，礧砢成广殿。
或剖出温瑜，精光具华瑱。
或将破仇敌，百礮资苦战。
或用镜功名，万古如会面。
今之洞庭者，一以非此选。
槎牙真不才，反作天下彦。
所奇者嵌崆，所尚者葱蒨。
旁穿参洞穴，内窍均环钏。
刻削九琳窗，玲珑五明扇。
新雕碧霞段，旋破秋天片。
无力置池塘，临风只流眄。','',''),('quantangshi-34175','奉和袭美太湖诗二十首 崦里','陸龜蒙','quantangshi','','卷35','山横路若绝，转檝逢平川。
川中水木幽，高下兼良田。
沟塍堕微溜，桑柘含疎烟。
处处倚蚕箔，家家下鱼筌。
呆犊卧新𦬻，野禽争折莲。
试招搔首翁，共语残阳边。
今来九州内，未得皆恬然。
贼阵始吉语，狂波又凶年。
吾翁欲何道，守此常安眠。
笑我掉头去，芦中闻刺船。
余知隐地术，可以齐真仙。
终当从之游，庶复全于天。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34176','奉和袭美太湖诗二十首 石板','陸龜蒙','quantangshi','','卷35','一片倒山屏，何时隳洞门。
屹然空阔中，万古波涛痕。
我意上帝命，持来压泉源。
恐为庚辰官，囚怪力所掀。
又疑广袤次，零落潜惊奔。
不然遭霹雳，强半沈无垠。
如何造化首，便截秋云根。
往事不足问，奇踪安可论。
吾今病烦暑，据簟常昏昏。
欲从石公乞，莹理平如璊。
前后植桂桧，东西置琴尊。
尽携天壤徒，浩唱羲皇言。','',''),('quantangshi-34177','杂讽九首 一','陸龜蒙','quantangshi','','卷35','红蚕缘枯桑，青茧大如瓮。
人争捩其臂，羿矢亦不中。
微微待贤禄，一一希入梦。
纵操上吉言，口噤难即贡。
蛟龙在怒水，拔取牙角弄。
丹穴如可游，家家畜孤凤。
凶门尚儿戏，战血波澒溶。
社鬼苟有灵，谁能遏秋恸。','',''),('quantangshi-34178','杂讽九首 二','陸龜蒙','quantangshi','','卷35','童麋来触犀，德力不相及。
伊无惬心事，祗有碎首泣。
况将鹏虱校，数又百与十。
攻如饿鸱呌，势若脱兔急。
斯为朽关键，怒荦抉以入。
年来横干戈，未见拔城邑。
得非佐饔者，齿齿待啜汁。
羁维豪杰辈，四骇方少絷。
此皆乘时利，纵舍在呼吸。
吾欲斧其吭，无雷动幽蛰。','',''),('quantangshi-34179','杂讽九首 三','陸龜蒙','quantangshi','','卷35','𪃿鹅惨于冰，陆立怀所适。
斯人道仍閟，不得不呜呃。
当时布衣士，亦作天子客。
至今东方生，满口自夸白。
终为万乘交，谈笑无所隔。
致君非有书，乃是尧舜画。
祗今侯门峻，日扫贫贱迹。
朝趋九韶音，暮列五鼎食。
如闻恭俭语，謇謇事夕惕。
可拍伊牧肩，功名被金石。','',''),('quantangshi-34180','杂讽九首 四','陸龜蒙','quantangshi','','卷35','赤舌可烧城，谗邪易为伍。
诗人疾之甚，取俾投豺虎。
长风吹窾木，始有音韵吐。
无木亦无风，笙簧由喜怒。
女娲炼五石，天缺犹可补。
当其利口衔，罅漏不复数。
元精遗万类，双目如牖户。
非是既相参，重瞳亦为瞽。','',''),('quantangshi-34181','杂讽九首 五','陸龜蒙','quantangshi','','卷35','东南有狂兕，猎者西北矢。
利尘白冥冥，独此清夜止。
无人语其事，偶坐窥天纪。
安得东壁明，洪洪用坟史。
搜扬好古士，一以罄云水。
流堪洒菁英，风足去稗秕。
如能出奇计，坐可平贼垒。
徐陈羲皇道，高驾太平轨。
攫疏成特雄，濯垢为具美。
贡贤当上赏，景福视所履。
永播南熏音，垂之万年耳。','',''),('quantangshi-34182','杂讽九首 六','陸龜蒙','quantangshi','','卷35','有蘖何青青，空城雪霜里。
千林尽枯槁，苦节独不死。
他遭匠石顾，总入牺黄美。
遂得保天年，私心未为耻。
高从宿枭怪，下亦容蝼蚁。
大厦若抡材，亭亭托君子。','',''),('quantangshi-34183','杂讽九首 七','陸龜蒙','quantangshi','','卷35','左右佩劒者，彼此亦相笑。
趋时与闭门，喧寂不同调。
潜机取声利，自许臻乎妙。
志士以神窥，惭然真可吊。
天之发遐籁，大小随万窍。
魁其罏冶姿，形质惟所召。
鼗笙磬竽瑟，是必登清庙。
伊圣不可欺，谁能守蓬藋。','',''),('quantangshi-34184','杂讽九首 八','陸龜蒙','quantangshi','','卷35','横笛喝秋风，清商入疏越。
君居不夜城，肯怨孤戍月。
吴兵甚犀利，太白光突兀。
日已费千金，厪闻侵一拨。
岂无恶年少，纵酒游侠窟。
募为敢死军，去以枭叛卒。
岂无中林士，贯穿学问骨。
兵法五十家，浩荡如溟渤。
高悬鹿皮睡，清涧时依樾。
分已诺烟霞，全遗事干谒。
既非格猛兽，未可轻华髪。
北面师其谋，几能止征伐。
何妨秦堇勇，又有曹刿说。
尧舜尚询刍，公乎听无忽。','',''),('quantangshi-34185','杂讽九首 九','陸龜蒙','quantangshi','','卷35','朝为壮士歌，暮为壮士歌。
壮士心独苦，傍人谓之何。
古铁久不快，倚天无处磨。
将来易水上，犹足生寒波。
捷可搏飞狖，健能超槖駞。
羣儿被坚利，索手安冯河。
惊飙扫长林，直木谢𬄭科。
严霜冻大泽，僵龙不如蛇。
昔者天血碧，吾徒安叹嗟。','',''),('quantangshi-34186','美人','陸龜蒙','quantangshi','','卷35','美人抱瑶瑟，哀怨弹别鹤。
雌雄南北飞，一旦异栖托。
谅非金石性，安得宛如昨。
生为竝蒂花，亦有先后落。
秋林对斜日，光景自相薄。
犹欲悟君心，朝朝佩兰若。','',''),('quantangshi-34187','感事','陸龜蒙','quantangshi','','卷35','将军被鲛函，祗畏金石镞。
岂知谗箭利，一中成赤族。
古来信簧舌，巧韵凄锵曲。
君闻悦耳音，尽日听不足。
初因起毫髪，渐可离骨肉。
所以贤达心，求人须任目。','',''),('quantangshi-34188','素丝','陸龜蒙','quantangshi','','卷35','园客丽独茧，诗人吟五緵。
如何墨子泪，反以悲途穷。
我意岂如是，愿参天地功。
为线补君衮，为弦系君桐。
左右修阙职，宫商还古风。
端然洁白心，可与神明通。','',''),('quantangshi-34189','次幽独君韵 一','陸龜蒙','quantangshi','','卷35','灵气独不死，尚能成绮文。
如何孤窆里，犹自读三坟。','',''),('quantangshi-34190','次幽独君韵 二','陸龜蒙','quantangshi','','卷35','落日送万古，秋声含七哀。
枯株不萧瑟，枝干虚崔嵬。
伊昔临大道，歌钟醉高台。
台今已平地，祗有春风回。
明月白草死，积阴荒陇推。
圣贤亦如此，恸绝真悠哉。','',''),('quantangshi-34191','赠远','陸龜蒙','quantangshi','','卷35','芙蓉匣中镜，欲照心还嬾。
本是细腰人，别来罗带缓。
从君出门后，不奏云和管。
妾思冷如簧，时时望君暖。
心期梦中见，路永魂梦短。
怨坐泣西风，秋窗月华满。','',''),('quantangshi-34192','村夜二篇 一','陸龜蒙','quantangshi','','卷35','江上冬日短，裴回草堂暝。
鸿当绝塞来，客向孤村病。
緜緜起归念，咽咽兴微咏。
菊迳月方高，橘斋霜已并。
盘飱蔬粟粗，史籍签牌盛。
目冷松桂寒，耳喧儿女竞。
开瓶浮蚁绿，试笔秋毫劲。
昼户亦重关，寒屏递相映。
诗从骚雅得，字向铅椠正。
遇敌舞蛇矛，逢谈捉犀柄。
无名升甲乙，有志扶荀孟。
守道希昔贤，为文通古圣。
幽忧废长劒，顦顇惭清镜。
祗会鱼鸟情，讵知时俗性。
浮虚多徇势，老嬾图历聘。
既不务人知，空余乐天命。
吾家在田野，家事苦辽敻。
耕稼一以微，囷仓自然罄。
愁襟风叶乱，独坐灯花迸。
明发成浩歌，谁能少倾听。','',''),('quantangshi-34193','村夜二篇 二','陸龜蒙','quantangshi','','卷35','世既贱文章，归来事耕稼。
伊人着农道，我亦赋田舍。
所悲劳者苦，敢用词为诧。
祗効刍牧言，谁防轻薄駡。
嘻今居宠禄，各自矜雄霸。
堂上考华钟，门前竚高驾。
纤洪动丝竹，水陆供鲙炙。
小雨静楼台，微风动兰麝。
吹嘘川可倒，眄睐花争奼。
万户膏血穷，一筵歌舞价。
安知勤播植，卒岁无闲暇。
种以春鳸初，获从秋隼下。
专专望穜稑，搰搰条桑柘。
日晏腹未充，霜繁体犹躶。
平生守仁义，所疾唯狙诈。
上诵周孔书，沈溟至酣籍。
岂无致君术，尧舜不上下。
岂无活国方，颇牧齐教化。
蛟龙任干死，云雨终不借。
羿臂束如囚，徒劳夸善射。
才能诮箕斗，辩可移嵩华。
若与虻辈量，饥寒殆相亚。
长吟倚清瑟，孤愤生遥夜。
自古有遗贤，吾容偏称谢。','',''),('quantangshi-34194','记事','陸龜蒙','quantangshi','','卷35','本作渔钓徒，心将遂疎放。
苦为饥寒累，未得恣闲畅。
去年十二月，身住霅溪上。
病里贺丰登，鸡豚聊馈饷。
巍峩卞山雪，凝冽不可向。
瘦骨倍加寒，徒为厚缯纩。
晴来露青霭，千仞缺寻丈。
卧恐玉华销，时时推枕望。
虽然营卫困，亦觉精神王。
把笔强题诗，粗言环怪状。
吴兴郑太守，文律颇清壮。
凤尾与鲸牙，纷披落杂唱。
缄书寄城内，搪突无以况。
料峭采莲船，纵横簸天浪。
方倾谢公酒，忽值庄生丧。
默默阻音徽，临风但惆怅。
春归迨秋末，固自婴微恙。
岁晏弗躬亲，何由免欺诳。
今来观刈获，乃在松江并。
门外两潮过，波澜光荡漾。
都缘新卜筑，是事皆草创。
尔后如有年，还应惬微尚。
天高气味爽，野迥襟怀旷。
感物动牢愁，愤时频肮脏。
平生乐篇翰，至老安敢忘。
骏骨正牵盐，玄文终覆酱。
嗟今多赤舌，见善惟蔽谤。
忖度大为防，涵容宽作量。
图书筐簏外，关眼皆剩长。
饿隶亦胜无，薄田家所仰。
稍离饥寒患，学古真可强。
圣道庶经营，世途多踉跄。
近闻天子诏，复许私酝酿。
促使舂酒材，呼儿具盆盎。
宵长拥吟褐，日晏开书幌。
我醉卿可还，陶然似元亮。','',''),('quantangshi-34195','孤雁','陸龜蒙','quantangshi','','卷35','我生天地间，独作南宾雁。
哀鸣慕前侣，不免饮啄晏。
虽蒙小雅咏，未脱鱼网患。
况是婚礼须，忧为弋者篡。
晴鸢争上下，意气苦凌慢。
吾常吓鸳雏，尔辈安足讪。
回头语晴鸢，汝食腐鼠惯。
无异驽骀羣，恋短豆皂栈。
岂知潇湘岸，葭菼苹萍间。
有石形状奇，寒流古来湾。
闲看麋鹿志，了不忧刍豢。
世所重巾冠，何妨野夫丱。
骚人夸蕙芷，易象取陆苋。
漆园逍遥篇，中亦载斥鷃。
汝惟材性下，嗜好不可谏。
身虽慕高翔，粪壤是盻盼。
或闻通鬼魅，怪祟立可辩。
硩蔟书尚存，宁容恣妖幻。','',''),('quantangshi-34196','南泾渔父','陸龜蒙','quantangshi','','卷35','予方任疎慵，地僻即所好。
江流背村落，偶往心已嫪。
田家相去远，岑寂且纵傲。
出户手先筇，见人头未帽。
南泾有渔父，往往携稚造。
问其所以渔，对我真蹈道。
我初簎鱼鼈，童丱至于耄。
窟穴与生成，自然通壶奥。
孜孜戒吾属，天物不可暴。
大小参去留，候其孳养报。
终朝获鱼利，鱼亦未常耗。
同覆天地中，违仁辜覆焘。
余观为政者，此意谅难到。
民皆死搜求，莫肯兴愍悼。
今年川泽旱，前岁山源潦。
牒诉已盈庭，闻之类禽噪。
譬如死鸡鹜，岂不容乳抱。
孟子讥宋人，非其揠苗躁。
吾嘉渔父旨，雅叶贤哲操。
倘遇采诗官，斯文诚敢告。','',''),('quantangshi-34197','引泉诗','陸龜蒙','quantangshi','','卷35','上嗣位六载，吾宗刺桐川。
余来拜旌戟，诏下之明年。
是时春三月，绕郭花蝉联。
岚盘百万髻，上插黄金钿。
授以道士馆，置榻于东偏。
满院声碧树，空堂形老仙。
本性乐凝淡，及来更虚玄。
焚香礼真像，盥手披灵编。
新定山角角，乌龙独巉然。
除非净晴日，不见苍崖巅。
上有拏云峰，下有喷壑泉。
泉分数十汊，落处皆峥潺。
寒声入烂醉，聒破西窗眠。
支筇起独寻，祗在墙东边。
呼童具畚锸，立凿莓苔穿。
灇淙一派堕，练带横斜牵。
乱石抛落落，寒流响溅溅。
狂奴七里濑，缩到疎楹前。
跳花泼半散，涌沫飞旋圆。
势束三峡挂，泻危孤磴悬。
曾闻瑶池溜，亦灌朱草田。
凫伯弄翠蘂，鸾雏舞丹烟。
凌风捩桂柂，隔雾驰犀船。
况当玄元家，尝着道德篇。
上善可比水，斯文参五千。
精灵若在此，肯恶微波传。
不拟争滴沥，还应会沦涟。
出门复飞箭，合势浮青天。
必有学真子，鹿冠秋鹤颜。
如能辅余志，日使疏其源。','',''),('quantangshi-34198','纪梦游甘露寺','陸龜蒙','quantangshi','','卷35','昔卧嵩高云，云窗正寒夕。
披裘忽生梦，似到空王宅。
峨天一峰立，栏楯横半壁。
级倚绿巅差，关临赤霄辟。
扪虚陟孤峭，不翅千余尺。
叠掌望罘罳，分明袒肩释。
凌香稽首罢，嘹哓□□□。
高户乘北风，声号大波白。
光中目难送，定验方可觌。
树细鸿蒙烟，岛疎零落碧。
须臾羣籁入，空水相喷激。
积浪亚寒堆，呀如鬬危石。
跳音簇鞞鼓，溅沫交矛戟。
鸟疾帆亦奔，纷纷助劲敌。
思非水灵怒，即是饥龙擘。
怯慑不敢前，荷襟汗霑霢。
回经定僧处，泉木光相射。
岩磴云族栖，柖柯露华适。
逍遥得真趋，逦迤寻常迹。
山腹贮孤亭，岚根四垂帟。
谁题雪月句，乃是曹刘格。
阆阙一枝琼，边楼数声笛。
吟高矍然起，若自苍旻掷。
短烛堕余花，圆蟾挂斜魄。
自从神锡境，无处不登陟。
忽上南徐山，心期豁而获。
岂伊烦恼骨，合到清凉域。
暗得胡蝶身，幽期尽相识。
奈何有名氏，未列金闺籍。
翻慙丱顶童，得奉真如策。
云涛触风望，毫管和烟搦。
聊记梦中游，留之问禅客。','',''),('quantangshi-34199','惜花','陸龜蒙','quantangshi','','卷35','人寿期满百，花开唯一春。
其间风雨至，旦夕旋为尘。
若使花解愁，愁于看花人。','',''),('quantangshi-34200','别离','陸龜蒙','quantangshi','','卷35','丈夫非无泪，不洒离别间。
杖劒对尊酒，耻为游子颜。
蝮蛇一螫手，壮士即解腕。
所志在功名，离别何足叹。','',''),('quantangshi-34201','鸣雁行','陸龜蒙','quantangshi','','卷35','朔风动地来，吹起沙上声。
闺中有边思，玉筯此时横。
莫怕儿女恨，主人烹不鸣。','',''),('quantangshi-34202','短歌行','陸龜蒙','quantangshi','','卷35','爪牙在身上，陷穽犹可制。
爪牙在胸中，劒戢无所畏。
人言畏猛虎，谁是撩头弊。
祗见古来心，奸雄暗相噬。','',''),('quantangshi-34203','挟瑟歌','陸龜蒙','quantangshi','','卷35','挟瑟为君抚，君嫌声太古。
寥寥倚浪系，㗫㗫沈湘语。
赖有秋风知，清泠吹玉柱。','',''),('quantangshi-34204','婕妤怨','陸龜蒙','quantangshi','','卷35','妾貌非倾国，君王忽然宠。
南山掌上来，下敌新恩重。
后宫多窈窕，日日学新声。
一落君王耳，南山又须轻。','',''),('quantangshi-34205','江南曲','陸龜蒙','quantangshi','','卷35','为爱江南春，涉江聊采苹。
水深烟浩浩，空对双车轮。
车轮明月团，车盖浮云盘。
云月徒自好，水中行路难。
遥遥洛阳道，夹道生春草。
寄语棹船郎，莫夸风浪好。','',''),('quantangshi-34206','渔具诗 网','陸龜蒙','quantangshi','','卷35','大罟纲目繁，空江波浪黑。
沈沈到波底，恰共波同色。
牵时万鬐入，已有千钧力。
尚悔不横流，恐他人更得。','',''),('quantangshi-34207','渔具诗 罩','陸龜蒙','quantangshi','','卷35','左手揭圆罛，轻桡弄舟子。
不知潜鳞处，但去笼烟水。
时穿紫屏破，忽值朱衣起。
贵得不贵名，敢论鲂与鲤。','',''),('quantangshi-34208','渔具诗 𦊔','陸龜蒙','quantangshi','','卷35','有意烹小鲜，乘流驻孤棹。
虽然烦取舍，未肯求津要。
多为虾蚬误，已分䴔䴖笑。
寄语龙伯人，荒唐不同调。','',''),('quantangshi-34209','渔具诗 钓筒','陸龜蒙','quantangshi','','卷35','短短截筠光，悠悠卧江色。
蓬差樐相应，雨慢烟交织。
须臾中芳饵，迅疾如飞翼。
彼竭我还浮，君看不争得。','',''),('quantangshi-34210','渔具诗 钓车','陸龜蒙','quantangshi','','卷35','溪上持只轮，溪边指茅屋。
闲乘风水便，敢议朱丹毂。
高多倚衡惧，下有折轴速。
曷若载逍遥，归来卧云族。','',''),('quantangshi-34211','渔具诗 鱼梁','陸龜蒙','quantangshi','','卷35','能编似云薄，横绝清川口。
缺处欲随波，波中先置笱。
投身入笼槛，自古难飞走。
尽日水滨吟，殷勤谢渔叟。','',''),('quantangshi-34212','渔具诗 叉鱼','陸龜蒙','quantangshi','','卷35','春溪正含绿，良夜才参半。
持矛若羽轻，列烛如星烂。
伤鳞跳密藻，碎首沈遥岸。
尽族染东流，傍人作佳翫。','',''),('quantangshi-34213','渔具诗 射鱼','陸龜蒙','quantangshi','','卷35','弯弓注碧浔，掉尾行凉沚。
青枫下晚照，正在澄明里。
抨弦断荷扇，溅血殷菱蘂。
若使禽荒闻，移之暴烟水。','',''),('quantangshi-34214','渔具诗 鸣桹','陸龜蒙','quantangshi','','卷35','水浅藻荇涩，[钓]罩无所及。
铿如木铎音，势若金钲急。
敺之就深处，用以资俯拾。
搜罗尔甚微，遁去将何入。','',''),('quantangshi-34215','渔具诗 沪','陸龜蒙','quantangshi','','卷35','万植御洪波，森然倒林薄。
千颅咽云上，过半随潮落。
其间风信背，更值雷声恶。
天道亦裒多，吾将移海若。','',''),('quantangshi-34216','渔具诗 𥶠','陸龜蒙','quantangshi','','卷35','斩木置水中，枝条互相蔽。
寒鱼遂家此，自以为生计。
春冰忽融冶，尽取无遗裔。
所托成祸机，临川一凝睇。','',''),('quantangshi-34217','渔具诗 种鱼','陸龜蒙','quantangshi','','卷35','凿池收赬鳞，疎疎置云屿。
还同汗漫游，遂以江湖处。
如非一神守，潜被蛟龙主。
蛟龙若无道，跛鼈亦可御。','',''),('quantangshi-34218','渔具诗 药鱼','陸龜蒙','quantangshi','','卷35','香饵缀金钩，日中悬者几。
盈川是毒流，细大同时死。
不唯空饲犬，便可将贻蚁。
苟负竭泽心，其他尽如此。','',''),('quantangshi-34219','渔具诗 舴艋','陸龜蒙','quantangshi','','卷35','篷棹两三事，天然相与闲。
朝随穉子去，暮唱菱歌还。
倚石迟后侣，徐桡供远山。
君看万斛载，沈溺须臾间。','',''),('quantangshi-34220','渔具诗 笭箵','陸龜蒙','quantangshi','','卷35','谁谓笭箵小，我谓笭箵大。
盛鱼自足餐，置璧能为害。
时将刷苹浪，又取悬藤带。
不及腰上金，何劳问蓍蔡。','',''),('quantangshi-34221','奉和袭美添渔具五篇 渔庵','陸龜蒙','quantangshi','','卷35','结茅次烟水，用以资啸傲。
岂谓钓家流，忽同禅室号。
闲凭山叟占，晚有溪禽嫪。
华屋莫相非，各随吾所好。','',''),('quantangshi-34222','奉和袭美添渔具五篇 钓矶','陸龜蒙','quantangshi','','卷35','拣得白云根，秋潮未曾没。
坡陁坐鳌背，散漫垂龙髪。
持竿从掩雾，置酒复待月。
即此放神情，何劳适吴越。','',''),('quantangshi-34223','奉和袭美添渔具五篇 蓑衣','陸龜蒙','quantangshi','','卷35','山前度微雨，不废小涧渔。
上有青襏襫，下有新腒疎。
滴沥珠影泫，离披岚彩虚。
君看荷制者，不得安吾庐。','',''),('quantangshi-34224','奉和袭美添渔具五篇 箬笠','陸龜蒙','quantangshi','','卷35','朝携下枫浦，晚戴出烟艇。
冒雪或平檐，听泉时仄顶。
飙移霭然色，波乱危如影。
不识九衢尘，终年居下泂。','',''),('quantangshi-34225','奉和袭美添渔具五篇 背蓬','陸龜蒙','quantangshi','','卷35','敏手劈江筠，随身织烟壳。
沙禽固不知，钓伴犹初觉。
闲从翠微拂，静唱沧浪濯。
见说万山潭，渔童尽能学。','',''),('quantangshi-34226','樵人十咏 樵溪','陸龜蒙','quantangshi','','卷35','山高溪且深，苍苍但羣木。
抽条欲千尺，众亦疑朴𣙙。
一朝蒙翦伐，万古辞林麓。
若遇燎玄穹，微烟出云族。','',''),('quantangshi-34227','樵人十咏 樵家','陸龜蒙','quantangshi','','卷35','草木黄落时，比邻见相喜。
门当清涧尽，屋在寒云里。
山棚日才下，野竈烟初起。
所谓顺天民，唐尧亦如此。','',''),('quantangshi-34228','樵人十咏 樵叟','陸龜蒙','quantangshi','','卷35','自小即胼胝，至今凋鬓髪。
所图山褐厚，所爱山炉热。
不知冠盖好，但信烟霞活。
富贵如疾颠，吾从老岩穴。','',''),('quantangshi-34229','樵人十咏 樵子','陸龜蒙','quantangshi','','卷35','生自苍崖边，能谙白云养。
才穿远林去，已在孤峰上。
薪和野花束，步带山词唱。
日暮不归来，柴扉有人望。','',''),('quantangshi-34230','樵人十咏 樵径','陸龜蒙','quantangshi','','卷35','石脉青霭间，行行自幽绝。
方愁山缭绕，更值云遮截。
争推好林浪，共约归时节。
不似名利途，相期覆车辙。','',''),('quantangshi-34231','樵人十咏 樵斧','陸龜蒙','quantangshi','','卷35','淬砺秋水清，携持远山曙。
丁丁在前涧，杳杳无寻处。
巢倾鸟犹在，树尽猨方去。
授钺者何人，吾今易其虑。','',''),('quantangshi-34232','樵人十咏 樵担','陸龜蒙','quantangshi','','卷35','轻无斗储价，重则筋力绝。
欲下半岩时，忧襟两如结。
风高势还却，雪厚疑中折。
负荷诚独难，移之赠来哲。','',''),('quantangshi-34233','樵人十咏 樵风','陸龜蒙','quantangshi','','卷35','朝随早潮去，暮带残阳返。
向背得清飙，相追无近远。
采山一何迟，服道常苦蹇。
仙术信能为，年华未将晚。','',''),('quantangshi-34234','樵人十咏 樵火','陸龜蒙','quantangshi','','卷35','积雪报松坞，蠹根然草堂。
深炉与远烧，此夜仍交光。
或似坐奇兽，或如焚异香。
堪嗟宦游子，冻死道路傍。','',''),('quantangshi-34235','樵人十咏 樵歌','陸龜蒙','quantangshi','','卷35','纵调为野吟，徐徐下云磴。
因知负樵乐，不减援琴兴。
出林方自转，隔水犹相应。
但取天壤情，何求郢人称。','',''),('quantangshi-34236','奉和袭美酒中十咏 酒星','陸龜蒙','quantangshi','','卷35','万古醇酎气，结而成晶荧。
降为嵇阮徒，动与尊罍并。
不独祭天庙，亦应邀客星。
何当八月槎，载我游青冥。','',''),('quantangshi-34237','奉和袭美酒中十咏 酒泉','陸龜蒙','quantangshi','','卷35','初悬碧崖口，渐注青溪腹。
味既敌中山，饮宁拘一斛。
春疑浸花骨，暮若酣云族。
此地得封侯，终身持美禄。','',''),('quantangshi-34238','奉和袭美酒中十咏 酒篘','陸龜蒙','quantangshi','','卷35','山斋酝方熟，野童编近成。
持来欢伯内，坐使贤人清。
不待盎中满，旋供花下倾。
汪汪日可挹，未羡黄金籯。','',''),('quantangshi-34239','奉和袭美酒中十咏 酒牀','陸龜蒙','quantangshi','','卷35','六尺样何奇，溪边濯来洁。
糟深贮方半，石重流还咽。
闲移秋病可，偶听寒梦缺。
往往枕眠时，自疑陶靖节。','',''),('quantangshi-34240','奉和袭美酒中十咏 酒垆','陸龜蒙','quantangshi','','卷35','锦里多佳人，当垆自沽酒。
高低过反坫，大小随圆瓿。
数钱红烛下，涤器春江口。
若得奉君欢，十千求一斗。','',''),('quantangshi-34241','奉和袭美酒中十咏 酒楼','陸龜蒙','quantangshi','','卷35','百尺江上起，东风吹酒香。
行人落帆上，远树涵残阳。
凝睇复凝睇，一觞还一觞。
须知凭栏客，不醉难为肠。','',''),('quantangshi-34242','奉和袭美酒中十咏 酒旗','陸龜蒙','quantangshi','','卷35','摇摇倚青岸，远荡游人思。
风欹翠竹杠，雨澹香醪字。
才来隔烟见，已觉临江迟。
大斾非不荣，其如有王事。','',''),('quantangshi-34243','奉和袭美酒中十咏 酒尊','陸龜蒙','quantangshi','','卷35','黄金即为侈，白石又太拙。
斲得奇树根，中如老蛟穴。
时招山下叟，共酌林间月。
尽醉两忘言，谁能作天舌。','',''),('quantangshi-34244','奉和袭美酒中十咏 酒城','陸龜蒙','quantangshi','','卷35','何代驱生灵，筑之为酿地。
殊无甲兵守，但有糟浆气。
雉堞屹如狂，女墙低似醉。
必若据而争，先登仪狄氏。','',''),('quantangshi-34245','奉和袭美酒中十咏 酒乡','陸龜蒙','quantangshi','','卷35','谁知此中路，暗出虚无际。
广莫是邻封，华胥为附丽。
三杯闻古乐，伯雅逢遗裔。
自尔等荣枯，何劳问玄弟。','',''),('quantangshi-34246','添酒中六咏 酒池','陸龜蒙','quantangshi','','卷35','万斛输曲沼，千钟未为多。
残霞入醍齐，远岸澄白酇。
后土亦沈醉，奸臣空浩歌。
迩来荒淫君，尚得乘余波。','',''),('quantangshi-34247','添酒中六咏 酒龙','陸龜蒙','quantangshi','','卷35','铜雀羽仪丽，金龙光彩奇。
潜倾邺宫酒，忽作商庭漦。
若怒鳞甲赤，如酣头角垂。
君臣坐相灭，安用骄奢为。','',''),('quantangshi-34248','添酒中六咏 酒瓮','陸龜蒙','quantangshi','','卷35','候暖麴糵调，覆深苫盖净。
溢处每淋漓，沈来还濎滢。
常闻清凉酎，可养希夷性。
盗饮以为名，得非君子病。','',''),('quantangshi-34249','添酒中六咏 酒船','陸龜蒙','quantangshi','','卷35','昔人性何诞，欲载无穷酒。
波上任浮身，风来即开口。
荒唐意难遂，沈湎名不朽。
千古如比肩，问君能继不。','',''),('quantangshi-34250','添酒中六咏 酒枪','陸龜蒙','quantangshi','','卷35','景山实名士，所玩垂清尘。
尝作酒家语，自言中圣人。
奇器质含古，挫糟未应醇。
唯怀魏公子，即此飞觞频。','',''),('quantangshi-34251','添酒中六咏 酒杯','陸龜蒙','quantangshi','','卷35','叔夜傲天壤，不将琴酒疎。
制为酒中物，恐是琴之余。
一弄广陵散，又裁绝交书。
颓然掷林下，身世俱何如。','',''),('quantangshi-34252','奉和袭美茶具十咏 茶坞','陸龜蒙','quantangshi','','卷35','茗地曲隈回，野行多缭绕。
向阳就中密，背涧差还少。
遥盘云髻慢，乱簇香篝小。
何处好幽期，满岩春露晓。','',''),('quantangshi-34253','奉和袭美茶具十咏 茶人','陸龜蒙','quantangshi','','卷35','天赋识灵草，自然钟野姿。
闲来北山下，似与东风期。
雨后探芳去，云间幽路危。
唯应报春鸟，得共斯人知。','',''),('quantangshi-34254','奉和袭美茶具十咏 茶笋','陸龜蒙','quantangshi','','卷35','所孕和气深，时抽玉苕短。
轻烟渐结华，嫩蘂初成管。
寻来青霭曙，欲去红云暖。
秀色自难逢，倾筐不曾满。','',''),('quantangshi-34255','奉和袭美茶具十咏 茶籯','陸龜蒙','quantangshi','','卷35','金刀劈翠筠，织似波文斜。
制作自野老，携持伴山娃。
昨日鬬烟粒，今朝贮绿华。
争歌调笑曲，日暮方还家。','',''),('quantangshi-34256','奉和袭美茶具十咏 茶舍','陸龜蒙','quantangshi','','卷35','旋取山上材，架为山下屋。
门因水势斜，壁任岩隈曲。
朝随鸟俱散，暮与云同宿。
不惮采掇劳，祗忧官未足。','',''),('quantangshi-34257','奉和袭美茶具十咏 茶竈','陸龜蒙','quantangshi','','卷35','无突抱轻岚，有烟映初旭。
盈锅玉泉沸，满甑云芽熟。
奇香袭春桂，嫩色凌秋菊。
炀者若吾徒，年年看不足。','',''),('quantangshi-34258','奉和袭美茶具十咏 茶焙','陸龜蒙','quantangshi','','卷35','左右捣凝膏，朝昏布烟缕。
方圆随样拍，次第依层取。
山谣纵高下，火候还文武。
见说焙前人，时时炙花脯。','',''),('quantangshi-34259','奉和袭美茶具十咏 茶鼎','陸龜蒙','quantangshi','','卷35','新泉气味良，古铁形状丑。
那堪风雪夜，更值烟霞友。
曾过赬石下，又住清溪口。
且共荐臯卢，何劳倾斗酒。','',''),('quantangshi-34260','奉和袭美茶具十咏 茶瓯','陸龜蒙','quantangshi','','卷35','昔人谢塸埞，徒为妍词饰。
岂如圭璧姿，又有烟岚色。
光参筠席上，韵雅金罍侧。
直使于阗君，从来未尝识。','',''),('quantangshi-34261','奉和袭美茶具十咏 煮茶','陸龜蒙','quantangshi','','卷35','闲来松间坐，看煮松上雪。
时于浪花里，并下蓝英末。
倾余精爽健，忽似氛埃灭。
不合别观书，但宜窥玉札。','',''),('quantangshi-34262','置酒行','陸龜蒙','quantangshi','','卷35','落尘花片排香痕，阑珊醉露栖愁魂。
洞庭波色惜不得，东风领入黄金尊。
千筠掷毫春谱大，碧舞红啼相倡和。
安知寂寞西海头，青𥳇未垂孤凤饿。','',''),('quantangshi-34263','江湖散人歌','陸龜蒙','quantangshi','','卷35','江湖散人天骨奇，短髪搔来蓬半垂。
手提孤篁曳寒茧，口诵太古沧浪词。
词云太古万万古，民性甚野无风期。
夜栖止与禽兽杂，独自构架纵横枝。
因而称曰有巢氏，民共敬贵如君师。
当时只效乌鹊辈，岂是有意陈尊卑。
无端后圣穿凿破，一派前导千流随。
多方恼乱元气死，日使文字生奸欺。
圣人事业转销耗，尚有渔者存熙熙。
风波不独困一士，凡百器具皆能施。
罛疎沪腐鲈鳜脱，止失检驭无谗疵。
人间所谓好男子，我见妇女留须眉。
奴颜婢膝真乞丐，反以正直为狂痴。
所以头欲散，不散弁峩巍。
所以腰欲散，不散佩陆离。
行散任之适，坐散从倾欹。
语散空谷应，笑散春云披。
衣散单复便，食散酸醎宜。
书散浑真草，酒散甘醇醨。
屋散势斜直，树散行参差。
客散忘簪屦，禽散虚笼池。
物外一以散，中心散何疑。
不共诸侯分邑里，不与天子专隍陴。
静则守桑柘，乱则逃妻儿。
金镳贝带未尝识，白刃杀我穷生为。
或闻蕃将负恩泽，号令铁马如风驰。
大君年小丞相少，当轴自请都旌旗。
神锋悉出羽林仗，缋画日月蟠龙螭。
太宗基业甚牢固，小丑背叛当歼夷。
禁军近自肃宗置，抑遏辅国争雄雌。
必然大段剪凶逆，须召劲勇持军麾。
四方贼垒犹占地，死者暴骨生寒饥。
归来輙拟荷锄笠，诟吏已责租钱迟。
兴师十万一日费，不啻千金何以支。
祗今利口且箕敛，何暇俛首哀惸嫠。
均荒补败岂无术，布在方册撑颓隵。
冰霜襦袴易反掌，白面诸郎殊不知。
江湖散人悲古道，悠悠幸寄羲皇傲。
官家未议活苍生，拜赐江湖散人号。','',''),('quantangshi-34264','五歌 放牛','陸龜蒙','quantangshi','','卷35','江草秋穷似秋半，十角吴牛放江岸。
邻肩抵尾乍依隈，横去斜奔忽分散。
荒陂断堑无端入，背上时时孤鸟立。
日暮相将带雨归，田家烟火微茫湿。','',''),('quantangshi-34265','五歌 水鸟','陸龜蒙','quantangshi','','卷35','水鸟山禽虽异名，天工各与双翅翎。
雏巢吞啄即一例，游处高卑殊不停。
则有觜铍爪戟劲立直眎者，击搏挽裂图膻腥。
如此等色恣豪横，耸身往往凌青冥。
为人罗绊取材力，韦韝彩绶悬金铃。
三驱不以鸟捕鸟，矢下先得闻诸经。
超然可继义勇后，恰似有志行天刑。
鸥闲鹤散两自遂，意思不受人丁宁。
今朝棹倚寒江汀，舂鉏翡翠参䴔䴖。
孤翘侧睨瞥灭没，未是即肯驯檐楹。
妇女衣襟便佞舌，始得金笼日提挈。
精神卓荦背人飞，冷抱蒹葭宿烟月。
我与时情大乖刺，祗是江禽有毛髪。
殷勤谢汝莫相猜，归来长短同羣活。','',''),('quantangshi-34266','五歌 刈获','陸龜蒙','quantangshi','','卷35','自春徂秋天弗雨，廉廉早稻才遮亩。
芒粒稀疎熟更轻，地与禾头不相拄。
我来愁筑心如堵，更听农夫夜深语。
凶年是物即为灾，百阵野凫千穴鼠。
平明抱杖入田中，十穗萧条九穗空。
敢言一岁囷仓实，不了如今朝暮舂。
天职谁司下民籍，苟有区区宜㭊㭊。
本作耕耘意若何，虫豸兼教食人食。
古者为邦须蓄积，鲁饥尚责如齐籴。
今之为政异当时，一任流离恣征索。
平生幸遇华阳客，向日餐霞转肥白。
欲卖耕牛弃水田，移家且傍三茅宅。','',''),('quantangshi-34267','五歌 雨夜','陸龜蒙','quantangshi','','卷35','屋小茅干雨声大，自疑身着蓑衣卧。
兼似孤舟小泊时，风吹折苇来相佐。
我有愁襟无可那，才成好梦刚惊破。
背壁残灯不及萤，重挑却向灯前坐。','',''),('quantangshi-34268','五歌 食鱼','陸龜蒙','quantangshi','','卷35','江南春旱鱼无泽，岁晏未曾腥鼎鬲。
今朝有客卖鲈鲂，手提见我长于尺。
呼儿舂取红莲米，轻重相当加十倍。
且作吴羹助早餐，饱卧晴檐曝寒背。
横戈负羽正纷纷，祗用骁雄不用文。
争如晓夕讴吟样，好伴沧洲白鸟羣。','',''),('quantangshi-34269','丁隐君歌','陸龜蒙','quantangshi','','卷35','华阳道士南游归，手中半卷青萝衣。
自言逋客持赠我，乃是钱搪丁翰之。
连江大抵多奇岫，独话君家最奇秀。
盘烧天竺春笋肥，琴倚洞庭秋石瘦。
草堂暗引龙泓溜，老树根株若蹲兽。
霜浓果熟未容收，往往儿童杂猨狖。
去岁猖狂有黄寇，官军解散无人鬬。
满城奔迸翰之闲，只把枯松塞圭窦。
前度相逢正卖文，一钱不直虚云云。
今来利作采樵客，可以抛身麋鹿羣。
丁隐君，丁隐君，叩头且莫变名氏，即日更寻丁隐君。','',''),('quantangshi-34270','紫溪翁歌','陸龜蒙','quantangshi','','卷35','一丘之木，其栖深也屋，吾容不辱。
一溪之石，其居平也席，吾劳以息。
一窦之泉，其音清也弦，吾方在悬。
得乎人，得乎天，吾不知所以然而然。','',''),('quantangshi-34271','赓歌','陸龜蒙','quantangshi','','卷35','采江之鱼兮，朝船有鲈。
采江之蔬兮，暮筐有蒲。
左图且书，右琴与壶。
寿欤夭欤，贵欤贱欤。','',''),('quantangshi-34272','鹤媒歌','陸龜蒙','quantangshi','','卷35','偶系渔舟汀树枝，因看射鸟令人悲。
盘空野鹤忽然下，背翳见媒心不疑。
媒闲静立如无事，清唳时时入遥吹。
裴回未忍过南塘，且应同声就同类。
梳翎宛若相逢喜，祗怕才来又惊起。
窥鳞啄藻乍低昂，立定当胸流一矢。
媒欢舞跃势离披，似谄功能邀弩儿。
云飞水宿各自物，妬侣害羣犹尔为。
而况世间有名利，外头笑语中猜忌。
君不见荒陂野鹤陷良媒，同类同声真可畏。','',''),('quantangshi-34273','庆封宅古井行','陸龜蒙','quantangshi','','卷35','古甓团团藓花碧，鼎渫寒泉深百尺。
江南戴白尽能言，此地曾为庆封宅。
庆封嗜酒荒齐政，齐人剪族封奔迸。
虽过鲁国羞鲁儒，欲弄吴民窃吴柄。
吴分岩邑号朱方，子家负固心彊梁。
泽车豪马驰似水，锦凤玉龙森若墙。
一朝云梦围兵至，胸陷锋铓脑涂地。
因知富德不富财，颜氏箪瓢有深意。
宣父尝违盗泉水，懦夫立事贪夫止。
今歌此井示吴人，断绠沉瓶自兹始。','',''),('quantangshi-34274','小鸡山樵人歌','陸龜蒙','quantangshi','','卷35','长其船兮利其斧，输予薪兮勿予侮。
田予登兮谷予庾，突晨烟兮蓬缕缕。
窗有明兮编有古，饱而安兮惟编是伍，时不用兮吾无汝抚。','',''),('quantangshi-34275','吴俞儿舞歌 劒俞','陸龜蒙','quantangshi','','卷35','枝月喉，棹霜脊，北斗离离在寒碧。
龙魂清，虎尾白，秋照海心同一色。
纛影吒沙千影侧，神豪髪直。
四睨之人股佶栗，欲定不定定不得。
舂牍残，儿且止，狄胡有胆大如山，怖亦死。','',''),('quantangshi-34276','吴俞儿舞歌 矛俞','陸龜蒙','quantangshi','','卷35','手盘风，头背分。
电光战扇，欲刺敲心留半线。
缠肩绕脰，𧞔合眩旋。
卓植赴列，夺避中节。
前冲函礼穴，上指孛彗灭，与君一用来有截。','',''),('quantangshi-34277','吴俞儿舞歌 弩俞','陸龜蒙','quantangshi','','卷35','牛来开弦，人为置镞。
捩机关，迸山谷。
鹿骇涩，隼击迟。
析毫中睫，洞腋分龟。
达坚垒，残雄师。
可以冠猛乐壮曲，抑扬蹈厉。
有裂犀兕之气者，非公与。','',''),('quantangshi-34278','句曲山朝真词二首 迎真','陸龜蒙','quantangshi','','卷35','九华磬答寒泉急，十绝幡摇翠微湿。
司命旍旌未下来，焚香抱简凝神立。
残星下照霓襟冷，缺月才分鹤轮影。
空洞灵章发一声，春来万壑烟花醒。','',''),('quantangshi-34279','句曲山朝真词二首 送真','陸龜蒙','quantangshi','','卷35','萦云凤髻飘然解，玉钺玄干俨先迈。
朝真弟子悄无言，再拜碧杯添沆瀣。
火{金灵}跳跃龙毛盖，脑髪青青赮綷綷。
万象销沈一瞬间，空余月外闻残佩。','',''),('quantangshi-34280','战秋辞','陸龜蒙','quantangshi','','卷35','八月空堂，前临隙荒。
抽关散扇，晨乌未光。
左右物态，森疎强梁。
天随子爽駴恂栗，恍军庸之我当。
濠然而沟，垒然而墙。
纛然而桂，队然而篁。
杉巉攒矛，蕉标建常。
槁艾矢束，矫蔓弦张。
蛙合助吹，鸟分启行。
若革进而金止，固违阴而就阳。
无何，云颜师，风旨伯，苍茫惨澹，隳危摵划。
烟蒙上焚，雨阵下棘。
如濠者注，如垒者辟，如纛者亚，如队者析，如矛者折，如常者拆，如矢者仆，如弦者磔，如吹者瘖，如行者惕，石有髪兮尽累，木有耳兮咸馘。
云风雨烟，乘胜之势骄。
杉篁蕉蔓，败北之气摵。
天随子曰：吁！秋无神则已，如其有神，吾为尔羞之。
南北畿圻，盗兴五朞。
方州大都，虎节龙旗。
瓦解冰碎，瓜分豆离。
斧抵耋老，干穿乳儿。
昨宇今烬，朝人暮尸。
万犊一啖，千仓一炊。
扰践边朔，歼伤蜑夷。
制质守帅，披攘城池。
弓弮不刓，甲缀不离。
凶渠歌笑，裂地无疑。
天有四序，秋为司刑。
少昊负扆，亲朝百灵。
蓐收相臣，太白将星。
可霾可电，可风可霆。
可堑溺颠陷，可夭札迷冥。
曾忘鏖剪，自意澄宁。
苟蜡礼之云责，触天怒而谁丁。
奈何欺荒庭，凌坏砌，摋崇茝，批宿蕙。
揭编茅而逞力，断纬萧而作势。
不过约弱欹垂，戕残废替。
可谓弃其本而趋其末，舍其大而从其细也。
辞犹未已，色若愧耻。
于是堕者止，偃者起。','',''),('quantangshi-34281','祝牛宫辞','陸龜蒙','quantangshi','','卷35','四牸三牯，中一去乳。
天霜降寒，纳此室处。
老农拘拘，度地不亩。
东西几何，七举其武。
南北几何，丈二加五。
偶楹当闲，载尺入土。
太岁在亥，余不足数。
上缔蓬茅，下远官府。
耕耨以时，饮食得所。
或寝或卧，免风免雨。
宜尔子孙，实我仓庾。','',''),('quantangshi-34282','迎潮送潮辞 迎潮','陸龜蒙','quantangshi','','卷35','江霜严兮枫叶丹，潮声高兮墟落寒。
鸥巢卑兮渔箔短，远岸没兮光烂烂。
潮之德兮无际，既充其大兮又充其细。
密幽人兮欵柴门，寂寞流连兮依稀旧痕。
濡腴泽槁兮潮之恩，不尸其功兮归于混元。','',''),('quantangshi-34283','迎潮送潮辞 送潮','陸龜蒙','quantangshi','','卷35','潮西来兮又东下，日染中流兮红洒洒。
汀葭苍兮屿蓼枯，风骚牢兮愁烟孤。
大几望兮微将晦翳，睨瀛溶兮敛然而退。
爱长波兮数数，一幅巾兮无缨可濯。
帆生尘兮檝有衣，怅潮之还兮吾犹未归。','',''),('quantangshi-34284','问吴宫辞','陸龜蒙','quantangshi','','卷35','彼吴之宫兮江之郍涯，复道盘兮当高且斜。
波摇疏兮雾蒙箔，菡萏国兮鸳鸯家。
鸾之箫兮蛟之瑟，骈筠参差兮界丝密。
宴曲房兮上初日，月落星稀兮歌酣未毕。
越山丛丛兮越溪疾，美人雄劒兮相先后出。
火姑苏兮沼长洲，此宫之丽人兮留乎不留。
霜氛重兮孤榜晓，远树扶苏兮愁烟悄眇。
欲摭愁烟兮问故基，又恐愁烟兮推白鸟。','',''),('quantangshi-34285','萤诗','陸龜蒙','quantangshi','','卷35','肖翘虽振羽，戚促尽疑冰。
风助流还急，烟遮点渐凝。
不须轻列宿，才可拟孤灯。
莫倚隋家事，曾烦下诏征。','',''),('quantangshi-34286','蝉','陸龜蒙','quantangshi','','卷35','祗凭风作使，全仰柳为都。
一腹清何甚，双翎薄更无。
伴貂金换酒，并雀画成图。
恐是千年恨，偏令落日呼。','',''),('quantangshi-34287','秋热','陸龜蒙','quantangshi','','卷35','自惜秋捐扇，今来意未衰。
殷勤付柔握，淅沥待清吹。
午气朱崖近，宵声白羽随。
总如南国候，无复婕妤悲。','',''),('quantangshi-34288','村中晚望','陸龜蒙','quantangshi','','卷35','抱杖柴门立，江村日易斜。
雁寒犹忆侣，人病更离家。
短鬓看成雪，双眸旧有花。
何须万里外，即此是天涯。','',''),('quantangshi-34289','四明山诗 石窗','陸龜蒙','quantangshi','','卷35','石窗何处见，万仞倚晴虚。
积霭迷青璅，残霞动绮疏。
山应列圆峤，宫便接方诸。
祗有三奔客，时来教隐书。','',''),('quantangshi-34290','四明山诗 过云','陸龜蒙','quantangshi','','卷35','相访一程云，云深路仅分。
啸台随日辨，樵斧带风闻。
晓着衣全湿，寒冲酒不醺。
几回归思静，仿髴见苏君。','',''),('quantangshi-34291','四明山诗 云南','陸龜蒙','quantangshi','','卷35','云南更有溪，丹砾尽无泥。
药有巴賨卖，枝多越鸟啼。
夜清先月午，秋近少岚迷。
若得山颜住，芝𥰭手自携。','',''),('quantangshi-34292','四明山诗 云北','陸龜蒙','quantangshi','','卷35','云北是阳川，人家洞壑连。
坛当星斗下，楼拶翠微边。
一半遥峰雨，三条古井烟。
金庭如有路，应到左神天。','',''),('quantangshi-34293','四明山诗 鹿亭','陸龜蒙','quantangshi','','卷35','鹿亭岩下置，时领白麛过。
草细眠应久，泉香饮自多。
认声来月坞，寻迹到烟萝。
早晚吞金液，骑将上绛河。','',''),('quantangshi-34294','四明山诗 樊榭','陸龜蒙','quantangshi','','卷35','樊榭何年筑，人应白日飞。
至今山客说，时驾玉麟归。
乳蔕缘松嫩，芝台出石微。
凭栏虚目断，不见羽华衣。','',''),('quantangshi-34295','四明山诗 潺湲洞','陸龜蒙','quantangshi','','卷35','石浅洞门深，潺潺万古音。
似吹双羽管，如奏落霞琴。
倒穴漂龙沫，穿松溅鹤襟。
何人乘月弄，应作上清吟。','',''),('quantangshi-34296','四明山诗 青棂子','陸龜蒙','quantangshi','','卷35','山实号青棂，环冈次第生。
外形坚绿壳，中味敌璚英。
堕石樵儿拾，敲林宿鸟惊。
亦应仙吏守，时取荐层城。','',''),('quantangshi-34297','四明山诗 鞠侯','陸龜蒙','quantangshi','','卷35','何事鞠侯名，先封在四明。
但为连臂饮，不作断肠声。
野蔓垂缨细，寒泉佩玉清。
满林游宦子，谁为作君卿。','',''),('quantangshi-34298','奉和袭美赠魏处士五贶诗 五泻舟','陸龜蒙','quantangshi','','卷35','样自桐川得，词因隐地成。
好渔翁亦喜，新白鸟还惊。
沙际拥江沫，渡头横雨声。
尚应嫌越相，遗祸不遗名。','',''),('quantangshi-34299','奉和袭美赠魏处士五贶诗 华顶杖','陸龜蒙','quantangshi','','卷35','万古阴崖雪，灵根不为枯。
瘦于霜鹤胫，奇似黑龙须。
拄访谭玄客，持看泼墨图。
湖云如有路，兼可到仙都。','',''),('quantangshi-34300','奉和袭美赠魏处士五贶诗 太湖砚','陸龜蒙','quantangshi','','卷35','谁截小秋滩，闲窥四绪宽。
绕为千嶂远，深置一潭寒。
坐久云应出，诗成墨未干。
不知新博物，何处拟重刊。','',''),('quantangshi-34301','奉和袭美赠魏处士五贶诗 乌龙养和','陸龜蒙','quantangshi','','卷35','养和名字好，偏寄道情深。
所以亲逋客，兼能助五禽。
倚肩沧海望，钩膝白云吟。
不是逍遥侣，谁知世外心。','',''),('quantangshi-34302','奉和袭美赠魏处士五贶诗 诃陵尊','陸龜蒙','quantangshi','','卷35','鱼骼匠成尊，犹残海浪痕。
外堪欺玳瑁，中可酌昆仑。
水绕苔矶曲，山当草阁门。
此中醒复醉，何必问干坤。','',''),('quantangshi-34303','奉酬袭美早春病中书事','陸龜蒙','quantangshi','','卷35','祗贪诗调苦，不计病容生。
我亦休文瘦，君能叔宝清。
药须勤一服，春莫累多情。
欲入毗耶问，无人敌浄名。','',''),('quantangshi-34304','又酬次韵','陸龜蒙','quantangshi','','卷35','从来多远思，尤向静中生。
所以令心苦，还应是骨清。
酒香偏入梦，花落又关情。
积此风流事，争无后世名。','',''),('quantangshi-34305','奉酬袭美秋晚见题二首 一','陸龜蒙','quantangshi','','卷35','为爱晚窗明，门前亦嬾行。
图书看得熟，邻里见还生。
鸟啄琴材响，僧传药味精。
缘君多古思，携手上空城。','',''),('quantangshi-34306','奉酬袭美秋晚见题二首 二','陸龜蒙','quantangshi','','卷35','何事乐渔樵，巾车或倚桡。
和诗盈古箧，赊酒半寒瓢。
失雨园蔬赤，无风蚛叶雕。
清言一相遗，吾道未全消。','',''),('quantangshi-34307','奉和袭美初冬章上人院','陸龜蒙','quantangshi','','卷35','每伴来方丈，还如到四禅。
菊承荒砌露，茶待远山泉。
画古全无迹，林寒却有烟。
相看吟未竟，金磬已泠然。','',''),('quantangshi-34308','袭美见题郊居十首因次韵酬之以伸荣谢 一','陸龜蒙','quantangshi','','卷35','近来唯乐静，移傍故城居。
闲打修琴料，时封谢药书。
夜停江上鸟，晴晒箧中鱼。
出亦图何事，无劳置栈车。','',''),('quantangshi-34309','袭美见题郊居十首因次韵酬之以伸荣谢 二','陸龜蒙','quantangshi','','卷35','倩人医病树，看仆补衡茅。
散髪还同阮，无心敢慕巢。
简便书露竹，尊待破霜匏。
日好林间坐，烟萝近欲交。','',''),('quantangshi-34310','袭美见题郊居十首因次韵酬之以伸荣谢 三','陸龜蒙','quantangshi','','卷35','倭僧留海纸，山匠制云牀。
嬾外应无敌，贫中直是王。
池平鸥思喜，花尽蝶情忙。
欲问新秋计，菱丝一亩强。','',''),('quantangshi-34311','袭美见题郊居十首因次韵酬之以伸荣谢 四','陸龜蒙','quantangshi','','卷35','故山空自掷，当路竟谁知。
祗有经时策，全无养拙资。
病深怜灸客，炊晚信樵儿。
谩欲陈风俗，周官未采诗。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34312','袭美见题郊居十首因次韵酬之以伸荣谢 五','陸龜蒙','quantangshi','','卷35','福地能容壍，玄关讵有扉。
静思琼版字，闲洗铁筇衣。
鸟破凉烟下，人冲暮雨归。
故园秋草梦，犹记绿微微。','',''),('quantangshi-34313','袭美见题郊居十首因次韵酬之以伸荣谢 六','陸龜蒙','quantangshi','','卷35','水影沈鱼器，邻声动纬车。
燕轻捎坠叶，蜂嬾卧燋花。
说史评诸例，论兵到百家。
明时如不用，归去种桑麻。','',''),('quantangshi-34314','袭美见题郊居十首因次韵酬之以伸荣谢 七','陸龜蒙','quantangshi','','卷35','禹穴奇编缺，雷平异境残。
静吟封箓检，归兴削帆竿。
白石堪为饭，青萝好作冠。
几时当斗柄，同上步罡坛。','',''),('quantangshi-34315','袭美见题郊居十首因次韵酬之以伸荣谢 八','陸龜蒙','quantangshi','','卷35','强起披衣坐，徐行处暑天。
上阶来鬬雀，移树去惊蝉。
莫问盐车骏，谁看酱瓿玄。
黄金如可化，相近买云泉。','',''),('quantangshi-34316','袭美见题郊居十首因次韵酬之以伸荣谢 九','陸龜蒙','quantangshi','','卷35','野入青芜巷，陂侵白竹门。
风高开栗刺，沙浅露芹根。
迸鼠缘藤桁，饥乌立石盆。
东吴虽不改，谁是武王孙。','',''),('quantangshi-34317','袭美见题郊居十首因次韵酬之以伸荣谢 十','陸龜蒙','quantangshi','','卷35','疎慵真有素，时势尽无能。
风月虽为敌，林泉幸未憎。
酒材经夏阙，诗债待秋征。
祗有君同癖，闲来对曲肱。','',''),('quantangshi-34318','和张广文贲旅泊吴门次韵','陸龜蒙','quantangshi','','卷35','高秋能叩触，天籁忽成文。
苦调虽潜倚，灵音自绝羣。
茅峰曾醮斗，笠泽久眠云。
许伴山中躅，三年任一醺。','',''),('quantangshi-34319','又次前韵酬广文','陸龜蒙','quantangshi','','卷35','独倚秋光岸，风漪学簟文。
玄堪教凤集，书好换鹅羣。
叶堕平台月，香消古径云。
强歌非白紵，聊以送余醺。','',''),('quantangshi-34320','送延陵张宰','陸龜蒙','quantangshi','','卷35','春尽未离关，之官亦似闲。
不嫌请薄俸，为喜带名山。
默祷三真后，高吟十字还。
祗应江上鸟，时下讼庭间。','',''),('quantangshi-34321','送人罢官归茅山','陸龜蒙','quantangshi','','卷35','呼僮晓拂鞍，归上大茅端。
薄俸虽休入，明霞自足餐。
暗霜松粒赤，疎雨草堂寒。
又凿中峰石，重修醮月坛。','',''),('quantangshi-34322','立春日','陸龜蒙','quantangshi','','卷35','去年花落时，题作送春诗。
自为重相见，应无今日悲。
道孤逢识寡，身病买名迟。
一夜东风起，开帘不敢窥。','',''),('quantangshi-34323','中秋夜寄友生','陸龜蒙','quantangshi','','卷35','秋来一度满，重见色难齐。
独坐犹过午，同吟不到西。
疎芒唯斗在，残白合河迷。
更忆前年望，孤舟泊大溪。','',''),('quantangshi-34324','奉和袭美古杉三十韵','陸龜蒙','quantangshi','','卷35','众木尽相遗，孤芳独任奇。
锸天形硉兀，当殿势𢼮危。
恐是夸娥怒，教临嶻嶭衰。
节穿开耳目，根瘿坐熊罴。
世只论荣落，人谁问等衰。
有巅从日上，无叶与秋欺。
虎搏应难动，雕蹲不敢迟。
战锋新缺齾，烧岸黑𪑿黧。
鬬死龙骸杂，争奔鹿角差。
肢销洪水脑，棱耸梵天眉。
磔索珊瑚涌，森严獬豸窥。
向空分荦指，冲浪出鲸鬐。
杨仆船幢在，蚩尤阵纛隳。
下连金粟固，高用铁菱披。
挺若苻坚棰，浮于祖纳椎。
峥嵘惊露鹤，䟐趚阂云螭。
傍宇将支压，撑霄欲抵隵。
背交虫臂局，相向鹘拳追。
格笔差犹立，阶干卓未麾。
鬼神应暗画，风雨恐潜移。
已觉寒松伏，偏宜后土疲。
好邀清啸傲，堪映古茅茨。
材大应容蝎，年深必孕夔。
后雕依佛氏，初植必僧弥。
拥肿烦庄辩，槎牙费庾词。
咏多灵符困，搜苦化权卑。
类既区中寡，朋当物外推。
蟠桃标日域，珠草侍仙墀。
真宰诚求梦，春工幸可医。
若能嘘嶰竹，犹足动华滋。','',''),('quantangshi-34325','奉和袭美新秋言怀三十韵次韵','陸龜蒙','quantangshi','','卷35','身闲唯爱静，篱外是荒郊。
地僻怜同巷，庭喧厌累巢。
岸声摇舴艋，窗影辨蟏蛸。
径祗溪禽下，关唯野客敲。
竹冈从古凸，池缘本来䫜。
早藕擎霜节，凉花束紫梢。
渔情随锤网，猎兴起鸣𩩉。
好梦经年说，名方着处抄。
才疎惟自补，技痒欲谁抓。
窗静常悬䕹，鞭闲不正鞘。
山衣轻斧藻，天籁逸弦匏。
蕙转风前带，桃烘雨后胶。
藓干黏晚砌，烟湿动晨庖。
沈约便图籍，扬雄重酒肴。
目曾窥绝洞，耳不犯征铙。
历外穷飞朔，蓍中记伏爻。
石林空寂历，云肆肯哓譊。
松桂何妨蠹，龟龙亦任嘲。
未能丹作髓，谁相紫为胞。
莫把荣枯异，但和大小包。
由弓猨不捷，梁圈虎忘虓。
旧友怀三益，关山阻二崤。
道随书簏古，时共钓轮抛。
好作忘机士，须为莫逆交。
看君驰谏草，怜我卧衡茅。
出处虽冥默，薰莸肯溷肴。
岸沙从鹤印，崖蜜劝人𦾱。
白菌盈枯枿，黄精满绿筲。
仙因隐居信，禅是净名教。
勿谓江湖永，终浮一大瓟。','',''),('quantangshi-34326','和袭美江南书情二十韵寄祕阁韦校书贻之商洛宋先辈垂文二同年次韵','陸龜蒙','quantangshi','','卷35','我志如鱼乐，君词称凤衔。
暂来从露冕，何事买云岩。
水石应容病，松篁未听谗。
罐香松蠹腻，山信药苗缄。
爱鹭欹危立，思猨矍铄獑。
谢才偏许朓，阮放最怜咸。
大乐宁忘缶，奇工肯顾瑊。
客愁迷旧隐，鹰健想秋毚。
砚缺犹慵琢，文繁却要芟。
雨余幽沼净，霞散远峰巉。
洗笔烟成段，培花土作杴。
访僧还觅伴，医鹤自须监。
荒庙犹怀季，清滩几梦严。
背风开蠹简，冲浪试新帆。
闷忆年支酒，闲裁古样衫。
钓家随野舫，仙蕴逐雕函。
度岁赊羸马，先春买小𧍧。
共疏泉入竹，同坐月过杉。
染翰穷高致，怀贤发至諴。
不堪潘子鬓，愁促易髟髟。','',''),('quantangshi-34327','忆袭美洞庭观步奉和次韵','陸龜蒙','quantangshi','','卷35','闻君游静境，雅具更摐摐。
竹伞遮云径，藤鞋踏藓矼。
杖斑花不一，尊大瘿成双。
水鸟行沙屿，山僧礼石幢。
已甘三秀味，谁念百牢腔。
远棹投何处，残阳到几窗。
仙谣珠树曲，村饷白醅[缸]。
地里方吴会，人风似冉厖。
探幽非遯世，寻胜肯迷邦。
为读江南传，何贤过二庞。','',''),('quantangshi-34328','江墅言怀','陸龜蒙','quantangshi','','卷35','病身兼稚子，田舍劣相容。
迹共公卿绝，贫须稼穑供。
月方行到闰，霜始近言浓。
树少栖禽杂，村孤守犬重。
汀洲藏晚弋，篱落露寒舂。
野弁欹还整，家书拆又封。
杉篁宜夕照，窗户倚疎钟。
南北唯闻战，纵横未胜农。
大春虽苦学，叔夜本多慵。
直使貂裘弊，犹堪过一冬。','',''),('quantangshi-34329','自和次前韵','陸龜蒙','quantangshi','','卷35','命既时相背，才非世所容。
着书粮易绝，多病药难供。
梦为怀山数，愁因戒酒浓。
鸟媒呈不一，鱼寨下仍重。
晚桁蓑兼褐，晴檐织带舂。
着签分水味，标石认田封。
此地家三户，何人禄万钟。
草堂聊当贵，金穴任轻农。
把钓竿初冷，题诗笔未慵。
莫忧寒事晚，江上少严冬。','',''),('quantangshi-34330','秋日遣怀十六韵寄道侣','陸龜蒙','quantangshi','','卷35','尽日临风坐，雄词妙略兼。
共知时世薄，宁恨岁华淹。
且把灵方试，休凭吉梦占。
夜然烧汞火，朝炼洗金盐。
有路求真隐，无媒举孝廉。
自然成啸傲，不是学沈潜。
水恨同心隔，霜愁两鬓霑。
鹤屏怜掩扇，乌帽爱垂檐。
雅调宜观乐，清才称典签。
冠𢼮玄髪少，书健紫毫尖。
故疾因秋召，尘容畏日黔。
壮图须行行，儒服谩襜襜。
片石聊当枕，横烟欲代帘。
蠹根延穴蚁，疎叶漏庭蟾。
药鼎高低铸，云庵早晚苫。
胡麻如重寄，从诮我无厌。','',''),('quantangshi-34331','京口与友生话别','陸龜蒙','quantangshi','','卷35','共是悲秋客，相逢恨不堪。
雁频辞苏北，人尚在江南。
名利机初发，樵渔事先谙。
松门穿戴寺，荷径绕秦潭。
绳检真难束，疎慵却易耽。
枕当高树稳，茶试远泉甘。
架上经唯一，尊前雅祗三。
风云劳梦想，天地入醺酣。
历自尧阶数，书因禹穴探。
御龙虽世禄，下马亦清谭。
国计徒盈策，家储不满甔。
断帘从燕出，𢼮弁请人簪。
木坠凉来叶，山横霁后岚。
竹窗深䆗窱，苔洞绿龛弇。
积行依颜子，和光则老聃。
杖诚为虎节，披信作鲛函。
养鹭看窥沼，寻僧助结庵。
功名思马援，歌唱咽羊昙。
乞食羞孤凤，无衣羡八蚕。
系帆留宿客，吟句任羸骖。
宠鹤空无卫，占乌未见𨝸。
香还须是桂，青会出于蓝。
蜀酒时倾瓿，吴鰕徧发坩。
玉封千挺藕，霜闭一筒柑。
惜佩终邀祸，辞环好激贪。
宗溟虽甽浍，成厦必楩柟。
碧玉雕琴荐，黄金饰劒镡。
烟缘莎砌引，水为药畦担。
博物君能继，多才我尚慙。
别离犹得在，秋鬓未鬖鬖。','',''),('quantangshi-34332','丹阳道中寄友生','陸龜蒙','quantangshi','','卷35','烟树绿微微，春流浸竹扉。
短蓑携稚去，孤艇载鱼归。
海俗芦编室，村娃练束衣。
旧栽奴橘老，新刈女桑肥。
锦鲤冲风掷，丝禽掠浪飞。
短亭幽径入，陈庙数峰围。
地废金牛暗，陵荒石兽稀。
思君同一望，帆上怨余晖。','',''),('quantangshi-34333','寄茅山何道士','陸龜蒙','quantangshi','','卷35','终身持玉舃，丹诀未应传。
况是曾同宿，相违便隔年。
问颜知更少，听话想逾玄。
古箓文垂露，新金汞绝烟。
蜂供和饵蜜，人寄买溪钱。
紫燕长巢硐，青龟忽上莲。
箧藏征隐诏，囊佩摄生篇。
圃暖芝台秀，岩春乳管圆。
池栖子孙鹤，堂宿弟兄仙。
幸阅灵书次，心期赐一编。','',''),('quantangshi-34334','江南秋怀寄华阳山人','陸龜蒙','quantangshi','','卷35','栉髪凉天曙，含毫故国情。
归心一夜极，病体九秋轻。
忽起襜褕咏，因悲络纬鸣。
逢山即堪隐，何路可图荣。
揲策空占命，持竿不钓名。
忘忧如有待，纵嬾似无营。
小径才分草，斜扉劣辨荆。
冷荷承露菂，疎菊卧烟茎。
谱为听琴阅，图缘看海㡠。
鹭毛浮岛白，鱼尾撇波赬。
庭橘低攀嗅，园葵旋折烹。
饿乌窥食案，鬬鼠落书棚。
种豆悲杨恽，投瓜忆卫旍。
东林谁处士，南郭自先生。
分野星多蹇，连山卦少亨。
衣裾徒博大，文籍漫纵横。
兰叶骚人佩，莼丝内史羹。
鹖冠难适越，羊酪未饶伧。
倚啸微抽恨，论玄好析酲。
栖迟劳鼓箧，豪侠爱金籯。
炼药传丹鼎，尝茶试石𪼿。
沼连枯苇暗，窗对脱梧明。
未达讥张翰，非才嫉禰衡。
远怀魂易黯，幽愤骨堪惊。
砺缺知矛利，磨瑕见璧瑛。
道源疏滴沥，儒肆售精诚。
敢叹良时掷，犹胜乱世撄。
相秦犹几死，王汉尚当黥。
饮啄期应定，穷通势莫争。
髡钳为皂隶，谭笑得公卿。
浴日安知量，追风不计程。
尘埃张耳分，肝胆季心倾。
谕蜀专操檄，通瓯独请缨。
匹夫能曲踊，万骑可横行。
许国轻妻子，防边重战耕。
俄分上尊酒，骤厌五侯鲭。
静默供三语，从容等一枰。
弘深司马法，雄杰贰师兵。
朔雪埋烽燧，寒笳裂斾旌。
乘时收句注，即日埽欃枪。
武昔威殊俗，文今被八纮。
琮璜陈始毕，韶夏教初成。
芽孽羣妖灭，松筠百度贞。
郎官青琐拜，使者绣衣迎。
帝道将云辟，浇波渐砥平。
学徒羞说霸，佳士耻为跉。
负杖歌栖亩，操觚赋北征。
才当曹斗怯，书比惠车盈。
谢氏怜儿女，郄家贵舅甥。
唯荒稚圭宅，莫赠景山枪。
贤彦风流远，江湖思绪萦。
讴哑摇舴艋，出没漾䴔䴖。
晚树参差碧，奇峰逦迤晴。
水喧揌紫芡，村响{姊女=臼}香秔。
荷笠渔翁古，穿篱守犬狞。
公衫白紵卷，田饷绿筲擎。
地与膏腴错，人多富寿并。
相欢时帖泰，独坐岁峥嵘。
唧啧蛩吟壁，连轩鹤舞楹。
戍风飘叠鼓，邻月动哀筝。
未得文章力，何由俸禄请。
和铅还搰搰，持斧自丁丁。
惊惧疑凋朽，功勤过屑琼。
凝神披夕秀，尽力取朝英。
蠹简开尘箧，寒灯立晓檠。
静翻词客系，闲难史官评。
天地宁舒惨，山川自变更。
秖能分跖惠，谁解等殇彭。
项岂重瞳圣，夔忧一足𨆪。
阮高酣麴糵，庄达谢牺牲。
齚舌无劳话，宽心岂可盛。
但从罏冶锻，莫受罻罗婴。
砚拨萍根洗，舟冲蓼穗撑。
短牀编翠竹，低机凭红柽。
霜信催杨柳，烟容褭杜蘅。
桁排巢燕燕，屏画醉猩猩。
嬾桧推岚影，飞泉撼玉琤。
𦪽{舟卭}寻远近，握槊鬬输赢。
枝压离披瓠，檐垂礧磊橙。
忘情及宗炳，抱疾过刘桢。
野馈夸菰饭，江商贾蔗饧。
送神枹瓦釜，留客上瓷觥。
举楫挥青劒，鸣榔扣远钲。
鸟行沈莽碧，鱼队破泓澄。
手戟非吾事，腰镰且发硎。
谅难求摽摽，聊欲取铮铮。
几叹虫甘蓼，还思鹿美苹。
愁长难自剪，歌断有谁赓。
未去师黄石，空能说白珩。
性湍休激浪，言莠罢抽萌。
地僻琴尊独，溪寒杖屦清。
物齐消臆对，戈倒共心盟。
丝曳灵妃瑟，金涵太子笙。
幽栖胶竹坞，仙虑驿蓬瀛。
想像珠襦凤，追飞翠蘂莺。
雾帘深杳悄，云磬冷敲铿。
箓字多阶品，华阳足弟兄。
焚香凝一室，尽日思层城。
匿景崦嵫色，呀空渤澥声。
吾当营巨黍，东去射长鲸。','',''),('quantangshi-34335','送宣武从事越中按狱','陸龜蒙','quantangshi','','卷35','晓看呈使范，知欲敕星轺。
水国难驱传，山城便倚桡。
秉筹先独立，持法称高标。
旌斾临危堞，金丝发丽谯。
别愁当翠巘，冤望隔风潮。
木落孤帆迥，江寒叠鼓飘。
客鸿吴岛尽，残雪剡汀消。
坐想休秦狱，春应到柳条。','',''),('quantangshi-34336','江南冬至和人怀洛下','陸龜蒙','quantangshi','','卷35','昔居清洛涯，长恨苦寒迟。
自作江南客，稀迟下雪时。
有烟栖菊梗，无冻落杉枝。
背日能寻径，临风尚覆棋。
鸟声浑欲转，草色固应知。
与看平湖上，东流或片澌。','',''),('quantangshi-34337','谨和谏议罢郡叙怀六韵','陸龜蒙','quantangshi','','卷35','已报东吴政，初捐左契归。
天应酬苦节，人不犯寒威。
江上思重借，朝端望载饥。
紫泥封夜诏，金殿赐春衣。
对酒情何远，裁诗思极微。
待升镕造日，江海问渔扉。','',''),('quantangshi-34338','二遗诗','陸龜蒙','quantangshi','','卷35','谁从毫末见参天，又到苍苍化石年。
万古清风吹作籁，一条寒溜滴成穿。
闲追金带徒劳恨，静格朱丝更可怜。
幸与野人俱散诞，不烦良匠更雕镌。','',''),('quantangshi-34339','䴔䴖','陸龜蒙','quantangshi','','卷35','词赋曾夸鸀鳿流，果为名误别沧洲。
虽蒙静置疎笼晚，不似闲栖折苇秋。
自昔稻粱高鸟畏，至今圭组野人讐。
防徽避缴无穷事，好与裁书谢白鸥。','',''),('quantangshi-34340','新秋月夕客有自远相寻者作吴体二首以赠 一','陸龜蒙','quantangshi','','卷35','风初寥寥月乍满，杉篁左右供余清。
因君一话故山事，忆鹤互应深溪声。
云门老森定未起，白阁道士遥相迎。
日闻羽檄日夜急，掉臂欲归岩下行。','',''),('quantangshi-34341','新秋月夕客有自远相寻者作吴体二首以赠 二','陸龜蒙','quantangshi','','卷35','惊闻远客访良夜，扶病起坐纶巾欹。
清谈白紵思悄悄，玉绳银汉光离离。
三吴烟雾且如此，百越琛賮来何时。
林端片月落未落，强慰别情言后期。','',''),('quantangshi-34342','闲书','陸龜蒙','quantangshi','','卷35','病学高僧置一牀，披衣才暇即焚香。
闲阶雨过苔花润，小簟风来薤叶凉。
南国羽书催部曲，东山毛褐傲羲皇。
升平闻道无时节，试问中林亦不妨。','',''),('quantangshi-34343','独夜','陸龜蒙','quantangshi','','卷35','新秋霁夜有清境，穷襜病容无佳期。
生公把经向石说，而我对月须人为。
独行独坐亦独酌，独玩独吟还独悲。
古称独坐与独立，若比羣居终校奇。','',''),('quantangshi-34344','寄吴融','陸龜蒙','quantangshi','','卷35','一夜秋声入井桐，数枝危绿怕西风。
霏霏晚砌烟华上，淅淅疎帘雨气通。
君整输蹄名未了，我依琴鹤病相攻。
到头江畔从渔事，织作中流万尺篊。','',''),('quantangshi-34345','中秋待月','陸龜蒙','quantangshi','','卷35','转缺霜轮上转迟，好风偏似送佳期。
帘斜树隔情无限，烛暗香残坐不辞。
最爱笙调闻北里，渐看星澹失南箕。
何人为校清凉力，未似初圆欲午时。','',''),('quantangshi-34346','重忆白菊','陸龜蒙','quantangshi','','卷35','我怜贞白重寒芳，前后丛生夹小堂。
月朵暮开无绝艳，风茎时动有奇香。
何慙谢雪清才咏，不羡刘梅贵主妆。
更忆幽窗凝一梦，夜来村落有微霜。','',''),('quantangshi-34347','别墅怀归','陸龜蒙','quantangshi','','卷35','水国初冬和暖天，南荣方好背阳眠。
题诗朝忆复暮忆，见月上弦还下弦。
遥为晚花吟白菊，近炊香稻识红莲。
何人授我黄金百，买取苏君负郭田。','',''),('quantangshi-34348','寄淮南郑宝书记','陸龜蒙','quantangshi','','卷35','记室千年翰墨孤，唯君才学似应徐。
五丁驱得神功尽，二酉搜来祕检疎。
炀帝帆樯留泽国，淮王牋奏入班书。
清词醉草无因见，但钓寒江半尺鲈。','',''),('quantangshi-34349','小雪后书事','陸龜蒙','quantangshi','','卷35','时候频过小雪天，江南寒色未曾偏。
枫汀尚忆逢人别，麦陇唯应欠雉眠。
更拟结茅临水次，偶因行药到村前。
邻翁意绪相安慰，多说明年是稔年。','',''),('quantangshi-34350','寒夜同袭美访北禅院寂上人','陸龜蒙','quantangshi','','卷35','月楼风殿静沈沈，披拂霜华访道林。
鸟在寒枝栖影动，人依古堞坐禅深。
明时尚阻青云步，半夜犹追白石吟。
自是海边鸥伴侣，不劳金偈更降心。','',''),('quantangshi-34351','和袭美江南道中怀茅山广文南阳博士三首次韵 一','陸龜蒙','quantangshi','','卷35','一片轻帆背夕阳，望三峰拜七真堂。
天寒夜漱云牙净，雪坏晴梳石髪香。
自拂烟霞安笔格，独开封检试砂牀。
莫言洞府能招隐，会辗飙轮见玉皇。','',''),('quantangshi-34352','和袭美江南道中怀茅山广文南阳博士三首次韵 二','陸龜蒙','quantangshi','','卷35','壶中行坐可携天，何况林间息万缘。
组绶任垂三品石，佩环从落四公泉。
丹台已运阴阳火，碧简须雕次第仙。
想得雷平春色动，五芝烟甲又芊眠。','',''),('quantangshi-34353','和袭美江南道中怀茅山广文南阳博士三首次韵 三','陸龜蒙','quantangshi','','卷35','良常应不动移文，金醴从酸亦自醺。
桂父旧歌飞绛雪，桐孙新韵倚玄云。
春临柳谷莺先觉，曙醮芜香鹤共闻。
珍重双双玉条脱，尽凭三岛寄羊君。','',''),('quantangshi-34354','早春雪中作吴体寄袭美','陸龜蒙','quantangshi','','卷35','迎春避腊不肯下，欺花冻草还飘然。
光填马窟盖塞外，势压鹤巢偏殿巅。
山炉瘿节万状火，墨突干衰孤穗烟。
君披鹤氅独自立，何人解道真神仙。','',''),('quantangshi-34355','奉和袭美吴中言情见寄次韵','陸龜蒙','quantangshi','','卷35','菰烟芦雪是侬乡，钓线随身好坐忘。
徒爱右军遗点画，闲披左氏得膏盲。
无因月殿闻移屧，秖有风汀去采香。
莫问江边渔艇子，玉皇看赐羽衣裳。','',''),('quantangshi-34356','和袭美扬州看辛夷花次韵','陸龜蒙','quantangshi','','卷35','柳疎梅堕少春丛，天遣花神别致功。
高处朵稀难避日，动时枝弱易为风。
堪将乱蘂添云肆，若得千株便雪宫。
不待羣芳应有意，等闲桃杏即争红。','',''),('quantangshi-34357','奉和袭美行次野梅次韵','陸龜蒙','quantangshi','','卷35','飞棹参差拂早梅，强欺寒色尚低徊。
风怜薄媚留香与，月会深情借艳开。
梁殿得非萧帝瑞，齐宫应是玉儿媒。
不知谢客离肠醒，临水应添万恨来。','',''),('quantangshi-34358','奉和袭美暇日独处见寄','陸龜蒙','quantangshi','','卷35','谢府殷楼少暇时，又抛清宴入书帷。
三千余岁上下古，八十一家文字奇。
冷梦汉臯怀鹿隐，静怜烟岛觉鸿离。
知君满箧前朝事，凤诺龙奴借与窥。','',''),('quantangshi-34359','奉和袭美见访不遇','陸龜蒙','quantangshi','','卷35','为愁烟岸老尘嚣，扶病呼儿斸翠苕。
秖道府中持简牍，不知林下访渔樵。
花盘小墢晴初压，叶拥疎篱冻未烧。
倚杖徧吟春照午，一池冰段几多消。','',''),('quantangshi-34360','酬袭美见寄海蟹','陸龜蒙','quantangshi','','卷35','药杯应阻蟹螯香，却乞江边采捕郎。
自是扬雄知郭索，且非何胤敢餦餭。
骨清犹似含春霭，沫白还疑带海霜。
强作南朝风雅客，夜来偷醉早梅傍。','',''),('quantangshi-34361','奉和袭美开元寺客省早景即事次韵','陸龜蒙','quantangshi','','卷35','日上罘罳叠影红，一声清梵万缘空。
䙰褷满地贝多雪，料峭入楼于阗风。
水榭初抽寥泬思，竹窗犹挂梦魂中。
灵香散尽禅家接，谁共殷源小品同。','',''),('quantangshi-34362','独夜有怀因作吴体寄袭美','陸龜蒙','quantangshi','','卷35','人吟侧景抱冻竹，鹤梦缺月沈枯梧。
清涧无波鹿无魄，白云有根虬有须。
云虬涧鹿真逸调，刀名锥利非良图。
不然快作燕市饮，笑抚肉枅眠酒垆。','',''),('quantangshi-34363','阖闾城北有卖花翁讨春之士往往造焉因招袭美','陸龜蒙','quantangshi','','卷35','故城边有卖花翁，水曲舟轻去尽通。
十亩芳菲为旧业，一家烟雨是元功。
闲添药品年年别，笑指生涯树树红。
若要见春归处所，不过携手问东风。','',''),('quantangshi-34364','奉和袭美病中庭际海石榴花盛发见寄次韵','陸龜蒙','quantangshi','','卷35','紫府真人饷露囊，猗兰灯烛未荧煌。
丹华乞曙先侵日，金焰欺寒却照霜。
谁与佳名从海曲，秖应芳裔出河阳。
那堪谢氏庭前见，一段清香染郄郎。','',''),('quantangshi-34365','袭美以春橘见惠兼之雅篇因次韵酬谢','陸龜蒙','quantangshi','','卷35','到春犹作九秋鲜，应是亲封白帝烟。
良玉有浆须让味，明珠无纇亦羞圆。
堪居汉苑霜梨上，合在仙家火枣前。
珍重更过三十子，不堪分付野人边。','',''),('quantangshi-34366','奉和袭美病中书情寄上崔谏议次韵','陸龜蒙','quantangshi','','卷35','或偃虚斋或在公，蔼然林下昔贤风。
庭前有蜨争烟蘂，帘外无人报水筒。
行药不离深幌底，寄书多向远山中。
西园夜烛偏堪忆，曾为题诗刻半红。','',''),('quantangshi-34367','奉酬袭美病中见寄','陸龜蒙','quantangshi','','卷35','逢花逢月便相招，忽卧云航隔野桥。
春恨与谁同酩酊，玄言何处问逍遥？
题诗石上空回笔，拾蕙汀边独倚桡。
早晚却还岩下电，共寻芳径结烟条。','',''),('quantangshi-34368','奉和袭美病孔雀','陸龜蒙','quantangshi','','卷35','嬾移金翠傍檐楹，斜倚芳丛旧态生。
唯奈瘴烟笼饮啄，可堪春雨滞飞鸣。
鸳鸯水畔回头羡，豆蔻图前举眼惊。
争得鹧鸪来伴着，不妨还校有心情。','',''),('quantangshi-34369','上元日道室焚修寄袭美','陸龜蒙','quantangshi','','卷35','三清今日聚灵官，玉刺齐抽谒广寒。
执盖冒花香寂历，侍晨交佩响阑珊。
将排凤节分阶易，欲校龙书下笔难。
唯有世尘中小兆，夜来心拜七星坛。','',''),('quantangshi-34370','正月十五惜春寄袭美','陸龜蒙','quantangshi','','卷35','六分春色一分休，满眼东波尽是愁。
花匠凝寒应束手，酒龙多病尚垂头。
无穷嬾惰齐中散，有底机谋敌右侯。
见织短篷裁小檝，拿烟闲弄个渔舟。','',''),('quantangshi-34371','袭美病中闻余游颜家园见寄次韵酬之','陸龜蒙','quantangshi','','卷35','日华风蕙正交光，羯末相携籍草塘。
佳酒旋倾醽醁嫩，短船闲弄木兰香。
烟丝鸟拂来萦带，蘂榼人收去约簧。
今日好为联句会，不成刚为欠檀郎。','',''),('quantangshi-34372','春雨即事寄袭美','陸龜蒙','quantangshi','','卷35','小谢轻埃日日飞，城边江上阻春晖。
虽愁野岸花房冻，还得山家药笋肥。
双屐着频看齿折，败裘披苦见毛稀。
比邻钓叟无尘事，洒笠鸣蓑夜半归。','',''),('quantangshi-34373','奉和袭美抱疾杜门见寄次韵','陸龜蒙','quantangshi','','卷35','虽失春城醉上期，下帷裁徧未裁诗。
因吟郢岸百亩蕙，[欲]采商崖三秀枝。
栖野鹤笼宽使织，施山僧饭别教炊。
但医沈约重瞳健，不怕江花不满枝。','',''),('quantangshi-34374','偶掇野蔬寄袭美有作','陸龜蒙','quantangshi','','卷35','野园烟里自幽寻，嫩甲香蕤引渐深。
行歇每依鵶舅影，挑频时见鼠姑心。
凌风蔼彩初携笼，带露虚疎或贮襟。
欲助春盘还爱否，不妨萧洒似家林。','',''),('quantangshi-34375','奉和袭美卧疾感春见寄次韵','陸龜蒙','quantangshi','','卷35','共寻花思极飞腾，病带春寒去未能。
烟径水涯多好鸟，竹牀蒲椅但高僧。
须知日富为神授，秖有家贫免盗憎。
除却数函图籍外，更将何事结良朋。','',''),('quantangshi-34376','徐方平后闻赦因寄袭美','陸龜蒙','quantangshi','','卷35','新春旒扆御翚轩，海内初传涣汗恩。
秦狱已收为厉气，瘴江初返未招魂。
英材尽作龙蛇蛰，战地多成虎豹村。
除却数般伤痛外，不知何事及王孙。','',''),('quantangshi-34377','袭美以鱼牋见寄因谢成篇','陸龜蒙','quantangshi','','卷35','捣成霜粒细鳞鳞，知作愁吟喜见分。
向日乍惊新茧色，临风时辨白萍文。
好将花下承金粉，堪送天边咏碧云。
见倚小窗亲襞染，尽图春色寄夫君。','',''),('quantangshi-34378','次和袭美病后春思','陸龜蒙','quantangshi','','卷35','气和灵府渐氤氲，酒有贤人药有君。
七字篇章看月得，百劳言语傍花闻。
闲寻古寺消晴日，最忆深溪枕夜云。
早晚共摇孤艇去，紫屏风外碧波文。','',''),('quantangshi-34379','袭美以公斋小宴见招因代书寄之','陸龜蒙','quantangshi','','卷35','早云才破漏春阳，野客晨兴喜又忙。
自与酌量煎药水，别教安置晒书牀。
依方酿酒愁迟去，借样裁巾怕索将。
唯待数般幽事了，不妨还入少年场。','',''),('quantangshi-34380','京口','陸龜蒙','quantangshi','','卷35','江干古渡伤离情，断山零落春潮平。
东风料峭客帆远，落叶夕阳天际明。
战舸昔浮千骑去，钓舟今载一翁轻。
可怜宋帝筹帷处，苍翠无烟草自生。','',''),('quantangshi-34381','润州送人往长洲','陸龜蒙','quantangshi','','卷35','秋来频上向吴亭，每上思归意剩生。
废苑池台烟里色，夜村蓑笠雨中声。
汀洲月下菱船疾，杨柳风高酒斾轻。
君住松江多少日，为尝鲈鲙与莼羹。','',''),('quantangshi-34382','润州江口送人谒池阳卫郎中','陸龜蒙','quantangshi','','卷35','山翁曾约旧交欢，须拂侯门侧注冠。
月在石头摇戍角，风生江口亚帆竿。
闲随野醉溪声闹，独伴清谭晓色残。
待取新秋归更好，九华苍翠入楼寒。','',''),('quantangshi-34383','袭美以纱巾见惠继以雅音因次韵酬谢','陸龜蒙','quantangshi','','卷35','薄如蝉翅背斜阳，不称春前赠𦊔郎。
初觉顶寒生远吹，预忧头白透新霜。
堪窥水槛澄波影，好拂花墙亚蘂香。
知有芙蓉留自戴，欲峨烟雾访黄房。','',''),('quantangshi-34384','闻袭美有亲迎之期因以寄贺','陸龜蒙','quantangshi','','卷35','梁鸿夫妇欲双飞，细雨轻寒拂雉衣。
初下雪窗因眷恋，次乘烟幰奈光辉。
参差扇影分华月，断续箫声落翠微。
见说春风偏有贺，露花千朵照庭闱。','',''),('quantangshi-34385','袭美以巨鱼之半见分因以酬谢','陸龜蒙','quantangshi','','卷35','谁与春江上信鱼，可怜霜刃截来初。
鳞隳似撤骚人屋，腹断疑伤远客书。
避网几跳山影破，逆风曾蹙浪花虚。
今朝最是家童喜，免泥荒畦掇野蔬。','',''),('quantangshi-34386','奉和袭美馆娃宫怀古次韵','陸龜蒙','quantangshi','','卷35','镂楣消落濯春雨，苍翠无言空断崖。
草碧未能忘帝女，燕轻犹自识宫钗。
江山祗有愁容在，劒佩应和愧色埋。
赖在伍员骚思少，吴王才免似荆怀。','',''),('quantangshi-34387','同袭美游北禅院','陸龜蒙','quantangshi','','卷35','连延花蔓映风廊，岸帻披襟到竹房。
居士祗今开梵处，先生曾是草玄堂。
清尊林下看香印，远岫窗中挂钵囊。
今日有情消未得，欲将名理问思光。','',''),('quantangshi-34388','袭美以紫石砚见赠以诗迎之','陸龜蒙','quantangshi','','卷35','霞骨坚来玉自愁，琢成飞燕古钗头。
澄沙脆弱闻应伏，青铁沈埋见亦羞。
最称风亭批碧简，好将云窦渍寒流。
君能把赠闲吟客，徧写江南物象酬。','',''),('quantangshi-34389','和袭美送孙发百篇游天台','陸龜蒙','quantangshi','','卷35','直应天授与诗情，百咏唯消一日成。
去把彩毫挥下国，归参黄绶别春卿。
闲窥碧落怀烟雾，暂向金庭隐姓名。
珍重兴公徒有赋，石梁深处是君行。','',''),('quantangshi-34390','奉和袭美闻开元寺开笋园寄章上人','陸龜蒙','quantangshi','','卷35','春龙争地养檀栾，况是双林雨后看。
迸出似毫当垤㙞，孤生如恨倚栏干。
凌虚势欲齐金刹，折赠光宜照玉盘。
更得锦苞零落后，粉环高下局烟寒。','',''),('quantangshi-34391','蔷薇','陸龜蒙','quantangshi','','卷35','倚墙当户自横陈，致得贫家似不贫。
外布芳菲虽笑日，中含芒刺欲伤人。
清香往往生遥吹，狂蔓看看及四邻。
遇有客来堪玩处，一端晴绮照烟新。','',''),('quantangshi-34392','奉和袭美开元寺佛钵诗','陸龜蒙','quantangshi','','卷35','空王初受逞神功，四钵须臾现一重。
持次想添香积饭，覆时应带步罗钟。
光寒好照金毛鹿，响静堪降白耳龙。
从此宝函香里见，不须西去诣灵峰。','',''),('quantangshi-34393','酬袭美夏首病愈见招次韵','陸龜蒙','quantangshi','','卷35','雨多青合是垣衣，一幅蛮牋夜欵扉。
蕙带又闻宽沈约，茅斋犹自忆王微。
方灵祗在君臣正，篆古须抛点画肥。
除却伴谈秋水外，野鸥何处更忘机。','',''),('quantangshi-34394','新夏东郊闲泛有怀袭美','陸龜蒙','quantangshi','','卷35','迟于春日好于秋，野客相携上钓舟。
经略彴时冠暂亚，佩笭箵后带频搊。
蒹葭鹭起波摇笠，村落蚕眠树挂钩。
料得祗君能爱此，不争烟水似封侯。','',''),('quantangshi-34395','四月十五日道室书事寄袭美','陸龜蒙','quantangshi','','卷35','乌饭新炊芼臛香，道家斋日以为常。
月苗杯举存三洞，云蘂函开叩九章。
一掬阳泉堪作雨，数铢秋石欲成霜。
可中值着雷平信，为觅闲眠苦竹牀。','',''),('quantangshi-34396','看压新醅寄怀袭美','陸龜蒙','quantangshi','','卷35','晓压糟牀渐有声，旋如[荒]涧野泉清。
身前古态熏应出，世上愁痕滴合平。
饮啄断年同鹤俭，风波终日看人争。
尊中若使常能渌，两绶通侯总强名。','',''),('quantangshi-34397','奉和袭美登初阳楼寄怀北平郎中','陸龜蒙','quantangshi','','卷35','远窗浮槛亦成年，几伴杨公白昼筵。
日暖烟花曾扑地，气浮星象却归天。
闲将水石侵军垒，醉引笙歌上钓船。
无限恩波犹在目，东风吹起细漪涟。','',''),('quantangshi-34398','奉和夏初袭美见访题小斋次韵','陸龜蒙','quantangshi','','卷35','四邻多是老农家，百树鸡桑半顷麻。
尽趁[晴]明修网架，每和烟雨掉缲车。
啼鸾偶坐身藏叶，饷妇归来鬓有花。
不是对君吟复醉，更将何事送年华。','',''),('quantangshi-34399','奉和袭美所居首夏水木尤清适然有作次韵','陸龜蒙','quantangshi','','卷35','柿阴成列药花空，却忆桐江下钓筒。
亦以鱼虾供熟鹭，近缘樱笋识邻翁。
闲分酒剂多还少，自记书签白间红。
更爱夜来风月好，转思玄度对支公。','',''),('quantangshi-34400','奉和袭美题达上人药圃二首 一','陸龜蒙','quantangshi','','卷35','药味多从远客赍，旋添花圃旋成畦。
三桠旧种根应异，九节初移叶尚低。
山荚便和幽涧石，水芝须带本池泥。
从今直到清秋日，又有香苗几番齐。','',''),('quantangshi-34401','奉和袭美题达上人药圃二首 二','陸龜蒙','quantangshi','','卷35','净名无语示清羸，药草搜来喻更微。
一雨一风皆遂性，花开花落尽忘机。
教疏兔镂金弦乱，自拥龙刍紫汞肥。
莫怪独亲幽圃坐，病容销尽欲依归。','',''),('quantangshi-34402','奉和袭美怀华阳润卿博士三首 一','陸龜蒙','quantangshi','','卷35','几降真官授隐书，洛公曾到梦中无。
眉间入静三辰影，肘后通灵五岳图。
北洞树形如曲盖，东凹山色入薰炉。
金墟福地能容否，愿作冈前蒋负刍。','',''),('quantangshi-34403','奉和袭美怀华阳润卿博士三首 二','陸龜蒙','quantangshi','','卷35','火景应难到洞宫，萧闲堂冷任天风。
谈玄麈尾抛云底，服散龙胎在酒中。
有路还将赤城接，无泉不共紫河通。
奇编早晚教传授，免以神仙问葛洪。','',''),('quantangshi-34404','奉和袭美怀华阳润卿博士三首 三','陸龜蒙','quantangshi','','卷35','终日焚香礼洞云，更思琪树转劳神。
曾寻下泊常经月，不到中峰又累春。
仙道最高黄玉箓，暑天偏称白纶巾。
清斋若见茅司命，乞取朱儿十二斤。','',''),('quantangshi-34405','以竹夹膝寄赠袭美','陸龜蒙','quantangshi','','卷35','截得篔簹冷似龙，翠光横在暑天中。
堪临薤簟闲凭月，好向松窗卧跂风。
持赠敢齐青玉案，醉吟偏称碧荷筒。
添君雅具教多着，为着西斋谱一通。','',''),('quantangshi-34406','奉和袭美夏景无事因怀章来二上人次韵 一','陸龜蒙','quantangshi','','卷35','檐外青阳有二梅，折来堪下冻醪杯。
高杉自欲生龙脑，小弁谁能寄鹿胎。
丽事肯教饶沈谢，谈微何必减宗雷。
还闻拟结东林社，争奈渊明醉不来。','',''),('quantangshi-34407','奉和袭美夏景无事因怀章来二上人次韵 二','陸龜蒙','quantangshi','','卷35','忽忆高僧坐夏堂，厌泉声闹笑云忙。
山重海澹怀中印，月冷风微宿上方。
病后书求嵩少药，定回衣染贝多香。
何时更问逍遥义，五粒松阴半石牀。','',''),('quantangshi-34408','顷自桐江得一钓车以袭美乐烟波之思因出以为玩俄辱三篇复抒酬答 一','陸龜蒙','quantangshi','','卷35','旋屈金钩劈翠筠，手中盘作钓鱼轮。
忘情不效孤醒客，有意闲窥百丈鳞。
雨似轻埃时一起，云如高盖强相亲。
任他华毂低头笑，此地终无覆败人。','',''),('quantangshi-34409','顷自桐江得一钓车以袭美乐烟波之思因出以为玩俄辱三篇复抒酬答 二','陸龜蒙','quantangshi','','卷35','曾招渔侣下清浔，独茧初随一锤深。
细辗烟华无辙迹，静含风力有车音。
相呼野饭依芳草，迭和山歌逗远林。
得失任渠但取乐，不曾生个是非心。','',''),('quantangshi-34410','顷自桐江得一钓车以袭美乐烟波之思因出以为玩俄辱三篇复抒酬答 三','陸龜蒙','quantangshi','','卷35','病来县着脆缗丝，独喜高情为我持。
数幅尚凝烟雨态，三篇能赋蕙兰词。
云深石静闲眠稳，月上江平放溜迟。
第一莫教谙此境，倚天功业待君为。','',''),('quantangshi-34411','奉和袭美吴中书事寄汉南裴尚书','陸龜蒙','quantangshi','','卷35','风清地古带前朝，遗事纷纷未寂寥。
三泖凉波鱼蕝动，五茸春草雉媒娇。
云藏野寺分金刹，月在江楼倚玉箫。
不用怀归忘此景，吴王看即奉弓招。','',''),('quantangshi-34412','奉和袭美夏景冲澹偶作次韵二首 一','陸龜蒙','quantangshi','','卷35','蝉雀参差在扇纱，竹襟轻利箨冠斜。
垆中有酒文园会，琴上无弦靖节家。
芝畹烟霞全覆穗，橘洲风浪半浮花。
闲思两地忘名者，不信人间髪解华。','',''),('quantangshi-34413','奉和袭美夏景冲澹偶作次韵二首 二','陸龜蒙','quantangshi','','卷35','祗于池曲象山幽，便是潇湘浸石楼。
斜拂芡盘轻鹜下，细穿菱线小鲵游。
闲开茗焙尝须徧，醉拨书帷卧始休。
莫道仙家无好爵，方诸还拜碧琳侯。','',''),('quantangshi-34414','奉和袭美送李明府之任南海','陸龜蒙','quantangshi','','卷35','春尽之官直到秋，岭云深处凭泷楼。
居人爱近沈珠浦，候吏多来拾翠洲。
賨税尽应输紫贝，蛮童多学佩金钩。
知君不恋南枝久，抛却经冬白罽裘。','',''),('quantangshi-34415','奉和袭美寄题罗浮轩辕先生所居','陸龜蒙','quantangshi','','卷35','鼎成仙驭入崆峒，百世犹传至道风。
暂应青词为穴凤，却思丹徼伴冥鸿。
金公的的生炉际，琼刃时时到梦中。
预恐浮山归有日，载将云室十洲东。','',''),('quantangshi-34416','奉和袭美寄琼州杨舍人','陸龜蒙','quantangshi','','卷35','明时非罪谪何偏，鵩鸟巢南更数千。
酒满椰杯消毒雾，风随蕉叶下泷船。
人多药户生狂蛊，吏有珠官出俸钱。
祗以直诚天自信，不劳诗句咏贪泉。','',''),('quantangshi-34417','奉和袭美宿报恩寺水阁','陸龜蒙','quantangshi','','卷35','峰抱池光曲岸平，月临虚槛夜何清。
僧穿小桧才分影，鱼掷高荷渐有声。
因忆故山吟易苦，各横秋簟梦难成。
周颙不用裁书劝，自得凉天证道情。','',''),('quantangshi-34418','奉和袭美醉中偶作见寄次韵','陸龜蒙','quantangshi','','卷35','海鹤飘飘韵莫侪，在公犹与俗情乖。
初呈酒务求专判，合祷山祠请自差。
永夜谭玄侵罔象，一生交态忘形骸。
怜君醉墨风流甚，几度题诗小谢斋。','',''),('quantangshi-34419','奉和袭美寄滑州李副使员外','陸龜蒙','quantangshi','','卷35','洛生闲咏正抽毫，忽傍旌旗着战袍。
檄下连营皆破胆，劒离孤匣欲吹毛。
清秋月色临军垒，半夜淮声入贼壕。
除却征南为上将，平徐功业更谁高。','',''),('quantangshi-34420','奉和袭美吴中言怀寄南海二同年','陸龜蒙','quantangshi','','卷35','曾见凌风上赤霄，尽将华藻赴嘉招。
城连虎踞山图丽，路入龙编海舶遥。
江客渔歌冲白荇，野禽人语映红蕉。
庭中必有君迁树，莫向空台望汉朝。','',''),('quantangshi-34421','奉和袭美伤史拱山人','陸龜蒙','quantangshi','','卷35','曾说山栖欲去寻，岂知霜骨葬寒林。
常依净住师冥目，兼事容成学算心。
逋客预斋还梵唱，老猨窥祭亦悲吟。
唯君独在江云外，谁诔孤贞置岘岑。','',''),('quantangshi-34422','白鸥诗','陸龜蒙','quantangshi','','卷35','惯向溪头漾浅沙，薄烟微雨是生涯。
时时失伴沈山影，往往争飞杂浪花。
晚树清凉还𪈺鳿，旧巢零落寄蒹葭。
池塘信美应难恋，针在鱼唇劒在虾。','',''),('quantangshi-34423','怀杨台文杨鼎文二秀才','陸龜蒙','quantangshi','','卷35','秋早相逢待得春，崇兰清露小山云。
寒花独自愁中见，曙角多同醒后闻。
钓具每随轻舸去，诗题闲上小楼分。
重思醉墨纵横甚，书破羊欣白练裙。','',''),('quantangshi-34424','奉和袭美谢友人惠人参','陸龜蒙','quantangshi','','卷35','五叶初成椵树阴，紫团峰外即鸡林。
名参鬼盖须难见，材似人形不可寻。
品第已闻升碧简，携持应合重黄金。
殷勤润取相如肺，封禅书成动帝心。','',''),('quantangshi-34425','严子重以诗游于名胜间旧矣余晚于江南相遇甚乐不幸且没袭美作诗序而吊之其名真不朽矣又何戚其死哉余因息悲而为之和','陸龜蒙','quantangshi','','卷35','每值江南日落春，十年诗酒爱逢君。
芙蓉湖上吟船倚，翡翠岩前醉马分。
祗有汀洲连旧业，岂无章疏动遗文。
犹怜未卜佳城处，更斸要离冢畔云。','',''),('quantangshi-34426','算山','陸龜蒙','quantangshi','','卷35','水绕苍山固护来，当时盘踞实雄才。
周郎计策清宵定，曹氏楼船白昼灰。
五十八年争虎视，三千余骑骋龙媒。
何如今日家天下，阊阖门临万国开。','',''),('quantangshi-34427','寄茅山何威仪二首 一','陸龜蒙','quantangshi','','卷35','大小三峰次九华，灵踪今尽属何家。
汉时仙上云巅鹤，蜀地春开洞底花。
闲傍积岚寻瀑眼，便凌残雪探芝芽。
年来已奉黄庭教，夕炼腥魂晓吸霞。','',''),('quantangshi-34428','寄茅山何威仪二首 二','陸龜蒙','quantangshi','','卷35','曾向人间拜节旄，乍疑因梦到仙曹。
身轻曳羽霞襟狭，髻耸峨烟鹿帻高。
山暖不荤峰上薤，水寒仍落洞中桃。
从闻此日搜奇话，转觉魂飞夜夜劳。','',''),('quantangshi-34429','早秋吴体寄袭美','陸龜蒙','quantangshi','','卷35','荒庭古树只独倚，败蝉残蛩苦相仍。
虽然诗胆大如斗，争奈愁肠牵似绳。
短烛初添蕙幌影，微风渐折蕉衣棱。
安得弯弓似明月，快箭拂下西飞鹏。','',''),('quantangshi-34430','病中秋怀寄袭美','陸龜蒙','quantangshi','','卷35','病容愁思苦相兼，清镜无形未我嫌。
贪广异蔬行径窄，故求偏药出钱添。
同人散后休赊酒，双燕辞来始下帘。
更有是非齐未得，重凭詹尹拂龟占。','',''),('quantangshi-34431','秋赋有期因寄袭美','陸龜蒙','quantangshi','','卷35','云似无心水似闲，忽思名在贡书间。
烟霞鹿弁聊悬着，隣里渔舠暂解还。
文章病来犹满箧，药苗衰后即离山。
广寒宫树枝多少，风送高低便可攀。','',''),('quantangshi-34432','和袭美新秋即事次韵三首 一','陸龜蒙','quantangshi','','卷35','心似孤云任所之，世尘中更有谁知。
愁寻冷落惊双鬓，病得清凉减四支。
怀旧药溪终独往，宿枯杉寺已频期。
兼须为月求高处，即是霜轮杀满时。','',''),('quantangshi-34433','和袭美新秋即事次韵三首 二','陸龜蒙','quantangshi','','卷35','帆檝衣裳尽钓徒，往来踪迹遍三吴。
闲中展卷兴亡小，醉后题诗点画麤。
松岛伴谭多道气，竹窗孤梦岂良图。
还须待致升平了，即往扁舟放五湖。','',''),('quantangshi-34434','和袭美新秋即事次韵三首 三','陸龜蒙','quantangshi','','卷35','声利从来解破除，秋滩唯忆下桐庐。
鸬鷀阵合残阳少，蜻蛚吟高冷雨疎。
辩伏南华论指指，才非玄晏借书书。
当时任使真堪笑，波上三年学炙鱼。','',''),('quantangshi-34435','和袭美赠南阳润卿将归雷平','陸龜蒙','quantangshi','','卷35','朝市山林隐一般，却归那减卧云懽。
堕阶红叶谁收得，半盎清醪客酹干。
玉笈诗成吟处晓，金沙泉落梦中寒。
真仙若降如相问，曾步星罡绕醮坛。','',''),('quantangshi-34436','顾道士亡弟子奉束帛乞铭于袭美因赋戏赠','陸龜蒙','quantangshi','','卷35','童初真府召为郎，君与抽毫刻便房。
亦谓神仙同许郭，不妨才力似班扬。
比于黄绢词尤妙，酬以霜缣价未当。
唯我有文无卖处，笔锋销尽墨池荒。','',''),('quantangshi-34437','和访寂上人不遇','陸龜蒙','quantangshi','','卷35','芭蕉霜后石栏荒，林下无人闭竹房。
经抄未成抛素几，锡环应撼过寒塘。
蒲团为拂浮埃散，茶器空怀碧饽香。
早晚却还宗炳社，夜深风雪对禅牀。','',''),('quantangshi-34438','秋夕文宴','陸龜蒙','quantangshi','','卷35','笔阵初临夜正清，击铜遥认小金钲。
飞觥壮若游燕市，觅句难于下赵城。
隔岭故人因会忆，傍檐栖鸟带吟惊。
梁王座上多词客，五韵甘心第七成。','',''),('quantangshi-34439','南阳广文欲于荆襄卜居袭美有赠代酬次韵','陸龜蒙','quantangshi','','卷35','不知天隐在何乡，且欲烟霞迹暂双。
鹤庙未能齐月驭，鹿门聊拟竝云窗。
藓衔荒磴移桑屐，花浸春醪挹石缸。
莫惜查头容钓伴，也应东印有余江。','',''),('quantangshi-34440','和袭美寄毗陵魏处士朴','陸龜蒙','quantangshi','','卷35','经苑初成墨沼开，何人林下肯寻来。
若非宗测图山后，即是韩康卖药回。
溪籁自吟朱鹭曲，沙云还作白鸥媒。
唯应地主公田熟，时送君家麴糵材。','',''),('quantangshi-34441','和袭美初冬偶作寄南阳润卿次韵','陸龜蒙','quantangshi','','卷35','逐日生涯敢计冬，可嗟寒事落然空。
窗怜返照缘书小，庭喜新霜为橘红。
衰柳尚能和月动，败兰犹拟倩烟笼。
不知海上今清浅，试与飞书问洛公。','',''),('quantangshi-34442','和袭美冬晓章上人院','陸龜蒙','quantangshi','','卷35','山寒偏是晓来多，况值禅窗雪气和。
病客功夫经未演，故人书信纳新磨。
闲临静案修茶品，独傍深溪记药科。
从此逍遥知有地，更乘清月伴君过。','',''),('quantangshi-34443','和袭美寄题镜岩周尊师所居','陸龜蒙','quantangshi','','卷35','见说身轻鹤不如，石房无侣共云居。
清晨自削灵香柹，独夜空吟碧落书。
十洞飞精应徧吸，一簪秋髪未曾梳。
知君便入悬珠会，早晚东骑白鲤鱼。','',''),('quantangshi-34444','寒夜文宴得惊字','陸龜蒙','quantangshi','','卷35','各将寒调触诗情，旋见微澌入砚生。
霜月满庭人暂起，汀洲半夜雁初惊。
三秋每为仙题想，一日多因累句倾。
千里建康衰草外，含毫谁是忆昭明。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34445','送润卿还华阳','陸龜蒙','quantangshi','','卷35','何事轻舟近腊回，茅家兄弟欲归来。
封题玉洞虚无奏，点检霜坛沆瀣杯。
云肆先生分气调，山图公子爱词才。
殷勤为向东乡荐，洒扫含真雪后台。','',''),('quantangshi-34446','和袭美为新罗弘惠上人撰灵鹫山周禅师碑送归诗','陸龜蒙','quantangshi','','卷35','一函迢递过东瀛，祗为先生处乞铭。
已得雄词封静检，却怀孤影在禅庭。
春过异国人应写，夜读沧洲怪亦听。
遥想勒成新塔下，尽望空碧礼文星。','',''),('quantangshi-34447','和袭美寒日书斋即事三首每篇各用一韵 一','陸龜蒙','quantangshi','','卷35','不必探幽上郁冈，公斋吟啸亦何妨。
唯求薏苡供僧食，别着氍毹待客牀。
春近带烟分短蕙，晓来冲雪撼疎篁。
余杭山酒犹封在，遥嘱高人未肯尝。','',''),('quantangshi-34448','和袭美寒日书斋即事三首每篇各用一韵 二','陸龜蒙','quantangshi','','卷35','已上星津八月槎，文通犹自学丹砂。
仙经写得空三洞，隐士招来别九华。
静对真图呼绿齿，偶开神室问黄芽。
方诸更是怜才子，锡赉于君合有差。','',''),('quantangshi-34449','和袭美寒日书斋即事三首每篇各用一韵 三','陸龜蒙','quantangshi','','卷35','名价皆酬百万余，尚怜方丈讲玄虚。
西都宾问曾成赋，东海人求近着书。
茅洞烟霞侵寤寐，檀溪风月挂樵渔。
清朝还要廷臣在，两地宁容便结庐。','',''),('quantangshi-34450','和袭美腊后送内大德从朂游天台','陸龜蒙','quantangshi','','卷35','应缘南国尽南宗，欲访灵溪路暗通。
归思不离双阙下，去程犹在四明东。
铜瓶净贮桃花雨，金策闲摇麦穗风。
若恋吾君先拜疏，为论台岳未封公。','',''),('quantangshi-34451','和袭美寄题玉霄峰叶涵象尊师所居','陸龜蒙','quantangshi','','卷35','天台一万八千丈，师在浮云端掩扉。
永夜祗知星斗大，深秋犹见海山微。
风前几降青毛节，雪后应披白羽衣。
南望烟霞空再拜，欲将飞魄问灵威。','',''),('quantangshi-34452','南阳广文博士还雷平后寄','陸龜蒙','quantangshi','','卷35','微微春色染林塘，亲拨烟霞坐涧房。
阴洞雪胶知未入，浊醪风破的偷尝。
芝台晓用金铛煮，星度闲将玉铪量。
几遍侍晨官欲降，曙坛先起独焚香。','',''),('quantangshi-34453','和袭美题支山南峰僧次韵','陸龜蒙','quantangshi','','卷35','眉毫霜细欲垂肩，自说初栖海岳年。
万壑烟霞秋后到，一林风雨夜深禅。
时翻贝叶添新藏，间插松枝护小泉。
好是清冬无外事，匡林斋罢向阳眠。','',''),('quantangshi-34454','送董少卿游茅山','陸龜蒙','quantangshi','','卷35','威辇高悬度世名，至今仙裔作公卿。
将随羽节朝珠阙，曾佩鱼符管赤城。
云冻尚含孤石色，雪干犹堕古松声。
应知四扇灵方在，待取归时绿髪生。','',''),('quantangshi-34455','和袭美寄怀南阳润卿','陸龜蒙','quantangshi','','卷35','高抱相逢各绝尘，水经山疏不离身。
才情未拟汤从事，玄解犹嫌竺道人。
霞染洞泉浑变紫，雪披江树半和春。
谁怜故国无生计，唯种南塘二亩芹。','',''),('quantangshi-34456','袭美将以绿罽为赠因成四韵','陸龜蒙','quantangshi','','卷35','三迳风霜若利刀，襜褕吹断罥蓬蒿。
病中祗自悲龙具，世上何人识羽袍。
狐貉近怀珠履贵，薜萝遥羡白巾高。
陈王轻暖如相遗，免致衰荷效广骚。','',''),('quantangshi-34457','和过张祜处士丹阳故居','陸龜蒙','quantangshi','','卷35','胜华通子共悲辛，荒迳今为旧宅邻。
一代交游非不贵，五湖风月合教贫。
魂应绝地为才鬼，名与遗编在史臣。
闻道平生多爱石，至今犹泣洞庭人。','',''),('quantangshi-34458','和袭美寄广文先生','陸龜蒙','quantangshi','','卷35','忽辞明主事真君，直取姜巴路入云。
龙篆拜时轻诰命，霓襟披后小玄纁。
峰前北帝三元会，石上东卿九锡文。
应笑世间名利火，等闲灵府剩先焚。','',''),('quantangshi-34459','和袭美先辈悼鹤','陸龜蒙','quantangshi','','卷35','一夜圆吭绝不鸣，八公虚道得千龄。
方添上客云眠思，忽伴中仙劒解形。
但掩丛毛穿古堞，永留寒影在空屏。
君才幸自清如水，更向芝田为刻铭。','',''),('quantangshi-34460','幽居有白菊一丛因而成咏呈知己','陸龜蒙','quantangshi','','卷35','还是延年一种材，即将瑶朵冒霜开。
不如红艳临歌扇，欲伴黄英入酒杯。
陶令接䍦堪岸着，梁王高屋好欹来。
月中若有闲田地，为劝嫦娥作意裁。','',''),('quantangshi-34461','和袭美伤开元观顾道士','陸龜蒙','quantangshi','','卷35','何事神超入杳冥，不骑孤鹤上三清。
多应白简迎将去，即是朱陵炼更生。
药奠肯同椒醑味，云谣空替薤歌声。
武皇徒有飘飘思，谁问山中宰相名。','',''),('quantangshi-34462','和袭美醉中即席赠润卿博士次韵','陸龜蒙','quantangshi','','卷35','共是虚皇简上仙，清词如羽欲飘然。
登山凡着几緉屐，破浪欲乘千里船。
远梦只留丹井畔，闲吟多在酒旗前。
谁知海上无名者，只记渔歌不记年。','',''),('quantangshi-34463','送浙东德师侍御罢府西归','陸龜蒙','quantangshi','','卷35','王谢遗踪玉籍仙，三年闲上鄂君船。
诗怀白阁僧吟苦，俸买青田鹤价偏。
行次野枫临远水，醉中衰菊卧凉烟。
芙蓉散尽西归去，唯有山阴九万牋。','',''),('quantangshi-34464','送羊振文先辈往桂阳归觐','陸龜蒙','quantangshi','','卷35','风雅先生去一麾，过庭才子趣归期。
让王门外开帆叶，义帝城中望戟支。
郢路渐寒飘雪远，湘波初暖涨云迟。
灵均精魄如能问，又得千年贾傅词。','',''),('quantangshi-34465','袭美留振文宴龟蒙抱病不赴猥示倡和因次韵酬谢','陸龜蒙','quantangshi','','卷35','绮席风开照露晴，祗将茶荈代云觥。
繁弦似玉纷纷碎，佳妓如鸿一一惊。
毫健几多飞藻客，羽寒寥落映花莺。
幽人独自西窗晚，闲凭香柽反照明。','',''),('quantangshi-34466','和袭美重送圆载上人归日本国','陸龜蒙','quantangshi','','卷35','老思东极旧岩扉，却待秋风泛舶归。
晓梵阳乌当石磬，夜禅阴火照田衣。
见翻经论多盈箧，亲植杉松大几围。
遥想到时思魏阙，只应遥拜望斜晖。','',''),('quantangshi-34467','和袭美褚家林亭','陸龜蒙','quantangshi','','卷35','一阵西风起浪花，绕栏杆下散瑶华。
高窗曲槛仙侯府，卧苇荒芹白鸟家。
孤岛待寒凝片月，远山终日送余霞。
若知方外还如此，不要秋乘上海槎。','',''),('quantangshi-34468','归雁','陸龜蒙','quantangshi','','卷35','北走南征象我曹，天涯迢递翼应劳。
似悲边雪音犹苦，初背岳云行未高。
月岛聚栖防暗缴，风滩斜起避惊涛。
时人不问随阳意，空拾栏边翡翠毛。','',''),('quantangshi-34469','王先辈草堂','陸龜蒙','quantangshi','','卷35','松迳隈云到静堂，杏花临涧水流香。
身从乱后全家隐，日校人间一倍长。
金箓渐加新品秩，玉皇偏赐羽衣裳。
何如圣代弹冠出，方朔曾为汉侍郎。','',''),('quantangshi-34470','伤越','陸龜蒙','quantangshi','','卷35','越溪自古好风烟，盗束兵缠已半年。
访戴客愁随水远，浣纱人泣共埃捐。
临焦赖洒王师雨，欲堕重登刺史天。
早晚山川尽如故，清吟闲上鄂君船。','',''),('quantangshi-34471','新定陪太守一百五夜南馆玩月','陸龜蒙','quantangshi','','卷35','风雨教春处处伤，一宵云尽见沧浪。
全无片烛侵光彩，只有清滩助雪霜。
烟蔽棹歌归浦潊，露将花影到衣裳。
却嫌殷浩南楼夕，一带秋声入恨长。','',''),('quantangshi-34472','中元夜寄道侣二首 一','陸龜蒙','quantangshi','','卷35','学饵霜茸骨未轻，每逢真夕梦还清。
丁宁独受金妃约，许与亲题玉篆名。
月苦撼残临水佩，风微飘断系云缨。
须臾枕上桐窗晓，露压千枝滴滴声。','',''),('quantangshi-34473','中元夜寄道侣二首 二','陸龜蒙','quantangshi','','卷35','橘斋风露已清余，东郭先生病未除。
孤枕易为蛩破梦，短檐难得燕传书。
广云披日君应近，倒影裁花我尚疎。
唯羡羽人襟似水，平持旄节步空虚。','',''),('quantangshi-34474','寄怀华阳道士','陸龜蒙','quantangshi','','卷35','华阳门外五芝生，飡罢愁君入杳冥。
遥夜独栖还有梦，昔年相见便忘形。
为分科斗亲铅椠，与说蜉蝣坐竹棂。
醮后几时归紫阁，别来终日诵黄庭。
闲教辨药僮名甲，静识窥巢鹤姓丁。
绝涧饮羊春水腻，傍林烧石野烟腥。
深沈谷响含疎磬，片段岚光落画屏。
休采古书探禹穴，自刊新历鬬尧蓂。
珠宫凤合迎萧史，玉籍人谁访蔡经。
架上黑椽长褐稳，案头丹篆小符灵。
霓轩入洞齐初月，羽节升坛拜七星。
当路独行冲虎豹，向风孤啸起雷庭。
凝神密室多生白，叙事聊编尽杀青。
匝地山川皆暗写，隐天竽籁祗闲听。
分张火力烧金竈，拂拭苔痕洗酒瓶。
翠壁上吟朝复暮，暖云边卧醉还醒。
倚身长短裁筇杖，倩客高低结草亭。
直用森严朝北帝，爱将清浅问东溟。
常思近圃看栽杏，拟借邻峰伴采苓。
揜树半扉晴霭霭，背琴残烛晓荧荧。
旧来扪虱知王猛，欲去为龙叹管宁。
蟾魄几应临蕙帐，渔竿犹尚枕枫汀。
衔烟细草无端绿，冒雨闲花作意馨。
掠岸惊波沈翡翠，入檐斜照碍蜻蜓。
初征汉栈宜飞檄，待破燕山好勒铭。
六辔未收千里马，一囊空负九秋萤。
我悲雌伏真方枘，他骋雄材似建瓴。
合在深崖齐散术，自求沧海点流萍。
频抛俗物心还爽，远忆幽期目剩暝。
见买扁舟束真诰，手披仙语任扬舲。','',''),('quantangshi-34475','人日代客子','陸龜蒙','quantangshi','','卷35','人日兼春日，长怀复短怀。
遥知双彩胜，并在一金钗。','',''),('quantangshi-34476','筑城词二首 一','陸龜蒙','quantangshi','','卷35','城上一培土，手中千万杵。
筑城畏不坚，坚城在何处。','',''),('quantangshi-34477','筑城词二首 二','陸龜蒙','quantangshi','','卷35','莫叹将军逼，将军要却敌。
城高功亦高，尔命何劳惜。','',''),('quantangshi-34478','古意','陸龜蒙','quantangshi','','卷35','君心莫淡薄，妾意正栖托。
愿得双车轮，一夜生四角。','',''),('quantangshi-34479','春晓','陸龜蒙','quantangshi','','卷35','春庭晓景别，清露花逦迤。
黄蜂一过慵，夜夜栖香蘂。','',''),('quantangshi-34480','杂兴','陸龜蒙','quantangshi','','卷35','桃李傍檐楹，无人赏春华。
时情重不见，却忆菖蒲花。','',''),('quantangshi-34481','雁','陸龜蒙','quantangshi','','卷35','南北路何长，中间万弋张。
不知烟雾里，几只到衡阳。','',''),('quantangshi-34482','寄远','陸龜蒙','quantangshi','','卷35','鬓乱羞云卷，眉空羡月生。
中原犹将将，何日重卿卿。','',''),('quantangshi-34483','庭前','陸龜蒙','quantangshi','','卷35','合欢能解恚，萱草信忘忧。
尽向庭前种，萋萋特地愁。','',''),('quantangshi-34484','洞房怨','陸龜蒙','quantangshi','','卷35','玉锸朝扶鬓，金梯晚下台。
春衫将别泪，一夜两难裁。','',''),('quantangshi-34485','江行','陸龜蒙','quantangshi','','卷35','酒旗菰叶外，楼影浪花中。
醉帆张数幅，唯待鲤鱼风。','',''),('quantangshi-34486','巫峡','陸龜蒙','quantangshi','','卷35','巫峡七百里，巫山十二重。
年年自云雨，环佩竟谁逢。','',''),('quantangshi-34487','归路','陸龜蒙','quantangshi','','卷35','渐入新丰路，衰红映小桥。
浑如七年病，初得一丸销。','',''),('quantangshi-34488','南塘曲','陸龜蒙','quantangshi','','卷35','妾住东湖下，郎居南浦边。
闲临烟水望，认得采菱船。','',''),('quantangshi-34489','黄金二首 一','陸龜蒙','quantangshi','','卷35','自古黄金贵，犹沽骏与才。
近来簪珥重，无可上高台。','',''),('quantangshi-34490','黄金二首 二','陸龜蒙','quantangshi','','卷35','平分从满箧，醉掷任成堆。
