城中皆一尺，非妾髻鬟高。','',''),('quantangshi-34494','大堤','陸龜蒙','quantangshi','','卷35','大堤春日暮，骢马解镂衢。
请君留上客，容妾荐雕胡。','',''),('quantangshi-34495','金陵道','陸龜蒙','quantangshi','','卷35','北雁行行直，东流澹澹春。
当时六朝客，还道帝乡人。','',''),('quantangshi-34496','离骚','陸龜蒙','quantangshi','','卷35','天问复招魂，无因彻帝阍。
岂知千丽句，不敌一谗言。','',''),('quantangshi-34497','对酒','陸龜蒙','quantangshi','','卷35','后代称欢伯，前贤号圣人。
