小炉低幌还遮掩，酒滴灰香似去年。','',''),('quantangshi-34602','袭美醉中寄一壶并一绝走笔次韵奉酬','陸龜蒙','quantangshi','','卷35','酒痕衣上杂莓苔，犹忆红螺一两杯。
正被遶篱荒菊笑，日斜还有白衣来。','',''),('quantangshi-34603','再和次韵','陸龜蒙','quantangshi','','卷35','堦下饥禽啄嫩苔，野人方倒病中杯。
寒蔬卖却还沽吃，可有金貂换得来。','',''),('quantangshi-34604','和袭美重玄寺双矮桧','陸龜蒙','quantangshi','','卷35','可怜烟刺是青螺，如到双林误礼多。
更忆早秋登北固，海门苍翠出晴波。','',''),('quantangshi-34605','醉中戏赠袭美','陸龜蒙','quantangshi','','卷35','南北风流旧不同，伧吴今日若相通。
病来犹伴金杯满，欲得人呼小褚公。','',''),('quantangshi-34606','润卿遗青䭀饭兼之一绝聊用答谢','陸龜蒙','quantangshi','','卷35','旧闻香积金仙食，今见青精玉斧餐。
自笑镜中无骨录，可能飞上紫云端。','',''),('quantangshi-34607','文宴招润卿博士辞以道侣将至一绝寄之','陸龜蒙','quantangshi','','卷35','仙客何时下鹤翎，方瞳如水脑华清。
不过传达杨君梦，从许人间小兆听。','',''),('quantangshi-34608','再招','陸龜蒙','quantangshi','','卷35','遥知道侣谈玄次，又是文交丽事时。
虽是寒轻云重日，也留花簟待徐摛。','',''),('quantangshi-34609','玩金鸂𪆟戏赠袭美','陸龜蒙','quantangshi','','卷35','曾向溪边泊暮云，至今犹忆浪花羣。
不知镂羽凝香雾，堪与鸳鸯觉后闻。','',''),('quantangshi-34610','子规一首','陸龜蒙','quantangshi','','卷35','碧竿微露月玲珑，谢豹伤心独叫风。
高处已应闻滴血，山榴一夜几枝红。','',''),('quantangshi-34611','寄题天台国清寺齐梁体','陸龜蒙','quantangshi','','卷35','峰带楼台天外立，明河色近罘罳湿。
松间石上定僧寒，半夜楢溪水声急。','',''),('quantangshi-34612','奉和谏议酬先辈霜菊','陸龜蒙','quantangshi','','卷35','紫茎芳艳照西风，秖怕霜华掠断丛。
争奈病夫难强饮，应须速自召车公。','',''),('quantangshi-34613','和袭美咏臯桥','陸龜蒙','quantangshi','','卷35','横截春流架断虹，凭栏犹思五噫风。
今来未必非梁孟，却是无人断伯通。','',''),('quantangshi-34614','和袭美悼鹤','陸龜蒙','quantangshi','','卷35','酆都香稻字重思，遥想飞魂去未饥。
争奈野鸦无数健，黄昏来占旧栖枝。','',''),('quantangshi-34615','和醉中袭美先起次韵','陸龜蒙','quantangshi','','卷35','莫唱艳歌凝翠黛，已通仙籍在金闺。
他时若寄相思泪，红粉痕应伴紫泥。','',''),('quantangshi-34616','和袭美酒病偶作次韵','陸龜蒙','quantangshi','','卷35','柳疎桐下晚窗明，秖有微风为析酲。
唯欠白绡笼解散，洛生闲咏两三声。','',''),('quantangshi-34617','忆白菊','陸龜蒙','quantangshi','','卷35','稚子书传白菊开，西成相滞未容回。
月明阶下窗纱薄，多少清香透入来。','',''),('quantangshi-34618','和同润卿寒夜访袭美各惜其志次韵','陸龜蒙','quantangshi','','卷35','醉韵飘飘不可亲，掉头吟侧华阳巾。
如能跂脚南窗下，便是羲皇世上人。','',''),('quantangshi-34619','和袭美寒夜文宴润卿有期不至','陸龜蒙','quantangshi','','卷35','细雨轻觞玉漏终，上清词句落吟中。
松斋一夜怀贞白，霜外空闻五粒风。','',''),('quantangshi-34620','移石盆','陸龜蒙','quantangshi','','卷35','移得龙泓潋滟寒，月轮初下白云端。
无人尽日澄心坐，倒影新篁一两竿。','',''),('quantangshi-34621','石竹花咏','陸龜蒙','quantangshi','','卷35','曾看南朝画国娃，古萝衣上碎明霞。
而今莫共金钱鬬，买却春风是此花。','',''),('quantangshi-34622','和袭美友人许惠酒以诗征之','陸龜蒙','quantangshi','','卷35','冻醪初漉嫩如春，轻蚁漂漂杂蘂尘。
得伴方平同一醉，明朝应作蔡经身。','',''),('quantangshi-34623','闻圆载上人挟儒书洎释典归日本国更作一绝以送','陸龜蒙','quantangshi','','卷35','九流三藏一时倾，万轴光凌渤澥声。
从此遗编东去后，却应荒外有诸生。','',''),('quantangshi-34624','闲吟','陸龜蒙','quantangshi','','卷35','闲吟料得三更尽，始把孤灯背竹窗。
一夜西风高浪起，不教归梦过寒江。','',''),('quantangshi-34625','秘色越器','陸龜蒙','quantangshi','','卷35','九秋风露越窑开，夺得千峰翠色来。
好向中宵盛沆瀣，共嵇中散鬬遗杯。','',''),('quantangshi-34626','景阳宫井','陸龜蒙','quantangshi','','卷35','古堞烟埋宫井树，陈主吴姬堕泉处。
舜没苍梧万里云，却不闻将二妃去。','',''),('quantangshi-34627','江南二首 一','陸龜蒙','quantangshi','','卷35','便风船尾香秔熟，细雨层头赤鲤跳。
待得江餐闲望足，日斜方动木兰桡。','',''),('quantangshi-34628','江南二首 二','陸龜蒙','quantangshi','','卷35','村边紫豆花垂次，岸上红梨叶战初。
莫怪烟中重回首，酒家青紵一行书。','',''),('quantangshi-34629','溪思雨中','陸龜蒙','quantangshi','','卷35','雨映前山万絇丝，樐声冲破似鸣机。
无端织得愁成段，堪作骚人酒病衣。','',''),('quantangshi-34630','江城夜泊','陸龜蒙','quantangshi','','卷35','漏移寒箭丁丁急，月挂虚弓霭霭明。
此夜离魂堪射断，更须江笛两三声。','',''),('quantangshi-34631','宫人斜','陸龜蒙','quantangshi','','卷35','草着愁烟似不春，晚莺哀怨问行人。
须知一种埋香骨，犹胜昭君作虏尘。','',''),('quantangshi-34632','送棊客','陸龜蒙','quantangshi','','卷35','满目山川似势棊，况当秋雁正斜飞。
金门若召羊玄保，赌取江东太守归。','',''),('quantangshi-34633','汉宫词','陸龜蒙','quantangshi','','卷35','招灵阁上霓旌绝，柏梁台中珠翠稠。
一身三十六宫夜，露滴玉盘青桂秋。','',''),('quantangshi-34634','上清','陸龜蒙','quantangshi','','卷35','玉林风露寂寥清，仙妃对月闲吹笙。
新篁冷涩曲未尽，细拂云枝栖凤惊。','',''),('quantangshi-34635','秋荷','陸龜蒙','quantangshi','','卷35','蒲茸承露有佳色，茭叶束烟如效颦。
盈盈一水不得渡，冷翠遗香愁向人。','',''),('quantangshi-34636','有别二首 一','陸龜蒙','quantangshi','','卷35','且将丝䋏系兰舟，醉下烟汀减去愁。
江上有楼君莫上，落花随浪正东流。','',''),('quantangshi-34637','有别二首 二','陸龜蒙','quantangshi','','卷35','池上已看莺舌默，云间应即雁翰开。
唯愁别后当风立，万树将秋入恨来。','',''),('quantangshi-34638','病中晓思','陸龜蒙','quantangshi','','卷35','月堕霜西竹井寒，辘轳丝冻下瓶难。
幽人病久浑成渴，愁见龙书一鼎干。','',''),('quantangshi-34639','送友人之湖上','陸龜蒙','quantangshi','','卷35','故人溪上有渔舟，竿倚风苹夜不收。
欲寄一函聊问讯，洪乔宁作置书邮。','',''),('quantangshi-34640','寒日逢僧','陸龜蒙','quantangshi','','卷35','瘦胫高褰梵屧轻，野塘风劲锡环鸣。
如何不向深山里，坐拥闲云过一生。','',''),('quantangshi-34641','冬柳','陸龜蒙','quantangshi','','卷35','柳汀斜对野人窗，零落衰条傍晓江。
正是霜风飘断处，寒鸥惊起一双双。','',''),('quantangshi-34642','寄友人','陸龜蒙','quantangshi','','卷35','敬亭寒夜溪声里，同听先生讲太玄。
上得云梯不回首，钓竿犹在五湖边。','',''),('quantangshi-34643','岛树','陸龜蒙','quantangshi','','卷35','波涛漱苦盘根浅，风雨飘多着叶迟。
