自埽雪中归鹿迹，天明恐被猎人寻。','',''),('quantangshi-34645','晚渡','陸龜蒙','quantangshi','','卷35','半波风雨半波晴，渔曲飘秋野调清。
各样莲船逗村去，笠檐衰袂有残声。','',''),('quantangshi-34646','赠老僧二首 一','陸龜蒙','quantangshi','','卷35','枯貌自同霜里木，余生唯指佛前灯。
少时写得坐禅影，今见问人何处僧。','',''),('quantangshi-34647','赠老僧二首 二','陸龜蒙','quantangshi','','卷35','自有家山供衲线，不离溪曲取庵茅。
旧曾闻说林中鸟，定后长来顶上巢。','',''),('quantangshi-34648','忆山泉','陸龜蒙','quantangshi','','卷35','一夜寒声来梦里，平明着屐到声边。
心期盛夏同过此，脱却荷衣石上眠。','',''),('quantangshi-34649','白芙蓉','陸龜蒙','quantangshi','','卷35','澹然相对却成劳，月染风裁个个高。
似说玉皇亲谪堕，至今犹着水霜袍。','',''),('quantangshi-34650','严光钓台','陸龜蒙','quantangshi','','卷35','片帆竿外揖清风，石立云孤万古中。
不是狂奴为故态，仲华争得黑头公。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34651','读陈拾遗集','陸龜蒙','quantangshi','','卷35','蓬颗何时与恨平，蜀江衣带蜀山轻。
寻闻骑士枭黄祖，自是无人祭禰衡。','',''),('quantangshi-34652','吴宫怀古','陸龜蒙','quantangshi','','卷35','香迳长洲尽棘丛，奢云艳雨秖悲风。
吴王事事须亡国，未必西施胜六宫。','',''),('quantangshi-34653','送琴客之建康','陸龜蒙','quantangshi','','卷35','蕙风杉露共泠泠，三峡寒泉漱玉清。
君到南朝访遗事，柳家双锁旧知名。','',''),('quantangshi-34654','闺怨','陸龜蒙','quantangshi','','卷35','白袷行人又远游，日斜空上映花楼。
愁丝堕絮相逢着，绊惹春风卒未休。','',''),('quantangshi-34655','丁香','陸龜蒙','quantangshi','','卷35','江上悠悠人不问，十年云外醉中身。
殷勤解却丁香结，纵放繁枝散诞春。','',''),('quantangshi-34656','种蒲','陸龜蒙','quantangshi','','卷35','杜若溪边手自移，旋抽烟劒碧参差。
何时织得孤帆去，悬向秋风访所思。','',''),('quantangshi-34657','范蠡','陸龜蒙','quantangshi','','卷35','平吴专越祸胎深，岂是功成有去心。
句践不知嫌鸟喙，归来犹自铸良金。','',''),('quantangshi-34658','山僧二首 一','陸龜蒙','quantangshi','','卷35','山藓几重生草履，涧泉长自满铜瓶。
时将如意敲眠虎，遣向林间坐听经。','',''),('quantangshi-34659','山僧二首 二','陸龜蒙','quantangshi','','卷35','一夏不离苍岛上，秋来频话石城南。
思归瀑布声前坐，却把松枝拂旧庵。','',''),('quantangshi-34660','上云乐','陸龜蒙','quantangshi','','卷35','青丝作筰桂为船，白兔捣药虾蟇丸。
便浮天汉泊星渚，回首笑君承露盘。','',''),('quantangshi-34661','新秋杂题六首 眠','陸龜蒙','quantangshi','','卷35','一簟临窗薤叶秋，小帘风荡半离钩。
魂清雨急梦难到，身在五湖波上头。','',''),('quantangshi-34662','新秋杂题六首 行','陸龜蒙','quantangshi','','卷35','寻人直到月坞北，觅鹤便过云峰西。
只今犹有疎野调，但绕莓苔风雨畦。','',''),('quantangshi-34663','新秋杂题六首 倚','陸龜蒙','quantangshi','','卷35','橘下凝情香染巾，竹边留思露摇身。
背烟垂首尽日立，忆得山中无事人。','',''),('quantangshi-34664','新秋杂题六首 吟','陸龜蒙','quantangshi','','卷35','忆山摇膝石上晚，怀古掉头溪畔凉。
有时得句一声发，惊起鹭鹚和夕阳。','',''),('quantangshi-34665','新秋杂题六首 食','陸龜蒙','quantangshi','','卷35','日午空斋带睡痕，水蔬山药荐盘[飧]。
林乌信我无机事，长到而今下石盆。','',''),('quantangshi-34666','新秋杂题六首 坐','陸龜蒙','quantangshi','','卷35','偶避蝉声来隙地，忽随鸿影入辽天。
闲僧不会寂寥意，道学西方人坐禅。','',''),('quantangshi-34667','新沙','陸龜蒙','quantangshi','','卷35','渤澥声中涨小堤，官家知后海鸥知。
蓬莱有路教人到，应亦年年税紫芝。','',''),('quantangshi-34668','邺宫词二首 一','陸龜蒙','quantangshi','','卷35','魏武平生不好香，枫胶蕙炷洁宫房。
可知遗令非前事，却有余薰在绣囊。','',''),('quantangshi-34669','邺宫词二首 二','陸龜蒙','quantangshi','','卷35','花飞蝶骇不愁人，水殿云廊别置春。
晓日靓妆千骑女，白樱桃下紫纶巾。','',''),('quantangshi-34670','古别离','陸龜蒙','quantangshi','','卷35','仙人左手把长箭，欲射日乌乌不栖。
何事离情畏明发，一心唯恨汝南鸡。','',''),('quantangshi-34671','高道士','陸龜蒙','quantangshi','','卷35','峨眉道士风骨峻，手把玉皇书一通。
东游借得琴高鲤，骑人蓬莱清浅中。','',''),('quantangshi-34672','蔬食','陸龜蒙','quantangshi','','卷35','孔融不要留残脍，庾悦无端恡子鹅。
香稻熟来秋菜嫩，伴僧餐了听云和。','',''),('quantangshi-34673','寄远','陸龜蒙','quantangshi','','卷35','缥梨花谢莺口吃，黄犊少年人未归。
画扇红弦相掩映，独看斜月下帘衣。','',''),('quantangshi-34674','山中僧','陸龜蒙','quantangshi','','卷35','手关一室翠微里，日暮白云栖半间。
白云朝出天际去，若比老僧犹未闲。','',''),('quantangshi-34675','洞宫秋夕','陸龜蒙','quantangshi','','卷35','浓霜打叶落地声，南溪石泉细泠泠。
洞宫寂寞人不去，坐见月生云母屏。','',''),('quantangshi-34676','连昌宫词二首 门','陸龜蒙','quantangshi','','卷35','金铺零落兽镮空，斜揜双扉细草中。
日暮鸟归宫树绿，不闻鸦轧闭春风。','',''),('quantangshi-34677','连昌宫词二首 阶','陸龜蒙','quantangshi','','卷35','草没苔封叠翠斜，坠红千叶拥残霞。
年年直为秋霖苦，滴陷青珉隐起花。','',''),('quantangshi-34678','怀宛陵旧游','陸龜蒙','quantangshi','','卷35','陵阳佳地昔年游，谢朓青山李白楼。
唯有日斜溪上思，酒旗风影落春流。','',''),('quantangshi-34679','松石晓景图','陸龜蒙','quantangshi','','卷35','霜骨云根惨澹愁，宿烟封着未全收。
将归与说文通后，写得松江岸上秋。','',''),('quantangshi-34680','钓车','陸龜蒙','quantangshi','','卷35','小轮轻线妙无双，曾伴幽人酒一缸。
