曲去日中还，直行日暮宿。
何必日中还，曲途荆棘间。','',''),('quantangshi-34709','彼农二章 一','陸龜蒙','quantangshi','','卷35','世路浇险，淳风荡除。
彼农家流，犹存厥初。
藁焉而席，茨焉而居。
首乱如葆，形枯若腒。
大耋既鲐，童子未𪘯。
以负以载，悉薅悉鉏。
我慕圣道，我躭古书。
小倦于学，时游汝庐。
有饭一盛，莫盐莫蔬。
有繻一缇，不襟不祛。
所谓饥寒，汝何逭欤。','',''),('quantangshi-34710','彼农二章 二','陸龜蒙','quantangshi','','卷35','禹贡厥田，上下各异。
善人为邦，民受其赐。
去年西成，野有遗穗。
今夏南亩，旱气赤地。
遭其丰凶，概歛无二。
退输弗供，进诉弗视。
号于旻天，以血为泪。
孟子有言，王无罪岁。
诗以穷辞，以嫉悍吏。','',''),('quantangshi-34711','奉酬袭美苦雨见寄','陸龜蒙','quantangshi','','卷35','松篁交加午阴黑，别是江南烟霭国。
顽云猛雨更相欺，声似虓号色如墨。
茅茨裛烂檐生衣，夜夜化为萤火飞。
萤飞渐多屋渐薄，一注愁霖当面落。
愁霖愁霖尔何错，灭顶于余奚所作。
既不能赋似陈思王，又不能诗似谢康乐。
昔年尝过杜子美，亦得高歌破印纸。
惯曾掀搅大笔多，为我才情也如此。
高揖愁霖词未已，披文忽自皮夫子。
哀弦怨柱合为吟，㤞我穷栖蓬藋里。
初悲湿翼何由起，末欲牋天叩天耳。
其如玉女正投壶，笑电霏霏作天喜。
我本曾无一棱田，平生啸傲空渔船。
有时赤脚弄明月，踏破五湖光底天。
去岁王师东下急，输兵粟尽民相泣。
伊予不战不耕人，敢怨烝黎无糁粒。
不然受性圆如规，千姿万态分毫厘。
唾壶虎子尽能执，舐痔折枝无所辞。
有头强方心强直，撑拄颓风不量力。
自爱垂名野史中，宁论抱困荒城侧。
唯君浩叹非庸人，分衣辍饮来相亲。
横眠木榻忘华荐，对食露葵轻八珍。
欲穷玄，凤未白，欲怀仙，鲸尚隔。
不如驱入醉乡中，只恐醉乡田地窄。','',''),('quantangshi-34712','夏日闲居作四声诗寄袭美 平声','陸龜蒙','quantangshi','','卷35','荒池菰蒲深，闲阶莓苔平。
江边松篁多，人家帘栊清。
为书凌遗编，调弦夸新声。
求欢虽殊途，探幽聊怡情。','',''),('quantangshi-34713','夏日闲居作四声诗寄袭美 平上声','陸龜蒙','quantangshi','','卷35','朝烟淹楼台，晚雨染岛屿。
渔童惊狂歌，艇子喜野语。
山容堪停杯，柳影好隐暑。
年华如飞鸿，斗酒幸且举。','',''),('quantangshi-34714','夏日闲居作四声诗寄袭美 平去声','陸龜蒙','quantangshi','','卷35','新开窗犹偏，自种蕙未徧。
书签风摇闻，钓榭雾破见。
耕耘闲之资，啸咏性最便。
希夷全天真，讵要问贵贱。','',''),('quantangshi-34715','夏日闲居作四声诗寄袭美 平入声','陸龜蒙','quantangshi','','卷35','端居愁无涯，一夕髪欲白。
因为鸾章吟，忽忆鹤骨客。
手披丹台文，脚着赤玉舃。
如蒙清音酬，若渴吸月液。','',''),('quantangshi-34716','奉酬袭美苦雨四声重寄三十二句 平声','陸龜蒙','quantangshi','','卷35','幽栖眠疎窗，豪居凭高楼。
浮沤惊跳丸，寒声思重裘。
