虽无东臯田，还生鱼乎忧。','',''),('quantangshi-34717','奉酬袭美苦雨四声重寄三十二句 平上声','陸龜蒙','quantangshi','','卷35','层云愁天低，久雨倚槛冷。
丝禽藏荷香，锦鲤绕岛影。
