逡巡新春人，转面见战箭。','',''),('quantangshi-34725','叠韵吴宫词二首 二','陸龜蒙','quantangshi','','卷35','红栊通东风，翠珥醉易坠。
平明兵盈城，弃置遂至地。','',''),('quantangshi-34726','和胥口即事 一','陸龜蒙','quantangshi','','卷35','雨后山容若动，天寒树色如消。
目送回汀隐隐，心随挂鹿摇摇。
白蒋知秋露裛，青枫欲暮烟饶。
