绿倒红飘欲尽，风斜雨细相逢。
断岸沈渔𦋥𦊲，邻村送客𦪽{舟卭}。
即是清霜剖野，乘闲莫厌来重。','',''),('quantangshi-34728','齐梁怨别','陸龜蒙','quantangshi','','卷35','寥寥缺月看将落，檐外霜华染罗幕。
