青箱有意终须续，断简遗编一半通。','',''),('quantangshi-34737','和袭美怀锡山药名离合二首 一','陸龜蒙','quantangshi','','卷35','鹤伴前溪栽白杏，人来阴洞写枯松。
萝深境静日欲落，石上未眠闻远钟。','',''),('quantangshi-34738','和袭美怀锡山药名离合二首 二','陸龜蒙','quantangshi','','卷35','佳句成来谁不伏，神丹偷去亦须防。
风前莫怪携诗藁，本是吴吟荡桨郎。','',''),('quantangshi-34739','和袭美怀鹿门县名离合二首 一','陸龜蒙','quantangshi','','卷35','云容覆枕无非白，水色侵矶直是蓝。
田种紫芝餐可寿，春来何事恋江南。','',''),('quantangshi-34740','和袭美怀鹿门县名离合二首 二','陸龜蒙','quantangshi','','卷35','竹溪深处猿同宿，松阁秋来客共登。
封迳古苔侵石鹿，城中谁解访山僧。','',''),('quantangshi-34741','寒日古人名','陸龜蒙','quantangshi','','卷35','初寒朗咏裴回立，欲谢玄关早晚开。
昨日登楼望江色，鱼梁鸿雁几多来。','',''),('quantangshi-34742','句','陸龜蒙','quantangshi','','卷35','几点社翁雨，一番花信风。
水鸟歌妇女，衣襟便佞舌。
溪山自是清凉国，松竹合封萧洒侯。
山上花明水上曛，一桡青翰破霞文。
白帝霜舆欲御秋，但说漱流并枕石。
不辞蝉腹与龟肠，头方不会王门事。
尘土空缁白苎衣，秋来嬾上向吴亭。','',''),('quantangshi-34743','旅泊吴门','張賁','quantangshi','','卷35','一舸吴江晚，堪忧病广文。
鲈鱼谁与伴，鸥鸟自成羣。
反照纵横水，斜空断续云。
异乡无限思，尽付酒醺醺。','',''),('quantangshi-34744','贲中间有吴门旅泊之什蒙鲁望垂和更作一章以伸酬谢','張賁','quantangshi','','卷35','偶发陶匏响，皆蒙组绣文。
清秋将落帽，子夏正离羣。
有恨书燕雁，无聊赋郢云。
徧看心自醉，不是酒能醺。','',''),('quantangshi-34745','酬袭美先见寄倒来韵','張賁','quantangshi','','卷35','寻疑天意丧斯文，故选茅峰寄白云。
酒后只留沧海客，香前唯见紫阳君。
近年已绝诗书癖，今日兼将笔砚焚。
为有此身犹苦患，不知何者是玄纁。','',''),('quantangshi-34746','奉和袭美醉中即席见赠次韵','張賁','quantangshi','','卷35','桂枝新下月中仙，学海词锋誉蔼然。
文阵已推忠信甲，穷波犹认孝廉船。
清标称住羊车上，俗韵惭居鹤氅前。
共许逢蒙快弓箭，再穿杨叶在明年。','',''),('quantangshi-34747','奉和袭美题褚家林亭','張賁','quantangshi','','卷35','疎野林亭震泽西，朗吟闲步喜相携。
时时风折芦花乱，处处霜摧稻穗低。
百本败荷鱼不动，一枝寒菊蝶空迷。
今朝偶得高阳伴，从放山翁醉似泥。','',''),('quantangshi-34748','奉和袭美伤开元观顾道士','張賁','quantangshi','','卷35','凤麟胶尽夜如何，共叹先生劒解多。
几度吊来唯白鹤，此时乘去必青骡。
图中含景随残照，琴里流泉寄逝波。
惆怅真灵又空返，玉书谁授紫微歌。','',''),('quantangshi-34749','和鲁望白菊','張賁','quantangshi','','卷35','雪彩冰姿号女华，寄身多是地仙家。
有时南国和霜立，几处东篱伴月斜。
谢客琼枝空贮恨，袁郎金钿不成夸。
自知终古清香在，更出梅妆弄晚霞。','',''),('quantangshi-34750','奉和袭美先辈悼鹤','張賁','quantangshi','','卷35','池塘萧索掩空笼，玉树同嗟一土中。
莎径罢鸣唯泣露，松轩休舞但悲风。
丹台旧氅难重缉，紫府新书岂更通。
云减雾消无处问，只留华髪与衰翁。','',''),('quantangshi-34751','偶约道流终乖文会答皮陆','張賁','quantangshi','','卷35','仙侣无何访蔡经，两烦韶濩出彤庭。
人间若有登楼望，应怪文星近客星。','',''),('quantangshi-34752','和袭美寒夜见访','張賁','quantangshi','','卷35','云孤鹤独且相亲，仿効从它折角巾。
不用吴江叹留滞，风姿俱是玉清人。','',''),('quantangshi-34753','和袭美醉中先起次韵','張賁','quantangshi','','卷35','何事桃源路忽迷，惟留云雨怨空闺。
仙郎共许多情调，莫遣重歌浊水泥。','',''),('quantangshi-34754','和皮陆酒病偶作','張賁','quantangshi','','卷35','白编椰席镂冰明，应助杨青解宿酲。
难继二贤金玉唱，可怜空作断猿声。','',''),('quantangshi-34755','送浙东德师侍御罢府西归','張賁','quantangshi','','卷35','孤云独鸟本无依，江海重逢故旧稀。
杨柳渐疏芦苇白，可怜斜日送君归。','',''),('quantangshi-34756','以青䭀饭分送袭美鲁望因成一绝','張賁','quantangshi','','卷35','谁屑琼瑶事青䭀，旧传名品出华阳。
应宜仙子胡麻拌，因送刘郎与阮郎。','',''),('quantangshi-34757','玩金鸂鶒和陆鲁望','張賁','quantangshi','','卷35','翠羽红襟镂彩云，双飞常笑白鸥羣。
谁怜化作雕金质，从倩沈檀十里闻。','',''),('quantangshi-34758','悼鹤和袭美','張賁','quantangshi','','卷35','渥顶鲜毛品格驯，莎庭闲暇重难羣。
无端日暮东风起，飘散春空一片云。','',''),('quantangshi-34759','览皮先辈盛制因作十韵以寄用伸欵仰','崔璐','quantangshi','','卷35','河岳挺灵异，星辰精气殊。
在人为英杰，与国作祯符。
襄阳得奇士，俊迈真龙驹。
勇果鲁仲由，文赋蜀相如。
浑浩江海广，葩华桃李敷。
小言入无间，大言塞空虚。
几人游赤水，夫子得玄珠。
鬼神争奥秘，天地惜洪炉。
既有曾参行，仍兼君子儒。
吾知上帝意，将使居黄枢。
好保千金体须为万姓谟。','',''),('quantangshi-34760','浙东罢府西归酬别张广文皮先辈陆秀才','李縠','quantangshi','','卷35','岂有头风笔下痊，浪成蛮语向初筵。
兰亭旧趾虽曾见，柯笛遗音更不传。
照曜文星吴分野，留连花月晋名贤。
相逢只恨相知晚，一曲骊歌又几年。','',''),('quantangshi-34761','和皮日休悼鸖 一','李縠','quantangshi','','卷35','才子襟期本上清，陆云家鸖伴闲情。
犹怜反顾五六里，何意忽归十二城。
露滴谁闻高叶坠，月沈休藉半阶明。
人闻华表堪留语，剩向秋风寄一声。','',''),('quantangshi-34762','和皮日休悼鸖 二','李縠','quantangshi','','卷35','道林曾放雪翎飞，应悔庭除闭羽衣。
料得王恭披鹤氅，倚吟犹待月中归。','',''),('quantangshi-34763','醉中袭美先月中归','李縠','quantangshi','','卷35','休文虽即逃琼液，阿鹜还须掩玉闺。
月落金鸡一声后，不知谁悔醉如泥。','',''),('quantangshi-34764','奉酬皮先辈霜菊见赠','崔璞','quantangshi','','卷35','菊花开晚过秋风，闻道芳香正满丛。
争奈病夫难强饮，应须速自召车公。','',''),('quantangshi-34765','蒙恩除替将还京洛偶叙所怀因成六韵呈军事院诸公郡中一二秀才','崔璞','quantangshi','','卷35','两载求人瘼，三春受代归。
务繁多簿籍，才短乏恩威。
共理乖天奖，分忧值岁饥。
遽蒙交郡印，安敢整朝衣。
作牧慙为政，思乡念式微。
傥容还故里，高卧掩柴扉。','',''),('quantangshi-34766','和皮日休悼鹤 一','魏朴','quantangshi','','卷35','直欲裁诗问杳冥，岂教灵化亦浮生。
风林月动疑留魄，沙岛香愁似蕴情。
雪骨夜封苍藓冷，练衣寒在碧塘轻。
人间飞去犹堪恨，况是泉台远玉京。','',''),('quantangshi-34767','和皮日休悼鹤 二','魏朴','quantangshi','','卷35','经秋宋玉已悲伤，况报胎禽昨夜亡。
霜晓起来无问处，伴僧弹指遶荷塘。','',''),('quantangshi-34768','皮袭美见留小宴次韵','羊昭業','quantangshi','','卷35','泽国春来少遇晴，有花开日且飞觥。
王戎似电休推病，周顗才醒众却惊。
芳景渐浓偏属酒，暖风初畅欲调莺。
知君不肯然官烛，争得华筵彻夜明。','',''),('quantangshi-34769','送羊振文归觐桂阳','顏萱','quantangshi','','卷35','高挂吴帆喜动容，问安归去指湘峯。
悬鱼庭内芝兰秀，驭鹤门前薜荔封。
红斾正怜棠影茂，彩衣偏带桂香浓。
临岐独有霑襟恋，南巷当年共化龙。','',''),('quantangshi-34770','送圆载上人','顏萱','quantangshi','','卷35','师来一世恣经行，却泛沧波问去程。
心静已能防渴鹿，鼙喧时为骇长鲸。
禅林几结金桃重，梵室重修铁瓦轻。
料得还乡无别利，只应先见日华生。','',''),('quantangshi-34771','过张祜处士丹阳故居','顏萱','quantangshi','','卷35','忆昔为儿逐我兄，曾抛竹马拜先生。
书斋已换当时主，诗壁空题故友名。
岂是争权留怨敌，可怜当路尽公卿。
柴扉草屋无人问，犹向荒田责地征。','',''),('quantangshi-34772','和袭美伤顾道士','鄭璧','quantangshi','','卷35','斜汉银澜一夜东，飘飘何处五云中。
空留华表千年约，才毕丹炉九转功。
形蜕远山孤圹月，影寒深院晓松风。
门人不覩飞升去，犹与浮生哭恨同。','',''),('quantangshi-34773','奉和陆鲁望白菊','鄭璧','quantangshi','','卷35','白艳轻明带露痕，始知佳色重难羣。
终朝疑笑梁王雪，尽日慵飞蜀帝魂。
燕雨似翻瑶渚浪，雁风疑卷玉绡纹。
琼妃若会宽裁剪，堪作蟾宫夜舞裙。','',''),('quantangshi-34774','和袭美索友人酒','鄭璧','quantangshi','','卷35','乘兴闲来小谢家，便裁诗句乞榴花。
邴原虽不无端醉，也爱临风从鹿车。','',''),('quantangshi-34775','文燕润卿不至','鄭璧','quantangshi','','卷35','已知羽驾朝金阙，不用烧兰望玉京。
应是易迁明月好，玉皇留看舞双成。','',''),('quantangshi-34776','塞上','司空圖','quantangshi','','卷35','万里隋城在，三边虏气衰。
沙填孤障角，烧断故关碑。
马色经寒惨，雕声带晚悲。
将军正闲暇，留客换歌辞。','',''),('quantangshi-34777','寄永嘉崔道融','司空圖','quantangshi','','卷35','旅寓虽难定，乘闲是胜游。
碧云萧寺霁，红树谢邨秋。
戍鼓和潮暗，船灯照岛幽。
诗家多滞此，风景似相留。','',''),('quantangshi-34778','下方','司空圖','quantangshi','','卷35','三十年来往，中间京洛尘。
倦行今白首，归卧已清神。
坡暖冬抽笋，松凉夏健人。
更惭征诏起，避世迹非真。','',''),('quantangshi-34779','华下','司空圖','quantangshi','','卷35','日炙旱云裂，迸为千道血。
天地沸一镬，竟自烹妖孽。
尧汤遇灾数，灾数还中辍。
何事奸与邪，古来难扑灭。','',''),('quantangshi-34780','僧舍贻友','司空圖','quantangshi','','卷35','笑破人间事，吾徒莫自欺。
解吟僧亦俗，爱舞鹤终卑。
竹上题幽梦，溪边约敌棋。
旧山归有阻，不是故迟迟。','',''),('quantangshi-34781','下方','司空圖','quantangshi','','卷35','昏旦松轩下，怡然对一瓢。
雨微吟思足，花落梦无聊。
细事当棋遣，衰容喜镜饶。
溪僧有深趣，书至又相邀。','',''),('quantangshi-34782','华下送文浦','司空圖','quantangshi','','卷35','郊居谢名利，何事最相亲。
渐与论诗久，皆知得句新。
川明虹照雨，树密鸟冲人。
应念从今去，还来岳下频。','',''),('quantangshi-34783','自诫','司空圖','quantangshi','','卷35','我祖铭座右，嘉谋贻厥孙。
勤此苟不怠，令名日可存。
媒炫士所耻，慈俭道所尊。
松柏岂不茂，桃李亦自繁。
众人皆察察，而我独昏昏。
取训于老氏，大辩欲讷言。','',''),('quantangshi-34784','效陈拾遗子昂感遇二首 一','司空圖','quantangshi','','卷35','高燕飞何捷，啄害恣羣雏。
人岂玩其暴，华轩容尔居。
强欺自天禀，刚吐信吾徒。
乃知不平者，矫世道终孤。','',''),('quantangshi-34785','效陈拾遗子昂感遇二首 二','司空圖','quantangshi','','卷35','阳和含煦润，卉木竞纷华。
当为众所悦，私已汝何夸。
北里祕穠艳，东园锁名花。
豪夺乃常理，笑君徒咄嗟。','',''),('quantangshi-34786','效陈拾遗子昂','司空圖','quantangshi','','卷35','丑妇竞簪花，花多映愈丑。
邻女恃其姿，掇之不盈手。
量已苟自私，招损乃谁咎。
宠禄既非安，于吾竟何有。','',''),('quantangshi-34787','感时','司空圖','quantangshi','','卷35','好鸟无恶声，仁兽肯狂噬。
宁教鹦鹉哑，不遣麒麟细。
人人语与默，唯观利与势。
爱毁亦自遭，掩谤终失计。','',''),('quantangshi-34788','秋思','司空圖','quantangshi','','卷35','身病时亦危，逢秋多恸哭。
风波一摇荡，天地几翻覆。
孤萤出荒池，落叶穿破屋。
势利长草草，何人访幽独。','',''),('quantangshi-34789','早春','司空圖','quantangshi','','卷35','伤怀同客处，病眼却花朝。
草嫩侵沙短，冰轻着雨消。
风光知可爱，容髪不相饶。
早晚丹丘去，飞书肯见招。','',''),('quantangshi-34790','上陌梯寺怀旧僧二首 一','司空圖','quantangshi','','卷35','云根禅客居，皆说旧无庐。
松日明金像，山风向木鱼。
依栖应不阻，名利本来疎。
纵有人相问，林间懒拆书。','',''),('quantangshi-34791','上陌梯寺怀旧僧二首 二','司空圖','quantangshi','','卷35','高鸦隔谷见，路转寺西门。
塔影荫泉脉，山苗侵烧痕。
钟疎含杳霭，合迥亘黄昏。
更待他僧到，长如前信存。','',''),('quantangshi-34792','寄怀元秀上人','司空圖','quantangshi','','卷35','悠悠干禄利，草草废渔樵。
身世堪惆怅，风骚顿寂寥。
高秋期步野，积雨放趋朝。
得句如相忆，莎斋且见招。','',''),('quantangshi-34793','次韵和秀上人游南五台','司空圖','quantangshi','','卷35','中峰曾到处，题记没苍苔。
振锡传深谷，翻经想旧台。
危松临砌偃，惊鹿蓦溪来。
内殿御诗切，身回心未回。','',''),('quantangshi-34794','赠圆昉公','司空圖','quantangshi','','卷35','天阶让紫衣，冷格鹤犹卑。
道胜嫌名出，身闲觉老迟。
晓香延宿火，寒磬度高枝。
每说长松寺，他年与我期。','',''),('quantangshi-34795','赠信美寺岑上人','司空圖','quantangshi','','卷35','巡礼诸方遍，湘南频有缘。
焚香老山寺，乞食向江船。
纱碧笼名画，灯寒照净禅。
我来能永日，莲漏滴寒泉。','',''),('quantangshi-34796','江行二首 一','司空圖','quantangshi','','卷35','地阔分吴塞，枫高映楚天。
曲塘春尽雨，方响夜深船。
行纪添新梦，羇愁甚往年。
何时京洛路，马上见人烟。','',''),('quantangshi-34797','江行二首 二','司空圖','quantangshi','','卷35','初程风信好，回望失津楼。
日带潮声晚，烟含楚色秋。
戍旗当远客，岛树转惊鸥。
此去非名利，孤帆任白头。','',''),('quantangshi-34798','长安赠王注','司空圖','quantangshi','','卷35','正下搜贤诏，多君独避名。
客来当意惬，花发遇歌成。
乐地留高趣，权门让后生。
东方御闲驷，园外好同行。','',''),('quantangshi-34799','赠步寄李员外','司空圖','quantangshi','','卷35','危桥转溪路，经雨石丛荒。
幽瀑下仙果，孤巢悬夕阳。
病辞青琐祕，心在紫芝房。
更喜谐招隐，诗家有望郎。','',''),('quantangshi-34800','寄郑仁规','司空圖','quantangshi','','卷35','清才郑小戎，标的贵游中。
万里云无侣，三山鹤不笼。
香和丹地暖，晚着彩衣风。
荣路期经济，唯应在至公。','',''),('quantangshi-34801','寄考功王员外','司空圖','quantangshi','','卷35','喜闻三字耗，闲客是陪游。
白鸟闲疎索，青山日滞留。
琴如高韵称，诗愧逸才酬。
更勉匡君志，论思在献谋。','',''),('quantangshi-34802','杂言','司空圖','quantangshi','','卷35','鸟飞飞，兔蹶蹶，朝来暮去驱时节。
女娲只解补青天，不解煎胶黏日月。','',''),('quantangshi-34803','陈疾','司空圖','quantangshi','','卷35','自怜旅舍亦酣歌，世路无机奈尔何。
霄汉逼来心不动，鬓毛白尽兴犹多。
残阳暂照乡关近，远鸟因投岳庙过。
闲得此身归未得，磬声深夏隔烟萝。','',''),('quantangshi-34804','淅上 一','司空圖','quantangshi','','卷35','华下支离已隔河，又来此地避干戈。
山田渐广猨时到，邨舍新添燕亦多。
丹桂石楠宜并长，秦云楚雨暗相和。
儿童栗熟迷归路，归得仍随牧竖歌。','',''),('quantangshi-34805','淅上 二','司空圖','quantangshi','','卷35','西北乡关近帝京，烟尘一片正伤情。
愁看地色连空色，静听歌声似哭声。
红蓼满邨人不在，青山遶槛路难平。
从他烟棹更南去，休向津头问去程。','',''),('quantangshi-34806','山中','司空圖','quantangshi','','卷35','全家与我恋孤岑，蹋得苍苔一径深。
逃难人多分隙地，放生麋大出寒林。
名应不朽轻仙骨，理到忘机近佛心。
昨夜前溪骤雷雨，晚晴闲步数峰吟。','',''),('quantangshi-34807','寄赠诗僧秀公','司空圖','quantangshi','','卷35','灵一心传清塞心，可公吟后础公吟。
近来雅道相亲少，惟仰吾师所得深。
好句未停无暇日，旧山归老有东林。
冷曹孤宦甘寥落，多谢携筇数访寻。','',''),('quantangshi-34808','重阳日访元秀上人','司空圖','quantangshi','','卷35','红叶黄花秋景宽，醉吟朝夕在樊川。
却嫌今日登山俗，且共高僧对榻眠。
别画长怀吴寺壁，宜茶偏赏霅溪泉。
归来童穉争相笑，何事无人与酒船。','',''),('quantangshi-34809','丁未岁归王官谷','司空圖','quantangshi','','卷35','家山牢落战尘西，匹马偷归路已迷。
冢上卷旗人簇立，花边移寨鸟惊啼。
本来薄俗轻文字，却致中原动鼓鼙。
将取一壶闲日月，长歌深入武陵溪。','',''),('quantangshi-34810','书怀','司空圖','quantangshi','','卷35','病来犹强引雏行，力上东原欲试耕。
几处马嘶春麦长，一川人喜雪峰晴。
闲知有味心难肯，道贵谋安迹易平。
陶令若能兼不饮，无弦琴亦是沽名。','',''),('quantangshi-34811','退栖','司空圖','quantangshi','','卷35','宦游萧索为无能，移住中条最上层。
得劒乍如添健仆，亡书久似失良朋。
燕昭不是空怜马，支遁何妨亦爱鹰。
自此致身绳检外，肯教世路日兢兢。','',''),('quantangshi-34812','五十','司空圖','quantangshi','','卷35','闲身事少只题诗，五十今来觉陡衰。
清秩偶叨非养望，丹方频试更堪疑。
髭须强染三分折，弦管遥听一半悲。
漉酒有巾无黍酿，负他黄菊满东篱。','',''),('quantangshi-34813','新岁对写真','司空圖','quantangshi','','卷35','得见明时下寿身，须甘岁酒更移巡。
生情暗结千重恨，寒势常欺一半春。
文武轻销丹竈火，市朝偏贵黑头人。
自伤衰飒慵开镜，拟与儿童别写真。','',''),('quantangshi-34814','华下','司空圖','quantangshi','','卷35','箨冠新带步池塘，逸韵偏宜夏景长。
扶起绿荷承早露，惊回白鸟入残阳。
久无书去干时贵，时有僧来自故乡。
不用名山访真诀，退休便是养生方。','',''),('quantangshi-34815','重阳山居','司空圖','quantangshi','','卷35','诗人自古恨难穷，暮节登临且喜同。
四望交亲兵乱后，一川风物笛声中。
菊残深处回幽蝶，陂动晴光下早鸿。
明日更期来此醉，不堪寂寞对衰翁。','',''),('quantangshi-34816','争名','司空圖','quantangshi','','卷35','争名岂在更搜奇，不朽才消一句诗。
穷辱未甘英气阻，乖疎还有正人知。
荷香浥露侵衣润，松影和风傍枕移。
只此共栖尘外境，无妨亦恋好文时。','',''),('quantangshi-34817','光启四年春戊申','司空圖','quantangshi','','卷35','乱后烧残数架书，峰前犹自恋吾庐。
忘机渐喜逢人少，览镜空怜待鹤疎。
孤屿池痕春涨满，小阑花韵午晴初。
酣歌自适逃名久，不必门多长者车。','',''),('quantangshi-34818','丁巳重阳','司空圖','quantangshi','','卷35','重阳未到已登临，探得黄花且独斟。
客舍喜逢连日雨，家山似响隔河砧。
乱来已失耕桑计，病后休论济活心。
自贺逢时能自弃，归鞭唯拍马鞯吟。','',''),('quantangshi-34819','喜王驾小仪重阳相访','司空圖','quantangshi','','卷35','白菊初开卧内明，闻君相访病身轻。
樽前且拨伤心事，溪上还随觅句行。
幽鹤傍人疑旧识，残蝉向日噪新晴。
拟将寂寞同留住，且劝康时立大名。','',''),('quantangshi-34820','酬张芬赦后见寄','司空圖','quantangshi','','卷35','紫凤朝衔五色书，阳春忽布网罗除。
已将心变寒灰后，岂料光生腐草余。
建水风烟收客泪，杜陵花烛梦郊居。
劳君故有诗相赠，欲报琼瑶愧不如。','',''),('quantangshi-34821','上元放二雉','司空圖','quantangshi','','卷35','婴网虽皆困，搴笼喜共归。
无心期尔报，相见莫惊飞。','',''),('quantangshi-34822','中秋','司空圖','quantangshi','','卷35','闲吟秋景外，万事觉悠悠。
此夜若无月，一年虚过秋。','',''),('quantangshi-34823','偶题','司空圖','quantangshi','','卷35','水榭花繁处，春晴日午前。
鸟窥临槛镜，马过隔墙鞭。','',''),('quantangshi-34824','闲步','司空圖','quantangshi','','卷35','几处白烟断，一川红树时。
坏桥侵辙水，残照背邨碑。','',''),('quantangshi-34825','春中','司空圖','quantangshi','','卷35','伏溜侵堦润，繁花隔竹香。
娇莺方晓听，无事过南塘。','',''),('quantangshi-34826','独望','司空圖','quantangshi','','卷35','绿树连邨暗，黄花出陌稀。
远陂春草绿，犹有水禽飞。','',''),('quantangshi-34827','杂题','司空圖','quantangshi','','卷35','孤枕闻莺起，幽怀独悄然。
地融春力润，花泛晓光鲜。','',''),('quantangshi-34828','漫题三首 一','司空圖','quantangshi','','卷35','乱后他乡节，烧残故国春。
自怜垂白首，犹伴踏青人。','',''),('quantangshi-34829','漫题三首 二','司空圖','quantangshi','','卷35','齿落伤情久，心惊健忘频。
蜗庐经岁客，蚕市异乡人。','',''),('quantangshi-34830','漫题三首 三','司空圖','quantangshi','','卷35','率怕人言谨，闲宜酒韵高。
山林若无虑，名利不难逃。','',''),('quantangshi-34831','河上二首 一','司空圖','quantangshi','','卷35','惨惨日将暮，驱羸独到庄。
沙痕傍墟落，风色入牛羊。','',''),('quantangshi-34832','河上二首 二','司空圖','quantangshi','','卷35','新霁田园处，夕阳禾黍明。
沙邨平见水，深巷有鸥声。','',''),('quantangshi-34833','早朝','司空圖','quantangshi','','卷35','白日新年好，青春上国多。
街平双阙近，尘起五云和。','',''),('quantangshi-34834','即事二首 一','司空圖','quantangshi','','卷35','茶爽添诗句，天清莹道心。
只留鹤一只，此外是空林。','',''),('quantangshi-34835','即事二首 二','司空圖','quantangshi','','卷35','御礼征奇策，人心注盛时。
从来留振滞，只待济临危。','',''),('quantangshi-34836','永夜','司空圖','quantangshi','','卷35','永夜疑无日，危时只赖山。
旷怀休戚外，孤迹是非间。','',''),('quantangshi-34837','秦关','司空圖','quantangshi','','卷35','形胜今虽在，荒凉恨不穷。
虎狼秦国破，狐兔汉陵空。','',''),('quantangshi-34838','渡江','司空圖','quantangshi','','卷35','秋江共僧渡，乡泪滴船回。
一夜吴船梦，家书立马开。','',''),('quantangshi-34839','退居漫题七首 一','司空圖','quantangshi','','卷35','花缺伤难缀，莺喧奈细听。
惜春春已晚，珍重草青青。','',''),('quantangshi-34840','退居漫题七首 二','司空圖','quantangshi','','卷35','堤柳自绵绵，幽人无恨牵。
只忧诗病发，莫寄校书牋。','',''),('quantangshi-34841','退居漫题七首 三','司空圖','quantangshi','','卷35','燕语曾来客，花催欲别人。
莫愁春又过，看着又新春。','',''),('quantangshi-34842','退居漫题七首 四','司空圖','quantangshi','','卷35','身外都无事，山中久避喧。
破巢看乳燕，留果待啼猨。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-34843','退居漫题七首 五','司空圖','quantangshi','','卷35','诗家通籍美，工部与司勋。
高贾虽难敌，微官偶胜君。','',''),('quantangshi-34844','退居漫题七首 六','司空圖','quantangshi','','卷35','努力省前非，人生上寿稀。
青云无直道，暗室有危机。','',''),('quantangshi-34845','退居漫题七首 七','司空圖','quantangshi','','卷35','燕拙营巢苦，鱼贪触网惊。
岂缘身外事，亦似我劳形。','',''),('quantangshi-34846','即事九首 一','司空圖','quantangshi','','卷35','宿雨川原霁，凭高景物新。
陂痕侵牧马，云影带耕人。','',''),('quantangshi-34847','即事九首 二','司空圖','quantangshi','','卷35','十年深隐地，一雨太平心。
匣涩休看劒，窗明复上琴。','',''),('quantangshi-34848','即事九首 三','司空圖','quantangshi','','卷35','明时那弃置，多病自迟留。
疎磬和吟断，残灯照卧幽。','',''),('quantangshi-34849','即事九首 四','司空圖','quantangshi','','卷35','衰鬓闲生少，丹梯望觉危。
松须依石长，鹤不傍人卑。','',''),('quantangshi-34850','即事九首 五','司空圖','quantangshi','','卷35','落叶频惊鹿，连峰欲映雕。
此生诗病苦，此病更萧条。','',''),('quantangshi-34851','即事九首 六','司空圖','quantangshi','','卷35','旅思又惊夏，庭前长小松。
远峰生贵气，残月歛衰容。','',''),('quantangshi-34852','即事九首 七','司空圖','quantangshi','','卷35','林鸟频窥静，家人亦笑慵。
旧居留稳枕，归卧听秋钟。','',''),('quantangshi-34853','即事九首 八','司空圖','quantangshi','','卷35','华宇知难保，烧来又却修。
只应巢燕惜，未必主人留。','',''),('quantangshi-34854','即事九首 九','司空圖','quantangshi','','卷35','幽鸟穿篱去，邻翁采药回。
云从潭底出，花向佛前开。','',''),('quantangshi-34855','松滋渡二首 一','司空圖','quantangshi','','卷35','步上短亭久，看回官渡船。
江乡宜晚霁，楚老语丰年。','',''),('quantangshi-34856','松滋渡二首 二','司空圖','quantangshi','','卷35','楚岫接乡思，茫茫归路迷。
更堪斑竹驿，初听鹧鸪啼。','',''),('quantangshi-34857','华清宫','司空圖','quantangshi','','卷35','帝业山河固，离宫宴幸频。
岂知驱战马，只是太平人。','',''),('quantangshi-34858','牛头寺','司空圖','quantangshi','','卷35','终南最佳处，禅诵出青霄。
羣木澄幽寂，疎烟泛泬寥。','',''),('quantangshi-34859','感时上卢相','司空圖','quantangshi','','卷35','兵待皇威振，人随国步安。
万方休望幸，封岳始鸣銮。','',''),('quantangshi-34860','乱后三首 一','司空圖','quantangshi','','卷35','丧乱家难保，艰虞病懒医。
空将忧国泪，犹拟洒丹墀。','',''),('quantangshi-34861','乱后三首 二','司空圖','quantangshi','','卷35','流芳能几日，惆怅又闻蝉。
行在多新贵，幽栖独长年。','',''),('quantangshi-34862','乱后三首 三','司空圖','quantangshi','','卷35','世事尝艰险，僧居惯寂寥。
美香闻夜合，清景见寅朝。','',''),('quantangshi-34863','秋景','司空圖','quantangshi','','卷35','景物皆难驻，伤春复怨秋。
旋书红叶落，拟画碧云收。','',''),('quantangshi-34864','避乱','司空圖','quantangshi','','卷35','离乱身偶在，窜迹任浮沈。
虎暴荒居逈，萤孤黑夜深。','',''),('quantangshi-34865','长亭','司空圖','quantangshi','','卷35','梅雨和乡泪，终年共酒衣。
殷勤华表鹤，羡尔亦曾归。','',''),('quantangshi-34866','邨西杏花二首 一','司空圖','quantangshi','','卷35','薄腻力偏羸，看看怆别时。
东风狂不惜，西子病难医。','',''),('quantangshi-34867','邨西杏花二首 二','司空圖','quantangshi','','卷35','肌细分红脉，香浓破紫苞。
无因留得翫，争忍折来抛。','',''),('quantangshi-34868','独坐','司空圖','quantangshi','','卷35','幽径入桑麻，坞西逢一家。
编篱薪带茧，补屋草和花。','',''),('quantangshi-34869','借居','司空圖','quantangshi','','卷35','借住郊园久，仍逢夏景新。
绿苔行屐稳，黄鸟傍窗频。','',''),('quantangshi-34870','重阳','司空圖','quantangshi','','卷35','菊开犹阻雨，蝶意切于人。
亦应知暮节，不比惜残春。','',''),('quantangshi-34871','偶书五首 一','司空圖','quantangshi','','卷35','衰榭当何忏，惟应悔壮图。
磬声花外远，人影塔前孤。','',''),('quantangshi-34872','偶书五首 二','司空圖','quantangshi','','卷35','色变莺雏长，竿齐笋箨垂。
白头身偶在，清夏景还移。','',''),('quantangshi-34873','偶书五首 三','司空圖','quantangshi','','卷35','蜀妓轻成妙，吴娃狎共纤。
晚妆留拜月，卷上水精帘。','',''),('quantangshi-34874','偶书五首 四','司空圖','quantangshi','','卷35','独步荒郊暮，沉思远墅幽。
平生多少事，弹指一时休。','',''),('quantangshi-34875','偶书五首 五','司空圖','quantangshi','','卷35','掩谤知迎吠，欺心见强颜。
有名人易困，无契债难还。','',''),('quantangshi-34876','杂题九首 一','司空圖','quantangshi','','卷35','病来胜未病，名缚便忘名。
今日甘为客，当时注愍征。','',''),('quantangshi-34877','杂题九首 二','司空圖','quantangshi','','卷35','暑湿深山雨，荒居破屋灯。
此生无忏处，此去作高僧。','',''),('quantangshi-34878','杂题九首 三','司空圖','quantangshi','','卷35','不须频怅望，且喜脱喧嚣。
亦有终焉意，陂南看稻苗。','',''),('quantangshi-34879','杂题九首 四','司空圖','quantangshi','','卷35','楼带猨吟迥，庭容鹤舞宽。
晒书因阅画，封药偶和丹。','',''),('quantangshi-34880','杂题九首 五','司空圖','quantangshi','','卷35','宴罢论诗久，亭高拜表频。
岸香蕃舶月，洲色海烟春。','',''),('quantangshi-34881','杂题九首 六','司空圖','quantangshi','','卷35','驿步堤萦阁，军城鼓振桥。
鸥和湖雁下，雪隔岭梅飘。','',''),('quantangshi-34882','杂题九首 七','司空圖','quantangshi','','卷35','带雪南山道，和钟北阙明。
太平当共贺，开化喝来声。','',''),('quantangshi-34883','杂题九首 八','司空圖','quantangshi','','卷35','舴艋猨偷上，蜻蜓燕竞飞。
樵香烧桂子，苔湿挂莎衣。','',''),('quantangshi-34884','杂题九首 九','司空圖','quantangshi','','卷35','溪涨渔家近，烟收鸟道高。
松花飘可惜，睡里洒离骚。','',''),('quantangshi-34885','古乐府','司空圖','quantangshi','','卷35','一叶随西风，君行亦向东。
知妾飞书意，无劳待早鸿。','',''),('quantangshi-34886','有感','司空圖','quantangshi','','卷35','灯影看须黑，墙阴惜草青。
岁阑悲物我，同是冒霜萤。','',''),('quantangshi-34887','休休亭','司空圖','quantangshi','','卷35','且喜安能保，那堪病更忧。
可怜藜杖者，真个种瓜侯。','',''),('quantangshi-34888','漫书二首 一','司空圖','quantangshi','','卷35','剩欲逢花折，判须冒雨频。
晴明开渐少，莫怕湿新巾。','',''),('quantangshi-34889','漫书二首 二','司空圖','quantangshi','','卷35','小蝶尔何竞，追飞不惮劳。
远教羣雀见，宁悟祸梯高。','',''),('quantangshi-34890','岁尽二首 一','司空圖','quantangshi','','卷35','明日添一岁，端忧奈尔何。
冲寒出洞口，犹校夕阳多。','',''),('quantangshi-34891','岁尽二首 二','司空圖','quantangshi','','卷35','莫话伤心事，投春满鬓霜。
殷勤共尊酒，今岁只残阳。','',''),('quantangshi-34892','牡丹','司空圖','quantangshi','','卷35','得地牡丹盛，晓添龙麝香。
主人犹自惜，锦幕护春霜。','',''),('quantangshi-34893','乱后','司空圖','quantangshi','','卷35','羽书传栈道，风火隔乡关。
病眼那堪泣，伤心不到间。','',''),('quantangshi-34894','春山','司空圖','quantangshi','','卷35','可是武陵溪，春芳着路迷。
