云韶韵俗停瑶瑟，鸾鹤飞低拂宝炉。','',''),('quantangshi-34985','劒器','司空圖','quantangshi','','卷35','楼下公孙昔擅场，空教女子爱军装。
潼关一败吴儿喜，簇马骊山看御汤。','',''),('quantangshi-34986','乙丑人日','司空圖','quantangshi','','卷35','自怪扶持七十身，归来又见故乡春。
今朝人日逢人喜，不料偷生作老人。','',''),('quantangshi-34987','携仙箓九首 一','司空圖','quantangshi','','卷35','岳北秋空渭北川，晴云渐薄薄如烟。
