听君总画麒麟阁，还我闲眠舴艋舟。','',''),('quantangshi-34991','携仙箓九首 五','司空圖','quantangshi','','卷35','仙凡路阻两难留，烟树人间一片秋。
若道阴功能济活，且将方寸自焚修。','',''),('quantangshi-34992','携仙箓九首 六','司空圖','quantangshi','','卷35','若有阴功救未然，玉皇品籍亦搜贤。
应知谭笑还高谢，别就沧洲赞上仙。','',''),('quantangshi-34993','携仙箓九首 七','司空圖','quantangshi','','卷35','英名何用苦搜奇，不朽才销一句诗。
却赖风波阻三岛，老臣犹得恋明时。','',''),('quantangshi-34994','携仙箓九首 八','司空圖','quantangshi','','卷35','剪取红云剩写诗，年年高会趂花时。
水精楼阁分明见，只欠霞浆别着旗。','',''),('quantangshi-34995','携仙箓九首 九','司空圖','quantangshi','','卷35','此生得作太平人，只向尘中便出尘。
移取碧桃花万树，年年自乐故乡春。','',''),('quantangshi-34996','浪淘沙','司空圖','quantangshi','','卷35','不必长漂玉洞花，曲中偏爱浪淘沙。
黄河却胜天河水，万里萦纡入汉家。','',''),('quantangshi-34997','赠日东鉴禅师','司空圖','quantangshi','','卷35','故国无心度海潮，老禅方丈倚中条。
