恼得闲人作酒病，刚须又扑越溪茶。','',''),('quantangshi-34999','暮春对柳二首 二','司空圖','quantangshi','','卷35','洞中犹说看桃花，轻絮狂飞自俗家。
正是阶前开远信，小娥旋拂碾新茶。','',''),('quantangshi-35000','戊午三月晦二首 一','司空圖','quantangshi','','卷35','随风逐浪剧蓬萍，圆首何曾解最灵。
笔砚近来多自弃，不关妖气暗文星。','',''),('quantangshi-35001','戊午三月晦二首 二','司空圖','quantangshi','','卷35','牛夸棋品无勍敌，谢占诗家作上流。
