莺也解啼花也发，不关心事最堪憎。','',''),('quantangshi-35003','偶书五首 二','司空圖','quantangshi','','卷35','自有池荷作扇摇，不关风动爱芭蕉。
只怜直上抽红蘂，似我丹心向本朝。','',''),('quantangshi-35004','偶书五首 三','司空圖','quantangshi','','卷35','曾看轻舟渡远津，无风着岸不经旬。
只缘命蹇须知命，却是人争阻得人。','',''),('quantangshi-35005','偶书五首 四','司空圖','quantangshi','','卷35','上谷何曾解有情，有情人自惜君行。
证因池上今生愿，的的他生作化生。','',''),('quantangshi-35006','偶书五首 五','司空圖','quantangshi','','卷35','新店南原后夜程，黄河风浪信难平。
渡头杨柳知人意，为惹官船莫放行。','',''),('quantangshi-35007','喜山鹊初归三首 一','司空圖','quantangshi','','卷35','翠衿红觜便知机，久避重罗稳处飞。
只为从来偏护惜，窗前今贺主人归。','',''),('quantangshi-35008','喜山鹊初归三首 二','司空圖','quantangshi','','卷35','山中只是惜珍禽，语不分明识尔心。
