谁料平生臂鹰手，挑灯自送佛前钱。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35069','力疾山下吴邨看杏花十九首 一','司空圖','quantangshi','','卷36','春来渐觉一川明，马上繁花作阵迎。
掉臂只将诗酒敌，不劳金鼓助横行。','',''),('quantangshi-35070','力疾山下吴邨看杏花十九首 二','司空圖','quantangshi','','卷36','阊阖曾排捧御炉，犹看晓月认金铺。
羸形不画凌烟阁，只为微才激壮图。','',''),('quantangshi-35071','力疾山下吴邨看杏花十九首 三','司空圖','quantangshi','','卷36','镜留雪鬓暖消无，春到棃花日又晡。
移取扶桑堦下种，年年看长碍金乌。','',''),('quantangshi-35072','力疾山下吴邨看杏花十九首 四','司空圖','quantangshi','','卷36','折来未尽不须休，年少争来莫与留。
更愿狂风知我意，一时吹向海西头。','',''),('quantangshi-35073','力疾山下吴邨看杏花十九首 五','司空圖','quantangshi','','卷36','才情百巧鬬风光，却笑雕花刻叶忙。
熨帖新巾来与裹，犹看腾踏少年场。','',''),('quantangshi-35074','力疾山下吴邨看杏花十九首 六','司空圖','quantangshi','','卷36','浮世荣枯总不知，且忧花阵被风欺。
侬家自有麒麟阁，第一功名只赏诗。','',''),('quantangshi-35075','力疾山下吴邨看杏花十九首 七','司空圖','quantangshi','','卷36','白衫裁袖本教宽，朱紫由来亦一般。
王老小儿吹笛看，我侬试舞尔侬看。','',''),('quantangshi-35076','力疾山下吴邨看杏花十九首 八','司空圖','quantangshi','','卷36','单床薄被又羁栖，待到花开亦甚迷。
若道折多还有罪，只应莺啭是金鸡。','',''),('quantangshi-35077','力疾山下吴邨看杏花十九首 九','司空圖','quantangshi','','卷36','近来桃李半烧枯，归卧乡园只老夫。
莫算明年人在否，不知花得更开无。','',''),('quantangshi-35078','力疾山下吴邨看杏花十九首 十','司空圖','quantangshi','','卷36','汉王何事损精神，花满深宫不见春。
穠艳三千临粉镜，独悲掩面李夫人。','',''),('quantangshi-35079','力疾山下吴邨看杏花十九首 十一','司空圖','quantangshi','','卷36','能艳能芳自一家，胜鸾胜凤胜烟霞。
客来须共醒醒看，碾尽明昌几角茶。','',''),('quantangshi-35080','力疾山下吴邨看杏花十九首 十二','司空圖','quantangshi','','卷36','造化无端欲自神，裁红剪翠为新春。
不如分减闲心力，更助英豪济活人。','',''),('quantangshi-35081','力疾山下吴邨看杏花十九首 十三','司空圖','quantangshi','','卷36','徘徊自劝莫沾缨，分付年年谷口莺。
却赖无情容易别，有情早个不胜情。','',''),('quantangshi-35082','力疾山下吴邨看杏花十九首 十四','司空圖','quantangshi','','卷36','闲步偏宜舞袖迎，春光何事独无情。
垂杨合是诗家物，只爱敷溪道北生。','',''),('quantangshi-35083','力疾山下吴邨看杏花十九首 十五','司空圖','quantangshi','','卷36','亦知王大是昌龄，杜二其如律韵清。
还有酸寒堪笑处，拟夸朱绂更峥嵘。','',''),('quantangshi-35084','力疾山下吴邨看杏花十九首 十六','司空圖','quantangshi','','卷36','潘郎爱说是诗家，枉占河阳一县花。
千载几人搜警句，补方金字爱晴霞。','',''),('quantangshi-35085','力疾山下吴邨看杏花十九首 十七','司空圖','quantangshi','','卷36','行乐溪边步转迟，出山渐减探花期。
去年四度今三度，恐到凭人折去时。','',''),('quantangshi-35086','力疾山下吴邨看杏花十九首 十八','司空圖','quantangshi','','卷36','此身衰病转堪嗟，长忍春寒独惜花。
更恨新诗无纸写，蜀牋堆积是谁家。','',''),('quantangshi-35087','力疾山下吴邨看杏花十九首 十九','司空圖','quantangshi','','卷36','昨日黄昏始看回，梦中相约又衔杯。
起来闻到风飘却，犹拟教人扫取来。','',''),('quantangshi-35088','少仪','司空圖','quantangshi','','卷36','昨日登班缀柏台，更惭起草属微才。
锦窠不是寻常锦，兼向丘迟夺得来。','',''),('quantangshi-35089','重阳四首 一','司空圖','quantangshi','','卷36','檐前减燕菊添芳，燕尽庭前菊又荒。
老大比他年少少，每逢佳节更悲凉。','',''),('quantangshi-35090','重阳四首 二','司空圖','quantangshi','','卷36','雨寒莫待菊花催，须怕晴空暖并开。
开却一枝开却尽，且随幽蝶更徘徊。','',''),('quantangshi-35091','重阳四首 三','司空圖','quantangshi','','卷36','青娥懒唱无衣换，黄菊新开乞酒难。
长有长亭惆怅事，隔河更得对凭栏。','',''),('quantangshi-35092','重阳四首 四','司空圖','quantangshi','','卷36','白发怕寒梳更懒，黄花晴日照初开。
篱头应是蝶相报，已被邻家携酒来。','',''),('quantangshi-35093','长命缕','司空圖','quantangshi','','卷36','他乡处处堪悲事，残照依依惜别天。
此去知名长命缕，殷勤为我唱花前。','',''),('quantangshi-35094','柏东','司空圖','quantangshi','','卷36','冥得机心岂在僧，柏东闲步爱腾腾。
免教世路人相忌，逢着村醪亦不憎。','',''),('quantangshi-35095','歌者十二首 一','司空圖','quantangshi','','卷36','追逐翻嫌傍管弦，金钗击节自当筵。
