看取明年春意动，更于何处最先知。','',''),('quantangshi-35118','杨柳枝寿杯词十八首 十一','司空圖','quantangshi','','卷36','昔年行乐及芳时，一上丹梯桂一枝。
笑问江头醉公子，饶君满把麴尘丝。','',''),('quantangshi-35119','杨柳枝寿杯词十八首 十二','司空圖','quantangshi','','卷36','渡头残照一行新，独自依依向北人。
莫恨乡程千里远，眼中从此故乡春。','',''),('quantangshi-35120','杨柳枝寿杯词十八首 十三','司空圖','quantangshi','','卷36','絮惹轻枝雪未飘，小溪烟束带危桥。
邻家女伴频攀折，不觉回身罥翠翘。','',''),('quantangshi-35121','杨柳枝寿杯词十八首 十四','司空圖','quantangshi','','卷36','处处萦空百万枝，一枝枝好更题诗。
隔城远岫招行客，便与朱楼当酒旗。','',''),('quantangshi-35122','杨柳枝寿杯词十八首 十五','司空圖','quantangshi','','卷36','锦城分得映金沟，两岸年年引胜游。','',''),('quantangshi-35123','杨柳枝寿杯词十八首 十六','司空圖','quantangshi','','卷36','日暖津头絮已飞，看看还是送君归。
莫言万绪牵愁思，缉取长绳系落晖。','',''),('quantangshi-35124','杨柳枝寿杯词十八首 十七','司空圖','quantangshi','','卷36','大堤时节近清明，霞衬烟笼遶郡城。
好是梨花相映处，更胜松雪日初晴。','',''),('quantangshi-35125','杨柳枝寿杯词十八首 十八','司空圖','quantangshi','','卷36','圣主千年乐未央，御沟金翠满垂杨。
年年织作升平字，高映南山献寿觞。','',''),('quantangshi-35126','山鹊','司空圖','quantangshi','','卷36','多惊本为好毛衣，只赖人怜始却归。
众鸟自知颜色减，妬他偏向眼前飞。','',''),('quantangshi-35127','李居士','司空圖','quantangshi','','卷36','高风只在五峰前，应是精灵降作贤。
万里无云惟一鹤，乡中同看却升天。','',''),('quantangshi-35128','杏花','司空圖','quantangshi','','卷36','诗家偏为此伤情，品韵由来莫与争。
解笑亦应兼解语，只应慵语倩莺声。','',''),('quantangshi-35129','白菊三首 一','司空圖','quantangshi','','卷36','不疑陶令是狂生，作赋其如有定情。
犹胜江南隐居士，诗魔终袅负孤名。','',''),('quantangshi-35130','白菊三首 二','司空圖','quantangshi','','卷36','自古诗人少显荣，逃名何用更题名。
诗中有虑犹须戒，莫向诗中着不平。','',''),('quantangshi-35131','白菊三首 三','司空圖','quantangshi','','卷36','登高可羡少年场，白菊堆边鬓似霜。
益算更希沾上药，今朝第七十重阳。','',''),('quantangshi-35132','听雨','司空圖','quantangshi','','卷36','半夜思家睡里愁，雨声落落屋檐头。
照泥星出依前黑，淹烂庭花不肯休。','',''),('quantangshi-35133','杨柳枝二首 一','司空圖','quantangshi','','卷36','陶家五柳簇衡门，还有高情爱此君。
何处更添诗境好，新蝉欹枕每先闻。','',''),('quantangshi-35134','杨柳枝二首 二','司空圖','quantangshi','','卷36','数枝珍重蘸沧浪，无限尘心暂免忙。
