自从南至歌风顶，始见人烟外有人。','',''),('quantangshi-35137','漫书','司空圖','quantangshi','','卷36','乐退安贫知是分，成家报国亦何惭。
到还僧院心期在，瑟瑟澄鲜百丈潭。','',''),('quantangshi-35138','杂题二首 一','司空圖','quantangshi','','卷36','棋局长携上钓船，杀中棋杀胜丝牵。
洪炉任铸千钧鼎，只在磻溪一缕悬。','',''),('quantangshi-35139','杂题二首 二','司空圖','quantangshi','','卷36','晓镜高窗气象深，自怜清格笑尘心。
世间不为蛾眉误，海上方应鹤背吟。','',''),('quantangshi-35140','题休休亭','司空圖','quantangshi','','卷36','咄，诺。
休休休，莫莫莫。
伎两虽多性灵恶，赖是长教闲处着。
休休休，莫莫莫。
一局棋，一炉药。
天意时情可料度，白日偏催快活人。
黄金难买堪骑鹤，若曰尔何能，答言耐辱莫。','',''),('quantangshi-35141','冯燕歌','司空圖','quantangshi','','卷36','魏中义士有冯燕，游侠幽并最少年。
避讐偶作滑台客，嘶风跃马来翩翩。
此时恰遇莺花月，堤上轩车昼不绝。
两面高楼语笑声，指点行人情暗结。
掷果潘郎谁不慕，朱门别见红妆露。
故故推门掩不开，似教欧轧传言语。
冯生敲镫袖笼鞭，半拂垂杨半惹烟。
树间春鸟知人意，的的心期暗与传。
传道张婴偏嗜酒，从此香闺为我有。
梁间客燕正相欺，屋上鸣鸠空自鬬。
婴归醉卧非讐汝，岂知负过人怀惧。
燕依户扇欲潜逃，巾在枕傍指令取。
谁言狼戾心能忍，待我情深情不隐。
回身本谓取巾难，倒柄方知授霜刅。
冯君抚劒即迟疑，自顾平生心不欺。
尔能负彼必相负，假手他人复在谁。
窗间红艳犹可掬，熟视花钿情不足。
唯将大义断胸襟，粉颈初回如切玉。
凤皇钗碎各分飞，怨魄娇魂何处追。
凌波如唤游金谷，羞彼[揶揄]泪满衣。
新人藏匿旧人起，白昼喧呼骇邻里。
诬执张婴不自明，贵免生前遭考捶。
官将赴市拥红尘，掉臂人来擗看人。
传声莫遣有冤滥，盗杀婴家即我身。
初闻僚吏翻疑叹，呵叱风狂词不变。
缧囚解缚犹自疑，疑是梦中方脱免。
未死劝君莫浪言，临危不顾始知难。
已为不平能割爱，更将身命救深冤。
白马贤侯贾相公，长悬金帛募才雄。
拜章请赎冯燕罪，千古三河激义风。
黄河东注无时歇，注尽波澜名不灭。
为感词人沈下贤，长歌更与分明说。
此君精爽知犹在，长与人间留炯诫。
铸作金燕香作堆，焚香酬酒听歌来。','',''),('quantangshi-35142','寄薛起居','司空圖','quantangshi','','卷36','小域新衔贺圣朝，亦知蹇分巧难抛。
麤才自合无岐路，不破工夫漫解嘲。','',''),('quantangshi-35143','月下留丹竈','司空圖','quantangshi','','卷36','月下留丹竈，坛边树羽衣。
异香人不觉，残夜鹤分飞。
朝会初元盛，蓬瀛旧侣稀。
瑶函真迹在，妖魅敢扬威。','',''),('quantangshi-35144','元日','司空圖','quantangshi','','卷36','甲子今重数，生涯只自怜。
殷勤元日日，欹午又明年。','',''),('quantangshi-35145','洛阳咏古','司空圖','quantangshi','','卷36','石勒童年有战机，洛阳长啸倚门时。
晋朝不是王夷甫，大智何由得预知。','',''),('quantangshi-35146','诗品二十四则 雄浑','司空圖','quantangshi','','卷36','大用外腓，真体内充。
返虚入浑，积健为雄。
具备万物，横绝太空。
荒荒油云，寥寥长风。
超以象外，得其环中。
持之匪强，来之无穷。','',''),('quantangshi-35147','诗品二十四则 冲淡','司空圖','quantangshi','','卷36','素处以默，妙机其微。
饮之太和，独鹤与飞。
犹之惠风，苒苒在衣。
阅音修篁，美曰载归。
遇之匪深，即之愈稀。
脱有形似，握手已违。','',''),('quantangshi-35148','诗品二十四则 纤穠','司空圖','quantangshi','','卷36','采采流水，蓬蓬远春。
窈窕深谷，时见美人。
碧桃满树，风日水滨。
柳阴路曲，流莺比邻。
乘之愈往，识之愈真。
如将不尽，与古为新。','',''),('quantangshi-35149','诗品二十四则 沈着','司空圖','quantangshi','','卷36','绿杉野屋，落日气清。
脱巾独步，时闻鸟声。
鸿雁不来，之子远行。
所思不远，若为平生。
海风碧云，夜渚月明。
如有佳语，大河前横。','',''),('quantangshi-35150','诗品二十四则 高古','司空圖','quantangshi','','卷36','畸人乘真，手把芙蓉。
泛彼浩劫，窅然空纵。
月出东斗，好风相从。
太华夜碧，人闻清钟。
虚伫神素，脱然畦封。
黄唐在独，落落玄宗。','',''),('quantangshi-35151','诗品二十四则 典雅','司空圖','quantangshi','','卷36','玉壶买春，赏雨茆屋。
坐中佳士，左右修竹。
白云初晴，幽鸟相逐。
眠琴绿阴，上有飞瀑。
落花无言，人淡如菊。
书之岁华，其曰可读。','',''),('quantangshi-35152','诗品二十四则 洗炼','司空圖','quantangshi','','卷36','犹鑛出金，如铅出银。
超心炼冶，绝爱[缁]磷。
空潭泻春，古镜照神。
体素储洁，乘月返真。
载瞻星辰，载歌幽人。
流水今日，明月前身。','',''),('quantangshi-35153','诗品二十四则 劲健','司空圖','quantangshi','','卷36','行神如空，行气如虹。
巫峡千寻，走云连风。
饮真茹强，蓄素守中。
喻彼行健，是谓存雄。
天地与立，神化攸同。
期之以实，御之以终。','',''),('quantangshi-35154','诗品二十四则 绮丽','司空圖','quantangshi','','卷36','神存富贵，始轻黄金。
浓尽必枯，浅者屡深。
露余山青，红杏在林。
月明华屋，画桥碧阴。
金尊酒满，共客弹琴。
取之自足，良殚美襟。','',''),('quantangshi-35155','诗品二十四则 自然','司空圖','quantangshi','','卷36','俯拾即是，不取诸邻。
俱道适往，着手成春。
如逢花开，如瞻岁新。
真予不夺，强得易贫。
幽人空山，过水采苹。
薄言情晤，悠悠天钧。','',''),('quantangshi-35156','诗品二十四则 含蓄','司空圖','quantangshi','','卷36','不着一字，尽得风流。
语不涉难，已不堪忧。
是有真宰，与之沈浮。
如渌满酒，花时返秋。
悠悠空尘，忽忽海沤。
浅深聚散，万取一收。','',''),('quantangshi-35157','诗品二十四则 豪放','司空圖','quantangshi','','卷36','观花匪禁，吞吐大荒。
由道返气，处得以狂。
天风浪浪，海山苍苍。
真力弥满，万象在旁。
前招三辰，后引凤皇。
晓策六鳌，濯足扶桑。','',''),('quantangshi-35158','诗品二十四则 精神','司空圖','quantangshi','','卷36','欲返不尽，相期与来。
明漪绝底，奇花初胎。
青春鹦鹉，杨柳池台。
碧山人来，清酒满杯。
生气远出，不着死灰。
妙造自然，伊谁与裁。','',''),('quantangshi-35159','诗品二十四则 缜密','司空圖','quantangshi','','卷36','是有真迹，如不可知。
意象欲生，造化已奇。
水流花开，清露未曦。
要路愈远，幽行为迟。
语不欲犯，思不欲痴。
犹春于绿，明月雪时。','',''),('quantangshi-35160','诗品二十四则 疎野','司空圖','quantangshi','','卷36','惟性所宅，真取弗羁。
拾物自富，与率为期。
筑屋松下，脱帽看诗。
但知旦暮，不辨何时。
倘然适意，岂必有为。
若其天放，如是得之。','',''),('quantangshi-35161','诗品二十四则 清奇','司空圖','quantangshi','','卷36','娟娟羣松，下有漪流。
晴雪满汀，隔溪渔舟。
可人如玉，步屧寻幽。
载行载止，空碧悠悠。
神出古异，淡不可收。
如月之曙，如气之秋。','',''),('quantangshi-35162','诗品二十四则 委曲','司空圖','quantangshi','','卷36','登彼太行，翠遶羊肠。
杳霭流玉，悠悠花香。
力之于时，声之于羌。
似往已回，如幽匪藏。
水理漩洑，鹏风翱翔。
道不自器，与之圆方。','',''),('quantangshi-35163','诗品二十四则 实境','司空圖','quantangshi','','卷36','取语甚直，计思匪深。
忽逢幽人，如见道心。
晴磵之曲，碧松之阴。
一客荷樵，一客听琴。
情性所至，妙不自寻。
遇之自天，冷然希音。','',''),('quantangshi-35164','诗品二十四则 悲慨','司空圖','quantangshi','','卷36','大风卷水，林木为摧。
意苦若死，招憩不来。
百岁如流，富贵冷灰。
大道日往，若为雄才。
壮士拂劒，浩然弥哀。
萧萧落叶，漏雨苍苔。','',''),('quantangshi-35165','诗品二十四则 形容','司空圖','quantangshi','','卷36','绝伫灵素，少回清真。
如觅水影，如写阳春。
风云变态，花草精神。
海之波澜，山之嶙峋。
俱似大道，妙契同尘。
离形得似，庶几斯人。','',''),('quantangshi-35166','诗品二十四则 超诣','司空圖','quantangshi','','卷36','匪神之灵，匪机之微。
如将白云，清风与归。
远引若至，临之已非。
少有道契，终与俗违。
乱山高木，碧苔芳晖。
诵之思之，其声愈稀。','',''),('quantangshi-35167','诗品二十四则 飘逸','司空圖','quantangshi','','卷36','落落欲往，矫矫不羣。
缑山之鹤，华顶之云。
高人画中，令色絪緼。
御风蓬叶，泛彼无垠。
如不可执，如将有闻。
识者已领，期之愈分。','',''),('quantangshi-35168','诗品二十四则 旷达','司空圖','quantangshi','','卷36','生者百岁，相去几何。
欢乐苦短，忧愁实多。
何如尊酒，日往烟萝。
花覆茆檐，疎雨相过。
倒酒既尽，杖藜行过。
孰不有古，南山峨峨。','',''),('quantangshi-35169','诗品二十四则 流动','司空圖','quantangshi','','卷36','若纳水輨，如转丸珠。
夫岂可道，假体遗愚。
荒荒坤轴，悠悠天枢。
载要其端，载同其符。
超超神明，返返冥无。
来往千载，是之谓乎。','',''),('quantangshi-35170','句','司空圖','quantangshi','','卷36','忍事敌灾星，物望倾心久。
凶渠破胆频。
鼎饫和方济，台阶润欲平。
夜短猨悲减，风和鹊喜虚。
骅骝思故第，鹦鹉失佳人。
鲸鲵人海涸，魑魅棘林幽。
棋声花院闭，幡影石坛高。
地凉清鹤梦，林静肃僧仪。
晚妆留拜月，春睡更生香。
隔谷见鸡犬，山苗接楚田。
人家寒食月，花影午时天。
官路好禽声，轩车驻晚程。
南楼山最秀，北路邑偏清。
多病形容五十三，谁邻借笏趂朝参。
十年太华无知己，只得虚中两首诗。
看师逸迹两师宜，高适歌行李白诗。','',''),('quantangshi-35171','送边上从事','周繇','quantangshi','','卷36','戎装佩镆鎁，走马逐轻车。
衰草城边路，残阳垄上笳。
黄河穿汉界，青冢出胡沙。
提笔男儿事，功名立可夸。','',''),('quantangshi-35172','送洛阳崔员外','周繇','quantangshi','','卷36','塞诏除嵩洛，观图见废兴。
城迁周古鼎，地列汉诸陵。
日送归朝客，时招住岳僧。
郡斋台阁满，公退即吟登。','',''),('quantangshi-35173','送人尉黔中','周繇','quantangshi','','卷36','盘山行几驿，水路复通巴。
峡涨三川雪，园开四季花。
公庭飞白鸟，官俸请丹砂。
知尉黔中后，高吟采物华。','',''),('quantangshi-35174','送宇文虞','周繇','quantangshi','','卷36','此别欲何往，未言归故林。
行车新岁近，落日乱山深。
野店寒无客，风巢动有禽。
潜知经目事，大半是愁吟。','',''),('quantangshi-35175','题东林寺虎掊泉','周繇','quantangshi','','卷36','胜致通幽感，灵泉有虎掊。
爪抬山脉断，掌托石心抝。
竹蔼疑相近，松阴盖亦交。
转令栖遁者，真境逾难抛。','',''),('quantangshi-35176','登甘露寺','周繇','quantangshi','','卷36','盘江上几层，峭壁半垂藤。
殿锁南朝像，龛禅外国僧。
海涛摏砌槛，山雨洒窗灯。
日暮疎钟起，声声彻广陵。','',''),('quantangshi-35177','甘露寺东轩','周繇','quantangshi','','卷36','每日怜晴眺，闲吟只自娱。
山从平地有，水到远天无。
老树多封楚，轻烟暗染吴。
虽居此廊下，入户亦踌蹰。','',''),('quantangshi-35178','甘露寺北轩','周繇','quantangshi','','卷36','晓色宜闲望，山风远益清。
白云连晋阁，碧树尽芜城。
水静沙痕出，烟消野火平。
最堪佳此境，为我长诗情。','',''),('quantangshi-35179','咏萤','周繇','quantangshi','','卷36','熠熠与娟娟，池塘竹树边。
乱飞同曳火，成聚却无烟。
微雨洒不灭，清风吹欲燃。
旧曾书按上，频把作囊悬。','',''),('quantangshi-35180','望海','周繇','quantangshi','','卷36','苍茫空泛日，四顾绝人烟。
半浸中华岸，旁通异域船。
岛间应有国，波外恐无天。
欲作乘槎客，翻愁去隔年。','',''),('quantangshi-35181','送杨环校书归广南','周繇','quantangshi','','卷36','天南行李半波涛，滩树枝枝拂戏猱。
初着蓝衫从远峤，乍辞云署泊轻艘。
山村象踏桄榔叶，海外人收翡翠毛。
名宦两成归旧隐，徧寻亲友兴何饶。','',''),('quantangshi-35182','经故宅有感','周繇','quantangshi','','卷36','身没南荒雨露赊，朱门空锁旧繁华。
池塘凿就方通水，桃杏栽成未见花。
异代图书藏几箧，倾城罗绮散谁家。
昔年埏埴生灵地，今日生人为叹嗟。','',''),('quantangshi-35183','送入蕃使','周繇','quantangshi','','卷36','猎猎旗幡过大荒，敕书犹带御烟香。
滹沱河冻军回探，逻逤城孤雁着行。
远寨风狂移帐幕，平沙日晚卧牛羊。
早终册礼朝天阙，莫遣虬髭染塞霜。','',''),('quantangshi-35184','白石潭秋霁作','周繇','quantangshi','','卷36','潭心烟雾破斜晖，殷殷雷声隔翠微。
崖蹙盘涡翻蜃窟，滩吹白石上渔矶。
陵风舴艋讴哑去，出水鸬鷀薄泊飞。
秋霁更谁同此望，远钟时见一僧归。','',''),('quantangshi-35185','题金陵栖霞寺赠月公','周繇','quantangshi','','卷36','明家不要买山钱，施作清池种白莲。
松桧老依云外地，楼台深锁洞中天。
风经绝顶回疎雨，石倚危屏挂落泉。
欲结茅庵伴师住，肯饶多少薜萝烟。','',''),('quantangshi-35186','嘲段成式','周繇','quantangshi','','卷36','蹙鞠且徒为，宁如目送时。
报讐慙选耎，存想恨逶迟。
促坐疑辟咡，衔杯强朵颐。
恣情窥窈窕，曾恃好风姿。
色授应难夺，神交愿莫辞。
请君看曲谱，不负少年期。','',''),('quantangshi-35187','送江州薛尚书','周繇','quantangshi','','卷36','匡庐千万峯，影匝郡城中。
忽佩虎符去，遥疑鸟道通。
烟霞时满郭，波浪暮连空。
树翳楼台月，帆飞鼓角风。
郡斋多岳客，乡户半渔翁。
王事行春外，题诗寄远公。','',''),('quantangshi-35188','津头望白水','周繇','quantangshi','','卷36','晴江暗涨岸吹沙，山畔船冲树杪斜。
城郭半淹桥市闹，鹭鸶缭绕入人家。','',''),('quantangshi-35189','公子行','周繇','quantangshi','','卷36','青山薄薄漏春风，日暮鸣鞭柳影中。
回望玉楼人不见，酒旗深处勒花骢。','',''),('quantangshi-35190','看牡丹赠段成式','周繇','quantangshi','','卷36','金蘂霞英叠彩香，初疑少女出兰房。
逡巡又是一年别，寄语集仙呼索郎。','',''),('quantangshi-35191','以人葠遗段成式','周繇','quantangshi','','卷36','人形上品传方志，我得真英自紫团。
慙非叔子空持药，更请伯言审细看。','',''),('quantangshi-35192','和段成式 一','周繇','quantangshi','','卷36','回簪转黛喜猜防，粉署裁诗助酒狂。
若遇仙丹偕羽化，便随萧史亦何伤。','',''),('quantangshi-35193','和段成式 二','周繇','quantangshi','','卷36','玉树琼筵映彩霞，澄虚楼阁似仙家。
只缘存想归兰室，不向春风看夜花。','',''),('quantangshi-35194','杂兴','聶夷中','quantangshi','','卷36','两叶能蔽目，双豆能塞聪。
理身不知道，将为天地聋。
扰扰造化内，茫茫天地中。
苟或有所愿，毛髪亦不容。','',''),('quantangshi-35195','杂怨 一','聶夷中','quantangshi','','卷36','生在绮罗下，岂识渔阳道。
良人自戍来，夜夜梦中到。
渔阳万里远，近于中门限。
中门逾有时，渔阳常在眼。','',''),('quantangshi-35196','杂怨 二','聶夷中','quantangshi','','卷36','君泪濡罗巾，妾泪滴路尘。
罗巾今在手，日得随妾身。
路尘如因风，得上君车轮。','',''),('quantangshi-35197','行路难','聶夷中','quantangshi','','卷36','莫言行路难，夷狄如中国。
谓言骨肉亲，中门如异域。
出处全在人，路亦无通塞。
门前两条辙，何处去不得。','',''),('quantangshi-35198','大垂手','聶夷中','quantangshi','','卷36','金刀翦轻云，盘用黄金缕。
装束赵飞燕，教来掌上舞。
舞罢飞燕死，片片随风去。','',''),('quantangshi-35199','空城雀','聶夷中','quantangshi','','卷36','一雀入官仓，所食能损几。
所虑往复频，官仓乃害尔。
鱼网不在天，鸟网不在水。
饮啄要自然，何必空城里。','',''),('quantangshi-35200','胡无人行','聶夷中','quantangshi','','卷36','男儿徇大义，立节不沽名。
腰间悬陆离，大歌胡无行。
不读战国书，不览黄石经。
醉卧咸阳楼，梦入受降城。
更愿生羽翼，飞身入青冥。
请携天子劒，斫下旄头星。
自然胡无人，虽有无战争。
悠哉典属国，驱羊老一生。','',''),('quantangshi-35201','咏田家','聶夷中','quantangshi','','卷36','二月卖新丝，五月粜新谷。
医得眼前疮，剜却心头肉。
我愿君王心，化作光明烛。
不照绮罗筵，只照逃亡屋。','',''),('quantangshi-35202','燕台二首 一','聶夷中','quantangshi','','卷36','燕台累黄金，上欲招儒雅。
贵得贤士来，更下于隗者。
自然乐毅徒，趋风走天下。
何必驰凤书，旁求向林野。','',''),('quantangshi-35203','燕台二首 二','聶夷中','quantangshi','','卷36','燕台高百尺，燕灭台亦平。
一种是亡国，犹得礼贤名。
何似章华畔，空余禾黍生。','',''),('quantangshi-35204','古兴','聶夷中','quantangshi','','卷36','片玉一尘轻，粒粟山丘重。
唐虞贵民食，秪是勤播种。
前圣后圣同，今人古人共。
一岁如苦饥，金玉何所用。','',''),('quantangshi-35205','劝酒二首 一','聶夷中','quantangshi','','卷36','白日无定影，清江无定波。
人无百年寿，百年复如何。
堂上陈美酒，堂下列笙歌。
与君入醉乡，醉乡乐天和。
岁岁松栢茂，日日丘陵多。
君看终南山，万古青峨峨。','',''),('quantangshi-35206','劝酒二首 二','聶夷中','quantangshi','','卷36','灞上送行客，听唱行客歌。
适来桥下水，已作渭川波。
人间荣乐少，四海别离多。
但恐别离泪，自成苦水河。
劝尔一杯酒，所赠无余多。','',''),('quantangshi-35207','饮酒乐','聶夷中','quantangshi','','卷36','日月似有事，一夜行一周。
草木犹须老，人生得无愁。
一饮解百结，再饮破百忧。
白发欺贫贱，不入醉人头。
我愿东海水，尽向杯中流。
安得阮步兵，同入醉乡游。','',''),('quantangshi-35208','公子行二首 一','聶夷中','quantangshi','','卷36','汉代多豪族，恩深益骄逸。
走马踏杀人，街吏不敢诘。
红楼宴青春，数里望云蔚。
金缸焰胜画，不畏落晖疾。
美人尽如月，南威莫能匹。
芙蓉自天来，不向水中出。
飞琼奏云和，碧箫吹凤质。
唯恨鲁阳死，无人驻白日。','',''),('quantangshi-35209','公子行二首 二','聶夷中','quantangshi','','卷36','花树出墙头，花里谁家楼。
一行书不读，身封万户侯。
美人楼上歌，不是古凉州。','',''),('quantangshi-35210','短歌','聶夷中','quantangshi','','卷36','八月木阴薄，十叶三堕枝。
人生过五十，亦已同此时。
朝出东郭门，嘉树郁参差。
暮出西郭门，原草已离披。
南邻好台榭，北邻善歌吹。
荣华忽销歇，四顾令人悲。
生死与荣辱，四者乃常期。
古人耻其名，没世无人知。
无言鬓似霜，勿谓事如丝。
耆年无一善，何殊食乳儿。','',''),('quantangshi-35211','过比干墓','聶夷中','quantangshi','','卷36','殷辛帝天下，厌为天下尊。
干纲既一断，贤愚无二门。
佞是福身本，忠作丧己源。
饿虎不食子，人无骨肉恩。
日影不入地，下埋冤死魂。
腐骨不为土，应作石木根。
余来过此乡，下马吊此坟。
静念君臣间，有道谁敢论。','',''),('quantangshi-35212','住京寄同志','聶夷中','quantangshi','','卷36','在京如在道，日日先鸡起。
不离十二街，日行一百里。
役役大块上，周朝复秦市。
贵贱与贤愚，古今同一轨。
白兔落天西，赤鵶飞海底。
一日复一日，日日无终始。
自嫌性如石，不达荣辱理。
试问九十翁，吾今尚如此。','',''),('quantangshi-35213','赠农','聶夷中','quantangshi','','卷36','劝尔勤耕田，盈尔仓中粟。
劝尔无伐桑，减尔身上服。
清霜一委地，万草色不绿。
狂风一飘林，万叶不着木。
青春如不耕，何以自拘束。','',''),('quantangshi-35214','客有追叹后时者作诗勉之','聶夷中','quantangshi','','卷36','后达多晚荣，速得多疾倾。
君看构大厦，何曾一日成。
在暖须在桑，在饱须在耕。
君子贵弘道，道弘无不亨。
太阳垂好光，毛髪悉见形。
我亦二十年，直似戴盆行。
荆山产美玉，石石皆坚贞。
未必尽有玉，玉且间石生。
精卫一微物，犹恐填海平。','',''),('quantangshi-35215','访嵩阳道士不遇','聶夷中','quantangshi','','卷36','先生五岳游，文焰灭金鼎。
日下鹤过时，人间空落影。
常言一粒药，不随死生境。
何当列御寇，去问仙人请。','',''),('quantangshi-35216','早发邺北经古城','聶夷中','quantangshi','','卷36','微月东南明，双牛耕古城。
但耕古城地，不知古城名。
当昔置此城，岂料今日耕。
蔓草已离披，狐兔何纵横。
秋云零落散，秋风萧条生。
对古良可叹，念今转伤情。
古人已冥冥，今人又营营。
不知马蹄下，谁家旧台亭。','',''),('quantangshi-35217','题贾氏林泉','聶夷中','quantangshi','','卷36','市朝束名利，林泉系清通。
岂知黄尘内，迥有白云踪。
轻流逗密蓧，直干入宽空。
高吟五君咏，疑对九华峰。
我知种竹心，欲扇清凉风。
我知决泉意，将明济物功。
有琴不张弦，众星列梧桐。
须知澹泊听，声在无声中。
地非樵者路，武陵又何逢。
祗虑迷所归，池上日西东。','',''),('quantangshi-35218','送友人归江南','聶夷中','quantangshi','','卷36','皇州五更鼓，月落西南维。
此时有行客，别我孤舟归。
上国身无主，下第诚可悲。','',''),('quantangshi-35219','秋夕','聶夷中','quantangshi','','卷36','日往无复见，秋堂暮乃学。
玄髪不知白，晓入寒铜觉。
为才未离羣，有玉犹在璞。
谁把碧桐枝，刻作云门乐。','',''),('quantangshi-35220','哭刘驾博士','聶夷中','quantangshi','','卷36','出门四顾望，此日何徘徊。
终南旧山色，夫子安在哉。
君诗如门户，夕闭昼还开。
君名如四时，春尽夏复来。
原野多丘陵，累累如高台。
君坟须数尺，谁与夫子偕。','',''),('quantangshi-35221','公子家','聶夷中','quantangshi','','卷36','种花满西园，花发青楼道。
花下一禾生，去之为恶草。','',''),('quantangshi-35222','田家二首 一','聶夷中','quantangshi','','卷36','父耕原上田，子劚山下荒。
六月禾未秀，官家已修仓。','',''),('quantangshi-35223','田家二首 二','聶夷中','quantangshi','','卷36','锄田当日午，汗滴禾下土。
谁念盘中餐，粒粒皆辛苦。','',''),('quantangshi-35224','杂怨','聶夷中','quantangshi','','卷36','良人昨日去，明月又不圆。
别时各有泪，零落青楼前。','',''),('quantangshi-35225','乌夜啼','聶夷中','quantangshi','','卷36','众鸟各归枝，乌乌尔不栖。
还应知妾恨，故向绿窗啼。','',''),('quantangshi-35226','起夜来','聶夷中','quantangshi','','卷36','念远心如烧，不觉中夜起。
桃花带露泛，立在月明里。','',''),('quantangshi-35227','古别离','聶夷中','quantangshi','','卷36','欲别牵郎衣，问郎游何处。
不恨归日迟，莫向临邛去。','',''),('quantangshi-35228','长安道','聶夷中','quantangshi','','卷36','此地无驻马，夜中犹走轮。
所以路傍草，少于衣上尘。','',''),('quantangshi-35229','游子行','聶夷中','quantangshi','','卷36','萱草生堂阶，游子行天涯。
慈亲倚门望，不见萱草花。','',''),('quantangshi-35230','闻人说海北事有感','聶夷中','quantangshi','','卷36','故乡归路隔高雷，见说年来事可哀。
村落日中眠虎豹，田园雨后长蒿莱。
海隅久已无春色，地底真成有劫灰。
荆棘满山行不得，不知当日是谁栽。','',''),('quantangshi-35231','华清词','顧雲','quantangshi','','卷36','祥云皓鹤盘碧空，乔松稍稍韵微风。
绛节影来，朱幡响丁东。
相公清斋朝蘂宫，太上符箓龙蛇踪。
散花天女侍香童，隔烟遥望见云水。
弹璈吹凤清珑珑，丹砂黄金世可度。
愿启一言告仙翁，道门弟子山中客。
长向山中礼空碧，九色真龙上汉时，愿把霓幢引烟策。','',''),('quantangshi-35232','天威行','顧雲','quantangshi','','卷36','蛮岭高，蛮海阔，去舸回艘投此歇。
一夜舟人得梦间，草草相呼一时发。
飓风忽起云颠狂，波涛摆掣鱼龙僵。
海神怕急上岸走，山燕股栗入石藏。
金蛇飞状霍闪过，白日倒挂银绳长。
轰轰砢砢雷车转，霹雳一声天地战。
风定云开始望看，万里青山分两片。
车遥遥，马阗阗，平如砥，直如弦。
云南八国万部落，皆知此路来朝天。
耿恭拜出井底水，广利刺开山上泉。
若论终古济物意，二将之功皆小焉。','',''),('quantangshi-35233','筑城篇','顧雲','quantangshi','','卷36','三十六里西川地，围遶城郭峨天横。
一家人率一口甓，版筑才兴城已成。
役夫登登无倦色，馔饱觞酣方暂息。
不假神龟出指踪，尽凭心匠为筹画。
画阁团团真铁瓮，堵阔巉岩齐石壁。
风吹四面旌旗动，火焰相烧满天赤。
散花楼晚挂残虹，濯锦秋江澄倒碧。
西川父老贺子孙，从兹始是中华人。','',''),('quantangshi-35234','苏君厅观韩干马障歌','顧雲','quantangshi','','卷36','杜甫歌诗吟不足，可怜曹霸丹青曲。
直言弟子韩干马，画马无骨但有肉。
今日披图见笔迹，始知甫也真凡目。
秦王学士居武功，六印名家声价雄。
乃孙屈迹宁百里，好奇学古有祖风。
竹厅斜日弈碁散，延我直入书斋中。
屹然六幅古屏上，歘见胡人牵入天廐之神龙。
麟鬐凤臆真相似，秋竹惨惨披两耳。
轻匀杏蘂糁皮毛，细拈银丝插鬃尾。
思量动步应千里，谁见初离渥洼水。
眼前只欠燕雪飞，蹄下如闻朔风起。
朱崖谪掾从亡殁，更有何人鉴奇物。
当时若遇燕昭王，肯把千金买枯骨。','',''),('quantangshi-35235','苔歌','顧雲','quantangshi','','卷36','槛前溪夺秋空色，百丈潭心数砂砾。
松筠条条长碧苔，苔色碧于溪水碧。
波回梳开孔雀尾，根细贴着盘陀石。
拨浪轻拈出少时，一髻浓烟三四尺。
山光日华乱相射，静缕兰鬐匀襞积。
试把临流抖擞看，琉璃珠子泪双滴。
如看玉女洗头处，解破云鬟收未得。
即是仙宫欲制六铢衣，染丝未倩鲛人织。
采之不敢盈筐箧，苦怕龙神河伯惜。
琼苏玉盐烂漫煮，咽入丹田续灵液。
会待功成插翅飞，蓬莱顶上寻仙客。','',''),('quantangshi-35236','池阳醉歌赠匡庐处士姚岩杰','顧雲','quantangshi','','卷36','九华太守行春罢，高绛红筵压花榭。
四面繁英拂槛开，帖雪团霞坠枝亚。
空中焰若烧蓝天，万里滑静无纤烟。
弦索紧快管声脆，急曲碎拍声相连。
主人怜才多倾兴，许客酣歌露真性。
春酎香浓枝盏黏，一醉有时三日病。
鼋潭鳞粉解不去，鸦岭蘂花浇不醒。
肺枯似着炉鞲煽，脑热如遭锤凿钉。
蒙溪先生梁公孙，忽然示我十轴文。
展开一卷读一首，四顾特地无涯垠。
又开一轴读一帙，酒病豁若风驱云。
文锋斡破造化窟，心刃掘出兴亡根。
经疾史恙万片恨，墨炙笔针如有神。
呵叱潘陆鄙琐屑，提挈扬孟归孔门。
时时说及开元理，家风飒飒吹人耳。
吴[兢]纂出升平源，十事分明铺在纸。
裔孙才业今如此，谁人为奏明天子。
銮驾何当猎左冯，神鹰一掷望千里。
戏操狂翰涴蛮牋，傍人莫笑我率然。','',''),('quantangshi-35237','咏柳二首 一','顧雲','quantangshi','','卷36','带露含烟处处垂，绽黄摇绿嫩参差。
长堤未见风飘絮，广陌初怜日映丝。
斜傍画筵偷舞态，低临妆阁学愁眉。
离亭不放到春暮，折尽拂檐千万枝。','',''),('quantangshi-35238','咏柳二首 二','顧雲','quantangshi','','卷36','闲花野草总争新，眉皱丝干独不匀。
乞取东风残气力，莫教虚度一年春。','',''),('quantangshi-35239','宴边将','張喬','quantangshi','','卷36','一曲梁州金石清，边风萧飒动江城。
座中有老沙场客，横笛休吹塞上声。','',''),('quantangshi-35240','郢州即事','張喬','quantangshi','','卷36','孤城临远水，千里见寒山。
白雪无人唱，沧洲尽日闲。
鸟归残烧外，帆出断云间。
此地秋风起，应随计吏还。','',''),('quantangshi-35241','送宾贡金夷吾奉使归本国','張喬','quantangshi','','卷36','渡海登仙籍，还家备汉仪。
孤舟无岸泊，万里有星随。
积水浮魂梦，流年半别离。
东风未回日，音信杳难期。','',''),('quantangshi-35242','华山','張喬','quantangshi','','卷36','谁将倚天劒，削出倚天峰。
众水背流急，他山相向重。
树黏青霭合，崖夹白云浓。
一夜盆倾雨，前湫起毒龙。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35243','滕王阁','張喬','quantangshi','','卷36','昔人登览处，遗阁大江隅。
叠浪有时有，闲云无日无。
早凉先燕去，返照后帆孤。
未得营归计，菱歌满旧湖。','',''),('quantangshi-35244','寄处士梁烛','張喬','quantangshi','','卷36','贤哉君子风，讽与古人同。
采药楚云里，移家湘水东。
星霜秋野阔，雨雹夜山空。
早晚相招隐，深耕老此中。','',''),('quantangshi-35245','送许棠下第游蜀','張喬','quantangshi','','卷36','天下猿多处，西南是蜀关。
马登青壁瘦，人宿翠微闲。
带雨逢残日，因江见断山。
行歌风月好，莫老锦城间。','',''),('quantangshi-35246','题终南山白鹤观','張喬','quantangshi','','卷36','上彻炼丹峰，求玄意未穷。
古坛青草合，往事白云空。
仙境日月外，帝乡烟雾中。
人间足烦署，欲去恋松风。','',''),('quantangshi-35247','赠边将','張喬','quantangshi','','卷36','将军夸胆气，功在杀人多。
对酒擎钟饮，临风拔劒歌。
翻师平碎叶，掠地取交河。
应笑孔门客，年年羡四科。','',''),('quantangshi-35248','吊建州李员外','張喬','quantangshi','','卷36','铭旌归故里，猿鸟亦凄然。
已葬桐江月，空回建水船。
客传为郡日，僧说读书年。
恐有吟魂在，深山古木边。','',''),('quantangshi-35249','送许棠及第归宣州','張喬','quantangshi','','卷36','雅调一生吟，谁为晚达心。
傍人贺及第，独自却霑襟。
宴别喧天乐，家归碍日岑。
青门许攀送，故里接云林。','',''),('quantangshi-35250','送庞百篇之任青阳县尉','張喬','quantangshi','','卷36','都堂公试日，词翰独超羣。
品秩台庭与，篇章圣主闻。
乡连三楚树，县对九华云。
多少青门客，临岐共羡君。','',''),('quantangshi-35251','曲江春','張喬','quantangshi','','卷36','寻春与送春，多遶曲江滨。
一片凫鹥水，千秋辇毂尘。
岸凉随众木，波影逐游人。
自是游人老，年年管吹新。','',''),('quantangshi-35252','秦原春望','張喬','quantangshi','','卷36','无穷名利尘，轩盖逐年新。
北阕东堂路，千山万水人。
云离僧榻曙，燕远凤楼春。
荏苒文明代，难归钓艇身。','',''),('quantangshi-35253','游华山云际寺','張喬','quantangshi','','卷36','少华中峰寺，高秋众景归。
地连秦塞起，河隔晋山微。
晚木蝉相应，凉天雁并飞。
殷勤记岩石，秪恐再来稀。','',''),('quantangshi-35254','送碁待诏朴球归新罗','張喬','quantangshi','','卷36','海东谁敌手，归去道应孤。
阙下传新势，船中覆旧图。
穷荒回日月，积水载寰区。
故国多年别，桑田复在无。','',''),('quantangshi-35255','送郑谷先辈赴汝州辟命','張喬','quantangshi','','卷36','看花兴未休，已散曲江游。
载笔离秦甸，从军过洛州。
嵩云将雨去，汝水背城流。
应念依门客，蒿莱满径秋。','',''),('quantangshi-35256','赠敬亭清越上人','張喬','quantangshi','','卷36','海上独随缘，归来二十年。
久闲时得句，渐老不离禅。
砌木欹临水，窗峰直倚天。
犹期向云里，别扫石床眠。','',''),('quantangshi-35257','题灵山寺','張喬','quantangshi','','卷36','树凉清岛寺，虚阁敞禅扉。
四面闲云入，中流独鸟归。
湖平幽径近，船泊夜灯微。
一宿秋风里，烟波隔捣衣。','',''),('quantangshi-35258','吊栖白上人','張喬','quantangshi','','卷36','今古遰相送，几时无逝波。
篇章名不朽，寂灭理如何。
内殿留真影，闲房落贝多。
从兹高塔寺，惆怅懒经过。','',''),('quantangshi-35259','北山书事','張喬','quantangshi','','卷36','黄河一曲山，天半锁重关。
圣日雄藩静，秋风老将闲。
车舆穿谷口，市井响云间。
大野无飞鸟，元戎校猎还。','',''),('quantangshi-35260','长安书事','張喬','quantangshi','','卷36','出送乡人尽，沧洲未得还。
秋风五陵树，晴日六街山。
有景终年住，无机是处闲。
何当向云外，免老别离间。','',''),('quantangshi-35261','送郑侍御赴汴州辟命','張喬','quantangshi','','卷36','官从谏署清，暂去佐戎旌。
朝客多相恋，吟僧欲伴行。
河冰天际白，岳雪眼前明。
即见东风起，梁园听早莺。','',''),('quantangshi-35262','吊造微上人','張喬','quantangshi','','卷36','至人随化往，遗路自堪伤。
白塔收真骨，青山闭影堂。
钟残含细韵，烟灭有余香。
松上斋乌在，迟迟立夕阳。','',''),('quantangshi-35263','经隐岩旧居','張喬','quantangshi','','卷36','夜久村落静，徘徊杨柳津。
青山犹有路，明月已无人。
梦寐空前事，星霜倦此身。
尝期结茅处，来往蹑遗尘。','',''),('quantangshi-35264','再题敬亭清越上人山房','張喬','quantangshi','','卷36','重来访惠休，已是十年游。
向水千松老，空山一磬秋。
石窗清吹入，河汉夜光流。
久别多新作，长吟洗俗愁。','',''),('quantangshi-35265','浮汴东归','張喬','quantangshi','','卷36','日暖泗滨西，无穷岸草齐。
薄烟衰草树，微月迥城鸡。
水近沧浪急，山随绿野低。
羞将旧名姓，还向旧游题。','',''),('quantangshi-35266','雨中宿僧院','張喬','quantangshi','','卷36','千灯有宿因，长老许相亲。
夜永楼台雨，更深江海人。
劳生无了日，妄念起微尘。
不是真如理，何门静此身。','',''),('quantangshi-35267','江行至沙浦','張喬','quantangshi','','卷36','烟霞接杳冥，旅泊寄回汀。
夜雨雷电歇，春江蛟蜃腥。
城侵潮影白，峤截鸟行青。
徧欲探泉石，南须过洞庭。','',''),('quantangshi-35268','送友人归江南','張喬','quantangshi','','卷36','辛勤同失意，迢递独还家。
落日江边笛，残春岛上花。
亲安诚可喜，道在亦何嗟。
谁伴高吟处，晴天望九华。','',''),('quantangshi-35269','刘补阙自九华山拜官因以寄献','張喬','quantangshi','','卷36','冥鸿久不羣，征拜动天文。
地主迎过郡，山僧送出云。
登车残月在，宿馆乱流分。
若更思林下，还须共致君。','',''),('quantangshi-35270','岳阳即事','張喬','quantangshi','','卷36','远色岳阳楼，湘帆数片愁。
竹风山上路，沙月水中洲。
力学桑田废，思归鬓髪秋。
功名如不立，岂易狎汀鸥。','',''),('quantangshi-35271','题兴善寺僧道深院','張喬','quantangshi','','卷36','江峰峰顶人，受法老西秦。
法本无前业，禅非为后身。
院栽他国树，堂展祖师真。
甚愿依宗旨，求闲未有因。','',''),('quantangshi-35272','送龙门令刘沧','張喬','quantangshi','','卷36','去宰龙门县，应思变化年。
还将鲁儒政，又与晋人传。
峭壁开中古，长河落半天。
几乡因劝勉，耕稼满云烟。','',''),('quantangshi-35273','送友人往宜春','張喬','quantangshi','','卷36','落花兼柳絮，无处不纷纷。
远道空归去，流莺独自闻。
野桥喧硙水，山郭入楼云。
故里南陵曲，秋期更送君。','',''),('quantangshi-35274','书边事','張喬','quantangshi','','卷36','调角断清秋，征人倚戍楼。
春风对青冢，白日落梁州。
大汉无兵阻，穷边有客游。
蕃情似此水，长愿向南流。','',''),('quantangshi-35275','送僧雅觉归东海','張喬','quantangshi','','卷36','山川心地内，一念即千重。
老别关中寺，禅归海外峰。
鸟行来有路，帆影去无踪。
几夜波涛息，先闻本国钟。','',''),('quantangshi-35276','和薛监察题兴善寺古松','張喬','quantangshi','','卷36','种在法王城，前朝古寺名。
瘦根盘地远，香吹入云清。
鹤动池台影，僧禅雨雪声。
看来人旋老，因此叹浮生。','',''),('quantangshi-35277','听琴','張喬','quantangshi','','卷36','清月转瑶轸，弄中湘水寒。
能令坐来客，不语自相看。
静恐鬼神出，急疑风雨残。
几时归岭峤，更过洞庭弹。','',''),('quantangshi-35278','送友人游蜀','張喬','quantangshi','','卷36','此心知者稀，欲别倍相依。
无食拟同去，有家还未归。
巴山开国远，劒道入天微。
必恐临邛客，疑君学赋非。','',''),('quantangshi-35279','闻仰山禅师往曹溪因赠','張喬','quantangshi','','卷36','曹溪松下路，猨鸟重相亲。
四海求玄理，千峰遶定身。
异花天上堕，灵草雪中春。
自惜经行处，焚香礼旧真。','',''),('quantangshi-35280','蓝溪夜坐','張喬','quantangshi','','卷36','蓝水警尘梦，夜吟开草堂。
月临山霭薄，松滴露花香。
诗外真风远，人间静兴长。
明朝访禅侣，更上翠微房。','',''),('quantangshi-35281','题郑侍御蓝田别业','張喬','quantangshi','','卷36','秋山清若水，吟客静于僧。
小径通商岭，高窗见杜陵。
云霞朝入镜，猨鸟夜窥灯。
许作前峰侣，终来寄上层。','',''),('quantangshi-35282','送友人进士许棠','張喬','quantangshi','','卷36','离乡积岁年，归路远依然。
夜火山头市，春江树杪船。
干戈愁鬓改，瘴疠喜家全。
何处营甘旨，潮涛浸薄田。','',''),('quantangshi-35283','秘省伴直','張喬','quantangshi','','卷36','乔枝聚暝禽，叠阁锁遥岑。
待月当秋直，看书废夜吟。
残薪留火细，古井下瓶深。
纵欲抄前史，贫难遂此心。','',''),('quantangshi-35284','宿昭应','張喬','quantangshi','','卷36','夜忆开元寺，凄凉里巷间。
薄烟通魏阙，明月照骊山。
半壁空宫闭，连天白道闲。
清晨更回首，独向灞陵还。','',''),('quantangshi-35285','送陆处士','張喬','quantangshi','','卷36','樽前放浩歌，便起泛烟波。
舟楫故人少，江湖明月多。
孤峰经宿上，僻寺共云过。
若向仙岩住，还应着薜萝。','',''),('quantangshi-35286','送韩处士归少室山','張喬','quantangshi','','卷36','江外历千岑，还归少室吟。
地闲缑岭月，窗迥洛城砧。
石窦垂寒乳，松枝长别琴。
他年瀑泉下，亦拟置家林。','',''),('quantangshi-35287','赠初上人','張喬','quantangshi','','卷36','竹色覆禅栖，幽禽遶院啼。
空门无去住，行客自东西。
井气春来歇，庭枝雪后低。
相看念山水，尽日话曹溪。','',''),('quantangshi-35288','送新罗僧','張喬','quantangshi','','卷36','东来此学禅，多病念佛缘。
把锡离岩寺，收经上海船。
落帆敲石火，宿岛汲瓶泉。
永向扶桑老，知无再少年。','',''),('quantangshi-35289','题山僧院','張喬','quantangshi','','卷36','溪路曾来日，年多与旧同。
地寒松影里，僧老磬声中。
远水清风落，闲云别院通。
心源若无碍，何必更论空。','',''),('quantangshi-35290','书梅福殿壁二首 一','張喬','quantangshi','','卷36','梅真从羽化，万古是须臾。
此地名空在，西山云亦孤。
井痕平野水，坛级上春芜。
纵有双飞鹤，年多松已枯。','',''),('quantangshi-35291','书梅福殿壁二首 二','張喬','quantangshi','','卷36','一自白云去，千秋坛月明。
我来思往事，谁更得长生。
雅韵磬钟远，真风楼殿清。
今来为尉者，天下有仙名。','',''),('quantangshi-35292','荆楚道中','張喬','quantangshi','','卷36','前程曾未到，岐路拟何为。
返照行人急，荒郊去鸟迟。
春宵多旅梦，夏闰远秋期。
处处牵愁绪，无穷是柳丝。','',''),('quantangshi-35293','送南陵尉李频','張喬','quantangshi','','卷36','重作东南尉，生涯尚似僧。
客程淮馆月，乡思海船灯。
晚雾看春毂，晴天见朗陵。
不应三考足，先授诏书征。','',''),('quantangshi-35294','将归江淮书','張喬','quantangshi','','卷36','东风摇众木，即有看花期。
紫陌频来日，沧洲独去时。
郡因兵役苦，家为海翻移。
未老多如此，那堪鬓不衰。','',''),('quantangshi-35295','沿汉东归','張喬','quantangshi','','卷36','北去穷秦塞，南归遶汉川。
深山逢古迹，远道见新年。
绝壁云衔寺，空江雪洒船。
萦回还此景，多坐夜灯前。','',''),('quantangshi-35296','送蜀客','張喬','quantangshi','','卷36','劒阁缘空去，西南转几州。
丹霄行客语，明月杜鹃愁。
露带山花落，云随野水流。
相如曾醉地，莫滞少年游。','',''),('quantangshi-35297','塞上','張喬','quantangshi','','卷36','勒兵辽水边，风急卷旌旃。
绝塞寒无树，平沙势尽天。
雪晴回探骑，月落控鸣弦。
永定山河誓，南归改汉年。','',''),('quantangshi-35298','送友人归袁州','張喬','quantangshi','','卷36','袁江猨鸟清，曾向此中行。
才子登科去，诸侯扫榻迎。
山藏明月浦，树遶白云城。
远想安亲后，秋风梦不惊。','',''),('quantangshi-35299','赠别李山人','張喬','quantangshi','','卷36','分合老西秦，年年梦白苹。
曾为洞庭客，还送洞庭人。
语别惜残夜，思归愁见春。
遥知泊舟处，沙月自相亲。','',''),('quantangshi-35300','思宜春寄友人','張喬','quantangshi','','卷36','胜游虽隔年，魂梦亦依然。
瀑水喧秋思，孤灯动夜船。
断虹全岭雨，斜月半溪烟。
旧日吟诗侣，何人更不眠。','',''),('quantangshi-35301','江行夜雨','張喬','quantangshi','','卷36','江风木落天，游子感流年。
万里波连蜀，三更雨到船。
梦残灯影外，愁积苇业边。
不及樵渔客，全家住岛田。','',''),('quantangshi-35302','赠仰大师','張喬','quantangshi','','卷36','仰山因久住，天下仰山名。
井邑身虽到，林泉性本清。
野云居处尽，江月定中明。
仿髴曾相识，今来隔几生。','',''),('quantangshi-35303','江南逢洛下友人','張喬','quantangshi','','卷36','洛下吟诗侣，南游只有君。
波涛归路见，蟋蟀在船闻。
晓月江城出，晴霞岛树分。
无穷怀古意，岂独遶湘云。','',''),('quantangshi-35304','东湖赠僧子兰','張喬','quantangshi','','卷36','名利了无时，何人暂访师。
道情闲外见，心地语来知。
竹落穿窗叶，松寒荫井枝。
匡山许同社，愿卜挂帆期。','',''),('quantangshi-35305','隐岩陪郑少师夜坐','張喬','quantangshi','','卷36','幸喜陪驺驭，频来向此宵。
砚磨清涧石，厨爨白云樵。
竹外村烟细，灯中禁漏遥。
衣冠与文理，静语对前朝。','',''),('quantangshi-35306','送三传赴长城尉','張喬','quantangshi','','卷36','登科精鲁史，为尉及良时。
高论穷诸国，长才并几司。
地倾流水疾，山叠过云迟。
暇日琴书畔，何人对手棋。','',''),('quantangshi-35307','送李道士归南岳','張喬','quantangshi','','卷36','千峰隔湘水，迢遰挂帆归。
扫月眠苍壁，和云着褐衣。
洞虚悬溜滴，径狭长松围。
只恐相寻日，人间旧识稀。','',''),('quantangshi-35308','延福里秋怀','張喬','quantangshi','','卷36','终年九陌行，要路迹皆生。
苦学犹难至，甘贫岂有成。
病携秋卷重，闲着暑衣轻。
一别林泉久，中宵御水声。','',''),('quantangshi-35309','题玄哲禅师影堂','張喬','quantangshi','','卷36','吾师视化身，一念即遗尘。
岩谷藏虚塔，江湖散学人。
云迷禅处石，院掩写来真。
寂寞焚香后，闲阶细草生。','',''),('quantangshi-35310','登慈恩寺塔','張喬','quantangshi','','卷36','窗户几层风，清凉碧落中。
世人来往别，烟景古今同。
列岫横秦断，长河极塞空。
斜阳越乡思，天末见归鸿。','',''),('quantangshi-35311','送友人东归','張喬','quantangshi','','卷36','远涉期秋卷，将行不废吟。
故乡芳草路，来往别离心。
挂席春风尽，开斋夏景深。
子规谁共听，江月上清岑。','',''),('quantangshi-35312','送僧鸾归蜀宁亲','張喬','quantangshi','','卷36','歌诗精外学，天子是知音。
坐夏宫钟近，宁亲劒阁深。
高名彻西国，旧迹寄东林。
自此栖禅者，因师满蜀今。','',''),('quantangshi-35313','送人归江南','張喬','quantangshi','','卷36','贫归无定程，水宿与山行。
未有安亲计，难为去国情。
岛烟孤寺磬，江月远船筝。
思苦秋回日，多应吟更清。','',''),('quantangshi-35314','将离江上作','張喬','quantangshi','','卷36','白衣归树下，青草恋江边。
三楚足深隐，五陵多少年。
寂寥闻蜀魄，清绝怨湘弦。
岐路在何处，西行心渺然。','',''),('quantangshi-35315','别李参军','張喬','quantangshi','','卷36','王孙游不遇，况我五湖人。
野店难投宿，渔家独问津。
岭分中夜月，江隔两乡春。
静想青云路，还应寄此身。','',''),('quantangshi-35316','送睦州张参军','張喬','quantangshi','','卷36','重禄轻身日，清资近故乡。
因知送君后，转自惜年芳。
远水分林影，层峰起鸟行。
扁舟此中去，溪月有余光。','',''),('quantangshi-35317','赠棋僧侣','張喬','quantangshi','','卷36','机谋时未有，多向弈棋销。
已与山僧敌，无令海客饶。
静驱云阵起，疎点雁行遥。
夜雨如相忆，松窗更见招。','',''),('quantangshi-35318','题湖上友人居','張喬','quantangshi','','卷36','岂得恋樵渔，全家湖畔居。
远无潮客信，闲寄岳僧书。
野白梅繁后，山明雨散初。
逍遥向云水，莫与宦情疎。','',''),('quantangshi-35319','送友人归宣州','張喬','quantangshi','','卷36','失计复离愁，君归我独游。
乱花藏道发，春水遶乡流。
暝火丛桥市，晴山叠郡楼。
无为谢公恋，吟过晓蝉秋。','',''),('quantangshi-35320','题古观','張喬','quantangshi','','卷36','急景遰衰老，此经谁养真。
松留千载鹤，碑隔六朝人。
洞水流花早，壶天闭雪春。
其如为名利，归踏五陵尘。','',''),('quantangshi-35321','送友人及第归江南','張喬','quantangshi','','卷36','岂易及归荣，辛勤致此名。
登车思往事，回首勉诸生。
路遶山光晓，帆通海气清。
秋期却闲坐，林下听江声。','',''),('quantangshi-35322','送朴充侍御归海东','張喬','quantangshi','','卷36','天涯离二纪，阙下历三朝。
涨海虽然阔，归帆不觉遥。
惊波时失侣，举火夜相招。
来往寻遗事，秦皇有断桥。','',''),('quantangshi-35323','吊前水部贾员外','張喬','quantangshi','','卷36','笼中江海禽，日夕有归心。
魏阙长谣久，吴山独往深。
别时羣木落，终处乱猨吟。
李白坟前路，溪僧送入林。','',''),('quantangshi-35324','题小松','張喬','quantangshi','','卷36','松子落何年，纤枝长水边。
斸开深涧雪，移出远林烟。
带月栖幽鸟，兼花灌冷泉。
微风动清韵，闲听罢琴眠。','',''),('quantangshi-35325','寄中岳颛顼先生','張喬','quantangshi','','卷36','先生颛顼后，得道自何人。
松柏卑于寿，儿孙老却身。
夜窗峰顶曙，寒涧洞中春。
恋此逍遥境，云间不可亲。','',''),('quantangshi-35326','送沈先辈尉昭应','張喬','quantangshi','','卷36','余才不废诗，佐邑喜闲司。
丹陛终须去，青山未可期。
叶凋温谷晚，云出古宫迟。
若草东封疏，君王到有时。','',''),('quantangshi-35327','送友人游湖南','張喬','quantangshi','','卷36','所投非旧知，亦似有前期。
路向长江上，帆扬细雨时。
春生南岳早，日转大荒迟。
尽采潇湘句，重来会近期。','',''),('quantangshi-35328','江上送友人南游','張喬','quantangshi','','卷36','何处积乡愁，天涯聚乱流。
岸长羣岫晚，湖阔片帆秋。
买酒过渔舍，分灯与钓舟。
潇湘见来雁，应念独边游。','',''),('quantangshi-35329','江南别友人','張喬','quantangshi','','卷36','劳生故白头，头白未应休。
阙下难孤立，天涯尚旅游。
听猨吟岛寺，待月上江楼。
醉别醒惆怅，云帆满乱流。','',''),('quantangshi-35330','商山道中','張喬','quantangshi','','卷36','春去计秋期，长安在梦思。
多逢山好处，少值客行时。
云起争峰势，花交隐涧枝。
停骖一惆怅，应秪岭猨知。','',''),('quantangshi-35331','吴江旅次','張喬','quantangshi','','卷36','行人愁落日，去鸟倦遥林。
旷野鸣流水，空山响暮砧。
旅途归计晚，乡树别年深。
寂寞逢村酒，渔家一醉吟。','',''),('quantangshi-35332','寄南中友人','張喬','quantangshi','','卷36','相梦如相见，相思去后频。
旧时行处断，华髪别来新。
浪动三湘月，烟藏五岭春。
又无归北客，书札寄何人。','',''),('quantangshi-35333','寄绩溪陈明府','張喬','quantangshi','','卷36','古邑猨声里，空城只半存。
岸移无旧路，沙涨别成村。
鼓角喧京口，江山尽汝濆。
六朝兴废地，行子一销魂。','',''),('quantangshi-35334','试月中桂','張喬','quantangshi','','卷36','与月转洪蒙，扶疎万古同。
根非生下土，叶不坠秋风。
每以圆时足，还随缺处空。
影高羣木外，香满一轮中。
未种丹霄日，应虚玉兔宫。
何当因羽化，细得问玄功。','',''),('quantangshi-35335','游歙州兴唐寺','張喬','quantangshi','','卷36','山桥通绝境，到此忆天台。
竹里寻幽径，云边上古台。
鸟归残照出，钟断细泉来。
为爱澄溪月，因成隔宿回。','',''),('quantangshi-35336','题诠律师院','張喬','quantangshi','','卷36','院凉松雨声，相对有山情。
未许溪边老，犹思岳顶行。
纱灯留火细，石井灌瓶清。
欲问吾师外，何人得此生。','',''),('quantangshi-35337','金山寺空上人院','張喬','quantangshi','','卷36','已老金山顶，无心上石桥。
讲移三楚遍，梵译五天遥。
板阁禅秋月，铜瓶汲夜潮。
自慙昏醉客，来坐亦通宵。','',''),('quantangshi-35338','题广信寺','張喬','quantangshi','','卷36','亭北敞灵溪，林梢与槛齐。
野云来影远，沙鸟去行低。
晚渡明村火，晴山响郡鼙。
思乡值摇落，赖不有猨啼。','',''),('quantangshi-35339','兴善寺贝多树','張喬','quantangshi','','卷36','还应毫末长，始见拂丹霄。
得子从西国，成阴见昔朝。
势随双刹直，寒出四墙遥。
带月啼春鸟，连空噪暝蜩。
远根穿古井，高顶起凉飙。
影动悬灯夜，声繁过雨朝。
静迟松桂老，坚任雪霜凋。
永共终南在，应随劫火烧。','',''),('quantangshi-35340','华山','張喬','quantangshi','','卷36','青苍河一隅，气状杳难图。
卓杰三峰出，高奇四岳无。
力疑擎上界，势独压中区。
众水东西走，羣山远近趋。
天回诸宿照，地耸百灵扶。
石壁烟霞丽，龙潭雨雹麤。
澄凝临甸服，险固束神都。
浅觉川原异，深应日月殊。
鹤归青霭合，仙去白云孤。
瀑漏斜飞冻，松长倒挂枯。
每来寻洞穴，不拟返江湖。
傥有芝田种，岩间老一夫。','',''),('quantangshi-35341','送何道士归山','張喬','quantangshi','','卷36','身非绝粒本清羸，束挂仙经杖一枝。
落叶独寻流水去，深山长与白云期。
树临丹竈寒花疾，坛近清岚夜月迟。
樵客若能随洞里，回归人世始应悲。','',''),('quantangshi-35342','城东寓居寄知己','張喬','quantangshi','','卷36','花木闲门苔藓生，浐川特去得吟情。
病来久绝洞庭信，年长却思庐岳耕。
落日独归林下宿，暮云多遶水边行。
干时退出长如此，频愧相忧道姓名。','',''),('quantangshi-35343','再书边事','張喬','quantangshi','','卷36','万里沙西寇已平，犬羊羣外筑空城。
分营夜火烧云远，校猎秋雕掠草轻。
秦将力随胡马竭，蕃河流入汉家清。
羌戎不识干戈老，须贺当时圣主明。','',''),('quantangshi-35344','游边感怀二首 一','張喬','quantangshi','','卷36','贫游缭绕困边沙，却被辽阳战士嗟。
不是无家归不得，有家归去似无家。','',''),('quantangshi-35345','游边感怀二首 二','張喬','quantangshi','','卷36','兄弟江南身塞北，雁飞犹自半年余。
夜来因得思乡梦，重读前秋转海书。','',''),('quantangshi-35346','无题','張喬','quantangshi','','卷36','九霄无诏下，何事触清尘。
宅带松萝僻，身惟猨鸟亲。
吟看仙掌月，期有洞庭人。
莫问烟霞句，悬知见岳神。','',''),('quantangshi-35347','蝉','張喬','quantangshi','','卷36','先秋蝉一悲，长是客行时。
曾感去年者，又鸣何处枝。
细听残韵在，回望旧声迟。
断续谁家树，凉风送别离。','',''),('quantangshi-35348','江上逢进士许棠','張喬','quantangshi','','卷36','诗人推上第，新榜又无君。
鹤髪他乡老，渔歌故国闻。
平江流晓月，独鸟伴余云。
且了髫年志，沙鸥未可羣。','',''),('quantangshi-35349','送河西从事','張喬','quantangshi','','卷36','结束佐戎旃，河西住几年。
陇头随日去，碛里寄星眠。
水近沙连帐，程遥马入天。
圣朝思上策，重待奏安边。','',''),('quantangshi-35350','河湟旧卒','張喬','quantangshi','','卷36','少年随将讨河湟，头白时清返故乡。
十万汉军零落尽，独吹边曲向残阳。','',''),('quantangshi-35351','促织','張喬','quantangshi','','卷36','念尔无机自有情，迎寒辛苦弄梭声。
椒房金屋何曾识，偏向贫家壁下鸣。','',''),('quantangshi-35352','猨','張喬','quantangshi','','卷36','挂月栖云向楚林，取来全是为清音。
谁知系在黄金索，翻畏侯家不敢吟。','',''),('quantangshi-35353','寄荐福寺栖白大师','張喬','quantangshi','','卷36','高塔六街无不见，塔边名出秪吾师。
尝闻朝客多相□，记得□□数句诗。','',''),('quantangshi-35354','越中赠别','張喬','quantangshi','','卷36','东越相逢几醉眠，满楼明月镜湖边。
别离吟断西陵渡，杨柳秋风两岸蝉。','',''),('quantangshi-35355','寄清越上人','張喬','quantangshi','','卷36','大道本来无所染，白云那得有心期。
远公独刻莲花漏，犹向空山礼六时。','',''),('quantangshi-35356','宿齐山僧舍','張喬','quantangshi','','卷36','一宿经窗卧白波，万重归梦隔烟萝。
若言不得南宗要，长在禅牀事更多。','',''),('quantangshi-35357','宿齐山僧舍','張喬','quantangshi','','卷36','一宿经窗望白波，晓随山月出烟萝。
若言不得南宗要，长在禅牀事更多。','',''),('quantangshi-35358','春日游曲江','張喬','quantangshi','','卷36','日暖鸳鸯拍浪春，蒹葭浦际聚青苹。
若论来往乡心切，须是烟波岛上人。','',''),('quantangshi-35359','渔家','張喬','quantangshi','','卷36','拥棹思悠悠，更深泛积流。
唯将一星火，何处宿芦洲。','',''),('quantangshi-35360','送人及第归海东','張喬','quantangshi','','卷36','东风日边起，草木一时春。
自笑中华路，年年送远人。','',''),('quantangshi-35361','题河中鹳雀楼','張喬','quantangshi','','卷36','高楼怀古动悲歌，鹳雀今无野燕过。
树隔五陵秋色早，水连三晋夕阳多。
渔人遗火成寒烧，牧笛吹风起夜波。
十载重来值摇落，天涯归计欲如何。','',''),('quantangshi-35362','宿洛都门','張喬','quantangshi','','卷36','山川马上度边禽，一宿都门永夜吟。
客路不归秋又晚，西风吹动洛阳砧。','',''),('quantangshi-35363','对月二首 一','張喬','quantangshi','','卷36','圆魄上寒空，皆言四海同。
安知千里外，不有雨兼风。','',''),('quantangshi-35364','对月二首 二','張喬','quantangshi','','卷36','盈缺青冥外，东风万古吹。
何人种丹桂，不长出轮枝。','',''),('quantangshi-35365','赠友人','張喬','quantangshi','','卷36','自说安贫归未得，竹边门掩小池冰。
典琴赊酒吟过寺，送客思乡上灞陵。
待月夜留烟岛客，忆云闲访翠微僧。
几时献了相如赋，共向嵩山采茯苓。','',''),('quantangshi-35366','笛','張喬','quantangshi','','卷36','剪雨裁烟一节秋，落梅杨柳曲中愁。
尊前暂借殷勤看，明日曾闻向陇头。','',''),('quantangshi-35367','渔者','張喬','quantangshi','','卷36','首戴圆荷髪不梳，叶舟为宅水为居。
沙头聚看人如市，钓得澄江一丈鱼。','',''),('quantangshi-35368','宿潺湲亭','張喬','quantangshi','','卷36','走月流烟叠树西，听来愁甚听猨啼。
几时御水声边住，却梦潺湲宿此溪。','',''),('quantangshi-35369','台城','張喬','quantangshi','','卷36','宫殿余基长草花，景阳宫树噪村鸦。
云屯雉堞依然在，空绕渔樵四五家。','',''),('quantangshi-35370','寄山僧','張喬','quantangshi','','卷36','闲倚蒲团向日眠，不能归老岳云边。
旧时僧侣无人在，惟有长松见少年。','',''),('quantangshi-35371','题上元许棠所任王昌龄厅','張喬','quantangshi','','卷36','瑠璃堂里当时客，久绝吟声继后尘。
百四十年庭树老，如今重得见诗人。','',''),('quantangshi-35372','自诮','張喬','quantangshi','','卷36','每到花时恨道穷，一生光景半成空。
只应抱璞非良玉，岂得年年不至公。','',''),('quantangshi-35373','赠河南诗友','張喬','quantangshi','','卷36','山东令族玉无尘，裁剪烟花笔下春。
不把瑶华借风月，洛阳才子更何人。','',''),('quantangshi-35374','寄维扬故人','張喬','quantangshi','','卷36','离别河边绾柳条，千山万水玉人遥。
月明记得相寻处，城锁东风十五桥。','',''),('quantangshi-35375','孤云','張喬','quantangshi','','卷36','舒卷因风何所之，碧天孤影势迟迟。
莫言长是无心物，还有随龙作雨时。','',''),('quantangshi-35376','咏棋子赠弈僧','張喬','quantangshi','','卷36','黑白谁能用入玄，千回生死体方圆。
空门说得恒沙劫，应笑终年为一先。','',''),('quantangshi-35377','谷口作','張喬','quantangshi','','卷36','巴客青冥过岭尘，雪崖交映一川春。
晴朝采药寻源去，必恐云深见异人。','',''),('quantangshi-35378','寄弟','張喬','quantangshi','','卷36','故里行人战后疎，青崖萍寄白云居。
那堪又是伤春日，把得长安落第书。','',''),('quantangshi-35379','春日有怀','張喬','quantangshi','','卷36','高下寻花春景迟，汾阳台榭白云诗。
看山怀古翻惆怅，未胜遥传不到时。','',''),('quantangshi-35380','鹭鸶障子','張喬','quantangshi','','卷36','剪得机中如雪素，画为江上带丝禽。
闲来相对茅堂下，引出烟波万里心。','',''),('quantangshi-35381','甘露寺僧房','張喬','quantangshi','','卷36','临水登山路，重寻旅思劳。
竹阴行处密，僧腊别来高。
远岫明寒火，危楼响夜涛。
悲秋不成寐，明月上千舠。','',''),('quantangshi-35382','宿江叟岛居','張喬','quantangshi','','卷36','一家烟岛隈，竹里夜窗开。
数派分潮去，千樯聚月来。
石楼云断续，涧渚雁徘徊。
了得平生志，还归筑钓台。','',''),('quantangshi-35383','江村','張喬','quantangshi','','卷36','贫游无定踪，乡信转难逢。
寒渚暮烟阔，去帆归思重。
潮平低戍火，木落远山钟。
况是渔家宿，疎篱响夜舂。','',''),('quantangshi-35384','赠进士顾云','張喬','quantangshi','','卷36','潮槛烟波别钓津，西京同□荻□贫。
不知守道归何日，相对无言尽几春。
晴景远山花外暮，云边高盖水边□。
与君愁寂无消处，赊酒青门送楚人。','',''),('quantangshi-35385','赠头陀僧','張喬','quantangshi','','卷36','自说年深别石桥，遍游灵迹熟南朝。
已知世路皆虚幻，不觉空门是寂寥。
沧海附船浮浪久，碧山寻塔上云遥。
如今竹院藏衰老，一点寒灯弟子烧。','',''),('quantangshi-35386','寻阳村舍','張喬','quantangshi','','卷36','荒林寄远居，坐卧见樵渔。
夜火随船远，寒更出郡疎。
雪迷登岳路，风阻转江书。
寂寞高窗下，思乡岁欲除。','',''),('quantangshi-35387','江楼作','張喬','quantangshi','','卷36','凭槛见天涯，非秋亦可悲。
晚天帆去疾，春雪燕来迟。
山水分乡县，干戈足别离。
南人废耕织，早晚罢王师。','',''),('quantangshi-35388','回鸾阁写望','張喬','quantangshi','','卷36','古阁上空半，寥寥千里心。
多年为客路，尽日倚栏吟。
山压秦川重，河来虏塞深。
回銮今不见，烟雾杳沉沉。','',''),('quantangshi-35389','题宣州开元寺','張喬','quantangshi','','卷36','谁家烟径长莓苔，金碧虚栏竹上开。
流水远分山色断，清猨时带角声来。
六朝明月唯诗在，三楚空山有雁回。
达理始应尽惆怅，僧闲应得话天台。','',''),('quantangshi-35390','题友人草堂','張喬','quantangshi','','卷36','空山卜隐初，生计亦无余。
三亩水边竹，一床琴畔书。
深林收晚果，绝顶拾秋蔬。
坚话长如此，何年献子虚。','',''),('quantangshi-35391','七松亭','張喬','quantangshi','','卷36','七松亭上望秦川，高鸟闲云满目前。
已比子真耕谷口，岂同陶令卧江边。
临崖把卷惊回烧，扫石留僧听远泉。
明月影中宫漏近，佩声应宿使朝天。','',''),('quantangshi-35392','题友人林斋','張喬','quantangshi','','卷36','乔木带凉蝉，来吟暑雨天。
不离高枕上，似宿远山边。
簟冷窗中月，茶香竹里泉。
吾庐近溪岛，忆别动经年。','',''),('quantangshi-35393','经宣城元员外山居','張喬','quantangshi','','卷36','无人袭仙隐，石室闭空山。
避烧猨犹到，随云鹤不还。
涧荒岩影在，桥断树阴闲。
但有黄河赋，长留在世间。','',''),('quantangshi-35394','经九华山费征君故居','張喬','quantangshi','','卷36','草堂芜没后，来往问樵翁。
断石荒林外，孤坟晚照中。
数溪分大野，九子立寒空。
烟壁曾行处，青云路不通。','',''),('quantangshi-35395','题贾岛吟诗台','張喬','quantangshi','','卷36','吟魂不复游，台亦似荒丘。
一径草中出，长江天外流。
暝烟寒鸟集，残月夜虫愁。
愿得生禾黍，锄平恨即休。','',''),('quantangshi-35396','游南岳','張喬','quantangshi','','卷36','入岩仙境清，行尽复重行。
若得闲无事，长来寄此生。
涧松闲易老，笼烛晚生明。
一宿泉声里，思乡梦不成。','',''),('quantangshi-35397','寻桃源','張喬','quantangshi','','卷36','武林春草齐，花影隔澄溪。
路远无人去，山空有鸟啼。
水垂青霭断，松偃绿萝低。
世上迷途客，经兹尽不迷。','',''),('quantangshi-35398','青鸟泉','張喬','quantangshi','','卷36','祗此沉仙翼，瑶池似不遥。
有声悬翠壁，无势下丹霄。
净濑烟霞古，寒原草木凋。
山河几更变，幽咽到唐朝。','',''),('quantangshi-35399','望巫山','張喬','quantangshi','','卷36','溪叠云深转谷迟，暝投孤店草虫悲。
愁连远水波涛夜，梦断空山雨雹时。
边海故园荒后买，入关玄髪夜来衰。
东归未必胜羁旅，况是东归未有期。','',''),('quantangshi-35400','省中偶作','張喬','quantangshi','','卷36','二转郎曹自勉旃，莎阶吟步想前贤。
不如何逊无佳句，若比冯唐是壮年。
捧制名题黄纸尾，约僧心在白云边。
乳毛松雪春来好，直夜清闲且学禅。','',''),('quantangshi-35401','秋夕','張喬','quantangshi','','卷36','春恨复秋悲，秋悲难到时。
每逢明月夜，长起故山思。
巷僻行吟远，蛩多独卧迟。
溪僧与樵客，动别十年期。','',''),('quantangshi-35402','山中冬夜','張喬','quantangshi','','卷36','寒叶风摇尽，空林鸟宿稀。
涧冰妨鹿饮，山雪阻僧归。
夜坐尘心定，长吟语力微。','',''),('quantangshi-35403','宿刘温书斋','張喬','quantangshi','','卷36','不掩盈窗月，天然格调高。
凉风移蟋蟀，落叶在离骚。
回笔挑灯烬，悬图见海涛。
因论三国志，空载几英豪。','',''),('quantangshi-35404','归旧山','張喬','quantangshi','','卷36','昔年山下结茅茨，村落重来野径移。
樵客相逢悲往事，林僧闲坐问归期。
异藤遍树无空处，幽草缘溪少歇时。
此景一抛吟欲老，可能文字圣朝知。','',''),('quantangshi-35405','潭上作','張喬','quantangshi','','卷36','竹岛残阳映翠微，雪翎禽过碧潭飞。
人间未有关身事，每到渔家不欲归。','',''),('quantangshi-35406','杨花落','張喬','quantangshi','','卷36','北斗南回春物老，红英落尽绿尚早。
韶风澹荡无所依，偏惜垂杨作春好。
此时可怜杨柳花，萦盈艳曳满人家。
人家女儿出罗幕，净扫玉除看花落。
宝环纤手捧更飞，翠羽轻裙承不着。
历历瑶琴舞袖陈，飞红拂黛怜玉人。
东园桃李芳已歇，犹有杨花娇暮春。','',''),('quantangshi-35407','九华楼晴望','張喬','quantangshi','','卷36','一夜江潭风雨后，九华晴望倚天秋。
重来此地知何日，欲别殷勤更上楼。','',''),('quantangshi-35408','终南山','張喬','quantangshi','','卷36','带雪复衔春，横天占半秦。
势奇看不定，景变写难真。
洞远皆通岳，川多更有神。
白云幽绝处，自古属樵人。','',''),('quantangshi-35409','哭陈陶','張喬','quantangshi','','卷36','先生抱衰疾，不起茂陵间。
夕临诸孤少，荒居吊客还。
遗文禅东岳，留语葬乡山。
多雨铭旌故，残灯素帐闲。
乐章谁与集，陇树即堪攀。
神理今难问，予将呌帝关。','',''),('quantangshi-35410','长门怨','張喬','quantangshi','','卷36','御泉长绕凤皇楼，自是恩波别处流。
闲揲舞衣归未得，夜来砧杵六宫秋。','',''),('quantangshi-35411','升平词五首 一','曹唐','quantangshi','','卷36','瑞气遶宫楼，皇居上苑游。
远冈连圣祚，平地载神州。
会合兼重译，潺湲近八流。
中兴岂假问，据此自千秋。','',''),('quantangshi-35412','升平词五首 二','曹唐','quantangshi','','卷36','寥泬敞延英，朝班立位横。
宣传无草动，拜舞有衣声。
鸳瓦霜消湿，虫丝日照明。
辛勤自不到，遥见似前程。','',''),('quantangshi-35413','升平词五首 三','曹唐','quantangshi','','卷36','处处是欢心，时康岁已深。
不同三尺劒，应似五弦琴。
寿笑山犹尽，明嫌日有阴。
何当怜一物，亦遗断愁吟。','',''),('quantangshi-35414','升平词五首 四','曹唐','quantangshi','','卷36','日日听歌谣，区中尽祝尧。
虫蝗初不害，夷狄近全销。
史笔唯书瑞，天台绝见妖。
因令匹夫志，转欲事清朝。','',''),('quantangshi-35415','升平词五首 五','曹唐','quantangshi','','卷36','五帝三皇主，萧曹魏邴臣。
文章唯返朴，戈甲尽生尘。
谏纸应无用，朝纲自有伦。
升平不可记，所见是闲人。','',''),('quantangshi-35416','洛东兰若归','曹唐','quantangshi','','卷36','一衲老禅床，吾生半异乡。
管弦愁里老，书劒梦中忙。
鸟急山初暝，蝉稀树正凉。
又归何处去，尘路月苍苍。','',''),('quantangshi-35417','仙都即景','曹唐','quantangshi','','卷36','黄帝登真处，青青不记年。
孤峰应碍日，一柱自擎天。
石怪长栖鹤，云闲若有仙。
鼎湖看不见，零落数枝莲。','',''),('quantangshi-35418','汉武帝将候西王母下降','曹唐','quantangshi','','卷36','昆仑凝想最高峰，王母来乘五色龙。
歌听紫鸾犹缥缈，语来青鸟许从容。
风回水落三清月，漏苦霜传五夜钟。
树影悠悠花悄悄，若闻箫管是行踪。','',''),('quantangshi-35419','汉武帝于宫中宴西王母','曹唐','quantangshi','','卷36','鳌岫云低太一坛，武皇斋洁不胜懽。
长生碧字期亲署，延寿丹泉许细看。
劒佩有声宫树静，星河无影禁花寒。
秋风褭褭月朗朗，玉女清歌一夜阑。','',''),('quantangshi-35420','刘晨阮肇游天台','曹唐','quantangshi','','卷36','树入天台石路新，云和草静迥无尘。
烟霞不省生前事，水木空疑梦后身。
往往鸡鸣岩下月，时时犬吠洞中春。
不知此地归何处，须就桃源问主人。','',''),('quantangshi-35421','刘阮洞中遇仙子','曹唐','quantangshi','','卷36','天和树色霭苍苍，霞重岚深路渺茫。
云实满山无鸟雀，水声沿涧有笙簧。
碧沙洞里干坤别，红树枝前日月长。
愿得花间有人出，免令仙犬吠刘郎。','',''),('quantangshi-35422','仙子送刘阮出洞','曹唐','quantangshi','','卷36','殷勤相送出天台，仙境那能却再来。
云液每归须强饮，玉书无事莫频开。
花当洞口应长在，水到人间定不回。
惆怅溪头从此别，碧山明月闭苍苔。','',''),('quantangshi-35423','仙子洞中有怀刘阮','曹唐','quantangshi','','卷36','不将清瑟理霓裳，尘梦那知鹤梦长。
洞里有天春寂寂，人间无路月茫茫。
玉沙瑶草连溪碧，流水桃花满涧香。
晓露风灯零落尽，此生无处访刘郎。','',''),('quantangshi-35424','刘阮再到天台不复见仙子','曹唐','quantangshi','','卷36','再到天台访玉真，青苔白石已成尘。
笙歌冥寞闲深洞，云鹤萧条绝旧隣。
草树总非前度色，烟霞不似昔年春。
桃花流水依然在，不见当时劝酒人。','',''),('quantangshi-35425','织女怀牵牛','曹唐','quantangshi','','卷36','北斗佳人双泪流，眼穿肠断为牵牛。
封题锦字凝新恨，抛掷金梭织旧愁。
桂树三春烟漠漠，银河一水夜悠悠。
欲将心向仙郎说，借问榆花早晚秋。','',''),('quantangshi-35426','王远宴麻姑蔡经宅','曹唐','quantangshi','','卷36','好风吹树杏花香，花下真人道姓王。
大篆龙蛇随笔札，小天星斗满衣裳。
闲抛南极归期晚，笑指东溟饮兴长。
要唤麻姑同一醉，使人沽酒向余杭。','',''),('quantangshi-35427','萼绿华将归九疑留别许真人','曹唐','quantangshi','','卷36','九点秋烟黛色空，绿华归思颇无穷。
每悲驭鹤身难任，长恨临霞语未终。
河影暗吹云梦月，花声闲落洞庭风。
蓝丝重勒金条脱，留与人间许侍中。','',''),('quantangshi-35428','穆王宴王母于九光流霞馆','曹唐','quantangshi','','卷36','桑叶扶疎闭日华，穆王邀命宴流霞。
霓旌着地云初驻，金奏掀天月欲斜。
歌咽细风吹粉蕊，饮余清露湿瑶砂。
不知白马红缰解，偷吃东田碧玉花。','',''),('quantangshi-35429','紫河张休真','曹唐','quantangshi','','卷36','琪树扶疎压瑞烟，玉皇朝客满花前。
山川到处成三月，丝竹经时即万年。
树石冥茫初缩地，杯盘狼籍未朝天。
东风小饮人皆醉，从听黄龙枕水眠。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35430','张硕重寄杜兰香','曹唐','quantangshi','','卷36','碧落香销兰露秋，星河无梦夜悠悠。
灵妃不降三清驾，仙鹤空成万古愁。
浩月隔花追欵别，瑞烟笼树省淹留。
人间何事堪惆怅，海色西风十二楼。','',''),('quantangshi-35431','玉女杜兰香下嫁于张硕','曹唐','quantangshi','','卷36','天上人间两渺茫，不知谁识杜兰香。
来经玉树三山远，去隔银河一水长。
怨入清尘愁锦瑟，酒倾玄露醉瑶觞。
遗情更说何珍重，擘破云鬟金凤皇。','',''),('quantangshi-35432','萧史携弄玉上升','曹唐','quantangshi','','卷36','岂是丹台归路遥，紫鸾烟驾不同飘。
一声洛水传幽咽，万片宫花共寂寥。
红粉美人愁未散，清华公子笑相邀。
缑山碧树青楼月，肠断春风为玉箫。','',''),('quantangshi-35433','皇初平将入金华山','曹唐','quantangshi','','卷36','莫道真游烟景赊，潇湘有路入京华。
溪头鹤树春常在，洞口人家日易斜。
一水暗鸣闲遶涧，五云长往不还家。
白羊成队难收拾，吃尽溪边巨胜花。','',''),('quantangshi-35434','汉武帝思李夫人','曹唐','quantangshi','','卷36','惆怅冰颜不复归，晚秋黄叶满天飞。
迎风细荇传香粉，隔水残霞见画衣。
白玉帐寒鸳梦绝，紫阳宫远雁书稀。
夜深池上兰桡歇，断续歌声彻太微。','',''),('quantangshi-35435','送羽人王锡归罗浮','曹唐','quantangshi','','卷36','风前整顿紫荷巾，常向罗浮保养神。
石磴倚天行带月，铁桥通海入无尘。
龙蛇出洞闲邀雨，犀象眠花不避人。
最爱葛洪寻药处，露苗烟蕊满山春。','',''),('quantangshi-35436','送刘尊师祗诏阙庭三首 一','曹唐','quantangshi','','卷36','海风叶叶驾霓旌，天路悠悠接上清。
锦诰凄凉遗去恨，玉箫哀绝醉离情。
五湖夜月幡幢湿，双阙清风劒佩轻。
从此暂辞华表柱，便应千载是归程。','',''),('quantangshi-35437','送刘尊师祗诏阙庭三首 二','曹唐','quantangshi','','卷36','五峰已别隔人间，双阙何年许再还。
既埽山川收地脉，须留日月驻天颜。
霞觞共饮身虽在，风驭难陪迹未闲。
从此枕中唯有梦，梦魂何处访三山。','',''),('quantangshi-35438','送刘尊师祗诏阙庭三首 三','曹唐','quantangshi','','卷36','仙老闲眠碧草堂，帝书征入白云乡。
龟台欲署长生籍，鸾殿还论不死方。
红露想倾延命酒，素烟思爇降真香。
五千言外无文字，更有何词赠武皇。','',''),('quantangshi-35439','三年冬大礼五首 一','曹唐','quantangshi','','卷36','皇帝斋心洁素诚，自朝真祖报升平。
华山秋草多归马，沧海寒波绝洗兵。
银箭水残河势断，玉炉烟尽日华生。
千官整肃三天夜，劒佩初闻入太清。','',''),('quantangshi-35440','三年冬大礼五首 二','曹唐','quantangshi','','卷36','海日西飞度禁林，太清宫殿月沉沉。
不闻北斗倾尧酒，空觉南风入舜琴。
歌压钧天闲梦尽，诏归秋水道情深。
雪风更起古杉叶，时送步虚清磬音。','',''),('quantangshi-35441','三年冬大礼五首 三','曹唐','quantangshi','','卷36','太一天坛降紫君，属车龙鹤夜成羣。
春浮玉藻寒初落，露拂金茎曙欲分。
三代乐回风入律，四溟歌驻水成文。
千官不动旌旗下，日照南山万树云。','',''),('quantangshi-35442','三年冬大礼五首 四','曹唐','quantangshi','','卷36','山拥飞云海水清，天坛未夕仗先成。
千官不起金縢议，万国空瞻玉藻声。
禁火曙然烟焰褭，宫衣寒拂雪花轻。
侧闻左右皆周吕，看取从容致太平。','',''),('quantangshi-35443','三年冬大礼五首 五','曹唐','quantangshi','','卷36','太和琴暖发南薰，水阔风高得细闻。
沧海举歌夔是相，历山回禅舜为君。
翠微呼处生丹障，清静封中起白云。
今日病身慙小隐，欲将泉石勒移文。','',''),('quantangshi-35444','暮春戏赠吴端公','曹唐','quantangshi','','卷36','年少英雄好丈夫，大家望拜执金吾。
闲眠晓日听鶗鴂，笑倚春风仗辘轳。
深院吹笙闻汉婢，静街调马任奚奴。
牡丹花下帘钩外，独凭红肌捋虎须。','',''),('quantangshi-35445','奉送严大夫再领容府二首 一','曹唐','quantangshi','','卷36','海风卷树冻岚消，忧国宁辞岭外遥。
自顾勤劳甘百战，不将功业负三朝。
劒澄黑水曾芟虎，箭劈黄云惯射雕。
代北天南尽成事，肯将心许霍嫖姚。','',''),('quantangshi-35446','奉送严大夫再领容府二首 二','曹唐','quantangshi','','卷36','日照双旌射火山，笑迎宾从却南还。
风云暗发谈谐外，感会潜生气概间。
蕲竹水翻台榭湿，刺桐花落管弦闲。
无因得靸真珠履，亲从新侯定八蛮。','',''),('quantangshi-35447','赠南岳冯处士二首 一','曹唐','quantangshi','','卷36','白石溪边自结庐，风泉满院称幽居。
鸟啼深树斸灵药，花落闲窗看道书。
烟岚晚过鹿裘湿，水月夜明山舍虚。
支颐冷笑缘名出，终日王门强曳裾。','',''),('quantangshi-35448','赠南岳冯处士二首 二','曹唐','quantangshi','','卷36','寂寥深木闭烟霞，洞里相知有几家。
笑看潭鱼吹水沫，醉嗔溪鹿吃蕉花。
穿厨历历泉声细，绕屋悠悠树影斜。
夜静着灰封釜竈，自添文武养丹砂。','',''),('quantangshi-35449','题子侄书院双松','曹唐','quantangshi','','卷36','自种双松费几钱，顿令院落似秋天。
