枝压细风过枕上，影笼残月到窗前。
莫教取次成闲梦，使汝悠悠十八年。','',''),('quantangshi-35450','羽林贾中丞','曹唐','quantangshi','','卷36','四十年前百战身，曾驱虎队扫胡尘。
