故国暗回残士卒，新坟空葬旧衣裳。
散牵细马嘶青草，任去佳人吊白杨。
除却阴符与兵法，更无一物在仪牀。','',''),('quantangshi-35454','和周侍御买剑','曹唐','quantangshi','','卷36','将军溢价买吴钩，要与中原静寇讐。
试挂窗前惊电转，略抛牀下怕泉流。
青天露拔云霓泣，黑地潜擎鬼魅愁。
见说夜深星斗畔，等闲期尅月支头。','',''),('quantangshi-35455','病马五首呈郑校书章三吴十五先辈 一','曹唐','quantangshi','','卷36','騄駬何年别渥洼。
