阶前莫怪垂双泪，不遇孙阳不敢嘶。','',''),('quantangshi-35457','病马五首呈郑校书章三吴十五先辈 三','曹唐','quantangshi','','卷36','不剪焦毛鬣半翻，何人别是古龙孙。
