一朝千里心犹在，争肯潜忘秣饲恩。','',''),('quantangshi-35458','病马五首呈郑校书章三吴十五先辈 四','曹唐','quantangshi','','卷36','空被秋风吹病毛，无因濯浪刷洪涛。
