今日却怀行乐处，两床丝竹水楼中。','',''),('quantangshi-35461','长安客舍叙邵陵旧宴寄永州萧使君五首 二','曹唐','quantangshi','','卷36','不知何路却飞翻，虚受贤侯郑重恩。
