谁知汉武无仙骨，满竈黄金成白烟。','',''),('quantangshi-35573','圣政纪颂','來鵠','quantangshi','','卷36','三皇不书，五帝不纪。
有圣有神，风销日已。
何教何师，生来死止。
无典无法，顽肩奡比。
三皇实作，五帝实治。
成天造地，不昏不圯。
言得非排，文得圣齿。
表表如见者，莫若乎史。
是知朴绳休结，正简斯若。
君诰臣箴，觚编毫络。
前书后经，规善鉴恶。
国之大章，如何寝略。
呜呼！贞观多吁，永徽多俞。
廷日发论，殿日发谟。
牙孽不作，鸟鼠不除。
论出不盖，谟行不纡。
楹然史臣，蛇然史裾。
瞠瞠而视，逶逶而窭。
翘笔当面，决防纳污。
不梏尔智，不息我愚。
执言直注，史文直敷。
故得粲粲朝典，落落廷謇。
圣牍既多，尧风不浅。
颂编坦轴，君出臣显。
若俨见旒，若俯见冕。
无闲殿旷廷，无尸安素宴。
三皇不亡，五帝不翦。
太宗得之，史焉斯展。
暨乎后相图身，天子专问。
我独以言，史不得近。
丘明见嫌，倚相在摈。
秉笔如今，随班不进。
班退史归，枉然畴依。
奏问莫覩，嘉谟固稀。
取彼诰命，禄为国肥。
炯哉时皇，言必成章。
德宣五帝，道奥三皇。
如何翌臣，嚵肉嗜𥁃。
觜距磨抉，楅衡拘长。
控截僚位，占护阳光。
垣私藩已，远史廋唐。
俾德音嘉访，默缩暗亡。
咽典噤法，盖圣笼昌。
曷以致此，史文不张。
后必非笑，将来否臧。
谓乎殿空扆逸，朝懵廷荒。
不知奸蔽，文失汪洋。
有贞观业，有永徽纲。
亦匿匪见，亦寝匪彰。
赖有后臣，斯言不佞。
伊尹直心，太甲须圣。
事既可书，史何不命。
乃具前欺，大陈不敬。
曰逐史之喻，请以物竝。
且十夫树杨，一夫欲竞。
栽既未牢，摒岂能盛。
帝业似栽，逐史似摒。
穆宗怃然，若疚若醟。
昔何臣斯，隐我祖正。
不传亲问，不写密诤。
孰示来朝，以光神政。
由是天呼震吸，征奔召急。
史题笔来，叱廷而入。
端耳抗目，不撝不挹。
獬豸侧头，螭蚪摆湿。
握管绝怡，当殿而立。
君也尽问，臣也倒诚。
磊磊其事，镗镗其声。
大何不显，细何不明。
语未绝绪，史已录成。
谓之何书，以政纪名。
伊纪清芬，可昭典坟。
古师官鸟，昔圣官云。
方之我后，录里书分。
录有君法，书有君文。
君法君文，在圣政纪云。
殿无闲时，廷无旷日。
云诹波访，卷编刓笔。
君劬臣劳，上讨下述。
惟勤惟明，在圣政纪出。
至德何比，至教焉如。
孰窥孰测，外夷内储。
谓君有道乎，臣有谟欤。
有道有谟，在圣政纪书。
一体列秩，同力翼戴。
祈福去邪，绝防无碍。
国章可披，唐文可爱。
善咨不偷，嘉论不盖。
不偷不盖，在圣政纪载。
谅夫，总斯不朽。
可悬魏阙，愚得是言。
非讪非伐，实谓医臣浑沌。
开君日月，妖物雰死。
天文光发，惟我之有颂兮，奚斯跃而董狐蹙。','',''),('quantangshi-35574','宛陵送李明府罢任归江州','來鵠','quantangshi','','卷36','菊花村晚雁来天，共把离觞向水边。
官满便寻垂钓侣，家贫已用卖琴钱。
浪生湓浦千层雪，云起炉峰一炷烟。
倘见吾乡旧知己，为言顦顇过年年。','',''),('quantangshi-35575','清明日与友人游玉粒塘庄','來鵠','quantangshi','','卷36','几宿春山逐陆郎，清明时节好烟光。
归穿细荇船头滑，醉踏残花屐齿香。
风急岭云飘迥野，雨余田水落方塘。
不堪吟罢东回首，满耳蛙声正夕阳。','',''),('quantangshi-35576','寒食山馆书情','來鵠','quantangshi','','卷36','独把一杯山馆中，每经时节恨飘蓬。
侵堦草色连朝雨，满地梨花昨夜风。
蜀魄啼来春寂寞，楚魂吟后月朦胧。
分明记得还家梦，徐孺宅前湖水东。','',''),('quantangshi-35577','病起','來鵠','quantangshi','','卷36','春初一卧到秋深，不见红芳与绿阴。
窗下展书难久读，池边扶杖欲闲吟。
藕穿平地生荷叶，笋过东家作竹林。
在舍浑如远乡客，诗僧酒伴镇相寻。','',''),('quantangshi-35578','鄂渚除夜书怀','來鵠','quantangshi','','卷36','鹦鹉洲头夜泊船，此时形影共凄然。
难归故国干戈后，欲告何人雨雪天。
筯拨冷灰书闷字，枕陪寒席带愁眠。
自嗟落魄无成事，明日春风又一年。','',''),('quantangshi-35579','鄂渚清明日与乡友登头陀山','來鵠','quantangshi','','卷36','冷酒一杯相劝频，异乡相遇转相亲。
落花风里数声笛，芳草烟中无限人。
都大此时深怅望，岂堪高处更逡巡。
思量费子真仙子，不作头陀山下尘。','',''),('quantangshi-35580','蚕妇','來鵠','quantangshi','','卷36','晓夕采桑多苦辛，好花时节不闲身。
若教解爱繁华事，冻杀黄金屋里人。','',''),('quantangshi-35581','题庐山双劒峰','來鵠','quantangshi','','卷36','倚天双劒古今闲，三尺高于四面山。
若使火云烧得动，始应农器满人间。','',''),('quantangshi-35582','云','來鵠','quantangshi','','卷36','千形万象竟还空，映水藏山片复重。
无限旱苗枯欲尽，悠悠闲处作奇峰。','',''),('quantangshi-35583','金钱花','來鵠','quantangshi','','卷36','也无棱郭也无神，露洗还同铸出新。
青帝若教花里用，牡丹应是得钱人。','',''),('quantangshi-35584','晓鸡','來鵠','quantangshi','','卷36','黯黯严城罢鼓鼙，数声相续出寒栖。
不嫌惊破纱窗梦，却怕为妖半夜啼。','',''),('quantangshi-35585','山中避难作','來鵠','quantangshi','','卷36','山头烽火水边营，鬼哭人悲夜夜声。
唯有碧天无一事，日还西下月还明。','',''),('quantangshi-35586','早春','來鵠','quantangshi','','卷36','新历才将半纸开，小庭犹聚爆竿灰。
偏憎杨柳难钤辖，又惹东风意绪来。','',''),('quantangshi-35587','鹭鸶','來鵠','quantangshi','','卷36','褭丝翘足傍澄澜，消尽年光伫思间。
若使见鱼无羡意，向人姿态更应闲。','',''),('quantangshi-35588','子规','來鵠','quantangshi','','卷36','雨恨花愁同此冤，啼时闻处正春繁。
千声万血谁哀尔，争得如花笑不言。','',''),('quantangshi-35589','新安官舍闲坐','來鵠','quantangshi','','卷36','寂寞空阶草乱生，簟凉风动若为情。
不知独坐闲多少，看得蜘蛛结网成。','',''),('quantangshi-35590','除夜','來鵠','quantangshi','','卷36','事关休戚已成空，万里相思一夜中。
愁到晓鸡声绝后，又将顦顇见春风。','',''),('quantangshi-35591','游鱼','來鵠','quantangshi','','卷36','弄萍隈荇思夷犹，掉尾扬鬐逐慢流。
应怕碧岩岩下水，浮藤如线月如钩。','',''),('quantangshi-35592','鹦鹉','來鵠','quantangshi','','卷36','色白还应及雪衣，觜红毛绿语仍奇。
年年锁在金笼里，何似陇山闲处飞。','',''),('quantangshi-35593','偶题二首 一','來鵠','quantangshi','','卷36','近来灵鹊语何疎，独凭栏干恨有殊。
一夜绿荷霜翦破，赚他秋雨不成珠。','',''),('quantangshi-35594','偶题二首 二','來鵠','quantangshi','','卷36','水边箕踞静书空，欲解愁肠酒不浓。
可惜青天好雷雹，只能驱趂懒蛟龙。','',''),('quantangshi-35595','惜花','來鵠','quantangshi','','卷36','东风渐急夕阳斜，一树夭桃数日花。
为惜红芳今夜里，不知和月落谁家。','',''),('quantangshi-35596','洞庭隐','來鵠','quantangshi','','卷36','高卧洞庭三十春，芰荷香里独垂纶。
莫嫌无事闲销日，有事始怜无事人。','',''),('quantangshi-35597','古劒池','來鵠','quantangshi','','卷36','秋水莲花三四枝，我来慷慨步迟迟。
不决浮云斩邪佞，直成龙去欲何为。','',''),('quantangshi-35598','梅花','來鵠','quantangshi','','卷36','枝枝倚槛照池冰，粉薄香残恨不胜。
占得早芳何所利，与他霜雪助威棱。','',''),('quantangshi-35599','闻蝉','來鵠','quantangshi','','卷36','绿槐阴里一声新，雾薄风轻力未匀。
莫道闻时总惆怅，有愁人有不愁人。','',''),('quantangshi-35600','卖花谣','來鵠','quantangshi','','卷36','紫艳红苞价不同，匝街罗列起香风。
无言无语呈颜色，知落谁家池馆中。','',''),('quantangshi-35601','子规','來鵠','quantangshi','','卷36','月落空山闻数声，此时孤馆酒初醒。
投人语若似伊泪，口畔血流应始听。','',''),('quantangshi-35602','句','來鵠','quantangshi','','卷36','回眸绿水波初起，合掌白莲花未开。','',''),('quantangshi-35603','菊','李山甫','quantangshi','','卷36','篱下霜前偶得存，忍教迟晚避兰荪。
也销造化无多力，未受阳和一点恩。
栽处不容依玉砌，要时还许上金尊。
陶潜殁后谁知己，露滴幽丛见泪痕。','',''),('quantangshi-35604','风','李山甫','quantangshi','','卷36','喜怒寒暄直不匀，终无形状始无因。
能将尘土平欺客，爱把波澜枉陷人。
飘乐遰香随日在，绽花开柳逐年新。
深知造化由君力，试为吹嘘借与春。','',''),('quantangshi-35605','月','李山甫','quantangshi','','卷36','狡兔顽蟾死复生，度云经汉澹还明。
夜长虽耐对君坐，年少不禁随尔行。
玉桂影摇乌鹊动，金波寒注鬼神惊。
人间半被虚抛掷，唯向孤吟客有情。','',''),('quantangshi-35606','秋','李山甫','quantangshi','','卷36','傍雨衣风冷渐匀，更凭青女事精神。
来时将得几多雁，到处愁他无限人。
能被绿杨深懊恼，谩偎黄菊送殷勤。
邹家不用偏吹律，到底荣枯也自均。','',''),('quantangshi-35607','松','李山甫','quantangshi','','卷36','地耸苍龙势抱云，天教青共众材分。
孤标百尺云中见，长啸一声风里闻。
桃李傍他真是佞，藤萝攀尔亦非羣。
平生相爱应相识，谁道修篁胜此君。','',''),('quantangshi-35608','读汉史','李山甫','quantangshi','','卷36','四百年间反覆寻，汉家兴替好沾襟。
每逢奸诈须挼手，真遇英雄始醒心。
王莽弄来曾半破，曹公将去便平沈。
当时虚受君恩者，谩向青编作鬼林。','',''),('quantangshi-35609','上元怀古二首 一','李山甫','quantangshi','','卷36','南朝天子爱风流，尽守江山不到头。
总是战争收拾得，却因歌舞破除休。
尧行道德终无敌，秦把金汤可自由。
试问繁华何处有，雨苔烟草古城秋。','',''),('quantangshi-35610','上元怀古二首 二','李山甫','quantangshi','','卷36','争帝图王德尽衰，骤兴驰霸亦何为。
君臣都是一塲笑，家国共成千载悲。
排岸远樯森似槊，落波残照赫如旗。
今朝城上难回首，不见楼船索战时。','',''),('quantangshi-35611','隋堤柳','李山甫','quantangshi','','卷36','曾傍龙舟拂翠华，至今凝恨倚天涯。
但经春色还秋色，不觉杨家是李家。
背日古阴从北朽，逐波疎影向南斜。
年年只有晴风便，遥为雷塘送雪花。','',''),('quantangshi-35612','蒲关西道中作','李山甫','quantangshi','','卷36','国东王气凝蒲关，楼台帖出晴空间。
紫烟横捧大舜庙，黄河直打中条山。
地锁咽喉千古壮，风传歌吹万家闲。
来来去去身依旧，未及潘年鬓已斑。','',''),('quantangshi-35613','道李秀才入军','李山甫','quantangshi','','卷36','弱柳贞松一地栽，不因霜霰自难媒。
书生只是平时物，男子争无乱世才。
铁马已随红斾去，同人犹着白衣来。
到头功业须如此，莫为初心首重回。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35614','送蕲州裴员外','李山甫','quantangshi','','卷36','正作南宫第一人，蹔随霓斾怆离羣。
晓从阙下辞天子，春向江头待使君。
五马尚迷青琐路，双鱼犹惹翠兰芬。
明朝无路寻归处，禁树参差隔紫云。','',''),('quantangshi-35615','代孔明哭先主','李山甫','quantangshi','','卷36','忆昔南阳顾草庐，便乘雷电捧乘舆。
酌量诸夏须平取，期刻羣雄待遍锄。
南面未能成帝业，西陵那忍送宫车。
九疑山下频惆怅，曾许微臣水共鱼。','',''),('quantangshi-35616','送职方王郎中吏部刘员外自太原郑相公幕继奉征书归省署','李山甫','quantangshi','','卷36','双凤衔书次第飞，玉皇催促列仙归。
云开日月临青琐，风卷烟霞上紫微。
莲影一时空俭府，兰香同处扑尧衣。
此生长扫朱门者，每向人间梦粉闱。','',''),('quantangshi-35617','寒食二首 一','李山甫','quantangshi','','卷36','柳带东风一向斜，春阴澹澹蔽人家。
有时三点两点雨，到处十枝五枝花。
万井楼台疑绣画，九原珠翠似烟霞。
年年今日谁相问，独卧长安泣岁华。','',''),('quantangshi-35618','寒食二首 二','李山甫','quantangshi','','卷36','风烟放荡花披猖，秋千女儿飞短墙。
绣袍驰马拾遗翠，锦袖鬬鸡喧广塲。
天地气和融霁色，池台日暖烧春光。
自怜尘土无他事，空脱荷衣泥醉乡。','',''),('quantangshi-35619','又代孔明哭先主','李山甫','quantangshi','','卷36','鲸鬣翻腾四海波，始将天意用干戈。
尽驱神鬼随鞭策，全罩英雄入网罗。
提劒尚残吴郡国，垂衣犹欠魏山河。
鼎湖无路追仙驾，空使羣臣泣血多。','',''),('quantangshi-35620','贫女','李山甫','quantangshi','','卷36','平生不识绣衣裳，闲把荆钗亦自伤。
镜里只应谙素貌，人间多自信红妆。
当年未嫁还忧老，终日求媒即道狂。
两意定知无说处，暗垂珠泪湿蚕筐。','',''),('quantangshi-35621','寓怀','李山甫','quantangshi','','卷36','万古交驰一片尘，思量名利孰如身。
长疑好事皆虚事，却恐闲人是贵人。
老逐少来终不放，辱随荣后直须匀。
劝君不用夸头角，梦里输赢总未真。','',''),('quantangshi-35622','蜀中寓怀','李山甫','quantangshi','','卷36','千里烟霞锦水头，五丁开得也风流。
春装宝阙重重树，日照仙州万万楼。
蛙似公孙虽不守，龙如诸葛亦须休。
此中无限英雄鬼，应对江山各自羞。','',''),('quantangshi-35623','下第卧疾卢员外召游曲江','李山甫','quantangshi','','卷36','眼前何事不伤神，忍向江头更弄春。
桂树既能欺贱子，杏花争肯采闲人。
麻衣未掉浑身雪，皂盖难遮满面尘。
珍重列星相借问，嵇康慵病也天真。','',''),('quantangshi-35624','司天台','李山甫','quantangshi','','卷36','拂云朱槛捧昭回，静对铜浑水镜开。
太史只知频奏瑞，苍生无计可防灾。
景公进德星曾退，汉帝推诚日为回。
何事旷官全不语，好天良月锁高台。','',''),('quantangshi-35625','落花','李山甫','quantangshi','','卷36','落拓东风不藉春，吹开吹谢两何因。
当时曾见笑筵主，今日自为行路尘。
颜色却还天上女，馨香留与世间人。
明年寒食重相见，零泪无端又满巾。','',''),('quantangshi-35626','赴举别所知','李山甫','quantangshi','','卷36','腰劒囊书出户迟，壮心奇命两相疑。
麻衣尽举一双手，桂树只生三两枝。
黄祖不怜鹦鹉客，志公偏赏麒麟儿。
叔牙忧我应相痛，回首天涯寄所思。','',''),('quantangshi-35627','贺邢州卢员外','李山甫','quantangshi','','卷36','紫泥飞诏下金銮，列象分明世仰观。
北省谏书藏旧草，南宫郎署握新兰。
春归凤沼恩波暖，晓入鸳行瑞气寒。
偏是此生栖息者，满衣零泪一时干。','',''),('quantangshi-35628','方干隐居','李山甫','quantangshi','','卷36','咬咬嘎嘎水禽声，露洗松阴满院清。
溪畔印沙多鹤迹，槛前题竹有僧名。
问人远岫千重意，对客闲云一片情。
早晚尘埃得休去，且将书劒事先生。','',''),('quantangshi-35629','早春微雨','李山甫','quantangshi','','卷36','怪来莺蝶似凝愁，不觉看花蹔湿头。
疎影未藏千里树，远阴微翳万家楼。
青罗舞袖纷纷转，红脸啼珠旋旋收。
岁旱且须教济物，为霖何事爱风流。','',''),('quantangshi-35630','谒翰林刘学士不遇','李山甫','quantangshi','','卷36','梦绕清华宴地深，洞宫横锁晓沈沈。
鹏飞碧海终难见，鹤入青霄岂易寻。
六尺羇魂迷定止，两行愁血谢知音。
平生只耻凌风翼，随得鸣珂上禁林。','',''),('quantangshi-35631','答刘书记见赠','李山甫','quantangshi','','卷36','吟近秋光思不穷，酷探骚雅愧无功。
茫然心苦千篇拙，瞑坐神凝万象空。
月上开襟当北户，竹边回首揖西风。
知音频有新诗赠，白雪纷纷落郢中。','',''),('quantangshi-35632','贺友人及第','李山甫','quantangshi','','卷36','得水蛟龙失水鱼，此心相对两何如。
敢辞今日须行卷，犹喜他年待荐书。
松桂也应情未改，萍蓬争奈迹还疎。
春风不见寻花伴，遥向青云泥子虚。','',''),('quantangshi-35633','雨后过华岳庙','李山甫','quantangshi','','卷36','华山黑影霄崔嵬，金天□□门未开。
雨淋鬼火灭不灭，风送神香来不来。
墙外素钱飘似雪，殿前阴栢吼如雷。
知君暗宰人间事，休把苍生梦里裁。','',''),('quantangshi-35634','赠弹琴李处士','李山甫','quantangshi','','卷36','情知此事少知音，自是先生枉用心。
世上几时曾好古，人前何必更沾襟。
致身不似笙竽巧，悦耳宁如郑卫淫。
三尺焦桐七条线，子期师旷两沈沈。','',''),('quantangshi-35635','刘员外寄移菊','李山甫','quantangshi','','卷36','秋来缘树复缘墙，怕共平芜一例荒。
颜色不能随地变，风流唯解逐人香。
烟含细叶交加碧，露拆寒英次第黄。
深谢栽培与知赏，但慙终岁待重阳。','',''),('quantangshi-35636','南山','李山甫','quantangshi','','卷36','钝碧顽青几万秋，直无天地始应休。
莫嫌尘土佯遮面，能向楼台强出头。
霁色陡添千尺翠，夕阳闲放一堆愁。
假绕不是神仙骨，终抱琴书向此游。','',''),('quantangshi-35637','山中览刘书记新诗','李山甫','quantangshi','','卷36','记室新诗相寄我，蔼然清绝更无过。
溪风满袖吹骚雅，岩瀑无时滴薜萝。
云外山高寒色重，雪中松苦夜声多。
静酬嘉唱对幽景，苍鹤羸栖古木柯。','',''),('quantangshi-35638','早秋山中作','李山甫','quantangshi','','卷36','荣枯无路入千峯，肥遯谁谐此志同。
司寇亦曾遭鲁黜，步兵何事哭途穷。
桧松瘦健滴秋露，户牖虚明生晚风。
山思更清人影绝，陇云飞入草堂中。','',''),('quantangshi-35639','赋得寒月寄齐已','李山甫','quantangshi','','卷36','松下清风吹我襟，上方钟磬夜沉沉。
已知庐岳尘埃绝，更忆寒山雪月深。
高谢万缘消祖意，朗吟千首亦师心。
岂知名出徧诸夏，石上栖禅竹影侵。','',''),('quantangshi-35640','曲江二首 一','李山甫','quantangshi','','卷36','南山低对紫云楼，翠影红阴瑞气浮。
一种是春长富贵，大都为水也风流。
争攀柳带千千手，间插花枝万万头。
独向江边最惆怅，满衣尘土避王侯。','',''),('quantangshi-35641','曲江二首 二','李山甫','quantangshi','','卷36','江色沈天万草齐，暖烟晴霭自相迷。
蜂怜杏蕋细香落，莺坠柳条浓翠低。
千队国娥轻似雪，一羣公子醉如泥。
斜阳怪得长安动，陌上分飞万马蹄。','',''),('quantangshi-35642','迁居清溪和刘书记见示','李山甫','quantangshi','','卷36','担锡归来竹绕溪，过津曾笑鲁儒迷。
端居味道尘劳息，扣寂眠云心境齐。
还似村家无宠禄，时将隣叟话幽栖。
山衣毳烂唯添野，石井源清不贮泥。
祖意岂从年腊得，松枝肯为雪霜低。
晚天吟望秋光重，雨阵横空蔽断霓。','',''),('quantangshi-35643','阴地关崇徽公主手迹','李山甫','quantangshi','','卷36','一拓纤痕更不收，翠微苍藓几经秋。
谁陈帝子和番策，我是男儿为国羞。
寒雨洗来香已尽，澹烟笼着恨长留。
可怜汾水知人意，旁与吞声未忍休。','',''),('quantangshi-35644','题李员外厅','李山甫','quantangshi','','卷36','石砌蛩吟响，草堂人语稀。
道孤思绝唱，年长渐知非。
名利终成患，烟霞亦可依。
高丘松盖古，闲地药苗肥。
猨鸟啼嘉景，牛羊傍晚晖。
幽栖还自得，清啸坐忘机。
爱彼人深处，白云相伴归。','',''),('quantangshi-35645','山中寄梁判官','李山甫','quantangshi','','卷36','归卧东林计偶谐，柴门深向翠微开。
更无尘事心头起，还有诗情象外来。
康乐公应频结社，寒山子亦患多才。
星郎雅是道中侣，六艺拘牵在隗台。','',''),('quantangshi-35646','禅林寺作寄刘书记','李山甫','quantangshi','','卷36','坐近松风骨自寒，茅斋直拶白云边。
玄关不闭何人到，此事谁论在佛先。
天竺老师留一句，曹溪行者答全篇。
今朝林下忘言说，强把新诗寄谪仙。','',''),('quantangshi-35647','山中病后作','李山甫','quantangshi','','卷36','卧病厌厌三伏尽，商飙初自水边来。
高峯枯槁骨偏峭，野树扶疎叶未摧。
时序追牵从鬓改，蝉声酸急是谁催。
云门不闭全无事，心外沈然一聚灰。','',''),('quantangshi-35648','寄卫别驾','李山甫','quantangshi','','卷36','晓屐归来岳寺深，尝思道侣会东林。
昏沈天竺看经眼，萧索净名老病心。
云盖数重横陇首，苔花千点遍松阴。
知君超达悟空旨，三径闲行抱素琴。','',''),('quantangshi-35649','遣怀','李山甫','quantangshi','','卷36','长松埋涧底，郁郁未出原。
孤云飞陇首，高洁不可攀。
古道贵拙直，时事不足言。
莫饮盗泉水，无为天下先。
智者与愚者，尽归北邙山。
唯有东流水，年光不蹔闲。','',''),('quantangshi-35650','酬刘书记一二知己见寄','李山甫','quantangshi','','卷36','见说金台客，相逢秪论诗。
坐来残暑退，吟许野僧知。
自喜幽栖僻，唯慙道义亏。
身闲偏好古，句冷不求奇。
晦迹全无累，安贫自得宜。
同人终念我，莲社有归期。','',''),('quantangshi-35651','山中依韵答刘书记见赠','李山甫','quantangshi','','卷36','幽居少人事，三径草不开。
隐几虚室静，闲云入坐来。
至道非内外，讵言才不才。
宝月当秋空，高洁无纤埃。
心灭百虑减，诗成万象回。
亦有吾庐在，寂寞旧山隈。
从容未归去，满地生青苔。
谢公寄我诗，清奇不可陪。
白云飞不尽，碧云欲成堆。
惊风出地户，虩虩似震雷。
吟哦山岳动，令人心胆摧。
思君览章句，还复如望梅。
慷慨追古意，旷望登高台。
何当陶渊明，远师劝倾杯。
流年将老来，华髪自相催。
野寺连屏障，左右相裴回。','',''),('quantangshi-35652','山中答刘书记寓怀','李山甫','quantangshi','','卷36','贵门多冠冕，日与荣辱并。
山中有独夫，笑傲出衰盛。
正直任天真，鬼神亦相敬。
之子贲丘园，户牖松萝暎。
骨将槁木齐，心同止水净。
笔头指金波，座上横玉柄。
芙蓉出秋渚，绣段流清咏。
高古不称时，沈默岂相竞。
穷搜万籁息，危坐千峯静。
林僧继嘉唱，风前亦为幸。','',''),('quantangshi-35653','项羽庙','李山甫','quantangshi','','卷36','为虏为王尽偶然，有何羞见汉江船。
停分天下犹嫌少，可要行人赠纸钱。','',''),('quantangshi-35654','春日商山道中作','李山甫','quantangshi','','卷36','一迳春光里，扬鞭入翠微。
风来花落帽，云过雨沾衣。
谷鸟衔枝去，巴人负笈归。
残阳更惆怅，前路客亭稀。','',''),('quantangshi-35655','古石砚','李山甫','quantangshi','','卷36','追琢他山石，方圆一勺深。
抱真唯守墨，求用每虚心。
波浪因文起，尘埃为废侵。
凭君更研究，何啻直千金。','',''),('quantangshi-35656','惜花','李山甫','quantangshi','','卷36','未会春风意，开君又落君。
一年今烂熳，几日便缤纷。
别艳那堪赏，余香不忍闻。
尊前恨无语，应解作朝云。','',''),('quantangshi-35657','别杨秀才','李山甫','quantangshi','','卷36','因乱与君别，相逢悲且惊。
开襟魂自慰，拭泪眼空明。
故国已无业，旧交多不生。
如何又分袂，难话别离情。','',''),('quantangshi-35658','自叹拙','李山甫','quantangshi','','卷36','自怜心计拙，欲语更悲辛。
世乱僮欺主，年衰鬼弄人。
镜中颜欲老，江上业长贫。
不是刘公乐，何由变此身。','',''),('quantangshi-35659','乱后途中','李山甫','quantangshi','','卷36','乱离寻故园，朝市不如村。
恸哭翻无泪，颠狂觉少魂。
诸侯贪割据，羣盗恣并吞。
为问登坛者，何年答汉恩。','',''),('quantangshi-35660','燕','李山甫','quantangshi','','卷36','每岁同辛苦，看人似有情。
乱飞春得意，幽语夜闻声。
整羽庄姜恨，回身汉后轻。
豪家足金弹，不用污雕楹。','',''),('quantangshi-35661','题慈云寺僧院','李山甫','quantangshi','','卷36','帝城深处寺，栖殿压秋江。
红叶去寒树，碧峯来晓窗。
烟霞生净土，苔藓上高幢。
欲问吾师语，心猨不肯降。','',''),('quantangshi-35662','闻子规','李山甫','quantangshi','','卷36','冤禽名杜宇，此事更难知。
昔帝一时恨，后人千古悲。
断肠思故国，啼血溅芳枝。
况是天涯客，那堪□□眉。','',''),('quantangshi-35663','送刘将军入关讨贼','李山甫','quantangshi','','卷36','世人多恃武，何者是真雄。
欲灭黄巾贼，须凭黑矟公。
指星忧国计，望气识天风。
明日凌云上，期君第一功。','',''),('quantangshi-35664','陪郑先辈华山罗谷访张隐者','李山甫','quantangshi','','卷36','白云闲洞口，飞盖入岚光。
好鸟共人语，异花迎客香。
谷风闻鼓吹，苔石见文章。
不是陪仙侣，无因访阮郎。','',''),('quantangshi-35665','兵后寻边三首 一','李山甫','quantangshi','','卷36','千里烟砂尽日昏，战余烧罢闭重门。
新成劒戟皆农器，旧着衣裳尽血痕。
卷地朔风吹白骨，柱天青气泣幽魂。
自怜长策无人问，羞戴儒冠傍塞垣。','',''),('quantangshi-35666','兵后寻边三首 二','李山甫','quantangshi','','卷36','旗头指处见黄埃，万马横驰鹘翅回。
劒戟远腥凝血在，山河先暗阵云来。
角声恶杀悲于哭，鼓势争强怒若雷。
日暮却登寒垒望，饱鸱清啸伏尸堆。','',''),('quantangshi-35667','兵后寻边三首 三','李山甫','quantangshi','','卷36','风怒边沙迸铁衣，胡儿胡马正骄肥。
将军对阵谁教入，战士辞营不道归。
新血溅红黏蔓草，旧骸堆白映寒晖。
胸中纵有销兵术，欲向何门说是非。','',''),('quantangshi-35668','沧浪峡','李山甫','quantangshi','','卷36','走毂飞蹄过此傍，几人留意问沧浪。
烟波莫笑趋名客，为爱朝宗日夜忙。','',''),('quantangshi-35669','公子家二首 一','李山甫','quantangshi','','卷36','曾是皇家几世侯，入云高第照神州。
柳遮门户横金锁，花拥弦歌咽画楼。
锦袖妒姬争巧笑，玉衔[骄]马索闲游。
麻衣酷献平生业，醉倚春风不点头。','',''),('quantangshi-35670','公子家二首 二','李山甫','quantangshi','','卷36','柳底花阴压露尘，醉烟轻罩一团春。
鸳鸯占水能嗔客，鹦鹉嫌笼解駡人。
騕褭似龙随日换，轻盈如燕逐年新。
不知买尽长安笑，活得苍生几户贫。','',''),('quantangshi-35671','山下残夏偶作','李山甫','quantangshi','','卷36','等闲三伏后，独卧此高丘。
残暑炎于火，林风爽带秋。
声名何要出，吟咏亦堪休。
自许红尘外，云溪好漱流。','',''),('quantangshi-35672','夜吟','李山甫','quantangshi','','卷36','除却闲吟外，人间事事慵。
更深成一句，月冷上孤峯。
穷理多瞑目，含毫静倚松。
终篇浑不寐，危坐到晨钟。','',''),('quantangshi-35673','代崇徽公主意','李山甫','quantangshi','','卷36','金钗坠地鬓堆云，自别朝阳帝岂闻。
遣妾一身安社稷，不知何处用将军。','',''),('quantangshi-35674','下第献所知三首 一','李山甫','quantangshi','','卷36','偶向江头别钓矶，等闲经岁与心违。
虚教六尺受辛苦，枉把一身忧是非。
青桂本来无欠负，碧霄何处有因依？
春风不用相催促，回避花时也解归。','',''),('quantangshi-35675','下第献所知三首 二','李山甫','quantangshi','','卷36','不识人间巧路岐，只将端拙泥神只。
与他名利本无分，却共水云曾有期。
大抵物情应莫料，近来天意也须疑。
自怜心计今如此，凭仗春醪为解颐。','',''),('quantangshi-35676','下第献所知三首 三','李山甫','quantangshi','','卷36','十年磨镞事锋铓，始逐朱旗入战塲。
四海风云难际会，一生肝胆易开张。
退飞莺谷春零落，倒卓龙门路渺茫。
今日慙知也慙命，笑余歌罢忽凄凉。','',''),('quantangshi-35677','寄太常王少卿','李山甫','quantangshi','','卷36','别后西风起，新蝉坐卧闻。
秋天静如水，远岫碧侵云。
雅饮纯和气，清吟冰雪文。
想思重回首，梧叶下纷纷。','',''),('quantangshi-35678','游侠儿','李山甫','quantangshi','','卷36','好把雄姿浑世尘，一塲闲事莫因循。
荆轲只为闲言语，不与燕丹了得人。','',''),('quantangshi-35679','下第出春明门','李山甫','quantangshi','','卷36','曾和秋雨驱愁入，却向春风领恨回。
深谢灞陵堤畔柳，与人头上拂尘埃。','',''),('quantangshi-35680','望思台','李山甫','quantangshi','','卷36','君父昏蒙死不回，谩将平地筑高台。
九层黄土是何物，销得向前冤恨来。','',''),('quantangshi-35681','病中答刘书记见赠','李山甫','quantangshi','','卷36','病来双树下，云脚上禅袍。
频有琼瑶赠，空瞻雪月高。
已知捐俗态，时许话风骚。
衰疾未能起，相思徒自劳。','',''),('quantangshi-35682','早秋山中作','李山甫','quantangshi','','卷36','谁到山中语，雨余风气秋。
烟岚出涧底，瀑布落牀头。
至道亦非远，僻诗须苦求。
千峰有嘉景，拄杖独巡游。','',''),('quantangshi-35683','别墅','李山甫','quantangshi','','卷36','此地可求息，开门足野情。
窗明雨初歇，日落风更清。
苍藓槎根匝，碧烟水面生。
翫奇心自乐，暑月听蝉声。','',''),('quantangshi-35684','柳十首 一','李山甫','quantangshi','','卷36','灞岸江头腊雪消，东风偷软入纤条。
春来不忍登楼望，万架金丝着地娇。','',''),('quantangshi-35685','柳十首 二','李山甫','quantangshi','','卷36','受尽风霜得到春，一条条是逐年新。
寻常送别无余事，争忍攀将过与人。','',''),('quantangshi-35686','柳十首 三','李山甫','quantangshi','','卷36','长恨阳和也世情，把香和艳与红英。
家家只是栽桃李，独自无根到处生。','',''),('quantangshi-35687','柳十首 四','李山甫','quantangshi','','卷36','只为遮楼又拂桥，被人摧折好枝条。
假饶张绪如今在，须把风流暗里销。','',''),('quantangshi-35688','柳十首 五','李山甫','quantangshi','','卷36','弱带低垂可自由，傍他门户倚他楼。
金风不解相抬举，露压烟欺直到秋。','',''),('quantangshi-35689','柳十首 六','李山甫','quantangshi','','卷36','终日堂前学画眉，几人曾道胜花枝。
试看三月春残后，门外青阴是阿谁。','',''),('quantangshi-35690','柳十首 七','李山甫','quantangshi','','卷36','也曾飞絮谢家庭，从此风流别有名。
不是向人无用处，一枝愁杀别离情。','',''),('quantangshi-35691','柳十首 八','李山甫','quantangshi','','卷36','从来只是爱花人，杨柳何曾占得春。
多向客亭门外立，与他迎送往来尘。','',''),('quantangshi-35692','柳十首 九','李山甫','quantangshi','','卷36','强扶柔态酒难醒，殢着春风别有情。
公子王孙且相伴，与君俱得几时荣。','',''),('quantangshi-35693','柳十首 十','李山甫','quantangshi','','卷36','无赖秋风斗觉寒，万条烟草一时干。
游人若要春消息，直向江头腊后看。','',''),('quantangshi-35694','酬刘书记见赠','李山甫','quantangshi','','卷36','独在西峯末，怜君和气多。
劳生同朽索，急景似倾波。
禅者行担锡，樵师语隔坡。
旱□生赤藓，古木架青萝。
石涧新蝉脱，茅檐旧燕窠。
篇章蒙见许，松月好相过。
思苦通真理，吟清合大和。
□□□□□，风起送渔歌。','',''),('quantangshi-35695','赠徐三十','李山甫','quantangshi','','卷36','春满南宫白日长，夜来新值锦衣郎。
朱排六相助神耸，玉衬一厅侵骨凉。
砌竹拂袍争草色，庭花飘艳妬兰香。
从今不羡乘槎客，曾到三星列宿傍。','',''),('quantangshi-35696','牡丹','李山甫','quantangshi','','卷36','邀勒春风不早开，众芳飘后上楼台。
数苞仙艳火中出，一片异香天上来。
晓露精神妖欲动，暮烟情态恨成堆。
知君也解相轻薄，斜倚阑干首重回。','',''),('quantangshi-35697','赠宿将','李山甫','quantangshi','','卷36','校猎燕山经几春，雕弓白羽不离身。
年来马上浑无力，望见飞鸿指似人。','',''),('quantangshi-35698','水仙操','李咸用','quantangshi','','卷36','大波相拍流水鸣，蓬山鸟兽多奇形。
琴心不喜亦不惊，安弦缓爪何泠泠。
水仙缥缈来相迎，伯牙从此留嘉名。
峄阳散木虚且轻，重华斧下知其声。
檿丝相糺成凄清，调和引得薰风生。
指底先王长养情，曲终天下称太平。
后人好事传其曲，有时声足意不足。
始峩峩兮复洋洋，但见山青兼水绿。
成连入海移人情，岂是本来无嗜欲。
琴兮琴兮在自然，不在徽金将轸玉。','',''),('quantangshi-35699','鸡鸣曲','李咸用','quantangshi','','卷36','海树相扶乌影翘，戴红拍翠声胶胶。
鸳瓦冻危金距趫，夸雄鬬气争相高。
漏残雨急风萧萧，患乱忠臣欺宝刀。
霜浓月薄星昭昭，太平才子能歌谣。
山翁梦断出衡茅，谷口雾中饥虎号，离人枕上心忉忉。','',''),('quantangshi-35700','西门行','李咸用','quantangshi','','卷36','劳禽不择枝，饥虎不畏槛。
君子当固穷，无为仲由滥。
尔奋空拳彼击剑，水纵长澜火飞焰。
汉高偶试神蛇验，武王龟筮惊人险。
四龙或跃犹依泉，小狐勿恃冲波胆。','',''),('quantangshi-35701','轻薄怨','李咸用','quantangshi','','卷36','花骢躞蹀游龙骄，连连宝节挥长鞘。
凤雏麟子皆至交，春风相逐垂杨桥。
捻笙软玉开素苞，画楼闪闪红裙摇。
碧蹄偃蹇连金镳，狂情十里飞相烧。
西母青禽轻飘飘，分环破璧来往劳。
黄金千镒新一宵，少年心事风中毛。
明朝何处逢娇饶，门前桃树空夭夭。','',''),('quantangshi-35702','长歌行','李咸用','quantangshi','','卷36','要衣须破束，欲炙须解牛。
当年不快意，徒为他人留。
百岁之约何悠悠，华髪星星稀满头。
蛾眉螓首聊我仇，圆红阙白令人愁，何不夕引清奏？
朝登翠楼，逢花便折，闻胜即游。
鼓腕腾棍晴雷收，舞腰困褭垂杨柔。
象筯击折歌勿休，玉山未倒非风流。
眼前有物俱是梦，莫将身作黄金讐。
死生同域不用惧，富贵在天何足忧。','',''),('quantangshi-35703','巫山高','李咸用','quantangshi','','卷36','通蜀连秦山十二，中有妖灵会人意。
鬬艳传情世不知，楚王魂梦春风里。
雨态云容多似是，色荒见物皆成媚。
露泫烟愁岩上花，至今犹滴相思泪。
西眉南脸人中美，或者皆闻无所利。
忍听凭虚巧佞言，不求万寿翻求死。','',''),('quantangshi-35704','公无渡河','李咸用','quantangshi','','卷36','有叟有叟何清狂，行搔短髪提壶浆。
乱流直涉神洋洋，妻止不听追沈湘。
偕老不偕死，箜篌遗凄凉。
刳松轻稳琅玕长，连呼急榜庸何妨。
见溺不援能语狼，忍听丽玉传悲伤。','',''),('quantangshi-35705','春雨','李咸用','quantangshi','','卷36','大帝闲吹破冻风，青云融液流长空。
天人醉引玄酒注，倾香旋入花根土。
湿尘轻舞唐唐春，神娥无迹莓苔新。
老农私与牧童论，纷纷便是仓箱本。','',''),('quantangshi-35706','石版歌','李咸用','quantangshi','','卷36','云根劈裂雷斧痕，龙泉切璞青皮皴。
直方挺质贞且真，当庭卓立凝顽神。
春雨流膏成立文，主人性静看长新。
明月夜来回短影，何如照冷太湖滨。','',''),('quantangshi-35707','春宫词','李咸用','quantangshi','','卷36','风和气淑宫殿春，感阳体解思君恩。
眼光滴滴心振振，重瞳不转忧生民，女当为妾男当臣。
男力百岁在，女色片时新。
用不用，唯一人。
敢放天宠私微身，六宫万国教谁宾。','',''),('quantangshi-35708','富贵曲','李咸用','quantangshi','','卷36','画藻雕山金碧彩，鸳鸯曡翠眠晴霭。
编珠影里醉春庭，团红片下攒歌黛。
革咽丝烦欢不改，缴绛垂缇忽如晦。
活花起舞夜春来，蜡焰煌煌天日在。
雪暖瑶杯凤髓融，红拖象筯猩唇细。
空中汉转星移盖，火城拥出随朝会。
车如雷兮马如龙，鬼神辟易不敢害。
冠峩剑重锵环佩，步入天门相真宰。
开口长为爵禄筌，回眸便是公卿罪。
珍珠索得龙宫贫，膏腴刮下苍生背。
九野干戈指着心，威福满拳犹未快。
我闻周公贵为天子弟，富有半四海。
蔑有骄奢贻后悔，红锦障收。
珊瑚树碎，至今笑石崇王恺。','',''),('quantangshi-35709','独鹄吟','李咸用','quantangshi','','卷36','碧玉喙长丹顶圆，亭亭危立风松间。
啄萍吞鳞意已阑，举头咫尺轻重天。
黑翎白本排云烟，离羣脱侣孤如仙。
披霜唳月惊婵娟，逍游忘却还青田。
鸢寒鸦晚空相喧，时时侧耳清冷泉。','',''),('quantangshi-35710','煌煌京洛行','李咸用','quantangshi','','卷36','长安近甸巡游遍，洛阳寻有黄龙见。
千乘万骑如雷转，差差清跸祥云卷。
百司旧分当玉殿，太平官属无遗彦。
歌钟沸激香尘散，晨旗隐隐罗轩冕。
周公旧迹生红藓，瀍涧波光春照晚。
但听嵩山万岁声，将军旗鼓何时偃。','',''),('quantangshi-35711','升天行','李咸用','quantangshi','','卷36','堂堂削玉青蝇喧，寒鸦啄鼠愁飞鸾。
梳玄洗白逡巡间，兰言花笑俄衰残。
盘金束紫身属官，强仁小德终无端。
不如服取长流丹，潜神却入黄庭闲。
志定功成飞九关，逍遥长揖辞人寰。
空中龙驾时回旋，左云右鹤翔翩联。
双童树节当风翻，常娥倚桂开朱颜。
河边牛子星郎牵，三清宫殿浮晴烟。
玉皇据案方凝然，仙官立仗森幢幡。
引余再拜归仙班，清声妙色视听安。
飡和饮顺中肠宽，虚无之乐不可言。','',''),('quantangshi-35712','绯桃花歌','李咸用','quantangshi','','卷36','上帝春宫思丽绝，夭桃变态求新悦。
便是花中倾国容，牡丹露泣长门月。
野树滴残龙战血，曦车碾下朝霞屑。
惆怅东风未解狂，争教此物芳菲歇。','',''),('quantangshi-35713','短歌行','李咸用','quantangshi','','卷36','一罇绿酒绿于染，拍手高歌天地险。
上得青云下不难，下在黄埃上须渐。
少年欢乐须及时，莫学懦夫长泣岐。
白日欲沈犹未沈，片月已来天半垂。
坎鼓锵钟杀愁贼，挼碎是非佯不识。
长短高卑不可求，莫叹人生头雪色。','',''),('quantangshi-35714','小松歌','李咸用','quantangshi','','卷36','幽人不喜凡草生，秋锄斸得寒青青。
庭闲土瘦根脚狞，风摇雨拂精神醒。
短影月斜不满尺，清声细入鸣蛩翼。
天人戏剪苍龙髯，参差簇在瑶堦侧。
金精水鬼欺不得，长与东皇逞颜色。
劲节暂因君子移，贞心不为麻中直。','',''),('quantangshi-35715','大雪歌','李咸用','quantangshi','','卷36','同云惨惨如天怒，寒龙振鬣飞干雨。
玉圃花飘朵不匀，银河风急惊砂度。
谢客凭轩吟未住，望中顿失纵横路。
应是羲和倦晓昏，暂反元元归太素。','',''),('quantangshi-35716','塘上行','李咸用','quantangshi','','卷36','横塘日澹秋云隔，浪织轻飔罗幂幂。
红绡撇水荡舟人，画桡掺掺柔荑白。
鲤鱼虚掷无消息，花老莲疎愁未摘。
却把金钗打绿荷，懊恼露珠穿不得。','',''),('quantangshi-35717','寓意','李咸用','quantangshi','','卷36','直道荆棘生，斜径红尘起。
苍苍杳无言，麒麟回瑞趾。
东风如未来，飞雪终不已。','',''),('quantangshi-35718','剑喻','李咸用','quantangshi','','卷36','黯黯秋水寒，至刚非可缺。
风胡不出来，摄履人相蔑。
纵挺倚天形，谁是躬提挈。
愿将百炼身，助我王臣节。','',''),('quantangshi-35719','苍颉台','李咸用','quantangshi','','卷36','先贤忧民诈，观迹成纲纪。
自有书契来，争及结绳理。','',''),('quantangshi-35720','荆山','李咸用','quantangshi','','卷36','良工指君疑，真玉却非玉。
寄言怀宝人，不须伤手足。','',''),('quantangshi-35721','自君之出矣','李咸用','quantangshi','','卷36','自君之出矣，鸾镜空尘生。
思君如明月，明月逐君行。','',''),('quantangshi-35722','妾薄命','李咸用','quantangshi','','卷36','妾命何太薄，不及宫中水。
时时对天颜，声声入君耳。','',''),('quantangshi-35723','君子行','李咸用','quantangshi','','卷36','君子慎所履，小人多所疑。
尼甫至圣贤，犹为匡所縻。','',''),('quantangshi-35724','铜雀台','李咸用','quantangshi','','卷36','但见西陵惨明月，女妓无因更相悦。
有虞曾不有遗言，滴尽湘妃眼中血。','',''),('quantangshi-35725','倢伃怨','李咸用','quantangshi','','卷36','莫恃芙蓉开满面，更有身轻似飞燕。
不得团圆长近君，圭月鈋时泣秋扇。','',''),('quantangshi-35726','悲哉行','李咸用','quantangshi','','卷36','云色阴沈弄秋气，危叶高枝恨深翠。
用却春风力几多，微霜逼迫何容易。','',''),('quantangshi-35727','携手曲','李咸用','quantangshi','','卷36','携手春复春，未尝渐离别。
夭夭风前花，纤纤日中雪。
不敢怨于天，唯惊添岁月。
不敢怨于君，秪怕芳菲歇。
芳菲若长然，君恩应不绝。','',''),('quantangshi-35728','空城雀','李咸用','quantangshi','','卷36','啾啾空城雀，一啄数跳跃。
宁寻覆辙余，岂比巢危幕。
茫茫九万鹏，百雉且为乐。','',''),('quantangshi-35729','放歌行','李咸用','quantangshi','','卷36','蠢蠢荼蓼虫，薨薨避葵荠。
悠悠狷者心，寂寂厌清世。
如何不食甘，命合苦其噬。
如何不趣时，分合辱其体。
至哉先哲言，于物不凝滞。','',''),('quantangshi-35730','猛虎行','李咸用','quantangshi','','卷36','猛虎不怯敌，烈士无虚言。
怯敌辱其班，虚言负其恩。
爪牙欺白刃，果敢无前阵。
须知易水歌，至死无悔恡。','',''),('quantangshi-35731','陇头行','李咸用','quantangshi','','卷36','行人何旁徨，陇头水呜咽。
寒沙战鬼愁，白骨风霜切。
薄日曚昽秋，怨气阴云结。
杀成边将名，名着生灵灭。','',''),('quantangshi-35732','关山月','李咸用','quantangshi','','卷36','离离天际云，皎皎关山月。
羌笛一声来，白尽征人髪。
嘹唳孤鸿高，萧索悲风发。
雪压塞尘清，雕落沙场阔。
何当胡无人，荷戈朝凤阙。','',''),('quantangshi-35733','览友生古风','李咸用','quantangshi','','卷36','伯牙鸣玉琴，幽音随指发。
不是钟期听，俗耳安能别。
高山闲巍峩，流水声呜咽。
一卷冰雪言，清泠冷心骨。
分明古雅声，讽谕成凄切。
皴皵老松根，晃朗骊龙窟。
荆璞且深藏，瑉石方如雪。
金多丑女妍，木朽良工拙。
奸宄欺雷霆，魑魅嫌日月。
蝶迷桃李香，鲋惘江湖阔。
不寐孤灯前，舒卷忘饥渴。','',''),('quantangshi-35734','题友生丛竹','李咸用','quantangshi','','卷36','菊华寒露浓，兰愁晓霜重。
指佞不长生，蒲萐今无种。
安如植丛篁，他年待栖凤。
大则化龙骑，小可钓璜用。
留烟伴独醒，回阴冷闲梦。
何妨积雪凌，但为清风动。
乃知子猷心，不与常人共。','',''),('quantangshi-35735','石版','李咸用','quantangshi','','卷36','高人好自然，移得它山碧。
不磨如版平，大巧非因力。
古藓小青钱，尘中看野色。
冷倚砌花春，静伴疎篁直。
山僧若转头，如逢旧相识。','',''),('quantangshi-35736','江南曲','李咸用','quantangshi','','卷36','江南四月薰风低，江南女儿芳步齐。
晚云接水共渺弥，远沙曡草空萋萋。
白苎不堪论古意，数花犹可醉前溪。
孤舟有客归未得，乡梦欲成山鸟啼。','',''),('quantangshi-35737','临川逢陈百年','李咸用','quantangshi','','卷36','麻姑山下逢真士，玄肤碧眼方瞳子。
自言混沌凿不死，大笑老彭非久视。
强争龙虎是狂人，不保元和虚叩齿。
桃花雨过春光腻，劝我一杯灵液味。
教我无为礼乐拘，利路名场多忌讳。
不如含德反婴儿，金玉满堂真可贵。','',''),('quantangshi-35738','寄修睦上人','李咸用','quantangshi','','卷36','衣服田方无内客，一入庐云断消息。
应为山中胜概偏，惠持惠远多踪迹。
寻阳有个虚舟子，相忆由来无一事。
江边月色到岩前，此际心情必相似。
似不似，寄数字。','',''),('quantangshi-35739','读修睦上人歌篇','李咸用','quantangshi','','卷36','李白亡，李贺死。
陈陶赵睦寻相次，须知代不乏骚人。
贯休之后，惟修睦而已矣。
睦公睦公真可畏，开口向人无所忌。
才似烟霞生则媚，直如屈轶佞则指。
意下纷纷造化机，笔头滴滴文章髓。
明月清风三十年，被君驱使如奴婢。
劝君休，莫容易，世俗由来稀则贵。
珊瑚高架五云毫，小小不须烦藻思。','',''),('quantangshi-35740','远公亭牡丹','李咸用','quantangshi','','卷36','雁门禅客吟春亭，牡丹独逞花中英。
双成腻脸偎云屏，百般姿态因风生。
延年不敢歌倾城，朝云暮雨愁娉婷。
蘂繁蚁脚黏不行，甜迷蜂醉飞无声。
庐山根脚含精灵，发妍吐秀丛君庭。
湓江太守多闲情，栏朱绕绛留轻盈。
潺潺绿醴当风倾，平头奴子啾银笙。
红葩艳艳交童星，左文右武怜君荣，白铜鞮上慙清明。','',''),('quantangshi-35741','谢僧寄茶','李咸用','quantangshi','','卷36','空门少年初志坚，摘芳为药除睡眠。
匡山茗树朝阳偏，暖萌如爪拏飞鸢。
枝枝膏露凝滴圆，参差失向兜罗锦。
倾筐短甑蒸新鲜，白紵眼细匀于研。
甎排古砌春苔干，殷勤寄我清明前。
金槽无声飞碧烟，赤兽呵冰急铁喧。
林风夕和真珠泉，半匙清粉搅潺湲。
绿云轻绾湘娥鬟，尝来纵使重支枕，胡蝶寂寥空掩关。','',''),('quantangshi-35742','送人','李咸用','quantangshi','','卷36','少皥开宫行帝业，无刃金风剪红叶。
雁别边沙入暖云，蛩辞败草鸣香合。
有客为儒二十霜，酣歌郢雪时飘扬。
不甘长在诸生下，束书携劒离家乡。
利爪韝上鹰，雄文雾中豹。
可堪长与乌鸢噪，是宜摩碧汉以遐飞。
出南山而远蹈，况今大朝公道。
天子文明，团团月树悬青青。
燕中有马如龙行，不换黄金无骏名。
荆山有玉犹在璞，未遇良工虚掷鹊。
一壶清酒酌离情，休向嵩中随雀跃。','',''),('quantangshi-35743','古意论交','李咸用','quantangshi','','卷36','择友如淘金，沙尽不得宝。
结交如干银，产竭不成道。
我生四十年，相识苦草草。
多为势利朋，少有岁寒操。
通财能几何，闻善宁相告。
茫然同夜行，中路自不保。
常恐管鲍情，参差忽终老。
今来既见君，青天无片云。
语直瑟弦急，行高山桂芬。
约我为交友，不觉心醺醺。
见义必许死，临危当指囷。
无令后世士，重广孝标文。','',''),('quantangshi-35744','春风','李咸用','quantangshi','','卷36','青帝使和气，吹嘘万国中。
发生宁有异，先后自难同。
辇草不消力，岩花应费功。
年年三十骑，飘入玉蟾宫。','',''),('quantangshi-35745','自愧','李咸用','quantangshi','','卷36','多负悬弧礼，危时隐薜萝。
有心明俎豆，无力执干戈。
壮士难移节，贞松不改柯。
缨尘徒自满，欲濯待清波。','',''),('quantangshi-35746','夜吟','李咸用','quantangshi','','卷36','白兔轮当午，儒家业敢慵。
竹轩吟未已，锦帐梦应重。
落笔思成虎，悬梭待化龙。
景清神自爽，风逓远楼钟。','',''),('quantangshi-35747','昭君','李咸用','quantangshi','','卷36','古帝修文德，蛮夷莫敢侵。
不知桃李貌，能转虎狼心。
日暮边风急，程遥碛雪深。
千秋青冢骨，留怨在胡琴。','',''),('quantangshi-35748','秋夕','李咸用','quantangshi','','卷36','寥廓秋云薄，空庭月影微。
树寒栖鸟密，砌冷夜蛩稀。
晓鼓军容肃，疎钟客梦归。
吟余何所忆，圣主尚宵衣。','',''),('quantangshi-35749','秋日与友生言别','李咸用','quantangshi','','卷36','利名心未已，离别恨难休。
为个文儒业，致多岐路愁。
数花篱菊晚，片叶井梧秋。
又决出门计，一尊期少留。','',''),('quantangshi-35750','边城听角','李咸用','quantangshi','','卷36','戍楼鸣画角，寒露滴金枪。
细引云成阵，高催雁着行。
唤回边将梦，吹薄晓蟾光。
未遂终军志，何劳思故乡。','',''),('quantangshi-35751','秋日访同人','李咸用','quantangshi','','卷36','忽忆金兰友，携琴去自由。
远寻寒涧碧，深入乱山秋。
见后却无语，别来长独愁。
幸逢三五夕，露坐对冥搜。','',''),('quantangshi-35752','寄楚琼上人','李咸用','quantangshi','','卷36','遥知无事日，静对五峰秋。
鸟隔寒烟语，泉和夕照流。
凭栏疎磬尽，瞑目远云收。
几句出人意，风高白雪浮。','',''),('quantangshi-35753','游寺','李咸用','quantangshi','','卷36','无家身自在，时得到莲宫。
秋觉暑衣薄，老知尘世空。
幽情怜水石，野性任萍蓬。
是处堪闲坐，与僧行止同。','',''),('quantangshi-35754','春日','李咸用','quantangshi','','卷36','浩荡东风里，裴回无所亲。
危城三面水，古树一边春。
衰世难修道，花时不称贫。','',''),('quantangshi-35755','论交','李咸用','quantangshi','','卷36','行亏何必富，节在不妨贫。
易得笑言友，难逢终始人。
松篁贞管鲍，桃李艳张陈。
少见岁寒后，免为霜雪尘。','',''),('quantangshi-35756','秋兴','李咸用','quantangshi','','卷36','木叶乱飞尽，故人犹未还。
心虽游紫阙，时合在青山。
近寺僧邻静，临池鹤对闲。
兵戈如未息，名位莫相关。','',''),('quantangshi-35757','山居','李咸用','quantangshi','','卷36','草堂书一架，苔径竹千竿。
难世投谁是，清贫且自安。
邻居皆学稼，客至亦无官。
焦尾何人听，凉宵对月弹。','',''),('quantangshi-35758','遣兴','李咸用','quantangshi','','卷36','风细酒初醒，凭栏别有情。
蝉稀秋树瘦，雨尽晚云轻。
旅鬓一丝出，乡心寸火生。
子牟魂欲断，何日是升平。','',''),('quantangshi-35759','待旦','李咸用','quantangshi','','卷36','檐静燕雏语，窗虚蟾影过。
时情因客老，归梦入秋多。
蔽日羣山雾，滔天四海波。
吾皇思壮士，谁应大风歌。','',''),('quantangshi-35760','送从兄坤载','李咸用','quantangshi','','卷36','忍泪不敢下，恐兄情更伤。
别离当乱世，骨肉在他乡。
语尽意不尽，路长愁更长。
那堪回首处，残照满衣裳。','',''),('quantangshi-35761','惜别','李咸用','quantangshi','','卷36','细雨妆行色，霏霏入户来。
须知相识喜，却是别愁媒。
白刃方盈国，黄金不上台。','',''),('quantangshi-35762','早秋游山寺','李咸用','quantangshi','','卷36','闲卧云岩稳，攀缘笑戏猱。
静于诸境静，高却众山高。
至理无言了，浮生一梦劳。
清风朝复暮，四海自波涛。','',''),('quantangshi-35763','秋日疾中寄诸同志','李咸用','quantangshi','','卷36','闲居无胜事，公干卧来心。
门静秋风晚，人稀古巷深。
花疎篱菊色，叶减井梧阴。
赖有斯文在，时时得强寻。','',''),('quantangshi-35764','赠山僧','李咸用','quantangshi','','卷36','荣枯虽在目，名利不关身。
高出城隍寺，野为云鹤邻。
松声寒后远，潭色雨余新。
岂住空空里，空空亦是尘。','',''),('quantangshi-35765','宿隐者居','李咸用','quantangshi','','卷36','永日连清夜，因君识躁君。
竹扉难掩月，岩树易延云。
曙鸟枕前起，寒泉梦里闻。
又须随计吏，鸡鹤迥然分。','',''),('quantangshi-35766','送钱契明尊师归庐山','李咸用','quantangshi','','卷36','瘦倚青竹杖，炉峰指欲归。
霜黏行日屦，风暖到时衣。
凭槛云还在，攀松鹤不飞。
何曾有别恨，杨柳自依依。','',''),('quantangshi-35767','送进士刘松','李咸用','quantangshi','','卷36','滔滔皆鲁客，难得是心知。
到寺多同步，游山未失期。
云低春雨后，风细暮钟时。
忽别垂杨岸，遥遥望所之。','',''),('quantangshi-35768','赠任肃','李咸用','quantangshi','','卷36','玄髪难姑息，青云有路岐。
莫言多事日，虚掷少年时。
松色雪中出，人情难后知。
圣朝公道在，中鹄勿差池。','',''),('quantangshi-35769','题陈正字山居','李咸用','quantangshi','','卷36','怪来忘禄位，习学近潇湘。
见处云山好，吟中岁月长。
花光笼晚雨，树映浸寒塘。
几日凭栏望，归心自不忙。','',''),('quantangshi-35770','赠来进士鹏','李咸用','quantangshi','','卷36','语玄人不到，星汉在灵空。
若使无良遇，虚言有至公。
月明千峤雪，滩急五更风。
此际苦吟力，分将造化功。','',''),('quantangshi-35771','送曹税','李咸用','quantangshi','','卷36','掺袂向春风，何时约再逢。
若教相见密，肯恨别离重。
芳草渔家路，残阳水寺钟。
落帆当此处，吟兴不应慵。','',''),('quantangshi-35772','赠来鹏','李咸用','quantangshi','','卷36','默坐非关闷，凝情秪在诗。
庭闲花落后，山静月明时。
答客言多简，寻僧步稍迟。
既同和氏璧，终有玉人知。','',''),('quantangshi-35773','途中作','李咸用','quantangshi','','卷36','瘦马倦行役，斜阳劝着鞭。
野桥寒树亚，山店暮云连。
退鷁风虽急，攀龙志已坚。
路人休莫笑，百里有时贤。','',''),('quantangshi-35774','秋晚','李咸用','quantangshi','','卷36','斜阳山雨外，秋色思无穷。
柳叶飘干翠，枫枝撼碎红。
鬓毛看似雪，生计尚如蓬。
不及樵童乐，蒹葭一笛风。','',''),('quantangshi-35775','晓望','李咸用','quantangshi','','卷36','露惊松上鹤，晓色动扶桑。
碧浪催人老，红轮照物忙。
世情随日变，利路与天长。
好驾觥船去，陶陶入醉乡。','',''),('quantangshi-35776','寄友生','李咸用','quantangshi','','卷36','交情应不变，何事久离羣。
圆月思同步，寒泉忆共闻。
雪霜松色在，风雨雁行分。
每见人来说，窗前改旧文。','',''),('quantangshi-35777','江行','李咸用','quantangshi','','卷36','潇湘无事后，征棹复呕哑。
高岫留斜照，归鸿背落霞。
鱼残沙岸草，蝶寄洑流槎。
共说干戈苦，汀洲减钓家。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35778','题王氏山居','李咸用','quantangshi','','卷36','檐有烟岚色，地多松竹风。
自言离乱后，不到鼓鼙中。
径柳拂云绿，山樱带雪红。
南边青嶂下，时见采芝翁。','',''),('quantangshi-35779','送别','李咸用','quantangshi','','卷36','别意说难尽，离杯深莫辞。
长歌终此席，一笑又何时。
棹入寒潭急，帆当落照迟。
远书如不寄，无以慰相思。','',''),('quantangshi-35780','览文僧卷','李咸用','quantangshi','','卷36','虽无先圣耳，异代得闻昭。
怪石难为古，奇花不敢妖。
调高非郢雪，思静碍箕瓢。
未可重吟过，云山兴转饶。','',''),('quantangshi-35781','望仰山忆玄泰上人','李咸用','quantangshi','','卷36','晴岚凝片碧，知在此中禅。
见面定何日，无书已一年。
高秋关静梦，良夜入新篇。
仰德心如是，清风不我传。','',''),('quantangshi-35782','闻泉','李咸用','quantangshi','','卷36','淅淅梦初惊，幽窗枕簟清。
更无人共听，秪有月空明。
急想穿岩曲，低应过石平。
欲将琴强写，不是自然声。','',''),('quantangshi-35783','酬郑进士九江新居见寄','李咸用','quantangshi','','卷36','蹑屐扣柴关，因成尽日闲。
独听黄鸟语，深似白云间。
萍沼宽于井，莎城绿当山。
前期招我作，此景得吟还。','',''),('quantangshi-35784','九江和人赠陈生','李咸用','quantangshi','','卷36','天畏斯文坠，凭君助素风。
意深皆可补，句逸不因功。
暮替云愁远，秋惊月占空。
寄家当瀑布，时得笑言同。','',''),('quantangshi-35785','登楼值雨二首 一','李咸用','quantangshi','','卷36','共讶高楼望，匡庐色已空。
白云横野阔，遮岳与天同。
数点雨入酒，满襟香在风。
远江吟得出，方下郡斋东。','',''),('quantangshi-35786','登楼值雨二首 二','李咸用','quantangshi','','卷36','江徼多佳景，秋吟兴未穷。
送来松槛雨，半是蓼花风。
浪猛惊翘鹭，烟昏叫断鸿。
不知今夜客，几处卧鸣篷。','',''),('quantangshi-35787','送赵舒处士归庐山','李咸用','quantangshi','','卷36','归岫香炉碧，行吟步益迟。
诸侯师不得，樵客偶相随。
思旧江云断，谈玄岳月移。
秪应张野辈，异代作心知。','',''),('quantangshi-35788','僧院蔷薇','李咸用','quantangshi','','卷36','客引擎茶看，离披晒锦红。
不缘开净域，争忍负春风。
小片当吟落，清香入定空。
何人来此植，应固恼休公。','',''),('quantangshi-35789','友生携修睦上人诗见访','李咸用','quantangshi','','卷36','雪中敲竹户，袖出岳僧诗。
语尽景皆活，吟阑角独吹。
意如将俗背，业必少人知。
共约冰销日，云边访所思。','',''),('quantangshi-35790','冬夕喜友生至','李咸用','quantangshi','','卷36','天涯行欲遍，此夜故人情。
乡国别来久，干戈还未平。
灯残偏有焰，雪甚却无声。
多少新闻见，应须语到明。','',''),('quantangshi-35791','牡丹','李咸用','quantangshi','','卷36','少见南人识，识来嗟复惊。
始知春有色，不信尔无情。
恐是天地媚，暂随云雨生。
缘何绝尤物，更可比妍明。','',''),('quantangshi-35792','送春','李咸用','quantangshi','','卷36','四时为第一，一岁一重来。
好景应难胜，余花虚自开。
相思九个月，得信数枝梅。
不向东门送，还成负酒杯。','',''),('quantangshi-35793','送边将','李咸用','quantangshi','','卷36','天骄频犯塞，铁骑又征西。
臣节轻乡土，雄心生鼓鼙。
地寒花不艳，沙远日难低。
渐喜秋弓健，雕翻白草齐。','',''),('quantangshi-35794','春晴','李咸用','quantangshi','','卷36','檐滴春膏绝，凭栏晚吹生。
良朋在何处，高树忽流莺。
游寺期应定，寻芳步已轻。
新诗吟未稳，迟日又西倾。','',''),('quantangshi-35795','冬夜与修睦上人宿远公亭寄南岳玄泰禅师','李咸用','quantangshi','','卷36','丈室掩孤灯，更深霰雹增。
相看云梦客，共忆祝融僧。
语合茶忘味，吟欹卷有棱。
楚南山水秀，行止岂无凭。','',''),('quantangshi-35796','落花','李咸用','quantangshi','','卷36','拾得移时看，重思造化功。
如何飘丽景，不似遇春风。
满地余香在，繁枝一夜空。
秪应公子见，先忆坠楼红。','',''),('quantangshi-35797','寄嵩阳隐者','李咸用','quantangshi','','卷36','昔年江上别，初入乱离中。
我住匡山北，君之少室东。
信来经险道，诗半忆皇风。
何事犹高卧，岩边梦未通。','',''),('quantangshi-35798','早蝉','李咸用','quantangshi','','卷36','门柳不连野，乍闻为早蝉。
游人无定处，入耳更应先。
暂默斜阳雨，重吟远岸烟。
前年湘竹里，风激遶离筵。','',''),('quantangshi-35799','酬蕴微','李咸用','quantangshi','','卷36','白衣经乱世，相遇一开颜。
得句禅思外，论交野步间。
举朝无旧识，入眼秪青山。
几度斜阳寺，访君还独还。','',''),('quantangshi-35800','萱草','李咸用','quantangshi','','卷36','芳草比君子，诗人情有由。
秪应怜雅态，未必解忘忧。
积雨莎庭小，微风藓砌幽。
莫言开太晚，犹胜菊花秋。','',''),('quantangshi-35801','访友人不遇','李咸用','quantangshi','','卷36','出门无至友，动即到君家。
空掩一庭竹，去看何寺花。
短童应捧杖，稚女学擎茶。
吟罢留题处，苔阶日影斜。','',''),('quantangshi-35802','苔','李咸用','quantangshi','','卷36','几年风雨迹，曡在石孱颜。
生处景长静，看来情尽闲。
吟亭侵坏壁，药院掩空关。
每忆东行径，移筇独自还。','',''),('quantangshi-35803','红薇','李咸用','quantangshi','','卷36','春雨有五色，洒来花旋成。
欲留池上景，别染草中英。
画出看还欠，蓪为插未轻。
王孙多好事，携酒寄吟倾。','',''),('quantangshi-35804','别所知','李咸用','quantangshi','','卷36','有路有西东，天涯自恨同。
却须深酌酒，况不比飘蓬。
帆冒新秋雨，鼓传微浪风。
闰牵寒气早，何浦值宾鸿。','',''),('quantangshi-35805','小雪','李咸用','quantangshi','','卷36','散漫阴风里，天涯不可收。
压松犹未得，扑石暂能留。
阁静萦吟思，途长拂旅愁。
崆峒山北面，早想玉成丘。','',''),('quantangshi-35806','和修睦上人听猿','李咸用','quantangshi','','卷36','禅客闻犹苦，是声应是啼。
自然无稳梦，何必到巴溪。
疎雨洒不歇，回风吹暂低。
此宵秋欲半，山在二林西。','',''),('quantangshi-35807','庭竹','李咸用','quantangshi','','卷36','嫩绿与老碧，森然庭砌中。
坐销三伏景，吟起数竿风。
叶影重还密，梢声远或通。
更期春共看，桃映小花红。','',''),('quantangshi-35808','早行','李咸用','quantangshi','','卷36','家国三千里，中宵算去程。
困才成蝶梦，行不待鸡鸣。
马首摇残月，鸦羣起古城。
发来经几堠，村寺远钟声。','',''),('quantangshi-35809','哭所知','李咸用','quantangshi','','卷36','朝作青云士，暮为玄夜人。
风灯无定度，露薤亦逡巡。
乘马惊新冢，书帷摆旧尘。
秪应从此去，何处福生民。','',''),('quantangshi-35810','分题雪霁望炉峰','李咸用','quantangshi','','卷36','雪霁上庭除，炉峰势转孤。
略无烟作带，独有影沈湖。
冷触归鸿急，明凝落照俱。
□□□□□，□□□□□。','',''),('quantangshi-35811','雪十二韵','李咸用','quantangshi','','卷36','六出凝阴气，同云指上天。
结时风乍急，集处霰长先。
草穗翘祥燕，陂桩吐白莲。
犬狂南陌上，竹醉小池前。
樵径花黏履，渔舟玉帖舷。
阵经阳谷薄，势想朔方偏。
楼面光摇锡，篱头晓列钱。
石苔青鹿卧，殿网素蛾穿。
嘶马应思塞，蹲乌似为燕。
童痴为兽揑，僧爱用茶煎。
念物希周穆，含毫愧惠连。
吟阑余兴逸，还忆剡溪船。','',''),('quantangshi-35812','庐山','李咸用','quantangshi','','卷36','非岳不言岳，此山通岳言。
高人居乱世，几处满前轩。
秀作神仙宅，灵为风雨根。
余阴铺楚甸，一柱表吴门。
静得八公侣，雄临九子尊。
对犹青熨眼，到必冷凝魂。
势受重湖让，形难七泽吞。
黑岩藏昼电，紫雾泛朝暾。
莲堕宁唯华，玉焚堪小昆。
倒松微发罅，飞瀑远成痕。
曡见云容衬，棱收雪气昏。
裁诗曾困谢，作赋偶无孙。
流碍星光撇，惊冲雁阵翻。
峰奇寒倚剑，泉曲旋如盆。
草短分雏雉，林明露掷猿。
秋枫红叶散，春石谷雷奔。
月好虎溪路，烟深栗里源。
醉吟长易醒，梦去亦销烦。
有觉南方重，无疑厚地掀。
轻扬闻旧俗，端用镇元元。','',''),('quantangshi-35813','和吴处士题村叟壁','李咸用','quantangshi','','卷36','因阅乡居景，归心寸火然。
吾家依碧嶂，小槛枕清川。
远雨笼孤戍，斜阳隔断烟。
沙虚遗虎迹，水洑聚蛟涎。
粝麴芟汀蓼，甘茶挈石泉。
霜朝巡栗树，风夜探渔船。
戏日鱼呈腹，翘滩鹭并肩。
碁寻盘石净，酒傍野花妍。
器以锄为利，家惟竹直钱。
饭香同豆熟，汤暖摘松煎。
睡岛凫藏足，攀藤狖冻拳。
浅茅鸣鬬雉，曲枿啸寒鸢。
秋果𣙁梨涩，晨羞笋蕨鲜。
衣蓑留冷阁，席草种闲田。
椎髻担哺饷，庞眉识稔年。
吓鹰刍戴笠，驱犊筱充鞭。
不重官于社，常尊食作天。
谷深青霭蔽，峰迥白云缠。
每忆关魂梦，长夸表爱怜。
览君书壁句，诱我率成篇。','',''),('quantangshi-35814','谢友生遗端溪砚瓦','李咸用','quantangshi','','卷36','寻常濡翰次，恨不到端溪。
得自新知己，如逢旧解携。
翫余轻照乘，谢欲等悬黎。
静对胜凡客，闲窥忆好题。
娲天补剩石，昆剑切来泥。
着指痕犹湿，停旬水未低。
呵云润柱础，笔彩饮虹霓。
鹆眼工谙谬，羊肝士乍刲。
连澌光比镜，囚墨腻于䃜。
书信成池黑，吟须到日西。
正夸忧盗窃，将隐怯攀跻。
捧受同交印，矜持过秉圭。
草颠终近旭，嬾癖必无嵇。
用合缘鹦鹉，珍应负会稽。
贞姿还落落，寒韵或凄凄。
风月情相半，烟花思岂迷。
宜从方袋挈，枉把短行批。
浅小金为斗，泓澄玉作堤。
遇人依我惜，想尔与天齐。
□□□□□，行时秪独赍。','',''),('quantangshi-35815','和殷衙推春霖即事','李咸用','quantangshi','','卷36','东风吹暖雨，润下不能休。
古道云横白，移时客共愁。
绿沈莎似藻，红泛叶为舟。
忽起江湖兴，疑邻畎浍流。
此时无胜会，何处滞奇游？
阵急如酣战，点麤成乱沤。
竹因添洒落，松得长飕飗。
花惨闲庭晚，兰深曲径幽。
丝牵汀鸟足，线挂岳猿头。
天地昏同醉，寰区浩欲浮。
柳眉低带泣，蒲剑锐初抽。
石燕飜空重，虫罗缀滴稠。
荷倾蛟泪尽，岩拆电鞭收。
岂直望尧喜，却怀微禹忧。
树滋堪采菌，矶没懒垂鈎。
腥觉闻龙气，寒宜拥豹裘。
名膏那作沴，思稔必通侯。
蚌鹬徒喧竞，笙歌罢献酬。
山川藏秀媚，草木逞调柔。
极目非吾意，行吟独下楼。','',''),('quantangshi-35816','题陈将军别墅','李咸用','quantangshi','','卷36','明王猎士犹疎在，岩谷安居最有才。
高虎壮言知鬼伏，葛龙闲卧待时来。
云藏山色晴还媚，风约溪声静又回。
不独春光堪醉客，庭除长见好花开。','',''),('quantangshi-35817','湘浦有怀','李咸用','quantangshi','','卷36','鸿雁哀哀背朔方，余霞倒影画潇湘。
长汀细草愁春浪，古渡寒花倚夕阳。
鬼树夜分千炬火，渔舟朝巷一蓬霜。
侬家本是持竿者，为爱明时入帝乡。','',''),('quantangshi-35818','题陈处士山居','李咸用','quantangshi','','卷36','莲遶闲停柳遶池，蝉吟暮色一枝枝。
未逢皇泽搜遗逸，赢得青山避乱离。
花圃春风邀客醉，茅檐秋雨对僧碁。
樵童牧竖劳相问，岩穴从来出帝师。','',''),('quantangshi-35819','和蒋进士秋日','李咸用','quantangshi','','卷36','晚雨霏微思杪秋，不堪才子尚羇游。
尘随别骑东西急，波促年华日夜流。
凉月云开光自远，古松风在韵难休。
男儿但得功名立，纵是深恩亦易酬。','',''),('quantangshi-35820','陈正字山居','李咸用','quantangshi','','卷36','一叶闲飞斜照里，江南仲蔚在蓬蒿。
天衢云险驽骀蹇，月桂风和梦想劳。
遶枕泉声秋雨细，对门山色古屏高。
此中即是神仙地，引手何妨一钓鳌。','',''),('quantangshi-35821','与刘三礼陈孝廉言志','李咸用','quantangshi','','卷36','真宰无私造化均，年年分散月中春。
皆期早蹑青云路，谁肯长为白社人。
宋国高风休敛翼，圣朝公道易酬身。
大须审固穿杨箭，莫遣参差鬓雪新。','',''),('quantangshi-35822','秋日送严湘侍御归京','李咸用','quantangshi','','卷36','蟾影圭圆湖始波，楚人相别恨偏多。
知君有路升霄汉，独我无由出薜萝。
虽道危时难进取，到逢清世又如何。
谁听甯戚敲牛角，月落星稀一曲歌。','',''),('quantangshi-35823','题王处士山居','李咸用','quantangshi','','卷36','云木沈沈夏亦寒，此中幽隐几经年。
无多别业供王税，大半生涯在钓船。
蜀魄呌回芳草色，鹭鸶飞破夕阳烟。
干戈猬起能高卧，只个逍遥是谪仙。','',''),('quantangshi-35824','谢所知','李咸用','quantangshi','','卷36','狂歌狂舞慰风尘，心下多端亦嬾言。
早是乱离轻岁月，谁能愁悴过朝昏。
圣朝公道如长在，贱子谋身自有门。
却愧此时叨厚遇，他年何以报深恩。','',''),('quantangshi-35825','秋望','李咸用','quantangshi','','卷36','云阴惨澹柳阴稀，游子天涯一望时。
风闪雁行疎又密，地回江势急还迟。
荣枯物理终难测，贵贱人生自不知。
未达谁能多叹息，尘埃争损得男儿。','',''),('quantangshi-35826','送谭孝廉赴举','李咸用','quantangshi','','卷36','鼓鼙声里寻诗礼，戈戟林间入镐京。
好事尽从难处得，少年无向易中轻。
也知贵贱皆前定，未见疎慵遂有成。
吾道近来稀后进，善开金口答公卿。','',''),('quantangshi-35827','途中逢友人','李咸用','quantangshi','','卷36','大道将穷阮籍哀，红尘深翳步迟回。
皇天有意自寒暑，白日无情空往来。
霄汉何年征赋客，烟花随处作愁媒。
相逢且快眼前事，莫厌狂歌酒百杯。','',''),('quantangshi-35828','和人湘中作','李咸用','quantangshi','','卷36','湘川湘岸两荒凉，孤雁号空动旅肠。
一棹寒波思范蠡，满尊醇酒忆陶唐。
年华蒲柳凋衰鬓，身迹萍蓬滞别乡。
不及东流趋广汉，臣心日夜与天长。','',''),('quantangshi-35829','赠陈望尧','李咸用','quantangshi','','卷36','若说精通事艺长，词人争及孝廉郎。
秋萤短焰难盈案，邻烛余光不满行。
鹄箭亲疎虽异的，桂花高下一般香。
明时公道还堪信，莫遣锥锋久在囊。','',''),('quantangshi-35830','宿渔家','李咸用','quantangshi','','卷36','促杼声繁萤影多，江边秋兴独难过。
云遮月桂几枝恨，烟罩渔舟一曲歌。
难世斯人虽隐遁，明时公道复如何。
陶家壁上精灵物，风雨未来终是梭。','',''),('quantangshi-35831','旅馆秋夕','李咸用','quantangshi','','卷36','牢落生涯在水乡，只思归去泛沧浪。
秋风萤影随高柳，夜雨蛬声上短墙。
百岁易为成荏苒，丹霄谁肯借梯航。
若教名路无知己，匹马尘中是自忙。','',''),('quantangshi-35832','悼范摅处士','李咸用','quantangshi','','卷36','家在五云溪畔住，身游巫峡作闲人。
安车未至柴关外，片玉已藏坟土新。
虽有公卿闻姓字，惜无知己脱风尘。
到头积善成何事，天地茫茫秋又春。','',''),('quantangshi-35833','送人','李咸用','quantangshi','','卷36','一轴烟花满口香，诸侯相见肯相忘。
未闻圭璧为人弃，莫倦江山去路长。
盈耳暮蝉催别骑，数杯浮蚁咽离肠。
眼前多少难甘事，自古男儿当自强。','',''),('quantangshi-35834','春暮途中','李咸用','quantangshi','','卷36','细雨如尘散暖空，数峰春色在云中。
须知触目皆成恨，纵道多文争那穷。
飞燕有情依旧阁，垂杨无力受东风。
谁能会得干坤意，九土枯荣自不同。','',''),('quantangshi-35835','题陈正字林亭','李咸用','quantangshi','','卷36','晓烟轻翠拂帘飞，黄叶飘零弄所思。
正是低摧吾道日，不堪惆怅异乡时。
家林蛇豕方羣起，宫沼龟龙未有期。
赖有平原怜贱子，满亭山色借吟诗。','',''),('quantangshi-35836','送从兄入京','李咸用','quantangshi','','卷36','柳转春心梅艳香，相看江上恨何长。
多情流水引归思，无赖严风促别觞。
大抵男儿须振奋，近来时事懒思量。
云帆高挂一挥手，目送烟霄雁断行。','',''),('quantangshi-35837','秋夕书怀寄所知','李咸用','quantangshi','','卷36','秋萤一点雨中飞，独立黄昏思所知。
三岛路遥身汩没，九天风急羽差池。
年华逐浪催霜髪，旅恨和云拂桂知。
不向故人言此事，异乡谁更念栖迟。','',''),('quantangshi-35838','酬进士秦颙若','李咸用','quantangshi','','卷36','莺默平林燕别轩，相逢相笑话生前。
低飞旅恨看霜叶，曲写归情向暮川。
在野孤云终捧日，朝宗高浪本蒙泉。
何劳怅望风雷便，且混鱼龙黩武年。','',''),('quantangshi-35839','山中夜坐寄故里友生','李咸用','quantangshi','','卷36','展转檐前睡不成，一牀山月竹风清。
虫声促促催乡梦，桂影高高挂旅情。
祸福既能知倚伏，行藏争不要分明。
可怜任永真坚白，净洗双眸看太平。','',''),('quantangshi-35840','物情','李咸用','quantangshi','','卷36','谁分万类二仪间，禀性高卑各自然。
野鹤不栖葱蒨树，流莺长喜艳阳天。
李斯溷鼠心应动，庄叟泥龟意已坚。','',''),('quantangshi-35841','金谷园','李咸用','quantangshi','','卷36','石家旧地聊登望，宠辱从兹信可惊。
鸟度野花迷锦障，蝉吟古树想歌声。
虽将玉貌同时死，却羡苍头此日生。
多积黄金买刑戮，千秋成得绿珠名。','',''),('quantangshi-35842','投所知','李咸用','quantangshi','','卷36','手欠东堂桂一枝，家书不敢便言归。
挂檐晚雨思山阁，拂岸烟岚忆钓矶。
公道甚平才自薄，丹霄好上力犹微。
谁能借与抟扶势，万里飘飘试一飞。','',''),('quantangshi-35843','赠友弟','李咸用','quantangshi','','卷36','萤焰烧心雪眼劳，未逢佳梦见三刀。
他时讵有盐梅味，今日犹疑腹背毛。
金埒晓羇千里骏，玉轮寒养一枝高。
谁能终岁摇頳尾，唯唯洋洋向碧涛。','',''),('quantangshi-35844','春日喜逢乡人刘松','李咸用','quantangshi','','卷36','故人不见五春风，异地相逢岳影中。
旧业久抛耕钓侣，新闻多说战争功。
生民有恨将谁诉，花木无情秪自红。
莫把少年愁过日，一尊须对夕阳空。','',''),('quantangshi-35845','夏日别余秀才','李咸用','quantangshi','','卷36','岳麓云深麦雨秋，满倾杯酒对湘流。
沙边细柳牵行色，水面轻烟画别愁。
敢待傅岩成好梦，任从磻石挂纤鈎。
镜机冲漠非吾事，自要青云识五侯。','',''),('quantangshi-35846','庐陵九日','李咸用','quantangshi','','卷36','菊花山在碧江东，冷酒清吟兴莫穷。
四十三年秋里过，几多般事乱来空。
虽惊故国音书绝，犹喜新知语笑同。
竟日开门无客至，笛声迢逓夕阳中。','',''),('quantangshi-35847','和人游东林','李咸用','quantangshi','','卷36','一从张野卧云林，胜概谁人更解寻。
黄鸟不能言往事，白莲虚发至如今。
年年上国荣华梦，世世高流水石心。
始欲共君重怅望，紫霄峰外日沈沈。','',''),('quantangshi-35848','和彭进士秋日游靖居山寺','李咸用','quantangshi','','卷36','秋山入望已无尘，况得闲游谢事频。
问着尽能言祖祖，见时应不是真真。
添瓶野水遮还急，伴塔幽花落又新。
自笑未曾同逸步，终非宗炳社中人。','',''),('quantangshi-35849','和彭进士感怀','李咸用','quantangshi','','卷36','人生谁肯便甘休，遇酒逢花且共游。
若向云衢陪骥尾，直须天畔落旄头。
三编大雅曾关兴，一册南华旋解忧。
四海英雄多独断，不知何者是长筹。','',''),('quantangshi-35850','寄题从兄坤载村居','李咸用','quantangshi','','卷36','邻并无非樵钓者，庄生物论宛然齐。
雨中寒树愁鸱立，江上残阳瘦马嘶。
说与众佣同版筑，吕将羣叟共磻溪。
覆巢破卵方堪惧，取次梧桐凤且栖。','',''),('quantangshi-35851','送黄宾于赴举','李咸用','quantangshi','','卷36','秋风昨夜满潇湘，衰柳残蝉思客肠。
早是乱来无胜事，更堪江上揖离觞。
澄潭跃鲤摇轻浪，落日飞凫趁远樯。
渔父不须探去意，一枝春褭月中央。','',''),('quantangshi-35852','冬日喜逢吴价','李咸用','quantangshi','','卷36','垂杨烟薄井梧空，千里游人驻断蓬。
志意不因多事改，鬓毛难与别时同。
莺迁犹待销冰日，鹏起还思动海风。
穷达他年如赋命，且陶真性一杯中。','',''),('quantangshi-35853','题刘处士居','李咸用','quantangshi','','卷36','压破岚光半亩余，竹轩兰砌共清虚。
泉经小槛声长急，月过修篁影旋疎。
溪鸟时时窥户牖，山云往往宿庭除。
干戈谩道因天意，渭水高人自钓鱼。','',''),('quantangshi-35854','送李尊师归临川','李咸用','quantangshi','','卷36','蟠桃一别几千春，谪下人间作至人。
尘外烟霞吟不尽，鼎中龙虎伏初驯。
除存紫府无他意，终向青冥举此身。
辞我麻姑山畔去，蔡经踪迹必相亲。','',''),('quantangshi-35855','投知','李咸用','quantangshi','','卷36','西望长安路几千，迟回不为别家难。
酌量才地心虽动，点检囊装意又阑。
自是远人多蹇滞，近来仙牓半孤寒。
嘶风重诉牵盐耻，伯乐何妨转眼看。','',''),('quantangshi-35856','吴处士寄香兼劝入道','李咸用','quantangshi','','卷36','谢寄精专一捻香，劝予朝礼仕虚皇。
须知十极皆臣妾，岂止遗生奉混茫。
空挂黄衣宁续寿，曾闻玄教在知常。
但居平易俟天命，便是长生不死乡。','',''),('quantangshi-35857','草虫','李咸用','quantangshi','','卷36','如缲如织暮㗀㗀，应节催年使我愁。
行客语停孤店月，高人梦断一牀秋。
风低藓径疑偏急，雨咽槐亭得暂休。
须付画堂兰烛畔，歌怀醉耳两悠悠。','',''),('quantangshi-35858','咏柳','李咸用','quantangshi','','卷36','日近烟饶还有意，东垣西掖几千株。
牵仍别恨知难尽，夸炫春光恐更无。
解引人情长婉约，巧随风势强盘纡。
天应绣出繁华景，处处茸丝惹路衢。','',''),('quantangshi-35859','寄所知','李咸用','quantangshi','','卷36','曾将俎豆为儿戏，争奈干戈阻素心。
遁去不同秦客逐，病来还作越人吟。
名流古集典衣买，僻寺奇花贳酒寻。
从道趣时身计拙，如非所好肯开襟。','',''),('quantangshi-35860','雪','李咸用','quantangshi','','卷36','上帝无私意甚微，欲教霖雨更光辉。
也知出处花相似，可到贫家影便稀。
云汉风多银浪溅，昆山火后玉灰飞。
高楼四望吟魂敛，却忆明皇月殿归。','',''),('quantangshi-35861','绯桃花','李咸用','quantangshi','','卷36','茫茫天意为谁留，深染夭桃备胜游。
未醉已知醒后忆，欲开先为落时愁。
痴蛾乱扑灯难灭，跃鲤傍惊电不收。
何事梨花空似雪，也称春色是悠悠。','',''),('quantangshi-35862','同友人秋日登庾楼','李咸用','quantangshi','','卷36','兰摧菊暗不胜秋，倚着高楼思莫收。
六代风光无问处，九条烟水但凝愁。
谁能百岁长闲去，秪个孤帆岂自由。
欲学仲宣知是否，臂弓腰剑逐时流。','',''),('quantangshi-35863','和人咏雪','李咸用','quantangshi','','卷36','轻轻玉叠向风加，襟袖谁能认六葩。
高岫人迷千尺布，平林天与一般花。
横空络绎云遗屑，扑浪翩联蝶寄槎。','',''),('quantangshi-35864','和友人喜相遇十首 一','李咸用','quantangshi','','卷36','为儒自愧已多年，文赋歌诗路不专。
肯信披沙难见宝，只怜苫草易成编。
燕昭寤寐常求骏，郭隗寻思未是贤。
且固初心希一试，箭穿正鹄岂无缘。','',''),('quantangshi-35865','和友人喜相遇十首 二','李咸用','quantangshi','','卷36','揣情摩意已无功，只把篇章助国风。
宋玉谩夸云雨会，谢连宁许梦魂通。
愁成旅鬓千丝乱，吟得寒缸短焰终。
难世好居郊野地，出门常喜与人同。','',''),('quantangshi-35866','和友人喜相遇十首 三','李咸用','quantangshi','','卷36','惠子休惊学五车，沛公方起斩长蛇。
六雄互欲吞诸国，四海终须作一家。
自古经纶成世务，暂时朱绿比朝霞。
人生心口宜相副，莫使尧阶草势斜。','',''),('quantangshi-35867','和友人喜相遇十首 四','李咸用','quantangshi','','卷36','不傍江烟访所思，更应无处展愁眉。
数杯竹阁花残酒，一局松窗日午碁。
多病却疑天与便，自愚潜喜众相欺。
非穷非达非高尚，冷笑行藏秪独知。','',''),('quantangshi-35868','和友人喜相遇十首 五','李咸用','quantangshi','','卷36','闲吟闲坐道相应，远想南华亦自矜。
抛掷家乡轻似梦，寻常心地冷于僧。
和羹使用非胥靡，忆鲙言词小季鹰。
唯仗十篇金玉韵，此中高旨莫阶升。','',''),('quantangshi-35869','和友人喜相遇十首 六','李咸用','quantangshi','','卷36','已向丘门老此躯，可堪空作小人儒。
吟中景象千般有，书外囊装一物无。
润屋必能知早散，辉山应是不轻沽。
短衣宁倦重修谒，谁识高阳旧酒徒。','',''),('quantangshi-35870','和友人喜相遇十首 七','李咸用','quantangshi','','卷36','松桂寒多众木分，轻浮如叶自纷纭。
韶咸古曲教谁爱，山水清音喜独闻。
上国共知传大宝，旧交宁复在青云。
相逢莫厌杯中酒，同醉同醒秪有君。','',''),('quantangshi-35871','和友人喜相遇十首 八','李咸用','quantangshi','','卷36','还淳反朴已难期，依德依仁敢暂违。
寡欲自应刚正立，无私翻觉友朋稀。
旄头影莫侵黄道，傅说星终近紫微。
年纪少他蘧伯玉，幸因多难早知非。','',''),('quantangshi-35872','和友人喜相遇十首 九','李咸用','quantangshi','','卷36','麻衣未识帝城尘，四十为儒是病身。
有恨不关衔国耻，无愁直为倚家贫。
齐轻东海二高士，汉重商山四老人。
一种爱闲闲不得，混时行止却应真。','',''),('quantangshi-35873','和友人喜相遇十首 十','李咸用','quantangshi','','卷36','任说天长海影沈，友朋情比未为深。
唯应乐处无虚日，大半危时得道心。
命达夭殇同白首，价高甎瓦即黄金。
他年有要玄珠者，赤水萦纡试一寻。','',''),('quantangshi-35874','依韵修睦上人山居十首 一','李咸用','quantangshi','','卷36','生身便在乱离间，遇柳寻花作麽看。
老去转谙无是事，本来何处有多般。
长怜蠛蠓能随暖，独笑梧桐不耐寒。
覆载我徒争会得，大鹏飞尚未知宽。','',''),('quantangshi-35875','依韵修睦上人山居十首 二','李咸用','quantangshi','','卷36','云泉日日长松寺，丝管年年细柳营。
静躁殊途知自识，荣枯一贯亦何争。
道傍病树人从老，溪上新苔我独行。
若见净名居士语，逍遥全不让庄生。','',''),('quantangshi-35876','依韵修睦上人山居十首 三','李咸用','quantangshi','','卷36','莫言天道终难定，须信人心尽自轻。
宣室三千虽有恨，成周八百岂无情。
栢缘执性长时瘦，梅为多知两番生。
不是不同明主意，嬾将唇舌与齐烹。','',''),('quantangshi-35877','依韵修睦上人山居十首 四','李咸用','quantangshi','','卷36','不论轩冕及渔樵，性与情违渐渐遥。
季子祸从怜富贵，颜生道在乐箪瓢。
清闲自可齐三寿，忿恨还须戒一朝。
好学尧民偎舜日，短裁孤竹理云韶。','',''),('quantangshi-35878','依韵修睦上人山居十首 五','李咸用','quantangshi','','卷36','春风春雨一何频，望极空江觉损神。
莺有来由重入谷，柳无情绪强依人。
汉庭谒者休言事，鲁国诸生莫问津。
赖是水乡樗栎贱，满炉红焰且相亲。','',''),('quantangshi-35879','依韵修睦上人山居十首 六','李咸用','quantangshi','','卷36','三十年来要自观，履春冰恐未为难。
自于南国同埋剑，谁向东门便挂冠。
早是人情飞絮薄，可堪时令太行寒。
多慙幸住匡山下，偷得穠岚坐卧看。','',''),('quantangshi-35880','依韵修睦上人山居十首 七','李咸用','quantangshi','','卷36','畹兰未必因香折，湖象多应为齿焚。
兼济直饶同巨楫，自由何似学孤云。
秋深栎菌樵来得，木末山鼯梦断闻。
闲凭竹轩游子过，替他愁见日西曛。','',''),('quantangshi-35881','依韵修睦上人山居十首 八','李咸用','quantangshi','','卷36','何事深山啸复歌，短弓长剑不如他。
且图青史垂名稳，从道前贤自滞多。
𩿪鷃敢辞栖短棘，凤凰犹解怯高罗。
人生若得逢尧舜，便是巢由亦易过。','',''),('quantangshi-35882','依韵修睦上人山居十首 九','李咸用','quantangshi','','卷36','太玄太易小窗明，古义寻来醉复醒。
西伯纵逢头已白，步兵如在眼应青。
寒猿断后云为槛，宿鸟惊时月满庭。
此景得闲闲去得，人间无事不曾经。','',''),('quantangshi-35883','依韵修睦上人山居十首 十','李咸用','quantangshi','','卷36','壮气虽同德不同，项王何似王江东。
乡歌寂寂荒丘月，渔艇年年古渡风。
难世斯人犹不达，此时吾道岂能通。
吟君十首山中作，方觉多端总是空。','',''),('quantangshi-35884','同友生春夜闻雨','李咸用','quantangshi','','卷36','春雨三更洗物华，乱和丝竹响豪家。
滴繁知在长条柳，点重愁看破朵花。
檐静尚疑兼雾细，灯摇应是逐风斜。
此时童叟浑无梦，为喜流膏润谷芽。','',''),('quantangshi-35885','同友生题僧院杜鹃花','李咸用','quantangshi','','卷36','若比众芳应有在，难同上品是中春。
牡丹为性疎南国，朱槿操心不满旬。
留得却缘真达者，见来宁作独醒人。
鹤林太盛今空地，莫放枝条出四邻。','',''),('quantangshi-35886','春日题陈正字林亭','李咸用','quantangshi','','卷36','周回胜异似仙乡，稍减愁人日月长。
幕绕虚檐高岫色，镜临危槛小池光。
丝垂杨柳当风软，玉折含桃倚径香。
南北近来多少事，数声横笛怨斜阳。','',''),('quantangshi-35887','送河南韦主簿归京','李咸用','quantangshi','','卷36','岩风爱日泪阑干，去住情途各万端。
世乱敢言离别易，时清犹道路行难。
舟维晚雨湘川暗，袖拂晴岚岘首寒。
见说满朝亲友在，肯教憔悴出长安。','',''),('quantangshi-35888','喻道','李咸用','quantangshi','','卷36','汉武秦皇漫苦辛，那思俗骨本含真。
不知流水潜催老，未悟三山也是尘。
牢落沙丘终古恨，寂寥函谷万年春。
长生客待仙桃饵，月里婵娟笑煞人。','',''),('quantangshi-35889','山中','李咸用','quantangshi','','卷36','一簇烟霞荣辱外，秋山留得傍檐楹。
朝钟暮鼓不到耳，明月孤云长挂情。
世上路岐何缭绕，水边蓑笠称平生。
寻思阮籍当时意，岂是途穷泣利名。','',''),('quantangshi-35890','同玄昶上人观山榴','李咸用','quantangshi','','卷36','病随支遁偶行行，正见榴花独满庭。
瘦竹成林人不看，却应着得强青青。','',''),('quantangshi-35891','别李将军','李咸用','quantangshi','','卷36','一拜虬髭便受恩，宫门细柳五摇春。
男儿自古多离别，嬾对英雄泪满巾。','',''),('quantangshi-35892','早鸡','李咸用','quantangshi','','卷36','锦翅朱冠惊四邻，稻粱恩重职司晨。
不知下土兵难戢，但报明时向国人。','',''),('quantangshi-35893','别友','李咸用','quantangshi','','卷36','北吹微微动旅情，不堪分手在平明。
寒鸡不待东方曙，唤起征人蹋月行。','',''),('quantangshi-35894','草檄答南蛮有咏','胡曾','quantangshi','','卷36','辞天出塞阵云空，雾卷霞开万里通。
亲受虎符安宇宙，誓将龙剑定英雄。
残霜敢冒高悬日，秋叶争禁大段风。
为报南蛮须屏迹，不同蜀将武侯功。','',''),('quantangshi-35895','寒食都门作','胡曾','quantangshi','','卷36','二年寒食住京华，寓目春风万万家。
金络马衔原上草，玉颜人折路傍花。
轩车竞出红尘合，冠盖争回白日斜。
谁念都门两行泪，故园寥落在长沙。','',''),('quantangshi-35896','薄命妾','胡曾','quantangshi','','卷36','阿娇初失汉皇恩，旧赐罗衣亦罢薰。
倚枕夜悲金屋雨，卷帘朝泣玉楼云。
宫前叶落鸳鸯瓦，架上尘生翡翠裙。
龙骑不巡时渐久，长门空掩绿苔纹。','',''),('quantangshi-35897','独不见','胡曾','quantangshi','','卷36','玉关一自有氛埃，年少从军竟未回。
门外尘凝张乐榭，水边香灭按歌台。
窗残夜月人何处，帘卷春风燕复来。
万里寂寥音信绝，寸心争忍不成灰。','',''),('quantangshi-35898','交河塞下曲','胡曾','quantangshi','','卷36','交河冰薄日迟迟，汉将思家感别离。
塞北草生苏武泣，陇西云起李陵悲。
晓侵雉堞乌先觉，春入关山雁独知。
何处疲兵心最苦，夕阳楼上笛声时。','',''),('quantangshi-35899','车遥遥','胡曾','quantangshi','','卷36','自从车马出门朝，便入空房守寂寥。
玉枕夜残鱼信绝，金钿秋尽雁书遥。
脸边楚雨临风落，头上春云向日销。
芳草又衰还不至，碧天霜冷转无憀。','',''),('quantangshi-35900','早发潜水驿谒郎中员外','胡曾','quantangshi','','卷36','半床秋月一声鸡，万里行人费马蹄。
青野雾销凝晋洞，碧山烟散避秦溪。
楼台稍辨乌城外，更漏微闻鹤柱西。
已是大仙怜后进，不应来向武陵迷。','',''),('quantangshi-35901','赠渔者','胡曾','quantangshi','','卷36','不愧人间万户侯，子孙相继老扁舟。
往来南越谙鲛室，生长东吴识蜃楼。
自为钓竿能遣闷，不因萱草解销忧。
羡君独得逃名趣，身外无机任白头。','',''),('quantangshi-35902','自岭下泛鷁到清远峡作','胡曾','quantangshi','','卷36','乘船浮鷁下韶水，绝境方知在岭南。
薜荔雨余山自黛，蒹葭烟尽岛如蓝。
旦游萧帝新松寺，夜宿嫦娥桂影潭。
不为箧中书未献，便来兹地结茅庵。','',''),('quantangshi-35903','题周瑜将军庙','胡曾','quantangshi','','卷36','共说生前国步难，山川龙战血漫漫。
交锋魏帝旌旗退，委任君王社稷安。
庭际雨余春草长，庙前风起晚光残。
功勋碑碣今何在，不得当时一字看。','',''),('quantangshi-35904','咏史诗 乌江','胡曾','quantangshi','','卷36','争帝图王势已倾，八千兵散楚歌声。
乌江不是无船渡，耻向东吴再起兵。','',''),('quantangshi-35905','咏史诗 章华台','胡曾','quantangshi','','卷36','茫茫衰草没章华，因笑灵王昔好奢。
台土未干箫管绝，可怜身死野人家。','',''),('quantangshi-35906','咏史诗 细腰宫','胡曾','quantangshi','','卷36','楚王辛苦战无功，国破城荒霸业空。
唯有青春花上露，至今犹泣细腰宫。','',''),('quantangshi-35907','咏史诗 沙苑','胡曾','quantangshi','','卷36','冯翊南边宿雾开，行人一步一裴回。
谁知此地凋残柳，尽是高欢败后栽。','',''),('quantangshi-35908','咏史诗 石城','胡曾','quantangshi','','卷36','古郢云开白雪楼，汉江还遶石城流。
何人知道寥天月，曾向朱门送莫愁。','',''),('quantangshi-35909','咏史诗 荆山','胡曾','quantangshi','','卷36','抱玉岩前桂叶稠，碧溪寒水至今流。
空山落日猨声呌，疑是荆人哭未休。','',''),('quantangshi-35910','咏史诗 阳台','胡曾','quantangshi','','卷36','楚国城池飒已空，阳台云雨过无踪。
何人更有襄王梦，寂寂巫山十二重。','',''),('quantangshi-35911','咏史诗 居延','胡曾','quantangshi','','卷36','漠漠平沙际碧天，问人云此是居延。
停骖一顾犹魂断，苏武争禁十九年。','',''),('quantangshi-35912','咏史诗 沛宫','胡曾','quantangshi','','卷36','汉高辛苦事干戈，帝业兴隆俊杰多。
犹恨四方无壮士，还乡悲唱大风歌。','',''),('quantangshi-35913','咏史诗 金谷园','胡曾','quantangshi','','卷36','一自佳人坠玉楼，繁华东逐洛河流。
唯余金谷园中树，残日蝉声送客愁。','',''),('quantangshi-35914','咏史诗 湘川','胡曾','quantangshi','','卷36','虞舜南捐万乘君，灵妃挥涕竹成纹。
不知精魄游何处，落日潇湘空白云。','',''),('quantangshi-35915','咏史诗 夷门','胡曾','quantangshi','','卷36','六龙冉冉骤朝昏，魏国贤才杳不存。
唯有侯嬴在时月，夜来空自照夷门。','',''),('quantangshi-35916','咏史诗 黄金台','胡曾','quantangshi','','卷36','北乘羸马到燕然，此地何人复礼贤。
若问昭王无处所，黄金台上草连天。','',''),('quantangshi-35917','咏史诗 夷陵','胡曾','quantangshi','','卷36','夷陵城阙倚朝云，战败秦师纵火焚。
何事三千珠履客，不能西御武安君。','',''),('quantangshi-35918','咏史诗 汉江','胡曾','quantangshi','','卷36','汉江一带碧流长，两岸春风起绿杨。
借问胶船何处没，欲停兰棹祀昭王。','',''),('quantangshi-35919','咏史诗 苍梧','胡曾','quantangshi','','卷36','有虞龙驾不西还，空委箫韶洞壑间。
无计得知陵寝处，愁云长满九疑山。','',''),('quantangshi-35920','咏史诗 陈宫','胡曾','quantangshi','','卷36','陈国机权未可涯，如何后主恣娇奢。
不知即入宫中井，犹自听吹玉树花。','',''),('quantangshi-35921','咏史诗 南阳','胡曾','quantangshi','','卷36','世乱英雄百战余，孔明方此乐耕锄。
蜀王不自垂三顾，争得先生出旧庐。','',''),('quantangshi-35922','咏史诗 即墨','胡曾','quantangshi','','卷36','即墨门开纵火牛，燕师营里血波流。
固存不得田单术，齐国寻成一土丘。','',''),('quantangshi-35923','咏史诗 渭滨','胡曾','quantangshi','','卷36','岸草青青渭水流，子牙曾此独垂钩。
当时未入非熊兆，几向斜阳叹白头。','',''),('quantangshi-35924','咏史诗 五湖','胡曾','quantangshi','','卷36','东上高山望五湖，雪涛烟浪起天隅。
不知范蠡乘舟后，更有功臣继踵无。','',''),('quantangshi-35925','咏史诗 易水','胡曾','quantangshi','','卷36','一旦秦皇马角生，燕丹归北送荆卿。
行人欲识无穷恨，听取东流易水声。','',''),('quantangshi-35926','咏史诗 长平','胡曾','quantangshi','','卷36','长平瓦震武安初，赵卒俄成戏鼎鱼。
四十万人俱下世，元戎何用读兵书。','',''),('quantangshi-35927','咏史诗 西园','胡曾','quantangshi','','卷36','月满西园夜未央，金风不动邺天凉。
高情公子多秋兴，更领诗人入醉乡。','',''),('quantangshi-35928','咏史诗 长沙','胡曾','quantangshi','','卷36','江上南风起白苹，长沙城郭异咸秦。
故乡犹自嫌卑湿，何况当时赋鵩人。','',''),('quantangshi-35929','咏史诗 圯桥','胡曾','quantangshi','','卷36','庙算张良独有余，少年逃难下邳初。
逡巡不进泥中履，争得先生一卷书。','',''),('quantangshi-35930','咏史诗 铜雀台','胡曾','quantangshi','','卷36','魏武龙舆逐逝波，高台空按望陵歌。
遏云声绝悲风起，翻向樽前泣翠娥。','',''),('quantangshi-35931','咏史诗 东晋','胡曾','quantangshi','','卷36','石头城下浪崔嵬，风起声疑出地雷。
何事苻坚太相小，欲投鞭策过江来。','',''),('quantangshi-35932','咏史诗 吴江','胡曾','quantangshi','','卷36','子胥今日委东流，吴国明朝亦古丘。
大笑夫差诸将相，更无人解守苏州。','',''),('quantangshi-35933','咏史诗 函谷关','胡曾','quantangshi','','卷36','寂寂函关锁未开，田文车马出秦来。
朱门不养三千客，谁为鸡鸣得放回。','',''),('quantangshi-35934','咏史诗 武关','胡曾','quantangshi','','卷36','战国相持竟不休，武关才掩楚王忧。
出门若取灵均语，岂作咸阳一死囚。','',''),('quantangshi-35935','咏史诗 垓下','胡曾','quantangshi','','卷36','拔山力尽霸图隳，倚剑空歌不逝骓。
明月满营天似水，那堪回首别虞姬。','',''),('quantangshi-35936','咏史诗 郴县','胡曾','quantangshi','','卷36','义帝南迁路入郴，国亡身死乱山深。
不知埋恨穷泉后，几度西陵片月沈。','',''),('quantangshi-35937','咏史诗 东海','胡曾','quantangshi','','卷36','东巡玉辇委泉台，徐福楼船尚未回。
自是祖龙先下世，不关无路到蓬莱。','',''),('quantangshi-35938','咏史诗 故宜城','胡曾','quantangshi','','卷36','武安南伐勒秦兵，疎凿功将夏禹并。
谁谓长渠千载后，水流犹入故宜城。','',''),('quantangshi-35939','咏史诗 成都','胡曾','quantangshi','','卷36','杜宇曾为蜀帝王，化禽飞去旧城荒。
年年来呌桃花月，似向春风诉国亡。','',''),('quantangshi-35940','咏史诗 檀溪','胡曾','quantangshi','','卷36','三月襄阳绿草齐，王孙相引到檀溪。
的卢何处埋龙骨，流水依前遶大堤。','',''),('quantangshi-35941','咏史诗 青冢','胡曾','quantangshi','','卷36','玉貌元期汉帝招，谁知西嫁怨天骄。
至今青冢愁云起，疑是佳人恨未销。','',''),('quantangshi-35942','咏史诗 李陵台','胡曾','quantangshi','','卷36','北入单于万里疆，五千兵败滞穷荒。
英雄不伏蛮夷死，更筑高台望故乡。','',''),('quantangshi-35943','咏史诗 河梁','胡曾','quantangshi','','卷36','汉家英杰出皇都，携手河梁话入胡。
不是子卿全大节，也应低首拜单于。','',''),('quantangshi-35944','咏史诗 轵道','胡曾','quantangshi','','卷36','汉祖西来秉白旄，子婴宗庙委波涛。
谁怜君有翻身术，解向秦宫杀赵高。','',''),('quantangshi-35945','咏史诗 汉宫','胡曾','quantangshi','','卷36','明妃远嫁泣西风，玉筯双垂出汉宫。
何事将军封万户，却令红粉为和戎。','',''),('quantangshi-35946','咏史诗 豫让桥','胡曾','quantangshi','','卷36','豫让酬恩岁已深，高名不朽到如今。
年年桥上行人过，谁有当时国士心。','',''),('quantangshi-35947','咏史诗 华亭','胡曾','quantangshi','','卷36','陆机西没洛阳城，吴国春风草又青。
惆怅月中千岁鹤，夜来犹为唳华亭。','',''),('quantangshi-35948','咏史诗 东山','胡曾','quantangshi','','卷36','五马南浮一化龙，谢安入相此山空。
不知携妓重来日，几树莺啼谷口风。','',''),('quantangshi-35949','咏史诗 杀子谷','胡曾','quantangshi','','卷36','举国贤良尽泪垂，扶苏屈死树边时。
至今谷口泉呜咽，犹似秦人恨李斯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-35950','咏史诗 马陵','胡曾','quantangshi','','卷36','坠叶萧萧九月天，驱兵独过马陵前。
路傍古木虫书处，记得将军破敌年。','',''),('quantangshi-35951','咏史诗 玉门关','胡曾','quantangshi','','卷36','西戎不敢过天山，定远功成白马闲。
半夜帐中停烛坐，唯思生入玉门关。','',''),('quantangshi-35952','咏史诗 滹沱河','胡曾','quantangshi','','卷36','光武经营业未兴，王郎兵革正凭陵。
须知后汉功臣力，不及滹沱一片冰。','',''),('quantangshi-35953','咏史诗 黄河','胡曾','quantangshi','','卷36','博望沈埋不复旋，黄河依旧水茫然。
沿流欲共牛郎语，只得灵槎送上天。','',''),('quantangshi-35954','咏史诗 凤皇台','胡曾','quantangshi','','卷36','秦娥一别凤皇台，东入青冥更不回。
空有玉箫千载后，遗声时到世间来。','',''),('quantangshi-35955','咏史诗 五丈原','胡曾','quantangshi','','卷36','蜀相西驱十万来，秋风原下久裴回。
长星不为英雄住，半夜流光落九垓。','',''),('quantangshi-35956','咏史诗 平城','胡曾','quantangshi','','卷36','汉帝西征陷虏尘，一朝围解议和亲。
当时已有吹毛剑，何事无人杀奉春。','',''),('quantangshi-35957','咏史诗 汴水','胡曾','quantangshi','','卷36','千里长河一旦开，亡隋波浪九天来。
锦帆未落干戈起，惆怅龙舟更不回。','',''),('quantangshi-35958','咏史诗 兰台宫','胡曾','quantangshi','','卷36','迟迟春日满长空，亡国离宫蔓草中。
宋玉不忧人事变，从游那赋大王风。','',''),('quantangshi-35959','咏史诗 金牛驿','胡曾','quantangshi','','卷36','山岭千重拥蜀门，成都别是一干坤。
五丁不凿金牛路，秦惠何由得并吞。','',''),('quantangshi-35960','咏史诗 望思台','胡曾','quantangshi','','卷36','太子衔冤去不回，临臯从筑望思台。
至今汉武销魂处，犹有悲风木上来。','',''),('quantangshi-35961','咏史诗 邯郸','胡曾','quantangshi','','卷36','晓入邯郸十里春，东风吹下玉楼尘。
青娥莫怪频含笑，记得当年失步人。','',''),('quantangshi-35962','咏史诗 箕山','胡曾','quantangshi','','卷36','寂寂箕山春复秋，更无人到此溪头。
弃瓢岩畔中宵月，千古空闻属许由。','',''),('quantangshi-35963','咏史诗 会稽山','胡曾','quantangshi','','卷36','越王兵败已山栖，岂望全生出会稽。
何事夫差无远虑，更开罗网放鲸鲵。','',''),('quantangshi-35964','咏史诗 不周山','胡曾','quantangshi','','卷36','共工争帝力穷秋，因此捐生触不周。
遂使世间多感客，至今哀怨水东流。','',''),('quantangshi-35965','咏史诗 虞坂','胡曾','quantangshi','','卷36','悠悠虞坂路欹斜，迟日和风簇野花。
未省孙阳身没后，几多骐骥困盐车。','',''),('quantangshi-35966','咏史诗 秦庭','胡曾','quantangshi','','卷36','楚国君臣草莽间，吴王戈甲未东还。
包胥不动咸阳哭，争得秦兵出武关。','',''),('quantangshi-35967','咏史诗 延平津','胡曾','quantangshi','','卷36','延平津路水溶溶，峭壁巍岑一万重。
昨夜七星潭底见，分明神剑化为龙。','',''),('quantangshi-35968','咏史诗 瑶池','胡曾','quantangshi','','卷36','阿母瑶池宴穆王，九天仙乐送琼浆。
漫矜八骏行如电，归到人间国已亡。','',''),('quantangshi-35969','咏史诗 铜柱','胡曾','quantangshi','','卷36','一柱高标险塞垣，南蛮不敢犯中原。
功成自合分茅土，何事翻衔薏苡冤。','',''),('quantangshi-35970','咏史诗 关西','胡曾','quantangshi','','卷36','杨震幽魂下北邙，关西踪迹遂荒凉。
四知美誉留人世，应与干坤共久长。','',''),('quantangshi-35971','咏史诗 高阳池','胡曾','quantangshi','','卷36','古人未遇即衔杯，所贵愁肠得酒开。
何事山公持玉节，等闲深入醉乡来。','',''),('quantangshi-35972','咏史诗 泸水','胡曾','quantangshi','','卷36','五月驱兵入不毛，月明泸水瘴烟高。
誓将雄略酬三顾，岂惮征蛮七纵劳。','',''),('quantangshi-35973','咏史诗 细柳营','胡曾','quantangshi','','卷36','文帝銮舆劳北征，条侯此地整严兵。
辕门不峻将军令，今日争知细柳营。','',''),('quantangshi-35974','咏史诗 叶县','胡曾','quantangshi','','卷36','叶公丘墓已尘埃，云矗崇墉亦半摧。
借问往年龙见日，几多风雨送将来。','',''),('quantangshi-35975','咏史诗 杜邮','胡曾','quantangshi','','卷36','自古功成祸亦侵，武安冤向杜邮深。
五湖烟月无穷水，何事迁延到陆沈。','',''),('quantangshi-35976','咏史诗 柯亭','胡曾','quantangshi','','卷36','一宿柯亭月满天，笛亡人没事空传。
中郎在世无甄别，争得名垂尔许年。','',''),('quantangshi-35977','咏史诗 葛陂','胡曾','quantangshi','','卷36','长房回到葛陂中，人已登真竹化龙。
莫道神仙难顿学，嵇生自是不遭逢。','',''),('quantangshi-35978','咏史诗 博浪沙','胡曾','quantangshi','','卷36','嬴政鲸吞六合秋，削平天下虏诸侯。
山东不是无公子，何事张良独报讐。','',''),('quantangshi-35979','咏史诗 陇西','胡曾','quantangshi','','卷36','乘春来到陇山西，隗氏城荒碧草齐。
好笑王元不量力，函关那受一丸泥。','',''),('quantangshi-35980','咏史诗 白帝城','胡曾','quantangshi','','卷36','蜀江一带向东倾，江上巍峩白帝城。
自古山河归圣主，子阳虚共汉家争。','',''),('quantangshi-35981','咏史诗 牛渚','胡曾','quantangshi','','卷36','温峤南归辍棹晨，燃犀牛渚照通津。
谁知万丈洪流下，更有朱衣跃马人。','',''),('quantangshi-35982','咏史诗 朝歌','胡曾','quantangshi','','卷36','长嗟墨翟少风流，急管繁弦似寇讐。
若解闻韶知肉味，朝歌欲到肯回头。','',''),('quantangshi-35983','咏史诗 谷口','胡曾','quantangshi','','卷36','一旦天真逐水流，虎争龙战为诸侯。
子真独有烟霞趣，谷口耕锄到白头。','',''),('quantangshi-35984','咏史诗 武陵溪','胡曾','quantangshi','','卷36','一溪春水彻云根，流出桃花片片新。
若到长生是虚语，洞中争得有秦人。','',''),('quantangshi-35985','咏史诗 大泽','胡曾','quantangshi','','卷36','白蛇初断路人通，汉祖龙泉血刃红。
不是咸阳将瓦解，素灵那哭月明中。','',''),('quantangshi-35986','咏史诗 渑池','胡曾','quantangshi','','卷36','日照荒城芳草新，相如曾此挫强秦。
能令百二山河主，便作樽前击缶人。','',''),('quantangshi-35987','咏史诗 岘山','胡曾','quantangshi','','卷36','晓日登临感晋臣，古碑零落岘山春。
松间残露频频滴，酷似当时堕泪人。','',''),('quantangshi-35988','咏史诗 荥阳','胡曾','quantangshi','','卷36','汉祖东征屈未伸，荥阳失律纪生焚。
当时天下方龙战，谁为将军作诔文。','',''),('quantangshi-35989','咏史诗 长城','胡曾','quantangshi','','卷36','祖舜宗尧自太平，秦皇何事苦苍生。
不知祸起萧墙内，虚筑防胡万里城。','',''),('quantangshi-35990','咏史诗 赤壁','胡曾','quantangshi','','卷36','烈火西焚魏帝旗，周郎开国虎争时。
交兵不假挥长剑，已挫英雄百万师。','',''),('quantangshi-35991','咏史诗 田横墓','胡曾','quantangshi','','卷36','古墓崔巍约路岐，歌传薤露到今时。
