不得长年少，那堪远别离。
泛湖乘月早，践雪过山迟。
永望多时立，翻如在梦思。','',''),('quantangshi-36072','君不来','方干','quantangshi','','卷37','闲花未零落，心绪已纷纷。
久客无人见，新禽何处闻？
舟随一水远，路出万山分。
夜月生愁望，孤光必照君。','',''),('quantangshi-36073','将谒商州吕郎中道出楚州留献章中丞','方干','quantangshi','','卷37','江流盘复直，浮棹出家林。
商洛路犹远，山阳春已深。
青云应有望，白发未相侵。
才小知难荐，终劳许郭心。','',''),('quantangshi-36074','金州客舍','方干','quantangshi','','卷37','卷箔羣峰暮，萧条未掩关。
江流嶓[冢]雨，路入汉家山。
落叶欹眠后，孤砧倚望间。
此情偏耐醉，难遣酒罍闲。','',''),('quantangshi-36075','途中逢孙辂因得李频消息','方干','quantangshi','','卷37','灞上寒仍在，柔条亦自新。
山河虽度腊，雨雪未知春。
正忆同袍者，堪逢共国人。
衔杯益无语，与尔转相亲。','',''),('quantangshi-36076','送从兄郜','方干','quantangshi','','卷37','道路本无限，又应何处逢？
流年莫虚掷，华髪不相容。
野渡波摇月，空城雨翳钟。
此心随去马，迢递过千峰。','',''),('quantangshi-36077','送许温','方干','quantangshi','','卷37','壮岁分冞切，少年心正同。
当闻千里去，难遣一尊空。
翳烛蒹葭雨，吹帆橘柚风。
明年见亲族，尽集在怀中。','',''),('quantangshi-36078','镜中别业二首 一','方干','quantangshi','','卷37','寒山压镜心，此处是家林。
梁燕窥春醉，岩猿学夜吟。
云连平地起，月向白波沈。
犹自闻钟角，栖身可在深。','',''),('quantangshi-36079','镜中别业二首 二','方干','quantangshi','','卷37','世人如不容，吾自纵天慵。
落叶凭风扫，香秔倩水舂。
花朝连郭雾，雪夜隔湖钟。
身外无能事，头宜白此峰。','',''),('quantangshi-36080','经周处士故居','方干','quantangshi','','卷37','愁吟与独行，何事不伤情。
久立钓鱼处，唯闻啼鸟声。
山蔬和草嫩，海树入篱生。
吾在兹溪上，怀君恨不平。','',''),('quantangshi-36081','赠喻凫','方干','quantangshi','','卷37','所得非众语，众人那得知。
才吟五字句，又白几茎髭。
月阁欹眠夜，霜轩正坐时。
沈思心更苦，恐作满头丝。','',''),('quantangshi-36082','早发洞庭','方干','quantangshi','','卷37','长天接广泽，二气共含秋。
举目无平地，何心恋直钩。
孤钟鸣大岸，片月落中流。
却忆鸱夷子，当时此泛舟。','',''),('quantangshi-36083','贻钱塘县路明府','方干','quantangshi','','卷37','志业不得力，到今犹苦吟。
唫成五字句，用破一生心。
世路屈声远，寒溪怨气深。
前贤多晚达，莫怕鬓霜侵。','',''),('quantangshi-36084','湖上言事寄长城喻明府','方干','quantangshi','','卷37','吟霜与卧云，此兴亦甘贫。
吹箭落翠羽，垂丝牵锦鳞。
满湖风撼月，半日雨藏春。
却笑萦簪组，劳心字远人。','',''),('quantangshi-36085','涵碧亭','方干','quantangshi','','卷37','高低竹杂松，积翠复留风。
路极阴溪里，寒生暑气中。
闲云低覆草，片水静涵空。
方见洋源牧，心侔造化功。','',''),('quantangshi-36086','除夜','方干','quantangshi','','卷37','永怀难自问，此夕众愁兴。
晓韵侵春角，寒光隔岁灯。
心燃一寸火，泪结两行冰。
煦育诚非远，阳和又欲升。','',''),('quantangshi-36087','赠许牍山人','方干','quantangshi','','卷37','才子醉更逸，一吟倾一觞。
支颐忍有得，摇笔便成章。
王粲实可重，禰衡争不狂。
何时应会面，梦里是潇湘。','',''),('quantangshi-36088','赠功成将','方干','quantangshi','','卷37','定难在明略，何曾劳战争。
飞书谕强寇，计日下重城。
深雪移军夜，寒笳出塞情。
苦心殊易老，新髪早年生。','',''),('quantangshi-36089','白艾原客','方干','quantangshi','','卷37','原上桑柘瘦，再来还见贫。
沧州几年隐，白发一茎新。
败叶平空堑，残阳满近隣。
闲言说知己，半是学禅人。','',''),('quantangshi-36090','朔管','方干','quantangshi','','卷37','寥寥落何处，一夜过胡天。
送苦秋风外，吹愁白发边。
望乡皆下泪，久戍尽休眠。
寂寞空沙晓，开眸片月悬。','',''),('quantangshi-36091','忆故山','方干','quantangshi','','卷37','旧山长系念，终日卧边亭。
道路知已远，梦魂空再经。
秋泉凉好引，乳鹤静宜听。
独上高楼望，蓬身且未宁。','',''),('quantangshi-36092','冬夜泊僧舍','方干','quantangshi','','卷37','江东寒近腊，野寺水天昏。
无酒能消夜，随僧早闭门。
照墙灯焰细，着瓦雨声繁。
漂泊仍千里，清吟欲断魂。','',''),('quantangshi-36093','新秋独夜寄戴叔伦','方干','quantangshi','','卷37','遥夜独不卧，寂寥庭户中。
河明五陵上，月满九门东。
万里亲朋散，故园沧海空。
归怀正南望，此夕起秋风。','',''),('quantangshi-36094','送沛县司马丞之任','方干','quantangshi','','卷37','举酒一相劝，逢春聊尽欢。
羇游故交少，远别后期难。
路上野花发，雨中青草寒。
悠悠两都梦，小沛与长安。','',''),('quantangshi-36095','送卢评事东归','方干','quantangshi','','卷37','万里杨柳色，出关随故人。
轻烟覆流水，落日照行尘。
积梦江湖阔，忆家兄弟贫。
裴回灞亭上，不语共伤春。','',''),('quantangshi-36096','清明日送邓芮还乡','方干','quantangshi','','卷37','钟鼓喧离室，车徒促夜装。
晓榆新变火，轻柳暗飞霜。
转镜看华髪，传杯话故乡。
每嫌儿女泪，今日自沾裳。','',''),('quantangshi-36097','送崔拾遗出使江东','方干','quantangshi','','卷37','九门思谏诤，万里采风谣。
关外逢秋月，天涯过晚潮。
雁飞云杳杳，木落浦萧萧。
空怨他乡别，回舟暮寂寥。','',''),('quantangshi-36098','重阳日送洛阳李丞之任','方干','quantangshi','','卷37','为文通绝境，从宦及良辰。
洛下知名早，腰边结绶新。
且倾浮菊酒，聊拂染衣尘。
独恨沧州侣，愁来别故人。','',''),('quantangshi-36099','江州送李侍御归东洛','方干','quantangshi','','卷37','独乘骢马去，不并旅人还。
中外名卿贵，田园高步闲。
暮春经楚县，新月上淮山。
道路空瞻望，轩车不敢攀。','',''),('quantangshi-36100','送郭太祝归江东','方干','quantangshi','','卷37','乡人去欲尽，北雁又南飞。
京洛风尘久，江淮音信稀。
旧山知独往，一醉莫相违。
未得解羇旅，无劳问是非。','',''),('quantangshi-36101','送李恬及第后还贝州','方干','quantangshi','','卷37','成名年少日，就业圣人书。
擢桂谁相比，籝金已不如。
东城送归客，秋日待征车。
若到清潭畔，儒风变里闾。','',''),('quantangshi-36102','收两京后还上都兼访一二亲故','方干','quantangshi','','卷37','离堂千里客，归骑五陵人。
路转函关晚，烟开上苑新。
天涯将野服，阙下见乡亲。
问得存亡事，裁诗寄海滨。','',''),('quantangshi-36103','送汶上王明府之任','方干','quantangshi','','卷37','何时到故乡，归去佩铜章。
亲友移家尽，闾阎百战伤。
背关余草木，出塞足风霜。
遗老应相贺，知君不下堂。','',''),('quantangshi-36104','湖南使院遣情送江夏贺侍郎','方干','quantangshi','','卷37','云雨一消散，悠悠关复河。
俱从泛舟役，遂隔洞庭波。
楚水去不尽，秋风今更过。
无由得相见，却恨寄书多。','',''),('quantangshi-36105','过申州作','方干','quantangshi','','卷37','万人曾死战，几户免刀兵。
井邑初安堵，儿童未长成。
凉风吹古木，野火烧残营。
寥落千余里，山高水复清。','',''),('quantangshi-36106','汝南过访田评事','方干','quantangshi','','卷37','移家近汉阴，不复问华簪。
买酒宜城远，烧田梦泽深。
暮山逢鸟入，寒水见鱼沈。
与物皆无累，终年惬本心。','',''),('quantangshi-36107','送道上人游方','方干','quantangshi','','卷37','律仪通外学，诗思入玄关。
烟景随人别，风姿与物闲。
贯花留静室，咒水度空山。
谁识浮云意，悠悠天地间。','',''),('quantangshi-36108','送饶州王司法之任兼寄朱处士','方干','quantangshi','','卷37','莫辞还作吏，且喜速回车。
留醉悲残岁，含情寄远书。
共看衰老近，转觉宦名虚。
遥想清溪畔，幽人得自如。','',''),('quantangshi-36109','詹碏山居','方干','quantangshi','','卷37','爱此栖心静，风尘路已赊。
十余茎野竹，一两树山花。
遶石开泉细，穿萝引径斜。
无人会幽意，来往在烟霞。','',''),('quantangshi-36110','晓角','方干','quantangshi','','卷37','画角吹残月，寒声发戍楼。
立霜嘶马怨，攒碛泣兵愁。
燕雁鸣云畔，胡风冷草头。
罢闻三会后，天逈晓星流。','',''),('quantangshi-36111','冬日','方干','quantangshi','','卷37','烧火掩关坐，穷居客访稀。
冻云愁暮色，寒日淡斜晖。
穿牖竹风满，遶庭云叶飞。
已嗟周一岁，羇寓尚何依。','',''),('quantangshi-36112','残秋送友','方干','quantangshi','','卷37','早为千里别，况复是秋残。
木叶怨先老，江云愁暮寒。
交情如水淡，离酒泛杯宽。
料想还家后，休吟行路难。','',''),('quantangshi-36113','客行','方干','quantangshi','','卷37','藕叶缀为衣，东西泣路岐。
乡心日落后，身计酒醒时。
触目多添感，凝情足所思。
羁愁难尽遣，行坐一低眉。','',''),('quantangshi-36114','秋夜','方干','quantangshi','','卷37','度鸿惊睡醒，欹枕已三更。
梦破寂寥思，灯残零落明。
空窗闲月色，幽壁静虫声。
况是离乡久，依然无限情。','',''),('quantangshi-36115','新月','方干','quantangshi','','卷37','入夜天西见，蛾[眉]冷素光。
潭鱼惊钓落，云雁怯弓张。
隐隐临珠箔，微微上粉墙。
更怜三五夕，仙桂满轮芳。','',''),('quantangshi-36116','滁上怀周贺','方干','quantangshi','','卷37','就枕忽不寐，孤怀兴叹初。
南谯收旧历，上苑绝来书。
暝雪细声积，晨钟寒韵疎。
侯门昔弹铗，曾共食江鱼。','',''),('quantangshi-36117','寄石湓清越上人','方干','quantangshi','','卷37','寺处唯高僻，云生石枕前。
静吟因得句，独夜不妨禅。
窗接停猨树，岩飞浴鹤泉。
相思有书札，俱倩猎人传。','',''),('quantangshi-36118','陈式水墨山水','方干','quantangshi','','卷37','造化有功力，平分归笔端。
溪如冰后听，山似烧来看。
立意雪髯出，支颐烟汗干。
世间从尔后，应觉致名难。','',''),('quantangshi-36119','陈秀才亭际木兰','方干','quantangshi','','卷37','昔见初栽日，今逢成树时。
存思心更感，遶看步还迟。
蝶舞摇风蘂，莺啼含露枝。
裴回不忍去，应与醉相宜。','',''),('quantangshi-36120','赠镜公','方干','quantangshi','','卷37','幽独度遥夜，夜清神更闲。
高风吹越树，细露湿湖山。
月皎微吟后，钟鸣不寐间。
如教累簪组，此兴岂相关。','',''),('quantangshi-36121','登雪窦僧家','方干','quantangshi','','卷37','登寺寻盘道，人烟远更微。
石窗秋见海，山霭暮侵衣。
众木随僧老，高泉尽日飞。
谁能厌轩冕，来此便忘机。','',''),('quantangshi-36122','途中逢进士许巢','方干','quantangshi','','卷37','声望去已远，门人无不知。
义行相识处，贫过少年时。
妨寐夜吟苦，爱闲身达迟。
难求似君者，我去更逢谁。','',''),('quantangshi-36123','赠玛瑙山禅者','方干','quantangshi','','卷37','芿草不停兽，因师山更灵。
村林朝乞食，风雨夜开扃。
井味兼松粉，云根着净瓶。
尘劳如醉梦，对此暂能醒。','',''),('quantangshi-36124','酬故人陈乂都','方干','quantangshi','','卷37','远别那无梦，重游自有期。
半年乡信到，两地赤心知。
坐久吟移调，更长砚结凘。
文人才力薄，终怕阿戎欺。','',''),('quantangshi-36125','闰春','方干','quantangshi','','卷37','幂幂复苍苍，微和傍早阳。
前春寒已尽，待闰日犹长。
柳变虽因雨，花迟岂为霜。
自兹延圣历，谁不驻年光。','',''),('quantangshi-36126','方着作画竹','方干','quantangshi','','卷37','叠叶与高节，俱从毫末生。
流传千古誉，研炼十年情。
向月本无影，临风疑有声。
吾家钓台畔，似此两三茎。','',''),('quantangshi-36127','题友人山花','方干','quantangshi','','卷37','平明方发尽，为待好风吹。
不见移来日，先愁落去时。
浓香薰叠叶，繁朵压卑枝。
坐看皆终夕，游蜂似有期。','',''),('quantangshi-36128','赠诗僧怀静','方干','quantangshi','','卷37','几生余习在，时复作微吟。
坐夏莓苔合，行禅桧柏深。
入山成白首，学道是初心。
心地不移变，徒云寒暑侵。','',''),('quantangshi-36129','赠许牍秀才','方干','quantangshi','','卷37','理论与妙用，皆从人外来。
山河澄正气，雪月助宏才。
傲世寄渔艇，藏名归酒杯。
升沈在方寸，即恐起风雷。','',''),('quantangshi-36130','送于丹','方干','quantangshi','','卷37','至业是至宝，莫过心自知。
时情如甚畅，天道即无私。
入洛霜霰苦，离家兰菊衰。
焚舟不回顾，薄暮又何之。','',''),('quantangshi-36131','送人游日本国','方干','quantangshi','','卷37','沧茫大荒外，风教即难知。
连夜扬帆去，经年到岸迟。
波涛含左界，星斗定东维。
或有归风便，当为相见期。','',''),('quantangshi-36132','东溪言事寄于丹','方干','quantangshi','','卷37','日月昼夜转，年光难驻留。
轩窗才过雨，枕簟即知秋。
草际鸟行出，溪中虹影收。
唯君壮心在，应笑卧沧洲。','',''),('quantangshi-36133','暮发七里滩夜泊严光台下','方干','quantangshi','','卷37','一瞬即七里，箭驰犹是难。
樯边走岚翠，枕底失风湍。
但讶猨鸟定，不知霜月寒。
前贤竟何益，此地误垂竿。','',''),('quantangshi-36134','处州洞溪','方干','quantangshi','','卷37','气象四时清，无人画得成。
众山寒叠翠，两派绿分声。
坐月何曾夜，听松不似晴。
混元融结后，便有此溪名。','',''),('quantangshi-36135','称心寺中岛','方干','quantangshi','','卷37','水木深不极，似将星汉连。
中州唯此地，上界别无天。
雪折停猨树，花藏浴鹤泉。
师为终老意，日日复年年。','',''),('quantangshi-36136','岁晚苦寒','方干','quantangshi','','卷37','地气寒不畅，严风无定时。
挑灯青烬少，呵笔尺书迟。
白兔没已久，晨鸡僵未知。
竚看开圣历，喧煦立为期。','',''),('quantangshi-36137','杜鹃花','方干','quantangshi','','卷37','未问移栽日，先愁落地时。
疎中从间叶，密处莫烧枝。
郢客教谁探，胡蜂是自知。
周回两三步，常有醉乡期。','',''),('quantangshi-36138','山中','方干','quantangshi','','卷37','散拙亦自遂，麤将猨鸟同。
飞泉高泻月，独树逈含风。
果落盘盂上，云生箧笥中。
未甘明圣日，终作钓渔翁。','',''),('quantangshi-36139','路支使小池','方干','quantangshi','','卷37','儿童戏穿凿，咫尺见津涯。
藓岸和纤草，松泉溅浅沙。
光含半牀月，影入一枝花。
到此无醒日，当时有习家。','',''),('quantangshi-36140','清源标公','方干','quantangshi','','卷37','师为众人重，始得众人师。
年到白头日，行如新戒时。
瓶添放鱼涧，窗逈褭猿枝。
此地堪终老，迷痴自不知。','',''),('quantangshi-36141','题雪窦禅师壁','方干','quantangshi','','卷37','飞泉溅禅石，瓶注亦生苔。
海上山不浅，天边人自来。
长年随桧柏，独夜任风雷。
猎者闻疎磬，知师入定回。','',''),('quantangshi-36142','重寄金山寺僧','方干','quantangshi','','卷37','风涛匝山寺，磬韵达渔船。
此处别师久，远怀无信传。
月华妨静烛，鸟语答幽禅。
已见如如理，灰心应不然。','',''),('quantangshi-36143','哭胡圭','方干','quantangshi','','卷37','才高登上第，孝极殁庐茔。
一命何无定，片言徒有声。
故园花自发，新冢月初明。
寂寞重泉里，岂知春物荣。','',''),('quantangshi-36144','与清溪赵明府','方干','quantangshi','','卷37','清规暂趋府，独立与谁亲。
遂性无非酒，求闲却爱贫。
林泉应入梦，印绶莫留人。
王事闻多暇，吟来几首新。','',''),('quantangshi-36145','送剡县陈永秩满归越','方干','quantangshi','','卷37','俸禄三年后，程途一月间。
舟中非客路，镜里是家山。
密雪霑行袂，离杯变别颜。
古人唯贺满，今挈解由还。','',''),('quantangshi-36146','示乡叟','方干','quantangshi','','卷37','暮齿甘衰谢，逢人惜别离。
青山前代业，老树此身移。
买药将衣尽，寻方见字迟。
如何镊残鬓，览镜变成丝。','',''),('quantangshi-36147','游竹林寺','方干','quantangshi','','卷37','得路到深寺，幽虚曾识名。
藓浓阴砌古，烟起暮香生。
曙月落松翠，石泉流梵声。
闻僧说真理，烦恼自然轻。','',''),('quantangshi-36148','陆处士别业','方干','quantangshi','','卷37','问道远相访，无人觉路长。
夜深回钓檝，月影出书林。
蝉噪蓼花发，禽来山果香。
多时欲归去，西望又斜阳。','',''),('quantangshi-36149','赠中岳僧','方干','quantangshi','','卷37','坐来藂木大，谁见入岩年。
多病长留药，无忧亦是禅。
搘牀移片石，舂粟引高泉。
尽愿求心法，逢谁即拟传。','',''),('quantangshi-36150','寄普州贾司仓岛','方干','quantangshi','','卷37','乱山重复叠，何路访先生。
岂料多才者，空垂不世名闲曹犹得醉，薄俸亦胜耕。
莫问吟诗石，年年芳草平。','',''),('quantangshi-36151','送镜空上人游江南','方干','quantangshi','','卷37','去住如云鹤，飘然不可留。
何山逢后夏，一食在孤舟。
细雨莲塘晚，疎蝉橘岸秋。
应怀旧溪月，夜过石窗流。','',''),('quantangshi-36152','新正','方干','quantangshi','','卷37','筚门惆怅内，时节暗来频。
每见新正雪，长思故国春。
云西斜去雁，江上未归人。
又一年为客，何媒得到秦。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-36153','夜听步虚','方干','quantangshi','','卷37','寂寂永宫里，天师朝礼声。
步虚闻一曲，浑欲到三清。
瑞草秋风起，仙堦夜月明。
多年远尘意，此地欲铺平。','',''),('quantangshi-36154','题碧溪山禅老','方干','quantangshi','','卷37','师步有云随，师情唯鹤知。
萝迷收{艹/术}路，雪隔出溪时。
竹狖窥沙井，岩禽停桧枝。
由来傲卿相，卧稳答书迟。','',''),('quantangshi-36155','寒食宿先天寺无可上人房','方干','quantangshi','','卷37','双扉桧下开，寄宿石房苔。
幡北灯花动，城西雪霰来。
收棊想云梦，罢茗议天台。
同忆前年腊，师初白阁回。','',''),('quantangshi-36156','中秋月','方干','quantangshi','','卷37','凉霄烟霭外，三五玉蟾秋。
列野星辰正，当空鬼魅愁。
泉澄寒魄莹，露滴冷光浮。
未折青青桂，吟看不忍休。','',''),('quantangshi-36157','暮冬书怀呈友人','方干','quantangshi','','卷37','空为梁甫吟，谁竟是知音。
风雪生寒夜，乡园来旧心。
沧江孤棹逈，白阁一钟深。
君子久忘我，此怀甘自沈。','',''),('quantangshi-36158','赠江南僧','方干','quantangshi','','卷37','忘机室亦空，禅与沃州同。
唯有半庭竹，能生竟日风。
思山海月上，出定印香终。
继后传衣者，还须立雪中。','',''),('quantangshi-36159','柳','方干','quantangshi','','卷37','摇曳惹风吹，临堤软胜丝。
态浓谁为识，力弱自难持。
学舞枝翻袖，呈妆叶展眉。
如何一攀折，怀友又题诗。','',''),('quantangshi-36160','送姚合员外赴金州','方干','quantangshi','','卷37','受诏从华省，开旗发帝州。
野烟新驿曙，残照古山秋。
树势连巴没，江声入楚流。
唯应化行后，吟句上闲楼。','',''),('quantangshi-36161','送江阴霍明府之任','方干','quantangshi','','卷37','遥遥去舸新，浸郭苇兼苹。
树列巢滩鹤，乡多钓浦人。
虹分阳羡雨，浪隔广陵春。
知竟三年秩，琴书外是贫。','',''),('quantangshi-36162','送友及第归淛东','方干','quantangshi','','卷37','南行无俗侣，秋雁与寒云。
野趣自多惬，乡名人共闻。
吴山中路断，淛水半江分。
此地登临惯，摅情一送君。','',''),('quantangshi-36163','山中即事','方干','quantangshi','','卷37','趍世非身事，山中适性情。
野花多异色，幽鸟少凡声。
树影搜凉卧，苔光破碧行。
闲寻采药处，仙路渐分明。','',''),('quantangshi-36164','过黄州作','方干','quantangshi','','卷37','弭节齐安郡，孤城百战残。
傍村林有虎，带郭县无官。
暮角梅花怨，清江桂影寒。
黍离缘底事，撩我起长叹。','',''),('quantangshi-36165','元日','方干','quantangshi','','卷37','晨鸡两遍报更阑，刁斗无声晓漏干。
暖日映山调正气，东风入树舞残寒。
轩车欲识人间感，献岁须来帝里看。
才酌屠苏定年齿，坐中惟笑鬓毛斑。','',''),('quantangshi-36166','别从兄郜','方干','quantangshi','','卷37','展翅开帆秪待风，吹嘘成事古今同。
已呼断雁归行里，全胜枯鳞在辙中。
若许死前恩少报，终期言下命潜通。
临岐再拜无余事，愿取文章达圣聪。','',''),('quantangshi-36167','寄江陵王少府','方干','quantangshi','','卷37','分手频曾变寒暑，迢迢远意各何如。
波涛一阻两乡梦，岁月无过双鲤鱼。
吟处落花藏笔砚，睡时斜雨湿图书。
此来俗辈皆疎我，唯有故人心不疎。','',''),('quantangshi-36168','题睦州乌龙山禅居','方干','quantangshi','','卷37','曙后月华犹冷湿，自知坐卧逼天宫。
晨鸡未暇鸣山底，早日先来照屋东。
人世驱驰方丈内，海波摇动一杯中。
伴师长住应难住，归去仍须入俗笼。','',''),('quantangshi-36169','寄杭州于郎中','方干','quantangshi','','卷37','虽云圣代识贤明，自是山河应数生。
大雅篇章无弟子，高门世业有公卿。
入楼早月中秋色，遶郭寒潮半夜声。
白屋青云至悬阔，愚儒肝胆若为倾。','',''),('quantangshi-36170','寄灵武胡常侍','方干','quantangshi','','卷37','青云直上路初通，已在明君倚注中。
欲遣为霖安九有，先令作相赞东宫。
自从忠谠承天睠，更用文篇续国风。
最是何人感恩德，谢敷星下钓渔翁。','',''),('quantangshi-36171','上张舍人','方干','quantangshi','','卷37','海内芳声谁可竝，承家三代相门深。
剖符已副东人望，援笔曾传圣主心。
此地清廉惟饮水，四方焦热待为霖。
他年莫学鸱夷子，远泛扁舟用铸金。','',''),('quantangshi-36172','题慈溪张丞壁','方干','quantangshi','','卷37','因君贰邑蓝溪上，遣我维舟红叶时。
共向乡中非半面，俱惊鬓里有新丝。
竚看孤洁成三考，应笑愚疎舍一枝。
貌似故人心尚喜，相逢况是旧相知。','',''),('quantangshi-36173','赠邻居袁明府','方干','quantangshi','','卷37','隔竹每呼皆得应，二心亲熟更如何。
文章锻炼犹相似，年齿参差不校多。
雨后卷帘看越岭，更深欹枕听湖波。
朝昏幸得同醒醉，遮莫光阴自下坡。','',''),('quantangshi-36174','孙氏林亭','方干','quantangshi','','卷37','池亭才有二三亩，风景胜于千万家。
瑟瑟林排全巷竹，猩猩血染半园花。
竝牀欹枕逢春尽，援笔持杯到日斜。
丱角相知成白首，而今欢笑莫咨嗟。','',''),('quantangshi-36175','漳州阳亭言事寄于使君','方干','quantangshi','','卷37','谢守登城对远峰，金英泛泛满金钟。
楼头风景八九月，牀下水云千万重。
红斾朝昏虽许近，清才今古定难逢。
鲤鱼纵是凡鳞鬣，得在膺门合作龙。','',''),('quantangshi-36176','别胡中丞','方干','quantangshi','','卷37','二年朝夜见双旌，心魄知恩梦亦惊。
幽贱麤能分菽麦，从容岂合遇公卿。
吹嘘若自毫端出，羽翼应从肉上生。
却恨此身唯一死，空将一死报犹轻。','',''),('quantangshi-36177','游张公洞寄陶校书','方干','quantangshi','','卷37','步步势穿江底去，此中危滑转身难。
下蒸阴气松萝湿，外制温风杖屦寒。
数里烟云方觉异，前程世界更应宽。
由来委曲寻仙路，不似先生换骨丹。','',''),('quantangshi-36178','题睦州郡中千峰榭','方干','quantangshi','','卷37','岂知平地似天台，朱户深沈别径开。
曳响露蝉穿树去，斜行沙鸟向池来。
窗中早月当琴榻，墙上秋山入酒杯。
何事此中如世外，应缘羊祜是仙才。','',''),('quantangshi-36179','登新城县楼赠蔡明府','方干','quantangshi','','卷37','杨震东来是宦游，政成登此自消忧。
草中白道穿村去，树里清溪照郭流。
纵目四山宜永日，开襟五月似高秋。
不知县籍添新户，但见川原桑柘稠。','',''),('quantangshi-36180','和于中丞登扶风亭','方干','quantangshi','','卷37','避石攀萝去不迷，行时举步似丹梯。
东轩海日已先照，下界晨鸡犹未啼。
郭里云山全占寺，村前竹树半藏溪。
谢公吟望多来此，此地应将岘首齐。','',''),('quantangshi-36181','赠信州高员外','方干','quantangshi','','卷37','溪势盘回绕郡流，饶阳春色满溪楼。
岂唯啼鸟催人醉，更有繁花笑客愁。
蹇拙命中迷直道，仁慈风里驻扁舟。
膺门若感深恩去，终杀微躯未足酬。','',''),('quantangshi-36182','漳州于使君罢郡如之任漳南去上国二十四州使君无非亲故','方干','quantangshi','','卷37','漳南罢郡如之任，二十四州相次迎。
泊岸旗幡邮吏拜，连山风雨探人行。
月中倚棹吟渔浦，花底垂鞭醉凤城。','',''),('quantangshi-36183','送弟子伍秀才赴举','方干','quantangshi','','卷37','天遣相门延积庆，今同太庙荐嘉宾。
柳条此日同谁折，桂树明年为尔春。
倚棹寒吟渔浦月，垂鞭醉入凤城尘。
由来不要文章得，要且文章出众人。','',''),('quantangshi-36184','贻高谠','方干','quantangshi','','卷37','都缘相府有宗兄，却恐妨君正路行。
石上长松自森秀，雪中孤玉更凝明。
西陵晓月中秋色，北固军鼙半夜声。
幸有清才与洪笔，何愁高节不公卿。','',''),('quantangshi-36185','题长洲陈明府小亭','方干','quantangshi','','卷37','坐看孤峭却劳神，还是微吟到日曛。
松鹤认名呼得下，沙蝉飞处听犹闻。
夜阑亦似深山月，雨后唯关满屋云。
便此逍遥应不易，朱衣红斾未容君。','',''),('quantangshi-36186','送朱二十赴涟水','方干','quantangshi','','卷37','到县却应嫌水阔，离家终是见山疎。
笙歌不驻难辞酒，舟檝将行负担书。
为政必能安楚老，向公犹可钓淮鱼。
鸾凰取便多如此，掠地斜飞上太虚。','',''),('quantangshi-36187','德政上睦州胡中丞','方干','quantangshi','','卷37','上德由来合动天，旌旗到日是丰年。
羣书已熟无人似，五字研成举世传。
莫道政声同宇宙，须知紫气满山川。
岂唯里巷皆苏息，犹有恩波及钓船。','',''),('quantangshi-36188','袁明府以家醖寄余余以山梅答赠非唯四韵兼亦双关','方干','quantangshi','','卷37','封匏寄酒提携远，织笼盛梅答赠迟。
九度搅和谁用法，四边窥摘自攀枝。
罇罍泛蚁堪尝日，童稚驱禽欲熟时。
毕卓醉狂潘氏少，倾来掷去恰相宜。','',''),('quantangshi-36189','上杭州姚郎中','方干','quantangshi','','卷37','能除疾瘼似良医，一郡乡风当日移。
身贵久离行药伴，才高独作后人师。
春游下马皆成宴，吏散看山即有诗。
借问公方与文道，而今中夏更传谁。','',''),('quantangshi-36190','送叶秀才赴举兼呈吕少监','方干','quantangshi','','卷37','君辞旧里一年期，艺至心身亦自知。
尊尽离人看北斗，月寒惊鹊绕南枝。
书回册市砧应绝，棹出村潭菊未衰。
与尔相逢终不远，昨闻秘监在台墀。','',''),('quantangshi-36191','自缙云赴郡溪流百里轻棹一发曾不崇朝叙事四韵寄献段郎中','方干','quantangshi','','卷37','激箭溪湍势莫凭，飘然一叶若为乘。
仰瞻青壁开天罅，斗转寒湾避石棱。
巢鸟夜惊离岛树，啼猿昼怯下岩藤。
此中明日寻知己，恐似龙门不易登。','',''),('quantangshi-36192','胡中丞早梅','方干','quantangshi','','卷37','不独闲花不共时，一株寒艳尚参差。
凌晨未喷含霜朵，应候先开亚水枝。
芬郁合将兰竝茂，凝明应与雪相宜。
谢公吟赏愁飘落，可得更拈长笛吹。','',''),('quantangshi-36193','牡丹','方干','quantangshi','','卷37','借问庭芳早晚栽，座中疑展画屏开。
花分浅浅胭脂脸，叶堕殷殷腻粉腮。
红砌不须夸芍药，白苹何用逞重台。
殷勤为报看花客，莫学游蜂日日来。','',''),('quantangshi-36194','观项信水墨','方干','quantangshi','','卷37','险峭虽从笔下成，精能皆自意中生。
倚云孤桧知无朽，挂壁高泉似有声。
转扇惊波连岸动，回灯落日向山明。
小年师祖过今祖，异域应传项信名。','',''),('quantangshi-36195','书桃花坞周处士壁','方干','quantangshi','','卷37','醉吟雪月思深苦，思苦神劳华髪生。
自学古贤修静节，唯应野鹤识高情。
细泉出石飞难尽，孤烛和云湿不明。
何事嬾于嵇叔夜，更无书札答公卿。','',''),('quantangshi-36196','题桐庐谢逸人江居','方干','quantangshi','','卷37','少小高眠无一事，五侯勋盛欲如何。
湖边倚仗寒吟苦，石上横琴夜醉多。
鸟自树梢随果落，人从窗外卸帆过。
由来朝市为真隐，可要栖身向薜萝。','',''),('quantangshi-36197','叙雪寄喻凫','方干','quantangshi','','卷37','密片无声急复迟，纷纷犹胜落花时。
从容不觉藏苔迳，宛转偏宜傍柳丝。
透室虚明非月照，满空回散是风吹。
高人坐卧才方逸，援笔应成六出词。','',''),('quantangshi-36198','又叙雪寄喻凫','方干','quantangshi','','卷37','密片繁声旋不销，萦风杂霰转飘颻。
澄江莫蔽长流色，衰柳难黏自动条。
湿气添寒酤酒夜，素花迎曙卷帘朝。
此时明迳无行迹，唯望徽之问寂寥。','',''),('quantangshi-36199','哭秘书姚少监','方干','quantangshi','','卷37','寒空此夜落文星，星落文留万古名。
入室几人成弟子，为儒是处哭先生。
家无谏草逢明代，国有遗篇续正声。
晓向平原陈葬礼，悲风吹雨湿铭旌。','',''),('quantangshi-36200','送人宰永泰','方干','quantangshi','','卷37','北人虽泛南流水，称意南行莫恨赊。
道路先经毛竹岭，风烟渐近刺桐花。
舟停渔浦犹为客，县入樵溪似到家。
下马政声王事少，应容闲吏日高衙。','',''),('quantangshi-36201','旅次洋州寓居郝氏林亭','方干','quantangshi','','卷37','举目纵然非我有，思量似在故山时。
鹤盘远势投孤屿，蝉曳残声过别枝。
凉月照窗欹枕倦，澄泉遶石泛觞迟。
青云未得平行去，梦到江南身旅羇。','',''),('quantangshi-36202','茅山赠洪拾遗','方干','quantangshi','','卷37','圣代谏臣停谏舌，求归故里傲云霞。
溪头讲树缆渔艇，箧里朝衣输酒家。
但爱身闲辞禄俸，那嫌岁计在桑麻。
我来幸与诸生异，问答时容近绛纱。','',''),('quantangshi-36203','睦州吕郎中郡中环溪亭','方干','quantangshi','','卷37','为是仙才登望处，风光便似武陵春。
闲花半落犹迷蝶，白鸟双飞不避人。
树影兴余侵枕簟，荷香坐久着衣巾。
暂来此地非多日，明主那容借寇恂。','',''),('quantangshi-36204','赠华阴隐者','方干','quantangshi','','卷37','少微夜夜当仙掌，更有何人在此居。
花月旧应看浴鹤，松萝本自伴删书。
素琴醉去经宵枕，衰髪寒来向日梳。
故国多年归未遂，因逢此地忆君庐。','',''),('quantangshi-36205','上杭州杜中丞','方干','quantangshi','','卷37','昔用雄才登上第，今将重德合明君。
苦心多为安民术，援笔皆成出世文。
寒角细吹孤峤月，秋涛横卷半江云。
掠天逸势应非久，一鹗那栖众鸟羣。','',''),('quantangshi-36206','赠处州段郎中','方干','quantangshi','','卷37','幸见仙才领郡初，郡城孤峭似仙居。
杉萝色里游亭榭，瀑布声中阅簿书。
德重自将天子合，情高元与世人疎。
寒潭是处清连底，宾席何心望食鱼。','',''),('quantangshi-36207','书法华寺上方禅壁','方干','quantangshi','','卷37','砌下松巅有鹤栖，孤猿亦在鹤边啼。
卧闻雷雨归岩早，坐见星辰去地低。
一迳穿缘应就郭，千花掩映似无溪。
是非生死多忧恼，此日蒙师为破迷。','',''),('quantangshi-36208','书吴道隐林亭','方干','quantangshi','','卷37','藓榭莎亭萝筱阴，依稀气象似山林。
橘枝亚路黄苞重，井脉牵湖碧甃深。
稚子遮门留熟客，惊蝉入座避游禽。
四邻不见孤高处，翻笑腾腾只醉吟。','',''),('quantangshi-36209','陪王大夫泛湖','方干','quantangshi','','卷37','去去凌晨回见星，木兰舟稳画桡轻。
白波潭上鱼龙气，红树林中鸡犬声。
蜜炬烧残银汉昃，羽觞飞急玉山倾。
此时检点诸名士，却是渔翁无姓名。','',''),('quantangshi-36210','赠会稽张少府','方干','quantangshi','','卷37','高节何曾似任官，药苗香洁备常餐。
一分酒户添犹得，五字诗名隐即难。
笑我无媒生鹤髪，知君有意忆渔竿。
明年莫便还家去，镜里云山且共看。','',''),('quantangshi-36211','送郑台处士归绛岩','方干','quantangshi','','卷37','荣启先生挟琴去，厌寻灵胜忆岩栖。
白猿垂树窗边月，红鲤惊钩竹外溪。
惯采药苗供野馔，曾书蕉叶寄新题。
古贤犹怆河梁别，未可怱怱便解携。','',''),('quantangshi-36212','因话天台胜异仍送罗道士','方干','quantangshi','','卷37','积翠千层一径开，遥盘山腹到琼台。
藕花飘落前岩去，桂子流从别洞来。
石上丛林碍星斗，窗边瀑布走风雷。
纵云孤鹤无留滞，定恐烟萝不放回。','',''),('quantangshi-36213','哭喻凫先辈','方干','quantangshi','','卷37','日夜役神多损寿，先生下世未中年。
撰碑纵托登龙伴，营奠应支卖鹤钱。
孤壠阴风吹细草，空窗湿气渍残篇。
人间别更无冤事，到此谁能与问天。','',''),('quantangshi-36214','湖北有茅斋湖西有松岛轻棹往返颇谐素心因成四韵','方干','quantangshi','','卷37','湖北湖西往复还，朝昏只处自由间。
暑天移榻就深竹，月夜乘舟归浅山。
遶砌紫鳞欹枕钓，垂檐野果隔窗攀。
古贤暮齿方如此，多笑愚儒鬓未斑。','',''),('quantangshi-36215','鉴湖西岛言事','方干','quantangshi','','卷37','慵拙幸便荒僻地，纵听猨鸟亦何愁。
偶斟药酒欺梅雨，却着寒衣过麦秋。
岁计有时添橡实，生涯一半在渔舟。
世人若便无知己，应向此溪成白头。','',''),('quantangshi-36216','山中言事','方干','quantangshi','','卷37','欹枕亦吟行亦醉，卧吟行醉更何营。
贫来犹有故琴在，老去不过新髪生。
山鸟踏枝红果落，家童引钓白鱼惊。
潜夫自有孤云侣，可要王侯知姓名。','',''),('quantangshi-36217','赠萧山彭少府','方干','quantangshi','','卷37','作尉孜孜更寒苦，操心至癖不为清。
虽将剑鹤支残债，犹有歌篇取盛名。
尽拟勤求为弟子，皆将疑义问先生。
与君相识因儒术，岁月弥多别有情。','',''),('quantangshi-36218','赠式上人','方干','quantangshi','','卷37','纵居鼙角喧阗处，亦共云溪邃僻同。
万虑全离方寸内，一生多在五言中。
芰荷叶上难停雨，松桧枝间自有风。
莫笑旅人终日醉，吾将大醉与禅通。','',''),('quantangshi-36219','赠钱塘湖上唐处士','方干','quantangshi','','卷37','我爱君家似洞庭，冲湾泼岸夜波声。
蟾蜍影里清吟苦，舴艋舟中白发生。
常共酒杯为侣伴，复闻纱帽见公卿。
莫言举世无知己，自有孤云识此情。','',''),('quantangshi-36220','山中言事','方干','quantangshi','','卷37','日与村家事渐同，烧松啜茗学邻翁。
池塘月撼芙蕖浪，窗户凉生薜荔风。
书幌昼昏岚气里，巢枝俯折雪声中。
山阴钓叟无知己，窥镜挦多鬓欲空。','',''),('quantangshi-36221','题陶详校书阳羡隐居','方干','quantangshi','','卷37','芸香署里从容步，阳羡山中啸傲情。
竿底紫鳞输钓伴，花边白犬吠流莺。
长潭五月含冰气，孤桧中宵学雨声。
便泛扁舟应未得，鸱夷弃相始垂名。','',''),('quantangshi-36222','秋晚林中寄宾幕','方干','quantangshi','','卷37','八月萧条九月时，沙蝉海燕各分飞。
杯盂未称尝生酒，砧杵先催试熟衣。
泉漱玉声冲石窦，橘垂朱实压荆扉。
无过纵有家山思，印绶留连争得归。','',''),('quantangshi-36223','与乡人鉴休上人别','方干','quantangshi','','卷37','此日因师话乡里，故乡风土我偏谙。
一枝竹叶如溪北，半树梅花似岭南。
山夜猎徒多信犬，雨天村舍未催蚕。
如今休作还家意，两须垂丝已不堪。','',''),('quantangshi-36224','送王霖赴举','方干','quantangshi','','卷37','自古主司看荐士，明年应是不参差。
须凭吉梦为先兆，必恐长才偶盛时。
北阙上书冲雪早，西陵中酒趂潮迟。
郄诜可要真消息，只向春前便得知。','',''),('quantangshi-36225','思越中旧游寄友','方干','quantangshi','','卷37','甸外山川无越国，依稀只似剑门西。
镜中叠浪摇星斗，城上繁花咽鼓鼙。
断臂青猿啼玉笥，成行白鸟下耶溪。
此中曾是同游处，迢递寻君梦不迷。','',''),('quantangshi-36226','陪胡中丞泛湖','方干','quantangshi','','卷37','仙舟仙药醉行春，上界稀逢下界人。
绮绣峰前闻野鹤，旌旗影里见游鳞。
澄潭彻底齐心镜，杂树含芳让锦茵。
凡许从容谁不幸，就中光显是州民。','',''),('quantangshi-36227','叙雪献员外','方干','quantangshi','','卷37','纷纭宛转更堪看，压竹摧巢井径漫。
风柳细条粘不得，春溪绿色蔽应难。
清辉直认中庭月，湿气偏添半夜寒。
谢守来吟才更逸，郢词先至彩毫端。','',''),('quantangshi-36228','王将军','方干','quantangshi','','卷37','大志无心守章句，终怀上畧致殊功。
保宁帝业青萍在，投弃儒书绛帐空。
密雪曙连葱岭道，青松夜起柳营风。
将星依旧当文座，应念愚儒命未通。','',''),('quantangshi-36229','阳亭言事献漳州于使君','方干','quantangshi','','卷37','重叠山前对酒罇，腾腾兀兀度朝昏。
平明疎磬白云寺，遥夜孤砧红叶村。
去鸟岂知烟树远，惊鱼应觉露荷翻。
旅人寄食逢黄菊，每见故人思故园。','',''),('quantangshi-36230','海石榴','方干','quantangshi','','卷37','亭际夭妍日日看，每朝颜色一般般。
满枝犹待春风力，数朵先欺腊雪寒。
舞蝶似随歌拍转，游人只怕酒杯干。
久长年少应难得，忍不丛边到夜观。','',''),('quantangshi-36231','嘉兴许明府','方干','quantangshi','','卷37','檇李转闻风教好，重门夜不上重关。
腰悬墨绶三年外，身去青云一步间。
勤苦字人酬帝力，从容对客问家山。
升沈路别情犹在，不忘乡中旧往还。','',''),('quantangshi-36232','再题路支使南亭','方干','quantangshi','','卷37','行处避松兼碍石，即须门径落斜开。
爱邀旧友看渔钓，贪听新禽驻酒杯。
树影不随明月去，溪声常送落花来。
睡时分得江淹梦，五色毫端弄逸才。','',''),('quantangshi-36233','路支使小池','方干','quantangshi','','卷37','广狭偶然非制定，犹将方寸像沧溟。
一泓春水无多浪，数尺晴天几个星。
露满玉盘当半夜，匣开金镜在中庭。
主人垂钓常来此，虽把鱼竿醉未醒。','',''),('quantangshi-36234','哭江西处士陈陶','方干','quantangshi','','卷37','寿尽天年命不通，钓溪吟月便成翁。
虽云挂剑来坟上，亦恐藏书在壁中。
巢父精灵归大夜，客儿才调振遗风。
南华至理须齐物，生死即应无异同。','',''),('quantangshi-36235','越中言事二首 一','方干','quantangshi','','卷37','异术闲和合圣明，湖光浩气共澄清。
郭中云吐啼猿寺，山上花藏调角城。
香起荷湾停棹饮，丝垂柳陌约鞭行。
游人今日又明日，不觉镜中新髪生。','',''),('quantangshi-36236','越中言事二首 二','方干','quantangshi','','卷37','云霞水木共苍苍，元化分功秀一方。
百里湖波轻撼月，五更军角慢吹霜。
沙边贾客喧鱼市，岛上潜夫醉笋庄。
终岁逍遥仁术内，无名甘老买臣乡。','',''),('quantangshi-36237','题龙瑞观兼呈徐尊师','方干','quantangshi','','卷37','或雨或云常不定，地灵云雨自无时。
世人莫识神方字，仙鸟偏栖药树枝。
远壑度年如晦暝，阴溪入夏有凌澌。
此中唯有师知我，未得寻师即梦师。','',''),('quantangshi-36238','送陈秀才将游霅上便议北归','方干','quantangshi','','卷37','婆娑恋酒山花尽，绕缭还家水路通。
转檝拟从青草岸，吹帆犹是白苹风。
淮边欲暝军鼙急，洛下先寒苑树空。
诗句因余更孤峭，书题不合忘江东。','',''),('quantangshi-36239','送吴彦融赴举','方干','quantangshi','','卷37','用心精至自无疑，千万人中似汝稀。
上国才将五字去，全家便待一枝归。
西陵柳路摇鞭尽，北固潮程挂席飞。
想见明年榜前事，当时分散着来衣。','',''),('quantangshi-36240','同萧山陈长官县楼登望','方干','quantangshi','','卷37','坐看南北与西东，远近无非礼义中。
一县繁花香送雨，五株垂柳绿牵风。
寒涛背海喧还静，驿路穿林断复通。
仲叔受恩多感恋，裴回却怕酒壶空。','',''),('quantangshi-36241','送何道者','方干','quantangshi','','卷37','何事忽来还忽去，孤云不定鹤情高。
真经与术添年寿，灵药分功入鬓毛。
必拟一身生羽翼，终看陆地作波涛。
遍寻岩洞求仙者，即恐无人似尔曹。','',''),('quantangshi-36242','酬将作于少监','方干','quantangshi','','卷37','由来至宝出毫端，五色炎光照室寒。
仰望孤峰知耸峻，前临积水见波澜。
冰丝织络经心久，瑞玉雕磨措手难。
不是散斋兼拭目，寻常未便借人看。','',''),('quantangshi-36243','雪中寄殷道士','方干','quantangshi','','卷37','大片纷纷小片轻，雨和风击更纵横。
园林入夜寒光动，窗户凌晨湿气生。
蔽野吞村飘未歇，摧巢压竹密无声。
山阴道士吟多兴，六出花边五字成。','',''),('quantangshi-36244','宋从事','方干','quantangshi','','卷37','出众仙才是谪仙，裁霞曳绣一篇篇。
虽将洁白酬知己，自有风流助少年。
欹枕卧吟荷叶雨，持杯坐醉菊花天。
冥搜太苦神应乏，心在虚无更那边。','',''),('quantangshi-36245','出山寄苏从事','方干','quantangshi','','卷37','寸心似火频求荐，两鬓如霜始息机。
隔岸鸡鸣春耨去，邻家犬吠夜渔归。
倚松长啸宜疎拙，拂石欹眠绝是非。
多谢元瑜怜野贱，时回车马发光辉。','',''),('quantangshi-36246','送杭州李员外','方干','quantangshi','','卷37','政成何用满三年，上界羣仙待谪仙。
便赴新恩归紫禁，还从旧路上青天。
笙歌怨咽当离席，更漏丁东在画船。
必恐驻班留立位，前程一步是炉烟。','',''),('quantangshi-36247','赠李支使','方干','quantangshi','','卷37','药成平地是寥天，三十人中最少年。
白雪振声来辇下，青云开路到牀前。
公卿位近应翘足，荀宋才微可拍肩。
一等孔门为弟子，愚儒独自赋归田。','',''),('quantangshi-36248','卢卓山人画水','方干','quantangshi','','卷37','常闻画石不画水，画水至难君得名。
海色未将蓝汁染，笔锋犹傍墨花行。
散吞高下应无岸，斜蹙东南势欲倾。
坐久神迷不能决，却疑身在小蓬瀛。','',''),('quantangshi-36249','废宅','方干','quantangshi','','卷37','主人何处独裴回，流水自流花自开。
若见故交皆散去，即应新燕不归来。
入门缭绕穿荒竹，坐石逡巡染绿苔。
应是曾经恶风雨，修桐半折损琴材。','',''),('quantangshi-36250','题宝林山禅院','方干','quantangshi','','卷37','山捧亭台郭遶山，遥盘苍翠到山巅。
岩中古井虽通海，窟里阴云不上天。
罗列众星依木末，周回万室在檐前。
我来可要归禅老，一寸寒灰已达玄。','',''),('quantangshi-36251','题越州袁秀才林亭','方干','quantangshi','','卷37','清邃林亭指画开，幽岩别派像天台。
坐牵蕉叶题诗句，醉触藤花落酒杯。
白鸟不归山里去，红鳞多自镜中来。
终年此地为吟伴，早起寻君薄暮回。','',''),('quantangshi-36252','题龟山穆上人院','方干','quantangshi','','卷37','修持百法过半百，日往月来心更坚。
牀上水云随坐夏，林西山月伴行禅。
寒蜩远韵来窗里，白鸟斜行起砌边。
我爱寻师师访我，只应寻访是因缘。','',''),('quantangshi-36253','赠美人四首 一','方干','quantangshi','','卷37','直缘多艺用心劳，心路玲珑格调高。
舞袖低徊真蛱蝶，朱唇深浅假樱桃。
粉胸半掩疑晴雪，醉眼斜回小样刀。
才会雨云须别去，语慙不及琵琶槽。','',''),('quantangshi-36254','赠美人四首 二','方干','quantangshi','','卷37','严冬忽作看花日，盛暑翻为见雪时。
坐上弄娇声不转，尊前掩笑意难知。
含歌媚盼如桃叶，妙舞轻盈似柳枝。
年几未多犹怯在，些些私语怕人疑。','',''),('quantangshi-36255','赠美人四首 三','方干','quantangshi','','卷37','酒蕴天然自性灵，人间有艺总关情。
剥葱十指转筹疾，舞柳细腰随拍轻。
常恐胸前春雪释，惟愁座上庆云生。
若教梅尉无仙骨，争得仙娥驻玉京。','',''),('quantangshi-36256','赠美人四首 四','方干','quantangshi','','卷37','昔日仙人今玉人，深冬相见亦如春。
倍酬金价微含笑，才发歌声早动尘。
昔岁曾为萧史伴，今朝应作宋家邻。
百年别后知谁在，须遣丹青画取真。','',''),('quantangshi-36257','听段处士弹琴','方干','quantangshi','','卷37','几年调弄七条丝，元化分功十指知。
泉迸幽音离石底，松含细韵在霜枝。
窗中顾兔初圆夜，竹上寒蝉尽散时。
唯有此时心更静，声声可作后人师。','',''),('quantangshi-36258','初归镜中寄陈端公','方干','quantangshi','','卷37','去岁离家今岁归，孤帆梦向鸟前飞。
必知芦笋侵沙井，兼被藤花占石矶。
云岛采茶常失路，雪龛中酒不关扉。
故交若问逍遥事，玄冕何曾胜苇衣。','',''),('quantangshi-36259','再题龙泉寺上方','方干','quantangshi','','卷37','牛斗正齐羣木末，鸟行横截众山腰。
路盘砌下兼穿竹，井在岩头亦统潮。
海岸四更看日出，石房三月任花烧。
未能割得繁华去，难向此中甘寂寥。','',''),('quantangshi-36260','于秀才小池','方干','quantangshi','','卷37','一泓潋灧复澄明，半日功夫斸小庭。
占地未过四五尺，浸天唯入两三星。
鷁舟草际浮霜叶，[渔]火沙边驻小萤。
才见规模识方寸，知君立意象沧溟。','',''),('quantangshi-36261','叙钱塘异胜','方干','quantangshi','','卷37','暖景融融寒景清，越台风送晓钟声。
四郊远火烧烟月，一道惊波撼郡城。
夜雪未知东岸绿，春风犹放半江晴。
谢公吟处依稀在，千古无人继盛名。','',''),('quantangshi-36262','赠中岩王处士','方干','quantangshi','','卷37','垂杨褭褭草芊芊，气象清深似洞天。
援笔便成鹦鹉赋，洗花须用桔槔泉。
商于避世堪同日，渭曲逢时必有年。
直恐刚肠闲未得，醉吟争奈被才牵。','',''),('quantangshi-36263','初归故里献侯郎中','方干','quantangshi','','卷37','常思旧里欲归难，已作归心即自宽。
此日早知无爵位，当时便合把渔竿。
朝昏入闰春将逼，城邑多山夏却寒。
不是幽愚望荣忝，君侯异礼亦何安。','',''),('quantangshi-36264','归睦州中路寄侯郎中','方干','quantangshi','','卷37','颜巷萧条知命后，膺门感激受恩初。
却容鹤髪还蜗舍，犹梦渔竿从隼旟。
新定暮云吞故国，会稽春草入贫居。
乡中自古为儒者，谁得公侯降尺书。','',''),('quantangshi-36265','题报恩寺上方','方干','quantangshi','','卷37','来来先上上方看，眼界无穷世界宽。
岩溜喷空晴似雨，林萝碍日夏多寒。
众山迢递皆相叠，一路高低不记盘。
清峭关心惜归去，他时梦到亦难判。','',''),('quantangshi-36266','送永嘉王令之任二首 一','方干','quantangshi','','卷37','定拟孜孜化海边，须判素髪侮流年。
波涛不应双溪水，分野长如二月天。
浮客若容开荻地，钓翁应免税苔田。
前贤未必全堪学，莫读当时归去篇。','',''),('quantangshi-36267','送永嘉王令之任二首 二','方干','quantangshi','','卷37','虽展县图如到县，五程犹入缙云东。
山间阁道盘岩底，海界孤峰在浪中。
礼法未闻离汉制，土宜多说似吴风。
字人若用非常术，唯要旬时便立功。','',''),('quantangshi-36268','盐官王长官新创瑞隐亭','方干','quantangshi','','卷37','指画便分元化力，周回秀绝自清机。
孤云恋石寻常住，落絮萦风特地飞。
雏鸟啼花催酿酒，惊鱼溅水误沾衣。
明年秩满难将去，何似先教画取归。','',''),('quantangshi-36269','李户曹小妓天得善击越器以成曲章','方干','quantangshi','','卷37','越器敲来曲调成，腕头匀滑自轻清。
随风摇曳有余韵，测水浅深多泛声。
昼漏丁当相续滴，寒蝉计会一时鸣。
若教进上梨园去，众乐无由更擅名。','',''),('quantangshi-36270','岁晚言事寄乡中亲友','方干','quantangshi','','卷37','急景苍茫昼若昏，夜风干峭触前轩。
寒威半入龙蛇窟，暖气全归草树根。
蜡烬凝来多碧焰，香醪滴处有冰痕。
尺书未达年应老，先被新春入故园。','',''),('quantangshi-36271','赠孙百篇','方干','quantangshi','','卷37','御题百首思纵横，半日功夫举世名。
羽冀便从吟处出，珠玑续向笔头生。
莫嫌黄绶官资小，必料青云道路平。
才子风流复年少，无愁高卧不公卿。','',''),('quantangshi-36272','赠夏侯评事','方干','quantangshi','','卷37','傍窥盛德与高节，缅想应无前后人。
讲论参同深到骨，停腾姹女立成银。
棊功过却杨玄宝，易义精于梅子真。
朱紫侯门犹不见，可知岐路有风尘。','',''),('quantangshi-36273','送郑端公','方干','quantangshi','','卷37','圣主伫知宣室事，岂容才子滞长沙。
随珠此去方酬德，赵璧当时误指瑕。
骢马将离江浦月，绣衣却照禁中花。
应怜寂寞沧洲客，烟汉尘泥相去赊。','',''),('quantangshi-36274','题故人废宅二首 一','方干','quantangshi','','卷37','举目凄凉入破门，鲛人一饭尚知恩。
闲花旧识犹含笑，怪石无情更不言。
樵叟和巢伐桃李，牧童兼草踏兰荪。
壶觞笑咏随风去，唯有声声蜀帝魂。','',''),('quantangshi-36275','题故人废宅二首 二','方干','quantangshi','','卷37','寒莎野树入荒庭，风雨萧萧不掩扃。
旧径已知无孟竹，前溪应不浸荀星。
精灵消散归寥廓，功业传留在志铭。
薄暮停车更凄怆，山阳隣笛若为听。','',''),('quantangshi-36276','寄于少监','方干','quantangshi','','卷37','修持清苦振佳声，众鸟那知一鹗情。
蹑履三千皆后学，抟风九万即前程。
名将日月同时朽，身是山河应数生。
从此云泥更悬阔，渔翁不合见公卿。','',''),('quantangshi-36277','和剡县陈明府登县楼','方干','quantangshi','','卷37','郭里人家如掌上，檐前树木映窗棂。
烟霞若接天台地，分野应侵婺女星。
驿路古今通北阙，仙溪日夜入东溟。
彩衣才子多吟啸，公退时时见画屏。','',''),('quantangshi-36278','项洙处士画水墨钓台','方干','quantangshi','','卷37','画石画松无两般，犹嫌瀑布画声难。
虽云智惠生灵府，要且功夫在笔端。
泼处便连阴洞黑，添来先向朽枝干。
我家曾寄双台下，往往开图尽日看。','',''),('quantangshi-36279','赠天台叶尊师','方干','quantangshi','','卷37','莫见平明离少室，须知薄暮入天台。
常时爱缩山川去，有夜自携星月来。
灵药不知何代得，古松应是长年栽。
先生暗笑看棊者，半局棊边白发催。','',''),('quantangshi-36280','寄台州孙从事百篇','方干','quantangshi','','卷37','圣世科名酬志业，仙州秀色助神机。
梅真入仕提雄笔，阮瑀从军着彩衣。
昼寝不知山雪积，春游应趁夜潮归。
相思莫讶音书晚，鸟去犹须叠日飞。','',''),('quantangshi-36281','送睦州侯郎中赴阙','方干','quantangshi','','卷37','昔着政声闻国外，今留儒术化江东。
青云旧路归仙掖，白凤新词入圣聪。
弦管未知银烛晓，旌旗已侍锦帆风。
郡人难议酬恩德，徧在三年礼遇中。','',''),('quantangshi-36282','朱秀才庭际蔷薇','方干','quantangshi','','卷37','绣难相似画难真，明媚鲜妍绝比伦。
露压盘条方到地，风吹艳色欲烧春。
断霞转影侵西壁，浓麝分香入四邻。
看取后时归故里，庭花应让锦衣新。','',''),('quantangshi-36283','登龙瑞观北岩','方干','quantangshi','','卷37','纵目下看浮世事，方知峭崿与天通。
湖边风力归帆上，岭顶云根在雪中。
促韵寒钟催落照，斜行白鸟入遥空。
前人去后后人至，今古异时登眺同。','',''),('quantangshi-36284','送婺州许录事','方干','quantangshi','','卷37','之官便是还乡路，白日堂堂着锦衣。
八咏遗风资逸兴，二溪寒色助清威。
曙星没尽提纲去，暝角吹残鏁印归。
笑我中年更愚僻，醉醒多在钓渔矶。','',''),('quantangshi-36285','题龙泉寺绝顶','方干','quantangshi','','卷37','未明先见海底日，良久远鸡方报晨。
古树含风长带雨，寒岩四月始知春。
中天气爽星河近，下界时丰雷雨匀。
前后登临思无尽，年年改换去来人。','',''),('quantangshi-36286','赠上虞胡少府百篇','方干','quantangshi','','卷37','求仙不在炼金丹，轻举由来别有门。
日晷未移三十刻，风骚已及四千言。
宏才尚遣居卑位，公道何曾雪至冤。
歛板尘中无恨色，应缘利禄副晨昏。','',''),('quantangshi-36287','上郑员外','方干','quantangshi','','卷37','为郡至公兼至察，古今能有几多人。
忧民一似清吟苦，守节还如未达贫。
利刃从前堪切玉，澄潭到底不容尘。
潜夫岂合干旌斾，甘棹渔舟下钓纶。','',''),('quantangshi-36288','桐庐江阁','方干','quantangshi','','卷37','风烟百变无定态，缅想画人虚损心。
卷箔槛前沙鸟散，垂钩牀下锦鳞沈。
白云野寺凌晨磬，红树孤村遥夜砧。
此地四时抛不得，非唯盛暑事开襟。','',''),('quantangshi-36289','题澄圣塔院上方','方干','quantangshi','','卷37','地灵直是饶风雨，杉桧老于云雨间。
只讶窗中常见海，方知砌下更多山。
远泉势曲犹须引，野果枝低可要攀。
若把重门谕玄寂，何妨善闭却无关。','',''),('quantangshi-36290','僧院小泉井','方干','quantangshi','','卷37','亦恐浅深同禹穴，兼云制度象污罇。
窥寻未见泉来路，缅想应穿石裂痕。
片段似冰犹可把，澄清如镜不曾昏。
欲知到底无尘染，堪与吾师比性源。','',''),('quantangshi-36291','过姚监故居','方干','quantangshi','','卷37','不敢要君征亦起，致君全得似唐虞。
谠言昨叹离天听，新冢今闻入县图。
琴锁坏窗风自触，鹤归乔木月难呼。
学书弟子何人在，检点犹逢谏草无。','',''),('quantangshi-36292','陪李郎中夜[宴]','方干','quantangshi','','卷37','间世星郎夜[宴]时，丁丁寒漏滴声稀。
琵琶弦促千般语，鹦鹉杯深四散飞。
遍请玉容歌白雪，高烧红蜡照朱衣。
人间有此荣华事，争遣渔翁恋钓矶。','',''),('quantangshi-36293','狂寇后上刘尚书','方干','quantangshi','','卷37','孙武倾心与万夫，削平妖孽在斯须。
才施偃月行军令，便见台星逼座隅。
独柱搘天寰海正，雄名盖世古今无。
圣君争不酬功业，仗下高悬破贼图。','',''),('quantangshi-36294','尚书新创敌楼二首 一','方干','quantangshi','','卷37','下马政成无一事，应须胜地过朝昏。
笙歌引出桃花洞，罗绣拥来金谷园。
十里水云吞半郭，九秋山月入千门。
常闻大厦堪栖息，燕雀心知不敢言。','',''),('quantangshi-36295','尚书新创敌楼二首 二','方干','quantangshi','','卷37','异境永为欢乐地，歌钟夜夜复年年。
平明旭日生牀底，薄暮残霞落酒边。
虽向槛前窥下界，不知窗里是中天。
直须分付丹青手，画出旌幢遶谪仙。','',''),('quantangshi-36296','赠李郢端公','方干','quantangshi','','卷37','非唯孤峭与世绝，吟处斯须能变通。
物外搜罗归大雅，毫端剪削有余功。
山川正气侵灵府，雪月清辉引思风。
别得人间上升术，丹霄路在五言中。','',''),('quantangshi-36297','送孙百篇游天台','方干','quantangshi','','卷37','东南云路落斜行，入树穿村见赤城。
远近常时皆药气，高低无处不泉声。
映岩日向牀头没，湿烛云从柱底生。
更有仙花与灵鸟，恐君多半未知名。','',''),('quantangshi-36298','陆山人画水','方干','quantangshi','','卷37','毫末用功成一水，水源山脉固难寻。
逡巡便可见波浪，咫尺不能知浅深。
但有片云生海口，终无明月在潭心。
我来拟学磻溪叟，白首钓璜非陆沈。','',''),('quantangshi-36299','郭中山居','方干','quantangshi','','卷37','莫见一瓢离树上，犹须四壁在林间。
沈吟不寐先闻角，屈曲登高自有山。
溅石迸泉听未足，亚窗红果卧堪攀。
公卿若便遗名姓，却与禽鱼作往还。','',''),('quantangshi-36300','雪中寄李知诲判官','方干','quantangshi','','卷37','聚散联翩急复迟，解将华髪两相欺。
虽云竹重先藏路，却讶巢倾不损枝。
入户便从风起后，照窗翻似月明时。
此时门巷无行迹，尘满尊罍谁得知。','',''),('quantangshi-36301','途中言事寄居远上人','方干','quantangshi','','卷37','举目时时似故园，乡心自动向谁言。
白云晓湿寒山寺，红叶夜飞明月村。
震泽风帆归橘岸，钱塘水府抵城根。
羡师了达无牵束，竹径生苔掩竹门。','',''),('quantangshi-36302','雪中寄薛郎中','方干','quantangshi','','卷37','野禽未觉巢枝仄，稚子先忧径竹摧。
半夜忽明非月午，前庭旋释被春摧。
碎花若入樽中去，清气应归笔底来。
深拥红炉听仙乐，忍教愁坐画寒灰。','',''),('quantangshi-36303','题盛令新亭','方干','quantangshi','','卷37','举目岂知新智慧，存思便是小天台。
偶尝嘉果求枝去，因问名花寄种来。
春物诱才归健笔，夜歌牵醉入丛杯。
此中难遇逍遥事，计日应为印绶催。','',''),('quantangshi-36304','赠郑仁规','方干','quantangshi','','卷37','一石雄才独占难，应分二斗借人寰。
澄心不出风骚外，落笔全归教化间。
莲幕未来须更聘，桂枝才去即先攀。
可怜丽句能飞动，荀宋精灵亦厚颜。','',''),('quantangshi-36305','送缙陵王少府赴举','方干','quantangshi','','卷37','相看不忍尽离觞，五两牵风速去樯。
远驿新砧应弄月，初程残角未吹霜。
越山直下分吴苑，淮水横流入楚乡。
珍重郄家好兄弟，明年禄位在何方。','',''),('quantangshi-36306','路入剡中作','方干','quantangshi','','卷37','截湾冲濑片帆通，高枕微吟到剡中。
掠草并飞怜燕子，停桡独饮学渔翁。
波涛漫撼长潭月，杨柳斜牵一岸风。
便拟乘槎应去得，仙源直恐接星东。','',''),('quantangshi-36307','东山瀑布','方干','quantangshi','','卷37','遥夜看来疑月照，平明失去被云迷。
挂岩远势穿松岛，击石残声注稻畦。
素色喷成三伏雪，余波流作万年溪。
不缘真宰能开决，应向前山杂淤泥。','',''),('quantangshi-36308','水墨松石','方干','quantangshi','','卷37','三世精能举世无，笔端狼籍见功夫。
添来势逸阴崖黑，泼处痕轻灌木枯。
垂地寒云吞大漠，过江春雨入全吴。
兰堂坐久心弥惑，不道山川是画图。','',''),('quantangshi-36309','献浙东王大夫二首 一','方干','quantangshi','','卷37','出镇当时移越俗，致君何日不尧年。
到来唯饮长溪水，归去应将一个钱。
吟处美人擎笔砚，行时飞鸟避旌旃。
四方皆是分忧寄，独有东南戴二天。','',''),('quantangshi-36310','献浙东王大夫二首 二','方干','quantangshi','','卷37','王臣夷夏仰清名，领镇犹为失意行。
已见玉璜曾上钓，何愁金鼎不和羹。
誉将星月同时朽，身应山河满数生。
泥滓云霄至悬阔，渔翁不合见公卿。','',''),('quantangshi-36311','越州使院竹','方干','quantangshi','','卷37','莫见凌风飘粉箨，须知碍石作盘根。
细看枝上蝉吟处，犹是笋时虫蚀痕。
月送绿阴斜上砌，露凝寒色湿遮门。
列仙终日逍遥地，鸟雀潜来不敢喧。','',''),('quantangshi-36312','题赠李校书','方干','quantangshi','','卷37','名场失手一年年，月桂尝闻到手边。
谁道高情偏似鹤，自云长啸不如蝉。
众花交艳多成实，深井通潮半杂泉。
却是偶然行未到，元来有路上寥天。','',''),('quantangshi-36313','送王侍郎浙东入朝','方干','quantangshi','','卷37','自将苦节酬清秩，肯要庞眉一个钱。
恩爱已苏句践国，程途却上大罗天。
鱼池菊岛还公署，沙鹤松栽入画船。
密奏无非经济术，从容几刻在炉烟。','',''),('quantangshi-36314','赠黄处士','方干','quantangshi','','卷37','闭户先生无是非，竹湾松树藕苗衣。
愁吟密雪思难尽，醉倒残花扶不归。
若出薜萝迎鹤简，应抛舴艋别渔矶。
到头苦节终何益，空改文星作少微。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-36315','献王大夫二首 一','方干','quantangshi','','卷37','都缘声价振皇州，高卧中条不自由。
早副急征来凤沼，常陪内宴醉龙楼。
锵金五字能援笔，钓玉三年信直钩。
必恐借留终不遂，越人相顾已先愁。','',''),('quantangshi-36316','献王大夫二首 二','方干','quantangshi','','卷37','功成犹自更行春，塞路旌旗十里尘。
只用篇章为教化，不知夷夏望陶钧。
金章照耀浮光动，玉面生狞细步匀。
历任圣朝清峻地，至今依是少年身。','',''),('quantangshi-36317','赠五牙山人洗修白','方干','quantangshi','','卷37','变通唯在片时间，此事全由一粒丹。
若取寿长延至易，如嫌地远缩何难。
先生阔别能轻举，弟子才来学不飡。
箧里生尘是闲药，外沾犹可救衰残。','',''),('quantangshi-36318','处州献卢员外','方干','quantangshi','','卷37','才下轺车即岁丰，方知盛德与天通。
清声渐出寰瀛外，喜气全归教化中。
落地遗金终日在，经年滞狱当时空。
直缘后学无功业，不虑文翁不至公。','',''),('quantangshi-36319','石门瀑布','方干','quantangshi','','卷37','奔倾漱石亦喷苔，此是便随元化来。
长片挂岩轻似练，远声离洞咽于雷。
气含松桂千枝润，势画云霞一道开。
直是银河分派落，兼闻碎滴溅天台。','',''),('quantangshi-36320','题仙岩瀑布呈陈明府','方干','quantangshi','','卷37','方知激蹙与喷飞，直恐古今同一时。
远壑流来多石脉，寒空扑碎作凌澌。
谢公岩上冲云去，织女星边落地迟。
聚向山前更谁测，深沈见底是澄漪。','',''),('quantangshi-36321','赠山阴崔明府','方干','quantangshi','','卷37','用心何况两衙间，退食孜孜亦不闲。
压酒晒书犹检点，修琴取药似交关。
笙歌入夜舟中月，花木知春县里山。
平叔正堪汤饼试，风流不合问年颜。','',''),('quantangshi-36322','山井','方干','quantangshi','','卷37','滟滟湿光凌竹树，寥寥清气袭衣襟。
不知测穴通潮信，却讶轻涟动镜心。
夜久即疑星影过，早来犹见石痕深。
辘轳用智终何益，抱瓮遗名亦至今。','',''),('quantangshi-36323','偶作','方干','quantangshi','','卷37','直为篇章非动众，遂令轩盖不经过。
未妨溪上泛渔艇，又为门前张雀罗。
夜学事须凭雪照，朝厨争奈绝烟何。
若于岩洞求伦类，今古疎愚似我多。','',''),('quantangshi-36324','贼退后赠刘将军','方干','quantangshi','','卷37','非唯吴起与穰苴，今古推排尽不如。
白马知无髀上肉，黄巾泣向箭头书。
二年战地成桑茗，千里荒榛作比闾。
功业更多身转贵，伫看幢节引戎车。','',''),('quantangshi-36325','感时三首 一','方干','quantangshi','','卷37','不觉年华似箭流，朝看春色暮逢秋。
正嗟新冢垂青草，便见故交梳白头。
虽道了然皆是梦，应还达者即无愁。
破除生死须齐物，谁向穹苍问事由。','',''),('quantangshi-36326','感时三首 二','方干','quantangshi','','卷37','日乌往返无休息，朝出扶桑暮却回。
夜雨旋驱残热去，江风吹送早寒来。
才怜饮处飞花片，又见书边聚雪堆。
莫恃少年欺白首，须臾还被老相催。','',''),('quantangshi-36327','感时三首 三','方干','quantangshi','','卷37','世途扰扰复憧憧，真恐华夷事亦同。
岁月自消寒暑内，荣枯尽在是非中。
今朝犹作青襟子，明日还成白首翁。
堪笑愚夫足纷竞，不知流水去无穷。','',''),('quantangshi-36328','牡丹','方干','quantangshi','','卷37','不逢盛暑不冲寒，种子成丛用法难。
醉眼若为抛去得，狂心更拟折来看。
凌霜烈火吹无艳，裛露阴霞晒不干。
莫道娇红怕风雨，经时犹自未凋残。','',''),('quantangshi-36329','赠进士章碣','方干','quantangshi','','卷37','织锦虽云用旧机，抽梭起样更新奇。
何如且破望中叶，未可便攀低处枝。
藉地落花春半后，打窗斜雪夜深时。
此时才子吟应苦，吟苦鬼神知不知。','',''),('quantangshi-36330','与桐庐郑明府','方干','quantangshi','','卷37','字人心苦达神明，何止重门夜不扃。
莫道耕田全种秫，兼闻退食亦逢星。
暎林顾兔停琴望，隔水寒猨驻笔听。
却恐南山尽无石，南山有石合为铭。','',''),('quantangshi-36331','谢王大夫奏表','方干','quantangshi','','卷37','非唯言下变荣衰，大海可倾山可移。
如剖夜光归暗室，似驱春气入寒枝。
死灰到底翻腾焰，朽骨随头却长肥。
便杀微躬复何益，生成恩重报无期。','',''),('quantangshi-36332','送道人归旧岩','方干','quantangshi','','卷37','旧岩终副却归期，岩下有人应识师。
目覩婴孩成老叟，手栽松柏有枯枝。
前山低校无多地，东海浅于初去时。
若把古今相比类，姓丁仙鹤亦如斯。','',''),('quantangshi-36333','送钱特卿赴职天台','方干','quantangshi','','卷37','路入仙溪气象清，垂鞭树石罅中行。
雾昏不见西陵岸，风急先闻瀑布声。
山下县寮张乐送，海边津吏棹舟迎。
诗家弟子无多少，唯只于余别有情。','',''),('quantangshi-36334','题新竹','方干','quantangshi','','卷37','青苔斸破植贞坚，细碧竿排郁眼鲜。
小凤凰声吹嫩叶，短蛟龙尾褭轻烟。
节环腻色端匀粉，根拔秋光暗长鞭。
怪得入门肌骨冷，缀风黏月满庭前。','',''),('quantangshi-36335','哭王大夫','方干','quantangshi','','卷37','俗人皆嫉谢临川，果中常情□□□。
为政旧规方利国，降生直性已归天。
岘亭惋咽知无极，渭曲馨香莫计年。
从此心丧应毕世，忍看坟草读残篇。','',''),('quantangshi-36336','赠干素上人','方干','quantangshi','','卷37','苦用贞心传弟子，即应低眼看公卿。
水中明月无踪迹，风里浮云可计程。
庭际孤松随鹤立，窗间清磬学蝉鸣。
料师多刦长如此，岂筭前生与后生。','',''),('quantangshi-36337','题应天寺上方兼呈谦上人','方干','quantangshi','','卷37','中天坐卧见人寰，峭石垂藤不易攀。
晴卷风雷归故壑，夜和猿鸟锁寒山。
势横绿野苍茫外，影落平湖潋滟间。
师在西岩最高处，路寻之字见禅关。','',''),('quantangshi-36338','题法华寺绝顶禅家壁','方干','quantangshi','','卷37','苍翠岧嶤逼窅冥，下方雷雨上方晴。
飞流便向砌边挂，片月影从窗外行。
驯鹿不知谁结侣，野禽都是自呼名。
只应禅者无来去，坐看千山白发生。','',''),('quantangshi-36339','春日','方干','quantangshi','','卷37','春去春来似有期，日高添睡是归时。
虽将细雨催芦笋，却用东风染柳丝。
重雾已应吞海色，轻霜犹自锉花枝。
此时野客因花醉，醉卧花间应不知。','',''),('quantangshi-36340','上越州杨严中丞','方干','quantangshi','','卷37','连枝棣萼世无双，未秉鸿钧拥大邦。
折桂早闻推独步，分忧暂辍过重江。
晴寻凤沼云中树，思遶稽山枕上窗。
试把十年辛苦志，问津求拜碧油幢。','',''),('quantangshi-36341','月','方干','quantangshi','','卷37','桂轮秋半出东方，巢鹊惊飞夜未央。
海上风云摇皓影，空中露气湿流光。
斜临户牖通宵烛，回照堦墀到晓霜。
庾亮恃才高更逸，方闻墨翰已成章。','',''),('quantangshi-36342','早春','方干','quantangshi','','卷37','运行元化不参差，四极中华共一时。
正气才随灰律变，残寒便被柳条欺。
冰融大泽朝阳觉，草绿陈根夜雨知。
不信风光疾于箭，年来年去变霜髭。','',''),('quantangshi-36343','对花','方干','quantangshi','','卷37','清晓入花如步障，恋花行步步迟迟。
含风欲绽中心朵，似火应烧外面枝。
野客须𢬵终日醉，流莺自有隔年期。
使君坐处笙歌合，便是列仙身不知。','',''),('quantangshi-36344','除夜','方干','quantangshi','','卷37','玉漏斯须即达晨，四时吹转任风轮。
寒灯短烬方烧腊，画角残声已报春。
明日便为经岁客，昨朝犹是少年人。
新正定数随年减，浮世惟应百遍新。','',''),('quantangshi-36345','题松江驿','方干','quantangshi','','卷37','便向中流出太阳，兼疑大岸逼浮桑。
门前白道通丹阙，浪里青山占几乡。
帆势落斜依浦溆，钟声断续在沧茫。
古今悉不知天意，偏把云霞媚一方。','',''),('quantangshi-36346','思桐庐旧居便送鉴上人','方干','quantangshi','','卷37','莫道东南路不赊，思归一步是天涯。
林中夜半双台月，洲上春深九里花。
绿树遶村含细雨，寒潮背郭卷平沙。
闻师却到乡中去，为我殷勤谢酒家。','',''),('quantangshi-36347','送僧归日本','方干','quantangshi','','卷37','四极虽云共二仪，晦明前后即难知。
西方尚在星辰下，东域已过寅卯时。
大海浪中分国界，扶桑树底是天涯。
满帆若有归风便，到岸犹须隔岁期。','',''),('quantangshi-36348','宁国寺','方干','quantangshi','','卷37','深僻孤高无四邻，白云明月自相亲。
海中日出山先晓，世上寒轻谷未春。
窗逼野溪闻唳鹤，林通村径见樵人。
此时惟有雷居士，不厌[篮]舆去住频。','',''),('quantangshi-36349','山中寄吴磻十韵','方干','quantangshi','','卷37','莫问终休否，林中事已成。
盘餐怜火种，岁计付刀耕。
掬水皆花气，听松似雨声。
书空翘足卧，避险侧身行。
果傍闲轩落，蒲连湿岸生。
禅生知见理，妻子笑无名。
更拟教诗苦，何曾待酒清。
石溪鱼不大，月树鹊多惊。
砌下通樵路，窗间见县城。
云山任重叠，难隔故交情。','',''),('quantangshi-36350','嘉兴县内池阁','方干','quantangshi','','卷37','指画应心成，周回气象清。
牀前沙鸟语，案下锦鳞惊。
细柳风吹旋，新荷露压倾。
微芳缘岸落，迸笋入波生。
舴艋舟中醉，莓苔径上行。
高人莫归去，此处胜蓬瀛。','',''),('quantangshi-36351','镜湖西岛言事寄陶校书','方干','quantangshi','','卷37','樵猎两三户，凋疎是近邻。
风雷前壑雨，花木后岩春。
文字不得力，桑麻难救贫。
山禽欺稚子，夜犬吠渔人。
未必圣明代，长将云水亲。
知音不延荐，何路出泥尘。','',''),('quantangshi-36352','赠赵崇侍御','方干','quantangshi','','卷37','贵达合逢明圣日，风流又及少年时。
才因出众人皆嫉，势欲摩霄自不知。
正直早年闻苦节，从容此日见清规。
却教鹦鹉呼桃叶，便遣婵娟唱竹枝。
闲话篇章停烛久，醉迷歌舞出花迟。
云鸿别有回翔便，应笑啁啾燕雀卑。','',''),('quantangshi-36353','叙龙瑞观胜异寄于尊师','方干','quantangshi','','卷37','混元融结致功难，山下平湖湖上山。
万倾涵虚寒潋滟，千寻耸翠秀孱颜。
芰荷香入琴棊处，雷雨声离栋牖间。
但有五云依鹤岭，曾无陆路向人寰。
夜溪漱玉常堪听，仙树垂珠可要攀。
若弃荣名便居此，自然浮浊不相关。','',''),('quantangshi-36354','侯郎中新置西湖','方干','quantangshi','','卷37','远近利民因智力，周回润物像心源。
菰蒲纵感生成惠，鳣鲔那占广大恩。
潋滟清辉吞半郭，萦纡别派入遥村。
砂泉遶石通山脉，岸木黏萍是浪痕。
已见澄来连镜底，兼知极处浸云根。
波涛不起时方泰，舟檝徐行日易昏。
烟雾未应藏岛屿，凫鹥亦解避旌幡。
虽云桃叶歌还醉，却被荷花笑不言。
孤鹤必应思凤诏，凡鱼岂合在龙门。
能将盛事添元化，一夕机谟万古存。','',''),('quantangshi-36355','许员外新阳别业','方干','quantangshi','','卷37','兰汀橘岛映亭台，不是经心即手栽。
满阁白云随雨去，一池寒月逐潮来。
小松出屋和巢长，新迳通村避笋开。
柳絮风前欹枕卧，荷花香里棹舟回。
园中认叶封林草，檐下攀枝落野梅。
莫恣高情求逸思，须防急诏用长材。
若因萤火终残卷，便把渔歌送几杯。
多谢郢中贤太守，常时谈笑许追陪。','',''),('quantangshi-36356','李侍御上虞别业','方干','quantangshi','','卷37','满目亭台嘉木繁，燕蝉吟语不为喧。
昼潮势急吞诸岛，暑雨声回露半村。
真为援毫方掩卷，常因按曲便开尊。
若将明月为俦侣，应把清风遗子孙。
绣羽惊弓离果上，红鳞见饵出蒲根。
寻君未要先敲竹，且棹渔舟入大门。','',''),('quantangshi-36357','题悬溜岩隐者居','方干','quantangshi','','卷37','世人如要问生涯，满架堆牀是五车。
谷鸟暮蝉声四散，修篁灌木势交加。
蒲葵细织团圆扇，薤叶平铺合遝花。
却用水荷苞绿李，兼将寒井浸甘瓜。
惯缘嶮峭收松粉，常趂芳鲜掇茗芽。
池上树阴随浪动，窗前月影被巢遮。
坐云独酌杯盘湿，穿竹微吟路径斜。
见说公卿访遗逸，逢迎亦是戴乌纱。','',''),('quantangshi-36358','山中言事八韵寄李支使','方干','quantangshi','','卷37','岂知经史深相悞，两鬓垂丝百事休。
受业几多为弟子，成名一半作公侯。
前时射鹄徒抛箭，此日求鱼未上钩。
竹里断云来枕上，岩边片月在牀头。
过庭急雨和花落，遶舍澄泉带叶流。
缅想远书聆鹊喜，窥寻嘉果觉猿偷。
旧诗改处空留韵，新酝尝来不满篘。
阮瑀如能问寒馁，风光当日入沧洲。','',''),('quantangshi-36359','山中言事寄赠苏判官','方干','quantangshi','','卷37','寸心似火频求荐，两鬓如霜始息机。
隔岸鸡鸣春耨去，邻家犬吠夜渔归。
倚松长啸成疎拙，拂石欹眠绝是非。
执爨纵曾炊橡实，纫针曾解补荷衣。
常凭早月来张烛，亦假清风为掩扉。
多是元瑜怜野贱，时回车马发光辉。','',''),('quantangshi-36360','献王大夫','方干','quantangshi','','卷37','高情不与俗人知，耻学诸生取桂枝。
荀宋五言行世早，巢由三诏出溪迟。
操心已在精微域，落笔皆成典诰词。
一鹗难成燕雀伍，非熊本是帝王师。
贤臣虽蕴经邦术，明主终无谏猎时。
莫道百僚忧礼绝，兼闻七郡怕天移。
直缘材力头头赡，专被文星步步随。
不信重言通造化，须臾便可变荣衰。','',''),('quantangshi-36361','浅井','方干','quantangshi','','卷37','夜入明河星似少，曙摇澄碧扇风翻。
细泉细脉难来到，应觉添瓶耗旧痕。','',''),('quantangshi-36362','与徐温话别','方干','quantangshi','','卷37','去去何时却见君，悠悠烟水似天津。
明年今夜有明月，不是今年看月人。','',''),('quantangshi-36363','出东阳道中作','方干','quantangshi','','卷37','马首寒山黛色浓，一重重尽一重重。
醉醒已在他人界，犹忆东阳昨夜钟。','',''),('quantangshi-36364','酬孙发','方干','quantangshi','','卷37','锦价转高花更巧，能将旧手弄新梭。
从来一字为褒贬，二十八言犹太多。','',''),('quantangshi-36365','送乡中故人','方干','quantangshi','','卷37','少小与君情不疎，听君细话胜家书。
如今若到乡中去，道我垂钩不钓鱼。','',''),('quantangshi-36366','思江南','方干','quantangshi','','卷37','昨日草枯今日青，羇人又动望乡情。
夜来有梦登归路，不到桐庐已及明。','',''),('quantangshi-36367','题宝林寺禅者壁','方干','quantangshi','','卷37','邃岩乔木夏藏寒，牀下云溪枕上看。
台殿渐多山更重，却令飞去即应难。','',''),('quantangshi-36368','过李羣玉故居','方干','quantangshi','','卷37','讦直上书难遇主，衔冤下世未成翁。
琴尊剑鹤谁将去，惟锁山斋一树风。','',''),('quantangshi-36369','题玉笥山强处士','方干','quantangshi','','卷37','酒里藏身岩里居，删繁自是一家书。
世人呼尔为渔叟，尔学钓璜非钓鱼。','',''),('quantangshi-36370','君不来','方干','quantangshi','','卷37','远路东西欲问谁，寒来无处寄寒衣。
去时初种庭前树，树已胜巢人未归。','',''),('quantangshi-36371','经旷禅师旧院','方干','quantangshi','','卷37','谷鸟散啼如有恨，庭花含笑似无情。
更名变皃难休息，去去来来第几生。','',''),('quantangshi-36372','江南闻新曲','方干','quantangshi','','卷37','席上新声花下杯，一声声被拍声摧。
乐工不识长安道，尽是书中寄曲来。','',''),('quantangshi-36373','经故侯郎中旧居','方干','quantangshi','','卷37','一朝寂寂与冥冥，垄树未长坟草青。
高节雄才向何处，夜阑空锁满池星。','',''),('quantangshi-36374','越中逢孙百篇','方干','quantangshi','','卷37','上才乘酒到山阴，日日成篇字字金。
镜水周回千万顷，波澜倒泻入君心。','',''),('quantangshi-36375','寄谢麟','方干','quantangshi','','卷37','越国云溪秀发时，蒋京词赋谢麟诗。
后来若要知优劣，学圃无过老圃知。','',''),('quantangshi-36376','与长洲陈子美长官','方干','quantangshi','','卷37','枕上愁多百绪牵，常时睡觉在溪前。
人前尽是交亲力，莫道升沈总信天。','',''),('quantangshi-36377','新安殷明府家乐方响','方干','quantangshi','','卷37','葛溪铁片梨园调，耳底丁东十六声。
彭泽主人怜妙乐，玉杯春暖许同倾。','',''),('quantangshi-36378','别殷明府','方干','quantangshi','','卷37','许教门馆久踟躇，仲叔怀恩对玉壶。
