还家莫更寻山水，自有云山在笔峰。','',''),('quantangshi-36380','赠会稽杨长官','方干','quantangshi','','卷37','直钩终日竟无鱼，钟鼓声中与世疎。
若向湖边访幽拙，萧条四壁是闲居。','',''),('quantangshi-36381','赠申长官','方干','quantangshi','','卷37','言下随机见物情，看看狱路草还生。
旅人莫怪无鱼食，直为寒江水至清。','',''),('quantangshi-36382','将归湖上留别陈宰','方干','quantangshi','','卷37','归去春山逗晚晴，萦回树石罅中行。
明时不是无知己，自忆湖边钓与耕。','',''),('quantangshi-36383','贻亮上人','方干','quantangshi','','卷37','秋水一泓常见底，涧松千尺不生枝。
人间学佛知多少，净尽心花只有师。','',''),('quantangshi-36384','贻曦上人','方干','quantangshi','','卷37','四十年来多少人，一分零落九成尘。
与师犹得重相见，亦是枯株勉强春。','',''),('quantangshi-36385','书原上鲍处士屋壁','方干','quantangshi','','卷37','水阔坐看千万里，青芜盖地接天津。
禰衡莫爱山中静，遶舍山多却碍人。','',''),('quantangshi-36386','别孙蜀','方干','quantangshi','','卷37','吴越思君意易伤，别君添我鬓边霜。
由来淛水偏堪恨，截断千山作两乡。','',''),('quantangshi-36387','赠江上老人','方干','quantangshi','','卷37','潭底锦鳞多识钓，未投香饵即先知。
欲教鱼目无分别，须学揉蓝染钓丝。','',''),('quantangshi-36388','赠东溪贫道','方干','quantangshi','','卷37','非唯剑鹤独难留，触事皆闻被债收。
赖是豪家念寒馁，却还渔岛与渔舟。','',''),('quantangshi-36389','咏花','方干','quantangshi','','卷37','狂心醉眼共裴回，一半先开笑未开。
此日不能偷折去，胡蜂直恐趂人来。','',''),('quantangshi-36390','路入金州江中作','方干','quantangshi','','卷37','棹寻椒岸萦回去，数里时逢一两家。
知是从来贡金处，江边牧竖亦披沙。','',''),('quantangshi-36391','夜会郑氏昆季林亭','方干','quantangshi','','卷37','卷帘圆月照方塘，坐久尊空竹有霜。
