先生不入云台像，赢得桐江万古名。','',''),('quantangshi-36402','题严子陵祠二首 二','方干','quantangshi','','卷37','苍翠云峰开俗眼，泓澄烟水浸尘心。
惟将道业为芳饵，钓得高名直到今。','',''),('quantangshi-36403','失题','方干','quantangshi','','卷37','十六声中运手轻，一声声似自然声。
不缘精妙过流辈，争得江南别有名。','',''),('quantangshi-36404','句','方干','quantangshi','','卷37','弟子已攀桂，先生犹卧云。
把得新诗草里论。
枯井夜闻邻果落，废巢寒见别禽来。','',''),('quantangshi-36405','岁仗','羅鄴','quantangshi','','卷37','玉帛朝元万国来，鸡人晓唱五门开。
