歌舜薰风铿劒佩，祝尧嘉气霭楼台。
可怜四海车书共，重见萧曹佐汉材。','',''),('quantangshi-36406','牡丹','羅鄴','quantangshi','','卷37','落尽春红始着花，花时比屋事豪奢。
买栽池馆恐无地，看到子孙能几家。
