只宜醉梦依华寝，可称羸蹄赴宿程。
日苦几多心下见，那堪岁晏又无成。','',''),('quantangshi-36412','冬夕江上言事五首 四','羅鄴','quantangshi','','卷37','僻居多与懒相宜，吟拥寒炉过腊时。
