山川自小抛耕钓，骨肉无因免别离。
赖有陶情一尊酒，愁中相向展愁眉。','',''),('quantangshi-36413','冬夕江上言事五首 五','羅鄴','quantangshi','','卷37','一带长溪渌浸门，数声幽鸟啄云根。
松亭尽日唯空坐，难得儒翁共讨论。','',''),('quantangshi-36414','春日宿崇贤里','羅鄴','quantangshi','','卷37','柳暗榆飞春日深，水边门巷独来寻。
