枕近禁街闻晓鼓，月当高竹见栖禽。
劳歌莫问秋风计，恐起江河垂钓心。','',''),('quantangshi-36415','征人','羅鄴','quantangshi','','卷37','青楼一别戍金微，力尽秋来破虏围。
