正怜汉月当空照，不奈胡沙满眼飞。
唯有梦魂南去日，故乡山水路依稀。','',''),('quantangshi-36416','莺','羅鄴','quantangshi','','卷37','暖辞云谷背残阳，飞下东风翅渐长。
