好是精灵偏有感，能于乡里不为灾。
九江贾客应遥祝，五夜神兵数此来。
尽室唯求多降福，新年归去便风催。','',''),('quantangshi-36423','经故洛城','羅鄴','quantangshi','','卷37','一片危墙势恐人，墙边日日走蹄轮。
筑时驱尽千夫力，崩处空为数里尘。
长恨往来经此地，每嗟兴废欲霑巾。
那堪又向荒城过，锦雉惊飞麦陇春。','',''),('quantangshi-36424','老将','羅鄴','quantangshi','','卷37','百战辛勤归帝乡，南班班里最南行。
弓欺猨臂秋无力，劒泣虬髯晓有霜。
千古耻非书玉帛，一心犹自向河湟。
年年宿卫天颜近，曾把功勋奏建章。','',''),('quantangshi-36425','曲江春望','羅鄴','quantangshi','','卷37','故国东归泽国遥，曲江晴望忆渔樵。
都缘北阙春先到，不是南山雪易消。
瑞影玉楼开组绣，欢声丹禁奏云韶。
虽然未得陪鸳鹭，亦酹金觞祝帝尧。','',''),('quantangshi-36426','帝里','羅鄴','quantangshi','','卷37','喧喧蹄毂走红尘，南北东西暮与晨。
谩道青云难得路，何曾紫陌有闲人。
杯倾竹叶侯门月，马落桃花御水春。
只合咏歌来大国，况逢文景化惟新。','',''),('quantangshi-36427','新安城','羅鄴','quantangshi','','卷37','若筭防边久远名，新安岂更胜长城。
谩兴他役悲荒垒，何似从今实取兵。
圣德便应同险固，人心自不向忠贞。
但将死节酬尧禹，版筑无劳寇已平。','',''),('quantangshi-36428','自遣','羅鄴','quantangshi','','卷37','四十年来诗酒徒，一生缘兴滞江湖。
不愁世上无人识，唯怕村中没酒沽。
春巷摘桑喧姹女，江船吹笛舞蛮奴。
焚鱼酌醴醉尧代，吟向席门聊自娱。','',''),('quantangshi-36429','流水','羅鄴','quantangshi','','卷37','漾漾悠悠几派分，中浮短艇与鸥羣。
天街带雨淹芳草，玉洞飘花下白云。
静称一竿持处见，急宜孤馆觉来闻。
隋家柳畔偏堪恨，东入长淮日又曛。','',''),('quantangshi-36430','送张逸人','羅鄴','quantangshi','','卷37','自说归山人事赊，素琴丹竈是生涯。
牀头残药鼠偷尽，溪上破门风摆斜。
石井晴垂青葛叶，竹篱荒映白茅花。
遥知此去应稀出，独卧晴窗梦晓霞。','',''),('quantangshi-36431','春晚渡河有怀','羅鄴','quantangshi','','卷37','烟收绿野远连空，戍垒依稀入望中。
万里山河星拱北，百年人事水归东。
扁舟晚济桃花浪，走马晴嘶柳絮风。
乡思正多羁思苦，不须回首问渔翁。','',''),('quantangshi-36432','春望梁石头城','羅鄴','quantangshi','','卷37','柳碧桑黄破国春，残阳微雨望归人。
江山不改兴亡地，冠盖自为前后尘。
帆势挂风轻若翅，浪声吹岸叠如鳞。
六朝无限悲愁事，欲下荒城回首频。','',''),('quantangshi-36433','早发宜陵即事','羅鄴','quantangshi','','卷37','霜白山村月落时，一声鸡后又登岐。
居人犹自掩关在，行客已愁驱马迟。
身事不堪空感激，鬓毛看着欲凋衰。
青萍委匣休哮吼，未有恩讐拟报谁。','',''),('quantangshi-36434','鸳鸯','羅鄴','quantangshi','','卷37','红闲碧霁瑞烟开，锦翅双飞去又回。
一种鸟怜名字好，尽缘人恨别离来。
暖依牛渚汀莎媚，夕宿龙池禁漏催。
相对若教春女见，便须携向凤凰台。','',''),('quantangshi-36435','春闺','羅鄴','quantangshi','','卷37','愁坐兰闺日过迟，卷帘巢燕羡双飞。
管弦楼上春应在，杨柳桥边人未归。
玉笛岂能留舞态，金河犹自浣戎衣。
梨花满院东风急，惆怅无言倚锦机。','',''),('quantangshi-36436','赠东川梓桐县韦德孙长官','羅鄴','quantangshi','','卷37','前代高门今宰邑，怀才重义古来无。
笙歌厌听吟清句，京洛思归展画图。
蜀酝天寒留容醉，陇禽山晓隔帘呼。
何年期拜朱幡贵，马上论诗在九衢。','',''),('quantangshi-36437','题水帘洞','羅鄴','quantangshi','','卷37','乱泉飞下翠屏中，名共真珠巧缀同。
一片长垂今与古，半山遥听水兼风。
虽无舒卷随人意，自有潺湲济物功。
每向暑天来往见，疑将仙子隔房栊。','',''),('quantangshi-36438','野花','羅鄴','quantangshi','','卷37','拂露丛开血色殷，枉无名字对空山。
时逢舞蝶寻香至，少有行人辍棹攀。
若在侯门看不足，为生江岸见如闲。
结根毕竟输桃李，长近都城紫陌间。','',''),('quantangshi-36439','芦花','羅鄴','quantangshi','','卷37','如练如霜干复轻，西风处处拂江城。
长垂钓叟看不足，暂泊王孙愁亦生。
好傍翠楼装月色，枉随红叶舞秋声。
最宜羣鹭斜阳里，闲捕纤鳞傍尔行。','',''),('quantangshi-36440','山阳贻友人','羅鄴','quantangshi','','卷37','性僻多将云水便，山阳酒病动经年。
行迟暖陌花拦马，睡重春江雨打船。
闲弄玉琴双鹤舞，静窥庭树一猱悬。
结茅更莫期深隐，声价如今满日边。','',''),('quantangshi-36441','长安惜春','羅鄴','quantangshi','','卷37','千门共惜放春回，半锁楼台半复开。
公子不能留落日，南山遮莫倚高台。
残红似怨皇州雨，细绿犹藏画蜡灰。
毕竟思量何足叹，明年时节又还来。','',''),('quantangshi-36442','谢友人遗华阳巾','羅鄴','quantangshi','','卷37','剪露[裁]烟胜角冠，来从玉洞五云端。
醉宜薤叶欹斜影，稳称菱花子细看。
野客爱留笼鹤髪，溪翁争乞配渔竿。
真仙首饰劳相寄，尘土飜慙戴去难。','',''),('quantangshi-36443','早梅','羅鄴','quantangshi','','卷37','缀雪枝条似有情，凌寒澹注笑妆成。
冻香飘处宜春早，素艳开时混月明。
迁客岭头悲褭褭，美人帘下妬盈盈。
满园桃李虽堪赏，要且东风晚始生。','',''),('quantangshi-36444','留题张逸人草堂','羅鄴','quantangshi','','卷37','长悬青紫与芳枝，尘路无因免别离。
马上多于在家日，尊前堪惜少年时。
关河客梦还乡后，雨雪山程出店迟。
却羡高人此中老，轩车过尽不知谁。','',''),('quantangshi-36445','钟陵崔大夫罢镇攀随再经匡庐寺宿','羅鄴','quantangshi','','卷37','一抛文战学从公，两逐旌旗宿梵宫。
酒醒月移窗影畔，夜凉身在水声中。
侯门聚散真如梦，花界登临转悟空。
明发不堪山下路，几程愁雨又愁风。','',''),('quantangshi-36446','留献彭门郭常侍','羅鄴','quantangshi','','卷37','受得彭门拥信旗，一家将谓免羁离。
到来门馆空归去，羞向交亲说受知。
层构尚无容足地，尺波宁有跃鳞时。
到头忍耻求名是，须向青云觅路岐。','',''),('quantangshi-36447','洛水','羅鄴','quantangshi','','卷37','一道潺湲溅暖莎，年年惆怅是春过。
莫言行路听如此，流[入]深宫怅更多。
桥畔月来清见底，柳边风紧绿生波。
纵然满眼添归思，未把渔竿奈尔何。','',''),('quantangshi-36448','闻杜鹃','羅鄴','quantangshi','','卷37','花时一宿碧山前，明月东风呌杜鹃。
孤馆觉来听夜半，羸僮相对亦无眠。
汝身哀怨犹如此，我泪纵横岂偶然。
争得苍苍知有恨，汝身成鹤我成仙。','',''),('quantangshi-36449','趂职单于留别阙下知己','羅鄴','quantangshi','','卷37','职忝翩翩逐建牙，笈随征骑入胡沙。
定将千里书凭雁，应看三春雪当花。
年长有心终报国，时清到处便营家。
逢秋不拟同张翰，为忆鲈鱼却叹嗟。','',''),('quantangshi-36450','落第书怀寄友人','羅鄴','quantangshi','','卷37','清世谁能便陆沈，相逢休作忆山吟。
若教仙桂在平地，更有何人肯苦心。
去国汉妃还似玉，亡家石氏岂无金。
且安怀抱莫惆怅，瑶瑟调高尊酒深。','',''),('quantangshi-36451','鹦鹉咏','羅鄴','quantangshi','','卷37','玉槛瑶轩任所依，东风休忆岭头归。
金[笼]共惜好毛羽，红觜莫教多是非。
便向郄堂夸饮啄，还应禰笔发光辉。
乘时得路何须贵，燕雀鸾凤各有机。','',''),('quantangshi-36452','题沧浪峡','羅鄴','quantangshi','','卷37','门向红尘日日开，入门襟袖远尘埃。
暗香惹步涧花发，晚景逼檐溪鸟回。
不为市朝行路近，有谁车马看山来。
可怜严子持竿处，云水终年锁绿苔。','',''),('quantangshi-36453','白角簟','羅鄴','quantangshi','','卷37','叠玉骈圭巧思长，露华烟魄让清光。
休摇雉尾当三伏，似展龙鳞在一牀。
高价不唯标越绝，冷纹疑似卧潇湘。
杜陵他日重归去，偏称醉眠松桂堂。','',''),('quantangshi-36454','秋日怀江上友人','羅鄴','quantangshi','','卷37','行子岂知烟水劳，西风独自泛征艘。
酒醒孤馆秋帘卷，月满寒江夜笛高。
黄叶梦余归朔塞，青山家在极波涛。
去年今日逢君处，雁下芦花猨正号。','',''),('quantangshi-36455','题笙','羅鄴','quantangshi','','卷37','筠管参差排凤翅，月堂凄切胜龙吟。
最宜轻动纤纤玉，醉送当观滟滟金。
缑岭独能征妙曲，嬴台相共吹清音。
好将宫征陪歌扇，莫遣新声郑卫侵。','',''),('quantangshi-36456','下第','羅鄴','quantangshi','','卷37','谩把青春酒一杯，愁襟未信酒能开。
江边依旧空归去，帝里还如不到来。
门掩残阳鸣鸟雀，花飞何处好池台。
此时惆怅便堪老，何用人间岁月催。','',''),('quantangshi-36457','秋晚','羅鄴','quantangshi','','卷37','残星残月一声钟，谷际岩隈爽气浓。
不向碧台惊醉梦，但来青镜促愁容。
繁金露洁黄笼菊，独翠烟凝远涧松。
闲步幽林与苔径，渐移栖鸟及鸣蛩。','',''),('quantangshi-36458','长安春夕旅怀','羅鄴','quantangshi','','卷37','几年栖旅寄西秦，不识花枝醉过春。
短艇闲思五湖浪，羸蹄愁伴九衢尘。
关河风雨迷归梦，钟鼓朝昏老此身。
忽向太平时节过，一竿持去老遗民。','',''),('quantangshi-36459','洛阳春望','羅鄴','quantangshi','','卷37','洛阳春霁绝尘埃，嵩少烟岚画障开。
草色花光惹襟袖，箫声歌响隔楼台。
人心便觉闲多少，马足方知倦往来。
愁上中桥桥上望，碧波东去夕阳催。','',''),('quantangshi-36460','惜春','羅鄴','quantangshi','','卷37','燕归巢后即离羣，吟倚东风恨日曛。
一别一年方见我，游来游去不禁君。
莺花御苑看将尽，丝竹侯家亦少闻。
独坐南楼正惆怅，柳塘花絮更纷纷。','',''),('quantangshi-36461','冬日旅怀','羅鄴','quantangshi','','卷37','[乌]焰才沈桂魄生，霜阶拥褐暂吟行。
闲思江市白醪满，静忆僧窗绿绮横。
尘土自怜长失计，云帆尤觉有归情。
几多怅望无穷事，空画炉灰坐到明。','',''),('quantangshi-36462','春夕寄友人时有与歌者南北','羅鄴','quantangshi','','卷37','芳径春归花半开，碧山波暖雁初回。
满楼月色还依旧，昨夜歌声自不来。
愁眼向谁零玉筯，征蹄何处驻红埃？
中宵吟罢正惆怅，从此兰堂锁绿苔。','',''),('quantangshi-36463','春夜赤水驿旅怀','羅鄴','quantangshi','','卷37','一星残烛照离堂，失计游心归渺茫。
不自寻思无道路，为谁辛苦竞时光。
九衢春色休回首，半夜溪声正梦乡。
却羡去年买山侣，月斜渔艇倚潇湘。','',''),('quantangshi-36464','春山山馆旅怀','羅鄴','quantangshi','','卷37','山馆吟余山月斜，东风摇曳拂窗花。
岂知驱马无闲日，长在他人后到家。
孤劒向谁开壮节，流年催我自堪嗟。
灯前结束又前去，晓出石林啼乱鸦。','',''),('quantangshi-36465','秋夕旅怀','羅鄴','quantangshi','','卷37','阶前月色与蛩声，阶上愁人坐复行。
秦谷入霜空有梦，越山无计可归耕。
穷途若遣长堪恸，华髪无因肯晚生。
不似扁舟钓鱼者，免将心事筭浮荣。','',''),('quantangshi-36466','春过白遥岭','羅鄴','quantangshi','','卷37','鸟道穿云望峡遥，羸蹄经宿在岧嶤。
到来山下春将半，上得林端雪未消。
返驾王尊何足叹，哭途阮籍谩无聊。
未知遇此恓惶者，泣向东风鬓欲凋。','',''),('quantangshi-36467','别夜','羅鄴','quantangshi','','卷37','秋入江天河汉清，迢迢钟漏出孤城。
金波千里别来夜，玉筯两行流到明。
若在人间须有恨，除非禅伴始无情。
人间谁有□□□，聚散自然惆怅生。','',''),('quantangshi-36468','费拾遗书堂','羅鄴','quantangshi','','卷37','满袖归来天桂香，紫泥重降旧书堂。
自怜苇带同巢许，不驾蒲轮佐禹汤。
怪石尽含千古秀，奇花多吐四时芳。
何人更肯追高躅，唯有樵童戏藓牀。','',''),('quantangshi-36469','溪上春望','羅鄴','quantangshi','','卷37','无端溪上看兰桡，又是东风断柳条。
双鬓多于愁里镊，四时须向醉中销。
行人骏马嘶香陌，独我残阳倚野桥。
吟水咏山心未已，可能终不胜渔樵。','',''),('quantangshi-36470','献池州庾员外','羅鄴','quantangshi','','卷37','曾降瑶缄荐姓名，攀云几合到蓬瀛。
须存彭寿千年在，终见茅公九转成。
鲲海已知劳鹤使，萤窗不那梦霓旌。
琪花玉蔓应相笑，未得歌吟从酒行。','',''),('quantangshi-36471','春风','羅鄴','quantangshi','','卷37','每岁东来助发生，舞空悠扬徧寰瀛。
暗添芳草池塘色，远遰高楼箫管声。
帘透骊宫偏带恨，花催上苑剩多情。
如何一瑞车书日，吹取青云道路平。','',''),('quantangshi-36472','冬日寄献庾员外','羅鄴','quantangshi','','卷37','曾谒仙宫最上仙，西风许醉桂花前。
争欢酒蚁浮金爵，从听歌尘扑翠蝉。
秋霁卷帘凝锦席，夜阑吹笛称江天。
却思紫陌觥筹地，兔缺乌沈欲半年。','',''),('quantangshi-36473','钓翁','羅鄴','quantangshi','','卷37','来往烟波非定居，生涯蓑褐外无余。
闲垂两鬓任如鹤，只系一竿时得鱼。
月浦扣船歌皎洁，雨蓬隈岸卧萧疎。
行人误话金张贵，笑指北邙丘与墟。','',''),('quantangshi-36474','闻友人入越幕因以诗赠','羅鄴','quantangshi','','卷37','稽岭春生酒冻销，烟鬟红袖恃娇饶。
岸边丛雪晴香老，波上长虹晚影遥。
正哭阮途归未得，更闻江笔赴嘉招。
人间荣瘁真堪恨，坐想征轩鬓欲凋。','',''),('quantangshi-36475','东归','羅鄴','quantangshi','','卷37','日日唯忧行役迟，东归可是有家归。
都缘桂玉无门住，不算山川去路危。
秦树梦愁黄鸟啭，吴江钓忆锦鳞肥。
桃夭李艳清明近，惆怅当年意尽违。','',''),('quantangshi-36476','入关','羅鄴','quantangshi','','卷37','古道槐花满树开，入关时节一蝉催。
出门唯恐不先到，当路有谁长待来。
似箭年光还可惜，如蓬生计更堪哀。
故园若有渔舟在，应挂云帆早个回。','',''),('quantangshi-36477','览陈丕卷','羅鄴','quantangshi','','卷37','雪宫词客燕宫游，一轴烟花象外搜。
谩把蜀纹当昼展，徒夸湘碧带春流。
吟时致我寒侵骨，得处疑君白尽头。
从北南归明月夜，岭猨滩鸟更悠悠。','',''),('quantangshi-36478','巴南旅舍言怀','羅鄴','quantangshi','','卷37','万浪千岩首未回，无憀相倚上高台。
家山如画不归去，客舍似讐谁遣来。
红泪罢窥连晓烛，碧波休引向春杯。
后时若有青云望，何事偏教羽冀摧。','',''),('quantangshi-36479','登凌歊台','羅鄴','quantangshi','','卷37','高台今日竟长闲，因想兴亡自惨颜。
四海已归新雨露，六朝空认旧江山。
槎翘独鸟沙汀畔，风遰连樯雪浪间。
好是轮蹄来往便，谁人不向此跻攀。','',''),('quantangshi-36480','仆射陂晚望','羅鄴','quantangshi','','卷37','离人到此倍堪伤，陂水芦花似故乡。
身事未知何日了，马蹄唯觉到秋忙。
田园牢落东归晚，道路辛勤北去长。
却羡无愁是沙鸟，双双相趂下斜阳。','',''),('quantangshi-36481','芳草','羅鄴','quantangshi','','卷37','废苑墙南残雨中，似袍颜色在蒙茸。
微香暗惹游人步，远绿才分鬬雉踪。
三楚渡头长恨见，五侯门外却难逢。
年年纵有春风便，马迹车轮一万重。','',''),('quantangshi-36482','秋日留题蒋亭','羅鄴','quantangshi','','卷37','西风才起一蝉鸣，便筭关河马上程。
碧浪鷁舟从此别，丹霄鹄箭忍无成。
二年芳思随云雨，几日离歌恋斾旌。
回首横塘更东望，露荷烟菊倍伤情。','',''),('quantangshi-36483','早发','羅鄴','quantangshi','','卷37','一点灯残鲁酒醒，已携孤劒事离程。
愁看飞雪闻鸡唱，独向长空背雁行。
白草近关微有路，浊河连底冻无声。
此中来往本迢递，况是驱羸客塞城。','',''),('quantangshi-36484','雁二首 一','羅鄴','quantangshi','','卷37','暮天新雁起汀洲，红蓼花开水国愁。
想得故园今夜月，几人相忆在江楼。','',''),('quantangshi-36485','雁二首 二','羅鄴','quantangshi','','卷37','早背胡霜过戍楼，又随寒日下汀洲。
江南江北多离别，忍报年年两地愁。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-36486','萤二首 一','羅鄴','quantangshi','','卷37','水殿清风玉户开，飞光千点去还来。
无风无月长门夜，偏到阶前点绿苔。','',''),('quantangshi-36487','萤二首 二','羅鄴','quantangshi','','卷37','裴回无烛冷无烟，秋迳莎庭入夜天。
休向书窗来照字，近来红蜡满歌筵。','',''),('quantangshi-36488','看花','羅鄴','quantangshi','','卷37','花开只恐看来迟，及到愁如未看时。
家在楚乡身在蜀，一年春色负归期。','',''),('quantangshi-36489','柳絮','羅鄴','quantangshi','','卷37','处处东风扑晚阳，轻轻醉粉落无香。
就中堪恨隋堤上，曾惹龙舟舞凤凰。','',''),('quantangshi-36490','云','羅鄴','quantangshi','','卷37','纷纷霭霭遍江湖，得路为霖岂合无。
莫使悠扬只如此，帝乡还更暖苍梧。','',''),('quantangshi-36491','芳草','羅鄴','quantangshi','','卷37','曲江岸上天街里，两地纵生车马多。
不似萋萋南浦见，晚来烟雨半相和。','',''),('quantangshi-36492','出都门','羅鄴','quantangshi','','卷37','青门春色一花开，长到花时把酒杯。
自觉无家似潮水，不知归处去还来。','',''),('quantangshi-36493','宫中二首 一','羅鄴','quantangshi','','卷37','芳草长含玉辇尘，君王游幸此中频。
今朝别有承恩处，鹦鹉飞来说似人。','',''),('quantangshi-36494','宫中二首 二','羅鄴','quantangshi','','卷37','虽然自小属梨园，不识先皇玉殿门。','',''),('quantangshi-36495','河湟','羅鄴','quantangshi','','卷37','河湟何计绝烽烟，免使征人更戍边。
尽放农桑无一事，遣教知有太平年。','',''),('quantangshi-36496','闻子规','羅鄴','quantangshi','','卷37','蜀魄千年尚怨谁，声声啼血向花枝。
满山明月东风夜，正是愁人不寐时。','',''),('quantangshi-36497','望仙','羅鄴','quantangshi','','卷37','千山垒土望三山，云鹤无踪羽卫还。
若说神仙求便得，茂陵何事在人间。','',''),('quantangshi-36498','放鹧鸪','羅鄴','quantangshi','','卷37','好傍青山与碧溪，刺桐毛竹待双栖。
花时迁客伤离别，莫向相思树上啼。','',''),('quantangshi-36499','骊山','羅鄴','quantangshi','','卷37','风摇岩桂露闻香，白鹿惊时出绕墙。
不向骊山锁宫殿，可知仙去是明皇。','',''),('quantangshi-36500','梅花','羅鄴','quantangshi','','卷37','繁如瑞雪压枝开，越岭吴溪免用栽。
却是五侯家未识，春风不放过江来。','',''),('quantangshi-36501','鸡冠花','羅鄴','quantangshi','','卷37','一枝穠艳对秋光，露滴风摇倚砌傍。
晓景乍看何处似，谢家新染紫罗裳。','',''),('quantangshi-36502','汴河','羅鄴','quantangshi','','卷37','炀帝开河鬼亦悲，生民不独力空疲。
至今呜咽东流水，似向清平怨昔时。','',''),('quantangshi-36503','渡江有感','羅鄴','quantangshi','','卷37','岸落残红锦雉飞，渡江船上夕阳微。
一枝犹负平生意，归去何曾胜不归。','',''),('quantangshi-36504','题终南山僧堂','羅鄴','quantangshi','','卷37','九衢终日见南山，名利何人肯掩关。
唯有吾师达真理，坐看霜树老云间。','',''),('quantangshi-36505','大散岭','羅鄴','quantangshi','','卷37','过往长逢日色稀，雪花如掌扑行衣。
岭头却望人来处，特地身疑是鸟飞。','',''),('quantangshi-36506','嘉陵江','羅鄴','quantangshi','','卷37','嘉陵南岸雨初收，江似秋岚不煞流。
此地终朝有行客，无人一为棹扁舟。','',''),('quantangshi-36507','早行','羅鄴','quantangshi','','卷37','雨洒江声风又吹，扁舟正与睡相宜。
无端戍鼓催前去，别却青山向晓时。','',''),('quantangshi-36508','黄河晓渡','羅鄴','quantangshi','','卷37','大河平野正穷秋，羸马羸僮古渡头。
昨夜莲花峰下月，隔帘相伴到明愁。','',''),('quantangshi-36509','温泉','羅鄴','quantangshi','','卷37','一条春水漱莓苔，几绕玄宗浴殿回。
此水贵妃曾照影，不堪流入旧宫来。','',''),('quantangshi-36510','秋怨','羅鄴','quantangshi','','卷37','梦断南窗啼晓乌，新霜昨夜下庭梧。
不知帘外如圭月，还照边城到晓无。','',''),('quantangshi-36511','叹别','羅鄴','quantangshi','','卷37','北来南去几时休，人在光阴似箭流。
直待江山尽无路，始因抛得别离愁。','',''),('quantangshi-36512','送春','羅鄴','quantangshi','','卷37','欲别东风剩黯然，亦知春去有明年。
世间争那人先老，更对残花一醉眠。','',''),('quantangshi-36513','蜡烛','羅鄴','quantangshi','','卷37','暖香红焰一时燃，缇幕初垂月落天。
堪恨兰堂别离夜，如珠似泪滴樽前。','',''),('quantangshi-36514','陈宫','羅鄴','quantangshi','','卷37','白玉尊前紫桂香，迎春阁上燕双双。
陈王半醉贵妃舞，不觉隋兵夜渡江。','',''),('quantangshi-36515','水帘','羅鄴','quantangshi','','卷37','万点飞泉下白云，似帘悬处望疑真。
若将此水为霖雨，更胜长垂隔路尘。','',''),('quantangshi-36516','赏春','羅鄴','quantangshi','','卷37','芳草和烟暖更青，闲门要路一时生。
年年点检人间事，唯有春风不世情。','',''),('quantangshi-36517','叹平泉','羅鄴','quantangshi','','卷37','生前几到此亭台，寻叹投荒去不回。
若遣春风会人意，花枝尽合向南开。','',''),('quantangshi-36518','长安春雨','羅鄴','quantangshi','','卷37','兼风飒飒洒皇洲，能滞轻寒阻胜游。
半夜五侯池馆里，美人惊起为花愁。','',''),('quantangshi-36519','驾蜀回','羅鄴','quantangshi','','卷37','上皇西幸却归秦，花木依然满禁春。
唯有贵妃歌舞地，月明空殿锁香尘。','',''),('quantangshi-36520','吴王古宫井二首 一','羅鄴','quantangshi','','卷37','古宫荒井曾平后，见说耕人又凿开。
拾得玉衩镌勅字，当时恩泽赐谁来。','',''),('quantangshi-36521','吴王古宫井二首 二','羅鄴','quantangshi','','卷37','含青薜荔随金甃，碧砌磷磷生绿苔。
莫言数尺无波水，曾与如花竝照来。','',''),('quantangshi-36522','江帆','羅鄴','quantangshi','','卷37','别离不独恨蹄轮，渡口风帆发更频。
何处青楼方凭槛，半江斜日认归人。','',''),('quantangshi-36523','为人感赠','羅鄴','quantangshi','','卷37','歌舞从来最得名，如今老寄洛阳城。
当时醉送龙骧曲，留与谁家唱月明。','',''),('quantangshi-36524','春江恨别','羅鄴','quantangshi','','卷37','望断长川一叶舟，可堪归路更沿流。
垂来别处无人见，芳草斜阳满渡头。','',''),('quantangshi-36525','叹流水二首 一','羅鄴','quantangshi','','卷37','人间莫谩惜花落，花落明年依旧开。
却最堪悲是流水，便同人事去无回。','',''),('quantangshi-36526','叹流水二首 二','羅鄴','quantangshi','','卷37','龙跃虬蟠旋作潭，绕红溅绿下东南。
春风散入侯家去，漱齿花前酒半酣。','',''),('quantangshi-36527','落第东归','羅鄴','quantangshi','','卷37','年年春色独怀羞，彊向东归懒举头。
莫道还家便容易，人间多少事堪愁。','',''),('quantangshi-36528','镜','羅鄴','quantangshi','','卷37','昔岁相知别有情，几回磨拭始将行。
如今老去愁无限，抱向闲窗却怕明。','',''),('quantangshi-36529','南行','羅鄴','quantangshi','','卷37','腊晴江暖䴙鹈飞，梅雪香黏越女衣。
鱼市酒村相识徧，短船歌月醉方归。','',''),('quantangshi-36530','公子行','羅鄴','quantangshi','','卷37','金鞍玉勒照花明，过后春风特地生。
半醉五侯门里出，月高犹在禁街行。','',''),('quantangshi-36531','春日偶题城南韦曲','羅鄴','quantangshi','','卷37','韦曲城南锦绣堆，千金不惜买花栽。
谁知豪贵多羁束，落尽春红不见来。','',''),('quantangshi-36532','上东川顾尚书','羅鄴','quantangshi','','卷37','轻财重义真公子，长策沈机继武侯。
龙节坐持兵十万，可怜三蜀尽无忧。','',''),('quantangshi-36533','过王浚墓','羅鄴','quantangshi','','卷37','埋骨千年近路尘，路傍碑号晋将军。
当时若使无功业，早个耕桑到此坟。','',''),('quantangshi-36534','灞上感别','羅鄴','quantangshi','','卷37','灞水何人不别离，无家南北倚空悲。
十年此路花时节，立马霑襟酒一巵。','',''),('quantangshi-36535','春日与友人话别','羅鄴','quantangshi','','卷37','酌坐对芳草，东风吹旅衣。
最嫌驱马倦，自未有山归。
华髪将时逼，青云计又非。
离襟一霑洒，回首正残晖。','',''),('quantangshi-36536','竹','羅鄴','quantangshi','','卷37','翠叶才分细细枝，清阴犹未上阶墀。
蕙兰虽许相依日，桃李还应笑后时。
抱节不为霜霰改，成林终与凤凰期。
渭滨若更征贤相，好作渔竿系钓丝。','',''),('quantangshi-36537','边将','羅鄴','quantangshi','','卷37','马上乘秋欲建勋，飞狐夜鬬出师频。
若无紫塞烟尘事，谁识青楼歌舞人。
战骨沙中金镞在，贺筵花畔玉盘新。
由来边卒皆如此，只是君门合杀身。','',''),('quantangshi-36538','巴南旅泊','羅鄴','quantangshi','','卷37','巴山惨别魂，巴水彻荆门。
此地若重到，居人谁复存。
落帆红叶渡，驻马白云村。
却羡南飞雁，年年到故园。','',''),('quantangshi-36539','河上逢友人','羅鄴','quantangshi','','卷37','知君意不浅，立马问生涯。
薄业无归地，他乡便是家。
宵吟怜桂魄，朝起怯菱花。
语尽黄河上，西风日又斜。','',''),('quantangshi-36540','偶题离亭','羅鄴','quantangshi','','卷37','万般名利不关身，况待山平海变尘。
五月波涛争下峡，满堂金玉为何人。
谩夸浮世青云贵，未尽离杯白发新。
谁似雨篷篷底客，渚花汀鸟自相亲。','',''),('quantangshi-36541','夏晚望嵩亭有怀','羅鄴','quantangshi','','卷37','正怜云水与心违，湖上亭高对翠微。
尽日不妨凭槛望，终年未必有家归。
青蝉渐傍幽丛噪，白鸟时穿返照飞。','',''),('quantangshi-36542','途中寄友人','羅鄴','quantangshi','','卷37','秋庭怅望别君初，折柳分襟十载余。
相见或因中夜梦，寄来多是隔年书。
携樽座外花空老，垂钓江头柳渐疎。
裁得诗凭千里雁，吟来宁不忆吾庐。','',''),('quantangshi-36543','伤侯弟','羅鄴','quantangshi','','卷37','世间荣辱半相和，昨日权门今雀罗。
万古明君方纳谏，九江迁客更应多。
碧池草熟人偷钓，画戟春闲莺乱过。
几许乐僮无主后，不离隣巷教笙歌。','',''),('quantangshi-36544','春日过寿安山馆','羅鄴','quantangshi','','卷37','旧国多将泉石亲，西游爱此拂行尘。
帘开山色离亭午，步入松香别岛春。
谁肯暂安耕钓地，相逢谩叹路岐身。
归期不及桃花水，江上何曾鲙雪鳞。','',''),('quantangshi-36545','吴门再逢方干处士','羅鄴','quantangshi','','卷37','天上高名世上身，垂纶何不驾蒲轮。
一朝卿相俱前席，千古篇章冠后人。
稽岭不归空挂梦，吴宫相值欲霑巾。
吾王若致升平化，可独成周只渭滨。','',''),('quantangshi-36546','蝉','羅鄴','quantangshi','','卷37','才入新秋百感生，就中蝉噪最堪惊。
能催时节凋双鬓，愁到江山听一声。
不傍管弦拘醉态，偏依杨柳挠离情。
故园闻处犹惆怅，况是经年万里行。','',''),('quantangshi-36547','秋日留别义初上人','羅鄴','quantangshi','','卷37','塞寺穷秋别还师，西风一雁倍伤悲。
每嗟尘世长多事，重到禅斋是几时。
霜岭自添红叶恨，月溪休和碧云词。
关河回首便千里，飞锡南归讵可知。','',''),('quantangshi-36548','夏日宿灵岩寺宗公院','羅鄴','quantangshi','','卷37','寺入千岩石路长，孤吟一宿远公房。
卧听半夜杉坛雨，转觉中峰枕簟凉。
花界已无悲喜念，尘襟自足是非妨。
他年纵使重来此，息得心猨鬓已霜。','',''),('quantangshi-36549','冬日庙中书事呈栖白上人','羅鄴','quantangshi','','卷37','日高荒庙掩双扉，杉迳无人鸟雀悲。
昨日江潮起归思，满窗风雨觉来时。
何堪身计长如此，闲尽炉灰却是疑。
赖有碧云吟句客，禅余相访说新诗。','',''),('quantangshi-36550','夏日题远公北阁','羅鄴','quantangshi','','卷37','危阁压山冈，晴空疑鸟行。
胜搜花界尽，响益梵音长。
有月堪先到，无风亦自凉。
人烟纷绕绕，诸树共苍苍。
榻恋高楼语，瓯怜昼茗香。
此身闲未得，驱马入残阳。','',''),('quantangshi-36551','秋蝶二首 一','羅鄴','quantangshi','','卷37','秦楼花发时，秦女笑相随。
及到秋风日，飞来欲问谁。','',''),('quantangshi-36552','秋蝶二首 二','羅鄴','quantangshi','','卷37','似厌栖寒菊，翩翩占晚阳。
愁人如见此，应下泪千行。','',''),('quantangshi-36553','秋别','羅鄴','quantangshi','','卷37','别路垂[杨]柳，秋风凄管弦。
青楼君去后，明月为谁圆。','',''),('quantangshi-36554','共友人看花','羅鄴','quantangshi','','卷37','愁将万里身，来伴看花人。
何事独惆怅，故园还又春。','',''),('quantangshi-36555','行次','羅鄴','quantangshi','','卷37','终日长程复短程，一山行尽一山青。
路傍君子莫相笑，天上由来有客星。','',''),('quantangshi-36556','鳯州北楼','羅鄴','quantangshi','','卷37','城上层楼北望时，闲云远水自相宜。
人人尽道堪图画，枉遣山翁醉习池。','',''),('quantangshi-36557','赠僧','羅鄴','quantangshi','','卷37','繁华举世皆如梦，今古何人肯暂闲。
唯有东林学禅客，白头闲坐对青山。','',''),('quantangshi-36558','曲江春感','羅隱','quantangshi','','卷37','江头日暖花又开，江东行客心悠哉。
高阳酒徒半雕落，终南山色空崔嵬。
圣代也知无弃物，侯门未必用非才。
一船明月一竿竹，家住五湖归去来。','',''),('quantangshi-36559','皇陂','羅隱','quantangshi','','卷37','皇陂潋滟深复深，陂西下马聊登临。
垂杨风轻弄翠带，鲤鱼日暖跳黄金。
三月穷途无胜事，十年流水见归心。
输他谷口郑夫子，偷得闲名说至今。','',''),('quantangshi-36560','寄郑补阙','羅隱','quantangshi','','卷37','夫子门前数仞墙，每经过处忆游梁。
路从青琐无因见，恩在丹心不可忘。
未必便为谗口隔，只应贪草谏书忙。
别来愁悴知多少，两度槐花马上黄。','',''),('quantangshi-36561','牡丹花','羅隱','quantangshi','','卷37','似共东风别有因，绛罗高卷不胜春。
若教解语应倾国，任是无情亦动人。
芍药与君为近侍，芙蓉何处避芳尘。
可怜韩令功成后，辜负穠华过此身。','',''),('quantangshi-36562','黄河','羅隱','quantangshi','','卷37','莫把阿胶向此倾，此中天意固难明。
解通银汉应须曲，才出昆仑便不清。
高祖誓功衣带小，仙人占斗客槎轻。
三千年后知谁在，何必劳君报太平。','',''),('quantangshi-36563','汴河','羅隱','quantangshi','','卷37','当时天子是闲游，今日行人特地愁。
柳色纵饶妆故国，水声何忍到扬州。
干坤有意终难会，黎庶无情岂自由。
应笑秦皇用心错，谩驱神鬼海东头。','',''),('quantangshi-36564','西京崇德里居','羅隱','quantangshi','','卷37','进乏梯媒退又难，强随豪贵殢长安。
风从昨夜吹银汉，泪拟何门落玉盘。
抛掷红尘应有恨，思量仙桂也无端。
锦鳞赬尾平生事，却被闲人把钓竿。','',''),('quantangshi-36565','投所思','羅隱','quantangshi','','卷37','顦顇长安何所为，旅魂穷命自相疑。
满川碧嶂无归日，一榻红尘有泪时。
雕琢只应劳郢匠，膏肓终恐误秦医。
浮生七十今三十，从此凄惶未可知。','',''),('quantangshi-36566','经张舍人旧居','羅隱','quantangshi','','卷37','行尘不是昔时尘，谩向朱门忆侍臣。
一榻已无开眼处，九泉应有爱才人。
文余吐凤他年诏，树想栖鸾旧日春。
从此恩深转难报，夕阳衰草泪沾巾。','',''),('quantangshi-36567','雒城作','羅隱','quantangshi','','卷37','大卤旌旗出洛滨，此中烟月已埃尘。
更无楼阁寻行处，只有山川识野人。
早得铸金夸范蠡，旋闻垂钓哭平津。
旧游难得时难遇，回首空城百草春。','',''),('quantangshi-36568','姑苏城南湖陪曹使君游','羅隱','quantangshi','','卷37','水蓼花红稻穗黄，使君兰棹泛回塘。
倚风荇藻先开路，迎斾凫鹥尽着行。
手里兵符神与术，腰间金印彩为囊。
少年太守勋庸盛，应笑燕台两鬓霜。','',''),('quantangshi-36569','秋日有寄姑苏曹使君','羅隱','quantangshi','','卷37','多病无因棹小舟，阖闾城下谒名侯。
水寒不见双鱼信，风便唯闻五袴讴。
早说用兵长暗合，近传观稼亦闲游。
须知谢奕依前醉，闲阻清谈又一秋。','',''),('quantangshi-36570','送章碣赴举','羅隱','quantangshi','','卷37','苹鹿歌中别酒催，粉闱星彩动昭回。
久经罹乱心应破，乍覩升平眼渐开。
顾我昔年悲玉石，怜君今日蕴风雷。
龙门盛事无因见，费尽黄金老隗台。','',''),('quantangshi-36571','寄杨秘书','羅隱','quantangshi','','卷37','湖水平来见鲤鱼，偶因烹处得琼琚。
披寻藻思千重后，吟想冰光万里余。
漳浦病来情转薄，赤城吟苦意何如。
锦衣公子怜君在，十载兵戈从板舆。','',''),('quantangshi-36572','往年进士赵能卿尝话金庭胜事见示叙','羅隱','quantangshi','','卷37','会稽诗客赵能卿，往岁相逢话石城。
正恨故人无上寿，喜闻良宰有高情。
山朝佐命层层耸，水接飞流步步清。
两火一刀罹乱后，会须乘兴雪中行。','',''),('quantangshi-36573','得宣州窦尚书书因投寄二首 一','羅隱','quantangshi','','卷37','双鱼迢递到江滨，伤感南陵旧主人。
万里朝台劳寄梦，十年侯国阻趋尘。
寻知乱后尝辞禄，共喜闲来得养神。
时见齐山敬亭客，不堪戎马战征频。','',''),('quantangshi-36574','得宣州窦尚书书因投寄二首 二','羅隱','quantangshi','','卷37','曾逐旌旗过板桥，世途多难竟蓬飘。
步兵校尉辞公府，车骑将军忆本朝。
醉里旧游还历历，病中衰鬓奈萧萧。
遗簪堕履应留念，门客如今只下僚。','',''),('quantangshi-36575','雪','羅隱','quantangshi','','卷37','细玉罗纹下碧霄，杜门颜巷落偏饶。
巢居只恐高柯折，旅客愁闻去路遥。
撅冻野蔬和粉重，埽庭松叶带酥烧。
寒窗呵笔寻诗句，一片飞来纸上销。','',''),('quantangshi-36576','暇日有寄姑苏曹使君兼呈张郎中郡中宾僚','羅隱','quantangshi','','卷37','嘉植阴阴覆劒池，此中能政动神祗。
湖边观稼雨迎马，城外犒军风满旗。
融酒徒夸无算爵，俭莲还少最高枝。
珊瑚笔架真珠履，曾和陈王几首诗。','',''),('quantangshi-36577','寄右省王谏议','羅隱','quantangshi','','卷37','耳边要静不得静，心里欲闲终未闲。
自是宿缘应有累，可能时事更相关。
鱼慙张翰辞东府，鹤怨周颙负北山。
看却金庭芝术老，又驱车入七人班。','',''),('quantangshi-36578','焚书坑','羅隱','quantangshi','','卷37','千载遗踪一窖尘，路傍耕者亦伤神。
祖龙算事浑乖角，将谓诗书活得人。','',''),('quantangshi-36579','始皇陵','羅隱','quantangshi','','卷37','荒堆无草树无枝，嬾向行人问昔时。
六国英雄漫多事，到头徐福是男儿。','',''),('quantangshi-36580','送沈先辈归送上嘉礼','羅隱','quantangshi','','卷37','青青月桂触人香，白苎衫轻称沈郎。
好继马卿归故里，况闻山简在襄阳。
杯倾别岸应须醉，花傍征军渐欲芳。
拟把金钱赠嘉礼，不堪栖屑困名场。','',''),('quantangshi-36581','春日叶秀才曲江','羅隱','quantangshi','','卷37','江花江草暖相隈，也向江边把酒杯。
春色恼人遮不得，别愁如疟避还来。
安排贱迹无良策，裨补明时望重才。
一曲吴歌齐拍手，十年尘眼未曾开。','',''),('quantangshi-36582','西京道德里','羅隱','quantangshi','','卷37','秦树团团夕结阴，此中庄舃动悲吟。
一枝丹桂未入手，万里苍波长负心。
老去渐知时态薄，愁来唯愿酒杯深。
七雄三杰今何在，休为闲人泪满襟。','',''),('quantangshi-36583','忆夏口','羅隱','quantangshi','','卷37','汉阳渡口兰为舟，汉阳城下多酒楼。
当年不得尽一醉，别梦有时还重游。
襟带可怜吞楚塞，风烟只好狎江鸥。
月明更想曾行处，吹笛桥边木叶秋。','',''),('quantangshi-36584','武牢关','羅隱','quantangshi','','卷37','楚人曾此限封疆，不见清阴六里长。
一壑暮声何怨望，数峰秋势自颠狂。
由来四皓须神伏，大抵秦皇谩气强。
欲学鸡鸣试关吏，太平时节嬾思量。','',''),('quantangshi-36585','途中献晋州孟中丞','羅隱','quantangshi','','卷37','太平天子念蒲东，又委星郎养育功。
昨日隼旟辞阙下，今朝珠履在河中。
楼移庾亮千山月，树待袁宏一扇风。
不及政成应入拜，晋州何足展清通。','',''),('quantangshi-36586','长安秋夜','羅隱','quantangshi','','卷37','远闻天子似羲皇，偶舍渔乡入帝乡。
五等列侯无故旧，一枝仙桂有风霜。
灯欹短焰烧离鬓，漏转寒更滴旅肠。
归计未知身已老，九衢双阙夜苍苍。','',''),('quantangshi-36587','春晚寄钟尚书','羅隱','quantangshi','','卷37','宰府初开忝末尘，四年谈笑隔通津。
官资肯便矜中路，酒盏还应忆故人。
江畔旧游秦望月，槛前公事镜湖春。
如今莫问西禅坞，一炷寒香老病身。','',''),('quantangshi-36588','秋晓寄友人','羅隱','quantangshi','','卷37','洞庭霜落水云秋，又泛轻涟任去留。
世界高谈今已得，宦途清贵旧曾游。
手中彩笔夸题凤，天上泥封奖狎鸥。
更见南来钓翁说，醉吟还上木兰舟。','',''),('quantangshi-36589','秋日有酬','羅隱','quantangshi','','卷37','旧业传家有宝刀，近闻余力更挥毫。
腰间印佩黄金重，卷里诗裁白雪高。
宴罢嘉宾迎凤藻，猎归诸将问龙韬。
分茅列土才三十，犹拟廻头赌锦袍。','',''),('quantangshi-36590','所思','羅隱','quantangshi','','卷37','梁王兔苑荆榛里，炀帝鸡台梦想中。
只觉惘然悲谢傅，未知何以报文翁。
生灵不幸台星拆，造化无情世界空。
划尽寒灰始堪叹，满庭霜叶一窗风。','',''),('quantangshi-36591','送魏校书兼呈曹使君','羅隱','quantangshi','','卷37','乱离无计驻生涯，又事东游惜岁华。
村店酒旗沽竹叶，野桥梅雨泊芦花。
讐书发迹官虽屈，负米安亲路不赊。
应见使君论世旧，埽门重得向曹家。','',''),('quantangshi-36592','四皓庙','羅隱','quantangshi','','卷37','汉惠秦皇事已闻，庙前高木眼前云。
楚王谩费闲心力，六里青山尽属君。','',''),('quantangshi-36593','浮云','羅隱','quantangshi','','卷37','溶溶曳曳自舒张，不向苍梧即帝乡。
莫道无心便无事，也曾愁杀楚襄王。','',''),('quantangshi-36594','早发','羅隱','quantangshi','','卷37','北去南来无定居，此生生计竟何如。
酷怜一觉平明睡，长被鸡声恶破除。','',''),('quantangshi-36595','香','羅隱','quantangshi','','卷37','沈水良材食柏珍，博山烟暖玉楼春。
怜君亦是无端物，贪作馨香忘却身。','',''),('quantangshi-36596','邺城','羅隱','quantangshi','','卷37','台上年年揜翠蛾，台前高树夹漳河。
英雄亦到分香处，能共常人较几多。','',''),('quantangshi-36597','七夕','羅隱','quantangshi','','卷37','络角星河菡萏天，一家懽笑设红筵。
应倾谢女珠玑箧，尽写檀郎锦绣篇。
香帐簇成排窈窕，金针穿罢拜婵娟。
铜壶漏报天将晓，惆怅佳期又一年。','',''),('quantangshi-36598','送臧濆下第谒窦鄜州','羅隱','quantangshi','','卷37','赋得长杨不直钱，却来京口看莺迁。
也知绛灌轻才子，好谒尤常醉少年。
万里故乡云缥缈，一春生计泪澜丸。
多情柱史应相问，与话归心正浩然。','',''),('quantangshi-36599','清明日曲江怀友','羅隱','quantangshi','','卷37','君与田苏即旧游，我于交分亦绸缪。
二年隔绝黄泉下，尽日悲凉曲水头。
鸥鸟似能齐物理，杏花疑欲伴人愁。
寡妻稚子应寒食，遥望江陵一泪流。','',''),('quantangshi-36600','送郑州严员外','羅隱','quantangshi','','卷37','欲将刀笔润王猷，东去先分圣主忧。
满扇好风吹郑圃，一车甘雨别皇州。
尚书碛冷鸿声晚，仆射陂寒树影秋。
从此文星在何处，武牢关外庾公楼。','',''),('quantangshi-36601','孙员外赴阙后重到三衢','羅隱','quantangshi','','卷37','远山高树思悠哉，重倚危楼尽一杯。
谢守已随征诏入，鲁儒犹逐断蓬来。
地寒谩忆移暄手，时急方须济世才。
宣室夜阑如有问，可能全望未然灰。','',''),('quantangshi-36602','衡阳泊木居士庙下作','羅隱','quantangshi','','卷37','乌噪残阳草满庭，此中枯木似人形。
只应神物长为主，未必浮槎即有灵。
八月风波飘不去，四时黍稷荐惟馨。
南朝庾信无因赋，牢落祠前水气腥。','',''),('quantangshi-36603','钟陵见杨秀才','羅隱','quantangshi','','卷37','孺亭滕阁少踟蹰，三度南游一事无。
秪觉流年如鸟逝，不知何处有龙屠？
云归洪井枝柯敛，水下漳江气色麤。
赖得与君同此醉，醒来愁被鬼揶揄。','',''),('quantangshi-36604','自湘川东下立春泊夏口阻风登孙权城','羅隱','quantangshi','','卷37','吴门此去逾千里，湘浦离来想数旬。
只见风师长占路，不知青帝已行春。
危怜坏堞犹遮水，狂爱寒梅欲傍人。
事往时移何足问，且凭村酒暖精神。','',''),('quantangshi-36605','春日忆湖南旧游寄卢校书','羅隱','quantangshi','','卷37','旅榜前年过洞庭，曾提刀笔事甘宁。
瑇筵离隔将军幕，朱履频窥处士星。
恩重匣中孤劒在，梦余江畔数峰青。
金貂见服嘉宾散，回首昭丘一涕零。','',''),('quantangshi-36606','贺淮南节度卢员外赐绯','羅隱','quantangshi','','卷37','俭莲高贵九霄闻，粲粲朱衣降五云。
骢马早年曾避路，银鱼今日且从军。
御题彩服垂天眷，袍展花心透縠纹。
应笑当年老莱子，鲜华都自降明君。','',''),('quantangshi-36607','春日独游禅智寺','羅隱','quantangshi','','卷37','树远连天水接空，几年行乐旧隋宫。
花开花谢还如此，人去人来自不同。
鸾凤调高何处酒，吴牛蹄健满车风。
思量只合腾腾醉，煮海平陈一梦中。','',''),('quantangshi-36608','和淮南李司空同转运员外','羅隱','quantangshi','','卷37','层层高阁旧瀛洲，此地须征第一流。
丞相近年萦倚望，重才今日喜遨游。
荣持健笔金黄贵，恨咽离筵管吹秋。
谁继伊臯送行句，梁王诗好郢人愁。','',''),('quantangshi-36609','后土庙','羅隱','quantangshi','','卷37','四海兵戈尚未宁，始于云外学仪形。
九天玄女犹无圣，后土夫人岂有灵。
一带好云侵鬓绿，两层危岫拂眉青。
韦郎年少知何在，端坐思量太白经。','',''),('quantangshi-36610','金陵夜泊','羅隱','quantangshi','','卷37','冷烟轻澹傍衰丛，此夕秦淮驻断蓬。
栖雁远惊沽酒火，乱鵶高避落帆风。
地销王气波声急，山带秋阴树影空。
六代精灵人不见，思量应在月明中。','',''),('quantangshi-36611','上江州陈员外','羅隱','quantangshi','','卷37','寒江九派转城楼，东下钟陵第一州。
人自中台方贵盛，地从西晋即风流。
旧班久望鵷晴翥，余力犹闻虎夜浮。
应恨属官无健令，异时佳节阻闲游。','',''),('quantangshi-36612','广陵开元寺阁上作','羅隱','quantangshi','','卷37','满槛山川漾落晖，槛前前事去如飞。
云中鸡犬刘安过，月里笙歌炀帝归。
江蹙海门帆散去，地吞淮口树相依。
红楼翠幕知多少，长向东风有是非。','',''),('quantangshi-36613','上鄂州韦尚书','羅隱','quantangshi','','卷37','往岁先皇驭九州，侍臣才业最风流。
文穷典诰虽余力，俗致雍熙尽密谋。
兰省换班青作绶，柏台前引绛为韝。
都缘未负江山兴，开济生灵校一秋。','',''),('quantangshi-36614','早春巴陵道中','羅隱','quantangshi','','卷37','远雪亭亭望未销，岳阳春浅似相饶。
短芦冒土初生笋，高柳偷风已弄条。
波泛洞庭㺍獭健，谷连荆楚鬼神妖。
中流菱唱泊何处，一只画船兰作桡。','',''),('quantangshi-36615','广陵秋日酬进士臧濆见寄','羅隱','quantangshi','','卷37','驿西斜日满窗前，独凭秋栏思渺绵。
数尺断蓬惭故国，一轮清镜泣流年。
已知世事真徒尔，纵有心期亦偶然。
空愧荀家好兄弟，雁来鱼去是因缘。','',''),('quantangshi-36616','淮南送李司空朝觐','羅隱','quantangshi','','卷37','圣君宵旰望时雍，丹诏西来雨露浓。
宣父道高休叹凤，武侯才大本吟龙。
九州似鼎终须负，万物为铜只待镕。
腊后春前更何事，便看经度奏东封。','',''),('quantangshi-36617','秋日禅智寺见裴郎中题名寄韦瞻','羅隱','quantangshi','','卷37','野寺疎钟万木秋，偶寻题处认名侯。
官离南郡应闲暇，地胜东山想驻留。
百盏浓醪成别梦，两行垂露澣羁愁。
心知只有韦公在，更对真踪话旧游。','',''),('quantangshi-36618','广陵春日忆池阳有寄','羅隱','quantangshi','','卷37','烟水蒙蒙接板桥，数年经历驻征桡。
醉凭危槛波千顷，愁倚长亭柳万条。
别后故人冠獬豸，病来知己赏鹪鹩。
清流夹宅千家住，会向闲乘一信潮。','',''),('quantangshi-36619','春中湘中题岳麓寺僧舍','羅隱','quantangshi','','卷37','蟾宫虎穴两皆休，来凭危栏送远愁。
多事林莺还谩语，薄情边雁不回头。
春融只待干坤醉，水阔深知世界浮。
欲共高僧话心迹，野花芳草奈相尤。','',''),('quantangshi-36620','出试后投所知','羅隱','quantangshi','','卷37','此日蓬壶两日程，当时消息甚分明。
桃须曼倩催方熟，橘待洪崖遣始行。
岛外音书应有意，眼前尘士渐无情。
莫教更似山西鼠，啮破愁肠恨一生。','',''),('quantangshi-36621','湘南春日怀古','羅隱','quantangshi','','卷37','晴江春暖兰蕙薰，凫鹥苒苒鸥着羣。
洛阳贾谊自无命，少陵杜甫兼有文。
空阔远帆遮落日，苍茫野树碍归云。
松醪酒好昭潭静，闲过中流一吊君。','',''),('quantangshi-36622','江州望庐山','羅隱','quantangshi','','卷37','东南苍翠何崔嵬，横流一望幽抱开。
影寒已令水底去，脚阔欲过湖心来。
深处不唯容鬼怪，暗中兼恐有风雷。
仙人往往今谁在，红杏花香重首回。','',''),('quantangshi-36623','金陵寄窦尚书','羅隱','quantangshi','','卷37','二年岐路有西东，长忆优游楚驿中。
虎帐谈高无客继，马卿官傲少人同。
世危肯使依刘表，山好犹能忆谢公。
此去此恩言不得，谩将闲泪对春风。','',''),('quantangshi-36624','清溪江令公宅','羅隱','quantangshi','','卷37','蛮牋象管夜深时，曾赋陈宫第一诗。
宴罢风流人不见，废来踪迹草应知。
莺怜胜事啼空巷，蜨恋余香舞好枝。
还有往年金甃井，牧童樵叟等闲窥。','',''),('quantangshi-36625','郑州献卢舍人','羅隱','quantangshi','','卷37','海槎闲暇阆风轻，不是安流不肯行。
鸡省露浓汤饼熟，凤池烟暖诏书成。
渔筹已合光儒梦，尧印何妨且治兵。
会将两都收复后，右图仪表左题名。','',''),('quantangshi-36626','别池阳所居','羅隱','quantangshi','','卷37','黄尘初起此留连，火耨刀耕六七年。
雨夜老农伤水旱，雪晴渔父共舟船。
已悲世乱身须去，肯愧途危迹屡迁。
却是九华山有意，列行相送到江边。','',''),('quantangshi-36627','送内使周大夫自杭州朝贡','羅隱','quantangshi','','卷37','八都上将近平戎，便附輶轩奏圣聪。
三接驾前朝觐礼，一函江表战征功。
云间阆苑何时见，水底瑶池触处通。
知有殿庭余力在，莫辞消息寄西风。','',''),('quantangshi-36628','酬黄从事怀旧见寄','羅隱','quantangshi','','卷37','旧游不合到心中，把得君诗意亦同。
水馆酒阑清夜月，香街人散白杨风。
长绳系日虽难绊，辨口谈天不易穷。
世事自随蓬转在，思量何处是飞蓬。','',''),('quantangshi-36629','绣','羅隱','quantangshi','','卷37','一片丝罗□□□，洞房西室女工劳。
花随玉指添春色，鸟逐金针长羽毛。
蜀绵谩夸声自贵，越绫虚说价功高。
可中用作鸳鸯被，红叶枝枝不碍刀。','',''),('quantangshi-36630','西施','羅隱','quantangshi','','卷37','家国兴亡自有时，吴人何苦怨西施。
西施若解倾吴国，越国亡来又是谁。','',''),('quantangshi-36631','自遣','羅隱','quantangshi','','卷37','得即高歌失即休，多愁多恨亦悠悠。
今朝有酒今朝醉，明日愁来明日愁。','',''),('quantangshi-36632','白角箆','羅隱','quantangshi','','卷37','白似琼瑶滑似苔，随梳伴镜拂尘埃。
莫言此个尖头物，几度撩人恶髪来。','',''),('quantangshi-36633','铜雀台','羅隱','quantangshi','','卷37','强歌强舞竟难胜，花落花开泪满膺。
秪合当年伴君死，免交憔悴望西陵。','',''),('quantangshi-36634','鹦鹉','羅隱','quantangshi','','卷37','莫恨雕笼翠羽残，江南地暖陇西寒。
劝君不用分明语，语得分明出转难。','',''),('quantangshi-36635','金钱花','羅隱','quantangshi','','卷37','占得佳名绕树芳，依依相伴向秋光。
若教此物堪收贮，应被豪门尽劚将。','',''),('quantangshi-36636','梅','羅隱','quantangshi','','卷37','天赐胭脂一抹腮，盘中磊落笛中哀。
虽然未得和羹便，曾与将军止渴来。','',''),('quantangshi-36637','钱尚父生日','羅隱','quantangshi','','卷37','大昴分光降斗牛，兴唐宗社作诸侯。
伊夔事业扶千载，韩白机谋冠九州。
贵盛上持龙节钺，延长应续鹤春秋。
锦衣玉食将何报，更俟庄椿一举头。','',''),('quantangshi-36638','寄前户部陆郎中','羅隱','quantangshi','','卷37','出驯桑雉入朝簪，萧洒清名映士林。
近日篇章欺白雪，早年词赋得黄金。
桂堂纵道探龙颔，兰省何曾驻鹤心。
离乱事多人不会，酒浓花暖且闲吟。','',''),('quantangshi-36639','登瓦棺寺阁','羅隱','quantangshi','','卷37','下盘空迹上云浮，偶逐僧行步步愁。
暂憩已知须用意，渐来争忍不回头。
烟中树老重江晚，铎外风轻四境秋。
嬾指台城更东望，鹊飞龙鬬尽荒丘。','',''),('quantangshi-36640','九华山费征君所居','羅隱','quantangshi','','卷37','草堂何处试徘徊，见说遗踪向此开。
蟾桂自归三径后，鹤书曾降九天来。
白云事迹依前在，青琐光阴竟不回。
尽夕为君思曩日，野泉呜咽路莓苔。','',''),('quantangshi-36641','途中寄怀','羅隱','quantangshi','','卷37','不知何处是前程，合眼腾腾信马行。
两鬓已衰时未遇，数峰虽在病相撄。
尘埃巩洛虚光景，诗酒江湖漫姓名。
试哭军门看谁问，旧来还似禰先生。','',''),('quantangshi-36642','京口见李侍郎','羅隱','quantangshi','','卷37','傞傞江柳欲矜春，铁瓮城边见故人。
屈指不堪言甲子，披风常记是庚申。
别来且喜身俱健，乱后休悲业尽贫。
还有杖头沽酒物，待寻山寺话逡巡。','',''),('quantangshi-36643','秋日酬张特玄','羅隱','quantangshi','','卷37','病寄南徐两度秋，故人依约亦扬州。
偶因雁足思闲事，拟棹孤舟访旧游。
风急几闻江上笛，月高谁共酒家楼。
平生意气消磨尽，甘露轩前看水流。','',''),('quantangshi-36644','登高咏菊尽','羅隱','quantangshi','','卷37','篱畔霜前偶得存，苦教迟晚避兰荪。
能销造化几多力，不受阳和一点恩。
生处岂容依玉砌，要时还许上金罇。
陶公没后无知己，露滴幽丛见泪痕。','',''),('quantangshi-36645','登夏州城楼','羅隱','quantangshi','','卷37','寒城猎猎戍旗风，独倚危楼怅望中。
万里山河唐土地，千年魂魄晋英雄。
离心不忍听边马，往事应须问塞鸿。
好脱儒冠从校尉，一枝长戟六钧弓。','',''),('quantangshi-36646','水边偶题','羅隱','quantangshi','','卷37','野水无情去不回，水边花好为谁开。
只知事逐眼前去，不觉老从头上来。
穷似丘轲休叹息，达如周召亦尘埃。
思量此理何人会，蒙邑先生最有才。','',''),('quantangshi-36647','故洛阳公镇大梁时隐得游门下今之经历事往人非聊抒所怀以伤以谢','羅隱','quantangshi','','卷37','孤舟欲泊思何穷，曾忆西来值雪中。
珠履少年初满座，白衣游子也从公。
狂抛赋笔琉璃冷，醉倚歌筵瑇瑁红。
今日斯文向谁说，泪碑棠树两成空。','',''),('quantangshi-36648','杜陵秋思','羅隱','quantangshi','','卷37','南望商于北帝都，两堪栖托两无图。
只闻斥逐张公子，不觉悲同楚大夫。
岩畔早凉生紫桂，井边疎影落高梧。
一杯渌酒他年忆，沥向青波寄五湖。','',''),('quantangshi-36649','隐尝在江陵忝故中令白公叨蒙知遇今复重过渚宫感事悲身遂成长句','羅隱','quantangshi','','卷37','往岁酇侯镇渚宫，曾将清律暖孤蓬。
才怜曼倩三冬后，艺许由基一箭中。
言重不能轻薄命，地寒终是泣春风。
凤凰池涸台星拆，回首岐山忆至公。','',''),('quantangshi-36650','夜泊毗陵无锡县有寄','羅隱','quantangshi','','卷37','草虫幽咽树初团，独系孤舟夜已阑。
浊浪势奔吴苑急，疎钟声彻惠山寒。
愁催鬓髪凋何易，贫恋家乡别渐难。
他日亲朋应大笑，始知书劒是无端。','',''),('quantangshi-36651','桃花','羅隱','quantangshi','','卷37','暖触衣襟漠漠香，闲梅遮柳不胜芳。
数枝艳拂文君酒，半里红欹宋玉墙。
尽日无人疑怅望，有时经雨乍凄凉。
旧山山下还如此，廻首东风一断肠。','',''),('quantangshi-36652','筹笔驿','羅隱','quantangshi','','卷37','抛掷南阳为主忧，北征东讨尽良筹。
时来天地皆同力，运去英雄不自由。
千里山河轻孺子，两朝冠劒恨谯周。
唯余岩下多情水，犹解年年傍驿流。','',''),('quantangshi-36653','重过随州故兵部李侍郎恩知因抒长句','羅隱','quantangshi','','卷37','庄周高论伯牙琴，闲夜思量泪满襟。
四海共谁言近事，九原从此负初心。
鸥翻汉浦风波急，雁下郧溪雾雨深。
慙愧苍生还有意，解歌襦袴至如今。','',''),('quantangshi-36654','商于驿楼东望有感','羅隱','quantangshi','','卷37','山川去接汉江东，曾伴隋侯醉此中。
歌绕夜梁珠宛转，舞娇春席雪朦胧。
棠遗善政阴犹在，薤送哀声事已空。
惆怅知音竟难得，两行清泪白杨风。','',''),('quantangshi-36655','寄南城韦逸人','羅隱','quantangshi','','卷37','杜甫诗中韦曲花，至今无赖尚豪家。
美人晓折露沾袖，公子醉时香满车。
万里丹青传不得，二年风雨恨无涯。
羡他南涧高眠客，春去春来任物华。','',''),('quantangshi-36656','梅花','羅隱','quantangshi','','卷37','吴王醉处十余里，照野拂衣今正繁。
经雨不随山鸟散，倚风疑共路人言。
愁怜粉艳飘歌席，静爱寒香扑酒罇。
欲寄所思无好信，为人惆恨又黄昏。','',''),('quantangshi-36657','淮南高骈所造迎仙楼','羅隱','quantangshi','','卷37','鸾音鹤信杳难回，凤驾龙车早晚来。
仙境是谁知处所，人间空自造楼台。
云侵朱槛应难到，虫网闲窗永不开。
子细思量成底事，露凝风摆作尘埃。','',''),('quantangshi-36658','和禅月大师见赠','羅隱','quantangshi','','卷37','高僧惠我七言诗，顿豁尘心展白眉。
秀似谷中花媚日，清如潭底月圆时。
应观法界莲千叶，肯折人间桂一枝。
漂荡秦吴十余载，因循犹恨识师迟。','',''),('quantangshi-36659','谒文宣王庙','羅隱','quantangshi','','卷37','晚来乘兴谒先师，松柏凄凄人不知。
九仭萧墙堆瓦砾，三间茅殿走狐狸。
雨淋状似悲麟泣，露滴还同叹凤悲。
傥使小儒名稍立，岂教吾道受栖迟。','',''),('quantangshi-36660','代文宣王答','羅隱','quantangshi','','卷37','三教之中儒最尊，止戈为武武尊文。
吾今尚自披蓑笠，你等何须读典坟。
释氏宝楼侵碧汉，道家宫殿拂青云。
若教颜闵英灵在，终不羞他李老君。','',''),('quantangshi-36661','重送朗州张员外','羅隱','quantangshi','','卷37','朱轮此去正春风，且驻青云听断蓬。
一榻早年容孺子，双旌今日别文翁。
诚知汲善心长在，争奈干时迹转穷。
酬德酬恩两无路，谩劳惆怅凤城东。','',''),('quantangshi-36662','广陵秋夜读进士常修三篇因题','羅隱','quantangshi','','卷37','入蜀归吴三首诗，藏于笥箧重于师。
劒关夜读相如听，瓜步秋吟炀帝悲。
景物也知输健笔，时情谁不许高枝。
明年二月春风里，江岛闲人慰所思。','',''),('quantangshi-36663','逼试投所知','羅隱','quantangshi','','卷37','桃在仙翁旧苑傍，暖烟轻霭扑人香。
十年此地频偷眼，二月春风最断肠。
曾恨梦中无好事，也知囊里有仙方。
寻思仙骨终难得，始与回头问玉皇。','',''),('quantangshi-36664','汉江上作','羅隱','quantangshi','','卷37','汉江波浪渌于苔，每到江边病眼开。
半雨半风终日恨，无名无迹几时回。
云生岸谷秋阴合，树接帆樯晚思来。
对此空惭圣明代，忍教缨上有尘埃。','',''),('quantangshi-36665','秋夜寄进士顾荣','羅隱','quantangshi','','卷37','秋河耿耿夜沈沈，往事三更尽到心。
多病谩劳窥圣代，薄才终是费知音。
家山梦后帆千尺，尘土搔来髪一簪。
空羡良朋尽高价，可怜东箭与南金。','',''),('quantangshi-36666','寄渭北徐从事','羅隱','quantangshi','','卷37','暖云慵堕柳垂条，骢马徐郎过渭桥。
官秩旧参荀祕监，罇罍今伴霍嫖姚。
科随鹄箭频曾中，礼向侯弓以重招。
莫恨东风促行李，不多时节却归朝。','',''),('quantangshi-36667','徐寇南逼感事献江南知己次韵','羅隱','quantangshi','','卷37','酒阑离思浩无穷，西望维扬忆数公。
万里飘零身未了，一家知奖意曾同。
云横晋国尘应暗，路转吴江信不通。
今日便成卢子谅，满襟珠泪堕霜风。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-36668','寄三衢孙员外','羅隱','quantangshi','','卷37','小敷文伯见何时，南望三衢渴复饥。
天子未能崇典诰，诸生徒欲恋旌旗。
风高绿野苗千顷，露冷平楼酒满巵。
尽是数旬陪奉处，使君争肯不相思。','',''),('quantangshi-36669','淮南送卢端公归台','羅隱','quantangshi','','卷37','凤鸾势逸九霄宽，北去南来任羽翰。
朱绂两参王俭府，绣衣三领杜林官。
道从上国曾匡济，才向牢盆始重难。
应笑张纲谩生事，埋轮不得在长安。','',''),('quantangshi-36670','炀帝陵','羅隱','quantangshi','','卷37','入郭登桥出郭船，红楼日日柳年年。
君王忍把平陈业，只博雷塘数亩田。','',''),('quantangshi-36671','马嵬坡','羅隱','quantangshi','','卷37','佛屋前头野草春，贵妃轻骨此为尘。
从来绝色知难得，不破中原未是人。','',''),('quantangshi-36672','柳','羅隱','quantangshi','','卷37','灞岸晴来送别频，相偎相倚不胜春。
自家飞絮犹无定，争解垂丝绊路人。','',''),('quantangshi-36673','隋堤柳','羅隱','quantangshi','','卷37','夹路依依千里遥，路人回首认隋朝。
春风未借宣华意，犹费工夫长绿条。','',''),('quantangshi-36674','孟浩然墓','羅隱','quantangshi','','卷37','数步荒榛接旧蹊，寒江漠漠草凄凄。
鹿门黄土无多少，恰到书生冢便低。','',''),('quantangshi-36675','秦纪','羅隱','quantangshi','','卷37','长策东鞭及海隅，鼋鼍奔起鬼神趋。
怜君未到沙丘日，肯信人间有死无。','',''),('quantangshi-36676','仙掌','羅隱','quantangshi','','卷37','掌前流水驻无尘，掌下轩车日日新。
谩向山头高举手，何曾招得路行人。','',''),('quantangshi-36677','咏月','羅隱','quantangshi','','卷37','湖上风高动白苹，暂延清景此逡巡。
隔年违别成何事，半夜相看似故人。
蟾向静中矜爪距，兔隈明处弄精神。
嫦娥老大应惆怅，倚泣苍苍桂一轮。','',''),('quantangshi-36678','宿荆州江陵驿','羅隱','quantangshi','','卷37','西游象阙愧知音，东下荆溪称越吟。
风动芰荷香四散，月明楼阁影相侵。
闲欹别枕千般梦，醉送征帆万里心。
薜荔衣裳木兰檝，异时烟雨好追寻。','',''),('quantangshi-36679','抚州别阮兵曹','羅隱','quantangshi','','卷37','雪晴天外见诸峰，幽轧行轮有去踪。
内史宅边今独恨，步兵厨畔旧相容。
十年别鬓疑朝镜，千里归心着晚钟。
若不他时更青眼，未知谁肯荐临邛。','',''),('quantangshi-36680','新安投所知','羅隱','quantangshi','','卷37','少年容易舍樵渔，曾辱明公荐子虚。
汉殿寒夜时不食，宋都风急命何疎。
云埋野艇吟归去，草没山田赋遂初。
长劒一寻歌一奏，此心争肯为鲈鱼。','',''),('quantangshi-36681','江边有寄','羅隱','quantangshi','','卷37','江边旧业半雕残，每轸归心即万端。
狂折野梅山店暖，醉吹村笛酒楼寒。
只言圣代谋身易，争奈贫儒得路难。
同病同忧更何事，为君提笔画渔竿。','',''),('quantangshi-36682','送友人归夷门','羅隱','quantangshi','','卷37','二年流落大梁城，每送君归即有情。
别路算来成底事，旧游言着似前生。
苑荒嬾认词人会，门在空怜烈士名。
至竟男儿分应定，不须惆怅谷中莺。','',''),('quantangshi-36683','湘中见进士乔诩','羅隱','quantangshi','','卷37','吴公台下别经秋，破虏城边暂驻留。
一笑有情堪解梦，数年无故不同游。
云牵楚思横鱼艇，柳送乡心入酒楼。
且酌松醪依旧醉，谁能相见向春愁。','',''),('quantangshi-36684','上霅川裴郎中','羅隱','quantangshi','','卷37','贵提金印出咸秦，潇洒江城两度春。
一派水清疑见胆，数重山翠欲留人。
望崇早合归黄阁，诗好何妨恋白苹。
自是受恩心未足，却垂双翅羡吴均。','',''),('quantangshi-36685','钱塘江潮','羅隱','quantangshi','','卷37','怒声汹汹势悠悠，罗刹江边地欲浮。
漫道往来存大信，也知反覆向平流。
任抛巨浸疑无底，猛过西陵只有头。
至竟朝昏谁主掌，好骑赬鲤问阳侯。','',''),('quantangshi-36686','送人赴职任褒中','羅隱','quantangshi','','卷37','物态时情难重陈，夫君此去莫伤春。
男儿只要有知己，才子何堪更问津。
万转江山通蜀国，两行珠翠见褒人。
海棠花谢东风老，应念京都共苦辛。','',''),('quantangshi-36687','临川投穆中丞','羅隱','quantangshi','','卷37','试将生计问蓬根，心委寒灰首戴盆。
翅弱未知三岛路，舌顽虚掉五侯门。
啸烟白狖沈高木，捣月清砧触旅魂。
家在碧江归不得，十年鱼艇长苔痕。','',''),('quantangshi-36688','早春送张坤归大梁','羅隱','quantangshi','','卷37','萧萧羸马正尘埃，又送輶轩向吹台。
别酒莫辞今夜醉，故人知是几时回。
泉经华岳犹应冻，花到梁园始合开。
为谢东门抱关吏，不堪惆怅满离杯。','',''),('quantangshi-36689','东归途中作','羅隱','quantangshi','','卷37','松橘苍黄覆钓矶，早年生计近年违。
老知风月终堪恨，贫觉家山不易归。
别岸客帆和雁落，晚程霜叶向人飞。
买臣严助精灵在，应笑无成一布衣。','',''),('quantangshi-36690','送进士臧濆下第后归池州','羅隱','quantangshi','','卷37','赋成无处换黄金，却向春风动越吟。
天子爱才虽仄席，诸生多病又沾襟。
柳攀灞岸狂遮袂，水忆池阳渌满心。
珍重彩衣归正好，莫将闲事系升沈。','',''),('quantangshi-36691','湘中赠范郧','羅隱','quantangshi','','卷37','丹桂无心彼此谙，二年疎嬾共江潭。
愁知酒盏终难舍，老觉人情转不堪。
云外鸳鸯非故旧，眼前胶漆似烟岚。
劳歌一曲霜风暮，击折湘妃白玉簪。','',''),('quantangshi-36692','寄张侍郎','羅隱','quantangshi','','卷37','衰羸岂合话荆州，争奈思多不自由。
无路重趋桓典马，有诗曾上仲宣楼。
尘销别迹堪垂泪，树拂他门嬾举头。
一种人间太平日，独教零落忆沧州。','',''),('quantangshi-36693','渚宫秋思','羅隱','quantangshi','','卷37','楚城日暮烟霭深，楚人驻马还登临。
襄王台下水无赖，神女庙前云有心。
千载是非难重问，一江风雨好闲吟。
欲招屈宋当时魄，兰败荷枯不可寻。','',''),('quantangshi-36694','闲居早秋','羅隱','quantangshi','','卷37','槐杪清蝉烟雨余，萧萧凉叶堕衣裾。
噪槎乌散沈苍岭，弄杵风高上碧虚。
百岁梦生悲蛱蜨，一朝香死泣芙蕖。
六宫谁买相如赋，团扇恩情日日疎。','',''),('quantangshi-36695','建康','羅隱','quantangshi','','卷37','潮平远岸草侵沙，东晋衰来最可嗟。
庾舅已能窥帝室，王都还是预人家。
山寒老树啼风曲，泉暖枯骸动芷牙。
欲起九原看一徧，秦淮声急日西斜。','',''),('quantangshi-36696','送舒州宿松县傅少府','羅隱','quantangshi','','卷37','江蓠漠漠树重重，东过清淮到宿松。
县好也知临浣水，官闲应得看灊峰。
春风绿野吴歌怨，雪霁平郊楚酒浓。
留取余杯待张翰，明年归棹一从容。','',''),('quantangshi-36697','经故洛阳城','羅隱','quantangshi','','卷37','败垣危堞迹依稀，试驻羸骖吊落晖。
跋扈以成梁冀在，简书难问杜乔归。
由来世事须翻覆，未必余才解是非。
千载昆阳好功业，与君门下作恩威。','',''),('quantangshi-36698','夏州胡常侍','羅隱','quantangshi','','卷37','百尺高台勃勃州，大刀长戟汉诸侯。
征鸿过尽边云阔，战马闲来塞草秋。
国计已推肝胆许，家财不为子孙谋。
仍闻陇蜀由多事，深喜将军未白头。','',''),('quantangshi-36699','寄进士卢休','羅隱','quantangshi','','卷37','半年池口恨萍蓬，今日思量已梦中。
游子马蹄难重到，故人尊酒与谁同。
山横翠后千重绿，蜡想歌时一烬红。
从此客程君不见，麦秋梅雨徧江东。','',''),('quantangshi-36700','赠先辈令狐补阙','羅隱','quantangshi','','卷37','中间声迹早薰然，阻避钧衡过十年。
碧海浪高终济物，苍梧云好已归天。
花迎彩服离莺谷，柳傍东风触马鞭。
应念凄凉洞庭客，夜深双泪忆渔船。','',''),('quantangshi-36701','送秦州从事','羅隱','quantangshi','','卷37','一枝何足解人愁，抛却还随定远侯。
紫陌红尘今别恨，九衢双阙夜同游。
芳时易失劳行止，良会难期且驻留。
若到边庭有来使，试批书尾话梁州。','',''),('quantangshi-36702','湖州裴郎中赴阙后投简寄友生','羅隱','quantangshi','','卷37','锦帐郎官塞诏年，汀州曾驻木兰船。
禰衡酒醒春瓶倒，柳恽诗成海月圆。
歌蹙远山珠滴滴，漏催香烛泪涟涟。
使君入拜吾徒在，宣室他时岂偶然。','',''),('quantangshi-36703','秋日泊平望驿寄太常裴郎中','羅隱','quantangshi','','卷37','苹洲重到杳难期，西倚邮亭忆往时。
北海尊中常有酒，东阳楼上岂无诗。
地清每负生灵望，官重方升礼乐司。
闻说江南旧歌曲，至今犹自唱吴姬。','',''),('quantangshi-36704','西塞山','羅隱','quantangshi','','卷37','吴塞当时指此山，吴都亡后绿孱颜。
岭梅乍暖残妆恨，沙鸟初晴小队闲。
波阔鱼龙应混杂，壁危猿狖奈奸顽。
会将一副寒蓑笠，来与渔翁作往还。','',''),('quantangshi-36705','秋日汴河客舍酬友人','羅隱','quantangshi','','卷37','梁宋追游早岁同，偶然违别事皆空。
年如流水催何急，道似危途动即穷。
醉舞且欣连夜月，狂吟还聚上楼风。
烦君更枉骚人句，白凤灵虵满袖中。','',''),('quantangshi-36706','东归','羅隱','quantangshi','','卷37','仙桂高高似有神，貂裘敝尽取无因。
难将白发期公道，不觉丹枝属别人。
双阙往来慙请谒，五湖归后耻交亲。
盈盘紫蟹千巵酒，添得临岐泪满巾。','',''),('quantangshi-36707','广陵李仆射借示近诗因投献','羅隱','quantangshi','','卷37','朝论国计暮论兵，余力犹随凤藻生。
语继盘盂抛俗格，气兼河岳带商声。
闲寻绮思千花丽，静想高吟六义清。
天柄已持尧典在，更堪回首问缘情。','',''),('quantangshi-36708','三衢哭孙员外','羅隱','quantangshi','','卷37','燕恋雕梁马恋轩，此心从此更何言。
直将尘外三生命，未敌君侯一日恩。
红蜡有时还入梦，片帆何处独销魂？
忍看明发衣襟上，珠泪痕中见酒痕。','',''),('quantangshi-36709','箧中得故王郎中书','羅隱','quantangshi','','卷37','凤里前年别望郎，丁宁唯恐滞吴乡。
劝疎杯酒知妨事，乞与书题作裹粮。
苹鹿未能移海曲，县花寻已落河阳。
九原自此无因见，反覆遗踪泪万行。','',''),('quantangshi-36710','泪','羅隱','quantangshi','','卷37','逼脸横颐咽复匀，也曾谗毁也伤神。
自从鲁国潸然后，不是奸人即妇人。','',''),('quantangshi-36711','子规','羅隱','quantangshi','','卷37','铜梁路远草青青，此恨那堪枕上听。
一种有冤犹可报，不如衔石叠沧溟。','',''),('quantangshi-36712','姑苏台','羅隱','quantangshi','','卷37','让高泰伯开基日，贤见延陵复命时。
未会子孙因底事，解崇台榭为西施。','',''),('quantangshi-36713','王浚墓','羅隱','quantangshi','','卷37','男儿未必尽英雄，但到时来即命通。
若使吴都犹王气，将军何处立殊功。','',''),('quantangshi-36714','京中晚望','羅隱','quantangshi','','卷37','心如野鹿迹如萍，谩向人间性一灵。
往事不知多少梦，夜来和酒一时醒。','',''),('quantangshi-36715','寄窦泽处士二首 一','羅隱','quantangshi','','卷37','兰亭醉客旧知闻，欲问平安隔海云。
不是金陵钱太尉，世事谁肯更容身。','',''),('quantangshi-36716','寄窦泽处士二首 二','羅隱','quantangshi','','卷37','鳌背楼台拂白榆，此中槎客亦踟蹰。
牢山道士无仙骨，却向人间作酒徒。','',''),('quantangshi-36717','省试秋风生桂枝','羅隱','quantangshi','','卷37','凉吹从何起，中宵景象清。
漫随云叶动，高傍桂枝生。
漠漠看无际，萧萧别有声。
远吹斜汉转，低拂白榆轻。
寥泬工夫大，干坤岁序更。
因悲远归客，长望一枝荣。','',''),('quantangshi-36718','思故人','羅隱','quantangshi','','卷37','故人不可见，聊复拂鸣琴。
鹊绕风枝急，萤藏露草深。
平生四方志，此夜五湖心。
惆怅友朋尽，洋洋漫好音。','',''),('quantangshi-36719','寄陆龟蒙','羅隱','quantangshi','','卷37','龙楼李丞相，昔岁仰高文。
黄阁寻无主，青山竟未焚。
夜船乘海月，秋寺伴江云。
却恐尘埃里，浮名点污君。','',''),('quantangshi-36720','题方干诗','羅隱','quantangshi','','卷37','中间李建州，夏汭偶同游。
顾我论佳句，推君最上流。
九霄无鹤板，双鬓老渔舟。
世难方如此，何当浣旅愁。','',''),('quantangshi-36721','秋江','羅隱','quantangshi','','卷37','秋江待晚潮，客归斾旌摇。
细雨翻芦叶，高风却柳条。
兵戈村落破，饥俭虎狼骄。
吾土兼连此，离魂望里消。','',''),('quantangshi-36722','寄制诰李舍人','羅隱','quantangshi','','卷37','梁王握豹韬，雪里见枚臯。
上客趋丹陛，游人叹二毛。
门闲知待诏，星动想濡毫。
一首长杨赋，应嫌索价高。','',''),('quantangshi-36723','秋日怀孟夷庚','羅隱','quantangshi','','卷37','秋日黄陂下，孤舟忆共谁。
江山三分楚，风雨二妃祠。
知己秦貂没，流年贾鵩悲。','',''),('quantangshi-36724','送李右丞分司','羅隱','quantangshi','','卷37','分漕得洛川，谠议更昭然。
在省曾批敕，中台肯避权。
所悲时渐薄，共贺道由全。
卖与清平代，相兼直几钱。','',''),('quantangshi-36725','郴江迁客','羅隱','quantangshi','','卷37','不是逢清世，何由见皂囊。
事虽危虎尾，名胜泊鵷行。
毒雾郴江阔，愁云楚驿长。
归时有诗赋，一为吊沈湘。','',''),('quantangshi-36726','感旧','羅隱','quantangshi','','卷37','劒佩孙弘阁，戈鋋太尉营。
重言虚有位，孤立竟无成。
丘陇笳箫咽，池台岁月平。
此恩何以报，归处是柴荆。','',''),('quantangshi-36727','鹰','羅隱','quantangshi','','卷37','越海霜天暮，辞韬野草干。
俊通司隶职，严奉武夫官。
眼恶藏蜂在，心麤逐物殚。
近来脂腻足，驱遣不妨难。','',''),('quantangshi-36728','秋日寄狄补阙','羅隱','quantangshi','','卷37','红尘扰扰间，立马看南山。
谩道经年往，何妨逐日闲。
病中霜叶赤，愁里鬓毛斑。
不为良知在，驱车已出关。','',''),('quantangshi-36729','寄易定公乘亿侍郎','羅隱','quantangshi','','卷37','谢舞仍宫柳，高奇世少双。
侍中生不到，园令死须降。
班秩通乌府，罇罍奉碧幢。
昭王有余烈，试为祷迷邦。','',''),('quantangshi-36730','寄大理徐郎中','羅隱','quantangshi','','卷37','佐棘竟谁同，因思证圣中。
事虽忘显报，理合有阴功。
官序诜枝老，幽尘范甑空。
几时潘好礼，重与话清风。','',''),('quantangshi-36731','寄苏拾遗','羅隱','quantangshi','','卷37','早岁长杨赋，当年谏猎书。
格高时辈伏，言数宦情疎。
慷慨传丹桂，艰难保旧居。
退朝观藁草，能望马相如。','',''),('quantangshi-36732','寄许融','羅隱','quantangshi','','卷37','多病仍疎拙，唯君与我同。
帝乡年共老，江徼业俱空。
燕冷辞华屋，蛩凉恨晓丛。
白云高几许，全属采芝翁。','',''),('quantangshi-36733','寄礼部郑员外','羅隱','quantangshi','','卷37','栾郄门风大，裴王礼乐优。
班资冠鸡舌，人品压龙头。
夜直炉香细，晴编疏草稠。
近闻潘散骑，三十二悲秋。','',''),('quantangshi-36734','菊','羅隱','quantangshi','','卷37','篱落岁云暮，数枝聊自芳。
雪裁纤蘂密，金拆小苞香。
千载白衣酒，一生青女霜。
春丛莫轻薄，彼此有行藏。','',''),('quantangshi-36735','台城','羅隱','quantangshi','','卷37','水国春常在，台城夜未寒。
丽华承宠渥，江令捧杯盘。
宴罢明堂烂，诗成宝炬残。
兵来吾有计，金井玉钩栏。','',''),('quantangshi-36736','旧游','羅隱','quantangshi','','卷37','良时不复再，渐老更难言。
远水犹经眼，高楼似断魂。
依依宋玉宅，历历长卿村。
今日空江畔，相于只酒樽。','',''),('quantangshi-36737','寄虔州薛大夫','羅隱','quantangshi','','卷37','祝融峰下别，三载梦魂劳。
地转南康重，官兼亚相高。
海鹏终负日，神马背眠槽。
会得窥成绩，幽窗染兔毫。','',''),('quantangshi-36738','苏小小墓','羅隱','quantangshi','','卷37','魂兮檇李城，犹未有人耕。
好月当年事，残花触处情。
向谁曾艳冶，随分得声名。
应侍吴王宴，兰桡暗送迎。','',''),('quantangshi-36739','寒食日早出城东','羅隱','quantangshi','','卷37','青门欲曙天，车马已喧阗。
禁柳疎风雨，墙花拆露鲜。
向谁夸丽景，只是叹流年。
不得高飞便，回头望纸鸢。','',''),('quantangshi-36740','秋日怀贾随进士','羅隱','quantangshi','','卷37','边寇日骚动，故人音信稀。
长缨慙贾谊，孤愤忆韩非。
晓匣鱼肠冷，春园鸭掌肥。
知君安未得，聊且示忘机。','',''),('quantangshi-36741','乱后逢友人','羅隱','quantangshi','','卷37','沧海去未得，倚舟聊问津。
生灵寇盗尽，方镇改更贫。
梦里旧行处，眼前新贵人。
从来事如此，君莫独霑巾。','',''),('quantangshi-36742','残花','羅隱','quantangshi','','卷37','已叹良时晚，仍悲别酒催。
暖芳随日薄，轻片逐风回。
黛敛愁歌扇，妆残泣镜台。
繁阴莫矜炫，终是共尘埃。','',''),('quantangshi-36743','秋日富春江行','羅隱','quantangshi','','卷37','远岸平如翦，澄江静似铺。
紫鳞仙客驭，金颗李衡奴。
冷叠羣山阔，清涵万象殊。
严陵亦高见，归卧是良图。','',''),('quantangshi-36744','寄侯博士','羅隱','quantangshi','','卷37','规谏扬雄赋，邅回贾谊官。
久贫还往少，孤立转迁难。
清镜流年急，高槐旅舍寒。
侏儒亦何有，饱食向长安。','',''),('quantangshi-36745','送沈光侍御赴职闽中','羅隱','quantangshi','','卷37','未至应居右，全家出帝乡。
礼优逢苑雪，官重带台霜。
夜浦吴潮吼，春滩建水狂。
延平有风雨，从此是腾骧。','',''),('quantangshi-36746','寄袁皓侍郎','羅隱','quantangshi','','卷37','东台失路岐，荣辱事堪悲。
我寝牛衣敝，君居豸角危。
风尘慙上品，才业愧明时。
千里芙蓉幕，何由话所思。','',''),('quantangshi-36747','寄金吾李荪常侍','羅隱','quantangshi','','卷37','西班掌禁兵，兰錡最分明。
晓色严天仗，春寒避火城。
安危虽已任，韬略即嘉声。
请问何功德，壶关寇始平。','',''),('quantangshi-36748','商于驿与于蕴玉话别','羅隱','quantangshi','','卷37','南朝徐庾流，洛下忆同游。
酒采闲坊菊，山登远寺楼。
相思劳寄梦，偶别已经秋。
还被青青桂，催君不自由。','',''),('quantangshi-36749','封禅寺居','羅隱','quantangshi','','卷37','盛礼何由覩，嘉名偶寄居。
周南太史泪，蛮徼长卿书。
砌竹摇风直，庭花泣露疎。
谁能赋秋兴，千里隔吾庐。','',''),('quantangshi-36750','钱','羅隱','quantangshi','','卷37','志士不敢道，贮之成祸胎。
小人无事艺，假尔作梯媒。
解释愁肠结，能分睡眼开。
朱门狼虎性，一半逐君回。','',''),('quantangshi-36751','投寄韦右丞','羅隱','quantangshi','','卷37','赤壁征文聘，中台拜郄诜。
官资参令仆，曹署辖星辰。
幞被从谁起，持纲自此新。
举朝明典教，封纳诏书频。
禁树曾摛藻，台乌旧避尘。','',''),('quantangshi-36752','红叶','羅隱','quantangshi','','卷37','不奈荒城畔，那堪晚照中。
野晴霜浥绿，山冷雨催红。
游子灞陵道，美人长信宫。
等闲居岁暮，摇落意无穷。','',''),('quantangshi-36753','期徐道者不至','羅隱','quantangshi','','卷37','辽鹤虚空语，冥鸿未易亲。
偶然来即是，必拟见无因。
霜霰穷冬令，杯盘旅舍贫。
只应蓟子训，醉后懒分身。','',''),('quantangshi-36754','岁除夜','羅隱','quantangshi','','卷37','官历行将尽，村醪强自倾。
厌寒思暖律，畏老惜残更。
岁月已如此，寇戎犹未平。
儿童不谙事，歌吹待天明。','',''),('quantangshi-36755','雪','羅隱','quantangshi','','卷37','尽道丰年瑞，丰年事若何。
长安有贫者，为瑞不宜多。','',''),('quantangshi-36756','旅梦','羅隱','quantangshi','','卷37','旅梦思迁次，穷愁有叹嗟。
子鹅京口远，粳米会稽赊。
漏涩才成滴，灯寒不作花。
出门聊一望，蟾桂向人斜。','',''),('quantangshi-36757','秋寄张坤','羅隱','quantangshi','','卷37','庭树已黄落，闭门俱寂寥。
未知栖托处，空羡圣明朝。
酒醒乡心阔，云晴客思遥。
吾徒自多感，颜子只箪瓢。','',''),('quantangshi-36758','伤华髪','羅隱','quantangshi','','卷37','旧国迢迢远，清秋种种新。
已衰曾轸虑，初见忽霑巾。
日薄梳兼嬾，根危镊恐频。
青铜不自见，只拟老他人。','',''),('quantangshi-36759','九江早秋','羅隱','quantangshi','','卷37','雨过晚凉生，楼中枕簟清。
海风吹乱木，岩磬落孤城。
百岁几多日，四蹄无限程。
西邻莫高唱，俱是别离情。','',''),('quantangshi-36760','初秋寄友人','羅隱','quantangshi','','卷37','九华曾屏迹，罹乱与心违。
是处堪终老，新秋又未归。
病中芳草歇，愁里白云飞。
樵侣兼同志，音书近亦稀。','',''),('quantangshi-36761','秋居有寄','羅隱','quantangshi','','卷37','端居湖岸东，生计有无中。
魇处千般鬼，寒时百种风。
性灵纵道拙，心事奈成空。
多谢金台客，何当一笑同。','',''),('quantangshi-36762','雪霁','羅隱','quantangshi','','卷37','南山雪乍晴，寒气转峥嵘。
销却闲门出，随他骏马行。
一竿如有计，五鼎岂须烹。
愁见天街草，青青又欲生。','',''),('quantangshi-36763','堠子','羅隱','quantangshi','','卷37','终日路岐旁，前程亦可量。
未能慙面黑，只是恨头方。
雅旨逾千里，高文近两行。
君知不识字，第一莫形相。','',''),('quantangshi-36764','初夏寄顾绍宗','羅隱','quantangshi','','卷37','江上偶分袂，四回寒暑更。
青山无路入，白发满头生。
郢浦雁寻过，镜湖蝉又鸣。
怜君未归日，杯酒若为情。','',''),('quantangshi-36765','寄第五尊师','羅隱','quantangshi','','卷37','苕溪烟月久因循，野鹤衣裘独茧纶。
只说泊船无定处，不知携手是何人。
朱黄拣日囚尸鬼，青白临时注脑神。
欲访先生问经诀，世间难得不由身。','',''),('quantangshi-36766','寄西华黄炼师','羅隱','quantangshi','','卷37','西华有路入中华，依约山川认永嘉。
羽客昔时留筱簜，故人今又种烟霞。
坛高已降三清鹤，海近应通八月槎。
盛事两般君总得，老莱衣服戴颙家。','',''),('quantangshi-36767','所思','羅隱','quantangshi','','卷37','西上青云未有期，东归沧海一何迟。
酒阑梦觉不称意，花落月明空所思。
长恐病侵多事日，可堪贫过少年时。
鬬鸡走狗五陵道，惆怅输他轻薄儿。','',''),('quantangshi-36768','送支使萧中丞赴阙','羅隱','quantangshi','','卷37','八年刀笔到京华，归去青冥路未赊。
今日风流卿相客，旧时基业帝王家。
彤庭彩凤虽添瑞，望府红莲已减花。
从此常僚如有问，海边麇鹿斗边槎。','',''),('quantangshi-36769','送人归湘中兼寄旧知','羅隱','quantangshi','','卷37','青溪烟雨九华山，乱后应同梦寐间。
万里分飞休掩袂，两旬相见且开颜。
君依宰相貉蝉贵，我恋王门鬓髪斑。
为谢伏波筵上客，几时金印拟西还。','',''),('quantangshi-36770','自贻','羅隱','quantangshi','','卷37','衰老应难更进趋，药畦经卷自朝晡。
纵无显效亦藏拙，若有所成甘守株。
汉武巡游虚轧轧，秦皇吞并谩驱驱。
如何只见丁家鹤，依旧辽东叹绿芜。','',''),('quantangshi-36771','暇日感怀因寄同院吴蜕拾遗','羅隱','quantangshi','','卷37','璧池清秩访燕台，曾捧瀛州札翰来。
今日二难俱大夜，当时三幅谩高才。
戏悲槐市便便笥，狂忆樟亭满满杯。
犹幸小兰同舍在，每因相见即衔哀。','',''),('quantangshi-36772','偶兴','羅隱','quantangshi','','卷37','逐队随行二十春，曲江池畔避车尘。
如今赢得将衰老，闲看人间得意人。','',''),('quantangshi-36773','题凿石山僧院','羅隱','quantangshi','','卷37','日夜潮声送是非，一回登眺一忘机。
怜师好事无人见，不把兰芽染褐衣。','',''),('quantangshi-36774','圉城偶作','羅隱','quantangshi','','卷37','东望陈留日欲曛，每因刀笔想夫君。
自从郭泰碑铭后，只见黄金不见文。','',''),('quantangshi-36775','乌程','羅隱','quantangshi','','卷37','两府攀陪十五年，郡中甘雨幕中莲。
一瓶犹是乌程酒，须对霜风度泫然。','',''),('quantangshi-36776','送杨炼师却归贞浩岩','羅隱','quantangshi','','卷37','宦途不复更经营，归去东南任意行。
别后几回思会面，到来相见似前生。
久居竹盖知勤苦，旧业莲峰想变更。
为谢佯狂吴道士，耳中时有铁船声。','',''),('quantangshi-36777','暇日投钱尚父','羅隱','quantangshi','','卷37','牛斗星边女宿间，栋梁虚敞丽江关。
望高汉相东西阁，名重淮王大小山。
礼设鬬倾金凿落，马蹄争撼玉连环。
自慙麇鹿无能事，未报深恩鬓已斑。','',''),('quantangshi-36778','览晋史','羅隱','quantangshi','','卷37','齐王僚属好男儿，偶觅东归便得归。
满目路岐抛似梦，一船风雨去如飞。
盘擎紫线莼初熟，箸拨红丝鲙正肥。
惆怅途中无限事，与君千载两忘机。','',''),('quantangshi-36779','感别元帅尚父','羅隱','quantangshi','','卷37','玉函瑶检下台司，记得当时捧领时。
半壁龙虵蟠造化，满筐山岳动神只。
疲牛舐犊心犹切，阴鹤鸣雏力已衰。
稚子不才身抱疾，日窥贞迹泪双垂。','',''),('quantangshi-36780','尚父偶建小楼特摛丽藻绝句不敢称扬三首 一','羅隱','quantangshi','','卷37','结构叨冯柱石才，敢期幢盖此裴回。
阳春曲调高谁和，尽日焚香倚隗台。','',''),('quantangshi-36781','尚父偶建小楼特摛丽藻绝句不敢称扬三首 二','羅隱','quantangshi','','卷37','瑇簪珠履愧非才，时凭阑干首重回。
只待淮妖翦除后，别倾巵酒贺行台。','',''),('quantangshi-36782','尚父偶建小楼特摛丽藻绝句不敢称扬三首 三','羅隱','quantangshi','','卷37','阑槛初成愧楚才，不知星彩尚迂回。
风流孔令陶钧外，犹记山妖逼小台。','',''),('quantangshi-36783','题玄同先生草堂三首 一','羅隱','quantangshi','','卷37','杳杳诸天路，苍苍大涤山。
景舆留不得，毛节去应闲。
相府旧知己，教门新启关。
太平匡济术，流落在人间。','',''),('quantangshi-36784','题玄同先生草堂三首 二','羅隱','quantangshi','','卷37','先生诀行日，曾奉数行书。
意密寻难会，情深恨有余。
石桥春暖后，句漏药成初。
珍重云兼鹤，从来不定居。','',''),('quantangshi-36785','题玄同先生草堂三首 三','羅隱','quantangshi','','卷37','常时忆讨论，历历事犹存。
酒向余杭尽，云从大涤昏。
往来无道侣，归去有台恩。
自此玄言绝，长应闭洞门。','',''),('quantangshi-36786','城西作','羅隱','quantangshi','','卷37','从军无一事，终日掩空斋。
道薄交游少，才疎进取乖。
野禽鸣聒耳，庭草绿侵阶。
幸自同樗栎，何妨惬所怀。','',''),('quantangshi-36787','冬暮城西晚眺','羅隱','quantangshi','','卷37','谬忝莲华幕，虚霑柏署官。
欹危长抱疾，衰老不禁寒。
时事已日过，世途行转难。
千崖兼万壑，只向望中看。','',''),('quantangshi-36788','秋霁后','羅隱','quantangshi','','卷37','净碧山光冷，圆明露点匀。
渚莲丹脸恨，堤柳翠眉颦。
蝉已送行客，雁应辞主人。
蝇蚊渐无况，日晚自相亲。','',''),('quantangshi-36789','茅斋','羅隱','quantangshi','','卷37','从事不从事，养生非养生。
职为尸禄本，官是受恩名。
时态已相失，岁华从自惊。
西斋一巵酒，衰老与谁倾。','',''),('quantangshi-36790','使者','羅隱','quantangshi','','卷37','使者衔中旨，崎岖万里行。
人心犹未革，天意似难明。
四海霍光第，六宫张奉营。
陪臣无以报，西望不胜情。','',''),('quantangshi-36791','途中逢刘知远','羅隱','quantangshi','','卷37','吴楚烟波里，巢由季孟间。
只言无事贵，不道致身闲。
别渚莲根断，归心桂树顽。
空劳钟璞意，尘世隔函关。','',''),('quantangshi-36792','遁迹','羅隱','quantangshi','','卷37','遁迹知安住，霑襟欲奈何。
朝廷犹礼乐，郡邑忍干戈。
华马凭谁问，胡尘自此多。
因思汉明帝，中夜忆廉颇。','',''),('quantangshi-36793','陇头水','羅隱','quantangshi','','卷37','借问陇头水，年年恨何事。
全疑呜咽声，中有征人泪。
自古无长策，况我非深智。
何计谢潺湲，一宵空不寐。','',''),('quantangshi-36794','秦中富人','羅隱','quantangshi','','卷37','高高起华堂，区区引流水。
粪土金玉珍，犹嫌未奢侈。
陋巷满蓬蒿，谁知有颜子。','',''),('quantangshi-36795','思归行','羅隱','quantangshi','','卷37','不耕南亩田，为爱东堂桂。
身同树上花，一落又经岁。
交亲亦相薄，知己恩潜替。
日开十二门，自是无归计。','',''),('quantangshi-36796','即事中元甲子','羅隱','quantangshi','','卷37','三秦流血已成川，塞上黄云战[马]闲。
只有羸兵填渭水，终无奇事出商山。
田园已没红尘内，弟侄相逢白刃间。
惆怅翠华犹未返，泪痕空滴劒文斑。','',''),('quantangshi-36797','魏城逢故人','羅隱','quantangshi','','卷37','一年两度锦江游，前值东风后值秋。
芳草有情皆碍马，好云无处不遮楼。
山将别恨和心断，水带离声入梦流。
今日因君试回首，澹烟乔木隔绵州。','',''),('quantangshi-36798','游江夏口','羅隱','quantangshi','','卷37','醉别江东酒一杯，往年曾此驻尘埃。
鱼听建业歌声过，水看瞿塘雪影来。
黄祖不能容贱客，费祎终是负仙才。
平生胆气平生恨，今日江边首嬾回。','',''),('quantangshi-36799','春思','羅隱','quantangshi','','卷37','荡漾春风渌似波，惹情摇恨去傞傞。
燕翻永日音声好，柳舞空城意绪多。
蜀国暖回溪峡浪，卫娘清转遏云歌。
可怜户外桃兼李，仲蔚蓬蒿奈尔何。','',''),('quantangshi-36800','黄鹤驿寓题','羅隱','quantangshi','','卷37','野云芳草绕离鞭，敢对青楼倚少年。
秋色未催榆塞雁，人心先下洞庭船。
高歌酒市非狂者，大嚼屠门亦偶然。
车马同归莫同恨，古人头白尽林泉。','',''),('quantangshi-36801','安陆赠徐砺','羅隱','quantangshi','','卷37','灵虵桥下水声声，曾向桥边话别情。
一榻偶依陈太守，三年深忆禰先生。
尘欺鬓色非前事，火爇蓬根有去程。
还把余杯重相劝，不堪秋色背郧城。','',''),('quantangshi-36802','寄钟常侍','羅隱','quantangshi','','卷37','一从朱履步金台，蘖苦冰寒奉上台。
峻节不由人学得，远途终是自将来。
风高渐展摩天翼，干耸方呈构厦材。
应笑樟亭旧同舍，九州无验满炉灰。','',''),('quantangshi-36803','中秋夜不见月','羅隱','quantangshi','','卷37','阴云薄雾上空虚，此夕清光已破除。
只恐异时开霁后，玉轮依旧养蟾蜍。','',''),('quantangshi-36804','魏博罗令公附卷有回','羅隱','quantangshi','','卷37','寒门虽得在诸宗，栖北巢南恨不同。
马上固慙消髀肉，幄中由羡愈头风。
蹉跎岁月心仍切，迢遰江山梦未通。
深荷吾宗有知己，好将刀笔为英雄。','',''),('quantangshi-36805','寄处默师','羅隱','quantangshi','','卷37','甘露卷帘看雨脚，樟亭倚柱望潮头。
十年顾我醉中过，两地与师方外游。
久隔兵戈常寄梦，近无书信更堪忧。
香炉烟霭虎溪月，终棹铁船寻惠休。','',''),('quantangshi-36806','病中上钱尚父','羅隱','quantangshi','','卷37','左脚方行右臂挛，每慙名迹污宾筵。
纵饶吴土容衰病，争奈燕台费料钱。
藜杖已干难更把，竹舆虽在不堪悬。
深恩重德无言处，回首浮生泪泫然。','',''),('quantangshi-36807','送梅处士归宁国','羅隱','quantangshi','','卷37','十五年前即别君，别时天下未纷纭。
乱罹且喜身俱在，存没那堪耳更闻。
良会谩劳悲曩迹，旧交谁去吊荒坟。
殷勤为谢逃名客，想望千秋岭上云。','',''),('quantangshi-36808','经故友所居','羅隱','quantangshi','','卷37','槐花漠漠向人黄，此地追游迹已荒。
清论不知庄叟达，死交空欢赵岐忙。
病来未忍言闲事，老去唯知觅醉乡。
日暮街东策羸马，一声横笛似山阳。','',''),('quantangshi-36809','大梁从事居汜水','羅隱','quantangshi','','卷37','前年帝里望行尘，记得仙家第四人。
泉暖旧谙龙偃息，露寒初见鹤精神。
歌声上榻梁园晚，梦遶残钟汜水春。
知有箧中编集在，只应从此是经纶。','',''),('quantangshi-36810','杜处士新居','羅隱','quantangshi','','卷37','翠敛王孙草，荒诛宋玉茅。
寇余无故物，时薄少深交。
迸笋穿行径，饥雏出坏巢。
小园吾亦有，多病近来抛。','',''),('quantangshi-36811','绝境','羅隱','quantangshi','','卷37','绝境非身事，流年但物华。
水梳苔髪直，风引蕙心斜。
凡客从题凤，肤音未胜蛙。
小船兼有桨，始与问渔家。','',''),('quantangshi-36812','雪中怀友人','羅隱','quantangshi','','卷37','腊酒复腊雪，故人今越乡。
所思谁把盏，端坐恨无航。
兔苑旧游尽，龟台仙路长。
未知邹孟子，何以奉梁王。','',''),('quantangshi-36813','秋晚','羅隱','quantangshi','','卷37','宰邑慙良术，为文愧壮图。
纵饶长委命，争奈渐非夫。
杯酒有时有，乱罹无处无。
金庭在何域，回首一踟蹰。','',''),('quantangshi-36814','升仙桥','羅隱','quantangshi','','卷37','危梁枕路岐，驻马问前时。
价自友朋得，名因妇女知。
直须论运命，不得逞文词。
执戟君乡里，荣华竟若为。','',''),('quantangshi-36815','姑苏[真]娘墓','羅隱','quantangshi','','卷37','春草荒坟墓，萋萋向虎丘。
死犹嫌寂寞，生肯不风流。
皎镜山泉冷，轻裾海雾秋。
还应伴西子，香迳夜深游。','',''),('quantangshi-36816','灵山寺','羅隱','quantangshi','','卷37','晚景聊摅抱，凭栏几荡魂。
槛虚从四面，江阔奈孤根。
幽径薜萝色，小山菭藓痕。','',''),('quantangshi-36817','倚棹','羅隱','quantangshi','','卷37','倚棹听邻笛，霑衣认酒垆。
自缘悲巨室，谁复为穷途。
树解将军梦，城遗御史乌。
直应齐始了，倾酌向寒芜。','',''),('quantangshi-36818','秋夕对月','羅隱','quantangshi','','卷37','夜月色可掬，倚楼聊解颜。
未能分寇盗，徒欲满关山。
背冷金蟾滑，毛寒玉兔顽。
姮娥谩偷药，长寡老中闲。','',''),('quantangshi-36819','寄征士魏员外','羅隱','quantangshi','','卷37','家遁苏门节，清贫粉署官。
不矜朝命重，只恨路行难。
窗晓鸡谭倦，庭秋蝶梦阑。
羡君归未得，还有钓鱼竿。','',''),('quantangshi-36820','宿彭蠡馆','羅隱','quantangshi','','卷37','孤馆少行旅，解鞍增别愁。
远山矜薄暮，高柳怯清秋。
病里见时态，醉中思旧游。
所怀今已矣，何必恨东流。','',''),('quantangshi-36821','萤','羅隱','quantangshi','','卷37','空庭夜未央，点点度西墙。
抱影何微细，乘时忽发扬。
不思因腐草，便拟倚孤光。
若道能通照，车公业肯长。','',''),('quantangshi-36822','早秋宿叶堕所居','羅隱','quantangshi','','卷37','池荷叶正圆，长历报时殚。
旷野云蒸热，空庭雨始寒。
蝇蚊犹得志，簟席若为安。
浮世知谁是，劳歌共一懽。','',''),('quantangshi-36823','蜨','羅隱','quantangshi','','卷37','汉王刀笔精，写尔逼天生。
舞巧何妨急，飞高所恨轻。
野田黄雀虑，山馆主人情。
此物那堪作，庄周梦不成。','',''),('quantangshi-36824','春居','羅隱','quantangshi','','卷37','春风百卉摇，旧国路迢迢。
偶病成疎散，因贫得寂寥。
倚帘高柳弱，乘露小桃夭。
春色常无处，村醪更一瓢。','',''),('quantangshi-36825','轻飙','羅隱','quantangshi','','卷37','轻飙掠晚莎，秋物惨关河。
战垒平时少，斋坛上处多。
楚虽屈子重，汉亦忆廉颇。
不及云台议，空山老薜萝。','',''),('quantangshi-36826','燕','羅隱','quantangshi','','卷37','不必嫌漂露，何妨养羽毛。
汉妃金屋远，卢女杏梁高。
野迥双飞急，烟晴对语劳。
犹胜黄雀在，栖息是蓬蒿。','',''),('quantangshi-36827','陕西晚思','羅隱','quantangshi','','卷37','长途已自穷，此去便西东。
树色荣衰里，人心往返中。
别情流水急，归梦故山空。
莫忘交游分，从来事一同。','',''),('quantangshi-36828','除夜寄张达','羅隱','quantangshi','','卷37','梅花已着眼，竹叶况黏唇。
只此留残岁，那堪忆故人。
乱罹书不远，衰病日相亲。
江浦思归意，明朝又一春。','',''),('quantangshi-36829','寄酬邺王罗令公五首 一','羅隱','quantangshi','','卷37','营室东回廕斥丘，少年承袭拥青油。
坐调金鼎尊明主，横把雕戈拜列侯。
书札二王争巧拙，篇章七子避风流。
西园旧迹今应在，衰老无因奉胜游。','',''),('quantangshi-36830','寄酬邺王罗令公五首 二','羅隱','quantangshi','','卷37','脉散源分历几朝，纵然官宦只卑僚。
正忧末派沦沧海，忽见高枝拂绛霄。
十万貔貅趋玉帐，三千宾客珥金貂。
良时难得吾宗少，应念寒门更寂寥。','',''),('quantangshi-36831','寄酬邺王罗令公五首 三','羅隱','quantangshi','','卷37','敢将衰弱附强宗，细筭还缘血脉同。
湘浦烟波无旧迹，邺都兰菊有遗风。
每怜罹乱书犹达，所恨云泥路不通。
珍重珠玑兼绣段，草玄堂下寄扬雄。','',''),('quantangshi-36832','寄酬邺王罗令公五首 四','羅隱','quantangshi','','卷37','水云开霁立高亭，依约黎阳对福星。
只见篇章矜镂管，不知勋业柱青冥。
早缘入梦金方砺，晚为传家鼎始铭。
鹤髪四垂烟阁远，此生何处拜仪形。','',''),('quantangshi-36833','寄酬邺王罗令公五首 五','羅隱','quantangshi','','卷37','锦笈朱囊连复连，紫鸾飞下浙江边。
绡从海室夺烟雾，乐奏帝官胜管弦。
长笑应刘悲显达，每嫌伊霍少诗篇。
戴湾老圃根基薄，虚费工夫八十年。','',''),('quantangshi-36834','春日投钱塘元帅尚父二首 一','羅隱','quantangshi','','卷37','正忧衰老辱金台，敢望昭王顾问来。
门外旌旗屯[虎豹]，壁闲章句动风雷。
三都节已联翩降，两地花应次第开。
若比紫髯分鼎足，未闻余力有琼环。','',''),('quantangshi-36835','春日投钱塘元帅尚父二首 二','羅隱','quantangshi','','卷37','征东幕府十三州，敢望非才忝上游。
官秩已叨吴品职，姓名兼显鲁春秋。
盐车顾后声方重，火井窥来焰始浮。
一句黄河千载事，麦城王粲谩登楼。','',''),('quantangshi-36836','钱塘府亭','羅隱','quantangshi','','卷37','新恩别启馆娃宫，还拜吴王向此中。
九牧土田周制在，两藩茅社汉仪同。
春生旧苑芳洲雨，香入高台小径风。
更有宠光人未见，问安调膳尽三公。','',''),('quantangshi-36837','野狐泉','羅隱','quantangshi','','卷37','潏潏寒光溅路尘，相传妖物此潜身。
又应改换皮毛后，何处人间作好人。','',''),('quantangshi-36838','宿纪南驿','羅隱','quantangshi','','卷37','策蹇南游忆楚朝，阴风淅淅树萧萧。
不知无忌奸邪骨，又作何山野葛苗。','',''),('quantangshi-36839','赠无相禅师','羅隱','quantangshi','','卷37','人人尽道事空王，心里忙于市井忙。
惟有马当山上客，死门生路两相忘。','',''),('quantangshi-36840','遣兴','羅隱','quantangshi','','卷37','青云路不通，归计奈长蒙。
老恐医方误，穷忧酒盏空。
何堪罹乱后，更入是非中。
长短遭讥笑，回头避钓翁。','',''),('quantangshi-36841','江夏酬高崇节','羅隱','quantangshi','','卷37','腊雪都堂试，春风汴水行。
十年虽抱疾，何处不无情？
羣盗正当路，此游应隔生。
劳君问流落，山下已躬耕。','',''),('quantangshi-36842','鸎声','羅隱','quantangshi','','卷37','井上梧桐暗，花间雾露曦。
一枝晴复暖，百啭是兼非。
金屋梦初觉，玉关人未归。
不堪闲日听，因尔又霑衣。','',''),('quantangshi-36843','仿玉台体','羅隱','quantangshi','','卷37','青楼枕路隅，壁甃复椒涂。
晚梦通帘柙，春寒逼酒罏。
解吟怜芍药，难见恨菖蒲。
试问年多少，邻姬亦姓胡。','',''),('quantangshi-36844','夜泊义兴戏呈邑宰','羅隱','quantangshi','','卷37','溪畔维舟问戴星，此中三害有图经。
长桥可避南山远，却恐难防是最灵。','',''),('quantangshi-36845','听琵琶','羅隱','quantangshi','','卷37','香筵酒散思朝散，偶向梧桐暗处闻。
大底曲中皆有恨，满楼人自不知君。','',''),('quantangshi-36846','经耒阳杜工部墓','羅隱','quantangshi','','卷37','紫菊馨香覆楚醪，奠君江畔雨萧骚。
旅魂自是才相累，闲骨何妨冢更高。
騄骥丧来空蹇蹶，芝兰衰后长蓬蒿。
屈原宋玉邻君处，几驾青螭缓郁陶。','',''),('quantangshi-36847','题袁溪张逸人所居','羅隱','quantangshi','','卷37','蒲梢猎猎燕差差，数里溪光日落时。
芳树文君机上锦，远山孙寿镜中眉。
鸡窗夜静开书卷，鱼槛春深展钓丝。','',''),('quantangshi-36848','升平公主旧第','羅隱','quantangshi','','卷37','乘凤仙人降此时，玉篇才罢到文词。
两轮水硙光明照，百尺鲛绡换好诗。
带砺山河今尽在，风流罇俎见无期。
坛场客散香街暝，惆怅齐竽取次吹。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-36849','寄黔中王从事','羅隱','quantangshi','','卷37','故人刀笔事军书，南转黔江半月余。
别后乡关情几许，近来诗酒兴何如。
贪将醉袖矜莺谷，不把瑶缄附鲤鱼。
今日举觞君莫问，生涯牢落鬓萧疎。','',''),('quantangshi-36850','关亭春望','羅隱','quantangshi','','卷37','关畔春云拂马头，马前春事共悠悠。
风摇岸柳长条困，露裛山花小朵愁。
信越功名高似狗，裴王气力大于牛。
未知至竟将何用，渭水泾川一向流。','',''),('quantangshi-36851','寄徐济进士','羅隱','quantangshi','','卷37','往年疎嬾共江湖，月满花香记得无。
霜压楚莲秋后折，雨催蛮酒夜深酤。
红尘偶别迷前事，丹桂相倾愧后徒。
出得函关抽得手，从来不及阮元瑜。','',''),('quantangshi-36852','寄韦赡','羅隱','quantangshi','','卷37','石城蓑笠阻心期，落尽山花有所思。
羸马二年蓬转后，故人何处月明时？
风催晓雁看看别，雨胁秋蝇渐渐痴。
禅智阑干市桥酒，纵然相见只相悲。','',''),('quantangshi-36853','霅溪晚泊寄裴庶子','羅隱','quantangshi','','卷37','溪风如扇雨如丝，闲步闲吟柳恽诗。
杯酒疎狂非曩日，野花狼藉似当时。
道穷谩有依刘感，才急应无借寇期。
满眼云山莫相笑，与君俱是受深知。','',''),('quantangshi-36854','送姚安之赴任秋浦','羅隱','quantangshi','','卷37','官罢春坊地象雷，片帆高指贵池开。
五侯水暖鱼鳞去，九子山晴雁叙来。
江夏黄童徒逞辩，广都庞令恐非才。
到头称意须年少，赢得时光向酒杯。','',''),('quantangshi-36855','寄乔逸人','羅隱','quantangshi','','卷37','南经湘浦北扬州，别后风帆几度游。
春酒谁家禁烂熳，野花何处最淹留？
欲凭尺素边鸿嬾，未定雕梁海燕愁。
长短此行须入手，更饶君占一年秋。','',''),('quantangshi-36856','塞外','羅隱','quantangshi','','卷37','塞外偷儿塞内兵，圣君宵旰望升平。
碧幢未作朝廷计，白梃犹驱妇女行。
可使御戎无上策，只应忧国是虚声。
汉王第宅秦田土，今日将军已自荣。','',''),('quantangshi-36857','裴庶子除太仆卿因贺','羅隱','quantangshi','','卷37','楚圭班序未为轻，莫惜良途副圣明。
