秩随科第临时贵，官逐簪裾到处清。
应笑马安虚巧宦，四回迁转始为卿。','',''),('quantangshi-36858','咏史','羅隱','quantangshi','','卷37','蠹简遗编试一寻，寂寥前事似如今。
徐陵笔砚珊瑚架，赵胜宾朋瑇瑁簪。
未必片言资国计，只应邪说动人心。
九原郝泚何由起，虚误西蕃八尺金。','',''),('quantangshi-36859','中元夜泊淮口','羅隱','quantangshi','','卷37','木叶回飘水面平，偶因孤棹已三更。
秋凉雾露侵灯下，夜静鱼龙逼岸行。
欹枕正牵题柱思，隔楼谁转遶梁声。
锦帆天子狂魂魄，应过扬州看月明。','',''),('quantangshi-36860','寄池州郑员外','羅隱','quantangshi','','卷37','兽遶朱轮酒满船，郡城萧洒贵池边。
衣同莱子曾分笔，扇似袁宏别有天。
九点好山楼上客，两行高柳雨中烟。
陵阳百姓将何福，社舞村歌又一年。','',''),('quantangshi-36861','归梦','羅隱','quantangshi','','卷37','陆海波涛渐渐深，一回归梦抵千金。
路傍草色休多事，墙外莺声肯有心。
日晚向隅悲断梗，夜阑浇酒哭知音。
贪财败阵谁相悉，鲍叔如今不可寻。','',''),('quantangshi-36862','送溪州使君','羅隱','quantangshi','','卷37','兵寇伤残国力衰，就中南土藉良医。
凤衔泥诏辞丹阙，雕倚霜风上画旗。
官职不须轻远地，生灵只是计临时。
灞桥酒盏黔巫月，从此江心两所思。','',''),('quantangshi-36863','送霅川郑员外','羅隱','quantangshi','','卷37','明时塞诏列分麾，东拥朱轮出帝畿。
