汉帝诏衔应异日，梁王风雪是初筵。
临行不惜刀圭便，愁杀长安买笑钱。','',''),('quantangshi-36869','冬暮寄裴郎中','羅隱','quantangshi','','卷37','晓髪星星入镜宜，早年容易近年悲。
敢言得事时将晚，只恐酬恩日渐迟。
南国倾心应望速，东堂开口欲从谁。
仙郎旧有黄金约，沥胆隳肝更祷祈。','',''),('quantangshi-36870','中元甲子以辛丑驾幸蜀四首 一','羅隱','quantangshi','','卷37','子仪不起浑瑊亡，西幸谁人从武皇。
