几时睿算歼张角，何处愚人戴隗嚣？
跪望嵕山重启告，可能余烈不胜妖。','',''),('quantangshi-36872','中元甲子以辛丑驾幸蜀四首 三','羅隱','quantangshi','','卷37','邪气奔屯瑞气移，清平过尽到艰危。
