可怜一曲还京乐，重对红蕉教蜀儿。','',''),('quantangshi-36873','中元甲子以辛丑驾幸蜀四首 四','羅隱','quantangshi','','卷37','白丁攘臂犯长安，翠辇苍黄路屈盘。
