玉书分薄花生眼，金鼎功迟雪满须。
三秀紫芝劳梦寐，一番红槿恨朝晡。
未知朽败凡间骨，中授先生指教无。','',''),('quantangshi-36906','定远楼','羅隱','quantangshi','','卷37','前年上将定妖氛，曾筑岩城驻大军。
