所喜故人犹会面，不堪良牧已重泉。
醉思把筯欹歌席，狂忆判身入酒船。
今日与君赢得在，戴家湾里两皤然。','',''),('quantangshi-36911','江都','羅隱','quantangshi','','卷37','淮王高宴动江都，曾忆狂生亦坐隅。
九里楼台牵翡翠，两行鸳鹭踏真珠。
歌听丽句秦云咽，诗转新题蜀锦铺。
惆怅晋阳星拆后，世间兵革地荒芜。','',''),('quantangshi-36912','湖上岁暮感怀有寄友人','羅隱','quantangshi','','卷37','雪天萤席几辛勤，同志当时四五人。
兰版地寒俱[受]露，桂堂风恶独伤春。
音书久绝应埋玉，编简难言竟委尘。
唯有广都庞令在，白头罇酒忆交亲。','',''),('quantangshi-36913','送张绾游钟陵','羅隱','quantangshi','','卷37','南忆龙沙两岸行，当时天下尚清平。
醉眠野寺花方落，吟倚江楼月欲明。
老去亦知难重到，乱来争肯不牵情。
西山十二真人在，从此烦君语姓名。','',''),('quantangshi-36914','送{巩/言}光大师','羅隱','quantangshi','','卷37','禹祠分首戴湾逢，健笔寻知达九重。
圣主赐衣怜绝艺，侍臣摛藻许高踪。
宁亲久别街西寺，待诏初离海上峰。
一种苦心师得了，不须回首笑龙钟。','',''),('quantangshi-36915','息夫人庙','羅隱','quantangshi','','卷37','百雉摧残连野青，庙门犹见昔朝廷。
一生虽抱楚王恨，千载终为息地灵。
虫网翠环终缥缈，风吹宝瑟助微冥。
玉颜浑似羞来客，依旧无言照画屏。','',''),('quantangshi-36916','漂母冢','羅隱','quantangshi','','卷37','寂寂荒坟一水滨，芦洲绝岛自相亲。
青娥已落淮边月，白骨甘为泉下尘。
原上荻花飘素髪，道傍菰叶碎罗巾。
虽然寂寞千秋魄，犹是韩侯旧主人。','',''),('quantangshi-36917','感怀','羅隱','quantangshi','','卷37','石径松轩亦自由，谩随浮世逐飘流。
驽骀路结前程恨，蟋蟀床生半夜秋。
揜耳恶闻宫妾语，低颜须向路人羞。
虽教小事相催逼，未到青云拟白头。','',''),('quantangshi-36918','扇上画牡丹','羅隱','quantangshi','','卷37','为爱红芳满砌堦，教人扇上画将来。
叶随彩笔参差长，花逐轻风吹第开。
闲挂几曾停蛱蜨，频摇不怕落莓苔。
根生无地如仙桂，疑是姮娥月里栽。','',''),('quantangshi-36919','书怀','羅隱','quantangshi','','卷37','钓船抛却异乡来，拟向何门用不才。
日晚独登楼上望，马蹄车辙满尘埃。','',''),('quantangshi-36920','七夕','羅隱','quantangshi','','卷37','月帐星房次第开，两情惟恐曙光催。
时人不用穿针待，没得心情送巧来。','',''),('quantangshi-36921','柳','羅隱','quantangshi','','卷37','一簇青烟锁玉楼，半垂阑畔半垂沟。
明年更有新条在，绕乱春风卒未休。','',''),('quantangshi-36922','罗敷水','羅隱','quantangshi','','卷37','雉声角角野田春，试驻征车问水滨。
数树枯桑虽不语，思量应合识秦人。','',''),('quantangshi-36923','京中正月七日立春','羅隱','quantangshi','','卷37','一二三四五六七，万木生芽是今日。
远天归雁拂云飞，近水游鱼迸冰出。','',''),('quantangshi-36924','贵游','羅隱','quantangshi','','卷37','馆陶园外雨初晴，绣毂香车入凤城。
八尺家僮三尺棰，何知高祖要苍生。','',''),('quantangshi-36925','严陵滩','羅隱','quantangshi','','卷37','中都九鼎勤英髦，渔钓牛蓑且遁逃。
世祖升遐夫子死，原陵不及钓台高。','',''),('quantangshi-36926','虚白堂前牡丹相传云太傅手植在钱塘','羅隱','quantangshi','','卷37','欲询往事奈无言，六十年来托此根。
香暖几飘袁虎扇，格高常对孔融罇。
曾忧世乱阴难合，且喜春残色上存。
莫背阑干便相笑，与君俱受主人恩。','',''),('quantangshi-36927','县斋秋晚酬友人朱瓒见寄','羅隱','quantangshi','','卷37','中和节后捧琼瑰，坐读行吟数月来。
只叹雕龙方擅价，不知赬尾竟空回。
千枝白露陶潜柳，百尺黄金郭隗台。
惆怅报君无玉案，水天东望一裴回。','',''),('quantangshi-36928','第五将军于余杭天柱宫入道因题寄','羅隱','quantangshi','','卷37','交棃火枣味何如，闻说苕川已下车。
瓦榼尚携京口酒，草堂应写颍阳书。
亦知得意须乘鹤，未必忘机便钓鱼。
欲恐武皇还望祀，软轮征入问玄虚。','',''),('quantangshi-36929','寄无相禅师','羅隱','quantangshi','','卷37','老住西峰第几层，为师回首忆南能。
有缘有相应非佛，无我无人始是僧。
烂椹作袍名复利，铄金为讲爱兼憎。
何如一衲尘埃外，日日香烟夜夜灯。','',''),('quantangshi-36930','秋日有寄','羅隱','quantangshi','','卷37','丹青未合便回头，见尽人闲事始休。
只有百神朝宝镜，永无纤浪犯虚舟。
曾临铁瓮虽分职，近得金陵亦偶游。
东去西来人不会，上卿踪迹本玄洲。','',''),('quantangshi-36931','送前南昌崔令替任映摄新城县','羅隱','quantangshi','','卷37','五年苛政甚虫螟，深喜夫君已戴星。
大族不唯专礼乐，上才终是惜生灵。
亦知单父琴犹在，莫厌东归酒未醒。
二月春风何处好，亚夫营畔柳青青。','',''),('quantangshi-36932','下第作','羅隱','quantangshi','','卷37','年年模样一般般，何似东归把钓竿。
岩谷谩劳思雨露，彩云终是逐鵷鸾。
尘迷魏阙身应老，水到吴门叶欲残。
至竟穷途也须达，才能长与世人看。','',''),('quantangshi-36933','丁亥岁作','羅隱','quantangshi','','卷37','病想医门渴望梅，十年心地仅成灰。
早知世事长如此，自是孤寒不合来。
谷畔气浓高蔽日，蛰边声暖乍闻雷。
满城桃李君看取，一一还从旧处开。','',''),('quantangshi-36934','北邙山','羅隱','quantangshi','','卷37','一种山前路入秦，嵩山堪爱此伤神。
魏明未死虚留意，庄叟虽生酌满巾。
何必更寻无主骨，也知曾有弄权人。
羡他缑岭吹箫客，闲访云头看俗尘。','',''),('quantangshi-36935','重过三衢哭孙员外','羅隱','quantangshi','','卷37','烂柯山下忍重到，双桧楼前日欲残。
华屋未移春照灼，故侯何在泪丸澜。
不唯济物工夫大，长忆容才尺度宽。
一恸旁人莫相笑，知音衰尽路行难。','',''),('quantangshi-36936','送蕲州裴员外','羅隱','quantangshi','','卷37','六枝仙桂最先春，萧洒高辞九陌尘。
两晋家声须有主，六朝文雅别无人。
荣驱豹尾抛同辈，贵上螭头见近臣。
蕲水苍生莫相羡，早看归去掌丝纶。','',''),('quantangshi-36937','重九日广陵道中','羅隱','quantangshi','','卷37','秋山抱病何处登，前时韦曲今广陵。
广陵大醉不解闷，韦曲旧游堪拊膺。
佳节纵饶随分过，流年无奈得人憎。
却驱羸马向前去，牢落路岐非所能。','',''),('quantangshi-36938','东归别所知','羅隱','quantangshi','','卷37','芙蓉宫阙二妃坛，两处因依五岁寒。
邹律有风吹不变，郄枝无分住应难。
愁心似火还烧鬓，别泪非珠谩落盘。
却羡淮南好鸡犬，也能终始逐刘安。','',''),('quantangshi-36939','旅舍书怀寄所知二首 一','羅隱','quantangshi','','卷37','思量前事不堪寻，牢落余情满素琴。
四海岂无腾跃路，一家长有别离心。
道从汩没甘雌伏，迹恐因循更陆沈。
寂寞谁应吊空馆，异乡时节独霑襟。','',''),('quantangshi-36940','旅舍书怀寄所知二首 二','羅隱','quantangshi','','卷37','簟卷两牀琴瑟秋，暂凭前计奈相尤。
尘飘马尾甘蓬转，酒忆江边有梦留。
隋帝旧祠虽寂寞，楚妃清唱亦风流。
可怜别恨无人见，独背残阳下寺楼。','',''),('quantangshi-36941','西京道中','羅隱','quantangshi','','卷37','半夜秋声独断蓬，百年身事筭成空。
禰生词赋抛江夏，汉祖精神忆沛中。
未必他时能富贵，只应从此见穷通。
边禽陇水休相笑，自有沧洲一棹风。','',''),('quantangshi-36942','粉','羅隱','quantangshi','','卷37','每持纤白助君时，霜自无憀雪自疑。
郎若姓何应解傅，女能窥宋不劳施。
妆成丽色唯花妬，落尽啼痕只镜知。
最好玉京仙署里，更知秋月照琼枝。','',''),('quantangshi-36943','赠渔翁','羅隱','quantangshi','','卷37','叶艇悠扬鹤髪垂，生涯空托一纶丝。
是非不向眼前起，寒暑任从波上移。
风漾长歌笼月里，梦和春雨昼眠时。
逍遥此意谁人会，应有青山渌水知。','',''),('quantangshi-36944','下第寄张坤','羅隱','quantangshi','','卷37','谩费精神掉五侯，破琴孤劒是身讐。
九衢护阙拟何去，玉垒铜梁空旧游。
蝴蝶有情牵晚梦，杜鹃无赖伴春愁。
思量不及张公子，经岁池江倚酒楼。','',''),('quantangshi-36945','东归别常修','羅隱','quantangshi','','卷37','六载辛勤九陌中，却寻归路五湖东。
名慙桂苑一枝绿，鲙忆松江两筯红。
浮世到头须适性，男儿何必尽成功。
唯慙鲍叔深知我，他日蒲帆百尺风。','',''),('quantangshi-36946','言','羅隱','quantangshi','','卷37','圭玷由来尚可磨，似簧终日复如何。
成名成事皆因慎，亡国亡家只为多。
须信祸胎生利口，莫将讥思逞悬河。
猩猩鹦鹉无端解，长向人间被网罗。','',''),('quantangshi-36947','简令生日','羅隱','quantangshi','','卷37','祥烟霭霭拂楼台，庆积玄元节后来。
已向青阳标四序，便从嵩岳应三台。
龟衔玉柄增年筭，鹤舞琼筵献寿杯。
自顾下儒何以祝，柱天功业济时才。','',''),('quantangshi-36948','晚眺','羅隱','quantangshi','','卷37','凭古城边眺晚晴，远村高树转分明。
天如镜面都来静，地似人心总不平。
云向岭头闲不彻，水流溪里太忙生。
谁人得及庄居老，免被荣枯宠辱惊。','',''),('quantangshi-36949','野花','羅隱','quantangshi','','卷37','万点红芳血色殷，为无名字对空山。
多映戏蜨寻香住，少有行人辍棹攀。
若在侯门看不足，为生江岸见如闲。
结根必竟输桃李，长向春城紫陌间。','',''),('quantangshi-36950','病骢马','羅隱','quantangshi','','卷37','枥上病骢蹄褭褭，江边废宅路迢迢。
自经梅雨长垂耳，乍食菰浆欲折腰。
金络衔头光未灭，玉花毛色瘦来焦。
曾听禁漏惊街鼓，惯踏康庄怕小桥。
夜半雄声心尚壮，日中高卧尾还摇。
龙媒落地天池远，何事牵牛在碧霄。','',''),('quantangshi-36951','狄浦','羅隱','quantangshi','','卷37','晴川倚落晖，极目思依依。
野色寒来浅，人家乱后稀。
久贫身不达，多病意长违。
还有渔舟在，时时梦里归。','',''),('quantangshi-36952','南康道中','羅隱','quantangshi','','卷37','弱冠负文翰，此中听鹿鸣。
使君延上榻，时辈仰前程。
丹桂竟多故，白云空有情。
唯余路旁泪，霑洒向尘缨。','',''),('quantangshi-36953','北固亭东望寄默师','羅隱','quantangshi','','卷37','高亭暮色中，往事更谁同。
水谩矜天阔，山应到此穷。
病怜京口酒，老怯海门风。
唯有言堪解，何由见远公。','',''),('quantangshi-36954','华清宫','羅隱','quantangshi','','卷37','楼殿层层佳气多，开元时节好笙歌。
也知道德胜尧舜，争奈杨妃解笑何。','',''),('quantangshi-36955','韩信庙','羅隱','quantangshi','','卷37','翦项移秦势自雄，布衣还是负深功。
寡妻稚女俱堪恨，却把余杯奠蒯通。','',''),('quantangshi-36956','韦公子','羅隱','quantangshi','','卷37','击柱狂歌惨别颜，百年人事梦魂闲。
李将军自嘉声在，不得封侯亦自闲。','',''),('quantangshi-36957','望思台','羅隱','quantangshi','','卷37','芳草台边魂不归，野烟乔木弄残晖。
可怜高祖清平业，留与闲人作是非。','',''),('quantangshi-36958','帝幸蜀','羅隱','quantangshi','','卷37','马嵬山色翠依依，又见銮舆幸蜀归。
泉下阿蛮应有语，这回休更怨杨妃。','',''),('quantangshi-36959','王夷甫','羅隱','quantangshi','','卷37','把得闲书坐水滨，读来前事亦酸辛。
莫言麈尾清谭柄，坏却淳风是此人。','',''),('quantangshi-36960','鹭鸶','羅隱','quantangshi','','卷37','斜阳澹澹柳阴阴，风褭寒丝映水深。
不要向人夸素白，也知常有羡鱼心。','',''),('quantangshi-36961','书淮阴侯传','羅隱','quantangshi','','卷37','寒灯挑尽见遗尘，试沥椒浆合有神。
莫恨高皇不终始，灭秦谋项是何人。','',''),('quantangshi-36962','青山庙','羅隱','quantangshi','','卷37','市箫声咽迹崎岖，雪耻酬恩此丈夫。
霸主两亡时亦异，不知魂魄更无归。','',''),('quantangshi-36963','小松','羅隱','quantangshi','','卷37','已有清阴逼座隅，爱声仙客肯过无。
陵迁谷变须高节，莫向人间作大夫。','',''),('quantangshi-36964','竹','羅隱','quantangshi','','卷37','篱外清阴接药阑，晓风交戛碧琅玕。
子猷死后知音少，粉节霜筠谩岁寒。','',''),('quantangshi-36965','谩天岭','羅隱','quantangshi','','卷37','西去休言蜀道难，此中危峻已多端。
到头未会苍苍色，争得禁他两度谩。','',''),('quantangshi-36966','秋虫赋','羅隱','quantangshi','','卷37','物之小兮，迎网而毙。
物之大兮，兼网而逝。
网也者，绳其小而不绳其大。
吾不知尔身之危兮，腹之馁兮。
吁！。','',''),('quantangshi-36967','蟋蟀诗','羅隱','quantangshi','','卷37','顽飔毙芳，吹愁夕长。
屑戍有动，歌离吊梦。
如诉如言，绪引虚宽。
周隙伺榻，繁咽夤缘。
范睡蝉老，冠峨緌好。
不冠不緌，尔奚以悲。
蚊蚋有毒，食人肌肉。
苍蝇多端，黑白偷安。
尔也出处，物兮莫累。
坏舍啼衰，虚堂泣曙。
勿徇喧哗，鼠岂无牙。
勿学萋菲，垣亦有耳。
危条槁飞，抽恨咿咿。
别帐缸冷，柔魂不定。
美人在何，夜影流波。
与子伫立，裴回思多。','',''),('quantangshi-36968','西川与蔡十九同别子超','羅隱','quantangshi','','卷37','相欢虽则不多时，相别那能不歛眉。
蜀客赋高君解爱，楚宫腰细我还知。
百年恩爱无终始，万里因缘有梦思。
肠断门前旧行处，不堪全属五陵儿。','',''),('quantangshi-36969','龙泉东下却寄孙员外','羅隱','quantangshi','','卷37','縠江东下几多程，每泊孤舟即有情。
山色已随游子远，水纹犹认主人清。
恩如海岳何时报，恨似烟花触处生。
百尺风帆两行泪，不堪回首望峥嵘。','',''),('quantangshi-36970','牡丹','羅隱','quantangshi','','卷37','艳多烟重欲开难，红蘂当心一抹檀。
公子醉归灯下见，美人朝插镜中看。
当庭始觉春风贵，带雨方知国色寒。
日晚更将何所似，太真无力凭阑干。','',''),('quantangshi-36971','巫山高','羅隱','quantangshi','','卷37','下压重泉上千仞，香云结梦西风紧。
纵有精灵得往来，狖轭鼯轩亦颠陨。
岚光双双雷隐隐，愁为衣裳恨为鬓。
暮洒朝行何所之，江边日月情无尽。
珠零冷露丹堕枫，细腰长脸愁满宫。
人生对面犹异同，况在千岩万壑中。','',''),('quantangshi-36972','江南行','羅隱','quantangshi','','卷37','江烟湿雨蛟绡软，漠漠小山眉黛浅。
水国多愁又有情，夜槽压酒银船满。
细丝摇柳凝晓空，吴王台榭春梦中。
鸳鸯鸂鶒唤不起，平铺绿水眠东风。
西陵路边月悄悄，油碧轻车苏小小。','',''),('quantangshi-36973','空城雀','羅隱','quantangshi','','卷37','雀入官仓中，所食能损几。
所恨往复频，官仓乃害尔。
鱼网不在天，鸟网不张水。
饮啄要自然，何必空城里。','',''),('quantangshi-36974','芳树','羅隱','quantangshi','','卷37','细蕚慢逐风，暖香闲破鼻。
青帝固有心，时时漏天意。
去年高枝犹堕地，今年低枝已顦顇。
吾所以见造化之权，变通之理。
春夏作头，秋冬为尾。
循环反覆无终已，人生长短同一轨。
若使威可以制，力可以止。
则秦皇不肯敛手下沙丘，孟贲不合低头入蒿里。
伊人强猛犹如此，顾我劳生何足恃。
但顾我开素袍，倾绿蚁。
陶陶兀兀大醉于清宵白昼间，任他上是天，下是地。','',''),('quantangshi-36975','听琴','羅隱','quantangshi','','卷37','寒雨萧萧落井梧，夜深何处怨啼乌？不知一盏临邛酒，救得相如渴病无。','',''),('quantangshi-36976','大梁见乔诩','羅隱','quantangshi','','卷37','湘水春浮岸，淮灯夜满桥。
六年悲梗断，两地各萍漂。
刀笔依三事，篇章奏珥貂。
迹卑甘汩没，名散称逍遥。
好寺松为径，空江桂作桡。
野香花伴落，缸暖酒和烧。
晋沼寻游凤，秦冠竟叹鸮。
骨凡鸡犬薄，魂断蕙兰招。
怅望添燕琯，蹉跎厌鲁瓢。
败桐方委爨，冤匣正冲霄。
战代安厘国，封崇孝景朝。
千年非有限，一醉解无聊。
漏永灯花暗，炉红雪片销。
久游家共远，相对鬓俱凋。
运命从难合，光阴奈不饶。
到头蓑笠契，两信钓鱼潮。','',''),('quantangshi-36977','寄洪正师','羅隱','quantangshi','','卷37','寄蹇浑成迹，经年滞杜南。
价轻犹有二，足刖已过三。
鸡肋曹公忿，猪肝仲叔慙。
会应谋避地，依约近禅庵。','',''),('quantangshi-36978','圣真观刘真师院十韵','羅隱','quantangshi','','卷37','帘下严君卜，窗间少室峰。
摄生门已尽，混迹世犹逢。
山薮师王烈，簪缨友戴颙。
鱼跳介象鲙，饭吐葛玄蜂。
紫饱垂新椹，黄轻堕小松。
尘埃金谷路，楼阁上阳钟。
野耗鸢肩寄，仙书鸟爪封。
支牀龟纵老，取箭鹤何慵。
别久曾牵念，闲来肯压重。
尚余青竹在，试为剪成龙。','',''),('quantangshi-36979','寄聂尊师','羅隱','quantangshi','','卷37','欲芟荆棘种交棃，指画城中日恐迟。
安得紫青磨镜石，与君闲处看荣衰。','',''),('quantangshi-36980','金山僧院','羅隱','quantangshi','','卷37','根盘蛟蜃路藤萝，四面无尘辍棹过。
得似吾师始惆怅，眼前终日有风波。','',''),('quantangshi-36981','酬高崇节','羅隱','quantangshi','','卷37','旧游虽一梦，别绪忽千般。
败草汤陵晚，衰槐楚寺寒。
数奇常自愧，时薄欲何干。
犹赖君相勉，殷勤贡禹冠。','',''),('quantangshi-36982','送汝州李中丞十二韵','羅隱','quantangshi','','卷37','羣盗方为梗，分符奏未宁。
黄巾攻郡邑，白梃掠生灵。
尘土周畿暗，疮痍汝水腥。
一凶虽剪灭，数县尚凋零。
理必资宽猛，谋须藉典刑。
与能才物论，慎选忽天庭。
官品尊台秩，山河拥福星。
虎知应去境，牛在肯全形。
旧政穷人瘼，新衔展武经。
关防秋草白，城壁晚峰青。
破胆期来复，迷魂想待醒。
鲁山行县后，聊为奠惟馨。','',''),('quantangshi-36983','淮南送节度卢端公将命之汴州端公常为汴州相公从事','羅隱','quantangshi','','卷37','吹台高倚圃田东，此去轺车事不同。
珠履旧参萧相国，彩衣今佐晋司空。
醉离淮甸寒星下，吟指梁园密雪中。
到彼的知宣室语，几时征拜黑头公。','',''),('quantangshi-36984','送卢端公归台卢校书之夏县','羅隱','quantangshi','','卷37','绵绵堤草拂征轮，龙虎俱辞楚水滨。
只是胜之为御史，不知梅福是仙人。
地推八米源流盛，才笑三张事业贫。
一种西归一般达，柏台霜冷夏城春。','',''),('quantangshi-36985','送朗州张员外','羅隱','quantangshi','','卷37','圣朝纶阁最延才，须牧生民始入来。
凤藻已期他日用，隼旟应是隔年回。
旗飘岘首岚光重，酒奠湘江杜魄哀。
肠断秦原二三月，好花全为使君开。','',''),('quantangshi-36986','淮南送工部卢员外赴阙','羅隱','quantangshi','','卷37','始从豸角曳长裾，又吐鸡香奏玉除。
隋邸旧僚推谢掾，汉廷高议得相如。
贵分赤笔升兰署，荣着绯衣从板舆。
遥想到时秋欲尽，禁城凉冷露槐疎。','',''),('quantangshi-36987','淮南送司勋李郎中赴阙','羅隱','quantangshi','','卷37','中朝品秩重文章，双笔依前赐望郎。
五夜星辰归帝座，半年樽俎奉梁王。
南都水暖莲分影，北极天寒雁着行。
不必恋恩多感激，过淮应合见征黄。','',''),('quantangshi-36988','送陆郎中赴阙','羅隱','quantangshi','','卷37','幕下留连两月强，炉边侍史旧焚香。
不关雨露偏垂意，自是鸳鸾合着行。
三署履声通建礼，九霄星彩映明光。
少瑜镂管丘迟锦，从此西垣使凤凰。','',''),('quantangshi-36989','途中送人东游有寄','羅隱','quantangshi','','卷37','离骖莫惜暂逡巡，君向池阳我入秦。
岁月易抛非曩日，酒杯难得是同人。
路经隋苑桥灯夜，江转台城岸草春。
此处故交谁见问，为言霜鬓压风尘。','',''),('quantangshi-36990','过废江宁县','羅隱','quantangshi','','卷37','县前水色细鳞鳞，一为夫君吊水滨。
漫把文章矜后代，可知荣贵是他人。
莺偷旧韵还成曲，草赖余吟尽解春。
我亦有心无处说，等闲停棹似迷津。','',''),('quantangshi-36991','边夜','羅隱','quantangshi','','卷37','光景漂如水，生涯转似萍。
雁门穷朔路，牛斗故乡星。
句尽人谁切，歌终泪自零。','',''),('quantangshi-36992','哭张博士太常','羅隱','quantangshi','','卷37','前辈倏云殁，愧君曾比方。
格卑虽不称，言重亦难忘。
谏草犹青琐，悲风已白杨。
只应移理窟，泉下对真长。','',''),('quantangshi-36993','淮口军葬','羅隱','quantangshi','','卷37','一阵孤军不复回，更无分别只荒堆。
莫言赋分须如此，曾作文皇赤子来。','',''),('quantangshi-36994','燕昭王墓','羅隱','quantangshi','','卷37','战国苍茫难重寻，此中踪迹想知音。
强停别骑山花晓，欲吊遗魂野草深。
浮世近来轻骏骨，高台何处有黄金？
思量郭隗平生事，不殉昭王是负心。','',''),('quantangshi-36995','江南','羅隱','quantangshi','','卷37','玉树歌声泽国春，累累辎重忆亡陈。
垂衣端拱浑闲事，忍把江山乞与人。','',''),('quantangshi-36996','江北','羅隱','quantangshi','','卷37','废宫荒苑莫闲愁，成败终须要彻头。
一种风流一种死，朝歌争得似扬州。','',''),('quantangshi-36997','早登新安县楼','羅隱','quantangshi','','卷37','关城树色齐，往事未全迷。
塞路真人气，封门壮土泥。
草浓延蝶舞，花密教莺啼。
若以鸣为德，鸾皇不及鸡。','',''),('quantangshi-36998','干越亭','羅隱','quantangshi','','卷37','楚水萧萧多病身，强凭危槛送残春。
高城自有陵兼谷，流水那知越与秦。
岸下藤萝阴作怪，桥边蛟蜃夜欺人。
琵琶洲远江村阔，回首征途泪满巾。','',''),('quantangshi-36999','南园题','羅隱','quantangshi','','卷37','搏击路终迷，南园且灌畦。
敢言逃俗态，自是乐幽栖。
叶长春松阔，科圆早薤齐。
雨霑虚槛冷，雪压远山低。
竹好还成径，桃夭亦有蹊。
小窗奔野马，闲瓮养醯鸡。
水石心逾切，烟霄分已暌。
病怜王猛畚，愚笑隗嚣泥。
泽国潮平岸，江村柳覆堤。
到头乘兴是，谁手好提携。','',''),('quantangshi-37000','人日新安道中见梅花','羅隱','quantangshi','','卷37','长途酒醒腊春寒，嫩蘂香英扑马鞍。
不上寿阳公主面，怜君开得却无端。','',''),('quantangshi-37001','许由庙','羅隱','quantangshi','','卷37','高挂风瓢濯汉滨，土阶三尺愧清尘。
可怜比屋堪封日，若到人间是众人。','',''),('quantangshi-37002','题段太尉庙','羅隱','quantangshi','','卷37','近甸蒙尘日，南梁反正年。
飘流茂陵椀，零落太官椽。
建纛非降楚，披图异录燕。
堪嗟侍中血，不及御衣前。','',''),('quantangshi-37003','湘妃庙','羅隱','quantangshi','','卷37','刘表荒碑断水滨，庙前幽草闭残春。
已将怨泪流斑竹，又感悲风入白苹。
八族未来谁北拱，四凶犹在莫南巡。
九峰相似堪疑处，望见苍梧不见人。','',''),('quantangshi-37004','八骏图','羅隱','quantangshi','','卷37','穆满当年物外程，电腰风脚一何轻。
如今纵有骅骝在，不得长鞭不肯行。','',''),('quantangshi-37005','庭花','羅隱','quantangshi','','卷37','昨日芳艳浓，开尊几同醉。
今朝风雨恶，惆怅人生事。
南威病不起，西子老兼至。
向晚寂无人，相偎堕红泪。','',''),('quantangshi-37006','病中题主人庭鹤','羅隱','quantangshi','','卷37','辽水华亭旧所闻，病中毛羽最怜君。
稻粱且足身兼健，何必青云与白云。','',''),('quantangshi-37007','蝉','羅隱','quantangshi','','卷37','天地工夫一不遗，与君声调借君緌。
风栖露饱今如此，应忘当年滓浊时。','',''),('quantangshi-37008','薛阳陶觱篥歌','羅隱','quantangshi','','卷37','平泉上相东征日，曾为阳陶歌觱篥。
乌江太守会稽侯，相次三篇皆俊逸。
桥山殡葬衣冠后，金印苍黄南去疾。
龙楼冷落夏口寒，从此风流为废物。
人间至艺难得主，怀抱差池恨星律。
邗沟仆射戎政闲，试渡瓜洲吐伊郁。
西风九月草树秋，万喧沈寂登高楼。
左篁揭指征羽吼，炀帝起坐淮王愁。
高飘咽灭出滞气，下感知己时横流。
穿空激远不可遏，仿髴似向伊水头。
伊水林泉今已矣，因取遗编认前事。
武宗皇帝御宇时，四海恬然知所自。
扫除桀黠似提箒，制压羣豪若穿鼻。
九鼎调和各有门，谢安空俭真儿戏。
功高近代竟谁知，艺小似君犹不弃。
勿惜喑呜更一吹，与君共下难逢泪。','',''),('quantangshi-37009','酬丘光庭','羅隱','quantangshi','','卷37','正月十一日书札，五月十六日到来。
柳吟秦望咫尺地，鲤鱼何处闲裴回？
故人情意未疎索，次第序述眉眼开。
上言二年隔烟水，下有数幅真琼瑰。
行吟坐读口不倦，瀑泉激射琅玕摧。
壁池兰蕙日已老，村酒蘸甲时几杯。
鹤龄鸿算不复见，雨后蓑笠空莓苔。
自从黄寇扰中土，人心波荡犹未回。
道殷合眼拜九列，张浚掉舌升三台。
朝廷济济百揆序，宁将对面容奸回。
祸生有基妖有渐，翠华西幸蒙尘埃。
三川梗塞两河闭，大明宫殿生蒿莱。
懦夫早岁不量力，策蹇仰北高崔嵬。
千门万户扃锁密，良匠不肯雕散材。
君今得意尚如此，况我麋鹿悠悠哉。
荣衰贵贱目所睹，莫嫌头白黄金台。','',''),('quantangshi-37010','投宣武郑尚书二十韵','羅隱','quantangshi','','卷37','汉代簪缨盛，梁园雉堞雄。
物情须重德，时论在明公。
族大逾开魏，高神本降嵩。
世家惟蹇谔，官业即清通。
翰苑论思外，纶闱啸傲中。
健豪惊彩凤，高步出冥鸿。
履历虽吾道，行藏必圣聪。
绛霄无系滞，浙水忽西东。
庾监高楼月，袁郎满扇风。
四年将故事，两地有全功。
去去才须展，行行道益隆。
避权辞宪署，仗节出南宫。
雁影相承接，龙图共始终。
自然须作砺，不必恨临戎。
幕下莲花盛，竿头㺗佩红。
骑儿逢郭伋，战士得文翁。
人地应无比，箪瓢奈屡空。
因思一枝桂，已作断根蓬。
往事应归捷，劳歌且责躬。
殷勤信陵馆，今日自途穷。','',''),('quantangshi-37011','投浙东王大夫二十韵','羅隱','quantangshi','','卷37','越岭千峰秀，淮流一派长。
暂凭开物手，来展济时方。
旧迹兰亭在，高风桂树香。
地清无等级，天阔任徊翔。
麈尾谈何胜，螭头笔更狂。
直曾批凤诏，高已冠鵷行。
啸傲辞民部，雍容出帝乡。
赵尧推印绶，句践与封疆。
水占仙人吹，城留御史牀。
嘉宾邹润甫，百姓贺知章。
席暖飞鹦鹉，尘轻驻驌驦。
夜歌珠断续，晴舞雪悠扬。
化向棠阴布，春随棣萼芳。
盛名韬不得，雄略晦弥彰。
自愧三冬学，来窥数仞墙。
感深惟刻骨，时去欲霑裳。
想望鱼烧尾，咨嗟鼠啮肠。
可能因蹇拙，便合老沧浪。
题柱心犹壮，移山志不忘。
深惭百般病，今日问医王。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37012','寄剡县主簿','羅隱','quantangshi','','卷37','金庭养真地，珠篆会稽官。
境胜堪长往，时危喜暂安。
洞连沧海阔，山拥赤城寒。
他日抛尘土，因君拟炼丹。','',''),('quantangshi-37013','中秋不见月','羅隱','quantangshi','','卷37','风帘淅淅漏灯痕，一半秋光此夕分。
天为素娥孀怨苦，并教西北起浮云。','',''),('quantangshi-37014','答宗人衮','羅隱','quantangshi','','卷37','昆仑水色九般流，饮即神仙憩即休。
敢恨守株曾失意，始知缘木更难求。
鸰原谩欲均余力，鹤髪那堪问旧游。
遥望北辰当上国，羡君归掉五诸侯。','',''),('quantangshi-37015','早行','羅隱','quantangshi','','卷37','雨洒江声风又吹，扁舟正与睡相宜。
无端戍鼓催前去，别却青山向晓时。','',''),('quantangshi-37016','咏白菊','羅隱','quantangshi','','卷37','虽被风霜竞欲催，皎然颜色不低摧。
已疑素手能妆出，又似金钱未染来。
香散自宜飘渌酒，叶交仍得荫香苔。
寻思闭户中宵见，应认寒窗雪一堆。','',''),('quantangshi-37017','晚泊宿松','羅隱','quantangshi','','卷37','解缆随江流，晚泊古淮岸。
归云送春和，繁星丽云汉。
春深胡雁飞，人喧水禽散。
仰君邈难亲，沈思夜将旦。','',''),('quantangshi-37018','钱塘遇默师忆润州旧游','羅隱','quantangshi','','卷38','歌敲玉唾壶，醉击珊瑚枝。
石羊妙善街，甘露平泉碑。
扪苔想豪杰，剔藓看文词。
归来北固山，水槛光参差。','',''),('quantangshi-37019','江南别','羅隱','quantangshi','','卷38','去年今夜江南别，鸳鸯翅冷飞蓬爇。
今年今夜江北边，鲤鱼肠断音书绝。
男儿心事无了时，出门上马不自知。','',''),('quantangshi-37020','四顶山','羅隱','quantangshi','','卷38','胜景天然别，精神入画图。
一山分四顶，三面瞰平湖。
过夏僧无热，凌冬草不枯。
游人来至此，愿剃髪和须。','',''),('quantangshi-37021','姥山','羅隱','quantangshi','','卷38','临塘古庙一神仙，绣幌花容色俨然。
为逐朝云来此地，因随暮雨不归天。
眉分初月湖中鉴，香散余风竹上烟。
借问邑人沈水事，已经秦汉几千年。','',''),('quantangshi-37022','岐王宅','羅隱','quantangshi','','卷38','朱邸平台隔禁闱，贵游陈迹尚依稀。
云低雍畤祈年去，雨细长杨从猎归。
申白宾朋传道义，应刘文彩寄音徽。
承平旧物惟君尽，犹写雕鞍伴六飞。','',''),('quantangshi-37023','长明灯','羅隱','quantangshi','','卷38','破暗长明世代深，烟和香气两沈沈。
不知初点何人在，秪见当年火至今。
晓似红莲开沼面，夜如寒月镇潭心。
孤光自有龙神护，雀戏蛾飞不敢侵。','',''),('quantangshi-37024','堋口逢人','羅隱','quantangshi','','卷38','艰难别离久，中外往还深。
已改当时髪，空余旧日心。','',''),('quantangshi-37025','遇边使','羅隱','quantangshi','','卷38','累年无的信，每夜望边城。
袖掩千行泪，书封一尺金。','',''),('quantangshi-37026','移住别友','羅隱','quantangshi','','卷38','自到西川住，惟君别有情。
常逢对门远，又隔一重城。','',''),('quantangshi-37027','宫词','羅隱','quantangshi','','卷38','巧画蛾眉独出羣，当时人道便承恩。
经年不见君王面，落日黄昏空掩门。','',''),('quantangshi-37028','泾溪','羅隱','quantangshi','','卷38','泾溪石险人竞惧，终岁不闻倾覆人。
却是平流无石处，时时闻说有沈沦。','',''),('quantangshi-37029','题杜甫集','羅隱','quantangshi','','卷38','楚水悠悠浸楚亭，楚南天地两无情。
忍交孙武重泉下，不见时人说用兵。','',''),('quantangshi-37030','感弄猴人赐朱绂','羅隱','quantangshi','','卷38','十二三年就试期，五湖烟月奈相违。
何如买取胡孙弄，一笑君王便着绯。','',''),('quantangshi-37031','题磻溪垂钓图','羅隱','quantangshi','','卷38','吕望当年展庙谟，直钩钓国更谁如。
若教生在西湖上，也是须供使宅鱼。','',''),('quantangshi-37032','春风','羅隱','quantangshi','','卷38','也知有意吹嘘切，争奈人间善恶分。
但是粃糠细微物，等闲抬举到青云。','',''),('quantangshi-37033','竹下残雪','羅隱','quantangshi','','卷38','墙下浓阴对此君，小山尖险玉为羣。
夜来解冻风虽急，不向寒城减一分。','',''),('quantangshi-37034','杏花','羅隱','quantangshi','','卷38','暖气潜催次第春，梅花已谢杏花新。
半开半落闲园里，何异荣枯世上人。','',''),('quantangshi-37035','镇海军所贡','羅隱','quantangshi','','卷38','檐前飞雪扇前尘，千里移添上苑春。
他日丁宁柿林院，莫宣恩泽与闲人。','',''),('quantangshi-37036','席上歌水调','羅隱','quantangshi','','卷38','余声宛宛拂庭梅，通济渠边去又回。
若使炀皇魂魄在，为君应合过江来。','',''),('quantangshi-37037','题新榜','羅隱','quantangshi','','卷38','黄土原边狡兔肥，犬如流电马如飞。
灞陵老将无功业，犹忆当时夜猎归。','',''),('quantangshi-37038','句','羅隱','quantangshi','','卷38','夏窗七叶连阴暗。
赖家桥上潏河边。
