山雨霏微宿上亭，雨中因想雨淋铃。
老僧斋罢关门睡，不管波涛四面生。','',''),('quantangshi-37039','比红儿诗 一','羅虬','quantangshi','','卷38','姓字看侵尺五天，芳菲占断百花鲜。
马嵬好笑当时事，虚赚明皇幸蜀川。','',''),('quantangshi-37040','比红儿诗 二','羅虬','quantangshi','','卷38','金谷园中花正繁，坠楼从道感深恩。
齐奴却是来东市，不为红儿死更冤。','',''),('quantangshi-37041','比红儿诗 三','羅虬','quantangshi','','卷38','陷却平阳为小怜，周师百万战长川。
更教乞与红儿貌，举国山川不值钱。','',''),('quantangshi-37042','比红儿诗 四','羅虬','quantangshi','','卷38','一曲都缘张丽华，六宫齐唱后庭花。
