今日红儿貌倾国，恐须真宰别开花。','',''),('quantangshi-37101','比红儿诗 六十三','羅虬','quantangshi','','卷38','陌上行人歌黍离，三千门客欲何之。
若教麤及红儿貌，争取楼前斩爱姬。','',''),('quantangshi-37102','比红儿诗 六十四','羅虬','quantangshi','','卷38','休话如臯一笑时，金𩩉中臆锦离披。
陋容枉把雕弓射，射尽春禽未展眉。','',''),('quantangshi-37103','比红儿诗 六十五','羅虬','quantangshi','','卷38','长恨西风送早秋，低眉深恨嫁牵牛。
若同人世长相对，争作夫妻得到头。','',''),('quantangshi-37104','比红儿诗 六十六','羅虬','quantangshi','','卷38','谢娘休漫逞风姿，未必娉婷胜柳枝。
闻道只因嘲落絮，何曾得似杜红儿。','',''),('quantangshi-37105','比红儿诗 六十七','羅虬','quantangshi','','卷38','总传桃叶渡江时，只为王家一首诗。
今日红儿自堪赋，不须重唱旧来词。','',''),('quantangshi-37106','比红儿诗 六十八','羅虬','quantangshi','','卷38','巫山洛浦本无情，总为佳人便得名。
今日雕阴有神艳，后来公子莫相轻。','',''),('quantangshi-37107','比红儿诗 六十九','羅虬','quantangshi','','卷38','几抛云髻恨金墉，泪洗花颜百战中。
应有红儿些子貌，却言皇后长深宫。','',''),('quantangshi-37108','比红儿诗 七十','羅虬','quantangshi','','卷38','倚槛还应有所思，半开东阁见娇姿。
可中得似红儿貌，若遇韩朋好杀伊。','',''),('quantangshi-37109','比红儿诗 七十一','羅虬','quantangshi','','卷38','晓向妆台与画眉，镜中长欲助娇姿。
若教得似红儿貌，走马章台任道迟。','',''),('quantangshi-37110','比红儿诗 七十二','羅虬','quantangshi','','卷38','练得霜华助翠钿，相期朝谒玉皇前。
依稀有似红儿貌，方得吹箫引上天。','',''),('quantangshi-37111','比红儿诗 七十三','羅虬','quantangshi','','卷38','重门深掩几枝花，未胜红儿莫大夸。
王相不能探物理，可能虚上短辕车。','',''),('quantangshi-37112','比红儿诗 七十四','羅虬','quantangshi','','卷38','前代休怜事可奇，后来还出有光辉。
争知昼卧纱窗里，不见神人覆玉衣。','',''),('quantangshi-37113','比红儿诗 七十五','羅虬','quantangshi','','卷38','化羽尝闻赴九天，只疑尘世是虚传。
自从一见红儿貌，始信人间有谪仙。','',''),('quantangshi-37114','比红儿诗 七十六','羅虬','quantangshi','','卷38','从道长陵小市东，巧将花貌占春风。
红儿若是同时见，未必伊先入紫宫。','',''),('quantangshi-37115','比红儿诗 七十七','羅虬','quantangshi','','卷38','人间难免是深情，命断红儿向此生。
不似前时李丞相，枉抛才力为莺莺。','',''),('quantangshi-37116','比红儿诗 七十八','羅虬','quantangshi','','卷38','凤舞香飘绣幕风，暖穿驰道百花中。
还缘有似红儿貌，始道迎将入汉宫。','',''),('quantangshi-37117','比红儿诗 七十九','羅虬','quantangshi','','卷38','休道将军出世才，尽驱诸妓下歌台。
都缘没个红儿貌，致使轻教后阁开。','',''),('quantangshi-37118','比红儿诗 八十','羅虬','quantangshi','','卷38','冯媛须知住汉宫，将身只是解当熊。
不闻有貌倾人国，争得今朝更似红。','',''),('quantangshi-37119','比红儿诗 八十一','羅虬','quantangshi','','卷38','能将一笑使人迷，花艳何须上大堤。
疎属便同巫峡路，洛川真是武陵溪。','',''),('quantangshi-37120','比红儿诗 八十二','羅虬','quantangshi','','卷38','辞辇当时意可知，宠深还恐宠先衰。
若教得似红儿貌，占却君恩自不疑。','',''),('quantangshi-37121','比红儿诗 八十三','羅虬','quantangshi','','卷38','三吴时俗重风光，未见红儿一面妆。
好写妖娆与教看，便应休更话真娘。','',''),('quantangshi-37122','比红儿诗 八十四','羅虬','quantangshi','','卷38','波平楚泽浸星辰，台上君王宴早春。
毕竟章华会中客，冠缨虚绝为何人。','',''),('quantangshi-37123','比红儿诗 八十五','羅虬','quantangshi','','卷38','红儿不向汉宫生，便使双成谩得名。
疑是麻姑恼尘世，暂教微步下层城。','',''),('quantangshi-37124','比红儿诗 八十六','羅虬','quantangshi','','卷38','天碧轻纱只六铢，宛如含露透肌肤。
便教汉曲争明媚，应没心情更弄珠。','',''),('quantangshi-37125','比红儿诗 八十七','羅虬','quantangshi','','卷38','共嗟含恨向衡阳，方寸花牋寄沈郎。
不似红儿些子貌，当时争得少年狂。','',''),('quantangshi-37126','比红儿诗 八十八','羅虬','quantangshi','','卷38','浅色桃花亚短墙，不因风送也闻香。
凝情尽日君知否，还似红儿淡薄妆。','',''),('quantangshi-37127','比红儿诗 八十九','羅虬','quantangshi','','卷38','火色樱桃摘得初，仙宫只有世间无。
凝情尽日君知否，真似红儿口上朱。','',''),('quantangshi-37128','比红儿诗 九十','羅虬','quantangshi','','卷38','宿雨初晴春日长，入帘花气静难忘。
凝情尽日君知否，真似红儿舞袖香。','',''),('quantangshi-37129','比红儿诗 九十一','羅虬','quantangshi','','卷38','初月纤纤映碧池，池波不动独看时。
凝情尽日君知否，真似红儿罢舞眉。','',''),('quantangshi-37130','比红儿诗 九十二','羅虬','quantangshi','','卷38','浓艳浓香雪压枝，褭烟和露晓风吹。
红儿被掩妆成后，含笑无人独立时。','',''),('quantangshi-37131','比红儿诗 九十三','羅虬','quantangshi','','卷38','楼上娇歌褭夜霜，近来休数踏歌娘。
红儿谩唱伊州遍，认取轻敲玉韵长。','',''),('quantangshi-37132','比红儿诗 九十四','羅虬','quantangshi','','卷38','金粟妆成扼臂环，舞腰轻薄瑞云间。
红儿生在开元末，羞杀新丰谢阿蛮。','',''),('quantangshi-37133','比红儿诗 九十五','羅虬','quantangshi','','卷38','君看红儿学醉妆，夸裁宫襭砑裙长。
谁能更把闲心力，比竝当时武媚娘。','',''),('quantangshi-37134','比红儿诗 九十六','羅虬','quantangshi','','卷38','栀子同心裛露垂，折来深恐没人知。
花前醉客频相问，不赠红儿赠阿谁。','',''),('quantangshi-37135','比红儿诗 九十七','羅虬','quantangshi','','卷38','云间翡翠一双飞，水上鸳鸯不暂离。
写向人间百般态，与君题作比红诗。','',''),('quantangshi-37136','比红儿诗 九十八','羅虬','quantangshi','','卷38','旧恨长怀不语中，几回偷泣向春风。
还缘不及红儿貌，却得生教入楚宫。','',''),('quantangshi-37137','比红儿诗 九十九','羅虬','quantangshi','','卷38','一舸春深指鄂君，好风从度水成纹。
越人若见红儿貌，绣被应羞彻夜薰。','',''),('quantangshi-37138','比红儿诗 一百','羅虬','quantangshi','','卷38','花落尘中玉堕泥，香魂应上窈娘堤。
欲知此恨无穷处，长倩城乌夜夜啼。','',''),('quantangshi-37139','句','羅虬','quantangshi','','卷38','窗前远岫悬生碧，帘外残霞挂熟红。','',''),('quantangshi-37140','星精亭','鄭損','quantangshi','','卷38','星沈万古痕，孤绝势无邻。
地窄少留竹，空多剩占云。
钓篷和雨看，樵斧带霜闻。
莫惜寻常到，清风不负人。','',''),('quantangshi-37141','钓阁','鄭損','quantangshi','','卷38','小阁惬幽寻，周遭万竹森。
谁知一沼内，亦有五湖心。
钓直鱼应笑，身闲乐自深。
晚来春醉熟，香饵任浮沈。','',''),('quantangshi-37142','玉声亭','鄭損','quantangshi','','卷38','世间泉石本无价，那更天然落景中。
汉佩琮琤寒溜雨，秦箫缥缈夜敲风。
一方清气羣阴伏，半局闲棋万虑空。
借问主人能住久，后来好事有谁同。','',''),('quantangshi-37143','艺堂','鄭損','quantangshi','','卷38','堂开冻石千年翠，艺讲秋胶百步威。
揖让未能忘典礼，英雄孰不惯戎衣。
风波险似金机骇，日月忙如雪羽飞。
莫怪尊前频浩叹，男儿志愿与时违。','',''),('quantangshi-37144','星精石','鄭損','quantangshi','','卷38','突险呀空龙虎蹲，由来英气蓄寒根。
苍苔点染云生靥，老雨淋漓铁渍痕。
松韵远趋疑认祖，山阴轻覆似怜孙。
孤岩恰恰容幽构，可爱江南释子园。','',''),('quantangshi-37145','泛香亭','鄭損','quantangshi','','卷38','流杯处处称佳致，何似斯亭出自然。
山溜穿云来几里，石盘和藓凿何年。
声交鸣玉歌沈板，色幌寒金酒满船。
莫怪坐中难得醉，醒人心骨有潺湲。','',''),('quantangshi-37146','巴州寒食晚眺','張禕','quantangshi','','卷38','东望青天周与秦，杏花榆叶故园春。
野寺一倾寒食酒，晚来风景重愁人。','',''),('quantangshi-37147','题击瓯楼','張禕','quantangshi','','卷38','驻旌元师遗风在，击缶高人逸兴酣。
水转巴文清溜急，山连蒙岫翠光涵。','',''),('quantangshi-37148','题司空图壁','盧攜','quantangshi','','卷38','姓氏司空贵，官班御史卑。
老夫如且在，不用叹屯奇。','',''),('quantangshi-37149','愁诗','李廷璧','quantangshi','','卷38','到来难遣去难留，着骨黏心万事休。
潘岳愁丝生鬓里，婕妤悲色上眉头。
长途诗尽空骑马，远雁声初独倚楼。
更有相思不相见，酒醒灯背月如钩。','',''),('quantangshi-37150','题菖蒲废观','許三畏','quantangshi','','卷38','本是安期烧药处，今来改作坐禅宫。
数僧梵响满楼月，深谷猨声半夜风。
金简事移松阁逈，彩云影散阆山空。
我来不见修真客，却得真如问远公。','',''),('quantangshi-37151','致孙状元诉醵罚钱','盧嗣業','quantangshi','','卷38','未识都君面，频输复分钱。
苦心事笔砚，得志助花钿。
徒步求秋赋，持杯给暮饘。
力微多谢病，非不奉同年。','',''),('quantangshi-37152','红蔷薇','牛嶠','quantangshi','','卷38','晓啼珠露浑无力，绣簇罗襦不着行。
若缀寿阳公主额，六宫争肯学梅妆。','',''),('quantangshi-37153','杨柳枝五首 一','牛嶠','quantangshi','','卷38','解冻风来末上青，解垂罗袖拜卿卿。
无端褭娜临官路，舞送行人过一生。','',''),('quantangshi-37154','杨柳枝五首 二','牛嶠','quantangshi','','卷38','吴王宫里色偏深，一簇纤条万缕金。
不愤钱塘苏小小，引郎松下结同心。','',''),('quantangshi-37155','杨柳枝五首 三','牛嶠','quantangshi','','卷38','桥北桥南千万条，恨伊张绪不相饶。
金羁白马临风望，认得羊家静婉腰。','',''),('quantangshi-37156','杨柳枝五首 四','牛嶠','quantangshi','','卷38','狂雪随风扑马飞，惹烟无力被春欺。
莫交移入灵和殿，宫女三千又妬伊。','',''),('quantangshi-37157','杨柳枝五首 五','牛嶠','quantangshi','','卷38','褭翠笼烟拂暖波，舞裙新染麴尘罗。
章华台畔隋堤上，傍得春风尔许多。','',''),('quantangshi-37158','及第后宿平康里诗','鄭合','quantangshi','','卷38','春来无处不闲行，楚润相看别有情。
好是五更残酒醒，时时闻唤状头声。','',''),('quantangshi-37159','贺裴廷裕蜀中登第诗','李搏','quantangshi','','卷38','铜梁千里曙云开，仙箓新从紫府来。
天上已张新羽翼，世间无复旧尘埃。
嘉祯果中君平卜，贺喜须斟卓氏杯。
应笑戎藩刀笔吏，至今泥滓曝鱼鳃。','',''),('quantangshi-37160','复谑廷裕','李搏','quantangshi','','卷38','曾随风水化凡鳞，安上门前一字新。
闻道蜀江风景好，不知何似杏园春。','',''),('quantangshi-37161','吊贾岛','李克恭','quantangshi','','卷38','一一玄微缥缈成，尽吟方便爽神情。
宣宗谪去为闲事，韩愈知来已振名。
海底也应搜得净，月轮常被翫教倾。
如何未隔四十载，不遇论量向此生。','',''),('quantangshi-37162','君山','程賀','quantangshi','','卷38','曾游方外见麻姑，说道君山此本无。
云是昆仑山顶石，海风吹落洞庭湖。','',''),('quantangshi-37163','东归诗','盧尚卿','quantangshi','','卷38','九重丹诏下尘埃，深锁文闱罢选才。
桂树放教遮月长，杏园终待隔年开。
自从玉帐论兵后，不许金门谏猎来。
今日灞陵桥上过，路人应笑腊前回。','',''),('quantangshi-37164','题玉芝双奉院','顧在鎔','quantangshi','','卷38','入门如洞府，花木与时稀。
夜坐山当户，秋吟叶满衣。
犬随童子出，鸟避俗人飞。
至药应将熟，年年火气微。','',''),('quantangshi-37165','宿麻平驿','顧在鎔','quantangshi','','卷38','及到怡情处，暂忘登陟劳。
青山看不厌，明月坐来高。
犬为孤村吠，猨因冷木号。
微吟还独酌，多兴忆同袍。','',''),('quantangshi-37166','题光福上方塔','顧在鎔','quantangshi','','卷38','苍岛孤生白浪中，倚天高塔势翻空。
烟凝远岫列寒翠，霜染疎林堕碎红。
汀沼或栖彭泽雁，楼台深贮洞庭风。
六时金磬落何处，偏傍芦苇惊钓翁。','',''),('quantangshi-37167','枯木诗辞召命作','翁洮','quantangshi','','卷38','枯木傍溪崖，由来岁月赊。
有根盘水石，无叶接烟霞。
二月苔为色，三冬雪作花。
不因星使至，谁识是灵槎。','',''),('quantangshi-37168','赠进士王雄','翁洮','quantangshi','','卷38','河清海晏少波涛，几载垂钩不得鳌。
空向人间修谏草，又来江上咏离骚。
笳吹古堞边声远，岳倚晴空楚色高。
何事明廷有徐庶，总教三径卧蓬蒿。','',''),('quantangshi-37169','渔者','翁洮','quantangshi','','卷38','一叶飘然任浪吹，雨蓑烟笠肯忘机。
只贪浊水张罗众，却笑清流把钓稀。
苇岸夜依明月宿，柴门晴棹白云归。
到头得丧终须达，谁道渔樵有是非。','',''),('quantangshi-37170','上子男寿昌宰','翁洮','quantangshi','','卷38','陶公为政卓潘齐，入县看花柳满堤。
百里江山聊展骥，九臯云月怪驱鸡。
高楼野色迎襟袖，比屋歌声远鼓鼙。
只恐攀辕留不住，明时霄汉有丹梯。','',''),('quantangshi-37171','赠方干先生','翁洮','quantangshi','','卷38','由来箕踞任天真，别有诗名出世尘。
不爱春宫分桂树，欲教天子枉蒲轮。
城头鼙鼓三声晓，岛外湖山一簇春。
独向若耶溪上住，谁知不是钓鳌人。','',''),('quantangshi-37172','赠进士李德新接海棠梨','翁洮','quantangshi','','卷38','蜀人犹说种难成，何事江东见接生。
席上若微桃李伴，花中堪作牡丹兄。
高轩日午争浓艳，小径风移旋落英。
一种呈妍今得地，劒峯梨岭谩纵横。','',''),('quantangshi-37173','春日题航头桥','翁洮','quantangshi','','卷38','故园桥上绝埃尘，此日凭栏兴自新。
云影晚将仙掌曙，水光迷得武陵春。
薜萝烟里高低路，杨柳风前去住人。
莫怪马卿题姓字，终朝云雨化龙津。','',''),('quantangshi-37174','和方干题李频庄','翁洮','quantangshi','','卷38','高情度日非无事，自是高情不觉喧。
海气暗蒸莲叶沼，山光晴逗苇花村。
吟时胜概题诗板，静处繁华付酒尊。
闲伴白云收桂子，每寻流水斸桐孙。
犹凭律吕传心曲，岂虑星霜到鬓根。
多少清风归此地，十年虚打五侯门。','',''),('quantangshi-37175','苇藂','翁洮','quantangshi','','卷38','得地自成藂，那因种植功。
有花皆吐雪，无韵不含风。
倒影翘沙鸟，幽根立水虫。
萧萧寒雨夜，江汉思无穷。','',''),('quantangshi-37176','春','翁洮','quantangshi','','卷38','漠漠烟花处处通，游人南北思无穷。
林间鸟奏笙簧月，野外花含锦绣风。
鸑抱云霞朝凤阙，鱼翻波浪化龙宫。
此时谁羡神仙客，车马悠扬九陌中。','',''),('quantangshi-37177','夏','翁洮','quantangshi','','卷38','触目皆因长养功，浮生何处问穷通？
柳长北阙丝千缕，云簇南山火万笼。
大野烟尘飘赫日，高楼帘幕逗薰风。
身心已在喧阗处，惟羡沧浪把钓翁。','',''),('quantangshi-37178','秋','翁洮','quantangshi','','卷38','宋玉高吟思万重，澄澄寰宇振金风。
云闲日月浮虚白，木落山川叠碎红。
寥泬雁多宫漏永，河渠烟歛塞天空。
侯门处处槐花□，献赋何时遇至公。','',''),('quantangshi-37179','冬','翁洮','quantangshi','','卷38','寂寂栖心向杳冥，苦吟寒律句偏清。
云凝止水鱼龙蛰，雪点遥峰草木荣。
迥夜炉飜埃烬色，天河冰辗辘轳声。
归飞未得东风力，魂断三山九万程。','',''),('quantangshi-37180','过洞庭','李嶼','quantangshi','','卷38','浩渺注横流，千潭合万湫。
半洪侵楚翼，一汊属吴头。
动轴当新霁，漫空正仲秋。
势翻荆口迮，声拥岳阳浮。
远脉滋衡岳，微凉散橘州。
星辰连影动，岚翠逐隅收。
渐落分行雁，旋添趁伴舟。
升腾人莫测，安稳路何忧。
气与尘中别，言堪象外搜。
此身如麤了，来把一竿休。','',''),('quantangshi-37181','严塘经乱书事 一','鄭啓','quantangshi','','卷38','尘生宫阙雾蒙蒙，万骑龙飞幸蜀中。
在野傅岩君不梦，乘轩卫懿鹤何功。
虽知四海同盟久，未合中原武备空。
星落夜原妖气满，汉家麟阁待英雄。','',''),('quantangshi-37182','严塘经乱书事 二','鄭啓','quantangshi','','卷38','梁园皓色月如圭，清景伤时一惨凄。
未见山前归牧马，犹闻江上带征鞞。
鲲为鱼队潜鳞困，鹤处鸡羣病翅低。
正是四郊多垒日，波涛早晚静鲸鲵。','',''),('quantangshi-37183','邓表山','鄭啓','quantangshi','','卷38','白日三清此上时，观开山下彩云飞。
仙坛丹竈灵犹在，鹤驾清朝去不归。
晋末几迁陵谷改，尘中空换子孙非。
松花落尽无消息，半夜疎钟彻翠微。','',''),('quantangshi-37184','记知闻近过关试','韓儀','quantangshi','','卷38','短行轴了付三铨，休把新衔恼必先。
今日便称前进士，好留春色与明年。','',''),('quantangshi-37185','郊居','溫憲','quantangshi','','卷38','村前村后树，寓赏有余情。
青麦路初断，紫花田未耕。
雉声闻不到，山势望犹横。
寂寞春风里，吟酣信马行。','',''),('quantangshi-37186','杏花','溫憲','quantangshi','','卷38','团雪上晴梢，红明映碧寥。
店香风起夜，村白雨休朝。
静落犹和蒂，繁开正蔽条。
澹然闲赏久，无以破妖娆。','',''),('quantangshi-37187','春鸠','溫憲','quantangshi','','卷38','村南微雨新，平绿净无尘。
散睡桑条暖，闲鸣屋脊春。
远闻和晓梦，相应在诸邻。
行乐花时节，追飞见亦频。','',''),('quantangshi-37188','题崇[庆]寺壁','溫憲','quantangshi','','卷38','十口沟隍待一身，半年千里绝音尘。
鬓毛如雪心如死，犹作长安下第人。','',''),('quantangshi-37189','报颜标','姚巖傑','quantangshi','','卷38','为报颜公识我麽，我心唯只与天和。
眼前俗物关情少，醉后青山入意多。
田子莫嫌弹铗恨，甯生休唱饭牛歌。
圣朝若为苍生计，也合公车到薜萝。','',''),('quantangshi-37190','途中除夜','高蟾','quantangshi','','卷38','南北浮萍迹，年华又暗催。
残灯和腊尽，晓角带春来。
鬓欲渐侵雪，心仍未肯灰。
金门旧知己，谁为脱尘埃。','',''),('quantangshi-37191','长门怨','高蟾','quantangshi','','卷38','天上何劳万古春，君前谁是百年人。
魂销尚愧金炉烬，思起犹惭玉辇尘。
烟翠薄情攀不得，星茫浮艳采无因。
可怜明镜来相向，何似恩光朝夕新。','',''),('quantangshi-37192','秋日寄华阳山人','高蟾','quantangshi','','卷38','云木送秋何草草，风波凝冷太星星。
银鞍公子魂俱断，玉弩将军涕自零。
茅洞白龙和雨看，荆溪黄鹄带霜听。
人间不见清凉事，犹向溪翁乞画屏。','',''),('quantangshi-37193','感事','高蟾','quantangshi','','卷38','浊河从北下，清洛向东流。
清浊皆如此，何人不白头。','',''),('quantangshi-37194','楚思','高蟾','quantangshi','','卷38','叠浪与云急，翠兰和意香。
风流化为雨，日暮下巫阳。','',''),('quantangshi-37195','雪中','高蟾','quantangshi','','卷38','金阁倚云开，朱轩犯雪来。
三冬辛苦样，天意似难栽。','',''),('quantangshi-37196','道中有感','高蟾','quantangshi','','卷38','一醉六十日，一裘三十年。
年华经几日，日日掉征鞭。','',''),('quantangshi-37197','宋汴道中','高蟾','quantangshi','','卷38','平野有千里，居人无一家。
甲兵年正少，日久戍天涯。','',''),('quantangshi-37198','秋思','高蟾','quantangshi','','卷38','天地太萧索，山川何渺茫。
不堪星斗柄，犹把岁寒量。','',''),('quantangshi-37199','即事','高蟾','quantangshi','','卷38','三年离水石，一旦隐樵渔。
为问青云上，何人识卷舒。','',''),('quantangshi-37200','渔家','高蟾','quantangshi','','卷38','野水千年在，闲花一夕空。
近来浮世狭，何似钓船中。','',''),('quantangshi-37201','关中','高蟾','quantangshi','','卷38','风雨去愁晚，关河归思凉。
西游无紫气，一夕九回肠。','',''),('quantangshi-37202','归思','高蟾','quantangshi','','卷38','紫府归期断，芳洲别思迢。
黄金作人世，只被岁寒消。','',''),('quantangshi-37203','下第出春明门','高蟾','quantangshi','','卷38','曾和秋雨驱愁入，却向春风领恨回。
深谢灞陵堤畔柳，与人头上拂尘埃。','',''),('quantangshi-37204','华清宫','高蟾','quantangshi','','卷38','何事金舆不再游，翠鬟丹脸岂胜愁。
重门深锁禁钟后，月满骊山宫树秋。','',''),('quantangshi-37205','秋日北固晚望二首 一','高蟾','quantangshi','','卷38','风含远思翛翛晚，日照高情的的秋。
何事满江惆怅水，年年无语向东流。','',''),('quantangshi-37206','秋日北固晚望二首 二','高蟾','quantangshi','','卷38','泽国路岐当面苦，江城砧杵入心寒。
不知白发谁医得，为问无情岁月看。','',''),('quantangshi-37207','送张道士','高蟾','quantangshi','','卷38','因将岁月离三岛，闲贮风烟在一壶。
为问金乌头白后，人间流水却回无。','',''),('quantangshi-37208','吴门春雨','高蟾','quantangshi','','卷38','吴甸落花春漫漫，吴宫芳树晚沈沈。
王孙不耐如丝雨，罥断春风一寸心。','',''),('quantangshi-37209','旅夕','高蟾','quantangshi','','卷38','风散古陂惊宿雁，月临荒戍起啼鸦。
不堪吟断无人见，时复寒灯落一花。','',''),('quantangshi-37210','瓜洲夜泊','高蟾','quantangshi','','卷38','偶为芳草无情客，况是青山有事身。
一夕瓜洲渡头宿，天风吹尽广陵尘。','',''),('quantangshi-37211','金陵晚望','高蟾','quantangshi','','卷38','曾伴浮云归晚翠，犹陪落日泛秋声。
世间无限丹青手，一片伤心画不成。','',''),('quantangshi-37212','晚思','高蟾','quantangshi','','卷38','虞泉冬恨由来短，杨叶春期分外长。
惆怅浮生不知处，明朝依旧出沧浪。','',''),('quantangshi-37213','长信宫二首 一','高蟾','quantangshi','','卷38','天上梦魂何杳杳，日宫消息太沈沈。
君恩不似黄金井，一处团圆万丈深。','',''),('quantangshi-37214','长信宫二首 二','高蟾','quantangshi','','卷38','天上凤皇休寄梦，人间鹦鹉旧堪悲。
平生心绪无人识，一只金梭万丈丝。','',''),('quantangshi-37215','长安旅怀','高蟾','quantangshi','','卷38','马嘶九陌年年苦，人语千门日日新。
唯有终南寂无事，寒光不入帝乡尘。','',''),('quantangshi-37216','春 一','高蟾','quantangshi','','卷38','天柱几条搘白日，天门几扇锁明时。
阳春发处无根蔕，凭仗东风分外吹。','',''),('quantangshi-37217','春 二','高蟾','quantangshi','','卷38','明月断魂清霭霭，平芜归思绿迢迢。
人生莫遣头如雪，纵得春风亦不消。','',''),('quantangshi-37218','秋','高蟾','quantangshi','','卷38','阳羡溪声冷骇人，洞庭山翠晚凝神。
天将金玉为风露，曾为高秋几度贫。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37219','灞陵亭','高蟾','quantangshi','','卷38','一条归梦朱弦直，一片离心白羽轻。
明日灞陵新霁后，马头烟树绿相迎。','',''),('quantangshi-37220','偶作二首 一','高蟾','quantangshi','','卷38','丁当玉佩三更雨，平帖金闺一觉云。
明日薄情何处去，风流春水不知君。','',''),('quantangshi-37221','偶作二首 二','高蟾','quantangshi','','卷38','霞衣重叠红蝉暖，云髻葱笼紫凤寒。
天上少年分散后，一条烟水若为看。','',''),('quantangshi-37222','永夕','高蟾','quantangshi','','卷38','云鸿宿处江村冷，独狖啼时海国阴。
不会残灯无一事，觉来犹有向隅心。','',''),('quantangshi-37223','落花','高蟾','quantangshi','','卷38','一叶落时空下泪，三春归尽复何情。
无人共得东风语，半日尊前计不成。','',''),('quantangshi-37224','下第后上永崇高侍郎','高蟾','quantangshi','','卷38','天上碧桃和露种，日边红杏倚云栽。
芙蓉生在秋江上，不向东风怨未开。','',''),('quantangshi-37225','句','高蟾','quantangshi','','卷38','君恩秋后叶，日日向人疎。','',''),('quantangshi-37226','城南偶题','章謁','quantangshi','','卷38','谁家朱阁道边开，竹拂栏干满壁苔。
野水不知何处去，游人却是等闲来。
南山气耸分红树，北阙风高隔紫苔。
可惜登临好光景，五门须听鼓声回。','',''),('quantangshi-37227','赠边将','章謁','quantangshi','','卷38','千千铁骑拥尘红，去去平吞万里空。
宛转龙蟠金剑雪，连钱豹躩绣旗风。
行收部落归天阙，旋进封疆入帝聪。
只有河源与辽海，如今全属指麾中。','',''),('quantangshi-37228','桃源','章謁','quantangshi','','卷38','绝壁相欹是洞门，昔人从此入仙源。
数株花下逢珠翠，半曲歌中老子孙。
别后自疑园吏梦，归来谁信钓翁言。
山前空有无情水，犹遶当时碧树村。','',''),('quantangshi-37229','曲江','章謁','quantangshi','','卷38','日照香尘逐马蹄，风吹浪溅几回堤。
无穷罗绮填花径，大半笙歌占麦畦。
落絮却笼他树白，娇莺更学别禽啼。
秪缘频燕蓬洲客，引得游人去似迷。','',''),('quantangshi-37230','送韦岫郎中典泗州','章謁','quantangshi','','卷38','玉皇恩诏别星班，去压徐方分野间。
有鸟尽巢垂汴柳，无楼不到隔淮山。
旌旗渐向行时拥，案牍应从到日闲。
想忆朝天独吟坐，旋飞新作过秦关。','',''),('quantangshi-37231','赠婺州苏员外','章謁','quantangshi','','卷38','帝念琼枝欲并芳，星分婺女寄仙郎。
鸾从阙下虽辞侣，雁到江都却续行。
烟月一时搜古句，山川两地植甘棠。
即看龙虎西归去，便佐羲轩活万方。','',''),('quantangshi-37232','寄友人','章謁','quantangshi','','卷38','谢家山水属君家，曾共持钩掷岁华。
竹里竹鸡眠藓石，溪头鸂鶒踏金沙。
登楼夜坐三层月，接果春看五色花。
昨日西风动归思，满船凉叶在天涯。','',''),('quantangshi-37233','雨','章謁','quantangshi','','卷38','低着烟花漠漠轻，正堪吟坐掩柴扃。
乱沾细网垂穷巷，斜送阴云入古厅。
锁却暮愁终不散，添成春醉转难醒。
霁来还有风流事，重染南山一遍青。','',''),('quantangshi-37234','观锡宴','章謁','quantangshi','','卷38','倾朝朱紫正骈阗，红杏青莎映广筵。
不道楼台无锦绣，只愁尘土扑神仙。
鱼衔嫩草浮池面，蝶趂飞花到酒边。
日暮骅骝相拥去，几人沉醉失金鞭。','',''),('quantangshi-37235','城东即事','章謁','quantangshi','','卷38','闲寻香陌凤城东，时暂开襟向远风。
玉笛一声芳草外，锦鸳双起碧流中。
苑边花竹浓如绣，渭北山川澹似空。
回首汉宫烟霭里，天河金阁未央宫。','',''),('quantangshi-37236','夏日湖上即事寄晋陵萧明府','章謁','quantangshi','','卷38','亭午羲和驻火轮，开门嘉树庇湖濆。
行来宾客奇茶味，睡起儿童带簟纹。
屋小有时投树影，舟轻不觉入鸥羣。
陶家岂是无诗酒，公退堪惊日已曛。','',''),('quantangshi-37237','对月','章謁','quantangshi','','卷38','残霞卷尽出东溟，万古难消一片冰。
公子踏开香径藓，美人吹灭画堂灯。
琼轮正辗丹霄去，银箭休催皓露凝。
别有洞天三十六，水晶台殿冷层层。','',''),('quantangshi-37238','浙西送杜晦侍御入关','章謁','quantangshi','','卷38','紫诏征贤发帝聪，绣衣行处扑香风。
鹗归秦树幽禽散，星出吴天列舍空。
捧日思驰仙掌外，朝宗势动海门中。
鞭鞘所拂三千里，多少诸侯合避骢。','',''),('quantangshi-37239','寄江东道友','章謁','quantangshi','','卷38','野亭歌罢指西秦，避俗争名兴各新。
碧带黄麻呈缥缈，短竿长线弄因循。
夜潮分卷三江月，晓骑齐驱九陌尘。
可惜人间好声势，片帆羸马不相亲。','',''),('quantangshi-37240','下第有怀','章謁','quantangshi','','卷38','故乡朝夕有人还，欲作家书下笔难。
灭烛何曾妨夜坐，倾壶不独为春寒。
迁来莺语虽堪听，落了杨花也怕看。
但使他年遇公道，月轮长在桂珊珊。','',''),('quantangshi-37241','春日经湖上友人别业','章謁','quantangshi','','卷38','何处狂歌破积愁，携觞共下木兰舟。
绿泉溅石银屏湿，黄鸟逢人玉笛休。
天借烟霞装岛屿，春铺锦绣作汀洲。
一年一电逡巡事，不合花前不醉游。','',''),('quantangshi-37242','长安春日','章謁','quantangshi','','卷38','春日皇家瑞景迟，东风无力雨微微。
六宫罗绮同时泊，九陌烟花一样飞。
暖着柳丝金蘂重，冷开山翠雪棱稀。
输他得路蓬洲客，红绿山头烂醉归。','',''),('quantangshi-37243','陪浙西王侍郎夜宴','章謁','quantangshi','','卷38','深锁雷门宴上才，旋看歌舞旋传杯。
黄金鸂鶒当筵睡，红锦蔷薇影烛开。
稽岭好风吹玉佩，镜湖残月照楼台。
小儒末座频倾耳，祗怕城头画角催。','',''),('quantangshi-37244','春别','章謁','quantangshi','','卷38','掷下篱觞指乱山，趋程不待凤笙残。
花边马嚼金衔去，楼上人垂玉筯看。
柳陌虽然风袅袅，葱河犹自雪漫漫。
殷勤莫厌貂裘重，恐犯三边五月寒。','',''),('quantangshi-37245','送谢进士还闽','章謁','quantangshi','','卷38','百越风烟接巨鳌，还乡心壮不知劳。
雷霆入地建溪险，星斗逼人梨岭高。
却拥木绵吟丽句，便攀龙眼醉香醪。
名场声利喧喧在，莫向林泉改鬓毛。','',''),('quantangshi-37246','焚书坑','章謁','quantangshi','','卷38','竹帛烟消帝业虚，关河空锁祖龙居。
坑灰未冷山东乱，刘项元来不读书。','',''),('quantangshi-37247','东都望幸','章謁','quantangshi','','卷38','懒修珠翠上高台，眉月连娟恨不开。
纵使东巡也无益，君王自领美人来。','',''),('quantangshi-37248','旅舍早起','章謁','quantangshi','','卷38','迹暗心多感，神疲梦不游。
惊舟同厌夜，独树对悲秋。
晚角和人战，残星入汉流。
门前早行子，敲镫唱离忧。','',''),('quantangshi-37249','癸卯岁毗陵登高会中贻同志','章謁','quantangshi','','卷38','流落常嗟胜会稀，故人相遇菊花时。
凤笙龙笛数巡酒，红树碧山无限诗。
尘土十分归举子，干坤大半属偷儿。
长杨羽猎须留本，开济重为阙下期。','',''),('quantangshi-37250','上元夜建元寺观灯呈智通上人','章謁','quantangshi','','卷38','建元看别上元灯，处处回廊鬬火层。
珠玉乱抛高殿佛，绮罗深拜远山僧。
临风走笔思呈惠，到晓行禅合伴能。
无限喧阗留不得，月华西下露华凝。','',''),('quantangshi-37251','变体诗','章謁','quantangshi','','卷38','东南路尽吴江畔，正是穷愁暮雨天。
鸥鹭不嫌斜两岸，波涛欺得逆风船。
偶逢岛寺停帆看，深羡渔翁下钓眠。
今古若论英达筭，鸱夷高兴固无边。','',''),('quantangshi-37252','长安书怀','秦韜玉','quantangshi','','卷38','凉风吹雨滴寒更，乡思欺人拨不平。
长有归心悬马首，可堪无寐枕蛩声。
岚收楚岫和空碧，秋染湘江到底清。
早晚身闲着蓑去，橘香深处钓船横。','',''),('quantangshi-37253','桧树','秦韜玉','quantangshi','','卷38','翠云交干瘦轮囷，啸雨吟风几百春。
深盖屈盘青麈尾，老皮张展黑龙鳞。
唯堆寒色资琴兴，不放秋声染俗尘。
岁月如波事如梦，竟留苍翠待何人。','',''),('quantangshi-37254','读五侯传','秦韜玉','quantangshi','','卷38','汉亡金镜道将衰，便有奸臣竞佐时。
专国祗夸兄弟贵，举家谁念子孙危。
后宫得宠人争附，前殿陈诚帝不疑。
朱紫盈门自称贵，可嗟区宇尽疮痍。','',''),('quantangshi-37255','春雪','秦韜玉','quantangshi','','卷38','云重寒空思寂寥，玉尘如糁满春[朝]。
片才着地轻轻陷，力不禁风旋旋销。
惹砌任他香粉妒，萦丛自学小梅娇。
谁家醉卷珠帘看，弦管堂深暖易调。','',''),('quantangshi-37256','贫女','秦韜玉','quantangshi','','卷38','蓬门未识绮罗香，拟托良媒益自伤。
谁爱风流高格调，共怜时世俭梳妆。
敢将十指夸偏巧，不把双眉鬬画长。
苦恨年年压金线，为他人作嫁衣裳。','',''),('quantangshi-37257','题竹','秦韜玉','quantangshi','','卷38','削玉森森幽思清，院家高兴尚分明。
卷帘阴薄漏山色，欹枕韵寒宜雨声。
斜对酒缸偏觉好，静笼碁局最多情。
却惊九陌轮蹄外，独有溪烟数十茎。','',''),('quantangshi-37258','鹦鹉','秦韜玉','quantangshi','','卷38','每闻别雁竞悲鸣，却叹金笼寄此生。
早是翠襟争爱惜，可堪丹觜彊分明。
云漫陇树魂应断，歌接秦楼梦不成。
幸自禰衡人未识，赚他作赋被时轻。','',''),('quantangshi-37259','寄李处士','秦韜玉','quantangshi','','卷38','吕望甘罗道已彰，只凭时数为门张。
世涂必竟皆应定，人事都来不在忙。
要路强干情本薄，旧山归去意偏长。
因君指似封侯骨，渐拟回头别醉乡。','',''),('quantangshi-37260','对花','秦韜玉','quantangshi','','卷38','长与韶光暗有期，可怜蜂蝶却先知。
谁家促席临低树，何处横钗戴小枝？
丽日多情疑曲照，和风得路合偏吹。
向人虽道浑无语，笑劝王孙到醉时。','',''),('quantangshi-37261','寄怀','秦韜玉','quantangshi','','卷38','总藏心劒事儒风，大道如今已浑同。
会致名津搜儁彦，是张愁网绊英雄。
苏公有国皆悬印，楚将无官可赏功。
若使重生太平日，也应回首哭涂穷。','',''),('quantangshi-37262','题刑部李郎中山亭','秦韜玉','quantangshi','','卷38','侬家云水本相知，每到高斋强展眉。
瘦竹嚲烟遮板阁，卷荷擎雨出盆池。
笑吟山色同欹枕，闲背庭阴对覆碁。
不是主人多野兴，肯开青眼重渔师。','',''),('quantangshi-37263','八月十五日夜同卫谏议看月','秦韜玉','quantangshi','','卷38','常时月好赖新晴，不似年年此夜生。
初出海涛疑尚湿，渐来云路觉偏清。
寒光入水蛟龙起，静色当天鬼魅惊。
岂独座中堪仰望，孤高应到凤凰城。','',''),('quantangshi-37264','亭台','秦韜玉','quantangshi','','卷38','雕楹累栋架崔嵬，院宇生烟次第开。
为向西窗添月色，岂辞南海取花栽。
意将画地成幽沼，势拟驱山近小台。
清境渐深官转重，春时长是别人来。','',''),('quantangshi-37265','边将','秦韜玉','quantangshi','','卷38','劒光如电马如风，百捷长轻是掌中。
无定河边蕃将死，受降城外虏尘空。
旗缝雁翅如竿褭，箭拈雕翎逐隼雄。
自指燕山最高石，不知谁为勒殊功。','',''),('quantangshi-37266','塞下','秦韜玉','quantangshi','','卷38','到处人皆着战袍，麾旗风紧马蹄劳。
黑山霜重弓添硬，青冢沙平月更高。
大野几重开雪岭，长河无限旧云涛。
[凤]林关外皆唐土，何日陈兵戍不毛。','',''),('quantangshi-37267','织锦妇','秦韜玉','quantangshi','','卷38','桃花日日觅新奇，有镜何曾及画眉。
祗恐轻梭难作匹，岂辞纤手遍生胝。
合蝉巧间双盘带，联雁斜衔小折枝。
豪贵大堆酬曲彻，可怜辛苦一丝丝。','',''),('quantangshi-37268','钓翁','秦韜玉','quantangshi','','卷38','一竿青竹老江隈，荷叶衣裳可自裁。
潭定静悬丝影直，风高斜颭浪纹开。
朝携轻棹穿云去，暮背寒塘戴月回。
世上无穷嶮巇事，算应难入钓船来。','',''),('quantangshi-37269','曲江','秦韜玉','quantangshi','','卷38','曲沼深塘跃锦鳞，槐烟径里碧波新。
此中境既无佳境，他处春应不是春。
金牓真仙开乐席，银鞍公子醉花尘。
明年二月重来看，好共东风作主人。','',''),('quantangshi-37270','隋堤','秦韜玉','quantangshi','','卷38','种柳开河为胜游，堤前常使路人愁。
阴埋野色万条思，翠束寒声千里秋。
西日至今悲兔苑，东[波]终不反龙舟。
远山应见繁华事，不语青青对水流。','',''),('quantangshi-37271','天街','秦韜玉','quantangshi','','卷38','九衢风景尽争新，独占天门近紫宸。
宝马竞随朝暮客，香车争碾古今尘。
烟光正入南山色，气势遥连北阙春。
莫见繁华祗如此，暗中还换往来人。','',''),('quantangshi-37272','紫骝马','秦韜玉','quantangshi','','卷38','渥洼奇骨本难求，况是豪家重紫骝。
膘大宜悬银压胯，力浑欺着玉衔头。
生狞弄影风随步，踥蹀冲尘汗满沟。
若遇丈夫能控驭，任从骑取觅封侯。','',''),('quantangshi-37273','问古','秦韜玉','quantangshi','','卷38','大底荣枯各自行，兼疑阴隲也难明。
无门雪向头中出，得路云从脚下生。
深作四溟何浩渺，高为五岳太峥嵘。
都来总向人间看，直到皇天可是平。','',''),('quantangshi-37274','豪家','秦韜玉','quantangshi','','卷38','石甃通渠引御波，绿槐阴里五侯家。
地衣镇角香狮子，帘额侵钩绣辟邪。
按彻清歌天未晓，饮回深院漏犹赊。
四邻池馆吞将尽，尚自堆金为买花。','',''),('quantangshi-37275','陈宫','秦韜玉','quantangshi','','卷38','临春高阁拟瀛洲，贪宠张妃作胜游。
便把江山为己有，岂知台榭是身讐。
金城暗逐歌声碎，铁瓮潜随舞势休。
谁识古宫堪恨处，井桐吟雨不胜秋。','',''),('quantangshi-37276','送友人罢举授南陵令','秦韜玉','quantangshi','','卷38','共言愁是酌离杯，况值弦歌枉大才。
献赋未为龙化去，除书犹喜凤衔来。
花明驿路燕脂暖，山入江亭罨画开。
莫把新诗题别处，谢家临水有池台。','',''),('quantangshi-37277','投知己','秦韜玉','quantangshi','','卷38','炉中九转炼虽成，教主看时亦自惊。
羣岳竝天先减翠，大江临海恐无声。
赋归已罢吴门钓，身老仍抛楚岸耕。
唯有太平方寸血，今朝尽向隗台倾。','',''),('quantangshi-37278','牡丹','秦韜玉','quantangshi','','卷38','折妖放艳有谁催，疑就仙中旋折来。
图把一春皆占断，固留三月始教开。
压枝金蘂香如扑，逐朵檀心巧胜裁。
好是酒阑丝竹罢，倚风含笑向楼台。','',''),('quantangshi-37279','春游','秦韜玉','quantangshi','','卷38','选胜逢君叙解携，思和芳草远烟迷。
小梅香里黄莺啭，垂柳阴中白马嘶。
春引美人歌遍熟，风牵公子酒旗低。
早知有此关身事，悔不前年住越溪。','',''),('quantangshi-37280','仙掌','秦韜玉','quantangshi','','卷38','万仞连峰积翠新，灵踪依旧印轮巡。
何如捧日安皇道，莫把回山示世人。
已擘峻流穿太岳，长扶王气拥彊秦。
为余势负天工背，索取风云际会身。','',''),('quantangshi-37281','燕子','秦韜玉','quantangshi','','卷38','不知大厦许栖无，频已衔泥到座隅。
曾与佳人竝头语，几回抛却绣工夫。','',''),('quantangshi-37282','奉和春日玩雪','秦韜玉','quantangshi','','卷38','北阙同云掩晓霞，东风春雪满山家。
琼章定少千人和，银树先开六出花。','',''),('quantangshi-37283','独坐吟','秦韜玉','quantangshi','','卷38','客愁不尽本如水，草色含情更无已。
又觉春愁似草生，何人种在情田里。','',''),('quantangshi-37284','采茶歌','秦韜玉','quantangshi','','卷38','天柱香芽露香发，烂研瑟瑟穿荻篾。
太守怜才寄野人，山童碾破团团月。
倚云便酌泉声煮，兽炭潜然蚪珠吐。
看着晴天早日明，鼎中飒飒筛风雨。
老翠香尘下才熟，搅时绕筯天云绿。
耽书病酒两多情，坐对闽瓯睡先足。
洗我胸中幽思清，鬼神应愁歌欲成。','',''),('quantangshi-37285','贵公子行','秦韜玉','quantangshi','','卷38','堦前莎球绿不卷，银龟喷香挽不断。
乱花织锦柳拈线，妆点池台画屏展。
主人公业传国初，六亲联络驰朝车。
鬬鸡走狗家世事，抱来皆佩黄金鱼。
却笑儒生把书卷，学得颜回忍饥面。','',''),('quantangshi-37286','吹笙歌','秦韜玉','quantangshi','','卷38','信陵名重怜高才，见我长吹青眼开。
便出燕姬再倾醑，此时花下逢仙侣。
弯弯狂月压秋波，两条黄金𨴋黄雾。
逸艳初因醉态见，浓春可是韶光与。
纤纤软玉捧暖笙，深思香风吹不去。
檀唇呼吸宫商改，怨情渐逐清新举。
岐山取得娇凤雏，管中藏着轻轻语。
好笑襄王大迂阔，曾卧巫云见神女。
银锁金簧不得听，空劳翠辇冲泥雨。','',''),('quantangshi-37287','咏手','秦韜玉','quantangshi','','卷38','一双十指玉纤纤，不是风流物不拈。
鸾镜巧梳匀翠黛，画楼闲望擘珠帘。
金杯有喜轻轻点，银鸭无香旋旋添。
因把翦刀嫌道冷，泥人呵了弄人髯。','',''),('quantangshi-37288','句','秦韜玉','quantangshi','','卷38','女娲罗裙长百尺，搭在湘江作山色。','',''),('quantangshi-37289','逢韩喜','彥謙','quantangshi','','卷38','相逢浑不觉，祗似茂陵贫。
褭褭花骄客，潇潇雨净春。
借书消茗困，索句写梅真。
此去青云上，知君有几人。','',''),('quantangshi-37290','夜坐示友','彥謙','quantangshi','','卷38','夜久烛花落，凄声生远林。
有怀嫌会浅，无事又秋深。
黄叶归田梦，白头行路吟。
山中亦可乐，不似此同襟。','',''),('quantangshi-37291','梅亭','彥謙','quantangshi','','卷38','东海穷诗客，西风古驿亭。
发从残岁白，山入故乡青。
世事徒三窟，儿曹且一经。
丁宁速赊酒，煮栗试砂瓶。','',''),('quantangshi-37292','岁除','彥謙','quantangshi','','卷38','索索风搜客，沈沈雨洗年。
残林生猎迹，归鸟避窰烟。
节物杯浆外，溪山鬓影前。
行藏都未定，笔砚或能捐。','',''),('quantangshi-37293','咏月','彥謙','quantangshi','','卷38','阴盛此宵中，多为雨与风。
坐无风雨至，看与雪霜同。
抱湿离遥海，倾寒向远空。
年年不相值，还似道难通。','',''),('quantangshi-37294','闻应德茂先离棠溪','彥謙','quantangshi','','卷38','落日芦花雨，行人谷树村。
青山时问路，红叶自知门。
苜蓿穷诗味，芭蕉醉墨痕。
端知弃城市，经席许频温。','',''),('quantangshi-37295','松','彥謙','quantangshi','','卷38','托根蟠泰华，倚干蚀莓苔。
谁云山泽间，而无梁栋材。','',''),('quantangshi-37296','梅','彥謙','quantangshi','','卷38','玉人下瑶台，香风动轻素。
画角弄江城，鸣璫月中堕。','',''),('quantangshi-37297','兰二首 一','彥謙','quantangshi','','卷38','清风摇翠环，凉露滴苍玉。
美人胡不纫，幽香蔼空谷。','',''),('quantangshi-37298','兰二首 二','彥謙','quantangshi','','卷38','谢庭漫芳草，楚畹多绿莎。
于焉忽相见，岁晏将如何。','',''),('quantangshi-37299','葡萄','彥謙','quantangshi','','卷38','金谷风露凉，绿珠醉初醒。
珠帐夜不收，月明堕清影。','',''),('quantangshi-37300','春草','彥謙','quantangshi','','卷38','随梦入池塘，无心在金谷。
春风自年年，吹遍天涯绿。','',''),('quantangshi-37301','渔','彥謙','quantangshi','','卷38','相聚即为邻，烟火自成簇。
约伴过前溪，撑破蘼芜绿。','',''),('quantangshi-37302','留别四首 一','彥謙','quantangshi','','卷38','鹏程三万里，别酒一千钟。
好景当三月，春光上国浓。','',''),('quantangshi-37303','留别四首 二','彥謙','quantangshi','','卷38','野花红滴滴，江燕语喃喃。
鼓吹翻新调，都亭酒正酣。','',''),('quantangshi-37304','留别四首 三','彥謙','quantangshi','','卷38','登庸趋俊乂，厕用野无遗。
起喜赓歌日，明良际会时。','',''),('quantangshi-37305','留别四首 四','彥謙','quantangshi','','卷38','盐车淹素志，长坂入青云。
老骥春风里，奔腾独异羣。','',''),('quantangshi-37306','秋葵','彥謙','quantangshi','','卷38','月瓣团栾翦赭罗，长条排蘂缀鸣珂。
倾阳一点丹心在，承得中天雨露多。','',''),('quantangshi-37307','春草','彥謙','quantangshi','','卷38','天北天南遶路边，托根无处不延绵。
萋萋总是无情物，吹绿东风又一年。','',''),('quantangshi-37308','春日偶成','彥謙','quantangshi','','卷38','𥱧筝箫管和琵琶，兴满金尊酒量赊。
歌舞留春春似海，美人颜色正如花。','',''),('quantangshi-37309','秋日感怀','彥謙','quantangshi','','卷38','溪上芙蓉映醉颜，悲秋宋玉鬓毛斑。
无情最恨东流水，暗逐芳年去不还。','',''),('quantangshi-37310','七夕','彥謙','quantangshi','','卷38','会合无由叹久违，一年一度是缘非。
而予愿乞天孙巧，五色纫针补衮衣。','',''),('quantangshi-37311','怀友','彥謙','quantangshi','','卷38','金井凉生梧叶秋，闲看新月上帘钩。
冰壶总忆人如玉，目断重云十二楼。','',''),('quantangshi-37312','翡翠','彥謙','quantangshi','','卷38','莎草江汀漫晚潮，翠华香扑水光遥。
玉楼春暖笙歌夜，妆点花钿上舞翘。','',''),('quantangshi-37313','咏马二首 一','彥謙','quantangshi','','卷38','紫云团影电飞瞳，骏骨龙媒自不同。
骑过玉楼金辔响，一声嘶断落花风。','',''),('quantangshi-37314','咏马二首 二','彥謙','quantangshi','','卷38','崚嶒高耸骨如山，远放春郊苜蓿间。
百战沙场汗流血，梦魂犹在玉门关。','',''),('quantangshi-37315','留别','彥謙','quantangshi','','卷38','丹湖湖上送行舟，白雁啼残芦叶秋。
采石江头旧时路，题诗还忆水边楼。','',''),('quantangshi-37316','咏竹','彥謙','quantangshi','','卷38','醉卧凉阴沁骨清，石牀冰簟梦难成。
月明午夜生虚籁，悞听风声是雨声。','',''),('quantangshi-37317','忆孟浩然','彥謙','quantangshi','','卷38','郊外淩兢西复东，雪晴驴背兴无穷。
句搜明月梨花内，趣入春风柳絮中。','',''),('quantangshi-37318','寄友三首 一','彥謙','quantangshi','','卷38','新酒秦淮缩项鳊，凌霄花下共流连。
别来客邸空翘首，细雨春风忆往年。','',''),('quantangshi-37319','寄友三首 二','彥謙','quantangshi','','卷38','寒灯孤对拥青毡，牢落何如似客边。
却忆花前酣后饮，醉呼明月上遥天。','',''),('quantangshi-37320','寄友三首 三','彥謙','quantangshi','','卷38','客里逢春一惘然，梅花落尽柳如烟。
无情最恨东来雁，底事音书不肯传。','',''),('quantangshi-37321','无题十首 一','彥謙','quantangshi','','卷38','细草铺茵绿满堤，燕飞晴日正迟迟。
寻芳陌上花如锦，折得东风第一枝。','',''),('quantangshi-37322','无题十首 二','彥謙','quantangshi','','卷38','锦筝银甲响鵾弦，勾引春声上绮筵。
醉倚阑干花下月，犀梳斜嚲鬓云边。','',''),('quantangshi-37323','无题十首 三','彥謙','quantangshi','','卷38','楚云湘雨会阳台，锦帐芙蓉向夜开。
吹罢玉箫春似海，一双彩凤忽飞来。','',''),('quantangshi-37324','无题十首 四','彥謙','quantangshi','','卷38','春江新水促归航，惜别花前酒漫觞。
倒尽银瓶浑不醉，却怜和泪入愁肠。','',''),('quantangshi-37325','无题十首 五','彥謙','quantangshi','','卷38','谁知别易会应难，目断青鸾信渺漫。
情似蓝桥桥下水，年来流恨几时干。','',''),('quantangshi-37326','无题十首 六','彥謙','quantangshi','','卷38','漏滴铜龙夜已深，柳梢斜月弄疎阴。
满园芳草年年恨，剔尽灯花夜夜心。','',''),('quantangshi-37327','无题十首 七','彥謙','quantangshi','','卷38','夜合庭前花正开，轻罗小扇为谁裁。
多情惊起双蝴蝶，飞入巫山梦里来。','',''),('quantangshi-37328','无题十首 八','彥謙','quantangshi','','卷38','忆别悠悠岁月长，酒兵无计敌愁肠。
柔丝漫折长亭柳，绾得同心欲寄将。','',''),('quantangshi-37329','无题十首 九','彥謙','quantangshi','','卷38','杨柳青青映画楼，翠眉终日锁离愁。
杜鹃啼落枝头月，多为伤春恨不休。','',''),('quantangshi-37330','无题十首 十','彥謙','quantangshi','','卷38','云色鲛[绡]拭泪颜，一帘春雨杏花寒。
几时重会鸳鸯侣，月下吹笙和彩鸾。','',''),('quantangshi-37331','寄同上人','彥謙','quantangshi','','卷38','高高山顶寺，更有最高人。
定起松鸣屋，吟圆月上身。
云藏三伏热，水散百溪津。
曾乞兰花供，无书又过春。','',''),('quantangshi-37332','夜坐','彥謙','quantangshi','','卷38','愁鬓丁年白，寒灯丙夜青。
不眠惊戍鼓，久客厌邮铃。
汹汹城喷海，疎疎屋漏星。
十年穷父子，相守慰飘零。','',''),('quantangshi-37333','吊方干处士二首 一','彥謙','quantangshi','','卷38','不谓高名下，终全玉雪身。
交犹及前辈，语不似今人。
别号行鸣雁，遗编感获麟。
歛衣应自定，只着古衣巾。','',''),('quantangshi-37334','吊方干处士二首 二','彥謙','quantangshi','','卷38','不比他人死，何诗可挽君。
渊明元嬾仕，东野别攻文。
沧海诸公泪，青山处士坟。
相看莫浪哭，私諡有前闻。','',''),('quantangshi-37335','题证道寺','彥謙','quantangshi','','卷38','弯环青径斜，自是野僧家。
满涧洗岩液，插天排石牙。
炉寒余栢子，架静落藤花。
记得逃兵日，门多贵客车。','',''),('quantangshi-37336','宿赵𡸯别业','彥謙','quantangshi','','卷38','溪山兵后县，风雪旅中人。
迫夜愁严鼓，冲寒托软巾。
摧藏名字在，疏率馔肴真。
今代徐元直，高风自可亲。','',''),('quantangshi-37337','原上','彥謙','quantangshi','','卷38','危桥横古渡，村野带平林。
野骛寒塘静，山禽晓树深。
雨微风矗□，云暗雪侵寻。
安道门前水，清游岂独吟。','',''),('quantangshi-37338','寄台省知己','彥謙','quantangshi','','卷38','久怀声籍甚，千里致双鱼。
宦路终推毂，亲帏且着书。
才名贾太傅，文学马相如。','',''),('quantangshi-37339','自咏','彥謙','quantangshi','','卷38','白发三千丈，青春四十年。
两牙摇欲落，双膝痹如挛。
强仕非时彦，无闻惜昔贤。
自期终见恶，未忍舍遗编。','',''),('quantangshi-37340','游阳明洞呈王理得诸君','彥謙','quantangshi','','卷38','禹穴苍茫不可探，人传灵笈锁烟岚。
初晴鹤点青边嶂，欲雨龙移黑处潭。
北斗斋坛天寂寂，东风仙洞草毵毵。
堪怜尹叟非关吏，犹向江南逐老聃。','',''),('quantangshi-37341','新丰','彥謙','quantangshi','','卷38','沛中歌舞百余人，帝业功成里巷新。
半夜素灵先哭楚，一星遗火下烧秦。
貔貅扫尽无三户，鸡犬归来识四邻。
惆怅故园前事远，晓风长路起埃尘。','',''),('quantangshi-37342','拜越公墓因游定水寺有怀源老','彥謙','quantangshi','','卷38','越公已作飞仙去，犹得潭潭好墓田。
老树背风深拓地，野云依海细分天。
青峰晓接鸣钟寺，玉井秋澄试茗泉。
我与源公旧相识，遗言潇洒有人传。','',''),('quantangshi-37343','任潜谋隐之作','彥謙','quantangshi','','卷38','江边秋日逢任子，大理索诗吾欲忘。
为问山资何次第，祗余丹诀转凄凉。
黄金范蠡曾辞禄，白首虞翻未信方。
千古浮云共归思，晓风城郭水花香。','',''),('quantangshi-37344','晚秋游中溪','彥謙','quantangshi','','卷38','淡竹冈前沙雁飞，小花尖下柘丸肥。
山云不卷雨自薄，天气欲寒人正归。
招伴祗须新稻酒，临风犹有旧苔矶。
故人旧业依稀在，怪石老松今是非。','',''),('quantangshi-37345','寄陈少府兼简叔高','彥謙','quantangshi','','卷38','怀人路绝云归海，避俗门深草蔽丘。
万事渐消闲客梦，一年虚白少年头。
山螿啼缓从除架，淮雁来多莫上楼。
近日邻家有新酿，每逢诗伴得淹留。','',''),('quantangshi-37346','过清凉王导墓下','彥謙','quantangshi','','卷38','江左风流廊庙人，荒坟抛与梵宫邻。
多年羊虎犹眠石，败壁貂蝉祗贮尘。
万古云山同白骨，一庭花木自青春。
永思陵下犹凄切，废屋寒风吹野薪。','',''),('quantangshi-37347','第三溪','彥謙','quantangshi','','卷38','日晏霜浓十二月，林疎石瘦第三溪。
云沙有径萦寒烧，松屋无人闻昼鸡。
几聚衣冠埋作土，当年歌舞醉如泥。
早知涉世真成梦，不弃山田春雨犁。','',''),('quantangshi-37348','蒲津河亭','彥謙','quantangshi','','卷38','宿雨清秋霁景澄，广亭高树向晨兴。
烟横博望乘槎水，日上文王避雨陵。
孤棹夷犹期独往，曲阑愁绝每长凭。
思乡怀古多伤别，况此哀吟意不胜。','',''),('quantangshi-37349','毗陵道中','彥謙','quantangshi','','卷38','百年只有百清明，狼狈今年又避兵。
烟火谁开寒食禁，簪裾那复丽人行。
禾麻地废生边气，草木春寒起战声。
渺渺飞鸿天断处，古来还是阖闾城。','',''),('quantangshi-37350','越城待旦','彥謙','quantangshi','','卷38','策策虚楼竹隔明，悲来展转向谁倾。
天寒[胡]雁出万里，月落越鸡啼四更。
为底朱颜成老色，看人青史上新名。
清溪白石村村有，五尺乌犍托此生。','',''),('quantangshi-37351','过浩然先生墓','彥謙','quantangshi','','卷38','人间万卷庞眉老，眼见堂堂入草莱。
行客须当下马过，故交谁复裹鸡来。
山花不语如听讲，溪水无情自荐哀。
犹胜黄金买碑碣，百年名字已烟埃。','',''),('quantangshi-37352','赠孟德茂','彥謙','quantangshi','','卷38','江海悠悠雪欲飞，抱书空出又空归。
沙头人满鸥应笑，船上酒香鱼正肥。
尘土竟成谁计是，山林又悔一年非。
平生万卷应夫子，两世功名穷布衣。','',''),('quantangshi-37353','秋霁丰德寺与玄贞师咏月','彥謙','quantangshi','','卷38','露冷风轻霁魄圆，高楼更在碧山巅。
四溟水合疑无地，八月槎通好上天。
黯黯星辰环紫极，喧喧朝市匝青烟。
夜深独与岩僧语，羣动消声举世眠。','',''),('quantangshi-37354','长陵','彥謙','quantangshi','','卷38','长安高阙此安刘，祔葬累累尽列侯。
丰上旧居无故里，沛中原庙对荒丘。
耳闻明主提三尺，眼见愚民盗一[坯]。
千载腐儒骑瘦马，渭城斜月重回头。','',''),('quantangshi-37355','留别','彥謙','quantangshi','','卷38','西入潼关路，何时更盍簪。
年来人事改，老去鬓毛侵。
花染离筵泪，葵倾报国心。
龙潭千尺水，不似别情深。','',''),('quantangshi-37356','宿独留','彥謙','quantangshi','','卷38','日晚宿留城，人家半掩门。
羣鸦栖老树，一犬吠荒村。
争买鱼添价，新篘酒带浑。
船头对新月，谁与共清论。','',''),('quantangshi-37357','客中感怀','彥謙','quantangshi','','卷38','客路三千里，西风两鬓尘。
贪名笑吴起，说国叹苏秦。
托兴非耽酒，思家岂为蒪。
可怜今夜月，独照异乡人。','',''),('quantangshi-37358','过三山寺','彥謙','quantangshi','','卷38','三山江上寺，宫殿望岧嶤。
石径侵高树，沙滩半种苗。
一僧归晚日，羣鹭宿寒潮。
遥听风铃语，兴亡话六朝。','',''),('quantangshi-37359','望夫石','彥謙','quantangshi','','卷38','江上见危矶，人形立翠微。
妾来终日望，夫去几时归。
明月空悬镜，苍苔漫补衣。
可怜双泪眼，千古断斜晖。','',''),('quantangshi-37360','过湖口','彥謙','quantangshi','','卷38','江湖分两路，此地是通津。
云净山浮翠，风高浪泼银。
人行俱是客，舟住即为邻。
俯仰烟波内，蜉蝣寄此身。','',''),('quantangshi-37361','夜泊东溪有怀','彥謙','quantangshi','','卷38','水昏天色晚，崖下泊行舟。
独客伤归雁，孤眠叹野鸥。
溪声牵别恨，乡梦惹离愁。
酒醒推篷坐，凄凉望女牛。','',''),('quantangshi-37362','登庐山','彥謙','quantangshi','','卷38','五老峰巅望，天涯在目前。
湘潭浮夜雨，巴蜀暝寒烟。
泰华根同峙，嵩衡脉共联。
凭虚有仙骨，日月看推迁。','',''),('quantangshi-37363','金陵九日','彥謙','quantangshi','','卷38','野菊西风满路香，雨花台上集壶觞。
九重天近瞻钟阜，五色云中望建章。
绿酒莫辞今日醉，黄金难买少年狂。
清歌惊起南飞雁，散作秋声送夕阳。','',''),('quantangshi-37364','游清凉寺','彥謙','quantangshi','','卷38','白云红树路纡萦，古殿长廊次第行。
南望水连桃叶渡，北来山枕石头城。
一尘不到心源净，万有俱空眼界清。
竹院逢僧旧曾识，旋披禅衲为相迎。','',''),('quantangshi-37365','高平九日','彥謙','quantangshi','','卷38','云净南山紫翠浮，凭陵绝顶望悠悠。
偶逢佳节牵诗兴，漫把芳尊遣客愁。
霜染鸦枫迎日醉，寒冲泾水带冰流。
乌纱频岸西风里，笑插黄花满鬓秋。','',''),('quantangshi-37366','金陵怀古','彥謙','quantangshi','','卷38','碧树凉生宿雨收，荷花荷叶满汀洲。
登高有酒浑忘醉，慨古无言独倚楼。
宫殿六朝遗古迹，衣冠千古漫荒丘。
太平时节殊风景，山自青青水自流。','',''),('quantangshi-37367','道中逢故人','彥謙','quantangshi','','卷38','兰陵市上忽相逢，叙别殷勤兴倍浓。
良会若同鸡黍约，暂时不放酒杯空。
愁牵白发三千丈，路入青山几万重。
行色一鞭催去马，画桥嘶断落花风。','',''),('quantangshi-37368','早行遇雪','彥謙','quantangshi','','卷38','下马天未明，风高雪何急。
须臾路欲迷，顷刻山尽白。
鸡犬寂无声，曙光射寒色。
荒村绝烟火，髯冻布袍湿。
王事不可缓，行行动凄恻。','',''),('quantangshi-37369','樊登见寄四首 一','彥謙','quantangshi','','卷38','新辞翦秋水，洗我胸中尘。
无由惬良会，极目空怀人。
醉来拔剑歌，字字皆阳春。','',''),('quantangshi-37370','樊登见寄四首 二','彥謙','quantangshi','','卷38','轻黄着柳条，新春喜更始。
感时重搔首，怅望不能已。
无由托深情，倾泻芳尊里。','',''),('quantangshi-37371','樊登见寄四首 三','彥謙','quantangshi','','卷38','明月入我室，天风吹我袍。
良夜最岑寂，旅况何萧条。
驰情望海波，一鹤鸣九臯。','',''),('quantangshi-37372','樊登见寄四首 四','彥謙','quantangshi','','卷38','悠悠括城北，眄眄岩泉西。
宿草暝烟绿，苦竹含云低。
幽怀不可托，鹧鸪空自啼。','',''),('quantangshi-37373','春风四首 一','彥謙','quantangshi','','卷38','春风吹愁端，散漫不可收。
不如古溪水，祗望乡江流。','',''),('quantangshi-37374','春风四首 二','彥謙','quantangshi','','卷38','新花红烁烁，旧花满山白。
昔日金张门，狼籍余废宅。','',''),('quantangshi-37375','春风四首 三','彥謙','quantangshi','','卷38','回头语春风，莫向新花丛。
我见朱颜人，多金亦成翁。','',''),('quantangshi-37376','春风四首 四','彥謙','quantangshi','','卷38','多金不足惜，丹砂亦何益。
更种明年花，春风自相识。','',''),('quantangshi-37377','感物二首 一','彥謙','quantangshi','','卷38','騄骥初失羣，亦自矜趫腾。
俛仰岁时久，帖然困蚊蝇。
豪鲸逸其穴，尺水成沧溟。
岂无鱼鼈交，望望为所憎。
物理有翕张，达人同废兴。
幸无怵迫忧，聊复曲吾肱。','',''),('quantangshi-37378','感物二首 二','彥謙','quantangshi','','卷38','鱼目出泥沙，空村百金珍。
豫章值拥辏，细细供蒸薪。
论材何必多，适用即能神。
托交何必深，寡求永相亲。
鲍叔拙羇鲁，张生穷厄陈。
茫然扳援际，岂意出风尘。','',''),('quantangshi-37379','和陶渊明贫士诗七首 一','彥謙','quantangshi','','卷38','贫贱如故旧，少壮即相依。
中心不敢厌，但觉少光辉。
向来乘时士，亦有能奋飞。
一朝权势歇，欲退无所归。
不如行其素，辛苦奈寒饥。
人生系天运，何用发深悲。','',''),('quantangshi-37380','和陶渊明贫士诗七首 二','彥謙','quantangshi','','卷38','我居在穷巷，来往无华轩。
辛勤衣食物，出此二亩园。
薤菘郁朝露，桑柘浮春烟。
以兹乱心曲，智计无他奸。
择胜不在奢，兴至发清言。
相逢樵牧徒，混混谁愚贤。','',''),('quantangshi-37381','和陶渊明贫士诗七首 三','彥謙','quantangshi','','卷38','松风四山来，清宵响瑶琴。
听之不能寐，中有怨叹音。
旦起绕其树，磈砢不计寻。
清阴可敷席，有酒谁与斟。
由来大度士，不受流俗侵。
浩歌相倡答，慰此霜雪心。','',''),('quantangshi-37382','和陶渊明贫士诗七首 四','彥謙','quantangshi','','卷38','中年涉事熟，欲学唾面娄。
逡巡避少年，赴秽不敢酬。
旁人吁已甚，自喜计虑周。
微劳消厚疚，残辱胜深忧。
从知为下安，处上反无俦。
人生各有志，勇懦从所求。','',''),('quantangshi-37383','和陶渊明贫士诗七首 五','彥謙','quantangshi','','卷38','古人重畎亩，有禄不待干。
德成禄自至，释耒列王官。
不仕亦不贫，本自足饔飱。
后世耻躬耕，号呼脱饥寒。
我生千𥜥后，念此愧在颜。
为农倘可饱，何用出柴关。','',''),('quantangshi-37384','和陶渊明贫士诗七首 六','彥謙','quantangshi','','卷38','村郊多父老，面垢头如蓬。
我尝使之年，言语不待工。
古来名节士，敢望彭城龚。
有叟诮其后，更恨道不通。
鄙哉譊譊者，为隘不为通。
低头拜野老，负米吾愿从。','',''),('quantangshi-37385','和陶渊明贫士诗七首 七','彥謙','quantangshi','','卷38','去年秋事荒，贩籴仰邻州。
健者道路间，什百成朋俦。
今年渐向熟，庶几民不流。
书生自无田，与众同喜忧。
作诗劳邻曲，有倡谁与酬。
亦无采诗者，此修何可修。','',''),('quantangshi-37386','舟中望紫岩','彥謙','quantangshi','','卷38','近山如画墙，远山如帚长。
我从云中来，回头白茫茫。
惜去乃尔觉，常时自相忘。
相忘岂不佳，遣此怀春伤。
飘洒从何来，衣巾湿微凉。
初疑风雨集，冉冉游尘黄。
无归亦自可，信美非吾乡。
登舟望东云，犹向帆端翔。','',''),('quantangshi-37387','九日游中溪','彥謙','quantangshi','','卷38','悠悠循涧行，磊磊据石坐。
林垂短长云，山缀丹碧颗。
蓼花最无数，照水娇婀娜。
何知是节序，风日自清妥。
羣童竞时新，万果间蔬蓏。
欣然为之醉，乌帽危不堕。
此日山中怀，孟公不如我。','',''),('quantangshi-37388','六[月]十三日上陈微博士 一','彥謙','quantangshi','','卷38','骄云飞散雨，随风为有无。
老农终岁心，望施在须臾。
平生官田粟，长此礼义躯。
置之且勿戚，一饱任妻孥。','',''),('quantangshi-37389','六[月]十三日上陈微博士 二','彥謙','quantangshi','','卷38','青青泽中蒲，九夏气凄寒。
翾翾翠碧羽，照影苍溪间。
巢由薄天下，俗士荣一官。
小大各有适，自全良独难。','',''),('quantangshi-37390','六[月]十三日上陈微博士 三','彥謙','quantangshi','','卷38','穷居无公忧，私此长夏日。
蚊蝇如俗子，正尔相妒嫉。
麾驱非吾任，遁避亦无术。
惟当俟其定，静坐万虑一。','',''),('quantangshi-37391','宿田家','彥謙','quantangshi','','卷38','落日下遥峰，荒村倦行履。
停车息茅店，安寝正鼾睡。
忽闻扣门急，云是下乡隶。
公文捧花柙，鹰隼驾声势。
良民惧官府，听之肝胆碎。
阿母出搪塞，老脚走颠踬。
小心事延欵，□余粮复匮。
东邻借种鸡，西舍觅芳醑。
再饭不厌饱，一饮直呼醉。
明朝怯见官，苦苦灯前跪。
使我不成眠，为渠滴清泪。
民膏日已瘠，民力日愈弊。
空怀伊尹心，何补尧舜治。','',''),('quantangshi-37392','夏日访友','彥謙','quantangshi','','卷38','[堤]树生昼凉，浓阴扑空翠。
孤舟唤野渡，村疃入幽邃。
高轩俯清流，一犬隔花吠。
童子立门墙，问我向何处？
主人闻故旧，出迎时倒屣。
惊迓叙间阔，屈指越寒暑。
殷勤为延欵，偶尔得良会。
春盘擘紫虾，冰鲤斫银鲙。
荷梗白玉香，荇菜青丝脆。
腊酒击泥封，罗列总新味。
移席临湖滨，对此有佳趣。
流连送深杯，宾主共忘醉。
清风岸乌纱，长揖谢君去。
世事如浮云，东西渺烟水。','',''),('quantangshi-37393','游南明山','彥謙','quantangshi','','卷38','久闻南明山，共慕南明寺。
几度欲登临，日逐扰人事。
于焉偶闲暇，鸣辔忽相聚。
乘兴乐遨游，聊此托佳趣。
涉水渡溪南，迢遥翠微里。
石磴千叠斜，峭壁半空起。
白云锁峰腰，红叶暗溪嘴。
长藤络虚岩，疎花映寒水。
金银拱梵刹，丹青照廊宇。
石梁卧秋溟，风铃作檐语。
深洞结苔阴，岚气滴晴雨。
羊肠转咫尺，鸟道转千里。
屈曲到禅房，上人喜延竚。
香分宿火薰，茶汲清泉煮。
投闲息万机，三生有宿契。
行厨出盘飧，担瓮倒芳醑。
脱冠挂长松，白石籍凭倚。
宦途劳营营，暂此涤尘虑。
阄令促传觞，投壶更联句。
兴来较胜负，醉后忘尔汝。
忽闻吼蒲牢，落日下云屿。
长啸出烟萝，扬鞭赋归去。','',''),('quantangshi-37394','索虾','彥謙','quantangshi','','卷38','姑孰多紫虾，独有湖阳优。
出产在四时，极美宜于秋。
双箝鼓繁须，当顶抽长矛。
鞠躬见汤王，封作朱衣侯。
所以供盘餐，罗列同珍羞。
蒜友日相亲，瓜朋时与俦。
既名钓诗钓，又作钩诗钩。
于时同相访，数日承欵留。
厌饮多美味，独此心相投。
别来岁云久，驰想空悠悠。
衔杯动遐思，{拶扌=口}口涎空流。
封缄托双鲤，于焉来远求。
慷慨胡隐君，果肯分惠否。','',''),('quantangshi-37395','采桑女','彥謙','quantangshi','','卷38','春风吹蚕细如蚁，桑芽才努青鸦嘴。
侵晨探采谁家女，手挽长条泪如雨。
去岁初眠当此时，今岁春寒叶放迟。
愁听门外催里胥，官家二月收新丝。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37396','送许户曹','彥謙','quantangshi','','卷38','沙头小燕鸣春和，杨柳垂丝烟倒拖。
将军楼船发浩歌，云樯高插天嵯峨。
白虹走香倾翠壶，劝饮花前金叵罗。
神鳌驾粟升天河，新承雨泽浮恩波。','',''),('quantangshi-37397','咏葡萄','彥謙','quantangshi','','卷38','西园晚霁浮嫩凉，开尊漫摘葡萄尝。
满架高撑紫络索，一枝斜嚲金琅璫。
天风飕飕叶栩栩，蝴蝶声干作晴雨。
神蛟清夜蛰寒潭，万片湿云飞不起。
石家美人金谷游，罗帏翠幕珊瑚钩。
玉盘新荐入华屋，珠帐高悬夜不收。
胜游记得当年景，清气逼人毛骨冷。
笑呼明镜上遥天，醉倚银牀弄秋影。','',''),('quantangshi-37398','蟹','彥謙','quantangshi','','卷38','湖田十月清霜堕，晚稻初香蟹如虎。
扳罾拖网取赛多，篾篓挑将水边货。
纵横连爪一尺长，秀凝铁色含湖光。
蟛蜞石蟹已曾食，使我一见惊非常。
买之最厌黄髯老，偿价十钱尚嫌少。
漫夸丰味过蝤蛑，尖脐犹胜团脐好。
充盘煮熟堆琳琅，橙膏酱渫调堪尝。
一斗擘开红玉满，双螯{拶扌=口}出琼酥香。
岸头沽得泥封酒，细嚼频斟弗停手。
西风张翰苦思鲈，如斯丰味能知否。
物之可爱尤可憎，尝闻取刺于青蝇。
无肠公子固称美，弗使当道禁横行。','',''),('quantangshi-37399','叙别','彥謙','quantangshi','','卷38','谯楼夜促莲花漏，树阴摇月蛟螭走。
蟠拏对月吸深杯，月府清虚玉兔吼。
翠盘擘脯胭脂香，碧碗敲冰分蔗浆。
十载番思旧时事，好怀不似当年狂。
夜合花香开小院，坐爱凉风吹醉面。
酒中弹剑发清歌，白发年来为愁变。','',''),('quantangshi-37400','绯桃','彥謙','quantangshi','','卷38','短墙荒圃四无邻，烈火绯桃照地春。
坐久好风休掩袂，夜来微雨已霑巾。
敢同俗态期青眼，似有微词动绛唇。
尽日更无乡井念，此时何必见秦人。','',''),('quantangshi-37401','小院','彥謙','quantangshi','','卷38','小院无人夜，烟斜月转明。
清宵易惆怅，不必有离情。','',''),('quantangshi-37402','春雪初霁杏花正芳月上夜吟','彥謙','quantangshi','','卷38','霁景明如练，繁英杏正芳。
姮娥应有语，悔共雪争光。','',''),('quantangshi-37403','文惠宫人','彥謙','quantangshi','','卷38','认得前家令，宫人泪满裾。
不知梁佐命，全是沈尚书。','',''),('quantangshi-37404','赠窦尊师','彥謙','quantangshi','','卷38','我爱窦高士，弃官仍在家。
为嫌句漏令，兼不要丹砂。','',''),('quantangshi-37405','穆天子传','彥謙','quantangshi','','卷38','王母清歌玉琯悲，瑶台应有再来期。
穆王不得重相见，恐为无端哭盛姬。','',''),('quantangshi-37406','楚天','彥謙','quantangshi','','卷38','楚天遥望每长嚬，宋玉襄王尽作尘。
不会瑶姬朝与暮，更为云雨待何人。','',''),('quantangshi-37407','寄徐山人','彥謙','quantangshi','','卷38','一室清羸鹤体孤，气和神莹爽冰壶。
吴中高士虽求死，不那稽山有谢敷。','',''),('quantangshi-37408','题宗人故帖','彥謙','quantangshi','','卷38','所忠无处访相如，风笈尘编迹尚余。
惟有孝标情最厚，一编遗在茂陵书。','',''),('quantangshi-37409','垂柳','彥謙','quantangshi','','卷38','绊惹春风别有情，世间谁敢鬬轻盈。
楚王江畔无端种，饿损纤腰学不成。','',''),('quantangshi-37410','登兴元城观烽火','彥謙','quantangshi','','卷38','汉川城上角三呼，扈跸防边列万夫。
[褒]姒冢前烽火起，不知泉下破颜无。','',''),('quantangshi-37411','邓艾庙','彥謙','quantangshi','','卷38','昭烈遗黎死尚羞，挥刀斫石恨谯周。
如何千载留遗庙，血食巴山伴武侯。','',''),('quantangshi-37412','曲江春望','彥謙','quantangshi','','卷38','杏艳桃光夺晚霞，乐游无庙有年华。
汉朝冠盖皆陵墓，十里宜春汉苑花。','',''),('quantangshi-37413','汉殿','彥謙','quantangshi','','卷38','鸟去云飞意不通，夜坛斜月转松风。
君主寂虑无消息，却就闲人觅巨公。','',''),('quantangshi-37414','贺李昌时禁苑新命','彥謙','quantangshi','','卷38','振鹭翔鸾集禁闱，玉堂珠树莹风仪。
不知新到灵和殿，张绪何如柳一枝。','',''),('quantangshi-37415','牡丹','彥謙','quantangshi','','卷38','颜色无因饶锦绣，馨香惟解掩兰荪。
那堪更被烟蒙蔽，南国西施泣断魂。','',''),('quantangshi-37416','罗江驿','彥謙','quantangshi','','卷38','数枝高柳带鸣鸦，一树山榴自落花。
已是向来多泪眼，短亭回首在天涯。','',''),('quantangshi-37417','奏捷西蜀题沲江驿','彥謙','quantangshi','','卷38','野客乘轺非所宜，况将儒懦报戎机。
锦江不识临邛酒，且免相如渴病归。','',''),('quantangshi-37418','春早落英','彥謙','quantangshi','','卷38','纷纷从此见花残，转觉长绳系日难。
楼上有愁春不浅，小桃风雪凭阑干。','',''),('quantangshi-37419','仲山','彥謙','quantangshi','','卷38','千载遗踪寄薜萝，沛中乡里旧山河。
长陵亦是闲丘陇，异日谁知与仲多。','',''),('quantangshi-37420','汉嗣','彥謙','quantangshi','','卷38','汉嗣安危系数君，高皇决意势难分。
张良口辨周昌吃，同建储宫第一勋。','',''),('quantangshi-37421','四老庙','彥謙','quantangshi','','卷38','四汉储宫定不倾，可能园绮胜良平。
举朝公将无全策，借请闲人羽翼成。','',''),('quantangshi-37422','南梁戏题汉高庙','彥謙','quantangshi','','卷38','数载从军似武夫，今随戎捷气偏粗。
汉皇若问何为者，免道高阳旧酒徒。','',''),('quantangshi-37423','洛神','彥謙','quantangshi','','卷38','人世仙家本自殊，何须相见向中途。
惊鸿瞥过游龙去，漫恼陈王一事无。','',''),('quantangshi-37424','初秋到慈州冬首换绛牧','彥謙','quantangshi','','卷38','秋杪方攀玉树枝，隔年无计待春晖。
自嫌暂作仙城守，不逐莺来共燕飞。','',''),('quantangshi-37425','重经冯家旧里','彥謙','quantangshi','','卷38','冯家旧宅闭柴关，修竹犹存潏水湾。
应系星辰天上去，不留英骨葬人间。','',''),('quantangshi-37426','克复后登安国寺阁','彥謙','quantangshi','','卷38','千门万户鞠蒿藜，断烬遗垣一望迷。
惆怅建章鸳瓦尽，夜来空见玉绳低。','',''),('quantangshi-37427','题虔僧室','彥謙','quantangshi','','卷38','何缘春恨贮离忧，欲入空门万事休。
水月定中何所谓，也嚬眉黛托腮愁。','',''),('quantangshi-37428','见炀帝宝帐','彥謙','quantangshi','','卷38','汉文穷相作前王，悭惜明珠不斗量。
翡翠鲛鮹何所直，千裨万接上书囊。','',''),('quantangshi-37429','楼上偶题','彥謙','quantangshi','','卷38','尘土无因狎隐沦，青山一望每伤神。
可能前岭空乔木，应有怀才抱器人。','',''),('quantangshi-37430','亲仁里闻猨','彥謙','quantangshi','','卷38','朱雀街东半夜惊，楚魂湘梦两徒清。
五更撩乱趋朝火，满口尘埃亦数声。','',''),('quantangshi-37431','闻李渎司勋下世','彥謙','quantangshi','','卷38','异乡丹旐已飘扬，一顾深知实未亡。
任被褚裒泉下笑，重将北面哭真长。','',''),('quantangshi-37432','试夜题省廊桂','彥謙','quantangshi','','卷38','麻衣穿穴两京尘，十见东堂绿桂春。
今日竞飞杨叶箭，魏舒休作画筹人。','',''),('quantangshi-37433','竹风','彥謙','quantangshi','','卷38','竹映风窗数阵斜，旅人愁坐思无涯。
夜来留得江湖梦，全为干声似荻花。','',''),('quantangshi-37434','长溪秋望','彥謙','quantangshi','','卷38','柳短莎长溪水流，雨微烟暝立溪头。
寒鸦闪闪前山去，杜曲黄昏独自愁。','',''),('quantangshi-37435','严子陵','彥謙','quantangshi','','卷38','严陵情性是真狂，抵触三公傲帝王。
不怕旧交嗔僭越，唤他侯霸作君房。','',''),('quantangshi-37436','北齐','彥謙','quantangshi','','卷38','草草招提强据鞍，周师乘胜莫回看。
背城肯战知虚实，争奈人前忍笑难。','',''),('quantangshi-37437','楚世家','彥謙','quantangshi','','卷38','偏信由来惑是非，一言邪佞脱危机。
张仪重入怀王手，驷马安车却放归。','',''),('quantangshi-37438','骊山道中','彥謙','quantangshi','','卷38','月殿真妃下彩烟，渔阳追虏及汤泉。
君王指点新丰树，几不亲留七宝鞭。','',''),('quantangshi-37439','韦曲','彥謙','quantangshi','','卷38','欲写愁肠愧不才，多情练漉已低摧。
穷郊二月初离别，独傍寒村嗅野梅。','',''),('quantangshi-37440','黄子陂荷花','彥謙','quantangshi','','卷38','十顷狂风撼麴尘，缘堤照水露红新。
世间花气皆愁绝，恰是莲香更恼人。','',''),('quantangshi-37441','野行','彥謙','quantangshi','','卷38','蝶恋晚花终不去，鸥逢春水固难飞。
野人心地都无着，伴蝶随鸥亦不归。','',''),('quantangshi-37442','兴元沈氏庄','彥謙','quantangshi','','卷38','清浅萦纡一水间，竹冈藤树小跻攀。
露沾荒草行人过，月上高林宿鸟还。
江遶武侯筹笔地，雨昏张载勒铭山。
异乡一笑因酣醉，忘却愁来鬓发斑。','',''),('quantangshi-37443','乱后经表兄琼华观旧居','彥謙','quantangshi','','卷38','一去仙居似转蓬，再经花谢倚春丛。
醉中篇什金声在，别后音书锦字空。
长忆映碑逢若士，未曾携杖逐壶公。
东风狼籍苔侵径，蕙草香销杏带红。','',''),('quantangshi-37444','秋霁夜吟寄友人','彥謙','quantangshi','','卷38','槐柳萧疎溽暑收，金商频伏火西流。
尘衣岁晚缘身贱，雨簟更深满背秋。
前事悲凉何足道，远书慵懒未能修。
惟思待月高梧下，更就东牀访惠休。','',''),('quantangshi-37445','贺李昌时禁苑新命','彥謙','quantangshi','','卷38','玉简金文直上清，禁垣丹地闭严扃。
黄扉议政参元化，紫殿称觞拂寿星。
万户千门迷步武，非烟非雾隔仪形。
尘中旧侣无音信，知道辽东鹤姓丁。','',''),('quantangshi-37446','寄蒋二十四','彥謙','quantangshi','','卷38','鸟啭蜂飞日渐长，旅人情味悔思量。
禅门澹薄无心地，世事生疎欲面墙。
二月云烟迷柳色，九衢风土带花香。
大知高士禁愁寂，试倚阑干莫断肠。','',''),('quantangshi-37447','寄怀','彥謙','quantangshi','','卷38','有客伤春复怨离，夕阳亭畔草青时。
泪从红蜡无由制，肠比朱弦恐更危。
梅向好风惟是笑，柳因微雨不胜垂。
双溪未去饶归梦，夜夜孤眠枕独欹。','',''),('quantangshi-37448','送樊琯司业归朝','彥謙','quantangshi','','卷38','近者苏司业，文雄道最光。
夫君居太学，妙誉继中行。
汲郡陵初发，汾阴箧久亡。
寂寥方倚席，容易忽升堂。
去日应悬榻，来时定裂裳。
惬心频拾芥，应手屡穿杨。
辩急如无敌，飞腾固自强。
论心期舌在，问事畏头长。
驷马终题柱，诸生悉面墙。
啖螯讥尔雅，卖饼诉公羊。
未见泥函谷，俄惊火建章。
烟尘昏象魏，行在隔巴梁。
红粟填郿坞，青袍过寿阳。
翦茅行殿湿，伐栢旧陵香。
黉室青衿尽，渠门火斾扬。
云飞同去国，星散各殊方。
贱子悲穷辙，当年亦擅场。
齑辛寻幼妇，醴酒忆先生。
圣域探姬孔，皇风乐禹汤。
畏诛轻李喜，言命小臧仓。
折树休盘槊，沈钩且钓璜。
鸿都问词客，他日莫相忘。','',''),('quantangshi-37449','奉使岐下闻唐弘夫行军为贼所擒伤而有作','彥謙','quantangshi','','卷38','报国捐躯实壮夫，楚囚垂欲复神都。
云台画像皆何者，青史书名或不孤。
散卒半随袁校尉，寡妻休问辟司徒。
闻君败绩无归计，气激星辰坐向隅。','',''),('quantangshi-37450','咸通中始闻禇河南归葬阳翟是岁上平徐方大肆庆赏又诏八品锡其裔孙追叙风概因成二十韵','彥謙','quantangshi','','卷38','册府藏余烈，皇纲正本朝。
不听还笏谏，几覆缀旒祧。
咫尺言终直，怆惶道已消。
泪心传位日，挥涕授遗朝。
飞燕潜来赵，黄龙岂见谯。
既迷秦帝鹿，难问贾生雕。
穆卜缄縢秘，金根辙迹遥。
北军那夺印，东海漫难桥。
罗织黄门讼，笙簧白骨销。
炎方无信息，丹旐竟沦漂。
邂逅江鱼食，凄凉楚客招。
文忠徒諡议，子卯但箫韶。
未见公侯复，寻伤嗣续凋。
流年随水逝，高谊薄层霄。
柱石林公远，缣缃故国饶。
奇踪天骥活，遗轴锦鸾翘。
近者淮夷戮，前年归马调。
始闻移北葬，兼议荫山苗。
圣泽覃将溥，贞魂喜定飘。
异时穷巷客，怀古漫成谣。','',''),('quantangshi-37451','岐王宅','彥謙','quantangshi','','卷38','朱邸平台隔禁闱，贵游陈迹尚依稀。
云低雍畤祈年去，雨细长杨纵猎归。
申白宾朋传道义，应刘文彩寄音徽。
承平旧物惟君尽，犹写雕鞍伴六飞。','',''),('quantangshi-37452','东韦曲野思','彥謙','quantangshi','','卷38','淡雾轻云匝四垂，绿塘秋望独颦眉。
野莲随水无人见，寒鹭窥鱼共影知。
九陌要津劳目击，五湖闲梦诱心期。
孤灯夜夜愁欹枕，一觉沧洲似昔时。','',''),('quantangshi-37453','上巳','彥謙','quantangshi','','卷38','上巳接寒食，莺花寥落晨。
微微泼火雨，草草踏青人。
凉似三秋景，清无九陌尘。
与余同病者，对此合伤神。','',''),('quantangshi-37454','移莎','彥謙','quantangshi','','卷38','移从杜城曲，置在小斋东。
正是高秋里，仍兼细雨中。
结根方迸竹，疎荫托高桐。
苒苒齐芳草，飘飘笑断蓬。
片时留静者，一夜响鸣蛩。
野露通宵滴，溪烟尽日蒙。
试才卑庾薤，求味笑周菘。
只此霜栽好，他时赠伯翁。','',''),('quantangshi-37455','西明寺威公盆池新稻','彥謙','quantangshi','','卷38','为笑江南种稻时，露蝉鸣后雨霏霏。
莲盆积润分畦小，藻井垂阴擢秀稀。
得地又生金象界，结根仍对水田衣。
支公尚有三吴思，更使幽人忆钓矶。','',''),('quantangshi-37456','红叶','彥謙','quantangshi','','卷38','无处不飘扬，高楼临道旁。
素娥前夕月，青女夜来霜。
宿雨随时润，秋晴着物光。
幽怀长若此，病眼更相妨。
蜀纸裁深色，燕脂落靓妆。
低丛侵小阁，倒影入回塘。
谢朓留霞绮，甘宁弃锦张。
何人休远道，是处有斜阳。
薜荔垂书幌，梧桐坠井牀。
晚风生旅馆，寒籁近僧房。
桂绿明淮甸，枫丹照楚乡。
雁疎临鄠杜，蝉急傍潇湘。
树异桓宣武，园非顾辟疆。
茂陵愁卧客，不自保危肠。','',''),('quantangshi-37457','鸂鶒','彥謙','quantangshi','','卷38','一宿南塘烟雨时，好风摇动绿波微。
惊离晓岸冲花去，暖下春汀照影飞。
华屋拈弦弹鼓舞，绮窗含笔澹毛衣。
画屏见后长回首，争得雕笼莫放归。','',''),('quantangshi-37458','萤','彥謙','quantangshi','','卷38','日下芜城莽苍中，湿萤撩乱起衰丛。
寒烟陈后长门闭，夜雨隋家旧苑空。
星散欲陵前槛月，影低如试北窗风。
羇人此夕方愁绪，心似寒灰首似蓬。','',''),('quantangshi-37459','夜蝉','彥謙','quantangshi','','卷38','翠竹高梧夹后溪，劲风危露雨凄凄。
那知北牖残灯暗，又送西楼片月低。
清夜更长应未已，远烟寻断莫频嘶。
羇人此夕如三岁，不整寒衾待曙鸡。','',''),('quantangshi-37460','七夕','彥謙','quantangshi','','卷38','露白风清夜向晨，小星垂佩月埋轮。
绛河浪浅休相隔，沧海波深尚作尘。
天外凤皇何寂寞，世间乌鹊漫辛勤。
倚阑殿北斜楼上，多少通宵不寐人。','',''),('quantangshi-37461','中秋夜玩月','彥謙','quantangshi','','卷38','一夜高楼万景奇，碧天无际水无涯。
只留皎月当层汉，并送浮云出四维。
雾静不容玄豹隐，冰生惟恐夏虫疑。
坐来离思忧将晓，争得嫦娥仔细知。','',''),('quantangshi-37462','八月十六日夜月','彥謙','quantangshi','','卷38','断肠佳赏固难期，昨夜销魂更不疑。
丹桂影空蟾有露，绿槐阴在鹊无枝。
赖将吟咏聊惆怅，早是疎顽耐别离。
堪恨贾生曾恸哭，不缘清景为忧时。','',''),('quantangshi-37463','送韦向之睦州谒使君','彥謙','quantangshi','','卷38','才子南游多远情，闲舟荡漾任春行。
新安江上长如此，何似新安太守清。','',''),('quantangshi-37464','春残','彥謙','quantangshi','','卷38','景为春时短，愁随别夜长。
暂碁宁号隐，轻醉不成乡。
风雨曾通夕，莓苔有众芳。
落花如便去，楼上即河梁。','',''),('quantangshi-37465','玫瑰','彥謙','quantangshi','','卷38','麝炷腾清燎，鲛纱覆绿蒙。
宫妆临晓日，锦段落东风。
无力春烟里，多愁暮雨中。
不知何事意，深浅两般红。','',''),('quantangshi-37466','牡丹','彥謙','quantangshi','','卷38','真宰多情巧思新，固将能事送残春。
为云为雨徒虚语，倾国倾城不在人。
开日绮霞应失色，落时青帝合伤神。
嫦娥婺女曾相送，留下鵶黄作蘂尘。','',''),('quantangshi-37467','秋晚高楼','彥謙','quantangshi','','卷38','松拂疎窗竹映阑，素琴幽怨不成弹。
清宵霁极云离岫，紫禁风高露满盘。
晚蝶飘零惊宿雨，暮鸦淩乱报秋寒。
高楼瞪目归鸿远，如信嵇康欲画难。','',''),('quantangshi-37468','离鸾','彥謙','quantangshi','','卷38','闻道离鸾思故乡，也知情愿嫁王昌。
尘埃一别杨朱路，风月三年宋玉墙。
下疾不成双点泪，断多难到九回肠。
庭前佳树名栀子，试结同心寄谢娘。','',''),('quantangshi-37469','柳','彥謙','quantangshi','','卷38','春思春愁一万枝，远村遥岸寄相思。
西园有雨和苔长，南内无人拂槛垂。
游客寂寥缄远恨，暮莺啼呌惜芳时。
晚来飞絮如霜鬓，恐为多情管别离。','',''),('quantangshi-37470','春阴','彥謙','quantangshi','','卷38','一寸回肠百虑侵，旅愁危涕两争禁。
天涯已有销魂别，楼上宁无拥鼻吟。
感事不关河里笛，伤心应倍雍门琴。
春云更觉愁于我，闲盖低村作暝阴。','',''),('quantangshi-37471','春深独行马上有作','彥謙','quantangshi','','卷38','日烈风高野草香，百花狼籍柳披猖。
连天瑞霭千门远，夹道新阴九陌长。
众饮不欢逃席酒，独行无味放游缰。
年来与问闲游者，若个伤春向路旁。','',''),('quantangshi-37472','春雨','彥謙','quantangshi','','卷38','绮陌夜来雨，春楼寒望迷。
远客迎燕戏，乱响隔莺啼。
有恨开兰室，无言对李蹊。
花欹浑拂槛，柳重欲垂堤。
灯檠昏鱼目，薰炉咽麝脐。
别轻天北鹤，梦怯汝南鸡。
入户侵罗幌，捎檐润绣题。
新丰树已失，长信草初齐。
乱蝶寒犹舞，惊乌暝不栖。
庾郎盘马地，却怕有春泥。','',''),('quantangshi-37473','汉代','彥謙','quantangshi','','卷38','汉代金为屋，吴宫绮作寮。
艳词传静婉，新曲定妖娆。
箭响犹残梦，签声报早朝。
鲜明临晓日，回转度春宵。
半袖笼清镜，前丝压翠翘。
静多如有待，闲极似无憀。
梓泽花犹满，灵和柳未凋。
障昏巫峡雨，屏掩浙江潮。
未信潘名岳，应疑史姓萧。
漏因歌暂断，灯为雨频挑。
饮酒阑三雅，投壶赛百娇。
钿蝉新翅重，金鸭旧香焦。
水净疑澄练，霞孤欲建标。
别随秦柱促，愁为蜀弦么。
玄[晏]难瘳痹，临邛但发痟。
联诗征弱絮，思友咏甘蕉。
王氏怜诸谢，周郎定小乔。
黼帏翘彩雉，波扇画文鳐。
荇密妨垂钓，荷欹欲度桥。
不因衣带水，谁觉路迢迢。','',''),('quantangshi-37474','牡丹','彥謙','quantangshi','','卷38','青帝于君事分偏，穠堆浮艳倚朱门。
虽然占得笙歌地，将甚酬他雨露恩。','',''),('quantangshi-37475','湘妃庙','彥謙','quantangshi','','卷38','刘表荒碑断水滨，庙前幽草闭残春。
已将愁泪留斑竹，又感悲风入白苹。
八族未来谁北拱，四凶犹在莫南巡。
九峰相似堪疑处，望见苍梧不见人。','',''),('quantangshi-37476','句','彥謙','quantangshi','','卷38','独来成怅望，不去泥栏干。','',''),('quantangshi-37477','题甘露寺','周朴','quantangshi','','卷38','层阁叠危壁，瑞因千古名。
几连扬子路，独倚润州城。
云近衔江色，雕高背磬声。
僧居上方久，端坐见营营。','',''),('quantangshi-37478','题玄公院','周朴','quantangshi','','卷38','院深尘自外，如佛值玄公。
常迹或非次，志门因得中。
衣巾离暑气，牀榻向凉风。
是事不逾分，秪应明德同。','',''),('quantangshi-37479','福州东禅寺','周朴','quantangshi','','卷38','瓯闽在郊外，师院号东禅。
物得居来正，人经论后贤。
瓟槽柳塞马，盖地月支綖。
鹳鹊尚巢顶，谁堪举世传。','',''),('quantangshi-37480','赠大沩和尚','周朴','quantangshi','','卷38','大沩清复深，万象影沈沈。
有客衣多毳，空门偈胜金。
王侯皆作礼，陆子只来吟。
我问师心处，师言无处心。','',''),('quantangshi-37481','秋夜不寐寄崔温进士','周朴','quantangshi','','卷38','愁多难得寐，展转读书牀。
不是旅人病，岂知秋夜长。
归乡凭远梦，无梦更思乡。
枕上移窗月，分明是泪光。','',''),('quantangshi-37482','春中途中寄南巴崔使君','周朴','quantangshi','','卷38','旅人游汲汲，春气又融融。
农事蛙声里，归程草色中。
独慙出谷雨，未变暖天风。
子玉和予去，应怜恨不穷。','',''),('quantangshi-37483','寄处士方干','周朴','quantangshi','','卷38','桐庐江水闲，终日对柴关。
因想别离处，不知多少山。
钓舟春岸泊，庭树晓莺还。
莫便求栖隐，桂枝堪恨颜。','',''),('quantangshi-37484','寄塞北张符','周朴','quantangshi','','卷38','陇树塞风吹，辽城角几枝。
霜凝无暂歇，君貌莫应衰。
万里平沙际，一行边雁移。
那堪朔烟起，家信正相离。','',''),('quantangshi-37485','次梧州却寄永州使君','周朴','quantangshi','','卷38','随风身不定，今夜在苍梧。
客泪有时有，猨声无处无。
潮添瘴海阔，烟拂粤山孤。
却忆零陵住，吟诗半玉壶。','',''),('quantangshi-37486','赠念经僧','周朴','quantangshi','','卷38','庵前古折碑，夜静念经时。
月皎海霞散，露浓山草垂。
鬼闻抛故冢，禽听离寒枝。
想得天花坠，馨香拂白眉。','',''),('quantangshi-37487','董岭水','周朴','quantangshi','','卷38','湖州安吉县，门与白云齐。
禹力不到处，河声流向西。
去衙山色远，近水月光低。
中有高人在，沙中曳杖藜。','',''),('quantangshi-37488','早春','周朴','quantangshi','','卷38','良夜岁应足，严风为变春。
遍回寒作暖，通改旧成新。
秀树因馨雨，融冰雨泛苹。
韶光不偏党，积渐煦疲民。','',''),('quantangshi-37489','秋深','周朴','quantangshi','','卷38','柳色尚沈沈，风吹秋更深。
山河空远道，乡国自鸣砧。
巷有千家月，人无万里心。
长城哭崩后，寂绝至如今。','',''),('quantangshi-37490','赠双峰山和尚','周朴','quantangshi','','卷38','峩峩双髻山，瀑布泻云间。
尘世自疑水，禅门长去关。
茯神松不异，藏宝石俱闲。
向此师清业，如何方可攀。','',''),('quantangshi-37491','赠无了禅师','周朴','quantangshi','','卷38','不学世所惜，是何无了公。
灵匡虚院外，虎迹乱山中。
昼夜必连去，古今争敢同。
禅情岂堪问，问答更无穷。','',''),('quantangshi-37492','王霸坛','周朴','quantangshi','','卷38','王君上升处，信首古居前。
皂树即须朽，白龟应亦全。
云间犹一日，尘里已千年。
碧色坛如黛，时人谁可仙。','',''),('quantangshi-37493','送梁道士','周朴','quantangshi','','卷38','旧居桐栢观，归去爱安闲。
倒树造新屋，化人修古坛。
晚花霜后落，山雨夜深寒。
应有同溪客，相寻学炼丹。','',''),('quantangshi-37494','边思','周朴','quantangshi','','卷38','年高来远戍，白首罢干戎。
夜色蓟门火，秋声边塞风。
碛浮悲老马，月满引新弓。
百战阴山去，唯添上将雄。','',''),('quantangshi-37495','哭陈庾','周朴','quantangshi','','卷38','系马向山立，一杯聊奠君。
野烟孤客路，寒草故人坟。
琴韵归流水，诗情寄白云。
日斜休哭后，松韵不堪闻。','',''),('quantangshi-37496','宿玉泉寺','周朴','quantangshi','','卷38','野寺度残夏，空房欲暮时。
夜听猨不睡，秋思客先知。
竹迥烟生薄，山高月上迟。
又登尘路去，难与老僧期。','',''),('quantangshi-37497','题赤城中岩寺','周朴','quantangshi','','卷38','浮世师休话，晋时灯照岩。
禽飞穿静户，藤结入高杉。
存没诗千首，废兴经数函。
谁知将俗耳，来此避嚣谗。','',''),('quantangshi-37498','塞上行','周朴','quantangshi','','卷38','秦筑长城在，连云碛气侵。
风吹边草急，角绝塞鸿沈。
世世征人往，年年战骨深。
辽天望乡者，回首尽霑襟。','',''),('quantangshi-37499','玉泉寺','周朴','quantangshi','','卷38','寺还名玉泉，澄水亦遭贤。
物尚犹如此，人争合偶然。
溪流云断外，山峻鸟飞还。
初日长廊下，高僧正坐禅。','',''),('quantangshi-37500','春宫怨','周朴','quantangshi','','卷38','早被婵娟误，欲妆临镜慵。
承恩不在貌，教妾若为容。
风暖鸟声碎，日高花影重。
年年越溪女，相忆采芙蓉。','',''),('quantangshi-37501','宿刘温书斋','周朴','quantangshi','','卷38','不掩盈窗日，天然格调高。
凉风移蟋蟀，落叶在离骚。
回笔挑灯烬，悬图见海潮。
因论三国志，空载几英豪。','',''),('quantangshi-37502','登福州南涧寺','周朴','quantangshi','','卷38','万里重山遶福州，南横一道见溪流。
天边飞鸟东西没，尘里行人早晚休。
晓日青山当大海，连云古堑对高楼。
那堪望断他乡目，只此萧条自白头。','',''),('quantangshi-37503','望中怀古','周朴','quantangshi','','卷38','齐心楼上望浮云，万古千秋空姓名。
尧水永销天际去，姬风一变世间平。
高踪尽共烟霞在，大道长将日月明。
从此安然寰海内，后来无复谩相倾。','',''),('quantangshi-37504','升山寺','周朴','quantangshi','','卷38','升山自古道飞来，此是神功不可猜。
气色虽然离禹穴，峰峦犹自接天台。
岩边折树泉冲落，顶上浮云日照开。
南望闽城尘世界，千秋万古卷尘埃。','',''),('quantangshi-37505','哭李端','周朴','quantangshi','','卷38','三年翦拂感知音，哭向青山永夜心。
竹在晓烟孤凤去，剑荒秋水一龙沈。
新坟日落松声小，旧色春残草色深。
不及此时亲执绋，石门遥想泪霑襟。','',''),('quantangshi-37506','福州神光寺塔','周朴','quantangshi','','卷38','良匠用材为塔了，神光寺更得高名。
风云会处千寻出，日月中时八面明。
海水旋流倭国野，天文方戴福州城。
相轮顶上望浮世，尘里人心应总平。','',''),('quantangshi-37507','福州开元寺塔','周朴','quantangshi','','卷38','开元寺里七重塔，遥对方山影拟齐。
杂俗人看离世界，孤高僧上觉天低。
唯堪片片紫霞映，不与蒙蒙白雾迷。
心若无私罗汉在，参差免向日虹西。','',''),('quantangshi-37508','春日秦国怀古','周朴','quantangshi','','卷38','荒郊一望欲消魂，泾水萦纡傍远村。
牛马放多春草尽，原田耕破古碑存。
云和积雪苍山晚，烟伴残阳绿树昏。
数里黄沙行客路，不堪回首思秦原。','',''),('quantangshi-37509','春日游北园寄韩侍郎','周朴','quantangshi','','卷38','灼灼春园晚色分，露珠千点映寒云。
多情舞蝶穿花去，解语流莺隔水闻。
冷酒杯中宜泛滟，暖风林下自氛氲。
仙桃不肯全开拆，应借余芳待使君。','',''),('quantangshi-37510','喜贺拔先辈衡阳除正字','周朴','quantangshi','','卷38','黄纸晴空坠一缄，圣朝恩泽洗冤谗。
李膺门客为闲客，梅福官衔改旧衔。
名自石渠书典籍，香从芸阁着衣衫。
寰中不用忧天旱，霖雨看看属傅岩。','',''),('quantangshi-37511','客州赁居寄萧郎中','周朴','quantangshi','','卷38','松店茅轩向水开，东头舍赁一裴徊。
窗吟苦为秋江静，枕梦惊因晓角催。
邻舍见愁赊酒与，主人知去索钱来。
眼看白笔为霖雨，肯使红鳞便曝腮。','',''),('quantangshi-37512','赠李裕先辈','周朴','quantangshi','','卷38','晓擎弓箭入初场，一发曾穿百步杨。
仙籍旧题前进士，圣朝新奏校书郎。
马疑金马门前马，香认芸香阁上香。
闲伴李膺红烛下，慢吟丝竹浅飞觞。','',''),('quantangshi-37513','桐栢观','周朴','quantangshi','','卷38','东南一境清心目，有此千峰插翠微。
人在下方冲月上，鹤从高处破烟飞。
岩深水落寒侵骨，门静花开色照衣。
欲识蓬莱今便是，更于何处学忘机。','',''),('quantangshi-37514','塞上','周朴','quantangshi','','卷38','受降城必破，回落陇头移。
蕃道北海北，谋生今始知。','',''),('quantangshi-37515','塞上曲','周朴','quantangshi','','卷38','一阵风来一阵砂，有人行处没人家。
黄河九曲冰先合，紫塞三春不见花。','',''),('quantangshi-37516','塞下曲','周朴','quantangshi','','卷38','石国胡儿向碛东，爱吹横笛引秋风。
夜来云雨皆飞尽，月照平沙万里空。','',''),('quantangshi-37517','咏猨','周朴','quantangshi','','卷38','生在巫山更向西，不知何事到巴溪。
中宵为忆秋云伴，遥隔朱门向月啼。','',''),('quantangshi-37518','桃花','周朴','quantangshi','','卷38','桃花春色暖先开，明媚谁人不看来。
可惜狂风吹落后，殷红片片点莓苔。','',''),('quantangshi-37519','薛老峰','周朴','quantangshi','','卷38','薛老峰头三个字，须知此与石齐生。
直叫截断苍苔色，浮世人侪眼始明。','',''),('quantangshi-37520','吊李羣玉','周朴','quantangshi','','卷38','羣玉诗名冠李唐，投诗换得校书郎。
吟魂醉魄知何处，空有幽兰隔岸香。','',''),('quantangshi-37521','无等巌','周朴','quantangshi','','卷38','建造上方藤影里，高僧往往似天台。
不知名树檐前长，曾问道人岩下来。','',''),('quantangshi-37522','句','周朴','quantangshi','','卷38','古陵寒雨集，高鸟夕阳明。
高情千里外，长啸一声初。
月离山一丈，风吹花数苞。
晓来山鸟闹，雨过杏花稀。
曲渚回湾锁钓舟，平潮晚影沈清底。
远岳危栏等翠尖。
白日才离沧海底，清光先照户窗前。
连云天堑有山色，极目海门无雁行。
可怜黄雀衔将去，从此庄周梦不成。
禅是大沩诗是朴，大唐天子只三人。','',''),('quantangshi-37523','感兴','鄭谷','quantangshi','','卷38','禾黍不阳艳，竞栽桃李春。
翻令力耕者，半作卖花人。','',''),('quantangshi-37524','望湘亭','鄭谷','quantangshi','','卷38','湘水似伊水，湘人非故人。
登临独无语，风柳自摇春。','',''),('quantangshi-37525','采桑','鄭谷','quantangshi','','卷38','晓陌携笼去，桑林路隔淮。
何如鬬百草，赌取凤皇钗。','',''),('quantangshi-37526','闷题','鄭谷','quantangshi','','卷38','落第春相困，无心惜落花。
荆山归不得，归得亦无家。','',''),('quantangshi-37527','中台五题 乳毛松','鄭谷','quantangshi','','卷38','松格一何高，何人号乳毛。
霜天寓直夜，愧尔伴闲曹。','',''),('quantangshi-37528','中台五题 樗里子墓','鄭谷','quantangshi','','卷38','贤人骨已销，墓树几荣凋。
正直魂如在，斋心愿一招。','',''),('quantangshi-37529','中台五题 牡丹','鄭谷','quantangshi','','卷38','乱前看不足，乱后眼偏明。
却得蓬蒿力，遮藏见太平。','',''),('quantangshi-37530','中台五题 玉蕊','鄭谷','quantangshi','','卷38','唐昌树已荒，天意眷文昌。
晓入微风起，春时雪满墙。','',''),('quantangshi-37531','中台五题 石柱','鄭谷','quantangshi','','卷38','暴乱免遗折，森罗贤达名。
末郎何所取，叨继外门荣。','',''),('quantangshi-37532','别同志','鄭谷','quantangshi','','卷38','所立共寒苦，平生同与游。
相看临远水，独自上孤舟。
天澹沧浪晚，风悲兰杜秋。
前程吟此景，为子上高楼。','',''),('quantangshi-37533','送进士卢棨东归','鄭谷','quantangshi','','卷38','灞岸草萋萋，离觞我独携。
流年俱老大，失意又东西。
晓楚山云满，春吴水树低。
到家梅雨歇，犹有子规啼。','',''),('quantangshi-37534','从叔郎中諴辍自秋曹分符安陆属羣盗倡炽流毒江壖竟以援兵不来城池失守例削今任却叙省衔退居荆汉之间颇得琴尊之趣因有寄献','鄭谷','quantangshi','','卷38','华省称前任，何慙削一麾。
沧洲失孤垒，白发出重围。
苦节翻多难，空山自喜归。
悠悠清汉上，渔者日相依。','',''),('quantangshi-37535','送徐涣端公南归','鄭谷','quantangshi','','卷38','青衿离白社，朱绶始言归。
此去应多羡，初心尽不违。
江帆和日落，越鸟近乡飞。
一路春风里，杨花雪满衣。','',''),('quantangshi-37536','送祠部曹郎中邺出守洋州','鄭谷','quantangshi','','卷38','为儒欣出守，上路亦戎装。
旧制诗多讽，分忧俗必康。
开怀江稻熟，寄信露橙香。
郡阁清吟夜，寒星识望郎。','',''),('quantangshi-37537','送进士许彬','鄭谷','quantangshi','','卷38','泗上未休兵，壶关事可惊。
流年催我老，远道念君行。
残雪临晴水，寒梅发故城。
何当食新稻，岁稔又时平。','',''),('quantangshi-37538','次韵和王驾校书结绶见寄之什','鄭谷','quantangshi','','卷38','直应归谏署，方肯别山村。
勤苦常同业，孤单共感恩。
醉披仙鹤氅，吟扣野僧门。
梦见君高趣，天凉自灌园。','',''),('quantangshi-37539','祕阁伴直','鄭谷','quantangshi','','卷38','祕阁锁书深，墙南列晚岑。
吏人同野鹿，庭木似山林。
浅井寒芜入，回廊叠藓侵。
闲看薛稷鹤，共起五湖心。','',''),('quantangshi-37540','送太学颜明经及第东归','鄭谷','quantangshi','','卷38','平楚干戈后，田园失耦耕。
艰难登一第，离乱省诸兄。
树没春江涨，人繁野渡晴。
闲来思学馆，犹梦雪窗明。','',''),('quantangshi-37541','送进士赵能卿下第南归','鄭谷','quantangshi','','卷38','不归何慰亲，归去旧风尘。
洒泪慙关吏，无言对越人。
远帆花月夜，微岸水天春。
莫便随渔钓，平生已苦辛。','',''),('quantangshi-37542','送人游边','鄭谷','quantangshi','','卷38','春亦怯边游，此行风正秋。
别离逢雨夜，道路向云州。
碛树藏城近，沙河漾日流。
将军方破虏，莫惜献良筹。','',''),('quantangshi-37543','送人之九江谒郡侯苗员外绅','鄭谷','quantangshi','','卷38','泽国寻知己，南浮不偶游。
湓城分楚塞，庐岳对江州。
晓饭临孤屿，春帆入乱流。
双旌相望处，月白庾公楼。','',''),('quantangshi-37544','送许棠先辈之官泾县','鄭谷','quantangshi','','卷38','白头新作尉，县在故山中。
高第能卑宦，前贤尚此风。
芜湖春荡漾，梅雨昼溟蒙。
佐理人安后，篇章莫废功。','',''),('quantangshi-37545','送司封从叔员外徼赴华州裴尚书均辟','鄭谷','quantangshi','','卷38','如何抛锦帐，莲府对莲峰。
旧有云霞约，暂留鵷鹭踪。
敷溪秋雪岸，树谷夕阳钟。
尽入新吟境，归朝兴莫慵。','',''),('quantangshi-37546','送京参翁先辈归闽中','鄭谷','quantangshi','','卷38','解印东归去，人情此际多。
名高五七字，道胜两重科。
宿馆明寒烧，吟船兀夜波。
家山春更好，越鸟在庭柯。','',''),('quantangshi-37547','赠别','鄭谷','quantangshi','','卷38','南游曾共游，相别倍相留。
行色回灯晓，离声满竹秋。
稳眠彭蠡浪，好醉岳阳楼。
明日逢佳景，为君成白头。','',''),('quantangshi-37548','南游','鄭谷','quantangshi','','卷38','凄凉怀古意，湘浦吊灵均。
故国经新岁，扁舟寄病身。
山城多晓瘴，泽国少晴春。
渐远无相识，青梅独向人。','',''),('quantangshi-37549','巴賨旅寓寄朝中从叔','鄭谷','quantangshi','','卷38','惊秋思浩然，信美向巴天。
独倚临江树，初闻落日蝉。
哀荣悲往事，漂泊念多年。
未便甘休去，吾宗尽见怜。','',''),('quantangshi-37550','寄司勋张员外学士','鄭谷','quantangshi','','卷38','平昔偏知我，司勋张外郎。
昨来闻俶扰，忧甚欲颠狂。
烟暝搔愁鬓，春阴赖酒乡。
江楼倚不得，横笛数声长。','',''),('quantangshi-37551','寄边上从事','鄭谷','quantangshi','','卷38','男儿怀壮节，何不事嫖姚？
高叠观诸寨，全师护大朝。
浅山寒放马，乱火夜防苗。
下第春愁甚，劳君远见招。','',''),('quantangshi-37552','寄左省韦起居序','鄭谷','quantangshi','','卷38','风神何蕴藉，张绪正当年。
端简炉香里，濡毫洞案边。
饰装无雨备，着述减春眠。
旦夕应弥入，银台晓候宣。','',''),('quantangshi-37553','寄赠蓝田韦少府先辈','鄭谷','quantangshi','','卷38','王畿第一县，县尉是词人。
馆殿非初意，图书是旧贫。
斫冰泉窦响，赛雪庙松春。
自此升通籍，清华日近身。','',''),('quantangshi-37554','寄怀元秀上人','鄭谷','quantangshi','','卷38','悠悠干禄利，草草废渔樵。
身世堪惆怅，风骚颇寂寥。
高秋期野步，积雨放趋朝。
得句如相忆，莎斋且见招。','',''),('quantangshi-37555','赠圆昉公','鄭谷','quantangshi','','卷38','天阶让紫衣，冷格鹤犹卑。
道胜嫌名出，身闲觉老迟。
晚香延宿火，寒磬度高枝。
长说长松寺，他年与我期。','',''),('quantangshi-37556','寄题方干处士','鄭谷','quantangshi','','卷38','山雪照湖水，漾舟湖畔归。
松篁调远籁，台榭发清辉。
野岫分闲径，渔家并掩扉。
暮年诗力在，新句更幽微。','',''),('quantangshi-37557','寄献湖州从叔员外','鄭谷','quantangshi','','卷38','顾渚山边郡，溪将罨画通。
远看城郭里，全在水云中。
西阁归何晚，东吴兴未穷。
茶香紫笋露，洲迥白苹风。
歌缓眉低翠，杯明蜡翦红。
政成寻往事，辍棹问渔翁。','',''),('quantangshi-37558','访姨兄王斌渭口别墅','鄭谷','quantangshi','','卷38','枯桑河上村，寥落旧田园。
少小曾来此，悲凉不可言。
访邻多指冢，问路半移原。
久歉家僮散，初晴野荠繁。
客帆悬极浦，渔网晒危轩。
苦涩诗盈箧，荒唐酒满尊。
高枝霜果在，幽渚暝禽喧。
远霭笼樵响，微烟起烧痕。
哀荣孤族分，感激外兄恩。
三宿忘归去，圭峰恰对门。','',''),('quantangshi-37559','放朝偶作','鄭谷','quantangshi','','卷38','寒极放朝天，欣闻半夜宣。
时安逢密雪，日晏得高眠。
拥褐同休假，吟诗贺有年。
坐来幽兴在，松亚小窗前。','',''),('quantangshi-37560','顺动后蓝田偶作','鄭谷','quantangshi','','卷38','小谏升中谏，三年侍玉除。
且言无所补，浩叹欲何如。
宫阙飞灰烬，嫔嫱落里闾。
蓝峰秋更碧，霑洒望銮舆。','',''),('quantangshi-37561','府中寓止寄赵大谏','鄭谷','quantangshi','','卷38','老作含香客，贫无僦舍钱。
神州容寄迹，大尹是同年。
密迩都忘倦，乖慵益见怜。
雪风花月好，中夜便招延。','',''),('quantangshi-37562','峡中寓止二首 一','鄭谷','quantangshi','','卷38','荆州未解围，小县结茅茨。
强对官人笑，甘为野鹤欺。
江春铺网阔，市晚鬻蔬迟。
子美犹如此，翻然不敢悲。','',''),('quantangshi-37563','峡中寓止二首 二','鄭谷','quantangshi','','卷38','传闻殊不定，銮辂几时还。
俗易无常性，江清见老颜。
夜船归草市，春步上茶山。
寨将来相问，儿童竞启关。','',''),('quantangshi-37564','颜惠詹事即孤侄舅氏谪官黔巫舟中相遇怆然有寄','鄭谷','quantangshi','','卷38','犹子在天末，念渠怀渭阳。
巴山偶会遇，江浦共悲凉。
谪宦君何远，穷游我自强。
瘴村三月暮，雨熟野梅黄。','',''),('quantangshi-37565','访题进士孙秦延福南街居','鄭谷','quantangshi','','卷38','多病久离索，相寻聊解颜。
短墙通御水，疎树出南山。
岁月何难老，园林未得还。
无门共荣达，孤坐却如闲。','',''),('quantangshi-37566','访题进士张乔延兴门外所居','鄭谷','quantangshi','','卷38','平生苦节同，旦夕会原东。
掩卷斜阳里，看山落木中。
星霜今欲老，江海业全空。
近日文场内，因君起古风。','',''),('quantangshi-37567','寄南浦谪官','鄭谷','quantangshi','','卷38','多才翻得罪，天末抱穷忧。
白首为迁客，青山绕万州。
醉敧梅障晓，歌厌竹枝秋。
望阙怀乡泪，荆江水共流。','',''),('quantangshi-37568','李夷遇侍御久滞水乡因抒寄怀','鄭谷','quantangshi','','卷38','簪豸年何久，悬帆兴甚长。
江流爱吴越，诗格愈齐梁。
竹寺晴吟远，兰洲晚泊香。
高闲徒自任，华省待为郎。','',''),('quantangshi-37569','寄膳部李郎中昌符','鄭谷','quantangshi','','卷38','鄠郊陪野步，早岁偶因诗。
自后吟新句，长愁减旧知。
静灯微落烬，寒砚旋生澌。
夜夜冥搜苦，那能鬓不衰。','',''),('quantangshi-37570','寄前水部贾员外嵩','鄭谷','quantangshi','','卷38','谢病别文昌，仙舟向越乡。
贵为金马客，雅称水曹郎。
白鹭同孤洁，清波共渺茫。
相如词赋外，骚雅趣何长。','',''),('quantangshi-37571','寄棊客','鄭谷','quantangshi','','卷38','松窗楸局稳，相顾思皆凝。
几局赌山果，一先饶海僧。
覆图闻夜雨，下子对秋灯。
何日无羁束，期君向杜陵。','',''),('quantangshi-37572','闻进士许彬罢举归睦州怅然怀寄','鄭谷','quantangshi','','卷38','桐庐归旧庐，垂老复樵渔。
吾子虽言命，乡人嬾读书。
烟舟撑晚浦，雨屐翦春蔬。
异代名方振，哀吟莫废初。','',''),('quantangshi-37573','长安夜坐寄怀湖外嵇处士','鄭谷','quantangshi','','卷38','万里念江海，浩然天地秋。
风高羣木落，夜久数星流。
钟绝分宫漏，萤微隔御沟。
遥思洞庭上，苇露滴渔舟。','',''),('quantangshi-37574','赠文士王雄','鄭谷','quantangshi','','卷38','知己竟何人，哀君尚苦辛。
图书长在手，文学老于身。
公道天难废，贞姿世任嗔。
小斋松菊静，愿卜子为邻。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37575','赠富平李宰','鄭谷','quantangshi','','卷38','夫君清且贫，琴鹤最相亲。
简肃诸曹事，安闲一境人。
陵山云里拜，渠路雨中巡。
易得连宵醉，千缸石冻春。','',''),('quantangshi-37576','赠尚颜上人','鄭谷','quantangshi','','卷38','相寻喜可知，放锡便论诗。
酷爱山兼水，唯应我与师。
风雷吟不觉，猨鹤老为期。
近辈推栖白，其如趣向卑。','',''),('quantangshi-37577','赠泗口苗居士','鄭谷','quantangshi','','卷38','岁[晏]乐园林，维摩契道心。
江云寒不散，庭雪夜方深。
酒劝渔人饮，诗怜稚子吟。
四郊多垒日，勉我舍朝簪。','',''),('quantangshi-37578','梁烛处士辞金陵相国杜公归旧山因以寄赠','鄭谷','quantangshi','','卷38','相庭留不得，江野有苔矶。
两浙寻山徧，孤舟载鹤归。
世间书读尽，云外客来稀。
谏署搜贤急，应难惜布衣。','',''),('quantangshi-37579','哭建州李员外频','鄭谷','quantangshi','','卷38','令终归故里，末岁道如初。
旧友谁为志，清风岂易书。
雨坟生野蕨，乡奠钓江鱼。
独夜吟还泣，前年伴直庐。','',''),('quantangshi-37580','哭进士李洞二首 一','鄭谷','quantangshi','','卷38','所惜绝吟声，不悲君不荣。
李端终薄宦，贾岛得高名。
旅葬新坟小，遗孤远俗轻。
犹疑随计晚，昨夜草虫鸣。','',''),('quantangshi-37581','哭进士李洞二首 二','鄭谷','quantangshi','','卷38','自闻东蜀病，唯我独关情。
若近长江死，想君胜在生。
瘴蒸丹旐湿，灯隔素帷清。
冢树僧栽后，新蝉一两声。','',''),('quantangshi-37582','南康郡牧陆肱郎中辟许棠先辈为郡从事因有寄赠','鄭谷','quantangshi','','卷38','末路思前侣，犹为恋故巢。
江山多胜境，宾主是贫交。
饮舫闲依苇，琴堂雅结茅。
夜清僧伴宿，水月在松梢。','',''),('quantangshi-37583','久不得张乔消息','鄭谷','quantangshi','','卷38','天末去程孤，沿淮复向吴。
乱离何处甚，安稳到家无。
树尽云垂野，樯稀月满湖。
伤心绕村落，应少旧耕夫。','',''),('quantangshi-37584','题嵩高隐者居','鄭谷','quantangshi','','卷38','岂易访仙踪，云萝千万重。
他年来卜隐，此景愿相容。
乱水林中路，深山雪里钟。
见君琴酒乐，回首兴何慵。','',''),('quantangshi-37585','赵璘郎中席上赋蝴蝶','鄭谷','quantangshi','','卷38','寻艳复寻香，似闲还似忙。
暖烟沈蕙径，微雨宿花房。
书幌轻随梦，歌楼误采妆。
王孙深属意，绣入舞衣裳。','',''),('quantangshi-37586','贺进士骆用锡登第','鄭谷','quantangshi','','卷38','苦辛垂二纪，擢第却霑裳。
春榜到春晚，一家荣一乡。
题名登塔喜，醵宴为花忙。
好是东归日，高槐蕊半黄。','',''),('quantangshi-37587','兴州东池','鄭谷','quantangshi','','卷38','南连乳郡流，阔碧侵晴楼。
彻底千峰影，无风一片秋。
垂杨拂莲叶，返照媚渔舟。
鉴貌还惆怅，难遮两鬓羞。','',''),('quantangshi-37588','渠江旅思','鄭谷','quantangshi','','卷38','流落复蹉跎，交亲半逝波。
谋生非不切，言命欲如何。
故楚春田废，穷巴瘴雨多。
引人乡泪尽，夜夜竹枝歌。','',''),('quantangshi-37589','登杭州城','鄭谷','quantangshi','','卷38','漠漠江天外，登临返照间。
潮来无别浦，木落见他山。
沙鸟晴飞远，渔人夜唱闲。
岁穷归未得，心逐片帆还。','',''),('quantangshi-37590','曲江','鄭谷','quantangshi','','卷38','细草岸西东，酒旗遥水风。
楼台在烟杪，鸥鹭下沙中。
翠幄晴相接，芳洲夜暂空。
何人赏秋景，兴与此时同。','',''),('quantangshi-37591','沙苑','鄭谷','quantangshi','','卷38','茫茫信马行，不似近都城。
苑吏犹迷路，江人莫问程。
聚来千嶂出，落去一川平。
日暮客心速，愁闻雁数声。','',''),('quantangshi-37592','通川客舍','鄭谷','quantangshi','','卷38','奔走失前计，淹留非本心。
已难消永夜，况复听秋霖。
渐解巴儿语，谁怜越客吟。
黄花徒满手，白发不胜簪。','',''),('quantangshi-37593','潼关道中','鄭谷','quantangshi','','卷38','白道晓霜迷，离灯照马嘶。
秋风满关树，残月隔河鸡。
来往非无倦，穷通岂易齐。
何年归故社，披雨翦春畦。','',''),('quantangshi-37594','终南白鹤观','鄭谷','quantangshi','','卷38','步步景通真，门前众水分。
柽萝诸洞合，钟磬上清闻。
古木千寻雪，寒山万丈云。
终期扫坛级，来事紫阳君。','',''),('quantangshi-37595','题兴善寺寂上人院','鄭谷','quantangshi','','卷38','客来风雨后，院静似荒凉。
罢讲蛩离砌，思山叶满廊。
腊高兴故疾，炉暖发余香。
自说匡庐侧，杉阴半石牀。','',''),('quantangshi-37596','题水部李羽员外招国里居','鄭谷','quantangshi','','卷38','野色入前轩，翛然琴与尊。
画僧依寺壁，栽苇学江村。
自酝花前酒，谁敲雪里门。
不辞朝谒远，唯要近慈恩。','',''),('quantangshi-37597','信美寺岑上人','鄭谷','quantangshi','','卷38','巡礼诸方徧，湘南颇有缘。
焚香老山寺，乞食向江船。
纱碧笼名画，灯寒照净禅。
我来能永日，莲漏滴堦前。','',''),('quantangshi-37598','池上','鄭谷','quantangshi','','卷38','池榭惬幽独，狂吟学解嘲。
露荷香自在，风竹冷相敲。
丧志嫌孤宦，忘机爱澹交。
仙山如有分，必拟访三茅。','',''),('quantangshi-37599','游贵侯城南林墅','鄭谷','quantangshi','','卷38','韦杜八九月，亭台高下风。
独来新霁后，闲步澹烟中。
荷密连池绿，柿繁和叶红。
主人贪贵达，清境属邻翁。','',''),('quantangshi-37600','江行','鄭谷','quantangshi','','卷38','漂泊病难任，逢人泪满襟。
关东多事日，天末未归心。
夜雨荆江涨，春云郢树深。
殷勤听渔唱，渐次入吴音。','',''),('quantangshi-37601','舟次通泉精舍','鄭谷','quantangshi','','卷38','江清如洛汭，寺好似香山。
劳倦孤舟里，登临半日间。
树凉巢鹤健，岩响语僧闲。
更共幽云约，秋随绛帐还。','',''),('quantangshi-37602','水轩','鄭谷','quantangshi','','卷38','日日狎沙禽，偷安且放吟。
读书老不入，爱酒病还深。
歉后为羁客，兵余问故林。
杨花满牀席，搔首度春阴。','',''),('quantangshi-37603','浔阳姚宰厅作','鄭谷','quantangshi','','卷38','县幽公事稀，庭草是山薇。
足得招棊侣，何妨着道衣。
野泉当案落，汀鹭入衙飞。
寺去东林近，多应隔宿归。','',''),('quantangshi-37604','梓潼岁暮','鄭谷','quantangshi','','卷38','江城无宿雪，风物易为春。
酒美消磨日，梅香着莫人。
老吟穷景象，多难损精神。
渐有还京望，绵州减战尘。','',''),('quantangshi-37605','咸阳','鄭谷','quantangshi','','卷38','咸阳城下宿，往事可悲思。
未有谋身计，频迁反正期。
冻河孤棹涩，老树叠巢危。
莫问今行止，漂漂不自知。','',''),('quantangshi-37606','长安感兴','鄭谷','quantangshi','','卷38','徒劳悲丧乱，自古戒繁华。
落日狐兔径，近年公相家。
可悲闻玉笛，不见走香车。
寂寞墙匡里，春阴挫杏花。','',''),('quantangshi-37607','闻所知游樊川有寄','鄭谷','quantangshi','','卷38','谁无泉石趣，朝下少同过。
贪胜觉程近，爱闲经宿多。
片沙留白鸟，高木引青萝。
醉把渔竿去，殷勤藉岸莎。','',''),('quantangshi-37608','张谷田舍','鄭谷','quantangshi','','卷38','县官清且俭，深谷有人家。
一径入寒竹，小桥穿野花。
碓喧春涧满，梯倚绿桑斜。
自说年来稔，前村酒可赊。','',''),('quantangshi-37609','深居','鄭谷','quantangshi','','卷38','吾道有谁同，深居自固穷。
殷勤谢绿树，朝夕惠清风。
书满闲窗下，琴横野艇中。
年来头更白，雅称钓鱼翁。','',''),('quantangshi-37610','端居','鄭谷','quantangshi','','卷38','叶叶下高梧，端居失所图。
乱离时辈少，风月夜吟孤。
旧疾衰还有，穷愁醉暂无。
秋光如水国，不语理霜须。','',''),('quantangshi-37611','郊园','鄭谷','quantangshi','','卷38','相近复相寻，山僧与水禽。
烟蓑春钓静，雪屋夜棊深。
雅道谁开口，时风未醒心。
溪光何以报，秪有醉和吟。','',''),('quantangshi-37612','郊野','鄭谷','quantangshi','','卷38','蓼水菊篱边，新晴有乱蝉。
秋光终寂寞，晚醉自留连。
野湿禾中露，村闲社后天。
题诗满红叶，何必浣花牋。','',''),('quantangshi-37613','旅寓洛南村舍','鄭谷','quantangshi','','卷38','村落清明近，秋千稚女夸。
春阴妨柳絮，月黑见棃花。
白鸟窥鱼网，青帘认酒家。
幽栖虽自适，交友在京华。','',''),('quantangshi-37614','杏花','鄭谷','quantangshi','','卷38','不学梅欺雪，轻红照碧池。
小桃新谢后，双燕却来时。
香属灯龙客，烟笼宿蝶枝。
临轩须貌取，风雨易离披。','',''),('quantangshi-37615','水林檎花','鄭谷','quantangshi','','卷38','一露一朝新，帘栊晓景分。
艳和蜂蝶动，香带管弦闻。
笑拟春无力，妆浓酒渐醺。
直疑风起夜，飞去替行云。','',''),('quantangshi-37616','蓼花','鄭谷','quantangshi','','卷38','蔟蔟复悠悠，年年拂漫流。
差池伴黄菊，冷澹过清秋。
晚带鸣虫急，寒藏宿鹭愁。
故溪归不得，凭仗系渔舟。','',''),('quantangshi-37617','江梅','鄭谷','quantangshi','','卷38','江梅且缓飞，前辈有歌词。
莫惜黄金缕，难忘白雪枝。
吟看归不得，醉嗅立如痴。
和雨和烟折，含情寄所思。','',''),('quantangshi-37618','茘枝','鄭谷','quantangshi','','卷38','平昔谁相爱，骊山遇贵妃。
枉教生处远，愁见摘来稀。
晚夺红霞色，晴欺瘴日威。
南荒何所恋，为尔即忘归。','',''),('quantangshi-37619','驻跸华下同年司封员外从翁许共游西溪久违前契戏成寄赠','鄭谷','quantangshi','','卷38','北渚牵吟兴，西溪爽共游。
指期乘禁马，无暇狎沙鸥。
纵目怀青岛，澄心想碧流。
明公非不爱，应待泛龙舟。','',''),('quantangshi-37620','谷自乱离之后在西蜀半纪之余多寓止精舍与圆昉上人为净侣昉公于长松山旧斋尝约他日访会劳生多故游宦数年曩契未谐忽闻谢世怆吟四韵以吊之','鄭谷','quantangshi','','卷38','每思闻净话，雨夜对禅牀。
未得重相见，秋灯照影堂。
孤云终负约，薄宦转堪伤。
梦绕长松塔，遥焚一炷香。','',''),('quantangshi-37621','投时相十韵','鄭谷','quantangshi','','卷38','何以保孤危，操修自不知。
众中常杜口，梦里亦吟诗。
失计辞山早，非才得仕迟。
薄冰安可履，暗室岂能欺。
勤苦流萤信，吁嗟宿燕知。
残钟残漏晓，落叶落花时。
故旧寒门少，文章外族衰。
此生多轗轲，半世足漂离。
省署随清品，渔舟爽素期。
恋恩休未遂，双鬓渐成丝。','',''),('quantangshi-37622','喜秀上人相访','鄭谷','quantangshi','','卷38','雪初开一径，师忽扣双扉。
老大情相近，林泉约共归。
忧荣栖省署，孤僻谢朝衣。
他夜松堂宿，论诗更入微。','',''),('quantangshi-37623','夕阳','鄭谷','quantangshi','','卷38','夕阳秋更好，敛敛蕙兰中。
极浦明残雨，长天急远鸿。
僧窗留半榻，渔舸透疎篷。
莫恨清光尽，寒蟾即照空。','',''),('quantangshi-37624','摇落','鄭谷','quantangshi','','卷38','夜来摇落悲，桑枣半空枝。
故国无消息，流年有乱离。
霜秦闻雁早，烟渭认帆迟。
日暮寒鼙急，边军在雍岐。','',''),('quantangshi-37625','西蜀净众寺松溪八韵兼寄小笔崔处士','鄭谷','quantangshi','','卷38','松因溪得名，溪吹答松声。
缭绕能穿寺，幽奇不在城。
寒烟斋后散，春雨夜中平。
染岸苍苔古，翘沙白鸟明。
澄分僧影瘦，光彻客心清。
带梵侵云响，和钟击石鸣。
澹烹新茗爽，暖泛落花轻。
此景吟难尽，凭君画入京。','',''),('quantangshi-37626','迁客','鄭谷','quantangshi','','卷38','离夜闻横笛，可堪吹鹧鸪。
雪冤知早晚，雨泣渡江湖。
秋树吹黄叶，腊烟垂绿芜。
虞飜归有日，莫便哭穷途。','',''),('quantangshi-37627','蔡处士','鄭谷','quantangshi','','卷38','无着复无求，平生不解愁。
鬻蔬贫洁净，中酒病风流。
旨趣陶山相，诗篇沈隐侯。
小斋江色里，篱柱系渔舟。','',''),('quantangshi-37628','予尝有雪景一绝为人所讽吟段赞善小笔精微忽为图画以诗谢之','鄭谷','quantangshi','','卷38','赞善贤相后，家藏名画多。
留心于绘素，得事在烟波。
属兴同吟咏，成功更琢磨。
爱予风雪句，幽绝写渔蓑。','',''),('quantangshi-37629','京兆府试残月如新月','鄭谷','quantangshi','','卷38','荣落何相似，初终却一般。
犹疑和夕照，谁信堕朝寒。
水木辉华别，诗家比象难。
佳人应误拜，栖鸟反求安。
屈指期轮满，何心谓影残。
庾楼清赏处，吟彻曙钟看。','',''),('quantangshi-37630','咸通十四年府试木向荣','鄭谷','quantangshi','','卷38','园林青气动，众木散寒声。
败叶墙阴在，滋条雪后荣。
欣欣春令早，蔼蔼日华轻。
庾岭梅先觉，隋堤柳暗惊。
山川应物候，臯壤起农情。
秪待花开日，连栖出谷莺。','',''),('quantangshi-37631','丞相孟夏祗荐南郊纪献十韵','鄭谷','quantangshi','','卷38','节应清和候，郊宫事洁羞。
至诚闻上帝，明德祀圆丘。
雅用陶匏器，馨非黍稷流。
就阳陈盛礼，匡国祷鸿休。
渐晓兰迎露，微凉麦弄秋。
寿山横紫阁，瑞霭抱皇州。
外肃通班序，中严锡庆优。
奏歌三酒备，表敬百神柔。
池碧将还凤，原清再问牛。
万方瞻辅翼，共贺赞皇猷。','',''),('quantangshi-37632','叙事感恩上狄右丞','鄭谷','quantangshi','','卷38','昔岁曾投贽，关河在左冯。
庾公垂顾遇，王粲许从容。
首荐叨殊礼，全家寓近封。
白楼陪写望，青眼感遭逢。
顾念梁间燕，深怜涧底松。
岚光莲岳逼，酒味菊花浓。
寇难旋移国，漂离几听蛩。
半生悲逆旅，二纪间门墉。
蜀雪随僧蹋，荆烟逐雁冲。
凋零归两鬓，举止失前踪。
得事虽甘晚，陈诗未肯慵。
迩来趋九仞，又伴赏三峯。
栖托情何限，吹嘘意数重。
自兹俦侣内，无复叹龙钟。','',''),('quantangshi-37633','咏怀','鄭谷','quantangshi','','卷38','迂疎虽可欺，心路甚男儿。
薄宦浑无味，平生粗有诗。
澹交终不破，孤达晚相宜。
直夜花前唤，朝寒雪里追。
竹声输我听，茶格共僧知。
景物还多感，情怀偶不卑。
溪莺喧午寝，山蕨止春饥。
险事销肠酒，清欢敌手棋。
香锄抛药圃，烟艇忆莎陂。
自许亨途在，儒纲复振时。','',''),('quantangshi-37634','干符丙申岁奉试春涨曲江池','鄭谷','quantangshi','','卷38','王泽尚通津，恩波此日新。
深疑一夜雨，宛似五湖春。
泛滟翘振鹭，澄清跃紫鳞。
翠低孤屿柳，香失半汀苹。
凤辇寻佳境，龙舟命近臣。
桂花如入手，愿作从游人。','',''),('quantangshi-37635','华山','鄭谷','quantangshi','','卷38','峭仞耸巍巍，晴岚染近畿。
孤高不可状，图写尽应非。
绝顶神仙会，半空鸾鹤归。
云台分远霭，树谷隐斜晖。
坠石连村响，狂雷发庙威。
气中寒渭阔，影外白楼微。
云对莲花落，泉横露掌飞。
乳悬危磴滑，樵彻上方稀。
澹泊生真趣，逍遥息世机。
野花明涧路，春藓涩松围。
远洞时闻磬，羣僧昼掩扉。
他年洗尘骨，香火愿相依。','',''),('quantangshi-37636','入阁','鄭谷','quantangshi','','卷38','祕殿临轩日，和銮返正年。
两班文武盛，百辟羽仪全。
霜漏清中禁，风旗拂曙天。
门严新勘契，仗入乍承宣。
玉几当红旭，金炉纵碧烟。
对扬称法吏，赞引出宫钿。
言动挥毫疾，雍容执簿专。
寿山晴叆叇，颢气暖连延。
礼有鸳鸾集，恩无雨露偏。
小臣叨备位，歌咏泰阶前。','',''),('quantangshi-37637','故少师从翁隐岩别墅乱后榛芜感旧怆怀遂有追纪','鄭谷','quantangshi','','卷38','风骚为主人，凡俗仰清尘。
密行称闺阃，明诚动搢绅。
周旋居显重，内外掌丝纶。
妙主蓬壶籍，忠为社稷臣。
大仪墙仞峻，东辖纪纲新。
闻善常开口，推公岂为身。
立朝鸣佩重，归宅典衣贫。
半醉看花晚，中餐煮菜春。
晴台随鹿上，幽墅结僧邻。
理论知清越，生徒得李频。
药香沾笔砚，竹色染衣巾。
寄鹤眠云叟，骑驴入室宾。
近将姚监比，僻与段卿亲。
叶积池边路，茶迟雪后薪。
所难留着述，谁不秉陶钧。
丧乱时多变，追思事已陈。
浮华重发作，雅正甚湮沦。
宗从今何在，依栖素有因。
七松无影响，双泪益悲辛。
犹喜于门秀，年来屈复伸。','',''),('quantangshi-37638','送吏部曹郎中免官南归','鄭谷','quantangshi','','卷38','高名向已求，古韵古无俦。
风月抛兰省，江山复桂州。
贤人知止足，中岁便归休。
云鹤深相待，公卿不易留。
满朝张祖席，半路上仙舟。
箧重藏吴画，茶新换越瓯。
郡迎红烛宴，寺宿翠岚楼。
触目成幽兴，全家是胜游。
篷声渔叟雨，苇色鹭鸶秋。
久别郊园改，将归里巷修。
桑麻胜禄食，节序免乡愁。
阳朔花迎棹，崇贤叶满沟。
席春欢促膝，檐日暖梳头。
道畅应为蝶，时来必问牛。
终须康庶品，未爽漱寒流。
议在归羣望，情难恋自由。
小生诚浅拙，早岁便依投。
夏课每垂奖，雪天常见忧。
远招陪宿直，首荐向公侯。
攀送偏挥洒，龙钟志未酬。','',''),('quantangshi-37639','回銮','鄭谷','quantangshi','','卷38','妖星沈雨露，和气满京关。
上将忠勋立，明君法驾还。
顺风调雅乐，夹道序羣班。
香泛传宣里，尘清指顾间。
楼台新紫气，云物旧黄山。
晓渭行朝肃，秋郊旷望闲。
庙灵安国步，日角动天颜。
浩浩升平曲，流歌彻百蛮。','',''),('quantangshi-37640','峡中','鄭谷','quantangshi','','卷38','万重烟霭里，隐隐见夔州。
夜静明月峡，春寒堆雪楼。
独吟谁会解，多病自淹留。
往事如今日，聊同子美愁。','',''),('quantangshi-37641','蜀中寓止夏日自贻','鄭谷','quantangshi','','卷38','展转攲孤枕，风帏信寂寥。
涨江垂螮蝀，骤雨闹芭蕉。
道阻归期晚，年加记性销。
故人衰飒尽，相望在行朝。','',''),('quantangshi-37642','试笔偶书','鄭谷','quantangshi','','卷38','沙鸟与山麋，由来性不羁。
可凭唯在道，难解莫过诗。
任笑孤吟僻，终嫌巧宦卑。
秉慵恩地恕，冷澹好僧知。
华省慙公器，沧江负钓师。
露花春直夜，烟鼓早朝时。
世路多艰梗，家风免坠遗。
殷勤一蓑雨，秪得梦中披。','',''),('quantangshi-37643','奔避','鄭谷','quantangshi','','卷38','奔避投人远，漂离易感恩。
愁髯霜飒飒，病眼泪昏昏。
孤馆秋声树，寒江落照村。
更闻归路绝，新寨截荆门。','',''),('quantangshi-37644','吊水部贾员外嵩','鄭谷','quantangshi','','卷38','八韵与五字，俱为时所先。
幽魂应自慰，李白墓相连。','',''),('quantangshi-37645','贫女吟','鄭谷','quantangshi','','卷38','尘压鸳鸯废锦机，满头空插丽春枝。
东邻舞妓多金翠，笑翦灯花学画眉。','',''),('quantangshi-37646','席上贻歌者','鄭谷','quantangshi','','卷38','花月楼台近九衢，清歌一曲倒金壶。
座中亦有江南客，莫向春风唱鹧鸪。','',''),('quantangshi-37647','菊','鄭谷','quantangshi','','卷38','王孙莫把比荆蒿，九日枝枝近鬓毛。
露湿秋香满池岸，由来不羡瓦松高。','',''),('quantangshi-37648','下峡','鄭谷','quantangshi','','卷38','忆子啼猨绕树哀，雨随孤棹过阳台。
波头未白人头白，瞥见春风滟滪堆。','',''),('quantangshi-37649','文昌寓直','鄭谷','quantangshi','','卷38','何逊空堦夜雨平，朝来交直雨新晴。
落花乱上花塼上，不忍和苔蹋紫英。','',''),('quantangshi-37650','街西晚归','鄭谷','quantangshi','','卷38','御沟春水绕闲坊，信马归来傍短墙。
幽榭名园临紫陌，晚风时带牡丹香。','',''),('quantangshi-37651','十日菊','鄭谷','quantangshi','','卷38','节去蜂愁蝶不知，晓庭还绕折残枝。
自缘今日人心别，未必秋香一夜衰。','',''),('quantangshi-37652','鹭鸶','鄭谷','quantangshi','','卷38','闲立春塘烟澹澹，静眠寒苇雨飕飕。
渔翁归后汀沙晚，飞下滩头更自由。','',''),('quantangshi-37653','柳','鄭谷','quantangshi','','卷38','半烟半雨江桥畔，暎杏映桃山路中。
会得离人无限意，千丝万絮惹春风。','',''),('quantangshi-37654','下第退居二首 一','鄭谷','quantangshi','','卷38','年来还未上丹梯，且着渔蓑谢故溪。
落尽梨花春又了，破篱残雨晚莺啼。','',''),('quantangshi-37655','下第退居二首 二','鄭谷','quantangshi','','卷38','未尝青杏出长安，豪士应疑怕牡丹。
秪有退耕耕不得，茫然村落水吹残。','',''),('quantangshi-37656','江宿闻芦管','鄭谷','quantangshi','','卷38','塞曲凄清楚水滨，声声吹出落梅春。
须知风月千樯下，亦有葫芦河畔人。','',''),('quantangshi-37657','闲题','鄭谷','quantangshi','','卷38','举世何人肯自知，须逢精鉴定妍媸。
若教嫫母临明镜，也道不劳红粉施。','',''),('quantangshi-37658','曲江春草','鄭谷','quantangshi','','卷38','花落江堤蔟暖烟，雨余草色远相连。
香轮莫辗青青破，留与愁人一醉眠。','',''),('quantangshi-37659','雪中偶题','鄭谷','quantangshi','','卷38','乱飘僧舍茶烟湿，密洒歌楼酒力微。
