惊散渔家吹短笛，失羣征戍锁残阳。
故乡闻尔亦惆怅，何况扁舟非故乡。','',''),('quantangshi-37707','水','鄭谷','quantangshi','','卷38','竹院松廊分数派，不空清泚亦逶迤。
