洗钵老僧临岸久，钓鱼闲客卷纶迟。
晚晴一片连莎绿，悔与沧浪有旧期。','',''),('quantangshi-37708','海棠','鄭谷','quantangshi','','卷38','春风用意匀颜色，销得携觞与赋诗。
