侵堦藓拆春芽迸，绕径莎微夏荫浓。
无赖杏花多意绪，数枝穿翠好相容。','',''),('quantangshi-37710','荔枝树','鄭谷','quantangshi','','卷38','二京曾见画图中，数本芳菲色不同。
