宫花颜色开时丽，池雁毛衣浴后明。
礼部郎官人所重，省中别占好窠名。','',''),('quantangshi-37713','蜡烛','鄭谷','quantangshi','','卷38','仙漏迟迟出建章，宫帘不动透清光。
金闱露白新裁诏，画合春红正试妆。
泪滴杯盘何所恨，烬飘兰麝暗和香。
多情更有分明处，照得歌尘下燕梁。','',''),('quantangshi-37714','灯','鄭谷','quantangshi','','卷38','雨向莎堦滴未休，冷光孤恨雨悠悠。
船中闻雁洞庭宿，牀下有蛩长信秋。
背照翠帘新洒别，不挑红烬正含愁。
萧骚寒竹南窗静，一局闲棋为尔留。','',''),('quantangshi-37715','宗人作尉唐昌官署幽胜而又博学精富得以言谈将欲他之留书屋壁','鄭谷','quantangshi','','卷38','公堂潇洒有林泉，秪隔苔墙是渚田。
宗党相亲离乱世，春秋闲论战争年。
远江惊鹭来池口，绝顶归云过竹边。
风雨夜长同一宿，旧游多共忆樊川。','',''),('quantangshi-37716','为户部李郎中与令季端公寓止渠州江寺偶作寄献','鄭谷','quantangshi','','卷38','退居潇洒寄禅关，高挂朝簪净室间。
孤岛虽留双鹤歇，五云争放二龙闲。
轻舟共泛花边水，野屐同登竹外山。
仙署金闺虚位久，夜清应梦近天颜。','',''),('quantangshi-37717','重阳日访元秀上人','鄭谷','quantangshi','','卷38','红叶黄花秋景宽，醉吟朝夕在樊川。
