别画长怀吴寺壁，宜茶偏赏霅溪泉。
归来童稚争相笑，何事无人与酒船。','',''),('quantangshi-37718','阙下春日','鄭谷','quantangshi','','卷38','建章宫殿紫云飘，春漏迟迟下绛霄。
绮陌暖风嘶去马，粉廊初日照趋朝。
花经宿雨香难拾，莺在豪家语更娇。
秦楚年年有离别，扬鞭挥袖灞陵桥。','',''),('quantangshi-37719','赠刘神童','鄭谷','quantangshi','','卷38','习读在前生，僧谈足可明。
还家虽解喜，登第未知荣。
时果曾霑赐，春闱不挂情。
灯前犹恶睡，寤语读书声。','',''),('quantangshi-37720','远游','鄭谷','quantangshi','','卷38','江湖犹足事，食宿戍鼙喧。
久客秋风起，孤舟夜浪翻。
乡音离楚水，庙貌入湘源。
岸阔凫鹥小，林垂橘柚繁。
津官来有意，渔者笑无言。
早晚酬僧约，中条有药园。','',''),('quantangshi-37721','光化戊午年举公见示省试春草碧色诗偶赋是题','鄭谷','quantangshi','','卷38','苌弘血染新，含露满江滨。
想得寻花径，应迷拾翠人。
窗纱迎拥砌，簪玉妬成茵。
天借新晴色，云饶落日春。
岚光垂处合，眉黛看时嚬。
愿与仙桃比，无令惹路尘。','',''),('quantangshi-37722','江际','鄭谷','quantangshi','','卷38','杳杳渔舟破暝烟，疎疎芦苇旧江天。
那堪流落逢摇落，可得潸然是偶然。
万顷白波迷宿鹭，一林黄叶送残蝉。
兵车未息年华促，早晚闲吟向浐川。','',''),('quantangshi-37723','将之泸郡旅次遂州遇裴晤员外谪居于此话旧凄凉因寄二首 一','鄭谷','quantangshi','','卷38','谁解登高问上玄，谪仙何事谪诗仙。
云遮列宿离华省，树荫澄江入野船。
黄鸟晚啼愁瘴雨，青梅早落中蛮烟。
不知几首南行曲，留与巴儿万古传。','',''),('quantangshi-37724','将之泸郡旅次遂州遇裴晤员外谪居于此话旧凄凉因寄二首 二','鄭谷','quantangshi','','卷38','昔年共照松溪影，松折溪荒僧已无。
今日重思锦城事，雪销花谢梦何殊。
乱离未定身俱老，骚雅全休道甚孤。
我拜师门更南去，荔枝春熟向渝泸。','',''),('quantangshi-37725','次韵和秀上人长安寺居言怀寄渚宫禅者','鄭谷','quantangshi','','卷38','旧斋松老别多年，香社人稀丧乱间。
出寺秪知趋内殿，闭门长似在深山。
卧听秦树秋钟断，吟想荆江夕鸟还。
唯恐兴来飞锡去，老郎无路更追攀。','',''),('quantangshi-37726','蜀中春日','鄭谷','quantangshi','','卷38','海棠风外独霑巾，襟袖无端惹蜀尘。
和暖又逢挑菜日，寂寥未是探花人。
不嫌蚁酒冲愁肺，却忆渔蓑覆病身。
何事晚来微雨后，锦江春学曲江春。','',''),('quantangshi-37727','游蜀','鄭谷','quantangshi','','卷38','所向明知是暗投，两行清泪语前流。
云横新塞遮秦甸，花落空山入阆州。
不忿黄鹂惊晓梦，唯应杜宇信春愁。
梅黄麦绿无归处，可得漂漂爱浪游。','',''),('quantangshi-37728','峡中尝茶','鄭谷','quantangshi','','卷38','蔟蔟新英摘露光，小江园里火煎尝。
吴僧漫说鸦山好，蜀叟休夸鸟觜香。
合座半瓯轻泛绿，开缄数片浅含黄。
鹿门病客不归去，酒渴更知春味长。','',''),('quantangshi-37729','辇下冬暮咏怀','鄭谷','quantangshi','','卷38','永巷闲吟一径蒿，轻肥大笑事风骚。
烟含紫禁花期近，雪满长安酒价高。
失路渐惊前计错，逢僧更念此生劳。
十年春泪催衰飒，羞向清流照鬓毛。','',''),('quantangshi-37730','石城','鄭谷','quantangshi','','卷38','石城昔为莫愁乡，莫愁魂散石城荒。
江人依旧棹舴艋，江岸还飞双鸳鸯。
帆去帆来风浩渺，花开花落春悲凉。
烟浓草远望不尽，千古汉阳闲夕阳。','',''),('quantangshi-37731','蜀中三首 一','鄭谷','quantangshi','','卷38','马头春向鹿头关。
远树平芜一望闲，雪下文君沾酒市。
云藏李白读书山，江楼客恨黄梅后。
村落人歌紫芋间，堤月桥灯好时景。
汉庭无事不征蛮。','',''),('quantangshi-37732','蜀中三首 二','鄭谷','quantangshi','','卷38','夜无多雨晓生尘，草色岚光日日新。
蒙顶茶畦千点露，浣花牋纸一溪春。
扬雄宅在唯乔木，杜甫台荒绝旧邻。
却共海棠花有约，数年留滞不归人。','',''),('quantangshi-37733','蜀中三首 三','鄭谷','quantangshi','','卷38','渚远江清碧簟纹，小桃花绕薛涛坟。
朱桥直指金门路，粉堞高连玉垒云。
窗下[斵]琴翘凤足，波中濯锦散鸥羣。
子规夜夜啼巴树，不并吴乡楚国闻。','',''),('quantangshi-37734','少华甘露寺','鄭谷','quantangshi','','卷38','石门萝径与天邻，雨桧风篁远近闻。
饮涧鹿喧双派水，上楼僧蹋一梯云。
孤烟薄暮关城没，远色初晴渭曲分。
长欲然香来此宿，北林猨鹤旧同羣。','',''),('quantangshi-37735','慈恩寺偶题','鄭谷','quantangshi','','卷38','往事悠悠添浩叹，劳生扰扰竟何能。
故山岁晚不归去，高塔晴来独自登。
林下听经秋苑鹿，江边扫叶夕阳僧。
吟余却起双峰念，曾看庵西瀑布冰。','',''),('quantangshi-37736','石门山泉','鄭谷','quantangshi','','卷38','一脉清泠何所之，萦莎漱藓入僧池。
云边野客穷来处，石上寒猨见落时。
聚沫绕崖残雪在，迸流穿树堕花随。
烟春雨晚闲吟去，不复远寻皇子陂。','',''),('quantangshi-37737','渭阳楼闲望','鄭谷','quantangshi','','卷38','千重二华见皇州，望尽凝岚即此楼。
细雨不藏秦树色，夕阳空照渭河流。
后车宁见前车覆，今日难忘昨日忧。
扰扰尘中犹未已，可能疏傅独能休。','',''),('quantangshi-37738','送田光','鄭谷','quantangshi','','卷38','九陌低迷谁问我，五湖流浪可悲君。
着书笑破苏司业，赋咏思齐郑广文。
理棹好携三百首，阻风须饮几千分。
耒阳江口春山绿，恸哭应寻杜甫坟。','',''),('quantangshi-37739','送进士吴延保及第后南游','鄭谷','quantangshi','','卷38','得意却思寻旧迹，新衔未切向兰台。
吟看秋草出关去，逢见故人随计来。
胜地昔年诗板在，清歌几处郡筵开。
江湖易有淹留兴，莫待春风落庾梅。','',''),('quantangshi-37740','送进士王驾下第归蒲中','鄭谷','quantangshi','','卷38','失意离愁春不知，到家时是落花时。
孤单取事休言命，早晚逢人苦爱诗。
度塞风沙归路远，傍河桑柘旧居移。
应嗟我又巴江去，游子悠悠听子规。','',''),('quantangshi-37741','作尉鄠郊送进士潘为下第南归','鄭谷','quantangshi','','卷38','归去宜春春水深，麦秋梅雨过湘阴。
乡园几度经狂寇，桑柘谁家有旧林。
结绶位卑甘晚达，登龙心在且高吟。
灞陵桥上杨花里，酒满芳樽泪满襟。','',''),('quantangshi-37742','送进士韦序赴举','鄭谷','quantangshi','','卷38','丹霞照上三清路，瑞锦裁成五色毫。
波浪不能随世态，鸾凰应得入吾曹。
秋山晚水吟情远，雪竹风松醉格高。
预想明年腾跃处，龙津春碧浸仙桃。','',''),('quantangshi-37743','寄献狄右丞','鄭谷','quantangshi','','卷38','逐胜偷闲向杜陵，爱僧不爱紫衣僧。
身为醉客思吟客，官自中丞拜右丞。
残月露垂朝阙盖，落花风动宿斋灯。
孤单小谏渔舟在，心恋清潭去未能。','',''),('quantangshi-37744','转正郎后寄献集贤相公','鄭谷','quantangshi','','卷38','予名初在德门前，屈指年来三十年。
自贺孤危终际会，别将流涕感阶缘。
止陪鸳鸯居清秩，滥应星辰浼上玄。
平昔苦心何所恨，受恩多是旧诗篇。','',''),('quantangshi-37745','所知从事近藩偶有怀寄','鄭谷','quantangshi','','卷38','官舍种莎僧对榻，生涯如在旧山贫。
酒醒草檄闻残漏，花落移厨送晚春。
水墨画松清睡眼，云霞仙氅挂吟身。
霜台伏首思归切，莫把渔竿逐逸人。','',''),('quantangshi-37746','献大京兆薛常侍能','鄭谷','quantangshi','','卷38','耻将官业竞前途，自爱篇章古不如。
一炷香新开道院，数坊人聚避朝车。
纵游藉草花垂酒，闲卧临窗燕拂书。
唯有明公赏新句，秋风不敢忆鲈鱼。','',''),('quantangshi-37747','寄赠孙路处士','鄭谷','quantangshi','','卷38','平生诗誉更谁过，归老东吴命若何。
知己凋零垂白发，故园寥落近沧波。
酒醒藓砌花阴转，病起渔舟鹭迹多。
深入富春人不见，闲门空掩半庭莎。','',''),('quantangshi-37748','献制诰杨舍人','鄭谷','quantangshi','','卷38','为郡东吴秪饮冰，琐闱频降凤书征。
随行已有朱衣吏，伴直多招紫阁僧。
窗下调琴鸣远水，帘前睡鹤背秋灯。
苇陂竹坞情无限，闲话毗陵问杜陵。','',''),('quantangshi-37749','次韵酬张补阙因寒食见寄之什','鄭谷','quantangshi','','卷38','柳近清明翠缕长，多情右衮不相忘。
开缄虽覩新篇丽，破鼻须闻冷酒香。
时态嬾随人上下，花心甘被蝶分张。
朝稀且莫轻春赏，胜事由来在帝乡。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37750','赠宗人前公安宰君','鄭谷','quantangshi','','卷38','喧卑从宦出喧卑，别画能琴又解棊。
海上春耕因乱废，年来冬荐得官迟。
风中夜犬惊槐巷，月下寒驴啮槿篱。
孤散恨无推唱路，耿怀吟得赠君诗。','',''),('quantangshi-37751','寄赠杨夔处士','鄭谷','quantangshi','','卷38','结茅秪约钓鱼台，溅水鸬鷀去又回。
春卧瓮边听酒熟，露吟庭际待花开。
三江胜景遨游徧，百氏羣书讲贯来。
国步未安风雅薄，可能高尚掞天才。','',''),('quantangshi-37752','寄同年礼部赵郎中','鄭谷','quantangshi','','卷38','仙步徐徐整羽衣，小仪澄澹转中仪。
桦飘红烬趋朝路，兰纵清香宿省时。
彩笔烟霞供不足，纶闱鸾凤讶来迟。
自怜孤宦谁相念，祷祝空吟一首诗。','',''),('quantangshi-37753','春暮咏怀寄集贤韦起居衮','鄭谷','quantangshi','','卷38','寂寂风帘信自垂，杨花笋箨正离披。
长安一夜残春雨，右省三年老拾遗。
坐看羣贤争得路，退量孤分且吟诗。
五湖烟网非无意，未去难忘国士知。','',''),('quantangshi-37754','多情','鄭谷','quantangshi','','卷38','赋分多情却自嗟，萧衰未必为年华。
睡轻可忍风敲竹，饮散那堪月在花。
薄宦因循抛岘首，故人流落向天涯。
莺春雁夜长如此，赖是幽居近酒家。','',''),('quantangshi-37755','感怀投时相','鄭谷','quantangshi','','卷38','非才偶忝直文昌，两鬓年深一镜霜。
待漏敢辞称小吏，立班犹未出中行。
孤吟马迹抛槐陌，远梦渔竿掷苇乡。','',''),('quantangshi-37756','自贻','鄭谷','quantangshi','','卷38','饮筵博席与心违，野眺春吟更是谁。
琴有涧风声转澹，诗无僧字格还卑。
恨抛水国荷蓑雨，贫过长安樱笋时。
头角俊髦应指笑，权门踪迹独差池。','',''),('quantangshi-37757','自遣','鄭谷','quantangshi','','卷38','强健宦途何足谓，入微章句更难论。
谁知野性真天性，不扣权门扣道门。
窥砚晚莺临砌树，迸堦春笋隔篱根。
朝回何处消长日，紫阁峰南有旧村。','',''),('quantangshi-37758','中年','鄭谷','quantangshi','','卷38','漠漠秦云澹澹天，新年景象入中年。
情多最恨花无语，愁破方知酒有权。
苔色满墙寻故第，雨声一夜忆春田。
衰迟自喜添诗学，更把前题改数联。','',''),('quantangshi-37759','自适','鄭谷','quantangshi','','卷38','紫陌奔驰不暂停，送迎终日在郊坰。
年来鬓畔未垂白，雨后江头且蹋青。
浮蚁满杯难暂舍，贯珠一曲莫辞听。
春风秪有九十日，可合花前半日醒。','',''),('quantangshi-37760','结绶鄠郊縻摄府署偶有自咏','鄭谷','quantangshi','','卷38','莺离寒谷士逢春，释褐来年暂种芸。
自笑老为梅少府，可堪贫摄鲍参军。
酒醒往事多兴念，吟苦邻居必厌闻。
推却簿书搔短发，落花飞絮正纷纷。','',''),('quantangshi-37761','漂泊','鄭谷','quantangshi','','卷38','槿坠蓬疎池馆清，日光风绪澹无情。
鲈鱼斫鲙输张翰，橘树呼奴羡李衡。
十口漂零犹寄食，两川消息未休兵。','',''),('quantangshi-37762','吊故礼部韦员外序','鄭谷','quantangshi','','卷38','腊雪初晴共举杯，便期携手上春台。
高情唯怕酒不满，长逝可悲花正开。
晓奠莺啼残漏在，风帏燕觅旧巢来。
杜陵芳草年年绿，醉魄吟魂无复回。','',''),('quantangshi-37763','渼陂','鄭谷','quantangshi','','卷38','昔事东流共不回，春深独向渼陂来。
乱前别业依稀在，雨里繁花寂寞开。
却展渔丝无野艇，旧题诗句没苍苔。
潸然四顾难消遣，秪有佯狂泥酒杯。','',''),('quantangshi-37764','代秋扇词','鄭谷','quantangshi','','卷38','露入庭芜恨已深，热时天下是知音。
汗流浃背曾施力，气爽中宵便负心。
一片山溪从蠹损，数行文字任尘侵。
绿槐阴合清和后，不会何颜又见寻。','',''),('quantangshi-37765','宣义里舍冬暮自贻','鄭谷','quantangshi','','卷38','幽居不称在长安，沟浅浮春岸雪残。
板屋渐移方带野，水车新入夜添寒。
名如有分终须立，道若离心岂易宽。
满眼尘埃驰骛去，独寻烟竹翦渔竿。','',''),('quantangshi-37766','省中偶作','鄭谷','quantangshi','','卷38','三转郎曹自勉旃，莎阶吟步想前贤。
未如何逊无佳句，若比冯唐是壮年。
捧制名题黄纸尾，约僧心在白雪边。
乳毛松雪春来好，直夜清闲且学禅。','',''),('quantangshi-37767','同志顾云下第出京偶有寄勉','鄭谷','quantangshi','','卷38','凤策联华是国华，春来偶未上仙槎。
乡连南渡思菰米，泪滴东风避杏花。
吟聒暮莺归庙院，睡消迟日寄僧家。
一般情绪应相信，门静莎深树影斜。','',''),('quantangshi-37768','敷溪高士','鄭谷','quantangshi','','卷38','敷溪南岸掩柴荆，挂却朝衣爱净名。
闲得林园栽树法，喜闻儿侄读书声。
眠窗日暖添幽梦，步野风清散酒酲。
谪去征还何扰扰，片云相伴看衰荣。','',''),('quantangshi-37769','九日偶怀寄左省张起居','鄭谷','quantangshi','','卷38','令节争欢我独闲，荒台尽日向晴山。
浑无酒泛金英菊，漫道官趋玉笋班。
深愧青莎迎野步，不堪红叶照衰颜。
羡君官重多吟兴，醉带南陂落照还。','',''),('quantangshi-37770','春夕伴同年礼部赵员外省直','鄭谷','quantangshi','','卷38','锦帐名郎重锦科，清宵寓直纵吟哦。
冰含玉镜春寒在，粉傅仙闱月色多。
视草即应归属望，握兰知道暂经过。
流莺百啭和残漏，犹把芳樽藉露莎。','',''),('quantangshi-37771','倦客','鄭谷','quantangshi','','卷38','十年五年岐路中，千里万里西复东。
匹马愁冲晚村雪，孤舟闷阻春江风。
达士由来知道在，昔贤何必哭途穷。
闲烹芦笋炊菰米，会向源乡作醉翁。','',''),('quantangshi-37772','温处士能画鹭鹚以四韵换之','鄭谷','quantangshi','','卷38','昔年吟醉绕江蓠，爱把渔竿伴鹭鹚。
闻说小毫能纵逸，敢凭轻素写幽奇。
涓涓浪溅残菱蔓，戛戛风搜折苇枝。
得向晓窗闲挂翫，雪蓑烟艇恨无遗。','',''),('quantangshi-37773','驾部郑郎中三十八丈尹贰东周荣加金紫谷以末派之外恩旧事深因贺送','鄭谷','quantangshi','','卷38','香浮玉陛晓辞天，袍拂蒲茸称少年。
郎署转曹虽久次，京河亚尹是优贤。
纵游云水无公事，贵买琴书有俸钱。
今日龙门看松雪，探春明日向平泉。','',''),('quantangshi-37774','欹枕','鄭谷','quantangshi','','卷38','攲枕高眠日午春，酒酣睡足最闲身。
明朝会得穷通理，未必输他马上人。','',''),('quantangshi-37775','野步','鄭谷','quantangshi','','卷38','翠岚迎步兴何长，笑领渔翁入醉乡。
日暮渚田微雨后，鹭鹚闲暇稻花香。','',''),('quantangshi-37776','偶书','鄭谷','quantangshi','','卷38','承时偷喜负明神，务实那能得庇身。
不会苍苍主何事，忍饥多是力耕人。','',''),('quantangshi-37777','静吟','鄭谷','quantangshi','','卷38','骚雅荒凉我未安，月和余雪夜吟寒。
相门相客应相笑，得句胜于得好官。','',''),('quantangshi-37778','和知己秋日伤怀','鄭谷','quantangshi','','卷38','流水歌声共不回，去年天气旧亭台。
梁尘寂寞燕归去，黄蜀葵花一朵开。','',''),('quantangshi-37779','谷比岁受同年丈人故川守李侍郎教谕衰晏龙钟益用感叹遂以章句自贻','鄭谷','quantangshi','','卷38','多感京河李丈人，童蒙受教便书绅。
文章至竟无功业，名宦由来致苦辛。
皎日还应知守道，平生自信解甘贫。
孤单所得皆逾分，归种敷溪一亩春。','',''),('quantangshi-37780','郊墅','鄭谷','quantangshi','','卷38','韦曲樊川雨半晴，竹庄花院徧题名。
画成烟景垂杨色，滴破春愁压酒声。
满野红尘谁得路，连天紫阁独关情。
渼陂水色澄于镜，何必沧浪始濯缨。','',''),('quantangshi-37781','舟行','鄭谷','quantangshi','','卷38','九派迢迢九月残，舟人相语且相宽。
村逢好处嫌风便，酒到醒来觉夜寒。
蓼渚白波喧夏口，柿园红叶忆长安。
季鹰可是思鲈鲙，引退知时自古难。','',''),('quantangshi-37782','奔问三峰寓止近墅','鄭谷','quantangshi','','卷38','半年奔走颇惊魂，来谒行宫泪眼昏。
鸳鹭入朝同待漏，牛羊送日独归村。
灞陵散失诗千首，太华凄凉酒一樽。
兵革未休无异术，不知何以受君恩。','',''),('quantangshi-37783','朝直','鄭谷','quantangshi','','卷38','朝直叨居省阁间，由来疎退校安闲。
落花夜静宫中漏，微雨春寒廊下班。
自扣玄门齐宠辱，从他荣路用机关。
孤峰未得深归去，名画偏求水墨山。','',''),('quantangshi-37784','巴江','鄭谷','quantangshi','','卷38','乱来奔走巴江滨，愁客多于江徼人。
朝醉暮醉雪开霁，一枝两枝梅探春。
诏书罪己方哀痛，乡县征兵尚苦辛。
鬓秃又惊逢献岁，眼前浑不见交亲。','',''),('quantangshi-37785','故许昌薛尚书能尝为都官郎中后数岁故建州李员外频自宪府内弹拜都官员外八座外郎皆一时骚雅宗师则都官之曹振盛于此予早年请益实受深知今忝此官复是正秩岂唯俯慰孤宦何以仰继前贤荣惕在衷遂赋自贺','鄭谷','quantangshi','','卷38','都官虽未是名郎，践历曾闻薛许昌。
复有李公陪雅躅，岂宜郑子忝余光。
荣为后进趋兰署，喜拂前题在粉墙。
他日节旄如可继，不嫌曹冷在中行。','',''),('quantangshi-37786','访题表兄王藻渭上别业','鄭谷','quantangshi','','卷38','桑林摇落渭川西，蓼水弥弥接稻泥。
幽槛静来鱼唱远，暝天寒极雁行低。
浊醪最称看山醉，冷句偏宜选竹题。
中表人稀离乱后，花时莫惜重相携。','',''),('quantangshi-37787','题汝州从事厅','鄭谷','quantangshi','','卷38','诗人公署如山舍，秪向堦前便采薇。
惊燕拂帘闲睡觉，落花沾砚会餐归。
壁看旧记官多达，牓挂明文吏莫违。
自说小池栽苇后，雨凉频见鹭鹚飞。','',''),('quantangshi-37788','谷初忝谏垣今宪长薛公方在西阁知奖隆异以四韵代述荣感','鄭谷','quantangshi','','卷38','旧诗常得在高吟，不奈公心爱苦心。
道自琐闱言下振，恩从仙殿对回深。
流年渐觉霜欺鬓，至药能教土化金。
自拂青萍知有地，斋诚旦夕望为霖。','',''),('quantangshi-37789','兵部卢郎中光济借示诗集以四韵谢之','鄭谷','quantangshi','','卷38','七子风骚寻失主，五君歌诵久无声。
调和雅乐归时正，澄滤颓波到底清。
才大始知寰宇窄，吟高何止鬼神惊。
叶公好尚浑疎阔，忽见真龙几丧明。','',''),('quantangshi-37790','贺左省新除韦拾遗','鄭谷','quantangshi','','卷38','初升谏署是真仙，浪透桃花恰五年。
垂白郎官居座末，着绯人吏立阶前。
百寮班列趋丹陛，两掖风清上碧天。
从此追飞何处去，金銮殿与玉堂连。','',''),('quantangshi-37791','右省张补阙茂枢同在谏垣连居光德新春赋咏聊以寄怀','鄭谷','quantangshi','','卷38','小梅零落雪欺残，浩荡穷愁岂易宽。
唯有郎吟偿晚景，且无浓醉厌春寒。
高斋每喜追攀近，丽句先忧属和难。
十五年前谙苦节，知心不独为同官。','',''),('quantangshi-37792','右省补阙张茂枢同在谏垣邻居光德迭和篇什未尝间时忽见贻谓谷将来履历必在文昌当与何水部宋考功为俦谷虽赋于风雅实用兢惶因抒酬寄','鄭谷','quantangshi','','卷38','何宋清名动粉闱，不才今日偶陈诗。
考功岂敢闻题品，水部犹须系挈维。
积雪巷深酬唱夜，落花墙隔笑言时。
紫垣名士推扬切，为话心孤倍感知。','',''),('quantangshi-37793','寄职方李员外','鄭谷','quantangshi','','卷38','曾袖篇章谒长卿，今来附凤事何荣。
星临南省陪仙步，春满东朝接佩声。
谈笑不拘先后礼，岁寒仍契子孙情。
龙墀仗下天街暖，共看圭峰并马行。','',''),('quantangshi-37794','寄题诗僧秀公','鄭谷','quantangshi','','卷38','灵一心传清塞心，可公吟后楚公吟。
近来雅道相亲少，唯仰吾师所得深。
好句未停无暇日，旧山归老有东林。
冷曹孤宦甘寥落，多谢携筇数访寻。','',''),('quantangshi-37795','东蜀春晚','鄭谷','quantangshi','','卷38','如此浮生更别离，可堪长恸送春归。
潼江水上杨花雪，刚逐孤舟缭绕飞。','',''),('quantangshi-37796','永日有怀','鄭谷','quantangshi','','卷38','能消永日是摴蒱，坑堑由来似宦途。
两掷未终楗橛内，座中何惜为呼卢。','',''),('quantangshi-37797','槐花','鄭谷','quantangshi','','卷38','毵毵金蕊扑晴空，举子魂惊落照中。
今日老郎犹有恨，昔年相虐十秋风。','',''),('quantangshi-37798','小桃','鄭谷','quantangshi','','卷38','和烟和雨遮敷水，映竹映村连灞桥。
撩乱春风耐寒令，到头赢得杏花娇。','',''),('quantangshi-37799','长江县经贾岛墓','鄭谷','quantangshi','','卷38','水绕荒坟县路斜，耕人讶我久咨嗟。
重来兼恐无寻处，落日风吹鼓子花。','',''),('quantangshi-37800','嘉陵','鄭谷','quantangshi','','卷38','细雨湿萋萋，人稀江日西。
春愁肠已断，不在子规啼。','',''),('quantangshi-37801','嘉陵','鄭谷','quantangshi','','卷38','细雨湿凄凄，人稀江日西。
春膓已愁断，不待子规啼。','',''),('quantangshi-37802','中秋','鄭谷','quantangshi','','卷38','清香闻晓莲，水国雨余天。
天气正得所，客心刚悄然。
乱兵何日息，故老几人全。
此际难消遣，从来未学禅。','',''),('quantangshi-37803','朝谒','鄭谷','quantangshi','','卷38','捧日整朝簪，千官一片心。
班趋黄道急，殿接紫宸深。
威凤回香扆，新莺啭上林。
小松含瑞露，春翠易成阴。','',''),('quantangshi-37804','锦浦','鄭谷','quantangshi','','卷38','流落夜凄凄，春寒锦浦西。
不甘花逐水，可惜雪成泥。
病眼嫌灯近，离肠赖酒迷。
凭君嘱鹎鵊，莫向五更啼。','',''),('quantangshi-37805','峨嵋山','鄭谷','quantangshi','','卷38','万仞白云端，经春雪未残。
夏消江峡满，晴照蜀楼寒。
造境知僧熟，归林认鹤难。
会须朝阙去，秪有画图看。','',''),('quantangshi-37806','蜀江有吊','鄭谷','quantangshi','','卷38','孟子有良策，惜哉今已而。
徒将心体国，不识道消时。
折槛未为切，沈湘何足悲。
苍苍无问处，烟雨徧江蓠。','',''),('quantangshi-37807','书村叟壁','鄭谷','quantangshi','','卷38','草肥朝牧牛，桑绿晚鸣鸠。
列岫檐前见，清泉碓下流。
春蔬和雨割，社酒向花篘。
引我南陂去，篱边有小舟。','',''),('quantangshi-37808','题进士王驾郊居','鄭谷','quantangshi','','卷38','前山微有雨，永巷净无尘。
牛卧篱阴晚，鸠鸣村意春。
时浮应寡合，道在不嫌贫。
后径临陂水，菰蒲是切邻。','',''),('quantangshi-37809','题庄严寺休公院','鄭谷','quantangshi','','卷38','秋深庭色好，红叶间青松。
病客殊无着，吾师甚见容。
疎钟和细溜，高塔等遥峰。
未省求名侣，频于此地逢。','',''),('quantangshi-37810','题兴善寺','鄭谷','quantangshi','','卷38','寺在帝城阴，清虚胜二林。
藓侵隋画暗，茶助越瓯深。
巢鹤和钟唳，诗僧倚锡吟。
烟莎后池水，前迹杳难寻。','',''),('quantangshi-37811','宿澄泉兰若','鄭谷','quantangshi','','卷38','山半古招提，空林雪月迷。
乱流分石上，斜汉在松西。
云集寒庵宿，猨先晓磬啼。
此心如了了，即此是曹溪。','',''),('quantangshi-37812','送举子下第东归','鄭谷','quantangshi','','卷38','夫子道何孤，青云未得途。
诗书难舍鲁，山水暂游吴。
野绿梅阴重，江春浪势麤。
秣陵兵役后，旧业半成芜。','',''),('quantangshi-37813','寄察院李侍御文炬','鄭谷','quantangshi','','卷38','古柏间疎篁，清阴在印牀。
宿郊虔点馔，秋寺静监香。
参集行多揖，风仪见即庄。
伫闻横擘去，帷集谏书囊。','',''),('quantangshi-37814','偶怀寄台院孙端公棨','鄭谷','quantangshi','','卷38','才拙道仍孤，无何舍钓徒。
班虽沾玉笋，香不近金炉。
雨露瞻双阙，烟波隔五湖。
唯君应见念，曾共伏青蒲。','',''),('quantangshi-37815','次韵和秀上人游南五台','鄭谷','quantangshi','','卷38','中峰曾到处，题记没苍苔。
振锡传深谷，翻经想旧台。
苍松临砌偃，惊鹿蓦溪来。
内殿评诗切，身回心未回。','',''),('quantangshi-37816','乖慵','鄭谷','quantangshi','','卷38','乖慵居竹里，凉冷卧池东。
一霎芰荷雨，几回帘幕风。
远僧来扣寂，小吏笑书空。
衰鬓霜供白，愁颜酒借红。
扇轻摇鹭羽，屏古画渔翁。
自得无端趣，琴棊舫子中。','',''),('quantangshi-37817','南宫寓直','鄭谷','quantangshi','','卷38','寓直事非轻，宦孤忧且荣。
制承黄纸重，词见紫垣清。
晓霁庭松色，风和禁漏声。
僧携新茗伴，吏扫落花迎。
锁印诗心动，垂帘睡思生。
粉廊曾试处，石柱昔贤名。
来误宫窗燕，啼疑苑树莺。
残阳应更好，归促恨严城。','',''),('quantangshi-37818','恩门小谏雨中乞菊栽','鄭谷','quantangshi','','卷38','握兰将满岁，栽菊伴吟诗。
老去慵趋世，朝回独绕篱。
递香风细细，浇绿水弥弥。
秪共山僧赏，何当国士移。
孤根深有托，微雨正相宜。
更待金英发，凭君插一枝。','',''),('quantangshi-37819','荆渚八月十五夜值雨寄同年李屿','鄭谷','quantangshi','','卷38','共待辉光夜，翻成黯澹秋。
正宜清路望，潜起滴堦愁。
棹倚袁宏渚，帘垂庾亮楼。
桂无香实落，兰有露花休。
玉漏添萧索，金尊阻献酬。
明年佳景在，相约向神州。','',''),('quantangshi-37820','寄左省张起居','鄭谷','quantangshi','','卷38','含香复记言，清秩称当年。
点笔非常笔，朝天最近天。
家声三相后，公事一人前。
诗句江郎伏，书踪甯氏传。
风标欺鹭鹤，才力涌沙泉。
居僻贫无虑，名高退更坚。
渔舟思静泛，僧榻寄闲眠。
消息当弥入，丝纶的粲然。
依栖常接迹，属和旧盈编。
开口人皆信，凄凉是谢毡。','',''),('quantangshi-37821','前寄左省张起居一百言寻蒙唱酬见誉过实却用旧韵重答','鄭谷','quantangshi','','卷38','减瘦经多难，忧伤集晚年。
吟高风过树，坐久夜凉天。
旅退慙随众，孤飞怯向前。
钓朋蓑叟在，药术衲僧传。
鬓秃趋荣路，肠焦鄙盗泉。
品徒诚有隔，推唱意何坚。
寒地殊知感，秋灯耿不眠。
从来甘默尔，自此倍怡然。
兰为官须握，蒲因学更编。
预愁摇落后，子美笑无毡。','',''),('quantangshi-37822','读故许昌薛尚书诗集','鄭谷','quantangshi','','卷38','篇篇高且真，真为国风陈。
澹薄虽师古，纵横得意新。
翦裁成几箧，唱和是谁人。
华岳题无敌，黄河句绝伦。
吟残荔枝雨，咏彻海棠春。
李白欺前辈，陶潜仰后尘。
难忘嵩室下，不负蜀江滨。
属思看山眼，冥搜倚树身。
楷模劳梦想，讽诵爽精神。
落笔空追怆，曾蒙借斧斤。','',''),('quantangshi-37823','送水部张郎中彦回宰洛阳','鄭谷','quantangshi','','卷38','何逊兰休握，陶潜柳正垂。
官清真塞诏，事简好吟诗。
春漏怀丹阙，凉船泛碧伊。
已虚西阁位，朝夕凤书追。','',''),('quantangshi-37824','赠咸阳王主簿','鄭谷','quantangshi','','卷38','可爱咸阳王主簿，穷经尽到昔贤心。
登科未足酬多学，执卷犹闻惜寸阴。
自与山妻舂斗粟，祗凭邻叟典孤琴。
我来赊酒相留宿，听我披衣看雪吟。','',''),('quantangshi-37825','松','鄭谷','quantangshi','','卷38','下视垂杨拂路尘，双峰石上覆苔文。
浓霜满迳无红叶，晚日高枝有白云。
春砌花飘僧旋扫，寒溪子落鹤先闻。
那堪寂寞悲风起，千树深藏李白坟。','',''),('quantangshi-37826','梅','鄭谷','quantangshi','','卷38','江国正寒春信稳，岭头枝上雪飘飘。
何言落处堪惆怅，直是开时也寂寥。
素艳照尊桃莫比，孤香黏袖李须饶。
离人南去肠应断，片片随鞭过楚桥。','',''),('quantangshi-37827','鹤','鄭谷','quantangshi','','卷38','一自王乔放自由，俗人行处嬾回头。
睡轻旋觉松花堕，舞罢闲听涧水流。
羽翼光明欺积雪，风神洒落占高秋。
应嫌白鹭无仙骨，长伴渔翁宿苇洲。','',''),('quantangshi-37828','重阳夜旅怀','鄭谷','quantangshi','','卷38','强插黄花三两枝，还图一醉浸愁眉。
半牀斜月醉醒后，惆怅多于未醉时。','',''),('quantangshi-37829','壬戌西幸后','鄭谷','quantangshi','','卷38','武德门前颢气新，雪融鸳瓦土膏春。
夜来梦到宣麻处，草没龙墀不见人。','',''),('quantangshi-37830','多虞','鄭谷','quantangshi','','卷38','多虞难住人稀处，近耗浑无战罢碁。
向阙归山俱未得，且沽春酒且吟诗。','',''),('quantangshi-37831','短褐','鄭谷','quantangshi','','卷38','闲披短褐杖山藤，头不是僧心是僧。
坐睡觉来清夜半，芭蕉影动道场灯。','',''),('quantangshi-37832','曲江红杏','鄭谷','quantangshi','','卷38','遮莫江头柳色遮，日浓莺睡一枝斜。
女郎折得殷勤看，道是春风及第花。','',''),('quantangshi-37833','折得梅','鄭谷','quantangshi','','卷38','寒步江村折得梅，孤香不肯待春催。
满枝尽是愁人泪，莫殢朝来露湿来。','',''),('quantangshi-37834','牡丹','鄭谷','quantangshi','','卷38','画堂帘卷张清宴，含香带雾情无限。
春风爱惜未放开，柘枝鼓振红英绽。','',''),('quantangshi-37835','寂寞','鄭谷','quantangshi','','卷38','江郡人稀便是村，踏青天气欲黄昏。
春愁不破还成醉，衣上泪痕和酒痕。','',''),('quantangshi-37836','乱后灞上','鄭谷','quantangshi','','卷38','柳丝牵水杏房红，烟岸人稀草色中。
日暮一行高鸟处，依稀合是望春宫。','',''),('quantangshi-37837','长门怨二首 一','鄭谷','quantangshi','','卷38','闲把罗衣泣凤皇，先朝曾教舞霓裳。
春来却羡庭花落，得逐晴风出禁墙。','',''),('quantangshi-37838','长门怨二首 二','鄭谷','quantangshi','','卷38','流水君恩共不回，杏花争忍扫成堆。
残春未必多烟雨，泪滴闲堦长绿苔。','',''),('quantangshi-37839','郊野戏题','鄭谷','quantangshi','','卷38','竹巷溪桥天气凉，荷开稻熟村酒香。
唯忧野叟相回避，莫道侬家是汉郎。','',''),('quantangshi-37840','宗人惠四药','鄭谷','quantangshi','','卷38','宗人忽惠西山药，四味清新香助茶。
爽得心神便骑鹤，何须烧得白朱砂。','',''),('quantangshi-37841','题张衡庙','鄭谷','quantangshi','','卷38','远俗只凭淫祀切，多年平子固悠悠。
江烟日午无箫鼓，直到如今咏四愁。','',''),('quantangshi-37842','山鸟','鄭谷','quantangshi','','卷38','惊飞失势粉墙高，好个声音好羽毛。
小婢不须催柘弹，且从枝上吃樱桃。','',''),('quantangshi-37843','黯然','鄭谷','quantangshi','','卷38','搢绅奔避复沦亡，消息春来到水乡。
屈指故人能几许，月明花好更悲凉。','',''),('quantangshi-37844','借薛尚书集','鄭谷','quantangshi','','卷38','江天冬暖似花时，上国音尘杳未知。
正被虫声喧老耳，今君又借薛能诗。','',''),('quantangshi-37845','小北廰闲题','鄭谷','quantangshi','','卷38','冷曹孤宦本相宜，山在墙南落照时。
洗竹浇莎足公事，一来赢写一联诗。','',''),('quantangshi-37846','菊','鄭谷','quantangshi','','卷38','日日池边载酒行，黄昏犹自遶黄英。
重阳过后频来此，甚觉多情胜薄情。','',''),('quantangshi-37847','赠杨夔二首 一','鄭谷','quantangshi','','卷38','散赋宂书高且奇，百篇仍有百篇诗。
江湖休洒春风泪，十轴香于一桂枝。','',''),('quantangshi-37848','赠杨夔二首 二','鄭谷','quantangshi','','卷38','时无韩柳道难穷，也觉天公不至公。
看取年年金牓上，几人才气似扬雄。','',''),('quantangshi-37849','中秋夜有怀','許彬','quantangshi','','卷38','趋驰早晚休，一岁又残秋。
若只如今日，何难致白头。
沧波归处远，旅舍向边愁。
赖见前贤说，穷通不自由。','',''),('quantangshi-37850','寻白石山人涧','許彬','quantangshi','','卷38','路穷川岛上，果值古仙家。
阴洞长鸣磬，石泉寒泛花。
莓苔深峭壁，烟霭积层崖。
难见囊中术，人间有岁华。','',''),('quantangshi-37851','游头陀寺上方','許彬','quantangshi','','卷38','高步陟崔嵬，吟闲路惜回。
寺从何代有，僧是梵宫来。
暮霭连沙积，余霞逼槛开。
更期招静者，长啸上方台。','',''),('quantangshi-37852','归山夜发湖中','許彬','quantangshi','','卷38','广泽去无边，夜程风信偏。
疎星遥抵浪，远烧似迎船。
响岳猿相次，翻空雁接连。
北归家业就，深处更逾年。','',''),('quantangshi-37853','同友人会裴明府县楼','許彬','quantangshi','','卷38','开阁雨吹尘，陶家揖上宾。
湖山万叠翠，汀树一行春。
景逼归檐燕，歌喧已醉身。
登临兴未足，喜有数年因。','',''),('quantangshi-37854','荆山夜泊与亲友遇','許彬','quantangshi','','卷38','山海两分歧，停舟偶此期。
别来何限意，相见却无词。
坐永神疑梦，愁多鬓欲丝。
趋名易迟晚，此去莫经时。','',''),('quantangshi-37855','北游夜怀','許彬','quantangshi','','卷38','苦心终是否，舍此复无营。
已致归成晚，非缘去有程。
馆空吟向月，霜曙坐闻更。
住久谁相问，驰羸又独行。','',''),('quantangshi-37856','重经汉南','許彬','quantangshi','','卷38','分散多如此，人情岂自由。
重来看月夕，不似去年秋。
息虑虽孤寝，论空未识愁。
须同醉乡者，万事付江流。','',''),('quantangshi-37857','湘江','許彬','quantangshi','','卷38','孤舟方此去，嘉景称于闻。
烟尽九峰雪，雨生诸派云。
沙寒鸿鹄聚，底极龟鱼分。
异日谁为侣，逍遥耕钓羣。','',''),('quantangshi-37858','黔中书事','許彬','quantangshi','','卷38','巴蜀水南偏，山穷塞垒宽。
岁时将近腊，草树未知寒。
独狖啼朝雨，羣牛向暮滩。
更闻蛮俗近，烽火不艰难。','',''),('quantangshi-37859','经李翰林庐山屏风叠所居','許彬','quantangshi','','卷38','放逐非多罪，江湖偶不廻。
深居应有谓，济代岂无才。
叠巘晴舒障，寒川暗动雷。
谁能续高兴，醉死一千杯。','',''),('quantangshi-37860','酬简寂熊尊师以赵员外庐山草堂见借','許彬','quantangshi','','卷38','岂易投居止，庐山得此峰。
主人曾已许，仙客偶相逢。
顾己恩难答，穷经业未慵。
还能励僮仆，稍更补杉松。','',''),('quantangshi-37861','寄怀孙处士','許彬','quantangshi','','卷38','生平酌与吟，谁是见君心。
上国一归去，沧波闲至今。
钟繁秋寺远，岸阔晚涛深。
疎放长如此，何人更得寻。','',''),('quantangshi-37862','汉南怀友人','許彬','quantangshi','','卷38','此身西复东，何计此相逢。
梦尽吴越水，恨深湘汉钟。
积云开去路，曙雪叠前峰。
谁即知非旧，怜君忽见容。','',''),('quantangshi-37863','送人下第归江州','許彬','quantangshi','','卷38','名高不俟召，操赋献君门。
偶屈应缘数，他人尽为冤。
新春城外路，旧隐水边村。
归去无劳久，知音待更论。','',''),('quantangshi-37864','送苏处士归西山','許彬','quantangshi','','卷38','南游何所为，一箧又空归。
守道安清世，无心换白衣。
深溪猿共暮，绝顶客来稀。
早晚还相见，论诗更及微。','',''),('quantangshi-37865','送李处士归山','許彬','quantangshi','','卷38','旧山来复去，不与世人论。
得道书留箧，忘机酒满尊。
溪轩松偃坐，石室水临门。
应有频相访，相看坐到昏。','',''),('quantangshi-37866','送新罗客归','許彬','quantangshi','','卷38','君家沧海外，一别见何因。
风土难知教，程途自致贫。
浸天波色晚，横吹鸟行春。
明发千樯下，应为更远人。','',''),('quantangshi-37867','府试莱城晴日望三山','許彬','quantangshi','','卷38','不易识蓬瀛，凭高望有程。
盘根出巨浸，远色到孤城。
隐隐排云峻，层层就日明。
净收残霭尽，浮动嫩岚轻。
纵目徒多暇，驰心累发诚。
从容更何往，此路彻三清。','',''),('quantangshi-37868','题故李宾客庐山草堂','許彬','quantangshi','','卷38','难穷林下趣，坐使致君恩。
术业行当代，封章动谏垣。
已明邪佞迹，几雪薜萝冤。
报主深知此，忧民讵可论。
名将山共古，迹与道俱存。
为谢重来者，何人更及门。','',''),('quantangshi-37869','秋夕送友人归吴','崔塗','quantangshi','','卷38','离心醉岂懽，把酒彊相宽。
世路须求达，还家亦未安。
旅程愁算远，江月坐吟残。
莫羡扁舟兴，功成去不难。','',''),('quantangshi-37870','长安逢江南僧','崔塗','quantangshi','','卷38','孤云无定踪，忽到又相逢。
说尽天涯事，听残上国钟。
问人寻寺僻，乞食过街慵。
忆到曾栖处，开门对数峰。','',''),('quantangshi-37871','晚次修路僧','崔塗','quantangshi','','卷38','平尽不平处，尚嫌功未深。
应难将世路，便得称师心。
高鸟下残照，白烟生远林。
更闻清磬发，聊喜缓尘襟。','',''),('quantangshi-37872','湖外送友人游边','崔塗','quantangshi','','卷38','我泛潇湘浦，君行指塞云。
两乡天外隔，一径渡头分。
雨暗江花老，笳愁陇月曛。
不堪来去雁，迢递思离羣。','',''),('quantangshi-37873','读段太尉碑','崔塗','quantangshi','','卷38','愤激计潜成，临危岂顾生。
秪空持一笏，便欲碎长鲸。
国已酬徽烈，家犹耸义声。
不知青史上，谁可计功名。','',''),('quantangshi-37874','夕次洛阳道中','崔塗','quantangshi','','卷38','秋风吹故城，城下独吟行。
高树鸟已息，古原人尚耕。
流年川暗度，往事月空明。
不复叹岐路，马前尘夜生。','',''),('quantangshi-37875','读方干诗因怀别业','崔塗','quantangshi','','卷38','把君诗一吟，万里见君心。
华发新知少，沧洲旧隐深。
潮冲虚阁上，山入暮窗沈。
忆宿高斋夜，庭枝识海禽。','',''),('quantangshi-37876','题嵩阳隐者','崔塗','quantangshi','','卷38','四十年高梦，生涯指一丘。
无人同久住，有鹤对冥修。
草杂芝田出，泉和石髓流。
更嫌庭树老，疑是世间秋。','',''),('quantangshi-37877','友人问卜见招','崔塗','quantangshi','','卷38','何必问蓍龟，行藏自可期。
但逢公道日，即是命通时。
乐善知无厌，操心幸不欺。
岂能花下泪，长似去年垂。','',''),('quantangshi-37878','江行晚望','崔塗','quantangshi','','卷38','木落曙江晴，寒郊极望平。
孤舟三楚去，万里独吟行。
鸟占横查立，人当故里耕。
十年来复去，不觉二毛生。','',''),('quantangshi-37879','巫山庙','崔塗','quantangshi','','卷38','双黛俨如嚬，应伤故国春。
江山非旧主，云雨是前身。
梦觉传词客，灵犹福楚人。','',''),('quantangshi-37880','秋夕与友人话别','崔塗','quantangshi','','卷38','怀君非一夕，此夕倍堪悲。
华发犹漂泊，沧洲又别离。
冷禽栖不定，衰叶堕无时。
况值干戈隔，相逢未可期。','',''),('quantangshi-37881','与友人同怀江南别业','崔塗','quantangshi','','卷38','因君话故国，此夕倍依依。
旧业临秋水，何人在钓矶。
浮名如纵得，沧海亦终归。
却是风尘里，如何便息机。','',''),('quantangshi-37882','苦吟','崔塗','quantangshi','','卷38','朝吟复暮吟，只此望知音。
举世轻孤立，何人念苦心。
他乡无旧识，落日羡归禽。
况住寒江上，渔家似故林。','',''),('quantangshi-37883','春日郊居酬友人见贻','崔塗','quantangshi','','卷38','荒斋原上掩，不出动经旬。
忽觉草木变，始知天地春。
方期五字达，未厌一箪贫。
丽句劳相勉，余非乐钓纶。','',''),('quantangshi-37884','问卜','崔塗','quantangshi','','卷38','承家望一名，几欲问君平。
自小非无志，何年即有成。
岂能长失路，争忍学归耕。
不拟逢昭代，悠悠过此生。','',''),('quantangshi-37885','蜀城春','崔塗','quantangshi','','卷38','天涯憔悴身，一望一霑巾。
在处有芳草，满城无故人。
怀才皆得路，失计自伤春。
清镜不能照，鬓毛愁更新。','',''),('quantangshi-37886','送道士于千龄游南岳','崔塗','quantangshi','','卷38','物外与谁期，人间又别离。
四方多事日，高岳独游时。
猨狖潇湘树，烟波屈宋祠。
无因陪此去，空惜鬓将衰。','',''),('quantangshi-37887','入蜀赴举秋夜与先生话别','崔塗','quantangshi','','卷38','欲怆峨嵋别，中宵寝不能。
听残池上雨，吟尽枕前灯。
失计方期隐，修心未到僧。
云门一万里，应笑又担簦。','',''),('quantangshi-37888','春晚怀进士韦澹','崔塗','quantangshi','','卷38','故里花应尽，江楼梦尚残。
半生吟欲过，一命达何难。
特立圭无玷，相思草有兰。
二年春怅望，不似在长安。','',''),('quantangshi-37889','言怀','崔塗','quantangshi','','卷38','干时虽苦节，趋世且无机。
及觉知音少，翻疑所业非。
青云如不到，白首亦难归。
所以沧江上，年年别钓矶。','',''),('quantangshi-37890','秋夜兴上人别','崔塗','quantangshi','','卷38','常时岂不别，此别异常情。
南国初闻雁，中原未息兵。
暗蛩侵语歇，疎磬入吟清。
曾听无生说，辞师话此行。','',''),('quantangshi-37891','感花','崔塗','quantangshi','','卷38','绣轭香鞯夜不归，少年争惜最红枝。
东风一阵黄昏雨，又到繁华梦觉时。','',''),('quantangshi-37892','秋宿天彭僧舍','崔塗','quantangshi','','卷38','身世两相惜，秋云每独兴。
难将尘界事，话向雪山僧。
力善知谁许，归耕又未能。
此怀平不得，挑尽草堂灯。','',''),('quantangshi-37893','秋夜僧舍闻猨','崔塗','quantangshi','','卷38','哀猨听未休，禅景夜方幽。
暂得同僧静，那能免客愁。
影摇云外树，声褭月中秋。
曾向巴江宿，当时泪亦流。','',''),('quantangshi-37894','过昭君故宅','崔塗','quantangshi','','卷38','以色静胡尘，名还异众嫔。
免劳征战力，无愧绮罗身。
骨竟埋青冢，魂应怨画人。
不堪逢旧宅，寥落对江滨。','',''),('quantangshi-37895','过洛阳故城','崔塗','quantangshi','','卷38','三十世皇都，萧条是霸图。
片墙看破尽，遗迹渐应无。
野径通荒苑，高槐映远衢。
独吟人不问，清冷自呜呜。','',''),('quantangshi-37896','秋夕与友人同会','崔塗','quantangshi','','卷38','章句积微功，星霜二十空。
僻应如我少，吟喜得君同。
月上僧归后，诗成客梦中。
更闻栖鹤警，清露滴青松。','',''),('quantangshi-37897','春日登吴门','崔塗','quantangshi','','卷38','故国望不见，愁襟难暂开。
春潮映杨柳，细雨入楼台。
静少人同到，晴逢雁正来。
长安远于日，搔首独徘徊。','',''),('quantangshi-37898','湘中秋怀迁客','崔塗','quantangshi','','卷38','兰杜晓香薄，汀洲夕露繁。
并闻燕塞雁，独立楚人村。
雾散孤城上，滩回曙枕喧。
不堪逢贾傅，还欲吊湘沅。','',''),('quantangshi-37899','南山旅舍与故人别','崔塗','quantangshi','','卷38','一日又将暮，一年看即残。
病知新事少，老别旧交难。
山尽路犹险，雨余春却寒。
那堪试回首，烽火是长安。','',''),('quantangshi-37900','东林愿禅师院','崔塗','quantangshi','','卷38','与世渐无缘，身心独了然。
讲销林下日，腊长定中年。
磬绝朝斋后，香焚古寺前。
非因送小朗，不到虎溪边。','',''),('quantangshi-37901','孤雁 一','崔塗','quantangshi','','卷38','湘浦离应晚，边城去已孤。
如何万里计，只在一枝芦。
迥起波摇楚，寒栖月映蒲。','',''),('quantangshi-37902','孤雁 二','崔塗','quantangshi','','卷38','几行归去尽，片影独何之。
暮雨相呼失，寒塘独下迟。
渚云低暗度，关月冷遥随。
未必逢矰缴，孤飞自可疑。','',''),('quantangshi-37903','寄青城山颢禅师','崔塗','quantangshi','','卷38','怀师不可攀，师往杳冥间。
林下谁闻法，尘中只见山。
终年人不到，尽日鸟空还。
曾听无生说，应怜独未还。','',''),('quantangshi-37904','秋夕与王处士话别','崔塗','quantangshi','','卷38','微灯照寂寥，此夕正迢迢。
丹桂得已晚，故山归尚遥。
虫声移暗壁，月色动寒条。
此去如真隐，期君试一瓢。','',''),('quantangshi-37905','秋日犍为道中','崔塗','quantangshi','','卷38','久客厌岐路，出门吟且悲。
平生未到处，落日独行时。
芳草不长绿，故人无重期。
那堪更南渡，乡国已天涯。','',''),('quantangshi-37906','送僧归江东','崔塗','quantangshi','','卷38','坐彻秦城夏，行登越客船。
去留那有着，语默不离禅。
叶拥临关路，霞明近海天。
更寻同社侣，应得虎溪边。','',''),('quantangshi-37907','喜友人及第','崔塗','quantangshi','','卷38','孤吟望至公，已老半生中。
不有同人达，兼疑此道穷。
只应才自薄，岂是命难通。
尚激抟溟势，期君借北风。','',''),('quantangshi-37908','上巳日永崇里言怀','崔塗','quantangshi','','卷38','未敢分明赏物华，十年如见梦中花。
游人过尽衡门掩，独自凭栏到日斜。','',''),('quantangshi-37909','送僧归天竺','崔塗','quantangshi','','卷38','忽忆曾栖处，千峰近沃州。
别来秦树老，归去海门秋。
汲带寒汀月，禅隣贾客舟。
遥思清兴惬，不厌石林幽。','',''),('quantangshi-37910','牛渚夜泊','崔塗','quantangshi','','卷38','烟老石矶平，袁郎夜泛情。
数吟人不遇，千古月空明。
人事年年别，春潮日日生。
无因逢谢尚，风物自凄清。','',''),('quantangshi-37911','送友人归江南','崔塗','quantangshi','','卷38','渚田芳草徧，共忆故山春。
独往沧洲暮，相看白发新。
定过林下寺，应见社中人。
只恐东归后，难将鸥鸟亲。','',''),('quantangshi-37912','过陶征君隐居','崔塗','quantangshi','','卷38','陶令昔居此，弄琴遗世荣。
田园三亩绿，轩冕一铢轻。
衰柳自无主，白云犹可耕。
不随陵谷变，应只有高名。','',''),('quantangshi-37913','江上旅泊','崔塗','quantangshi','','卷38','汀洲一夜泊，久客半连樯。
尽说逢秋色，多同忆故乡。
孤冈生晚烧，独树隐回塘。
欲问东归路，遥知隔渺茫。','',''),('quantangshi-37914','灞上','崔塗','quantangshi','','卷38','长安名利路，役役古田今。
征骑少闲日，绿杨无旧阴。
水侵秦甸阔，草接汉陵深。
紫阁曾过处，依稀白鸟沈。','',''),('quantangshi-37915','寄舅','崔塗','quantangshi','','卷38','中朝轩冕内，久绝甯家亲。
白社同孤立，青云独并伸。
致君期折槛，举职在埋轮。
须信尧庭草，犹能指佞人。','',''),('quantangshi-37916','赠休粮僧','崔塗','quantangshi','','卷38','闻钟独不斋，何事更关怀。
静少人过院，闲从草上堦。
生台无鸟下，石路有云埋。
为忆禅中旧，时犹梦百崖。','',''),('quantangshi-37917','题绝岛山寺','崔塗','quantangshi','','卷38','绝岛跨危栏，登临到此难。
夕阳高鸟过，疎雨一钟残。
骇浪摇空阔，灵山厌渺漫。
那堪更回首，乡树隔云端。','',''),('quantangshi-37918','读侯道华真人传','崔塗','quantangshi','','卷38','汉皇轻万乘，方士说三丹。
不得修心要，翻知出世难。
茂陵春竟绿，金掌曙空寒。
何似先生去，翩翩逐彩鸾。','',''),('quantangshi-37919','残花','崔塗','quantangshi','','卷38','迟迟傍晓阴，昨夜色犹深。
毕竟终须落，堪悲古与今。
明年何处见，尽日此时心。
蜂蝶无情极，残香更不寻。','',''),('quantangshi-37920','题兴善寺隋松院与人期不至','崔塗','quantangshi','','卷38','青青伊涧松，移植在莲宫。
藓色前朝雨，秋声半夜风。
长闲应未得，暂赏亦难同。
不及禅栖者，相看老此中。','',''),('quantangshi-37921','樵者','崔塗','quantangshi','','卷38','行山行采薇，闲翦蕙为衣。
避世嫌山浅，逢人说姓稀。
有时还独醉，何处掩衡扉？
莫看棋终局，溪风晚待归。','',''),('quantangshi-37922','南涧耕叟','崔塗','quantangshi','','卷38','年年南涧滨，力尽志犹存。
雨雪朝耕苦，桑麻岁计贫。
战添丁壮役，老忆太平春。
见说经荒后，田园半属人。','',''),('quantangshi-37923','春日闲居忆江南旧业','崔塗','quantangshi','','卷38','杜门朝复夕，岂是解谋身。
梦不离泉石，林唯称隐沦。
渐谙浮世事，转忆故山春。
南国水风暖，又应生白苹。','',''),('quantangshi-37924','屈原庙','崔塗','quantangshi','','卷38','谗胜祸难防，沈冤信可伤。
本图安楚国，不是怨怀王。
庙古碑无字，洲晴蕙有香。
独醒人尚笑，谁与奠椒浆。','',''),('quantangshi-37925','宿庐山绝顶山舍','崔塗','quantangshi','','卷38','一磴出林端，千峰次第看。
长闲如未遂，暂到亦应难。
谷树云埋老，僧窗瀑影寒。
自嫌心不达，向此梦长安。','',''),('quantangshi-37926','王逸人隐居','崔塗','quantangshi','','卷38','一径入千岑，幽人许重寻。
不逢秦世乱，未觉武陵深。
石转生寒色，云归带夕阴。
却愁危坐久，看尽暝栖禽。','',''),('quantangshi-37927','申州道中','崔塗','quantangshi','','卷38','风紧日凄凄，乡心向此迷。
水分平楚阔，山接故关低。
客路缘烽火，人家厌鼓鼙。
那堪独驰马，江树穆陵西。','',''),('quantangshi-37928','江上怀翠微寺空上人','崔塗','quantangshi','','卷38','旅泛本无定，相逢那可期。
空怀白阁夜，未答碧云诗。
暮雨潮生早，春寒雁到迟。
所思今不见，乡国正天涯。','',''),('quantangshi-37929','秋宿鹤林寺','崔塗','quantangshi','','卷38','步步入林中，山穷意未穷。
偏逢僧话久，转与鹤栖同。
烛焰风销尽，兰条露湿空。
又须从此别，江上正秋鸿。','',''),('quantangshi-37930','远望','崔塗','quantangshi','','卷38','长为乡思侵，望极即霑襟。
不是前山色，能伤愁客心。
平芜连海尽，独树隐云深。
况复斜阳外，分明有去禽。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-37931','秋晚书怀','崔塗','quantangshi','','卷38','看看秋色晚，又是出门时。
白发生非早，青云去自迟。
梦唯怀上国，迹不到他岐。
以此坚吾道，还无愧已知。','',''),('quantangshi-37932','途中秋晚送友人归江南','崔塗','quantangshi','','卷38','又指烟波算路岐，此生多是厌羇离。
正逢摇落仍须别，不待登临已合悲。
里巷半空兵过后，水云初冷雁来时。
扁舟未得如君去，空向沧江梦所思。','',''),('quantangshi-37933','己亥岁感事','崔塗','quantangshi','','卷38','正闻青犊起葭萌，又报黄巾犯汉营。
岂是将皆无上略，直疑天自弃苍生。
瓜沙旧戍犹传檄，吴楚新春已废耕。
见说圣君能仄席，不知谁是请长缨。','',''),('quantangshi-37934','金陵晚眺','崔塗','quantangshi','','卷38','苇声骚屑水天秋，吟对金陵古渡头。
千古是非输蝶梦，一轮风雨属渔舟。
若无仙分应须老，幸有归山即合休。
何必登临更惆怅，比来身世只如浮。','',''),('quantangshi-37935','过长江贾岛主簿旧厅','崔塗','quantangshi','','卷38','雕琢文章字字精，我经此处倍伤情。
身从谪宦方霑禄，才被槌埋更有声。
过县已无曾识吏，到厅空见旧题名。
长江一曲年年水，应为先生万古清。','',''),('quantangshi-37936','途中感怀寄青城李明府','崔塗','quantangshi','','卷38','鳞鬣催残志未休，壮心飜是此身讐。
并闻寒雨多因夜，不得乡书又到秋。
耕钓旧交吟好忆，雪霜危栈去堪愁。
如何只是三年别，君着朱衣我白头。','',''),('quantangshi-37937','夏日书怀寄道友','崔塗','quantangshi','','卷38','达即匡邦退即耕，是非何足挠平生。
终期道向希夷得，未省心因宠辱惊。
峰转暂无当户影，雉飞时有隔林声。
十年惟悟吟诗句，待得中原欲铸兵。','',''),('quantangshi-37938','和进士张曙闻雁见寄','崔塗','quantangshi','','卷38','断行哀响递相催，争趁高秋作恨媒。
云外关山闻独去，渡头风雨见初来。
也知榆塞寒须别，莫恋苹汀暖不回。
试向富春江畔过，故园犹合有池台。','',''),('quantangshi-37939','鹦鹉洲即事','崔塗','quantangshi','','卷38','怅望春襟郁未开，重吟鹦鹉益堪哀。
曹瞒尚不能容物，黄祖何曾解爱才。
幽岛暖闻燕雁去，晓江晴觉蜀波来。
何人正得风涛便，一点轻帆万里回。','',''),('quantangshi-37940','读留侯传','崔塗','quantangshi','','卷38','覆楚讐韩势有余，男儿遭遇更难如。
偶成汉室千年业，只读圯桥一卷书。
翻把壮心轻尺组，却烦商皓正皇储。
若能终始匡天子，何必□□□□□。','',''),('quantangshi-37941','赤壁怀古','崔塗','quantangshi','','卷38','汉室河山鼎势分，勤王谁肯顾元勋。
不知征伐由天子，唯许英雄共使君。
江上战余陵是谷，渡头春在草连云。
分明胜败无寻处，空听渔歌到夕曛。','',''),('quantangshi-37942','东晋 一','崔塗','quantangshi','','卷38','五陵豪侠笑为儒，将为儒生只读书。
看取不成投笔后，谢安功业复何如。','',''),('quantangshi-37943','东晋 二','崔塗','quantangshi','','卷38','秦国金陵王气全，一龙正道始东迁。
兴亡竟不关人事，虚倚长淮五百年。','',''),('quantangshi-37944','春夕','崔塗','quantangshi','','卷38','水流花谢两无情，送尽东风过楚城。
胡蝶梦中家万里，子规枝上月三更。
故园书动经年绝，华发春唯满镜生。
自是不归归便得，五湖烟景有谁争。','',''),('quantangshi-37945','涧松','崔塗','quantangshi','','卷38','寸寸凌霜长劲条，路人犹笑未干霄。
南园桃李虽堪羡，争奈春残又寂寥。','',''),('quantangshi-37946','湘中弦 一','崔塗','quantangshi','','卷38','苍山遥遥江潾潾，路傍老尽没闲人。
王孙不见草空绿，惆怅渡头春复春。','',''),('quantangshi-37947','湘中弦 二','崔塗','quantangshi','','卷38','烟愁雨细云冥冥，杜兰香老三湘清。
故山望断不知处，鶗鴂隔花时一声。','',''),('quantangshi-37948','续纪汉武','崔塗','quantangshi','','卷38','分明三鸟下储胥，一觉钧天梦不如。
争那白头方士到，茂陵红叶已萧疎。','',''),('quantangshi-37949','陇上逢江南故人','崔塗','quantangshi','','卷38','三声戍角边城暮，万里乡心塞草春。
莫学少年轻远别，陇关西少向东人。','',''),('quantangshi-37950','夷陵夜泊','崔塗','quantangshi','','卷38','家依楚塞穷秋别，身逐孤舟万里行。
一曲巴歌半江月，便应消得二毛生。','',''),('quantangshi-37951','橹声','崔塗','quantangshi','','卷38','烟外桡声远，天涯幽梦回。
争知江上客，不是故乡来。','',''),('quantangshi-37952','海棠图','崔塗','quantangshi','','卷38','海棠花底三年客，不见海棠花盛开。
却向江南看图画，始慙虚到蜀城来。','',''),('quantangshi-37953','云','崔塗','quantangshi','','卷38','得路直为霖济物，不然闲共鹤忘机。
无端却向阳台畔，长送襄王暮雨归。','',''),('quantangshi-37954','过二妃庙','崔塗','quantangshi','','卷38','残阳楚水畔，独吊舜时人。
不及庙前草，至今江上春。','',''),('quantangshi-37955','送友人','崔塗','quantangshi','','卷38','登高迎送远，春恨并依依。
不得沧洲信，空看白鹤归。','',''),('quantangshi-37956','声','崔塗','quantangshi','','卷38','欢戚犹来恨不平，此中高下本无情。
韩娥绝唱唐衢哭，尽是人间第一声。','',''),('quantangshi-37957','放鹧鸪','崔塗','quantangshi','','卷38','秋入池塘风露微，晓开笼槛看初飞。
满身金翠画不得，无限烟波何处归。','',''),('quantangshi-37958','泉','崔塗','quantangshi','','卷38','远辞岩窦泻潺潺，静拂云根别故山。
可惜寒声留不得，旋添波浪向人间。','',''),('quantangshi-37959','巫山旅别','崔塗','quantangshi','','卷38','五千里外三年客，十二峰前一望秋。
无限别魂招不得，夕阳西下水东流。','',''),('quantangshi-37960','幽兰','崔塗','quantangshi','','卷38','幽植众宁知，芬芳只暗持。
自无君子佩，未是国香衰。
白露霑长草，春风到每迟。
不如当路草，芬馥欲何为。','',''),('quantangshi-37961','读庾信集','崔塗','quantangshi','','卷38','四朝十帝尽风流，建业长安两醉游。
唯有一篇杨柳曲，江南江北为君愁。','',''),('quantangshi-37962','过绣岭宫','崔塗','quantangshi','','卷38','古殿春残绿野阴，上皇曾此驻泥金。
三城帐属升平梦，一曲铃关怅望心。
苑路暗迷香辇绝，缭垣秋断草烟深。
前朝旧物东流在，犹为年年下翠岑。','',''),('quantangshi-37963','巴山道中除夜书怀','崔塗','quantangshi','','卷38','迢遰三巴路，羇危万里身。
乱山残雪夜，孤烛异乡春。
渐与骨肉远，转于僮仆亲。
那堪正漂泊，明日岁华新。','',''),('quantangshi-37964','题净众寺古松','崔塗','quantangshi','','卷38','百尺森疎倚梵台，昔人谁见此初栽。
故园未有偏堪恋，浮世如闲即合来。
天暝岂分苍翠色，岁寒应识栋梁材。
清阴可惜不驻得，归去暮城空首回。','',''),('quantangshi-37965','折杨柳','崔塗','quantangshi','','卷38','朝朝车马如蓬转，处处江山待客归。
若使人间少离别，杨花应合过春飞。','',''),('quantangshi-37966','七夕','崔塗','quantangshi','','卷38','年年七夕渡瑶轩，谁道秋期有泪痕。
自是人间一周岁，何妨天上只黄昏。','',''),('quantangshi-37967','泛楚江','崔塗','quantangshi','','卷38','九重城外家书远，百里洲前客棹还。
金印碧幢如见问，一生安稳是长闲。','',''),('quantangshi-37968','初过汉江','崔塗','quantangshi','','卷38','襄阳好向岘亭看，人物萧条值岁阑。
为报习家多置酒，夜来风雪过江寒。','',''),('quantangshi-37969','题授阳镇路','崔塗','quantangshi','','卷38','越鸟巢边溪路断，秦人耕处洞门开。
小桃花发春风起，千里江山一梦回。','',''),('quantangshi-37970','初识梅花','崔塗','quantangshi','','卷38','江北不如南地暖，江南好断北人肠。
燕脂桃颊棃花粉，共作寒梅一面妆。','',''),('quantangshi-37971','江雨望花','崔塗','quantangshi','','卷38','细雨满江春水涨，好风留客野梅香。
避秦不是无归意，一度逢花一断肠。','',''),('quantangshi-37972','雨后月中玉堂闲坐','韓偓','quantangshi','','卷38','银台直北金銮外，暑雨初晴皓月中。
唯对松篁听刻漏，更无尘土翳虚空。
绿香熨齿冰盘果，清冷侵肌水殿风。
夜久忽闻铃索动，玉堂西畔响丁东。','',''),('quantangshi-37973','六月十七日召对自辰及申方归本院','韓偓','quantangshi','','卷38','清[暑]帘开散异香，恩深咫尺对龙章。
花应洞里寻常发，日向壶中特地长。
坐久忽疑槎犯斗，归来兼恐海生桑。
如今冷笑东方朔，唯用诙谐侍汉皇。','',''),('quantangshi-37974','与吴子华侍郎同年玉堂同直怀恩叙恳因成长句四韵兼呈诸同年','韓偓','quantangshi','','卷38','往年莺谷接清尘，今日鳌山作侍臣。
二纪计偕劳笔研，一朝宣入掌丝纶。
声名烜赫文章士，金紫雍容富贵身。
绛帐恩深无路报，语余相顾却酸辛。','',''),('quantangshi-37975','和吴子华侍郎令狐昭化舍人叹白菊衰谢之绝次山本韵','韓偓','quantangshi','','卷38','正怜香雪披千片，忽讶残霞覆一丛。
还似妖姬长年后，酒酣双脸却微红。','',''),('quantangshi-37976','中秋禁直','韓偓','quantangshi','','卷38','星斗疎明禁漏残，紫泥封后独凭阑。
露和玉屑金盘冷，月射珠光贝阙寒。
天衬楼台笼苑外，风吹歌管下云端。
长卿秪为长门赋，未识君臣际会难。','',''),('quantangshi-37977','侍宴','韓偓','quantangshi','','卷38','蠭黄蝶粉两依依，狎宴临春日正迟。
密旨不教江令醉，丽华微笑认皇慈。','',''),('quantangshi-37978','锡宴日作','韓偓','quantangshi','','卷38','玉衔花马蹋香街，诏遣追欢绮席开。
中使押从天上去外人知自日边来。
臣心净比漪涟水，圣泽深于潋滟杯。
才有异恩颁稷契，已将优礼及邹枚。
清商适向棃园降，妙妓新行峡雨回。
不敢通宵离禁直，晚乘残醉入银台。','',''),('quantangshi-37979','宫柳','韓偓','quantangshi','','卷38','莫道秋来芳意违，宫娃犹似妒蛾眉。
幸当玉辇经过处，不怕金风浩荡时。
草色长承垂地叶，日华先动映楼枝。
涧松亦有凌云分，争似移根太液池。','',''),('quantangshi-37980','苑中','韓偓','quantangshi','','卷38','上苑离宫处处迷，相风高与露盘齐。
金阶铸出狻猊立，玉树雕成狒𤝞啼。
外使调鹰初得按，中官过马不教嘶。
笙歌锦绣云霄里，独许词臣醉似泥。','',''),('quantangshi-37981','从猎三首 一','韓偓','quantangshi','','卷38','猎犬谙斜路，宫嫔识认旗。
马前双兔起，宣尔羽林儿。','',''),('quantangshi-37982','从猎三首 二','韓偓','quantangshi','','卷38','小镫狭秋鞘，鞍轻妓细腰。
有时齐走马，也学唱交交。','',''),('quantangshi-37983','从猎三首 三','韓偓','quantangshi','','卷38','蹀躞巴陵骏，毰毸碧野鸡。
忽闻仙乐动，赐酒玉偏提。','',''),('quantangshi-37984','辛酉岁冬十一月随驾幸岐下作','韓偓','quantangshi','','卷38','曳裾谈笑殿西头，忽听征铙从冕旒。
凤盖行时移紫气，鸾旗驻处认皇州。
晓题御服颁羣吏，夜发宫嫔诏列侯。
雨露涵濡三百载，不知谁拟杀身酬。','',''),('quantangshi-37985','冬至夜作','韓偓','quantangshi','','卷38','中宵忽见动葭灰，料得南枝有早梅。
四野便应枯草绿，九重先觉冻云开。
阴冰莫向河源塞，阳气今从地底回。
不道惨舒无定分，却忧蚊响又成雷。','',''),('quantangshi-37986','秋霖夜忆家','韓偓','quantangshi','','卷38','垂老何时见弟兄，背灯愁泣到天明。
不知短发能多少，一滴秋霖白一茎。','',''),('quantangshi-37987','恩赐樱桃分寄朝士','韓偓','quantangshi','','卷38','未许莺偷出汉宫，上林初进半金笼。
蔗浆自透银杯冷，朱实相辉玉椀红。
俱有乱离终日恨，贵将滋味片时同。
霜威食檗应难近，宜在纱窗绣户中。','',''),('quantangshi-37988','出官经硖石县','韓偓','quantangshi','','卷38','谪宦过东畿，所抵州名濮。
故里欲清明，临风堪恸哭。
溪长柳似帷，山暖花如醭。
逆旅讶簪裾，野老悲陵谷。
暝鸟影连翩，惊狐尾纛簌。
尚得佐方州，信是皇恩沐。','',''),('quantangshi-37989','访同年虞部李郎中','韓偓','quantangshi','','卷38','策蹇相寻犯雪泥，厨烟未动日平西。
门庭野水䙰褷鹭，邻里短墙咿喔鸡。
未入庆霄君择肉，畏逢华毂我吹韲。
地炉贳酒成狂醉，更觉襟怀得丧齐。','',''),('quantangshi-37990','赠渔者','韓偓','quantangshi','','卷38','个侬居处近诛茅，枳棘篱兼用荻梢。
尽日风扉从自掩，无人筒钓是谁抛。
城方四面墙阴直，江阔中心水脉坳。
我亦好闲求老伴，莫嫌迁客且论交。','',''),('quantangshi-37991','春阴独酌寄同年虞部李郎中','韓偓','quantangshi','','卷38','春阴漠漠土脉润，春寒微微风意和。
闲嗤入甲奔竞态，醉唱落调渔樵歌。
诗道揣量疑可进，宦情刓缺转无多。
酒酣狂兴依然在，其奈千茎鬓雪何。','',''),('quantangshi-37992','奉和峡州孙舍人肇荆南重围中寄诸朝士二篇时李常侍洵严谏议龟李起居殷衡李郎中冉皆有继和余久有是债今至湖南方暇牵课 一','韓偓','quantangshi','','卷38','敏手何妨误汰金，敢怀私忿斅羊斟。
直应宣室还三接，未必丰城便陆沈。
炽炭一炉真玉性，浓霜千涧老松心。
私恩尚有捐驱誓，况是君恩万倍深。','',''),('quantangshi-37993','奉和峡州孙舍人肇荆南重围中寄诸朝士二篇时李常侍洵严谏议龟李起居殷衡李郎中冉皆有继和余久有是债今至湖南方暇牵课 二','韓偓','quantangshi','','卷38','征途安敢更迁延，冒入重围势使然。
众果却应存苦李，五瓶惟恐竭甘泉。
多端莫撼三珠树，密策寻遗七宝鞭。
黄篾舫中梅雨里，野人无事日高眠。','',''),('quantangshi-37994','雪中过重湖信笔偶题','韓偓','quantangshi','','卷38','道方时险拟如何，谪去甘心隐薜萝。
青草湖将天暗合，白头浪与雪相和。
旗亭腊酎逾年熟，水国春寒向晚多。
处困不忙仍不怨，醉来唯是欲傞傞。','',''),('quantangshi-37995','寄湖南从事','韓偓','quantangshi','','卷38','索寞襟怀酒半醒，无人一为解余酲。
岸头柳色春将尽，船背雨声天欲明。
去国正悲同旅雁，隔江何忍更啼莺。
莲花幕下风流客，试与温存谴逐情。','',''),('quantangshi-37996','翫水禽','韓偓','quantangshi','','卷38','两两珍禽渺渺溪，翠衿红掌净无泥。
向阳眠处莎成毯，蹋水飞时浪作梯。
依倚雕梁轻社燕，抑扬金距笑晨鸡。
劝君细认渔翁意，莫遣絚罗误稳栖。','',''),('quantangshi-37997','早翫雪梅有怀亲属','韓偓','quantangshi','','卷38','北陆候才变，南枝花已开。
无人同怅望，把酒独裴回。
冻白雪为伴，寒香风是媒。
何因逢越使，肠断谪仙才。','',''),('quantangshi-37998','欲明','韓偓','quantangshi','','卷38','欲明篱被风吹倒，过午门因客到开。
忍苦可能遭鬼笑，息机应免致鸥猜。
岳僧互乞新诗去，酒保频征旧债来。
唯有狂吟与沈饮，时时犹自触灵台。','',''),('quantangshi-37999','梅花','韓偓','quantangshi','','卷38','梅花不肯傍春光，自向深冬着艳阳。
龙笛远吹胡地月，燕钗初试汉宫妆。
风虽强暴翻添思，雪欲侵凌更助香。
应笑暂时桃李树，盗天和气作年芳。','',''),('quantangshi-38000','小隐','韓偓','quantangshi','','卷38','借得茅斋岳麓西，拟将身世老锄犂。
清晨向市烟含郭，寒夜归村月照溪。
炉为窗明僧偶坐，松因雪折鸟惊啼。
灵椿朝菌由来事，却笑庄生始欲齐。','',''),('quantangshi-38001','曛黑','韓偓','quantangshi','','卷38','古木侵天日已沈，露华凉冷润衣襟。
江城曛黑人行绝，唯有啼鸟伴夜砧。','',''),('quantangshi-38002','晓日','韓偓','quantangshi','','卷38','天际霞光入水中，水中天际一时红。
直须日观三更后，首送金乌上碧空。','',''),('quantangshi-38003','醉着','韓偓','quantangshi','','卷38','万里清江万里天，一村桑柘一村烟。
渔翁醉着无人唤，过午醒来雪满船。','',''),('quantangshi-38004','柳','韓偓','quantangshi','','卷38','一笼金线拂弯桥，几被儿童损细腰。
无奈灵和标格在，春来依旧褭长条。','',''),('quantangshi-38005','病中初闻复官二首 一','韓偓','quantangshi','','卷38','抽毫连夜侍明光，执靮三年从省方。
烧玉谩劳曾历试，铄金宁为欠周防。
也知恩泽招谗口，还痛神只误直肠。
闻道复官飜涕泗，属车何在水茫茫。','',''),('quantangshi-38006','病中初闻复官二首 二','韓偓','quantangshi','','卷38','又挂朝衣一自惊，始知天意重推诚。
青云有路通还去，白发无私健亦生。
曾避暖池将浴凤，却同寒谷乍迁莺。
宦途巇嶮终难测，稳泊渔舟隐姓名。','',''),('quantangshi-38007','早起五言三韵','韓偓','quantangshi','','卷38','万树绿杨垂，千般黄鸟语。
庭花风雨余，岑寂如村坞。
依依官渡头，晴阳照行旅。','',''),('quantangshi-38008','家书后批二十八字','韓偓','quantangshi','','卷38','四序风光总是愁，鬓毛衰飒涕横流。
此书未到心先到，想在孤城海岸头。','',''),('quantangshi-38009','湖南梅花一冬再发偶题于花援','韓偓','quantangshi','','卷38','湘浦梅花两度开，直应天意别栽培。
玉为通体依稀见，香号返魂容易回。
寒气与君霜里退，阳和为尔腊前来。
夭桃莫倚东风势，调鼎何曾用不材。','',''),('quantangshi-38010','即目二首 一','韓偓','quantangshi','','卷38','万古离怀憎物色，几生愁绪溺风光。
废城沃土肥春草，野渡空船荡夕阳。
倚道向人多脉脉，为情因酒易伥伥。
宦途弃掷须甘分，回避红尘是所长。','',''),('quantangshi-38011','即目二首 二','韓偓','quantangshi','','卷38','动非求进静非禅，咋舌吞声过十年。
溪涨浪花如积石，雨晴云叶似连钱。
干戈岁久谙戎事，枕簟秋凉减夜眠。
攻苦惯来无不可，寸心如水但澄鲜。','',''),('quantangshi-38012','净兴寺杜鹃一枝繁艳无比','韓偓','quantangshi','','卷38','一园红艳醉坡陀，自地连梢簇蒨罗。
蜀魄未归长滴血，秪应偏滴此丛多。','',''),('quantangshi-38013','花时与钱尊师同醉因成二十字','韓偓','quantangshi','','卷38','桥下浅深水，竹间红白花。
酒仙同避世，何用厌长沙。','',''),('quantangshi-38014','避地','韓偓','quantangshi','','卷38','西山爽气生襟袖，南浦离愁入梦魂。
人泊孤舟青草岸，鸟鸣高树夕阳村。
偷生亦似符天意，未死深疑负国恩。
白面儿郎犹巧宦，不知谁与正干坤。','',''),('quantangshi-38015','息兵','韓偓','quantangshi','','卷38','渐觉人心望息兵，老儒希觊见澄清。
正当困辱殊轻死，已过艰危却恋生。
多难始应彰劲节，至公安肯为虚名。
暂时胯下何须耻，自有苍苍鉴赤诚。','',''),('quantangshi-38016','翠碧鸟','韓偓','quantangshi','','卷38','天长水远网罗稀，保得重重翠碧衣。
挟弹小儿多害物，劝君莫近市朝飞。','',''),('quantangshi-38017','赠孙仁本尊师','韓偓','quantangshi','','卷38','齿如冰雪发如黳，几百年来醉似泥。
不共世人争得失，卧牀前有上天梯。','',''),('quantangshi-38018','乙丑岁九月在萧滩镇驻泊两月忽得商马杨迢员外书贺余复除戎曹依旧承旨还缄后因书四十字','韓偓','quantangshi','','卷38','旅寓在江郊，秋风正寂寥。
紫泥虚宠奖，白发已渔樵。
事往凄凉在，时危志气销。
若为将朽质，犹拟杖于朝。','',''),('quantangshi-38019','丙寅二月二十二日抚州如归馆雨中有怀诸朝客','韓偓','quantangshi','','卷39','凄凄恻恻又微嚬，欲话羇愁忆故人。
薄酒旋醒寒彻夜，好花虚谢雨藏春。
萍蓬已恨为逋客，江岭那知见侍臣。
未必交情系贫富，柴门自古少车尘。','',''),('quantangshi-38020','三月二十七日自抚州往南城县舟行见拂水蔷薇因有是作','韓偓','quantangshi','','卷39','江中春雨波浪肥，石上野花枝叶瘦。
枝低波高如有情，浪去枝留如力鬬。
绿刺红房战褭时，吴娃越艳醺酣后。
且将浊酒伴清吟，酒逸吟狂轻宇宙。','',''),('quantangshi-38021','茘枝三首 一','韓偓','quantangshi','','卷39','遐方不许贡珍奇，密诏唯教进茘枝。
汉武碧桃争比得，枉令方朔号偷儿。','',''),('quantangshi-38022','茘枝三首 二','韓偓','quantangshi','','卷39','封开玉笼鸡冠湿，叶衬金盘鹤顶鲜。
想得佳人微启齿，翠钗先取一双悬。','',''),('quantangshi-38023','茘枝三首 三','韓偓','quantangshi','','卷39','巧裁霞片裹神浆，崖蜜天然有异香。
应是仙人金掌露，结成冰入蒨罗囊。','',''),('quantangshi-38024','寄上兄长','韓偓','quantangshi','','卷39','两地支离路八千，襟怀凄怆鬓苍然。
乱来未必长团会，其奈而今更长年。','',''),('quantangshi-38025','宝劒','韓偓','quantangshi','','卷39','困极还应有甚通，难将粪壤掩神踪。
斗间紫气分明后，擘地成川看化龙。','',''),('quantangshi-38026','宝劒','韓偓','quantangshi','','卷39','困极还应有日通，难将粪土掩神踪。
但教出得丰城后，不是延津亦化龙。','',''),('quantangshi-38027','登南神光寺塔院','韓偓','quantangshi','','卷39','无奈离肠日九回，强摅离抱立高台。
中华地向城边尽，外国云从岛上来。
四序有花长见雨，一冬无雪却闻雷。
日宫紫气生冠冕，试望扶桑病眼开。','',''),('quantangshi-38028','两贤','韓偓','quantangshi','','卷39','卖卜严将卖饼孙，两贤高趣恐难伦。
而今若有逃名者，应被品流呼差人。','',''),('quantangshi-38029','再思','韓偓','quantangshi','','卷39','暴殄犹来是片时，无人向此略迟疑。
流金铄石玉长润，败柳凋花松不知。
但保行藏天是证，莫矜纤巧鬼难欺。
近来更得穷经力，好事临行亦再思。','',''),('quantangshi-38030','有瞩','韓偓','quantangshi','','卷39','晚凉闲步向江亭，默默看书旋旋行。
风转滞帆狂得势，潮来诸水寂无声。
谁将覆辙询长策，愿把棼丝属老成。
安石本怀经济意，何妨一起为苍生。','',''),('quantangshi-38031','秋深闲兴','韓偓','quantangshi','','卷39','此心兼笑野云忙，甘得贫闲味甚长。
病起乍尝新橘柚，秋深初换旧衣裳。
晴来喜鹊无穷语，雨后寒花特地香。
把钓覆棊兼举白，不离名教可顚狂。','',''),('quantangshi-38032','故都','韓偓','quantangshi','','卷39','故都遥想草萋萋，上帝深疑亦自迷。
塞雁已侵池籞宿，宫鸦犹恋女墙啼。
天涯烈士空垂涕，地下强魂必噬脐。
掩鼻计成终不觉，冯驩无路斅鸣鸡。','',''),('quantangshi-38033','梦仙','韓偓','quantangshi','','卷39','紫霄宫阙五云芝，九级坛前再拜时。
鹤舞鹿眠春草远，山高水阔夕阳迟。
每嗟阮肇归何速，深羡张骞去不疑。
澡练纯阳功力在，此心唯有玉皇知。','',''),('quantangshi-38034','赠吴顚尊师','韓偓','quantangshi','','卷39','饮酒经何代，休粮度此生。
迹应常自浼，顚亦强为名。
道若千钓重，身如一羽轻。
毫厘分象纬，袒跣揖公卿。
狗窦号光逸，渔阳裸禰衡。
笑雷冬蛰震，岩电夜珠明。
月魄侵簪冷，江光逼屐清。
半酣思救世，一手拟扶倾。
击地嗟衰俗，看天贮不平。
自缘怀气义，可是计烹亨。
议论通三教，年颜称五更。
老狂人不厌，密行鬼应惊。
未识心相许，开襟语便诚。
伊余常仗义，愿拜十年兄。','',''),('quantangshi-38035','送人弃官入道','韓偓','quantangshi','','卷39','仙李浓阴润，皇枝密叶敷。
俊才轻折桂，捷径取纡朱。
断绁三清路，扬鞭五达衢。
侧身期破的，缩手待呼卢。
社稷俄如缀，雄豪讵守株。
忸怩非壮志，摆脱是良图。
尘土留难住，缨緌弃若无。
冥心归大道，回首笑吾徒。
酒律应难忘，诗魔未肯徂。
他年如拔宅，为我指清都。','',''),('quantangshi-38036','感事三十四韵','韓偓','quantangshi','','卷39','紫殿承恩岁，金銮入直年。
人归三岛路，日过八花塼。
鸳鹭皆回席，臯夔亦慕膻。
庆霄舒羽翼，尘世有神仙。
虽遇河清圣，慙非岳降贤。
皇慈容散拙，公议逼陶甄。
江总参文会，陈暄侍狎筵。
腐儒亲帝座，太史认星躔。
侧弁聆神算，濡毫俟密宣。
宫司持玉研，书省擘香笺。
唯理心无党，怜才膝屡前。
焦劳皆实录，宵旰岂虚传。
始议新尧历，将期整舜弦。
去梯言必尽，仄席意弥坚。
上相思惩恶，中人讵省愆。
鹿穷唯抵触，兔急且㺦猭。
本是谋赊死，因之致劫迁。
氛霾言下合，日月暗中悬。
恭显诚甘罪，韦平亦恃权。
畏闻巢幕险，宁寤积薪然。
谅直寻钳口，奸纤益比肩。
晋谗终不解，鲁瘠竟难痊。
秪拟诛黄皓，何曾识霸先。
嗾獒飜丑正，养虎欲求全。
万乘烟尘里，千官劒戟边。
斗魁当北坼，地轴向西偏。
袁董非徒尔，师昭岂偶然。
中原成劫火，东海遂桑田。
溅血慙嵇绍，迟行笑褚渊。
四夷同效顺，一命敢虚捐。
山岳还青耸，穹苍旧碧鲜。
独夫长啜泣，多士已忘筌。
郁郁空狂叫，微微几病癫。
丹梯倚寥廓，终去问青天。','',''),('quantangshi-38037','向隅','韓偓','quantangshi','','卷39','守道得途迟，中兼遇乱离。
刚肠成绕指，玄发转垂丝。
客路少安处，病牀无稳时。
弟兄消息绝，独敛向隅眉。','',''),('quantangshi-38038','社后','韓偓','quantangshi','','卷39','社后重阳近，云天澹薄间。
目随棊客静，心共睡僧闲。
归鸟城衔日，残虹雨在山。
寂寥思晤语，何夕款柴关。','',''),('quantangshi-38039','息虑','韓偓','quantangshi','','卷39','息虑狎羣鸥，行藏合自由。
春寒宜酒病，夜雨入乡愁。
道向危时见，官因乱世休。
外人相待浅，独说济川舟。','',''),('quantangshi-38040','早起探春','韓偓','quantangshi','','卷39','句芒一夜长精神，腊后风头已见春。
烟柳半眠藏利脸，雪梅含笑绽香唇。
渐因闲暇思量酒，必怨顚狂泥摸人。
若个高情能似我，且应敧枕睡清晨。','',''),('quantangshi-38041','味道','韓偓','quantangshi','','卷39','如含瓦砾竟何功，痴黠相兼似得中。
心系是非徒怅望，事须光景旋虚空。
升沈不定都如梦，毁誉无恒却要聋。
弋者甚多应扼腕，任他闲处指冥鸿。','',''),('quantangshi-38042','秋郊闲望有感','韓偓','quantangshi','','卷39','枫叶微红近有霜，碧云秋色满吴乡。
鱼冲骇浪雪鳞健，鸦闪夕阳金背光。
心为感恩长惨戚，鬓缘经乱早苍浪。
可怜广武山前语，楚汉宁教作战场。','',''),('quantangshi-38043','李太舍池上玩红薇醉题','韓偓','quantangshi','','卷39','花低池小水泙泙，花落池心片片轻。
酩酊不能羞白鬓，顚狂犹自睠红英。
乍为旅客颜常厚，每见同人眼暂明。
京洛园林归未得，天涯相顾一含情。','',''),('quantangshi-38044','余寓汀州沙县病中闻前郑左丞璘随外镇举荐赴洛兼云继有急征旋见脂辖因作七言四韵戏以赠之或冀其感悟也','韓偓','quantangshi','','卷39','莫恨当年入用迟，通材何处不逢知。
桑田变后新舟檝，华表归来旧路岐。
公干寂寥甘坐废，子牟欢拚促行期。
移都已改侯王第，惆怅沙堤别筑基。','',''),('quantangshi-38045','又一绝请为申达京洛亲交知余病废','韓偓','quantangshi','','卷39','鬓惹新霜耳旧聋，眼昏腰曲四肢风。
交亲若要知形候，岚嶂烟中折臂翁。','',''),('quantangshi-38046','梦中作','韓偓','quantangshi','','卷39','紫宸初启列鸳鸾，直向龙墀对揖班。
九曜再新环北极，万方依旧祝南山。
礼容肃睦缨緌外，和气熏蒸劒履间。
扇合却循黄道退，庙堂谈笑百司闲。','',''),('quantangshi-38047','己巳年正月十二日自沙县抵邵武军将谋抚信之行到才一夕为闽相急脚相召却请赴沙县郊外泊船偶成一篇','韓偓','quantangshi','','卷39','访戴船回郊外泊，故乡何处望天涯。
半明半暗山村日，自落自开江庙花。
数盏绿醅桑落酒，一瓯香沫火前茶。','',''),('quantangshi-38048','建溪滩波心目惊眩余平生溺奇境今则畏怯不暇因书二十八字','韓偓','quantangshi','','卷39','长贪山水羡渔樵，自笑扬鞭趁早朝。
今日建溪惊恐后，李将军画也须烧。','',''),('quantangshi-38049','自沙县抵龙溪县值泉州军过后村落皆空因有一绝','韓偓','quantangshi','','卷39','水自潺湲日自斜，尽无鸡犬有鸣鸦。
千村万落如寒食，不见人烟空见花。','',''),('quantangshi-38050','此翁','韓偓','quantangshi','','卷39','高阁羣公莫忌侬，侬心不在宦名中。
严光一唾垂緌紫，何胤三遗大带红。
金劲任从千口铄，玉寒曾试几炉烘。
唯应鬼眼兼天眼，窥见行藏信此翁。','',''),('quantangshi-38051','失鹤','韓偓','quantangshi','','卷39','正怜标格出华亭，况是昂藏入相经。
碧落顺风初得志，故巢因雨却闻腥。
几时翔集来华表，每日沈吟看画屏。
为报鸡羣虚嫉妒，红尘向上有青冥。','',''),('quantangshi-38052','卜隐','韓偓','quantangshi','','卷39','屏迹还应减是非，却忧蓝玉又光辉。
桑梢出舍蚕初老，柳絮盖溪鱼正肥。
世乱岂容长惬意，景清还觉易忘机。
世间华美无心问，藜藿充肠苎作衣。','',''),('quantangshi-38053','晨兴','韓偓','quantangshi','','卷39','晓景山河爽，闲居巷陌清。
已能消滞念，兼得散余酲。
汲水人初起，回灯燕暂惊。
放怀殊未足，圆隙已尘生。','',''),('quantangshi-38054','暴雨','韓偓','quantangshi','','卷39','电尾烧黑云，雨脚飞银线。
急点溅池心，微烟昏水面。
气凉氛祲消，暑退松篁健。
丛蓼亚赬茸，擎荷飜绿扇。
风期谁与同，逸趣余探徧。
欲去更迟留，胸中久交战。','',''),('quantangshi-38055','山院避暑','韓偓','quantangshi','','卷39','行乐江郊外，追凉山寺中。
静阴生晚绿，寂虑延清风。
运塞地维窄，气苏天宇空。
何人识幽抱，目送冥冥鸿。','',''),('quantangshi-38056','闲兴','韓偓','quantangshi','','卷39','景寂有玄味，韵高无俗情。
他山冰雪解，此水波澜生。
影重验花密，滴稀知酒清。
忙人常扰扰，安得心和平。','',''),('quantangshi-38057','漫作二首 一','韓偓','quantangshi','','卷39','暑雨洒和气，香风吹日华。
瞬龙惊汗漫，翥凤綷云霞。
悬圃珠为树，天池玉作砂。
丹霄能几级，何必待乘槎。','',''),('quantangshi-38058','漫作二首 二','韓偓','quantangshi','','卷39','黍谷纯阳入，鸾霄瑞彩生。
岳灵分正气，仙卫借神兵。
汚俗迎风变，虚怀遇物倾。
千钧将一羽，轻重在平衡。','',''),('quantangshi-38059','腾腾','韓偓','quantangshi','','卷39','八年流落醉腾腾，点检行藏喜不胜。
乌帽素餐兼施药，前生多恐是医僧。','',''),('quantangshi-38060','寄隐者','韓偓','quantangshi','','卷39','烟郭云扃路不遥，怀贤犹恨太迢迢。
长松夜落钗千股，小港春添水半腰。
已约病身抛印绶，不嫌门巷似渔樵。
渭滨晦迹南阳卧，若比吾徒更寂寥。','',''),('quantangshi-38061','闲居','韓偓','quantangshi','','卷39','厌闻趋竞喜闲居，自种芜菁亦自锄。
麋鹿跳梁忧触拨，鹰鹯搏击恐麤疎。
拙谋却为多循理，所短深慙尽信书。
刀尺不亏绳墨在，莫疑张翰恋鲈鱼。','',''),('quantangshi-38062','僧影','韓偓','quantangshi','','卷39','山色依然僧已亡，竹间疎磬隔残阳。
智灯已灭余空烬，犹自光明照十方。','',''),('quantangshi-38063','洞庭玩月','韓偓','quantangshi','','卷39','洞庭湖上清秋月，月皎湖宽万顷霜。
玉椀深沈潭底白，金杯细碎浪头光。
寒惊乌鹊离巢噪，冷射蛟螭换窟藏。
更忆瑶台逢此夜，水晶宫殿挹琼浆。','',''),('quantangshi-38064','赠隐逸','韓偓','quantangshi','','卷39','静景须教静者寻，清狂何必在山阴。
蠭穿窗纸尘侵砚，鸟鬬庭花露滴琴。
莫笑乱离方解印，犹胜顚蹶未抽簪。
筑金总得非名士，况是无人解筑金。','',''),('quantangshi-38065','南浦','韓偓','quantangshi','','卷39','月若半环云若吐，高楼帘卷当南浦。
应是石城艇子来，两桨咿哑过花坞。
正值连宵酒未醒，不宜此际兼微雨。
直教笔底有文星，亦应难状分明苦。','',''),('quantangshi-38066','桃林场客舍之前有池半亩木槿栉比阏水遮山因命仆夫运斤梳沐豁然清朗复覩太虚因作五言八韵','韓偓','quantangshi','','卷39','插槿作藩篱，丛生覆小池。
为能妨远目，因遣去闲枝。
邻叟偷来赏，栖禽欲下疑。
虚空无障处，蒙闭有开时。
苇鹭怜潇洒，泥䲡畏日曦。
稍宽春水面，尽见晚山眉。
岸稳人偷钓，阶明日上基。
世间多弊事，事事要良医。','',''),('quantangshi-38067','中秋寄杨学士','韓偓','quantangshi','','卷39','鳞差甲子渐衰迟，依旧年年困乱离。
八月夜长乡思切，鬓边添得几茎丝。','',''),('quantangshi-38068','寄禅师','韓偓','quantangshi','','卷39','他心明与此心同，妙用忘言理暗通。
气运阴阳成世界，水浮天地寄虚空。
劫灰聚散铢锱黑，日御奔驰茧栗红。
万物尽遭风鼓动，唯应禅室静无风。','',''),('quantangshi-38069','清兴','韓偓','quantangshi','','卷39','阴沈天气连翩醉，摘索花枝料峭寒。
拥鼻绕廊吟看雨，不知遗却竹皮冠。','',''),('quantangshi-38070','深院','韓偓','quantangshi','','卷39','鹅儿唼啑栀黄觜，凤子轻盈腻粉腰。
深院下帘人昼寝，红蔷薇架碧芭蕉。','',''),('quantangshi-38071','凄凄','韓偓','quantangshi','','卷39','深将宠辱齐，往往亦凄凄。
白日知丹抱，青云有旧蹊。
嗜咸凌鲁济，恶洁助泾泥。
风雨今如晦，堪怜报晓鸡。','',''),('quantangshi-38072','火蛾','韓偓','quantangshi','','卷39','阳光不照临，积阴生此类。
非无惜死心，奈有灭明意。
妆穿粉焰焦，翅扑兰膏沸。
为尔一伤嗟，自弃非天弃。','',''),('quantangshi-38073','信笔','韓偓','quantangshi','','卷39','春风狂似虎，春浪白于鹅。
柳密藏烟易，松长见日多。
石崖采芝叟，乡俗摘茶歌。
道在无伊郁，天将奈尔何。','',''),('quantangshi-38074','雷公','韓偓','quantangshi','','卷39','闲人倚柱笑雷公，又向深山霹怪松。
必若有苏天下意，何如惊起武侯龙。','',''),('quantangshi-38075','船头','韓偓','quantangshi','','卷39','两岸绿芜齐似翦，掩映云山相向晚。
船头独立望长空，日艳波光逼人眼。','',''),('quantangshi-38076','喜凉','韓偓','quantangshi','','卷39','炉炭烧人百疾生，凤狂龙躁减心情。
四山毒瘴干坤浊，一簟凉风世界清。
楚调忽惊凄玉柱，汉宫应已湿金茎。
豪强顿息蛙唇吻，爽利重新鹘眼睛。
稳想海槎朝犯斗，健思胡马夜飜营。
东南亦是中华分，蒸郁相凌太不平。','',''),('quantangshi-38077','天鉴','韓偓','quantangshi','','卷39','何劳谄笑学趋时，务实清修胜用机。
猛虎十年摇尾立，苍鹰一旦醒心飞。
神依正道终潜卫，天鉴衷肠竞不违。
事历艰难人始重，九层成后喜从微。','',''),('quantangshi-38078','江岸闲步','韓偓','quantangshi','','卷39','一手携书一杖筇，出门何处觅情通。
立谈禅客传心印，坐睡渔师着背蓬。
青布旗夸千日酒，白头浪吼半江风。
淮阴市里人相见，尽道途穷未必穷。','',''),('quantangshi-38079','野塘','韓偓','quantangshi','','卷39','侵晓乘凉偶独来，不因鱼跃见萍开。
卷荷忽被微风触，泻下清香露一杯。','',''),('quantangshi-38080','余卧疾深村闻一二郎官今称继使闽越笑余迂古潜于异乡闻之因成此篇','韓偓','quantangshi','','卷39','枕流方采北山薇，驿骑交迎市道儿。
雾豹秪忧无石室，泥䲡唯要有洿池。
不羞莽卓黄金印，却笑羲皇白接䍦。
莫负美名书信史，清风埽地更无遗。','',''),('quantangshi-38081','安贫','韓偓','quantangshi','','卷39','手风慵展一行书，眼暗休寻九局图。
窗里日光飞野马，案头筠管长蒲庐。
谋身拙为安蛇足，报国危曾捋虎须。
举世可能无默识，未知谁拟试齐竽。','',''),('quantangshi-38082','残春旅舍','韓偓','quantangshi','','卷39','旅舍残春宿雨晴，恍然心地忆咸京。
树头蠭抱花须落，池面鱼吹柳絮行。
禅伏诗魔归净域，酒冲愁阵出奇兵。
两梁免被尘埃汚，拂拭朝簪待眼明。','',''),('quantangshi-38083','鹊','韓偓','quantangshi','','卷39','偏承雨露润毛衣，黑白分明众所知。
高处营巢亲凤阙，静时闲语上龙墀。
化为金印新祥瑞，飞向银河旧路岐。
莫怪天涯栖不稳，托身须是万年枝。','',''),('quantangshi-38084','露','韓偓','quantangshi','','卷39','鹤非千岁饮犹难，莺舌偷含岂自安。
光湿最宜丛菊亚，荡摇无奈绿荷干。
名因霈泽随天睠，分与浓霜保岁寒。
五色呈祥须得处，戛云仙掌有金盘。','',''),('quantangshi-38085','赠僧','韓偓','quantangshi','','卷39','尽说归山避战尘，几人终肯别嚣氛。
瓶添涧水盛将月，衲挂松枝惹得云。
三接旧承前席遇，一灵今用戒香熏。
相逢莫话金銮事，触拨伤心不愿闻。','',''),('quantangshi-38086','感旧','韓偓','quantangshi','','卷39','省趋弘阁待貂璫，指座深恩刻寸肠。
秦苑已荒空逝水，楚天无[限]更斜阳。
时昏却笑朱弦直，事过方闻锁骨香。
入室故寮流落尽，路人惆怅见灵光。','',''),('quantangshi-38087','八月六日作四首 一','韓偓','quantangshi','','卷39','日离黄道十年昏，敏手重开造化门。
火帝动炉销劒戟，风师吹雨洗干坤。
左牵犬马诚难测，右袒簪缨最负恩。
丹笔不知谁定罪，莫留遗迹怨神孙。','',''),('quantangshi-38088','八月六日作四首 二','韓偓','quantangshi','','卷39','金虎挻灾不复论，构成狂猘犯车尘。
御衣空惜侍中血，国玺几危皇后身。
图霸未能知盗道，饰非唯欲害仁人。
黄旗紫气今仍旧，免使老臣攀画轮。','',''),('quantangshi-38089','八月六日作四首 三','韓偓','quantangshi','','卷39','簪裾皆是汉公卿，尽作锋铓劒血醒。
显负旧恩归乱主，难教新国用轻刑。
穴中狡兔终须尽，井上婴儿岂自宁。
底事亦疑惩未了，更应书罪在泉扃。','',''),('quantangshi-38090','八月六日作四首 四','韓偓','quantangshi','','卷39','坐看包藏负国恩，无才不得预经纶。
袁安坠睫寻忧汉，贾谊濡毫但过秦。
威凤鬼应遮矢射，灵犀天与隔埃尘。
堤防瓜李能终始，免愧于心负此身。','',''),('quantangshi-38091','驿步','韓偓','quantangshi','','卷39','暂息征车病眼开，况穿松竹入楼台。
江流灯影向东去，树递雨声从北来。
物近刘舆招垢腻，风经庾亮汚尘埃。
高情自古多惆怅，赖有南华养不材。','',''),('quantangshi-38092','访隐者遇沈醉书其门而归','韓偓','quantangshi','','卷39','晓入江村觅钓翁，钓翁沈醉酒缸空。
夜来风起闲花落，狼藉柴门鸟径中。','',''),('quantangshi-38093','疎雨','韓偓','quantangshi','','卷39','疎雨从东送疾雷，小庭凉气净莓苔。
卷帘燕子穿人去，洗砚鱼儿触手来。
但欲进贤求上赏，唯将拯溺作良媒。
戎衣一挂清天下，傅野非无济世才。','',''),('quantangshi-38094','南安寓止','韓偓','quantangshi','','卷39','此地三年偶寄家，枳篱茅厂共桑麻。
蝶矜翅暖徐窥草，蠭倚身轻凝看花。
天近函关屯瑞气，水侵吴甸浸晴霞。
岂知卜肆严夫子，潜指星机认海槎。','',''),('quantangshi-38095','十月七日早起作时气疾初愈','韓偓','quantangshi','','卷39','疾愈身轻觉数通，山无岚瘴海无风。
阳精欲出阴精落，天地包含紫气中。','',''),('quantangshi-38096','有感','韓偓','quantangshi','','卷39','坚辞羽葆与吹铙，飜向天涯困系匏。
故老未曾忘炙背，何人终拟问苞茅。
融风渐暖将回雁，滫水犹腥近斩蛟。
万里关山如咫尺，女牀唯待凤归巢。','',''),('quantangshi-38097','观鬬鸡偶作','韓偓','quantangshi','','卷39','何曾解报稻粱恩，金距花冠气遏云。
白日枭鸣无意问，唯将芥羽害同羣。','',''),('quantangshi-38098','蜻蜓','韓偓','quantangshi','','卷39','碧玉眼睛云母翅，轻于粉蝶瘦于蠭。
坐来迎拂波光久，岂是殷勤为蓼丛。','',''),('quantangshi-38099','即目','韓偓','quantangshi','','卷39','书墙暗记移花日，洗瓮先知酝酒期。
须信闲人有忙事，早来冲雨觅渔师。','',''),('quantangshi-38100','寄邻庄道侣','韓偓','quantangshi','','卷39','闻说经旬不启关，药窗谁伴醉开颜。
夜来雪压村前竹，剩见溪南几尺山。','',''),('quantangshi-38101','初赴期集','韓偓','quantangshi','','卷39','轻寒着背雨凄凄，九陌无尘未有泥。
还是平时旧滋味，慢垂鞭袖过街西。','',''),('quantangshi-38102','惜花','韓偓','quantangshi','','卷39','皱白离情高处切，腻香愁态静中深。
眼随片片沿流去，恨满枝枝被雨淋。
总得苔遮犹慰意，若教泥汚更伤心。
临轩一盏悲春酒，明日池塘是绿阴。','',''),('quantangshi-38103','半醉','韓偓','quantangshi','','卷39','水向东流竟不回，红颜白发递相催。
壮心暗逐高歌尽，往事空因半醉来。
云护雁霜笼澹月，雨连莺晓落残梅。
西楼怅望芳菲节，处处斜阳草似苔。','',''),('quantangshi-38104','春尽','韓偓','quantangshi','','卷39','惜春连日醉昏昏，醒后衣裳见酒痕。
细水浮花归别涧，断云含雨入孤村。
人闲易有芳时恨，地胜难招自古魂。
慙愧流莺相厚意，清晨犹为到西园。','',''),('quantangshi-38105','睡起','韓偓','quantangshi','','卷39','睡起墙阴下药阑，瓦松花白闭柴关。
断年不出僧嫌癖，逐日无机鹤伴闲。
尘土莫寻行止处，烟波长在梦魂间。
终撑舴艋称渔叟，赊买湖心一崦山。','',''),('quantangshi-38106','寄友人','韓偓','quantangshi','','卷39','伤时惜别心交加，搘颐一向千咨嗟。
旷野风吹寒食月，广庭烟着黄昏花。
长拟醺酣遗世事，若为局促问生涯。
夫君亦是多情者，几处将愁殢酒家。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38107','见别离者因赠之','韓偓','quantangshi','','卷39','征人草草尽戎装，征马萧萧立路傍。
尊酒阑珊将远别，秋山迤逦更斜阳。
白髭兄弟中年后，瘴海程途万里长。
曾向天涯怀此恨，见君呜咽更凄凉。','',''),('quantangshi-38108','伤乱','韓偓','quantangshi','','卷39','岸上花根总倒垂，水中花影几千枝。
一枝一影寒山里，野水野花清露时。
故国几年犹战鬬，异乡终日见旌旗。
交亲流落身羸病，谁在谁亡两不知。','',''),('quantangshi-38109','南亭','韓偓','quantangshi','','卷39','每日在南亭，南亭似僧院。
人语静先闻，鸟啼深不见。
松瘦石棱棱，山光溪淀淀。
堑蔓坠长茸，岛花垂小蒨。
行簪隐士冠，卧读先贤传。
更有兴来时，取琴弹一徧。','',''),('quantangshi-38110','太平谷中玩水上花','韓偓','quantangshi','','卷39','山头水从云外落，水面花自山中来。
一溪红点我独惜，几树蜜房谁见开。
应有妖魂随暮雨，岂无香迹在苍苔。
凝眸不觉斜阳尽，忘逐樵人蹑石回。','',''),('quantangshi-38111','雨','韓偓','quantangshi','','卷39','坐来簌簌山风急，山雨随风暗原隰。
树带繁声出竹闻，溪将大点穿篱入。
饷妇寥翘布领寒，牧童拥肿蓑衣湿。
此时高味共谁论，拥鼻吟诗空伫立。','',''),('quantangshi-38112','幽独','韓偓','quantangshi','','卷39','幽独起侵晨，山莺啼更早。
门巷掩萧条，落花满芳草。
烟和魂共远，春与人同老。
默默又依依，凄然此怀抱。','',''),('quantangshi-38113','江行','韓偓','quantangshi','','卷39','浪蹙青山江北岸，云含黑雨日西边。
舟人偶语忧风色，行客无聊罢昼眠。
争似槐花九衢里，马蹄安稳慢垂鞭。','',''),('quantangshi-38114','汉江行次','韓偓','quantangshi','','卷39','村寺虽深已暗知，幡竿残日迥依依。
沙头有庙青林合，驿步无人白鸟飞。
牧笛自由随草远，渔歌得意扣舷归。
竹园相接春波暖，痛忆家乡旧钓矶。','',''),('quantangshi-38115','偶题','韓偓','quantangshi','','卷39','俟时轻进固相妨，实行丹心仗彼苍。
萧艾转肥兰蕙瘦，可能天亦妬馨香。','',''),('quantangshi-38116','湖南绝少含桃偶有人以新摘者见惠感事伤怀因成四韵','韓偓','quantangshi','','卷39','时节虽同气候殊，不知堪荐寝园无。
合充凤食留三岛，谁许莺偷过五湖。
苦笋恐难同象匕，酪浆无复莹蠙珠。
金銮岁岁长宣赐，忍泪看天忆帝都。','',''),('quantangshi-38117','隰州新驿','韓偓','quantangshi','','卷39','盛德已图形，胡为忽构兵。
燎原虽自及，诛乱不无名。
掷鼠须防误，连鸡莫惮惊。
本期将系虏，末策但婴城。
肘腋人情变，朝廷物论生。
果闻荒谷缢，旋覩藁街烹。
帝怒今方息，时危喜暂清。
始终俱以此，天意甚分明。','',''),('quantangshi-38118','乱后春日途经野塘','韓偓','quantangshi','','卷39','世乱他乡见落梅，野塘晴暖独裴回。
船冲水鸟飞还住，袖拂杨花去却来。
季重旧游多丧逝，子山新赋极悲哀。
眼看朝市成陵谷，始信昆明是劫灰。','',''),('quantangshi-38119','赠易卜崔江处士','韓偓','quantangshi','','卷39','白首穷经通祕义，青山养老度危时。
门传组绶身能退，家学渔樵迹更奇。
四海尽闻龟策妙，九霄堪叹鹤书迟。
壶中日月将何用，借与闲人试一窥。','',''),('quantangshi-38120','过临淮故里','韓偓','quantangshi','','卷39','交游昔岁已凋零，第宅今来亦变更。
旧庙荒凉时飨绝，诸孙饥冻一官成。
五湖竟负他年志，百战空垂异代名。
荣盛几何流落久，遣人襟抱薄浮生。','',''),('quantangshi-38121','赠湖南李思齐处士','韓偓','quantangshi','','卷39','两板船头浊酒壶，七丝琴畔白髭须。
三春日日黄梅雨，孤客年年青草湖。
燕侠冰霜难狎近，楚狂锋刃触凡愚。
知余绝粒窥仙事，许到名山看药炉。','',''),('quantangshi-38122','乱后却至近甸有感','韓偓','quantangshi','','卷39','狂童容易犯金门，比屋齐人作旅魂。
夜户不扃生茂草，春渠自溢浸荒园。
关中忽见屯边卒，塞外飜闻有汉村。
堪恨无情清渭水，渺茫依旧绕秦原。','',''),('quantangshi-38123','同年前虞部李郎中自长沙赴行在余以紫石砚赠之赋诗代书','韓偓','quantangshi','','卷39','斧柯新样胜珠玑，堪赞星郎染翰时。
不向东垣修直疏，即须西掖草妍词。
紫光称近丹青笔，声韵宜裁锦绣诗。
蓬岛侍臣今放逐，羡君回去逼龙墀。','',''),('quantangshi-38124','甲子岁夏五月自长沙抵醴陵贵就深僻以便疎慵由道林之南步步胜绝去绿口分东入南小江山水益秀村篱之次忽见紫薇花因思玉堂及西掖厅前皆植是花遂赋诗四韵聊寄知心','韓偓','quantangshi','','卷39','职在内庭宫阙下，厅前皆种紫薇花。
眼明忽傍渔家见，魂断方惊魏阙赊。
浅色晕成宫里锦，浓香染着洞中霞。
此行若遇支机石，又被君平验海槎。','',''),('quantangshi-38125','和王舍人抚州饮席赠韦司空','韓偓','quantangshi','','卷39','楼台掩映入春寒，丝竹铮鏦向夜阑。
席上弟兄皆杞梓，花前宾客尽鸳鸾。
孙弘莫惜频开合，韩信终期别筑坛。
削玉风姿官水土，黑头公自古来难。','',''),('quantangshi-38126','避地寒食','韓偓','quantangshi','','卷39','避地淹留已自悲，况逢寒食欲霑衣。
浓春孤馆人愁坐，斜日空园花乱飞。
路远渐忧知己少，时危又与赏心违。
一名所系无穷事，争敢当年便息机。','',''),('quantangshi-38127','山驿','韓偓','quantangshi','','卷39','参差西北数行雁，寥落东方几片云。
叠石小松张水部，暗山寒雨李将军。
秋花粉黛宜无味，独鸟笙簧称静闻。
潇洒襟怀遗世虑，驿楼红叶自纷纷。','',''),('quantangshi-38128','早发蓝关','韓偓','quantangshi','','卷39','关门愁立候鸡鸣，搜景驰魂入杳冥。
云外日随千里雁，山根霜共一潭星。
路盘暂见樵人火，栈转时闻驿使铃。
自问辛勤缘底事，半年驱马傍长亭。','',''),('quantangshi-38129','深村','韓偓','quantangshi','','卷39','甘向深村固不材，犹胜摧折傍尘埃。
清宵翫月唯红叶，永日关门但绿苔。
幽院菊荒同寂寞，野桥僧去独裴回。
隔篱农叟遥相贺，□□□□膏雨来。','',''),('quantangshi-38130','重游曲江','韓偓','quantangshi','','卷39','追寻前事立江汀，渔者应闻太息声。
避客野鸥如有感，损花微雪似无情。
疎林自觉长堤在，春水空连古岸平。
惆怅引人还到夜，鞭鞘风冷柳烟轻。','',''),('quantangshi-38131','三月','韓偓','quantangshi','','卷39','辛夷才谢小桃发，蹋青过后寒食前。
四时最好是三月，一去不回唯少年。
吴国地遥江接海，汉陵魂断草连天。
新愁旧恨真无奈，须就邻家瓮底眠。','',''),('quantangshi-38132','秋村','韓偓','quantangshi','','卷39','稻垄蓼红沟水清，荻园叶白秋日明。
空坡路细见骑过，远田人静闻水行。
柴门狼藉牛羊气，竹坞幽深鸡犬声。
绝粒看经香一炷，心知无事即长生。','',''),('quantangshi-38133','残花','韓偓','quantangshi','','卷39','余霞残雪几多在，蔫香冶态犹无穷。
黄昏月下惆怅白，清明雨后寥𤞚红。
树底草齐千片净，墙头风急数枝空。
西园此日伤心处，一曲高歌水向东。','',''),('quantangshi-38134','夜船','韓偓','quantangshi','','卷39','野云低迷烟苍苍，平波挥目如凝霜。
月明船上帘幕卷，露重岸头花木香。
村远夜深无火烛，江寒坐久换衣裳。
诚知不觉天将曙，几簇青山雁一行。','',''),('quantangshi-38135','伤春','韓偓','quantangshi','','卷39','三月光景不忍看，五陵春色何摧残。
穷途得志反惆怅，饮席话旧多阑珊。
中酒向阳成美睡，惜花冲雨觉伤寒。
野棠飞尽蒲根暖，寂寞南溪倚钓竿。','',''),('quantangshi-38136','归紫阁下','韓偓','quantangshi','','卷39','一笈携归紫阁峰，马蹄闲慢水溶溶。
黄昏后见山田火，胧{月悤}时闻县郭钟。
瘦竹迸生僧坐石，野藤缠杀鹤翘松。
钓矶自别经秋雨，长得莓苔更几重。','',''),('quantangshi-38137','夜坐','韓偓','quantangshi','','卷39','天似空江星似波，时时珠露滴圆荷。
平生踪迹慕真隐，此夕襟怀深自多。
格是厌厌饶酒病，终须的的学渔歌。
无名无位堪休去，犹拟朝衣换钓蓑。','',''),('quantangshi-38138','午寝梦江外兄弟','韓偓','quantangshi','','卷39','长夏居闲门不开，绕门青草绝尘埃。
空庭日午独眠觉，旅梦天涯相见回。
鬓向此时应有雪，心从别处即成灰。
如何水陆三千里，几月书邮始一来。','',''),('quantangshi-38139','曲江夜思','韓偓','quantangshi','','卷39','鼓声将绝月斜痕，园外闲坊半掩门。
池里红莲凝白露，苑中青草伴黄昏。
林塘阒寂偏宜夜，烟火稀疎便似村。
大抵世间幽独景，最关诗思与离魂。','',''),('quantangshi-38140','过汉口','韓偓','quantangshi','','卷39','浊世清名一概休，古今飜覆剩堪愁。
年年春浪来巫峡，日日残阳过沔州。
居杂商徒偏富庶，地多词客自风流。
联翩半世腾腾过，不在渔船即酒楼。','',''),('quantangshi-38141','惜春','韓偓','quantangshi','','卷39','愿言未偶非高卧，多病无憀选胜游。
一夜雨声三月尽，万般人事五更头。
年逾弱冠即为老，节过清明却似秋。
应是西园花已落，满溪红片向东流。','',''),('quantangshi-38142','及第过堂日作','韓偓','quantangshi','','卷39','早随真侣集蓬瀛，阊阖门开尚见星。
龙尾楼台迎晓日，鳌头宫殿入青冥。
暗惊凡骨升仙籍，忽讶麻衣谒相庭。
百辟敛容开路看，片时辉赫胜图形。','',''),('quantangshi-38143','夏课成感怀','韓偓','quantangshi','','卷39','别离终日心忉忉，五湖烟波归梦劳。
凄凉身事夏课毕，濩落生涯秋风高。
居世无媒多困踬，昔贤因此亦号啕。
谁怜愁苦多衰改，未到潘年有二毛。','',''),('quantangshi-38144','离家第二日却寄诸兄弟','韓偓','quantangshi','','卷39','睡起褰帘日出时，今辰初恨间容辉。
千行泪激傍人感，一点心随健步归。
却望山川空黯黯，回看僮仆亦依依。
定知兄弟高楼上，遥指征途羡鸟飞。','',''),('quantangshi-38145','游江南水陆院','韓偓','quantangshi','','卷39','早于喧杂是深雠，犹恐行藏坠俗流。
高寺嬾为携酒去，名山长恨送人游。
关河见月空垂泪，风雨看花欲白头。
除却祖师心法外，浮生何处不堪愁。','',''),('quantangshi-38146','江南送别','韓偓','quantangshi','','卷39','江南行止忽相逢，江馆棠棃叶正红。
一笑共嗟成往事，半酣相顾似衰翁。
关山月皎清风起，送别人归野渡空。
大抵多情应易老，不堪岐路数西东。','',''),('quantangshi-38147','格卑','韓偓','quantangshi','','卷39','格卑尝恨足牵仍，欲学忘情似不能。
入意云山输画匠，动人风月羡琴僧。
南朝峻洁推弘景，东晋清狂数季鹰。
惆怅后尘流落尽，自抛怀抱醉懵腾。','',''),('quantangshi-38148','冬日','韓偓','quantangshi','','卷39','萧条古木衔斜日，戚沥晴寒滞早梅。
愁处雪烟连野起，静时风竹过墙来。
故人每忆心先见，新酒偷尝手自开。
景状入诗兼入画，言情不尽恨无才。','',''),('quantangshi-38149','再止庙居','韓偓','quantangshi','','卷39','去值秋风来值春，前时今日共销魂。
颓坦古柏疑山关，高柳鸣鸦似水村。
菜甲未齐初出叶，树阴方合掩重门。
幽深冻馁皆推分，静者还应为讨论。','',''),('quantangshi-38150','老将','韓偓','quantangshi','','卷39','折枪黄马倦尘埃，掩耳凶徒怕疾雷。
雪密酒酣偷号去，月明衣冷斫营回。
行驱貔虎披金甲，立听笙歌掷玉杯。
坐久不须轻矍铄，至今双擘硬弓开。','',''),('quantangshi-38151','边上看猎赠元戎','韓偓','quantangshi','','卷39','绣帘临晓觉新霜，便遣移厨较猎场。
燕卒铁衣围汉相，鲁儒戎服从梁王。
搜山闪闪旗头远，出树斑斑豹尾长。
赞获一声连朔漠，贺杯环骑舞优倡。
军回野静秋天白，角怨城遥晚照黄。
红袖拥门持烛炬，解劳今夜宴华堂。','',''),('quantangshi-38152','余自刑部员外郎为权所挤值盘石出镇藩屏朝选宾佐以余充职掌记郁郁不乐因成长句寄所知','韓偓','quantangshi','','卷39','正叨清级忽从戎，况与燕台事不同。
开口谩劳矜道在，抚膺唯合哭途穷。
操心未省趋浮俗，点额尤慙自至公。','',''),('quantangshi-38153','北齐二首 一','韓偓','quantangshi','','卷39','任道骄奢必败亡，且将繁盛悦嫔嫱。
几千籢镜成楼柱，六十间云号殿廊。
后主猎回初按乐，胡姬酒醒更新妆。
绮罗堆里春风畔，年少多情一帝王。','',''),('quantangshi-38154','北齐二首 二','韓偓','quantangshi','','卷39','神器传时异至公，败亡安可怨悤悤。
犯寒猎士朝频戮，告急军书夜不通。
并部义旗遮日暗，邺城飞焰照天红。
周朝将相还无体，宁死何须入铁笼。','',''),('quantangshi-38155','寄京城亲友二首 一','韓偓','quantangshi','','卷39','苦吟看坠叶，寥落共天涯。
壮岁空为客，初寒更忆家。
雨墙经月藓，山菊向阳花。
因味碧云句，伤哉后会赊。','',''),('quantangshi-38156','寄京城亲友二首 二','韓偓','quantangshi','','卷39','相思凡几日，日欲咏离衿。
直得吟成病，终难状此心。
解衣悲缓带，搔首闷遗簪。
西岭斜阳外，潜疑是故林。','',''),('quantangshi-38157','野寺','韓偓','quantangshi','','卷39','野寺看红叶，县城闻捣衣。
自怜痴病苦，犹共赏心违。
高阁正临夜，前山应落晖。
离情在烟鸟，遥入故关飞。','',''),('quantangshi-38158','吴郡怀古','韓偓','quantangshi','','卷39','主暗臣忠枉就刑，遂教强国醉中倾。
人亡建业空城在，花落西江春水平。
万古壮夫犹抱恨，至今词客尽伤情。
徒劳铁锁长千尺，不觉楼船下晋兵。','',''),('quantangshi-38159','守愚','韓偓','quantangshi','','卷39','深院寥寥竹荫廊，披衣欹枕过年芳。
守愚不觉世途险，无事始知春日长。
一亩落花围隙地，半竿浓日界空墙。
今来自责趋时嬾，飜恨松轩书满牀。','',''),('quantangshi-38160','村居','韓偓','quantangshi','','卷39','二月三月雨晴初，舍南舍北唯平芜。
前懽入望盈千恨，胜景牵心非一途。
日照神堂闻啄木，风含社树叫提壶。
行看旦夕棃霜发，犹有山寒伤酒垆。','',''),('quantangshi-38161','离家','韓偓','quantangshi','','卷39','八月初长夜，千山第一程。
款颜唯有梦，怨泣却无声。
祖席诸宾散，空郊匹马行。
自怜非达识，局促为浮名。','',''),('quantangshi-38162','秋雨内宴','韓偓','quantangshi','','卷39','一带清风入画堂，撼真珠箔碎玎璫。
更看槛外霏霏雨，似劝须教醉玉觞。','',''),('quantangshi-38163','寒食日沙县雨中看蔷薇','韓偓','quantangshi','','卷39','何处遇蔷薇，殊乡冷节时。
雨声笼锦帐，风势偃罗帏。
通体全无力，酡颜不自持。
绿疎微露刺，红密欲藏枝。
惬意凭阑久，贪吟放盏迟。
旁人应见讶，自醉自题诗。','',''),('quantangshi-38164','地炉','韓偓','quantangshi','','卷39','两星残火地炉畔，梦断背灯重拥衾。
侧听空堂闻静响，似敲疎磬褭清音。
风灯有影随笼转，腊雪无声逐夜深。
禅客钓翁徒自好，那知此际湛然心。','',''),('quantangshi-38165','隰州新驿赠刺史','韓偓','quantangshi','','卷39','贤侯新换古长亭，先定心机指顾成。
高义尽招秦逐客，旷怀偏接鲁诸生。
萍蓬到此销离恨，燕雀飞来带喜声。
却笑昔贤交易极，一开东合便垂名。','',''),('quantangshi-38166','草书屏风','韓偓','quantangshi','','卷39','何处一屏风，分明怀素踪。
虽多尘色染，犹见墨痕浓。
怪石奔秋涧，寒藤挂古松。
若教临水畔，字字恐成龙。','',''),('quantangshi-38167','永明禅师房','韓偓','quantangshi','','卷39','景色方妍媚，寻真出近郊。
宝香炉上爇，金磬佛前敲。
蔓草棱山径，晴云拂树梢。
支公禅寂处，时有鹤来巢。','',''),('quantangshi-38168','登楼有题','韓偓','quantangshi','','卷39','暑气檐前过，蝉声树杪交。
待潮生浦口，看雨过山坳。
才见兰舟动，仍闻桂檝敲。
窣云朱槛好，终覩凤来巢。','',''),('quantangshi-38169','朝退书怀','韓偓','quantangshi','','卷39','鹤帔星冠羽客装，寝楼西畔坐书堂。
山禽养久知人唤，窗竹芟多漏月光。
粉壁不题新拙恶，小屏唯录古篇章。
孜孜莫患劳心力，富国安民理道长。','',''),('quantangshi-38170','元夜即席','韓偓','quantangshi','','卷39','元宵清景亚元正，丝雨霏霏向晚倾。
桂兔韬光云叶重，烛龙衔耀月轮明。
烟空但仰如膏润，绮席都忘滴砌声。
更待今宵开霁后，九衢车马未妨行。','',''),('quantangshi-38171','大庆堂赐宴元璫而有诗呈吴越王','韓偓','quantangshi','','卷39','非为亲贤展绮筵，恒常宁敢恣游盘。
绿搓杨柳緜初輭，红晕樱桃粉未干。
谷鸟乍啼声似涩，甘霖方霁景犹寒。
笙歌风紧人酣醉，却绕珍丛烂熳看。','',''),('quantangshi-38172','又和大庆堂赐宴元璫而有诗呈吴越王','韓偓','quantangshi','','卷39','樱桃花下会亲贤，风远铜乌转露盘。
蝶下粉墙梅乍坼，蚁浮金斝酒难干。
云和缓奏泉声咽，珠箔低垂水影寒。
狂简斐然吟咏足，却邀羣彦重吟看。','',''),('quantangshi-38173','再和大庆堂赐宴元璫而有诗呈吴越王','韓偓','quantangshi','','卷39','我有嘉宾宴乍欢，画帘纹细凤双盘。
影笼沼沚修篁密，声透笙歌羯鼓干。
散后便依书箧寐，渴来潜想玉壶寒。
樱桃零落红桃媚，更俟旬余共醉看。','',''),('quantangshi-38174','重和大庆堂赐宴元璫而有诗呈吴越王','韓偓','quantangshi','','卷39','冷宴殷勤展小园，舞鞇柔輭彩虬盘。
篸花尽日疑头重，病酒经宵觉口干。
嘉树倚楼青琐暗，晚云藏雨碧山寒。
文章天子文章别，八米卢郎未可看。','',''),('quantangshi-38175','余作探使以缭绫手帛子寄贺因而有诗','韓偓','quantangshi','','卷39','解寄缭绫小字封，探花筵上映春丛。
黛眉印在微微绿，檀口消来薄薄红。
缏处直应心共紧，砑时兼恐汗先融。
帝台春尽还东去，却系帬腰伴雪胷。','',''),('quantangshi-38176','别锦儿','韓偓','quantangshi','','卷39','一尺红绡一首诗，赠君相别两相思。
画眉今日空留语，解佩他年更可期。
临去莫论交颈意，清歌休着断肠词。
出门何事休惆怅，曾梦良人折桂枝。','',''),('quantangshi-38177','闲步','韓偓','quantangshi','','卷39','庄南纵步游荒野，独鸟寒烟轻惹惹。
傍山疎雨湿秋花，僻路浅泉浮败果。
樵人相见指惊麏，牧童四散收嘶马。
一壶倾尽未能归，黄昏更望诸峰火。','',''),('quantangshi-38178','干宁三年丙辰在奉天重围作','韓偓','quantangshi','','卷39','仗劒夜巡城，衣襟满霜霰。
贼火徧郊坰，飞焰侵星汉。
积雪似空江，长林如断岸。
独凭女墙头，思家起长叹。','',''),('quantangshi-38179','雨中','韓偓','quantangshi','','卷39','青桐承雨声，声声何重叠。
疎滴下高枝，次打敧低叶。
鸟湿更梳翎，人愁方拄颊。
独自上西楼，风襟寒帖帖。','',''),('quantangshi-38180','与僧','韓偓','quantangshi','','卷39','江海扁舟客，云山一衲僧。
相逢两无语，若个是南能。','',''),('quantangshi-38181','晚岸','韓偓','quantangshi','','卷39','揭起青𦪪上岸头，野花和雨冷修修。
春江一夜无波浪，校得行人分外愁。','',''),('quantangshi-38182','仙山','韓偓','quantangshi','','卷39','一炷心香洞府开，偃松皱涩半莓苔。
水清无底山如削，始有仙人骑鹤来。','',''),('quantangshi-38183','过茂陵','韓偓','quantangshi','','卷39','不悲霜露但伤春，孝理何因感兆民。
景帝龙髯消息断，异香空见李夫人。','',''),('quantangshi-38184','曲江秋日','韓偓','quantangshi','','卷39','斜烟缕缕鹭鸶栖，藕叶枯香折野泥。
有个高僧入图画，把经吟立水塘西。','',''),('quantangshi-38185','流年','韓偓','quantangshi','','卷39','三月伤心仍晦日，一春多病更阴天。
雄豪亦有流年恨，况是离魂易黯然。','',''),('quantangshi-38186','商山道中','韓偓','quantangshi','','卷39','云横峭壁水平铺，渡口人家日欲晡。
却忆往年看粉本，始知名画有工夫。','',''),('quantangshi-38187','招隐','韓偓','quantangshi','','卷39','立意忘机机已生，可能朝市污高情。
时人未会严陵志，不钓鲈鱼只钓名。','',''),('quantangshi-38188','雨村','韓偓','quantangshi','','卷39','雁行斜拂雨村楼，帘下三重幕一钩。
倚柱不知身半湿，黄昏独自未回头。','',''),('quantangshi-38189','使风','韓偓','quantangshi','','卷39','茶烟睡觉心无事，一卷黄庭在手中。
敧枕卷帘江万里，舟人不语满帆风。','',''),('quantangshi-38190','阻风','韓偓','quantangshi','','卷39','平生情趣羡渔师，此日烟江惬所思。
肥鳜香秔小艛艓，断肠滋味阻风时。','',''),('quantangshi-38191','并州','韓偓','quantangshi','','卷39','戍旗青草接榆关，雨里并州四月寒。
谁会凭阑潜忍泪，不胜天际似江干。','',''),('quantangshi-38192','夏夜','韓偓','quantangshi','','卷39','猛风飘电黑云生，霎霎高林簇雨声。
夜久雨休风又定，断云流月却斜明。','',''),('quantangshi-38193','阑干','韓偓','quantangshi','','卷39','埽花虽恨夜来雨，把酒却怜晴后寒。
吴质谩言愁得病，当时犹不凭阑干。','',''),('quantangshi-38194','以庭前海棠棃花一枝寄李十九员外','韓偓','quantangshi','','卷39','二月春风澹荡时，旅人虚对海棠棃。
不如寄与星郎去，想得朝回正画眉。','',''),('quantangshi-38195','驿楼','韓偓','quantangshi','','卷39','流云溶溶水悠悠，故乡千里空回头。
三更犹凭阑干月，泪满关山孤驿楼。','',''),('quantangshi-38196','频访卢秀才','韓偓','quantangshi','','卷39','药诀棊经思致论，柳腰莲脸本忘情。
频频强入风流坐，酒肆应疑阮步兵。','',''),('quantangshi-38197','答友人见寄酒','韓偓','quantangshi','','卷39','虽可忘忧矣，其如作病何。
淋漓满襟袖，更发楚狂歌。','',''),('quantangshi-38198','野钓','韓偓','quantangshi','','卷39','细雨桃花水，轻鸥逆浪飞。
风头阻归棹，坐睡倚蓑衣。','',''),('quantangshi-38199','曲江晚思','韓偓','quantangshi','','卷39','云物阴寂历，竹木寒青苍。
水冷鹭鸶立，烟月愁昏黄。','',''),('quantangshi-38200','赠友人','韓偓','quantangshi','','卷39','莫嫌谈笑与经过，却恐闲多病亦多。
若遣心中无一事，不知争奈日长何。','',''),('quantangshi-38201','半睡','韓偓','quantangshi','','卷39','眉山暗澹向残灯，一半云鬟坠枕棱。
四体着人娇欲泣，自家揉损砑缭绫。','',''),('quantangshi-38202','已凉','韓偓','quantangshi','','卷39','愁多却讶天凉早，思倦飜嫌夜漏迟。
何处山川孤馆里，向灯弯尽一双眉。','',''),('quantangshi-38203','寄禅师','韓偓','quantangshi','','卷39','从无入有云峰聚，已有还无电火销。
销聚本来皆是幻，世间闲口漫嚣嚣。','',''),('quantangshi-38204','访明公大德','韓偓','quantangshi','','卷39','寸发如霜袒右肩，倚肩筇竹貌怡然。
悬灯深屋夜分坐，移榻向阳斋后眠。
刮膜且扬三毒论，摄心徐指二宗禅。
清凉药分能知味，各自胷中有醴泉。','',''),('quantangshi-38205','大酺乐','韓偓','quantangshi','','卷39','晚日催弦管，春风入绮罗。
杏花如有意，偏落舞衫多。','',''),('quantangshi-38206','思归乐','韓偓','quantangshi','','卷39','泪滴珠难尽，容殊玉易销。
傥随明月去，莫道梦魂遥。','',''),('quantangshi-38207','御制春游长句','韓偓','quantangshi','','卷39','天意分明道已光，春游嘉景胜仙乡。
玉炉烟直风初静，银汉云消日正长。
柳带似眉全展绿，杏苞如脸半开香。
黄莺历历啼红树，紫燕关关语画梁。
低槛晚晴笼翡翠，小池波暖浴鸳鸯。
马嘶广陌贪新草，人醉花堤怕夕阳。
比屋管弦呈妙曲，连营罗绮鬬时妆。
全吴霸越千年后，独此升平显万方。','',''),('quantangshi-38208','幽窗','韓偓','quantangshi','','卷39','刺绣非无暇，幽窗自尟欢。
手香江橘嫩，齿輭越梅酸。
密约临行怯，私书欲报难。
无凭谙鹊语，犹得暂心宽。','',''),('quantangshi-38209','江楼二首 一','韓偓','quantangshi','','卷39','梦啼呜咽觉无语，杳杳微微望烟浦。
楼空客散燕交飞，江静帆飞日亭午。','',''),('quantangshi-38210','江楼二首 二','韓偓','quantangshi','','卷39','鳀鱼苦笋香味新，杨柳酒旗三月春。
风光百计牵人老，争奈多情是病身。','',''),('quantangshi-38211','春尽日','韓偓','quantangshi','','卷39','树头初日照西檐，树底蔫花夜雨霑。
外院池亭闻动锁，后堂阑槛见垂帘。
柳腰入户风斜倚，榆荚堆墙水半淹。
把酒送春惆怅在，年年三月病厌厌。','',''),('quantangshi-38212','咏灯','韓偓','quantangshi','','卷39','高在酒楼明锦幕，远随渔艇泊烟江。
古来幽怨皆销骨，休向长门背雨窗。','',''),('quantangshi-38213','别绪','韓偓','quantangshi','','卷39','别绪静愔愔，牵愁暗入心。
已回花渚棹，悔听酒垆琴。
菊露凄罗幕，棃霜恻锦衾。
此生终独宿，到死誓相寻。
月好知何计，歌阑叹不禁。
山巅更高处，忆上上头吟。','',''),('quantangshi-38214','见花','韓偓','quantangshi','','卷39','褰裳拥鼻正吟诗，日午墙头独见时。
血染蜀罗山踯躅，肉红宫锦海棠棃。
因狂得病真闲事，欲咏无才是所悲。
看却东风归去也，争教判得最繁枝。','',''),('quantangshi-38215','马上见','韓偓','quantangshi','','卷39','骄马锦连钱，乘骑是谪仙。
和帬穿玉镫，隔袖把金鞭。
去带懵腾醉，归成困顿眠。
自怜输廐吏，余暖在香鞯。','',''),('quantangshi-38216','绕廊','韓偓','quantangshi','','卷39','浓烟隔帘香漏泄，斜灯映竹光参差。
绕廊倚柱堪惆怅，细雨轻寒花落时。','',''),('quantangshi-38217','屐子','韓偓','quantangshi','','卷39','方寸肤圆光致致，白罗绣屧红托里。
南朝天子欠风流，却重金莲轻绿齿。','',''),('quantangshi-38218','青春','韓偓','quantangshi','','卷39','眼意心期卒未休，暗中终拟约秦楼。
光阴负我难相遇，情绪牵人不自由。
遥夜定嫌香蔽膝，闷时应弄玉搔头。
樱桃花谢棃花发，肠断青春两处愁。','',''),('quantangshi-38219','闻雨','韓偓','quantangshi','','卷39','香侵蔽膝夜寒轻，闻雨伤春梦不成。
罗帐四垂红烛背，玉钗敲着枕函声。','',''),('quantangshi-38220','嬾起','韓偓','quantangshi','','卷39','百舌唤朝眠，春心动几般。
枕痕霞黯澹，泪粉玉阑珊。
笼绣香烟歇，屏山烛焰残。
暖嫌罗韤窄，瘦觉锦衣宽。
昨夜三更雨，今朝一阵寒。
海棠花在否，侧卧卷帘看。','',''),('quantangshi-38221','已凉','韓偓','quantangshi','','卷39','碧阑干外绣帘垂，猩血屏风画折枝。
八尺龙须方锦褥，已凉天气未寒时。','',''),('quantangshi-38222','欲去','韓偓','quantangshi','','卷39','纷纭隔窗语，重约蹋青期。
总得相逢处，无非欲去时。
恨深书不尽，宠极意多疑。
惆怅桃源路，惟教梦寐知。','',''),('quantangshi-38223','横塘','韓偓','quantangshi','','卷39','秋寒洒背入帘霜，凤胫灯清照洞房。
蜀纸麝煤沾笔兴，越瓯犀液发茶香。
风飘乱点更筹转，拍送繁弦曲破长。
散客出门斜月在，两眉愁思问横塘。','',''),('quantangshi-38224','五更','韓偓','quantangshi','','卷39','往年曾约郁金牀，半夜潜身入洞房。
怀里不知金钿落，暗中唯觉绣鞵香。
此时欲别魂俱断，自后相逢眼更狂。
光景旋消惆怅在，一生赢得是凄凉。','',''),('quantangshi-38225','联缀体','韓偓','quantangshi','','卷39','院宇秋明日日长，社前一雁到辽阳。
陇头针线年年事，不喜寒砧捣断肠。','',''),('quantangshi-38226','半睡','韓偓','quantangshi','','卷39','抬镜仍嫌重，更衣又怕寒。
宵分未归帐，半睡待郎看。','',''),('quantangshi-38227','寒食夜','韓偓','quantangshi','','卷39','清江碧草两悠悠，各自风流一种愁。
正是落花寒食夜，夜深无伴倚南楼。','',''),('quantangshi-38228','哭花','韓偓','quantangshi','','卷39','曾愁香结破颜迟，今见妖红委地时。
若是有情争不哭，夜来风雨葬西施。','',''),('quantangshi-38229','重游曲江','韓偓','quantangshi','','卷39','鞭梢乱拂暗伤情，踪迹难寻露草青。
犹是玉轮曾辗处，一泓秋水涨浮萍。','',''),('quantangshi-38230','遥见','韓偓','quantangshi','','卷39','悲歌泪湿澹胭脂，闲立风吹金缕衣。
白玉堂东遥见后，令人斗薄画杨妃。','',''),('quantangshi-38231','新秋','韓偓','quantangshi','','卷39','一夜清风动扇愁，背时容色入新秋。
桃花脸里汪汪泪，忍到更深枕上流。','',''),('quantangshi-38232','宫词','韓偓','quantangshi','','卷39','绣帬斜立正销魂，侍女移灯掩殿门。
燕子不来花着雨，春风应自怨黄昏。','',''),('quantangshi-38233','蹋青','韓偓','quantangshi','','卷39','蹋青会散欲归时，金车久立频催上。
收帬整髻故迟迟，两点深心各惆怅。','',''),('quantangshi-38234','夜深','韓偓','quantangshi','','卷39','恻恻轻寒翦翦风，小梅飘雪杏花红。
夜深斜搭秋千索，楼阁朦胧烟雨中。','',''),('quantangshi-38235','夏日','韓偓','quantangshi','','卷39','庭树新阴叶未成，玉阶人静一蝉声。
相风不动乌龙睡，时有娇莺自唤名。','',''),('quantangshi-38236','新上头','韓偓','quantangshi','','卷39','学梳松鬓试新帬，消息佳期在此春。
为要好多心转惑，徧将宜称问傍人。','',''),('quantangshi-38237','中庭','韓偓','quantangshi','','卷39','夜短睡迟慵早起，日高方始出纱窗。
中庭自摘青梅子，先向钗头戴一双。','',''),('quantangshi-38238','咏浴','韓偓','quantangshi','','卷39','再整鱼犀拢翠簪，解衣先觉冷森森。
教移兰烛频羞影，自试香汤更怕深。
初似洗花难抑按，终忧沃雪不胜任。
岂知侍女帘帷外，剩取君王几饼金。','',''),('quantangshi-38239','席上有赠','韓偓','quantangshi','','卷39','矜严标格绝嫌猜，嗔怒虽逢笑靥开。
小雁斜侵眉柳去，媚霞横接眼波来。
鬓垂香颈云遮藕，粉着兰胷雪压梅。
莫道风流无宋玉，好将心力事妆台。','',''),('quantangshi-38240','早归','韓偓','quantangshi','','卷39','去是黄昏后，归当胧{月悤}时。
扠衣吟宿醉，风露动相思。','',''),('quantangshi-38241','玉合','韓偓','quantangshi','','卷39','罗囊绣两凤皇，玉合雕双鸂鶒。
中有兰膏渍红豆，每回拈着长相忆。
长相忆，经几春。
人怅望，香氤氲。
开缄不见新书迹，带粉犹残旧泪痕。','',''),('quantangshi-38242','金陵','韓偓','quantangshi','','卷39','风雨萧萧，石头城下木兰桡。
烟月迢迢，金陵渡口去来潮。
自古风流皆暗销，才魂妖魂谁与招。
彩牋丽句今已矣，罗韈金莲何寂寥。','',''),('quantangshi-38243','嬾卸头','韓偓','quantangshi','','卷39','侍女动妆籢，故故惊人睡。
那知本未眠，背面偷垂泪。
嬾卸凤皇钗，羞入鸳鸯被。
时复见残灯，和烟坠金穗。','',''),('quantangshi-38244','倚醉','韓偓','quantangshi','','卷39','倚醉无端寻旧约，却怜惆怅转难胜。
静中楼阁深春雨，远处帘栊半夜灯。
抱柱立时风细细，绕廊行处思腾腾。
分明窗下闻裁翦，敲徧阑干唤不譍。','',''),('quantangshi-38245','咏手','韓偓','quantangshi','','卷39','腕白肤红玉笋芽，调琴抽线露尖斜。
背人细拈垂胭鬓，向镜轻匀衬脸霞。
怅望昔逢褰绣幔，依稀曾见托金车。
后园笑向同行道，摘得蘼芜又折花。','',''),('quantangshi-38246','荷花','韓偓','quantangshi','','卷39','纨扇相敧绿，香囊独立红。
浸淫因重露，狂暴是秋风。
逸调无人唱，秋塘每夜空。
何繇见周昉，移入画屏中。','',''),('quantangshi-38247','松髻','韓偓','quantangshi','','卷39','髻根松慢玉钗垂，指点花枝又过时。
坐久暗生惆怅事，背人匀却泪胭脂。','',''),('quantangshi-38248','寄远','韓偓','quantangshi','','卷39','眉如半月云如鬟，梧桐叶落敲井阑。
孤灯亭亭公署寒，微霜凄凄客衣单。
想美人兮云一端，梦魂悠悠关山难。
空房展转怀悲酸，铜壶漏尽闻金鸾。','',''),('quantangshi-38249','踪迹','韓偓','quantangshi','','卷39','东乌西兔似车轮，劫火桑田不复论。
唯有风光与踪迹，思量长是暗销魂。','',''),('quantangshi-38250','病忆','韓偓','quantangshi','','卷39','信知尤物必牵情，一顾难酬觉命轻。
曾把禅机销此病，破除才尽又重生。','',''),('quantangshi-38251','妬媒','韓偓','quantangshi','','卷39','洞房深闭不曾开，横卧乌龙作妬媒。
好鸟岂劳兼比翼，异华何必更重台。
难留旋逐惊飙去，暂见如随急电来。
多为过防成后悔，偶因翻语得深猜。
已嫌刻蜡春宵短，最恨鸣珂晓鼓催。
应笑楚囊仙分薄，日中长是独裴回。','',''),('quantangshi-38252','不见','韓偓','quantangshi','','卷39','动静防闲又怕疑，佯佯脉脉是深机。
此身愿作君家燕，秋社归时也不归。','',''),('quantangshi-38253','昼寝','韓偓','quantangshi','','卷39','碧桐阴尽隔帘栊，扇拂金鹅玉簟烘。
扑粉更添香体滑，解衣唯见下裳红。
烦襟乍触冰壶冷，倦枕徐敧宝髻松。
何必苦劳魂与梦，王昌只在此墙东。','',''),('quantangshi-38254','意绪','韓偓','quantangshi','','卷39','绝代佳人何寂寞，棃花未发梅花落。
东风吹雨入西园，银线千条度虚阁。
脸粉难匀蜀酒浓，口脂易印吴绫薄。
娇饶意态不胜羞，愿倚郎肩永相着。','',''),('quantangshi-38255','惆怅','韓偓','quantangshi','','卷39','身情长在暗相随，生魄随君君岂知。
被头不暖空霑泪，钗股欲分犹半疑。
朗月清风难惬意，词人绝色多伤离。
何如饮酒连千醉，席地幕天无所知。','',''),('quantangshi-38256','忍笑','韓偓','quantangshi','','卷39','宫样衣裳浅画眉，晚来梳洗更相宜。
水精鹦鹉钗头颤，举袂佯羞忍笑时。','',''),('quantangshi-38257','咏柳','韓偓','quantangshi','','卷39','褭雨拖风不自持，全身无力向人垂。
玉纤折得遥相赠，便似观音手里时。','',''),('quantangshi-38258','密意','韓偓','quantangshi','','卷39','呵花贴鬓黏寒发，凝酥光透猩猩血。
经过洛水几多人，唯有陈王见罗韈。','',''),('quantangshi-38259','偶见','韓偓','quantangshi','','卷39','秋千打困解罗帬，指点醍醐索一尊。
见客入来和笑走，手搓梅子映中门。','',''),('quantangshi-38260','寒食夜有寄','韓偓','quantangshi','','卷39','风流大抵是伥伥，此际相思必断肠。
云薄月昏寒食夜，隔帘微雨杏花香。','',''),('quantangshi-38261','寒食夜有寄','韓偓','quantangshi','','卷39','风流大抵是伥伥，一度相思一断肠。
云薄月昏寒食夜，隔帘微雨杏花香。','',''),('quantangshi-38262','效崔国辅体四首 一','韓偓','quantangshi','','卷39','澹月照中庭，海棠花自落。
独立俯闲阶，风动秋千索。','',''),('quantangshi-38263','效崔国辅体四首 二','韓偓','quantangshi','','卷39','雨后碧苔院，霜来红叶楼。
闲阶上斜日，鹦鹉伴人愁。','',''),('quantangshi-38264','效崔国辅体四首 三','韓偓','quantangshi','','卷39','酒力滋睡眸，卤莽闻街鼓。
欲明天更寒，东风打窗雨。','',''),('quantangshi-38265','效崔国辅体四首 四','韓偓','quantangshi','','卷39','罗幕生春寒，绣窗愁未眠。
南湖一夜雨，应湿采莲船。','',''),('quantangshi-38266','后魏时相州人作李波小妹歌疑其未备因补之','韓偓','quantangshi','','卷39','李波小妹字雍容，窄衣短袖蛮锦红。
未解有情梦梁殿，何曾自媚妒吴宫。
难教牵引知酒味，因令怅望成春慵。
海棠花下秋千畔，背人撩鬓道怱怱。','',''),('quantangshi-38267','春昼','韓偓','quantangshi','','卷39','春融艳艳，大醉陶陶。
漏添迟日，箭减良宵。
藤垂戟户，柳拂河桥。
帘幕燕子，池塘[伯]劳。
肤清臂瘦，衫薄香销。
楚殿衣窄，南朝髻高。
河阳县远，清波地遥。
丝缠露泣，各自无憀。','',''),('quantangshi-38268','三忆 一','韓偓','quantangshi','','卷39','忆眠时，春梦困腾腾。
展转不能起，玉钗垂枕棱。','',''),('quantangshi-38269','三忆 二','韓偓','quantangshi','','卷39','忆行时，背手挼金雀。
敛笑慢回头，步转阑干角。','',''),('quantangshi-38270','三忆 三','韓偓','quantangshi','','卷39','忆去时，向月迟迟行。
强语戏同伴，图郎闻笑声。','',''),('quantangshi-38271','六言三首 一','韓偓','quantangshi','','卷39','春楼处子倾城，金陵狎客多情。
朝云暮雨会合，罗韤绣被逢迎。
华山梧桐相覆，蛮江豆蔻连生。
幽欢不尽告别，秋河怅望平明。','',''),('quantangshi-38272','六言三首 二','韓偓','quantangshi','','卷39','一灯前雨落夜，三月尽草青时。
