惆怅空教梦见，懊恼多成酒悲。
红袖不干谁会，揉损联娟澹眉。','',''),('quantangshi-38273','六言三首 三','韓偓','quantangshi','','卷39','此间青草更远，不唯空绕汀洲。
那里朝日才出，还应先照西楼。
忆泪因成恨泪，梦游常续心游。
桃源洞口来否，绛节霓旌久留。','',''),('quantangshi-38274','寒食日重游李氏园亭有怀','韓偓','quantangshi','','卷39','往年同在鸾桥上，见倚朱阑咏柳緜。
今日独来香径里，更无人迹有苔钱。
伤心阔别三千里，屈指思量四五年。
料得他乡遇佳节，亦应怀抱暗凄然。','',''),('quantangshi-38275','思录旧诗于卷上凄然有感因成一章','韓偓','quantangshi','','卷39','缉缀小诗钞卷里，寻思闲事到心头。
自吟自泣无人会，肠断蓬山第一流。','',''),('quantangshi-38276','春闺二首 一','韓偓','quantangshi','','卷39','愿结交加梦，因倾潋滟尊。
醒来情绪恶，帘外正黄昏。','',''),('quantangshi-38277','春闺二首 二','韓偓','quantangshi','','卷39','氤氲帐里香，薄薄睡时妆。
长吁解罗带，怯见上空牀。','',''),('quantangshi-38278','代小玉家为蕃骑所虏后寄故集贤裴公相国','韓偓','quantangshi','','卷39','动天金鼓逼神州，惜别无心学坠楼。
不得回眸辞傅粉，便须含泪对残秋。
折钗伴妾埋青冢，半镜随郎葬杜邮。
唯有此宵魂梦里，殷勤见觅凤池头。','',''),('quantangshi-38279','荐福寺讲筵偶见又别','韓偓','quantangshi','','卷39','见时浓日午，别处暮钟残。
景色疑春尽，襟怀似酒阑。
两情含眷恋，一饷致辛酸。
夜静长廊下，难寻屐齿看。','',''),('quantangshi-38280','复偶见三绝 一','韓偓','quantangshi','','卷39','雾为襟袖玉为冠，半似羞人半忍寒。
别易会难长自叹，转身应把泪珠弹。','',''),('quantangshi-38281','复偶见三绝 二','韓偓','quantangshi','','卷39','桃花脸薄难藏泪，柳叶眉长易觉愁。
密迹未成当面笑，几回抬眼又低头。','',''),('quantangshi-38282','复偶见三绝 三','韓偓','quantangshi','','卷39','半身映竹轻闻语，一手揭帘微转头。
此意别人应未觉，不胜情绪两风流。','',''),('quantangshi-38283','厌花落','韓偓','quantangshi','','卷39','厌花落，人寂寞。
果树阴成燕翅齐，西园永日闲高阁。
后堂夹帘愁不卷，低头闷把衣襟拈。
忽然事到心中来，四肢娇入茸茸眼。
也曾同在华堂宴，佯佯拢鬓偷回面。
半醉狂心忍不禁，分明一任傍人见。
书中说却平生事，犹疑未满情郎意。
锦囊封了又重开，夜深窗下烧红纸。
红纸千张言不尽，至诚无语传心印。
但得鸳鸯枕臂眠，也任时光都一瞬。','',''),('quantangshi-38284','春闷偶成十二韵','韓偓','quantangshi','','卷39','阡陌悬云壤，阑畦隔艾芝。
路遥行雨嬾，河阔过桥迟。
雁足应难达，狐踪浪得疑。
谢鲲吟未废，张硕梦堪思。
有意通情处，无言拢鬓时。
格高归敛笑，歌怨在颦眉。
醉后金蝉重，欢余玉燕敧。
素姿凌白柰，圆颊诮红棃。
粉字题花笔，香牋咏柳诗。
绣窗携手约，芳草蹋青期。
别泪开泉脉，春愁罥藕丝。
相思不相信，幽恨更谁知。','',''),('quantangshi-38285','想得','韓偓','quantangshi','','卷39','两重门里玉堂前，寒食花枝月午天。
想得那人垂手立，娇羞不肯上秋千。','',''),('quantangshi-38286','偶见背面是夕兼梦','韓偓','quantangshi','','卷39','酥凝背胛玉搓肩，轻薄红绡覆白莲。
此夜分明来入梦，当时惆怅不成眠。
眼波向我无端艳，心火因君特地然。
莫道人生难际会，秦楼鸾凤有神仙。','',''),('quantangshi-38287','五更','韓偓','quantangshi','','卷39','秋雨五更头，桐竹鸣骚屑。
却似残春间，断送花时节。
空楼雁一声，远屏灯半灭。
绣被拥娇寒，眉山正愁绝。','',''),('quantangshi-38288','有忆','韓偓','quantangshi','','卷39','昼漏迢迢夜漏迟，倾城消息杳无期。
愁肠泥酒人千里，泪眼倚楼天四垂。
自笑计狂多独语，谁怜梦好转相思。
何时斗帐浓香里，分付东风与玉儿。','',''),('quantangshi-38289','半夜','韓偓','quantangshi','','卷39','板合数尊后，至今犹酒悲。
一宵相见事，半夜独眠时。
明朝窗下照，应有鬓如丝。','',''),('quantangshi-38290','信笔','韓偓','quantangshi','','卷39','睡髻休频拢，春眉忍更长。
整钗栀子重，泛酒菊花香。
绣叠昏金色，罗揉损砑光。
有时闲弄笔，亦画两鸳鸯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38291','寄恨','韓偓','quantangshi','','卷39','秦钗枉断长条玉，蜀纸虚留小字红。
死恨物情难会处，莲花不肯嫁春风。','',''),('quantangshi-38292','两处','韓偓','quantangshi','','卷39','楼上澹山横，楼前沟水清。
怜山又怜水，两处总牵情。','',''),('quantangshi-38293','拥鼻','韓偓','quantangshi','','卷39','拥鼻悲吟一向愁，寒更转尽未回头。
绿屏无睡秋分簟，红叶伤心月午楼。
却要因循添逸兴，若为趋竞怆离忧。
殷勤凭仗官渠水，为到西溪动钓舟。','',''),('quantangshi-38294','闺怨','韓偓','quantangshi','','卷39','时光潜去暗凄凉，嬾对菱花晕晓妆。
初坼秋千人寂寞，后园青草任他长。','',''),('quantangshi-38295','褭娜','韓偓','quantangshi','','卷39','褭娜腰肢澹薄妆，六朝宫样窄衣裳。
着词暂见樱桃破，飞盏遥闻豆蔻香。
春恼情怀身觉瘦，酒添颜色粉生光。
此时不敢分明道，风月应知暗断肠。','',''),('quantangshi-38296','多情','韓偓','quantangshi','','卷39','天遣多情不自持，多情兼与病相宜。
蠭偷野蜜初尝处，莺啄含桃欲咽时。
酒荡襟怀微駊騀，春牵情绪更融怡。
水香剩置金盆里，琼树长须浸一枝。','',''),('quantangshi-38297','偶见','韓偓','quantangshi','','卷39','千金莫惜旱莲生，一笑从教下蔡倾。
仙树有花难问种，御香闻气不知名。
愁来自觉歌喉咽，瘦去谁怜舞掌轻。
小叠红笺书恨字，与奴方便寄卿卿。','',''),('quantangshi-38298','个侬','韓偓','quantangshi','','卷39','甚感殷勤意，其如阻碍何。
隔帘窥绿齿，映柱送横波。
老大逢知少，襟怀暗喜多。
因倾一尊酒，聊以慰蹉跎。','',''),('quantangshi-38299','无题 一','韓偓','quantangshi','','卷39','小槛移灯灺，空房锁隙尘。
额波风尽日，帘影月侵晨。
香辣更衣后，钗梁拢鬓新。
吉音闻诡计，醉语近天真。
妆好方长叹，欢余却浅颦。
绣屏金作屋，丝幰玉为轮。
致意通緜竹，精诚托锦鳞。
歌凝眉际恨，酒发脸边春。
溪紵殊倾越，楼箫岂羡秦。
柳虚禳沴气，梅实引芳津。
乐府降清唱，宫厨减食珍。
防闲襟并敛，忍妬泪休匀。
宿饮愁萦梦，春寒瘦着人。
手持双豆蔻，的的为东邻。','',''),('quantangshi-38300','无题 二','韓偓','quantangshi','','卷39','碧瓦偏光日，红帘不受尘。
柳昏连绿野，花烂烁清晨。
书密偷看数，情通破体新。
明言终未实，暗祝始应真。
枉道嫌偷药，推诚鄙效颦。
合成云五色，宜作日中轮。
照兽金涂爪，钗鱼玉镂鳞。
渺弥三岛浪，平远一楼春。
堕髻还名寿，修蛾本姓秦。
棹寻闻犬洞，槎入饮牛津。
麟脯随重酿，霜华间八珍。
锦囊霞彩烂，罗韤砑光匀。
羞涩佯牵伴，娇饶欲泥人。
偷儿难捉搦，慎莫共比邻。','',''),('quantangshi-38301','无题 三','韓偓','quantangshi','','卷39','紫蜡融花蔕，红緜拭镜尘。
梦狂飜惜夜，妆嬾厌凌晨。
茜袖啼痕数，香牋墨色新。','',''),('quantangshi-38302','倒押前韵','韓偓','quantangshi','','卷39','白下同归路，乌衣枉作邻。
佩声犹隔箔，香气已迎人。
酒劝杯须满，书羞字不匀。
歌怜黄竹怨，味实碧桃珍。
翦烛非良策，当关是要津。
东阿初度洛，杨恽旧家秦。
粉化横波溢，衫轻晓雾春。
鵶黄双凤翅，麝月半鱼鳞。
别袂飜如浪，回肠转似轮。
后期才注脚，前事又含颦。
纵有才难咏，宁无画逼真。
天香闻更有，琼树见长新。
鬬草常更仆，迷阄误达晨。
齅花判不得，檀注惹风尘。','',''),('quantangshi-38303','闺情','韓偓','quantangshi','','卷39','轻风滴砾动帘钩，宿酒犹酣嬾卸头。
但觉夜深花有露，不知人静月当楼。
何郎烛暗谁能咏，韩寿香焦亦任偷。
敲折玉钗歌转咽，一声声作两眉愁。','',''),('quantangshi-38304','自负','韓偓','quantangshi','','卷39','人许风流自负才，偷桃三度到瑶台。
至今衣领胭脂在，曾被谪仙痛齩来。','',''),('quantangshi-38305','天凉','韓偓','quantangshi','','卷39','愁来却讶天凉早，思倦飜嫌夜漏迟。
何处山川孤馆里，向灯弯尽一双眉。','',''),('quantangshi-38306','日高','韓偓','quantangshi','','卷39','朦胧犹记管弦声，噤[㾕]余寒酒半醒。
春暮日高帘半卷，落花和雨满中庭。','',''),('quantangshi-38307','夕阳','韓偓','quantangshi','','卷39','花前洒泪临寒食，醉里回头问夕阳。
不管相思人老尽，朝朝容易下西墙。','',''),('quantangshi-38308','旧馆','韓偓','quantangshi','','卷39','前欢往恨分明在，酒兴诗情大半亡。
还似墙西紫荆树，残花摘索映高塘。','',''),('quantangshi-38309','中春忆赠','韓偓','quantangshi','','卷39','年年长是阻佳期，万种恩情只自知。
春色转添惆怅事，似君花发两三枝。','',''),('quantangshi-38310','春恨','韓偓','quantangshi','','卷39','残梦依依酒力余，城头画角伴啼乌。
平明未卷西楼幕，院静时闻响辘轳。','',''),('quantangshi-38311','秋千','韓偓','quantangshi','','卷39','池塘夜歇清明雨，绕院无尘近花坞。
五丝绳系出墙迟，力尽才瞵见邻圃。
下来娇喘未能调，斜倚朱阑久无语。
无语兼动所思愁，转眼看天一长吐。','',''),('quantangshi-38312','长信宫二首 一','韓偓','quantangshi','','卷39','天上梦魂何杳杳，宫中消息太沈沈。
君恩不似黄金井，一处团圆万丈深。','',''),('quantangshi-38313','长信宫二首 二','韓偓','quantangshi','','卷39','天上凤皇休寄梦，人间鹦鹉旧堪悲。
平生心绪无人识，一只金梭万丈丝。','',''),('quantangshi-38314','句','韓偓','quantangshi','','卷39','岂独鸱夷解归去，五湖渔艇且哺糟。','',''),('quantangshi-38315','奉和御制','吳融','quantangshi','','卷39','岳寺清秋霁，宸游永日闲。
霓旌森物外，凤吹落人间。
玉漱穿城水，屏开对阙山。
皆知圣情悦，丽藻洒芳兰。','',''),('quantangshi-38316','和集贤相公西溪侍宴观竞渡','吳融','quantangshi','','卷39','片水耸层桥，祥烟霭庆霄。
昼花铺广宴，晴电闪飞桡。
浪叠摇仙仗，风微定彩标。
都人同盛观，不觉在行朝。','',''),('quantangshi-38317','山居即事四首 一','吳融','quantangshi','','卷39','桂树秋来风满枝，碧岩归日免乖期。
故人尽向蟾宫折，独我攀条欲寄谁。','',''),('quantangshi-38318','山居即事四首 二','吳融','quantangshi','','卷39','不傲南窗且采樵，干松每带湿云烧。
庖厨却得长兼味，三秀芝根五术苗。','',''),('quantangshi-38319','山居即事四首 三','吳融','quantangshi','','卷39','万事翛然只有棊，小轩高净簟凉时。
阑珊半局和微醉，花落中庭树影移。','',''),('quantangshi-38320','山居即事四首 四','吳融','quantangshi','','卷39','无邻无里不成村，水曲云重掩石门。
何用深求避秦客，吾家便是武陵源。','',''),('quantangshi-38321','红白牡丹','吳融','quantangshi','','卷39','不必繁弦不必歌，静中相对更情多。
殷鲜一半霞分绮，洁澈旁边月颭波。
看久愿成庄叟梦，惜留须倩鲁阳戈。
重来应共今来别，风堕香残衬绿莎。','',''),('quantangshi-38322','中秋陪熙用学士禁中翫月','吳融','quantangshi','','卷39','月圆年十二，秋半每多阴。
此夕无纤霭，同君宿禁林。
未高知海阔，当午见宫深。
衣似繁霜透，身疑积水沈。
遭逢陪侍辇，归去忆抽簪。
太液池南岸，相期到晓吟。','',''),('quantangshi-38323','题豪家故池','吳融','quantangshi','','卷39','岁久无泉引，春来仰雨流。
萍枯黏朽槛，沙浅露沈舟。
照影人何在，持竿客寄游。
翛然兴废外，回首谢眠鸥。','',''),('quantangshi-38324','偶题','吳融','quantangshi','','卷39','贱子曾尘国士知，登门倒屣忆当时。
西州酌尽看花酒，东阁编成咏雪诗。
莫道精灵无伯有，寻闻任侠报爰丝。
乌衣旧宅犹能认，粉竹金松一两枝。','',''),('quantangshi-38325','渚宫立春书怀','吳融','quantangshi','','卷39','春候侵残腊，江芜绿已齐。
风高莺啭澁，雨密雁飞低。
向日心须在，归朝路欲迷。
近闻惊御火，犹及灞陵西。','',''),('quantangshi-38326','闻李翰林游池上有寄','吳融','quantangshi','','卷39','花飞絮落水和流，玉署词臣奉诏游。
四面看人随画鷁，中流合乐起眠鸥。
皇恩自抱丹心报，清颂谁将白雪酬。
不为禁钟催入宿，前峰月上未回舟。','',''),('quantangshi-38327','谷口寓居偶题','吳融','quantangshi','','卷39','涔涔病骨怯朝天，谷口归来取性眠。
峭壁削成开画障，急溪飞下咽繁弦。
不能尘土争闲事，且放形神学散仙。','',''),('quantangshi-38328','无题','吳融','quantangshi','','卷39','万态千端一瞬中，沁园芜没伫秋风。
䴔䴖夜警池塘冷，蝙蝠昼飞楼阁空。
粉貌早闻残洛市，箫声犹自傍秦宫。
今朝陌上相非者，曾此歌钟几醉同。','',''),('quantangshi-38329','赋雪','吳融','quantangshi','','卷39','一夜阴风度，平明颢气交。
未知融结判，唯见混茫包。
路莫藏行迹，林难出树梢。
气应封兽穴，险必堕禽巢。
影密灯回照，声繁竹送敲。
翫宜苏让点，飡称蜜匀抄。
结冻防鱼跃，黏沙费马跑。
炉寒资爇荻，屋暖赖编茅。
远不分山叠，低宜失地坳。
阑干高百尺，新霁若为抛。','',''),('quantangshi-38330','寄僧','吳融','quantangshi','','卷39','柳拂池光一点清，紫方袍袖杖藜行。
偶传新句来中禁，谁把闲书寄上卿。
锡倚山根重藓破，棊敲石面碎云生。
应怜正视淮王诏，不识东林物外情。','',''),('quantangshi-38331','酬僧','吳融','quantangshi','','卷39','吾师既续惠休才，况值高秋万象开。
吟处远峰横落照，定中黄叶下青苔。
双林不见金兰久，丹楚空翻组绣来。
闻说近郊寒尚绿，登临应待一追陪。','',''),('quantangshi-38332','题延寿坊东南角古池','吳融','quantangshi','','卷39','蔓草萧森曲岸摧，水笼沙浅露莓苔。
更无蔟蔟红妆点，犹有双双翠羽来。
雨细几逢耕犊去，日斜时见钓人回。
繁华自古皆相似，金谷荒园土一堆。','',''),('quantangshi-38333','登鹳雀楼','吳融','quantangshi','','卷39','鸟在林梢脚底看，夕阳无际戍烟残。
冻开河水奔浑急，雪洗条山错落寒。
始为一名抛故国，近因多难怕长安。
祖鞭掉折徒为尔，赢得云溪负钓竿。','',''),('quantangshi-38334','和峡州冯使君题所居','吳融','quantangshi','','卷39','三年拔薤成仁政，一日诛茅葺所居。
晓岫近排吟阁冷，夜江遥响寝堂虚。
唯怀避地逃多难，不羡朝天卧直庐。
记得街西邻舍否，投荒南去五千余。','',''),('quantangshi-38335','秋日感事','吳融','quantangshi','','卷39','一叶飘然夕照沈，世间何事不经心。
几人欲话云台峻，独我方探禹穴深。
鸡檄固应无下策，鹤书还要问中林。
自怜情为多忧动，不为西风白露吟。','',''),('quantangshi-38336','莺','吳融','quantangshi','','卷39','日落林西鸟未知，自先飞上最高枝。
千啼万语不离恨，已去又来如有期。
惯识江南春早处，长惊蓟北梦回时。
谢家园里成吟久，只欠池塘一句诗。','',''),('quantangshi-38337','次韵和王员外杂游四韵','吳融','quantangshi','','卷39','一分难减亦难加，得似溪头浣越纱。
两桨惯邀催去艇，七香曾占取来车。
黄昏忽堕当楼月，清晓休开满镜花。
谁见玉郎肠断处，露牀风簟半欹斜。','',''),('quantangshi-38338','秋事','吳融','quantangshi','','卷39','江天暑气自凉清，物候须知一雨成。
松竹健来唯欠语，蕙兰衰去始多情。
他年拟献书空在，此日知机意尽平。
更欲轻桡放烟浪，苇花深处睡秋声。','',''),('quantangshi-38339','和陆拾遗题谏院松','吳融','quantangshi','','卷39','落落孤松何处寻，月华西畔结根深。
晓含仙掌三清露，晚上宫墙百雉阴。
野鹤不归应有怨，白云高去太无心。
碧岩秋涧休相望，捧日元须在禁林。','',''),('quantangshi-38340','题杨子津亭','吳融','quantangshi','','卷39','杨子江津十四经，纪行文字徧长亭。
惊人旅鬓斩新白，无事海门依旧青。
前路莫知霜凛凛，故乡何处雁冥冥。
可怜不识生离者，数点渔帆落暮汀。','',''),('quantangshi-38341','闲望','吳融','quantangshi','','卷39','三点五点映山雨，一枝两枝临水花。
蛱蝶狂飞掠芳草，鸳鸯稳睡翘暖沙。
阙下新居成别业，江南旧隐是谁家。
东迁西去俱无计，却羡暝归林上鸦。','',''),('quantangshi-38342','雪后过昭应','吳融','quantangshi','','卷39','路过章台气象宽，九重城阙在云端。
烟含上苑沈沈紫，雪露南山悚悚寒。
绮陌已堪骑宝马，绿芜行即弹金丸。
灞川南北真图画，更待残阳一望看。','',''),('quantangshi-38343','商人','吳融','quantangshi','','卷39','百尺竿头五两斜，此生何处不为家。
北抛衡岳南过雁，朝发襄阳暮看花。
蹭蹬也应无陆地，团圆应觉有天涯。
随风逐浪年年别，却笑如期八月槎。','',''),('quantangshi-38344','岐下闻杜鹃','吳融','quantangshi','','卷39','化去蛮乡北，飞来渭水西。
为多亡国恨，不忍故山啼。
怨已惊秦凤，灵应识汉鸡。
数声烟漠漠，余思草萋萋。
楼迥波无际，林昏日又低。
如何不肠断，家近五云溪。','',''),('quantangshi-38345','雨后闻思归乐二首 一','吳融','quantangshi','','卷39','山禽连夜叫，兼雨未尝休。
尽道思归乐，应多离别愁。
我家方旅食，故国在沧洲。
闻此不能寐，青灯茆屋幽。','',''),('quantangshi-38346','雨后闻思归乐二首 二','吳融','quantangshi','','卷39','一夜鸟飞鸣，关关彻五更。
似因归路隔，长使别魂惊。
未省愁雨暗，就中伤月明。
须知越吟客，欹枕不胜情。','',''),('quantangshi-38347','中夜闻啼禽','吳融','quantangshi','','卷39','漠漠苍苍未五更，宿禽何处两三声。
若非西涧回波触，即是南塘急雨惊。
金屋独眠堪寄恨，商陵永诀更牵情。
此时归梦随肠断，半壁残灯闪闪明。','',''),('quantangshi-38348','灵池县见早梅','吳融','quantangshi','','卷39','小园晴日见寒梅，一寸乡心万里回。
春日暖时抛笠泽，战尘飞处上琴台。
栖身未识登龙地，落笔元非倚马才。
待勒燕然归未得，雪枝南畔少徘徊。','',''),('quantangshi-38349','野庙','吳融','quantangshi','','卷39','古原荒庙揜莓苔，何处喧喧鼓笛来。
日暮鸟归人散尽，野风吹起纸钱灰。','',''),('quantangshi-38350','闲书','吳融','quantangshi','','卷39','接鹭陪鸾漫得羣，未如高卧紫溪云。
晋阳起义寻常见，湖口屯营取次闻。
大底鹪鹏须自适，何尝玉石不同焚。
回看带砺山河者，济得危时没旧勋。','',''),('quantangshi-38351','寄贯休上人','吳融','quantangshi','','卷39','别来如梦亦如云，八字微言不复闻。
世上浮沈应念我，笔端飞动只降君。
几同江步吟秋霁，更忆山房语夜分。
见拟沃州寻旧约，且教丹顶许为邻。','',''),('quantangshi-38352','书怀','吳融','quantangshi','','卷39','傍岩依树结檐楹，夏物萧疎景更清。
滩响忽高何处雨，松阴自转远山晴。
见多邻犬遥相认，来惯幽禽近不惊。
争得便夸饶胜事，九衢尘里免劳生。','',''),('quantangshi-38353','重阳日荆州作','吳融','quantangshi','','卷39','万里投荒已自哀，高秋寓目更徘徊。
浊醪任冷难辞醉，黄菊因暄却未开。
上国莫归戎马乱，故人何在塞鸿来。
惊时感事俱无奈，不待残阳下楚台。','',''),('quantangshi-38354','寄贯休','吳融','quantangshi','','卷39','休公何处在，知我宦情无。
已似冯唐老，方知武子愚。
一身仍更病，双阙又须趋。
若得重相见，冥心学半铢。','',''),('quantangshi-38355','秋日渚宫即事','吳融','quantangshi','','卷39','漠漠澹云烟，秋归泽国天。
风高还促燕，雨细未妨蝉。
静引荒城望，凉惊旅枕眠。
更堪憔悴里，欲泛洞庭船。','',''),('quantangshi-38356','荆州寓居书怀','吳融','quantangshi','','卷39','一室四无邻，荒郊接古津。
幽闲消俗态，摇落露家贫。
绝迹思浮海，修书嬾寄秦。
东西不复问，翻笑泣岐人。','',''),('quantangshi-38357','和严谏议萧山庙十韵','吳融','quantangshi','','卷39','泽国瞻遗庙，云韶仰旧名。
一隅连障影，千仞落泉声。
老狖寻危栋，秋蛇束画楹。
路长资税驾，岁俭绝丰盛。
默默虽难测，昭昭本至平。
岂知迁去客，自有复来兵。
美舜歌徒作，欺尧犬正狞。
近兼闻顺动，敢复怨徂征。
日出天须霁，风休海自清。
肺肠无处说，一为启聪明。','',''),('quantangshi-38358','松江晚泊','吳融','quantangshi','','卷39','树远天疑尽，江奔地欲随。
孤帆落何处，残日更新离。
客是凄凉本，情为系滞枝。
寸肠无计免，应只楚猿知。','',''),('quantangshi-38359','湖州溪楼书献郑员外','吳融','quantangshi','','卷39','危槛等飞樯，闲追晚际凉。
青林上雨色，白鸟破溪光。
目以高须极，心因静更伤。
唯公旧相许，早晚侍长杨。','',''),('quantangshi-38360','秋兴','吳融','quantangshi','','卷39','微雨过菰苇，野居生早凉。
襟期渐萧洒，精爽欲飞扬。
鱼买罾头活，酒沽船上香。
不缘人不用，始道静胜忙。','',''),('quantangshi-38361','端居','吳融','quantangshi','','卷39','片雨过前汀，端居枕簟清。
病魔随暑退，诗思傍凉生。
别燕殷勤语，残蝉彷佛鸣。
古来悲不尽，况我本多情。','',''),('quantangshi-38362','途中','吳融','quantangshi','','卷39','一棹归何处，苍茫落照昏。
无人应失路，有树始知春。
湖岸春耕废，江城战鼓喧。
儒冠解相悞，学劒尽乘轩。','',''),('quantangshi-38363','西陵夜居','吳融','quantangshi','','卷39','寒潮落远汀，暝色入柴扃。
漏永沈沈静，灯孤的的清。
林风移宿鸟，池雨定流萤。
尽夜成愁绝，啼蛩莫近庭。','',''),('quantangshi-38364','燕雏','吳融','quantangshi','','卷39','掠水身犹重，偎风力尚微。
瓦苔难定立，檐雨忽喧归。
未识重溟远，先愁一叶飞。
衔泥在他日，两两占春晖。','',''),('quantangshi-38365','新秋','吳融','quantangshi','','卷39','白发又经秋，端居海上洲。
无机因事发，有涕为时流。
新酒乘凉压，残碁隔夜收。
公车无路入，同拜老闲侯。','',''),('quantangshi-38366','题越州法华寺','吳融','quantangshi','','卷39','寺在五峰阴，穿缘一径寻。
云藏古殿暗，石护小房深。
宿鸟连僧定，寒猨应客吟。
上方应见海，月出试登临。','',''),('quantangshi-38367','寒食洛阳道','吳融','quantangshi','','卷39','路岐无乐处，时节倍思家。
彩索扬轻吹，黄鹂啼落花。
连乹驰宝马，历禄鬬香车。
行客胜回首，看看春日斜。','',''),('quantangshi-38368','忆事','吳融','quantangshi','','卷39','去年花下把金巵，曾赋杨花数句诗。
回首朱门闭荒草，如今愁到牡丹时。','',''),('quantangshi-38369','金陵遇悟空上人','吳融','quantangshi','','卷39','东阁无人事渺茫，老僧持钵过丹阳。
十年栖止如何报，好与南谯剩炷香。','',''),('quantangshi-38370','途中','吳融','quantangshi','','卷39','柳弱风长在，云轻雨易休。
不劳芳草色，更惹夕阳愁。
万里独归去，五陵无与游。','',''),('quantangshi-38371','秋园','吳融','quantangshi','','卷39','始怜春草细霏霏，不觉秋来绿渐稀。
惆怅撷芳人散尽，满园烟露蝶高飞。','',''),('quantangshi-38372','富春','吳融','quantangshi','','卷39','天下有水亦有山，富春山水非人寰。
长川不是春来绿，千峰倒影落其间。','',''),('quantangshi-38373','山居即事','吳融','quantangshi','','卷39','小亭前面接青崖，白石交加衬绿苔。
日暮松声满阶砌，不关风雨鹤归来。','',''),('quantangshi-38374','寓言','吳融','quantangshi','','卷39','非明非暗朦朦月，不暖不寒慢慢风。
独卧空牀好天气，平生闲事到心中。','',''),('quantangshi-38375','华清宫二首 一','吳融','quantangshi','','卷39','四郊飞雪暗云端，唯此宫中落旋干。
绿树碧檐相掩映，无人知道外边寒。','',''),('quantangshi-38376','华清宫二首 二','吳融','quantangshi','','卷39','长生祕殿倚青苍，拟敌金庭不死乡。
无奈逝川东去急，秦陵松柏满残阳。','',''),('quantangshi-38377','过九成宫','吳融','quantangshi','','卷39','凤辇东归二百年，九成宫殿半荒阡。
魏公碑字封苍藓，文帝泉声落野田。
碧草断霑仙掌露，绿杨犹忆御炉烟。
升平旧事无人说，万叠青山但一川。','',''),('quantangshi-38378','出潼关','吳融','quantangshi','','卷39','重门随地险，一径入天开。
华岳眼前尽，黄河脚底来。
飞轩何满路，丹陛正求才。
独我疎慵质，飘然又此回。','',''),('quantangshi-38379','过丹阳','吳融','quantangshi','','卷39','云阳县郭半郊坰，风雨萧条万古情。
山带梁朝陵路断，水连刘尹宅基平。
桂枝自折思前代，藻鉴难逢耻后生。
遗事满怀兼满目，不堪孤棹舣荒城。','',''),('quantangshi-38380','和人题武城寺','吳融','quantangshi','','卷39','神清已觉三清近，目断仍劳万象牵。
渭水远含秋草渡，汉陵高枕夕阳天。
半岩云粉千竿竹，满寺风雷百尺泉。
别有阑干压行路，看人尘土竟流年。','',''),('quantangshi-38381','长安里中闻猨','吳融','quantangshi','','卷39','夹巷重门似海深，楚猨争得此中吟。
一声紫陌才回首，万里青山已到心。
惯倚客船和雨听，可堪侯第见尘侵。
无因永夜闻清啸，禁路人归月自沈。','',''),('quantangshi-38382','岐下闻子规','吳融','quantangshi','','卷39','劒阁西南远凤台，蜀魂何事此飞来。
偶因陇树相迷至，唯恐边风却送回。
只有花知啼血处，更无猨替断肠哀。
谁怜越客曾闻处，月落江平晓雾开。','',''),('quantangshi-38383','敷水有丐者云是马侍中诸孙悯而有赠','吳融','quantangshi','','卷39','天地尘昏九鼎危，大貂曾出武侯师。
一心忠赤山河见，百战功名日月知。
旧宅已闻栽禁树，诸孙仍见丐征岐。
而今不要教人识，正藉将军死鬬时。','',''),('quantangshi-38384','还俗尼','吳融','quantangshi','','卷39','柳眉梅额倩妆新，笑脱袈裟得旧身。
三峡却为行雨客，九天曾是散花人。
空门付与悠悠梦，宝帐迎回暗暗春。
寄语江南徐孝克，一生长短托清尘。','',''),('quantangshi-38385','彭门用兵后经汴路三首 一','吳融','quantangshi','','卷39','长亭一望一徘徊，千里关河百战来。
细柳旧营犹鏁月，[祁]连新冢已封苔。
霜凋绿野愁无际，烧接黄云惨不开。
若比江南更牢落，子山词赋莫兴[哀]。','',''),('quantangshi-38386','彭门用兵后经汴路三首 二','吳融','quantangshi','','卷39','隋堤风物已凄凉，堤下仍多旧战塲。
金镞有苔人拾得，芦花无主鸟衔将。
秋声暗促河声急，野色遥连日色黄。
独上寒城正愁绝，戍鼙惊起雁行行。','',''),('quantangshi-38387','彭门用兵后经汴路三首 三','吳融','quantangshi','','卷39','铁马云旗梦渺茫，东来无处不堪伤。
风吹白草人行少，月落空城鬼啸长。
一自纷争惊宇宙，可怜萧索绝烟光。
曾为塞北闲游客，辽水天山未断肠。','',''),('quantangshi-38388','寄殿院高侍御','吳融','quantangshi','','卷39','黄梅雨细羃长洲，柳密花疎水慢流。
钓艇正寻逋客去，绣衣方结少年游。
风前不肯看垂手，灯下还应惜裹头。
一夜自怜无羽翼，独当何逊滴阶愁。','',''),('quantangshi-38389','新安道中翫流水','吳融','quantangshi','','卷39','一渠春碧弄潺潺，密竹繁花掩映间。
看处便须终日住，算来争得此身闲。
萦纡似接迷春洞，清冷应连有雪山。
上却征车再回首，了然尘土不相关。','',''),('quantangshi-38390','忆钓舟','吳融','quantangshi','','卷39','青山小隐枕潺湲，一叶垂纶几溯沿。
后浦春风随兴去，南塘秋雨有时眠。
惯冲晓雾惊羣雁，爱颭残阳入乱烟。
回首无人寄惆怅，九衢尘土困扬鞭。','',''),('quantangshi-38391','灵宝县西侧津','吳融','quantangshi','','卷39','碧溪潋潋流残阳，晴沙两两眠鸳鸯。
柳花无赖苦多暇，蛱蝶有情长自忙。
千里宦游成底事，每年风景是他乡。
高歌一曲垂鞭去，尽日无人识楚狂。','',''),('quantangshi-38392','即席','吳融','quantangshi','','卷39','家住丛台旧，名参绛圃新。
醉波疑夺烛，娇态欲沈春。
伴雨聊过楚，归云定占秦。
桃花正浓暖，争不浪迷人。','',''),('quantangshi-38393','出迟','吳融','quantangshi','','卷39','园密花藏易，楼深月到难。
酒虚留客尽，灯暗远更残。
麝想眉间印，鸦知顶上盘。
